if (!function_exists('hatdogNormalizeLookupKey')) {
    function hatdogNormalizeLookupKey($value): string
    {
        return mb_strtolower(trim((string) $value));
    }
}

if (!function_exists('hatdogUsedPurchaseReturnKeys')) {
    /**
     * Build used Purchase Return keys from accounting without asking the
     * purchase MariaDB server to join an accounting table.
     *
     * @return array<string,bool> keyed as "purchase_order_id|return_number"
     */
    function hatdogUsedPurchaseReturnKeys(iterable $purchaseOrderIds = []): array
    {
        $ids = collect($purchaseOrderIds)
            ->map(fn ($id) => (int) $id)
            ->filter(fn ($id) => $id > 0)
            ->unique()
            ->values();

        $query = DB::connection('accounting')->table('payable_cheque_voucher_invoices')
            ->whereNotNull('purchase_order_id')
            ->whereNotNull('return_number')
            ->where('return_number', '!=', '');

        if ($ids->isNotEmpty()) {
            $query->whereIn('purchase_order_id', $ids->all());
        }

        $keys = [];
        foreach ($query->get(['purchase_order_id', 'return_number']) as $row) {
            foreach (preg_split('/\s*,\s*/', (string) $row->return_number, -1, PREG_SPLIT_NO_EMPTY) ?: [] as $number) {
                $normalized = hatdogNormalizeLookupKey($number);
                if ($normalized !== '') {
                    $keys[(int) $row->purchase_order_id . '|' . $normalized] = true;
                }
            }
        }

        return $keys;
    }
}

if (!function_exists('hatdogEnrichPurchaseReturnItems')) {
    function hatdogEnrichPurchaseReturnItems($items)
    {
        $items = collect($items)->values();
        if ($items->isEmpty()) {
            return $items;
        }

        $products = DB::connection('masterlist')->table('products')
            ->whereIn('id', $items->pluck('product_id')->map(fn ($id) => (int) $id)->filter()->unique()->values()->all())
            ->get(['id', 'product_code', 'description', 'part_number', 'application'])
            ->keyBy('id');

        return $items->map(function ($item) use ($products) {
            $product = $products->get((int) ($item->product_id ?? 0));
            $item->product_name = (string) ($product->description ?? '');
            $item->part_number = (string) ($product->part_number ?? '');
            $item->application = (string) ($product->application ?? '');
            if (trim((string) ($item->product_code ?? '')) === '') {
                $item->product_code = (string) ($product->product_code ?? '');
            }
            return $item;
        })->values();
    }
}

if (!function_exists('hatdogAuditActor')) {
    function hatdogAuditActor($user): array
    {
        if (is_array($user)) {
            $user = (object) $user;
