        return [
            'name' => trim((string) ($user->name ?? $user->username ?? $user->User_ID ?? 'Admin')) ?: 'Admin',
            'identifier' => trim((string) ($user->User_ID ?? $user->username ?? $user->id ?? '')) ?: null,
        ];
    }
}

