if (!function_exists('hatdogNormalizeSystemTheme')) {
    function hatdogNormalizeSystemTheme(?string $theme): string
    {
        $theme = Str::of((string) $theme)->lower()->replace('_', '-')->trim()->toString();

        return array_key_exists($theme, hatdogSystemThemeOptions()) ? $theme : 'default';
    }
}

