if (!function_exists('hatdogSystemThemeNow')) {
    function hatdogSystemThemeNow(): \Carbon\Carbon
    {
        return now('Asia/Manila');
    }
}

if (!function_exists('hatdogSystemThemeTargetDate')) {
    function hatdogSystemThemeTargetDate(string $theme, ?\Carbon\Carbon $reference = null): \Carbon\Carbon
    {
        $reference = $reference ? $reference->copy()->timezone('Asia/Manila') : hatdogSystemThemeNow();
        $config = hatdogSystemThemeEventConfig()[$theme] ?? null;
        if (!$config) {
            return $reference->copy();
        }

        if (isset($config['configured_dates'])) {
            foreach ($config['configured_dates'] as $date) {
                $candidate = \Carbon\Carbon::parse($date, 'Asia/Manila');
                if ($candidate->greaterThan($reference)) {
                    return $candidate;
                }
            }

            $latestConfiguredDate = end($config['configured_dates']);
            $fallback = \Carbon\Carbon::parse($latestConfiguredDate, 'Asia/Manila')->year($reference->year);
            while ($fallback->lessThanOrEqualTo($reference)) {
                $fallback->addYear();
            }

            return $fallback;
        }

        $target = $reference->copy()
            ->setDate($reference->year, (int) $config['month'], (int) $config['day'])
            ->startOfDay();
        if ($target->lessThanOrEqualTo($reference)) {
            $target->addYear();
        }

        return $target;
    }
}

if (!function_exists('hatdogSystemThemeEventCandidates')) {
    function hatdogSystemThemeEventCandidates(string $theme, ?\Carbon\Carbon $reference = null): array
    {
        $reference = $reference ? $reference->copy()->timezone('Asia/Manila') : hatdogSystemThemeNow();
        $config = hatdogSystemThemeEventConfig()[$theme] ?? null;
        if (!$config) {
            return [];
        }

        $candidates = [];
        if (isset($config['configured_dates'])) {
            foreach ($config['configured_dates'] as $date) {
                $candidates[] = \Carbon\Carbon::parse($date, 'Asia/Manila')->startOfDay();
            }
        } else {
            for ($year = $reference->year - 1; $year <= $reference->year + 2; $year++) {
                $candidates[] = \Carbon\Carbon::create($year, (int) $config['month'], (int) $config['day'], 0, 0, 0, 'Asia/Manila');
            }
        }

        return collect($candidates)
            ->unique(fn (\Carbon\Carbon $date) => $date->format('Y-m-d'))
            ->sortBy(fn (\Carbon\Carbon $date) => $date->getTimestamp())
            ->values()
            ->all();
    }
}

if (!function_exists('hatdogSystemThemeWindowForEvent')) {
    function hatdogSystemThemeWindowForEvent(string $theme, \Carbon\Carbon $target): array
    {
        $target = $target->copy()->timezone('Asia/Manila')->startOfDay();

        if ($theme === 'christmas') {
            $start = $target->copy()->subDays(15);
            $end = \Carbon\Carbon::create($target->year, 12, 29, 23, 59, 59, 'Asia/Manila');
        } elseif ($theme === 'new-year') {
            $start = \Carbon\Carbon::create($target->year - 1, 12, 30, 0, 0, 0, 'Asia/Manila');
            $end = \Carbon\Carbon::create($target->year, 1, 10, 23, 59, 59, 'Asia/Manila');
        } else {
            $start = $target->copy()->subDays(15);
            $end = $target->copy()->addDays(5)->endOfDay();
        }

        return [
            'start' => $start,
            'end' => $end,
        ];
    }
}

if (!function_exists('hatdogSystemThemeRelevantWindow')) {
    function hatdogSystemThemeRelevantWindow(string $theme, ?\Carbon\Carbon $reference = null): ?array
    {
        $reference = $reference ? $reference->copy()->timezone('Asia/Manila') : hatdogSystemThemeNow();
        $config = hatdogSystemThemeEventConfig()[$theme] ?? null;
        if (!$config) {
            return null;
        }

        $windows = collect(hatdogSystemThemeEventCandidates($theme, $reference))
            ->map(function (\Carbon\Carbon $target) use ($theme, $config) {
                $window = hatdogSystemThemeWindowForEvent($theme, $target);

                return [
                    'key' => $theme,
                    'label' => $config['label'],
                    'priority' => (int) ($config['priority'] ?? 99),
                    'target' => $target,
                    'start' => $window['start'],
                    'end' => $window['end'],
                    'window_key' => $theme . ':' . $target->format('Y-m-d'),
                ];
            });

        $active = $windows
            ->first(fn (array $window) => $reference->betweenIncluded($window['start'], $window['end']));
        if ($active) {
            return $active;
        }

        return $windows
            ->first(fn (array $window) => $window['target']->greaterThan($reference));
    }
}

if (!function_exists('hatdogBuildSystemThemeCountdowns')) {
    function hatdogBuildSystemThemeCountdowns(?\Carbon\Carbon $reference = null): array
    {
        $reference = $reference ? $reference->copy()->timezone('Asia/Manila') : hatdogSystemThemeNow();

        return collect(hatdogSystemThemeEventConfig())->map(function (array $config, string $theme) use ($reference) {
            $window = hatdogSystemThemeRelevantWindow($theme, $reference);
            $target = $window['target'];
            $themeStart = $window['start'];
            $themeEnd = $window['end'];

            return [
                'key' => $theme,
                'label' => $config['label'],
                'target_iso' => $target->toIso8601String(),
                'auto_start_iso' => $themeStart->toIso8601String(),
                'theme_start_iso' => $themeStart->toIso8601String(),
                'theme_end_iso' => $themeEnd->toIso8601String(),
                'target_ms' => $target->getTimestampMs(),
                'auto_start_ms' => $themeStart->getTimestampMs(),
                'theme_start_ms' => $themeStart->getTimestampMs(),
                'theme_end_ms' => $themeEnd->getTimestampMs(),
                'priority' => (int) ($config['priority'] ?? 99),
                'window_key' => $theme . ':' . $target->format('Y-m-d'),
                'date_label' => $target->format('M d, Y'),
                'auto_start_label' => $themeStart->format('M d, Y'),
                'theme_start_label' => $themeStart->format('M d, Y'),
                'theme_end_label' => $themeEnd->format('M d, Y'),
            ];
        })->values()->all();
    }
}

if (!function_exists('hatdogActiveAutoSystemTheme')) {
    function hatdogActiveAutoSystemTheme(?\Carbon\Carbon $reference = null): ?array
    {
        $reference = $reference ? $reference->copy()->timezone('Asia/Manila') : hatdogSystemThemeNow();

        return collect(hatdogBuildSystemThemeCountdowns($reference))
            ->filter(fn (array $theme) => $reference->getTimestampMs() >= $theme['theme_start_ms'] && $reference->getTimestampMs() <= $theme['theme_end_ms'])
            ->sortBy('priority')
            ->first();
    }
}

if (!function_exists('hatdogReadSystemThemeState')) {
    function hatdogReadSystemThemeState(): array
    {
        try {
            $path = hatdogSystemThemeStoragePath();
            if (!File::exists($path)) {
                return ['active_theme' => 'default'];
            }

            $payload = json_decode(File::get($path), true);
            if (!is_array($payload)) {
                return ['active_theme' => 'default'];
            }

            $payload['active_theme'] = hatdogNormalizeSystemTheme($payload['active_theme'] ?? null);

            return $payload;
        } catch (\Throwable $e) {
            return ['active_theme' => 'default'];
        }
    }
}

if (!function_exists('hatdogSaveSystemTheme')) {
    function hatdogSaveSystemTheme(string $theme, string $source = 'manual', ?string $windowKey = null): string
    {
        $theme = hatdogNormalizeSystemTheme($theme);
        $path = hatdogSystemThemeStoragePath();
        $activeAutoTheme = hatdogActiveAutoSystemTheme();
        $state = [
            'active_theme' => $theme,
            'updated_by' => $source === 'auto' ? 'auto' : 'manual',
            'updated_at' => hatdogSystemThemeNow()->toIso8601String(),
        ];

        if ($source === 'auto' && $windowKey) {
            $state['last_auto_window'] = $windowKey;
        }

        if ($source === 'manual' && $theme === 'default' && $activeAutoTheme) {
            $state['manual_default_window'] = $activeAutoTheme['window_key'];
        }

        File::ensureDirectoryExists(dirname($path));
        File::put($path, json_encode($state, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES));

        return $theme;
    }
}

if (!function_exists('hatdogActiveSystemTheme')) {
    function hatdogActiveSystemTheme(): string
    {
        $state = hatdogReadSystemThemeState();
        $savedTheme = hatdogNormalizeSystemTheme($state['active_theme'] ?? null);
        $activeAutoTheme = hatdogActiveAutoSystemTheme();

        if (
            $savedTheme !== 'default'
            && ($state['updated_by'] ?? null) === 'auto'
            && (!$activeAutoTheme || ($state['last_auto_window'] ?? null) !== $activeAutoTheme['window_key'])
        ) {
            $savedTheme = hatdogSaveSystemTheme('default', 'expired');
            $state = hatdogReadSystemThemeState();
        }

        if (
            $savedTheme === 'default'
            && $activeAutoTheme
            && ($state['manual_default_window'] ?? null) !== $activeAutoTheme['window_key']
            && ($state['last_auto_window'] ?? null) !== $activeAutoTheme['window_key']
        ) {
            return hatdogSaveSystemTheme($activeAutoTheme['key'], 'auto', $activeAutoTheme['window_key']);
        }

        return $savedTheme;
    }
}

if (!function_exists('hatdogWriteAuditTrail')) {
    function hatdogWriteAuditTrail(array $payload): void
    {
        try {
            if (!\Illuminate\Support\Facades\Schema::connection('ledger')->hasTable('audit_trails')) {
                return;
            }

            \Illuminate\Support\Facades\DB::connection('ledger')->table('audit_trails')->insert([
                'module' => (string) ($payload['module'] ?? ''),
                'action' => (string) ($payload['action'] ?? ''),
                'source_connection' => $payload['source_connection'] ?? null,
                'source_table' => $payload['source_table'] ?? null,
                'source_id' => isset($payload['source_id']) ? (int) $payload['source_id'] : null,
                'display_id' => $payload['display_id'] ?? null,
                'record_name' => $payload['record_name'] ?? null,
                'user_name' => $payload['user_name'] ?? null,
                'user_identifier' => $payload['user_identifier'] ?? null,
                'audit_data' => array_key_exists('audit_data', $payload)
                    ? json_encode($payload['audit_data'], JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE)
                    : null,
                'created_at' => now(),
                'updated_at' => now(),
            ]);
        } catch (\Throwable $e) {
            \Illuminate\Support\Facades\Log::warning('Audit trail write failed.', [
                'module' => $payload['module'] ?? null,
                'action' => $payload['action'] ?? null,
                'exception' => $e::class,
                'message' => $e->getMessage(),
            ]);
        }
    }
}

if (!function_exists('hatdogAuditTrailPurgeTarget')) {
