if (!function_exists('hatdogSchemaHasColumnCached')) {
    function hatdogSchemaHasColumnCached(?string $connection, string $table, string $column): bool
    {
        $cacheKey = 'hatdog_schema_has_column:' . ($connection ?: 'default') . ':' . $table . ':' . $column;

        return Cache::rememberForever($cacheKey, function () use ($connection, $table, $column) {
            return $connection
                ? Schema::connection($connection)->hasColumn($table, $column)
                : Schema::hasColumn($table, $column);
        });
    }
}

if (!function_exists('calculateTotalPaid')) {
    /**
     * Calculate the total paid amount by summing all amountPaid values from invoices array.
     * 
     * @param array $invoices Array of invoices where each invoice has an 'amountPaid' key
     * @return float Total paid amount as decimal
     */
    function calculateTotalPaid(array $invoices): float
    {
        return array_reduce($invoices, function ($total, $invoice) {
            return $total + (float) ($invoice['amountPaid'] ?? 0);
        }, 0.0);
    }
}

if (!function_exists('determinePaymentStatus')) {
    /**
     * Determine payment status based on amount paid and net amount due.
     * 
     * Validates: Requirements 4.16, 9.8
     * 
     * @param array $invoice Invoice data with amountDue, amountPaid, discount1, discount2
     * @return string 'Full' if paid >= net due (with tolerance), otherwise 'Partial'
     */
    function determinePaymentStatus(array $invoice): string
    {
        $amountDue = (float) ($invoice['amountDue'] ?? 0);
        $amountPaid = (float) ($invoice['amountPaid'] ?? 0);
        $discount1 = (float) ($invoice['discount1'] ?? 0);
        $discount2 = (float) ($invoice['discount2'] ?? 0);
        
        // Calculate net amount due after applying discount_1
        $netDue = $amountDue;
        if ($discount1 > 0) {
            $netDue = $netDue - ($netDue * $discount1 / 100);
        }
        
        // Apply discount_2 to the already discounted amount
        if ($discount2 > 0) {
            $netDue = $netDue - ($netDue * $discount2 / 100);
        }
        
        // Compare with tolerance of 0.005
        return ($amountPaid >= ($netDue - 0.005)) ? 'Full' : 'Partial';
    }
}

if (!function_exists('hatdogBuildAdminDashboardTableData')) {
    function hatdogBuildAdminDashboardTableData(): array
    {
        $newlyAddedProducts = DB::connection('masterlist')
            ->table('products')
            ->where('status', 'Newly')
            ->orderByDesc('created_at')
            ->limit(100)
            ->get(['id', 'product_code', 'category', 'description']);

        $reorderProducts = DB::connection('masterlist')
            ->table('products')
            ->whereNotNull('Re_order_level')
            ->get(['id', 'product_code', 'category', 'description', 'Re_order_level']);

        $dashboardProducts = $newlyAddedProducts
            ->concat($reorderProducts)
            ->filter(fn ($product) => !empty($product->id) || trim((string) ($product->product_code ?? '')) !== '')
            ->unique(fn ($product) => $product->id ?: trim((string) ($product->product_code ?? '')))
            ->values();

        $dashboardProductIds = $dashboardProducts->pluck('id')->filter()->values();
        $ledgerHasProductCode = hatdogSchemaHasColumnCached('ledger', 'product_ledgers', 'product_code');
        $latestBalanceByProductId = collect();
        $latestBalanceByProductCode = collect();

        if ($dashboardProductIds->isNotEmpty()) {
            $dashboardProductCodes = $dashboardProducts
                ->pluck('product_code')
                ->map(fn ($code) => trim((string) $code))
                ->filter()
                ->unique()
                ->values();

            $ledgerQuery = DB::connection('ledger')
                ->table('product_ledgers')
                ->where(function ($query) use ($dashboardProductIds, $dashboardProductCodes, $ledgerHasProductCode) {
                    $query->whereIn('product_id', $dashboardProductIds);

                    if ($ledgerHasProductCode && $dashboardProductCodes->isNotEmpty()) {
                        $query->orWhereIn('product_code', $dashboardProductCodes);
                    }
                });

            $ledgerSelect = ['product_id', 'balance_stock'];
            if ($ledgerHasProductCode) {
                $ledgerSelect[] = 'product_code';
            }

            $pendingProductIds = $dashboardProductIds
                ->map(fn ($id) => (int) $id)
                ->filter()
                ->flip()
                ->all();

            $pendingProductCodes = $ledgerHasProductCode
                ? $dashboardProductCodes->flip()->all()
                : [];

            foreach ($ledgerQuery
                ->select($ledgerSelect)
                ->orderByDesc('date')
                ->orderByDesc('created_at')
                ->orderByDesc('id')
                ->cursor() as $ledgerRow) {
                $ledgerProductId = (int) ($ledgerRow->product_id ?? 0);

                if ($ledgerProductId > 0 && isset($pendingProductIds[$ledgerProductId])) {
                    $latestBalanceByProductId->put($ledgerProductId, (int) $ledgerRow->balance_stock);
                    unset($pendingProductIds[$ledgerProductId]);
                }

                if ($ledgerHasProductCode) {
                    $ledgerProductCode = trim((string) ($ledgerRow->product_code ?? ''));
                    if ($ledgerProductCode !== '' && isset($pendingProductCodes[$ledgerProductCode])) {
                        $latestBalanceByProductCode->put($ledgerProductCode, (int) $ledgerRow->balance_stock);
                        unset($pendingProductCodes[$ledgerProductCode]);
                    }
                }

                if (empty($pendingProductIds) && (!$ledgerHasProductCode || empty($pendingProductCodes))) {
                    break;
                }
            }
        }

        $resolveDashboardQty = function ($product) use ($latestBalanceByProductId, $latestBalanceByProductCode) {
            $productId = $product->id ?? null;
            $productCode = trim((string) ($product->product_code ?? ''));

            if ($productId && $latestBalanceByProductId->has((int) $productId)) {
                return (int) $latestBalanceByProductId->get((int) $productId);
            }

            if ($productCode !== '' && $latestBalanceByProductCode->has($productCode)) {
                return (int) $latestBalanceByProductCode->get($productCode);
            }

            return 0;
        };

        $normalizeDashboardCategory = function ($category) {
            $normalized = trim((string) $category);
            return $normalized !== '' ? $normalized : 'Uncategorized';
        };

        $lowStockProducts = $reorderProducts
            ->map(function ($product) use ($resolveDashboardQty, $normalizeDashboardCategory) {
                $balanceStock = $resolveDashboardQty($product);
                $reorderLevel = (int) $product->Re_order_level;

                return (object) [
                    'product_code' => $product->product_code,
                    'category' => $normalizeDashboardCategory($product->category ?? ''),
                    'description' => $product->description,
                    'qty' => $balanceStock,
                    'is_low_stock' => $balanceStock <= $reorderLevel,
                ];
            })
            ->filter(fn ($row) => $row->is_low_stock)
            ->values();

        return [
            'tab1_data' => $newlyAddedProducts->map(fn ($item) => [
                'code' => $item->product_code,
                'category' => $normalizeDashboardCategory($item->category ?? ''),
                'qty' => $resolveDashboardQty($item),
                'desc' => $item->description ?: 'N/A',
            ])->values()->all(),
            'tab2_data' => $lowStockProducts->map(fn ($item) => [
                'code' => $item->product_code,
                'category' => $item->category,
                'qty' => (int) $item->qty,
                'desc' => $item->description ?: 'N/A',
            ])->values()->all(),
        ];
    }
}

if (!function_exists('hatdogPurgeAuditTrailIfDue')) {
    function hatdogPurgeAuditTrailIfDue(): array
    {
        $nowManila = \Carbon\Carbon::now('Asia/Manila');
        $targetAt = hatdogAuditTrailPurgeTarget($nowManila);
        $nextTargetAt = hatdogAuditTrailPurgeTarget($nowManila->copy()->addMonthNoOverflow()->startOfMonth());
        $cacheKey = 'audit_trail:auto_delete:' . $targetAt->format('Y-m-d-His') . '-asia-manila';

        if ($nowManila->lt($targetAt)) {
            return [
                'due_at' => $targetAt->toIso8601String(),
                'purged' => false,
                'already_purged' => false,
                'deleted_count' => 0,
            ];
        }

        if (!\Illuminate\Support\Facades\Schema::connection('ledger')->hasTable('audit_trails')) {
            return [
                'due_at' => $targetAt->toIso8601String(),
                'purged' => false,
                'already_purged' => false,
                'deleted_count' => 0,
            ];
        }

        try {
            if (\Illuminate\Support\Facades\Cache::has($cacheKey)) {
                $cachedValue = \Illuminate\Support\Facades\Cache::get($cacheKey);
                return [
                    'due_at' => $nextTargetAt->toIso8601String(),
                    'purged' => false,
                    'already_purged' => true,
                    'deleted_count' => (int) (($cachedValue['deleted_count'] ?? 0)),
                ];
            }
        } catch (\Throwable $e) {
            // Continue even if cache is unavailable.
        }

        $deletedCount = (int) \Illuminate\Support\Facades\DB::connection('ledger')
            ->table('audit_trails')
            ->delete();

        try {
            \Illuminate\Support\Facades\Cache::put($cacheKey, [
                'deleted_count' => $deletedCount,
                'purged_at' => now()->toDateTimeString(),
            ], now()->addDays(7));
        } catch (\Throwable $e) {
            // The delete already happened, so cache failures can be ignored here.
        }

        \Illuminate\Support\Facades\Log::info('Audit trail auto-delete executed.', [
            'target_at' => $targetAt->toDateTimeString(),
            'deleted_count' => $deletedCount,
        ]);

        return [
            'due_at' => $nextTargetAt->toIso8601String(),
            'purged' => true,
            'already_purged' => false,
            'deleted_count' => $deletedCount,
        ];
    }
}

