if (!function_exists('hatdogRegularProxyToAdminRoute')) {
    function hatdogRegularProxyToAdminRoute(string $adminRouteName, array $routeParameters = [])
    {
        $user = session('user');
        if (!$user) {
            abort(401);
        }

        if (is_array($user)) {
            $user = (object) $user;
        }

        $allowedTypes = [2, 3];
        if (!in_array((int) ($user->account_type ?? 0), $allowedTypes)) {
            abort(403);
        }

        $currentRequest = request();
        $targetUri = route($adminRouteName, $routeParameters, false);
        $subRequest = \Illuminate\Http\Request::create(
            $targetUri,
            $currentRequest->method(),
            $currentRequest->all(),
            $_COOKIE,
            $currentRequest->files->all(),
            $currentRequest->server->all(),
            $currentRequest->getContent()
        );

        $subRequest->query->replace($currentRequest->query->all());
        $subRequest->headers->replace($currentRequest->headers->all());

        if ($currentRequest->hasSession()) {
            $subRequest->setLaravelSession($currentRequest->session());
        }

        $subRequest->setUserResolver($currentRequest->getUserResolver());
        $subRequest->setRouteResolver($currentRequest->getRouteResolver());

        // Fix root URL for route() inside sub-request (missing base path like /hatdog/public)
        app('url')->forceRootUrl($currentRequest->root());

        return app()->handle($subRequest);
    }
}

if (!function_exists('hatdogWaybillPendingResponse')) {
    function hatdogWaybillPendingResponse(Request $request)
    {
        $user = session('user');
        if (!$user) {
            return response()->json(['success' => false, 'message' => 'Unauthorized'], 403);
        }

        if (is_array($user)) {
            $user = (object) $user;
        }

        if (!in_array((int) ($user->account_type ?? 0), [1, 2, 3], true)) {
            return response()->json(['success' => false, 'message' => 'Forbidden'], 403);
        }

        try {
            $searchCust = trim((string) $request->query('customer', ''));
            $searchInv = trim((string) $request->query('invoice', ''));
            $search = trim((string) $request->query('search', ''));
            $page = max(1, (int) $request->query('page', 1));
            $perPage = 50;

            $query = DB::connection('sales')->table('sales_orders')
                ->whereIn('status', ['Confirmed', 'Partial'])
                ->where(function ($q) {
                    // waybill_id is a numeric nullable field. Pending means no linked waybill yet.
                    $q->whereNull('waybill_id')
                      ->orWhere('waybill_id', 0);
                })
                ->where(function ($q) {
                    $q->whereNull('waybill_no')
                      ->orWhere('waybill_no', '')
                      ->orWhere('waybill_no', 'NULL');
                });

            if ($search !== '') {
                $query->where(function ($q) use ($search) {
                    $q->where('customer_name', 'LIKE', "%{$search}%")
                      ->orWhere('invoice_numbers', 'LIKE', "%{$search}%");
                });
            }

            if ($searchCust !== '') {
                $query->where('customer_name', 'LIKE', "%{$searchCust}%");
            }

            if ($searchInv !== '') {
                $query->where('invoice_numbers', 'LIKE', "%{$searchInv}%");
            }

            $allOrders = $query
                ->orderBy('customer_name', 'asc')
                ->orderBy('id', 'asc')
                ->get();

            // Fetch all related customers in one query instead of one query per customer group.
            $customerIds = $allOrders
                ->pluck('customer_id')
                ->filter(fn ($id) => $id !== null && $id !== '')
                ->map(fn ($id) => (int) $id)
                ->unique()
                ->values();

            $customers = $customerIds->isEmpty()
                ? collect()
                : DB::connection('masterlist')->table('customers')
                    ->whereIn('id', $customerIds->all())
                    ->get()
                    ->keyBy('id');

            $grouped = $allOrders
                ->groupBy('customer_name')
                ->map(function ($items, $customerName) use ($customers) {
                    $first = $items->first();
                    $customerId = (int) ($first->customer_id ?? 0);
                    $customer = $customerId > 0 ? $customers->get($customerId) : null;

                    return [
                        'customer_name' => $customerName,
                        'customer_id' => $first->customer_id,
                        'address' => $customer->address ?? '---',
                        'contact_number' => $customer->contact_number ?? '---',
                        'order_count' => $items->count(),
                        'order_numbers' => $items->pluck('order_number')->values()->all(),
                        'order_ids' => $items->pluck('id')->values()->all(),
                        'order_amounts' => $items->pluck('total_amount')->values()->all(),
                        'invoice_numbers' => $items->pluck('invoice_numbers')->values()->all(),
                        'order_dates' => $items->pluck('created_at')->map(function ($date) {
                            if (!$date) {
                                return null;
                            }

                            try {
                                return \Carbon\Carbon::parse($date)->toDateTimeString();
                            } catch (\Throwable $e) {
                                return (string) $date;
                            }
                        })->values()->all(),
                        'total_amount' => (float) $items->sum('total_amount'),
                    ];
                })
                ->values();

            $totalCount = $grouped->count();
            $lastPage = max(1, (int) ceil($totalCount / $perPage));
            $page = min($page, $lastPage);

            $paginated = $grouped
                ->slice(($page - 1) * $perPage, $perPage)
                ->values();

            return response()->json([
                'success' => true,
                'orders' => $paginated,
                'total' => $totalCount,
                'page' => $page,
                'last_page' => $lastPage,
            ]);
        } catch (\Throwable $e) {
            Log::error('Waybill Pending Orders Error', [
                'exception' => $e::class,
                'message' => $e->getMessage(),
            ]);

            return response()->json([
                'success' => false,
                'message' => 'Unable to load pending waybills.',
                'error' => config('app.debug') ? $e->getMessage() : null,
            ], 500);
        }
    }
}

if (!function_exists('hatdogSupplierProfileJson')) {
    function hatdogSupplierProfileJson(
        Request $request,
        $supplierId,
        array $allowedAccountTypes,
        string $serviceMethod,
        string $logMessage,
        string $responseMessage
    ) {
        $user = session('user');
        if (!$user) {
            return response()->json(['success' => false, 'message' => 'Unauthorized'], 403);
        }

        if (is_array($user)) {
            $user = (object) $user;
        }

        if (!in_array((int) ($user->account_type ?? 0), $allowedAccountTypes, true)) {
            return response()->json(['success' => false, 'message' => 'Forbidden'], 403);
        }

        if (!is_numeric($supplierId) || (int) $supplierId < 1 || (string) (int) $supplierId !== (string) $supplierId) {
            return response()->json(['success' => false, 'message' => 'Supplier not found.'], 404);
        }

        try {
            $payload = app(\App\Services\SupplierComprehensiveProfileService::class)
                ->{$serviceMethod}((int) $supplierId, $request);

            return response()->json($payload);
        } catch (\Symfony\Component\HttpKernel\Exception\NotFoundHttpException $e) {
            return response()->json(['success' => false, 'message' => 'Supplier not found.'], 404);
        } catch (\Throwable $e) {
            Log::warning($logMessage, [
                'supplier_id' => $supplierId,
                'message' => $e->getMessage(),
            ]);

            return response()->json([
                'success' => false,
                'message' => $responseMessage,
            ], 500);
        }
    }
}

