if (!function_exists('hatdogDataupsTables')) {
    function hatdogDataupsTables(string $conn): array
    {
        $exclude = ['migrations', 'cache', 'cache_locks', 'failed_jobs', 'jobs', 'job_batches', 'password_reset_tokens', 'sessions'];
        return collect(\Illuminate\Support\Facades\DB::connection($conn)->select('SHOW TABLES'))
            ->map(fn ($r) => array_values((array) $r)[0] ?? null)
            ->filter()
            ->reject(fn ($t) => in_array($t, $exclude))
            ->values()
            ->all();
    }
}

if (!function_exists('hatdogDataupsPk')) {
    function hatdogDataupsPk(string $conn, string $table): ?string
    {
        $keys = \Illuminate\Support\Facades\DB::connection($conn)->select("SHOW KEYS FROM `{$table}` WHERE Key_name = 'PRIMARY'");
        return $keys[0]->Column_name ?? null;
    }
}

if (!function_exists('hatdogDataupsExportZip')) {
    function hatdogDataupsExportZip(string $conn, string $group): string
    {
        $tmp = rtrim(sys_get_temp_dir(), '\/');
        $zipPath = $tmp . DIRECTORY_SEPARATOR . 'du_' . bin2hex(random_bytes(8)) . '.zip';
        $zip = new ZipArchive();
        if ($zip->open($zipPath, ZipArchive::CREATE) !== true) {
            throw new \RuntimeException("Failed to create ZIP for {$group}");
        }
        $tables = hatdogDataupsTables($conn);
        $csvPaths = [];
        try {
            foreach ($tables as $table) {
                $csvPath = $tmp . DIRECTORY_SEPARATOR . 'csv_' . bin2hex(random_bytes(8)) . '.csv';
                $csvPaths[] = $csvPath;
                $handle = fopen($csvPath, 'w');
                $cols = \Illuminate\Support\Facades\DB::connection($conn)->select("SHOW COLUMNS FROM `{$table}`");
                $colNames = array_map(fn ($c) => $c->Field, $cols);
                fputcsv($handle, $colNames);
                $pk = hatdogDataupsPk($conn, $table);
                $query = \Illuminate\Support\Facades\DB::connection($conn)->table($table);
                if ($pk) {
                    $query->orderBy($pk)->chunkById(500, function ($rows) use ($handle, $colNames) {
                        foreach ($rows as $row) {
                            $data = [];
                            foreach ($colNames as $col) {
                                $data[] = $row->{$col} ?? '';
                            }
                            fputcsv($handle, $data);
                        }
                    }, $pk);
                } else {
                    foreach ($query->cursor() as $row) {
                        $data = [];
                        foreach ($colNames as $col) {
                            $data[] = $row->{$col} ?? '';
                        }
                        fputcsv($handle, $data);
                    }
                }
                fclose($handle);
                $zip->addFile($csvPath, "{$table}.csv");
            }
        } finally {
            $zip->close();
            foreach ($csvPaths as $p) {
                if (file_exists($p)) { @unlink($p); }
            }
        }
        return $zipPath;
    }
}

$recordSuspiciousAttempt = function (): void {
    try {
        Cache::add('security:suspicious_attempts', 0, now()->addDays(30));
        Cache::increment('security:suspicious_attempts');
    } catch (\Throwable $e) {
        // Keep authentication available even if cache storage is unavailable.
    }
};

$developerOtpThrottleKey = function (Login $user, string $ip): string {
    return 'developer-otp|'.Str::transliterate(Str::lower($user->User_ID)).'|'.$ip;
};

$maskEmail = function (string $email): string {
    [$name, $domain] = array_pad(explode('@', $email, 2), 2, '');
    if ($domain === '') {
        return $email;
    }

    $visible = Str::substr($name, 0, min(2, Str::length($name)));
    return $visible.str_repeat('*', max(2, Str::length($name) - Str::length($visible))).'@'.$domain;
};

$developerOtpSecondsLeft = function (): int {
    $expiresAt = (int) session('developer_otp_expires_at', 0);
    return max(0, $expiresAt - now()->timestamp);
};

$developerOtpEmailForUser = function (Login $user): string {
    $developerEmail = trim((string) ($user->Email ?? ''));

    if ($developerEmail === '' && filter_var($user->User_ID, FILTER_VALIDATE_EMAIL)) {
        $developerEmail = $user->User_ID;
    }

    if ($developerEmail === '' && filter_var(config('mail.from.address'), FILTER_VALIDATE_EMAIL)) {
        $developerEmail = config('mail.from.address');
    }

    return $developerEmail;
};

$sendDeveloperOtp = function (Login $user, Request $request) use ($maskEmail, $developerOtpEmailForUser): array {
    $developerEmail = $developerOtpEmailForUser($user);

    if ($developerEmail === '') {
        return [
            'success' => false,
            'message' => 'Developer email is not configured. Add an Email value for this developer account first.',
        ];
    }

    if (!filter_var($developerEmail, FILTER_VALIDATE_EMAIL)) {
        return [
            'success' => false,
            'message' => 'Developer email is invalid. Update the Email value before requesting an OTP.',
        ];
    }

    $otpCode = (string) random_int(100000, 999999);
    $expiresAt = now()->addMinutes(2);

    try {
        $user->forceFill([
            'Otp_Code' => $otpCode,
        ])->save();

        session([
            'developer_otp_login_id' => $user->getKey(),
            'developer_otp_expires_at' => $expiresAt->timestamp,
            'developer_otp_email_mask' => $maskEmail($developerEmail),
            'developer_otp_mail_pending' => true,
        ]);
    } catch (\Throwable $e) {
        Log::warning('Developer OTP delivery failed.', [
            'login_id' => $user->getKey(),
            'mailer' => config('mail.default'),
            'mail_host' => config('mail.mailers.smtp.host'),
            'exception' => $e::class,
            'message' => $e->getMessage(),
        ]);

        $user->forceFill(['Otp_Code' => null])->save();
        session()->forget(['developer_otp_login_id', 'developer_otp_expires_at', 'developer_otp_email_mask', 'developer_otp_mail_pending']);

        return [
            'success' => false,
            'message' => 'Unable to send developer OTP right now. Please check the mail settings and try again.',
        ];
    }

    return [
        'success' => true,
        'masked_email' => $maskEmail($developerEmail),
        'seconds' => 120,
    ];
};

// Redirect root to login
Route::get('/', function () {
    return redirect('/login');
});

// Beautiful login page (served as Blade template)
Route::get('/login', function () {
    if (session()->has('user')) {
        return redirect()->route('dashboard');
    }
    return view('login');
})->name('login');

// Login form submission
Route::post('/login', function (Request $request) use ($recordSuspiciousAttempt, $developerOtpThrottleKey, $sendDeveloperOtp) {
    $request->validate([
        'email' => 'required',
        'password' => 'required',
    ]);

    // Form fields from login.html are 'email' (User_ID) and 'password'
    $userId = $request->input('email');
    $password = $request->input('password');

    // Rate limiting key
    $throttleKey = Str::transliterate(Str::lower($userId).'|'.$request->ip());

    if (RateLimiter::tooManyAttempts($throttleKey, 5)) {
        $seconds = RateLimiter::availableIn($throttleKey);
        return redirect()->route('login')->with([
            'lockout' => true,
            'seconds' => $seconds,
            'error' => "Too many login attempts. System locked."
        ]);
    }

    $user = Login::select(hatdogLoginSessionColumns())->where('User_ID', $userId)->first();

    if ($user) {
        // Safe check for plain-text or Bcrypt hashed passwords
        $passwordMatches = false;
        if ($password === $user->Password) {
            $passwordMatches = true;
        } else {
            try {
                if (Hash::check($password, $user->Password)) {
                    $passwordMatches = true;
                }
            } catch (\Throwable $e) {
                // Ignore hashing errors for plain text passwords
            }
        }

        if ($passwordMatches) {
            RateLimiter::clear($throttleKey);
            if ($user->account_type == 4) {
                $otpThrottleKey = $developerOtpThrottleKey($user, $request->ip());

                if (RateLimiter::tooManyAttempts($otpThrottleKey, 5)) {
                    return redirect()->route('login')->with([
                        'developer_otp_lockout' => true,
                        'developer_otp_lockout_seconds' => RateLimiter::availableIn($otpThrottleKey),
                        'error' => 'Too many developer OTP attempts. This account is locked for 1 day.',
                    ]);
                }

                session()->forget(['developer_otp_login_id', 'developer_otp_expires_at', 'developer_otp_email_mask', 'developer_otp_mail_pending']);
                $otpResult = $sendDeveloperOtp($user, $request);

                if (!$otpResult['success']) {
                    return redirect()->route('login')->with('error', $otpResult['message']);
                }

                return redirect()->route('login')->with([
                    'developer_otp' => true,
                    'developer_otp_seconds' => $otpResult['seconds'],
                    'developer_otp_email' => $otpResult['masked_email'],
                    'developer_otp_notice' => 'Sending developer OTP to your email...',
                ]);
            }

            session(['user' => $user]);
            hatdogRecordLoginActivity($user, $request);
            if ($user->account_type == 1) {
                return redirect()->route('admin.dashboard');
            }
            if ($user->account_type == 3) {
                return redirect()->route('special.dashboard');
            }
            if ($user->account_type == 5) {
                return redirect()->route('warehouse.dashboard');
            }
            return redirect()->route('dashboard');
        }
    }

    // Fail attempt, hit throttle key
    $recordSuspiciousAttempt();
    RateLimiter::hit($throttleKey, 180); // 3 minutes lockout
    $remaining = RateLimiter::remaining($throttleKey, 5);

    // Redirect back to login if invalid
    $msg = 'Invalid User ID or Password.';
    if ($remaining > 0) {
        $msg .= " Remaining attempts: {$remaining}.";
    } else {
        $seconds = RateLimiter::availableIn($throttleKey);
        return redirect()->route('login')->with([
            'lockout' => true,
            'seconds' => $seconds,
            'error' => "Too many login attempts. System locked."
        ]);
    }

    return redirect()->route('login')->with('error', $msg);
});

Route::post('/login/developer/otp/send', function (Request $request) use ($developerOtpSecondsLeft, $developerOtpEmailForUser) {
    $loginId = session('developer_otp_login_id');
    if (!$loginId) {
        return response()->json([
            'success' => false,
            'message' => 'Developer OTP session expired. Please log in again.',
        ], 419);
    }

    if (!session('developer_otp_mail_pending')) {
        return response()->json([
            'success' => true,
            'message' => 'Developer OTP already sent.',
        ]);
    }

    if ($developerOtpSecondsLeft() <= 0) {
        session()->forget(['developer_otp_login_id', 'developer_otp_expires_at', 'developer_otp_email_mask', 'developer_otp_mail_pending']);

        return response()->json([
            'success' => false,
            'message' => 'Developer OTP expired. Please log in again.',
        ], 410);
    }

    $user = Login::select(hatdogLoginSessionColumns())->where('login_ID', $loginId)->where('account_type', 4)->first();
    if (!$user) {
        session()->forget(['developer_otp_login_id', 'developer_otp_expires_at', 'developer_otp_email_mask', 'developer_otp_mail_pending']);

        return response()->json([
            'success' => false,
            'message' => 'Developer account was not found. Please log in again.',
        ], 404);
    }

    $developerEmail = $developerOtpEmailForUser($user);
    $otpCode = (string) ($user->Otp_Code ?? $user->OTP_CODE ?? '');

    if (!filter_var($developerEmail, FILTER_VALIDATE_EMAIL) || !preg_match('/^\d{6}$/', $otpCode)) {
        Log::warning('Developer OTP mail request is invalid.', [
            'login_id' => $user->getKey(),
            'email' => $developerEmail,
        ]);

        return response()->json([
            'success' => false,
            'message' => 'Unable to send developer OTP. Please check the developer email and try again.',
        ], 422);
    }

    try {
        Mail::raw(
            "Your W68 developer login OTP is {$otpCode}. This code expires in 2 minutes.",
            function ($message) use ($developerEmail) {
                $message->to($developerEmail)
                    ->subject('W68 Developer Login OTP');
            }
        );

        session(['developer_otp_mail_pending' => false]);

        return response()->json([
            'success' => true,
            'message' => 'Developer OTP sent successfully.',
        ]);
    } catch (\Throwable $e) {
        Log::warning('Developer OTP delivery failed.', [
            'login_id' => $user->getKey(),
            'mailer' => config('mail.default'),
            'mail_host' => config('mail.mailers.smtp.host'),
            'exception' => $e::class,
            'message' => $e->getMessage(),
        ]);

        return response()->json([
            'success' => false,
            'message' => 'Unable to send developer OTP right now. Please check the mail settings and try again.',
        ], 500);
    }
})->name('developer.otp.send');

Route::post('/login/developer/otp', function (Request $request) use ($recordSuspiciousAttempt, $developerOtpThrottleKey, $developerOtpSecondsLeft) {
    $validated = $request->validate([
        'otp_code' => 'required|digits:6',
    ]);

    $loginId = session('developer_otp_login_id');
    if (!$loginId) {
        return redirect()->route('login')->with('error', 'Developer OTP session expired. Please log in again.');
    }

    $user = Login::select(hatdogLoginSessionColumns())->where('login_ID', $loginId)->where('account_type', 4)->first();
    if (!$user) {
        session()->forget(['developer_otp_login_id', 'developer_otp_expires_at', 'developer_otp_email_mask', 'developer_otp_mail_pending']);
        return redirect()->route('login')->with('error', 'Developer account was not found. Please log in again.');
    }

    $otpThrottleKey = $developerOtpThrottleKey($user, $request->ip());
    if (RateLimiter::tooManyAttempts($otpThrottleKey, 5)) {
        session()->forget(['developer_otp_login_id', 'developer_otp_expires_at', 'developer_otp_email_mask', 'developer_otp_mail_pending']);
        $user->forceFill(['Otp_Code' => null])->save();

        return redirect()->route('login')->with([
            'developer_otp_lockout' => true,
            'developer_otp_lockout_seconds' => RateLimiter::availableIn($otpThrottleKey),
            'error' => 'Too many developer OTP attempts. This account is locked for 1 day.',
        ]);
    }

    if ($developerOtpSecondsLeft() <= 0) {
        session()->forget(['developer_otp_login_id', 'developer_otp_expires_at', 'developer_otp_email_mask', 'developer_otp_mail_pending']);
        $user->forceFill(['Otp_Code' => null])->save();

        return redirect()->route('login')->with('error', 'Developer OTP expired. Please log in again.');
    }

    $storedOtp = (string) ($user->Otp_Code ?? $user->OTP_CODE ?? '');
    $otpMatches = false;

    try {
        $otpMatches = Hash::check($validated['otp_code'], $storedOtp) || hash_equals($storedOtp, $validated['otp_code']);
    } catch (\Throwable $e) {
        $otpMatches = hash_equals($storedOtp, $validated['otp_code']);
    }

    if ($otpMatches) {
        RateLimiter::clear($otpThrottleKey);
        $user->forceFill(['Otp_Code' => null])->save();
        $user->setAttribute('Otp_Code', null);
        $user->setAttribute('OTP_CODE', null);
        session()->forget(['developer_otp_login_id', 'developer_otp_expires_at', 'developer_otp_email_mask', 'developer_otp_mail_pending']);
        session(['user' => $user]);
        hatdogRecordLoginActivity($user, $request);

        return redirect()->route('developer.control-panel');
    }

    $recordSuspiciousAttempt();
    RateLimiter::hit($otpThrottleKey, 86400);
    $remaining = RateLimiter::remaining($otpThrottleKey, 5);

    if ($remaining <= 0 || RateLimiter::tooManyAttempts($otpThrottleKey, 5)) {
        session()->forget(['developer_otp_login_id', 'developer_otp_expires_at', 'developer_otp_email_mask', 'developer_otp_mail_pending']);
        $user->forceFill(['Otp_Code' => null])->save();

        return redirect()->route('login')->with([
            'developer_otp_lockout' => true,
            'developer_otp_lockout_seconds' => RateLimiter::availableIn($otpThrottleKey),
            'error' => 'Too many developer OTP attempts. This account is locked for 1 day.',
        ]);
    }

    return redirect()->route('login')->with([
        'developer_otp' => true,
        'developer_otp_seconds' => $developerOtpSecondsLeft(),
        'developer_otp_email' => session('developer_otp_email_mask'),
        'developer_otp_error' => "Invalid OTP code. Remaining attempts: {$remaining}.",
    ]);
})->name('developer.otp.verify');

// Logout route
Route::get('/logout', function () {
    $user = session('user');
    if ($user) {
        $userId = is_array($user) ? ($user['login_ID'] ?? null) : ($user->login_ID ?? null);
        if ($userId && Schema::hasTable('login_activity_logs')) {
            if (!Schema::hasColumn('login_activity_logs', 'logged_out_at')) {
                Schema::table('login_activity_logs', function ($table) {
                    $table->timestamp('logged_out_at')->nullable()->after('logged_in_at');
                });
            }
            DB::table('login_activity_logs')
                ->where('login_id', $userId)
                ->where('account_type', is_array($user) ? ($user['account_type'] ?? null) : ($user->account_type ?? null))
                ->whereNull('logged_out_at')
                ->orderBy('logged_in_at', 'desc')
                ->limit(1)
                ->update(['logged_out_at' => now()]);
        }
    }
    session()->forget('user');
    return redirect()->route('login');
})->name('logout');

