Route::get('/dashboard', function () {
    $user = session('user');
    if (!$user) {
        return redirect()->route('login');
    }
    if (is_array($user)) {
        $user = (object) $user;
    }
    if ($user->account_type == 1) {
        return redirect()->route('admin.dashboard');
    }
    if ($user->account_type == 4) {
        return redirect()->route('developer.control-panel');
    }
    if ($user->account_type == 2) {
        return redirect()->route('regular.dashboard');
    }
    if ($user->account_type == 3) {
        return redirect()->route('special.dashboard');
    }

    return redirect()->route('login')->with('error', 'Unsupported account type.');
})->name('dashboard');

