            $dailyCounts = (clone $loginActivityBaseQuery)
                ->where('logged_in_at', '>=', now()->subDays(14))
                ->selectRaw('DATE(logged_in_at) as login_date, COUNT(*) as total')
                ->groupBy('login_date')
