        if (!$user) return response()->json(['error' => 'Unauthorized'], 403);
        if (is_array($user)) $user = (object) $user;
        if ((int) ($user->account_type ?? 0) !== 3) return response()->json(['error' => 'Unauthorized'], 403);
        if (!Schema::hasColumn('logins', 'profile_picture')) {
            return response()->json(['success' => false, 'message' => 'Profile picture column not found'], 500);
        }

        $profileUser = \App\Models\Login::where('login_ID', $user->login_ID ?? 0)->first();
        if (!$profileUser) return response()->json(['error' => 'User not found'], 404);

