    // Master list pages
    Route::get('/master-list/product-master', fn () => hatdogSpecialUserView('Special_User.master_list.Product_Master-list'))->name('prod-master');
    Route::match(['GET', 'POST'], '/master-list/product-master/data', fn () => hatdogRegularProxyToAdminRoute('admin.prod-master.data'))->name('prod-master.data');
    Route::match(['GET', 'POST'], '/master-list/product-master/create', fn () => hatdogRegularProxyToAdminRoute('admin.prod-master.create'))->name('prod-master.create');
    Route::post('/master-list/product-master/update/{id}', function (\Illuminate\Http\Request $req, $id) {
        $user = session('user');
        if (!$user) {
            return response()->json(['error' => 'Unauthorized'], 403);
        }
        if (is_array($user)) {
            $user = (object) $user;
        }
        if ((int) ($user->account_type ?? 0) !== 3) {
            return response()->json(['error' => 'Forbidden'], 403);
        }

        try {
            $product = \App\Models\Product::findOrFail($id);
            $before = $product->toArray();
            $validated = $req->validate([
                'product_code' => "required|unique:masterlist.products,product_code,$id",
                'pricelist_code' => 'nullable|string|max:255',
                'part_number' => 'required|string',
                'specification' => 'nullable|string',
                'category' => 'required|string',
                'description' => 'nullable|string',
                'application' => 'nullable|string',
                'position' => 'nullable|string',
                'unit' => 'nullable|string|max:50',
                'on_hand' => 'required|integer|min:0',
                'Re_order_level' => 'nullable|integer|min:0',
                'status' => 'required|string',
                'selling_price' => 'required|numeric|min:0',
                'price_online' => 'nullable|numeric|min:0',
                'cost' => 'nullable|numeric|min:0',
                'date_added' => 'required|date',
                'Product_Picture' => 'nullable|string',
                'price_codes' => 'nullable|string',
            ]);
            $validated['description'] ??= '';
            $validated['application'] ??= '';
            $validated['position'] ??= '';
            $validated['unit'] ??= '';
            $validated['pricelist_code'] = isset($validated['pricelist_code']) && trim((string) $validated['pricelist_code']) !== ''
                ? trim((string) $validated['pricelist_code'])
                : null;
            // Product Master view editor must never directly alter stock or cost.
            $validated['on_hand'] = (int) ($product->on_hand ?? 0);
            $validated['cost'] = (float) ($product->cost ?? 0);
            $validated['price_online'] = $validated['price_online'] ?? 0;
            $validated['specification'] = isset($validated['specification']) && trim((string) $validated['specification']) !== ''
                ? trim((string) $validated['specification'])
                : null;

            // Sync price codes (guarded: only if submitted)
            if ($req->has('price_codes')) {
                $rawPriceCodes = $req->input('price_codes');
                $priceCodesData = [];
                if ($rawPriceCodes && is_string($rawPriceCodes)) {
                    $decoded = json_decode($rawPriceCodes, true);
                    if (is_array($decoded)) {
                        $seen = [];
                        foreach ($decoded as $i => $entry) {
                            // Backward-compatible: handle both string (old) and {price_code, selling_price} (new)
                            if (is_string($entry)) {
                                $code = trim($entry);
                                $sellingPrice = 0.00;
                            } elseif (is_array($entry)) {
                                $code = trim((string) ($entry['price_code'] ?? ''));
                                $sellingPrice = (float) ($entry['selling_price'] ?? 0);
                            } else {
                                continue;
                            }
                            if ($code === '') continue;
                            $upper = strtoupper($code);
                            if (isset($seen[$upper])) continue;
                            $seen[$upper] = true;
                            $priceCodesData[] = ['price_code' => $code, 'selling_price' => $sellingPrice, 'sort_order' => $i];
                        }
                    }
                }
                $product->priceCodes()->delete();
                if (!empty($priceCodesData)) {
                    $product->priceCodes()->createMany($priceCodesData);
                }
                $product->load('priceCodes');
            }

            $product->update($validated);
            $product->refresh();

            $oldOnlinePrice = round((float) ($before['price_online'] ?? 0), 2);
            $newOnlinePrice = round((float) ($product->price_online ?? 0), 2);
            $linkedOnlinePrice = \App\Models\OnlineProduct::query()
                ->where('product_id', $product->id)
                ->value('price');
            $linkedPriceOutOfSync = $linkedOnlinePrice !== null
                && round((float) $linkedOnlinePrice, 2) !== $newOnlinePrice;
            $priceSyncResult = null;
            if ($oldOnlinePrice !== $newOnlinePrice || $linkedPriceOutOfSync) {
                try {
                    $priceSyncResult = app(\App\Services\ShopeePriceSyncService::class)
                        ->pushSystemPriceToShopee($product, 'special_product_master_user_update');
                } catch (\Throwable $syncError) {
                    Log::error('Special Product Master SYSTEM -> SHOPEE price sync failed unexpectedly', [
                        'product_id' => $product->id,
                        'old_price_online' => $oldOnlinePrice,
                        'new_price_online' => $newOnlinePrice,
                        'error' => $syncError->getMessage(),
                    ]);
                    $priceSyncResult = [
                        'success' => false,
                        'sync_status' => 'failed',
                        'message' => 'Product saved, but Shopee price sync failed unexpectedly.',
                        'error' => $syncError->getMessage(),
                    ];
                }
            }

            $actor = hatdogAuditActor($user);
            $recordName = trim((string) ($product->description ?: ($product->part_number ?: $product->product_code)));
            hatdogWriteAuditTrail([
                'module' => 'product',
                'action' => 'Updated',
                'source_connection' => 'masterlist',
                'source_table' => 'products',
                'source_id' => $product->id,
                'display_id' => (string) ($product->product_code ?? $product->id),
                'record_name' => $recordName,
                'user_name' => $actor['name'],
                'user_identifier' => $actor['identifier'],
                'audit_data' => ['before' => $before, 'after' => $product->toArray()],
            ]);

            return response()->json([
                'success' => true,
                'message' => 'Product updated successfully',
                'product' => $product,
                'sync_status' => $priceSyncResult['sync_status'] ?? (!$linkedPriceOutOfSync && $oldOnlinePrice === $newOnlinePrice ? 'not_changed' : null),
                'sync_message' => $priceSyncResult['message'] ?? (!$linkedPriceOutOfSync && $oldOnlinePrice === $newOnlinePrice ? 'Online price was not changed; Shopee sync was not needed.' : null),
                'sync_error' => $priceSyncResult['error'] ?? (($priceSyncResult['summary']['errors'][0] ?? null) ?: null),
                'sync_result' => $priceSyncResult,
            ]);
        } catch (\Exception $e) {
            return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
        }
    })->name('prod-master.update');

    // Product Master - save only pricing-code setup from the inline View editor.
    Route::post('/master-list/product-master/price-codes/{id}', function (\Illuminate\Http\Request $req, $id) {
        $user = session('user');
        if (!$user) return response()->json(['error' => 'Unauthorized'], 403);
        if (is_array($user)) $user = (object) $user;
        if ((int) ($user->account_type ?? 0) !== 3) return response()->json(['error' => 'Forbidden'], 403);

        try {
            $data = $req->validate([
                'price_codes' => 'present|array|max:100',
                'price_codes.*.price_code' => 'required|string|max:100',
                'price_codes.*.selling_price' => 'required|numeric|min:0',
            ]);

            DB::connection('masterlist')->beginTransaction();
            $product = \App\Models\Product::query()->lockForUpdate()->findOrFail($id);
            $before = $product->priceCodes()->get(['price_code', 'selling_price', 'sort_order'])->toArray();

            $seen = [];
            $rows = [];
            foreach (($data['price_codes'] ?? []) as $index => $entry) {
                $code = trim((string) ($entry['price_code'] ?? ''));
                if ($code === '') continue;
                $key = mb_strtoupper($code);
                if (isset($seen[$key])) continue;
                $seen[$key] = true;
                $rows[] = [
                    'price_code' => $code,
                    'selling_price' => round((float) ($entry['selling_price'] ?? 0), 2),
                    'sort_order' => $index,
                ];
            }

            $product->priceCodes()->delete();
            if ($rows) $product->priceCodes()->createMany($rows);
            $product->load('priceCodes');
            DB::connection('masterlist')->commit();

            $priceCodes = $product->priceCodes->map(fn ($row) => [
                'price_code' => (string) $row->price_code,
                'selling_price' => (float) $row->selling_price,
            ])->values()->all();

            try {
                $actor = hatdogAuditActor($user);
                hatdogWriteAuditTrail([
                    'module' => 'product',
                    'action' => 'Updated Pricing Codes',
                    'source_connection' => 'masterlist',
                    'source_table' => 'product_price_codes',
                    'source_id' => $product->id,
                    'display_id' => (string) ($product->product_code ?? $product->id),
                    'record_name' => trim((string) ($product->description ?: ($product->part_number ?: $product->product_code))),
                    'user_name' => $actor['name'],
                    'user_identifier' => $actor['identifier'],
                    'audit_data' => ['before' => $before, 'after' => $priceCodes],
                ]);
            } catch (\Throwable $auditError) {
                Log::warning('Product pricing-code audit failed', ['product_id' => $product->id, 'error' => $auditError->getMessage()]);
            }

            return response()->json([
                'success' => true,
                'message' => 'Pricing codes updated successfully.',
                'price_codes' => $priceCodes,
            ]);
        } catch (\Throwable $e) {
            if (DB::connection('masterlist')->transactionLevel() > 0) DB::connection('masterlist')->rollBack();
            return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
        }
    })->name('prod-master.price-codes.update');

    // Product Master - active Sales Notes / Purchase Notes for one product.
    Route::get('/master-list/product-master/active-notes/{id}', function ($id) {
        $user = session('user');
        if (!$user) return response()->json(['error' => 'Unauthorized'], 403);
        if (is_array($user)) $user = (object) $user;
        if ((int) ($user->account_type ?? 0) !== 3) return response()->json(['error' => 'Forbidden'], 403);

        try {
            \App\Models\Product::findOrFail($id);

            $purchaseRows = DB::connection('purchase')
                ->table('purchase_note_items as pni')
                ->join('purchase_notes as pn', 'pn.id', '=', 'pni.purchase_note_id')
                ->where('pni.product_id', $id)
                ->whereIn('pn.status', ['Open', 'Partial', 'Surplus'])
                ->select([
                    'pn.purchase_note_number as number',
                    'pn.supplier_id',
                    'pn.date as note_date',
                    'pn.created_at',
                    'pn.status',
                    'pni.quantity',
                    'pni.unit_price',
                ])
                ->get();

            $supplierIds = $purchaseRows->pluck('supplier_id')->map(fn ($value) => (int) $value)->filter()->unique()->values();
            $supplierNames = $supplierIds->isEmpty()
                ? collect()
                : DB::connection('masterlist')->table('suppliers')->whereIn('id', $supplierIds->all())->pluck('name', 'id');

            $salesRows = DB::connection('sales')
                ->table('sales_note_items as sni')
                ->join('sales_notes as sn', 'sn.id', '=', 'sni.sales_note_id')
                ->where('sni.product_id', $id)
                ->whereNull('sni.deleted_at')
                ->whereIn('sn.status', ['Open', 'Partial'])
                ->select([
                    'sn.sales_number as number',
                    'sn.customer_name',
                    'sn.order_date as note_date',
                    'sn.created_at',
                    'sn.status',
                    'sni.quantity',
                    'sni.additional_qty',
                    'sni.unit_price',
                ])
                ->get();

            $rows = collect();
            foreach ($purchaseRows as $row) {
                $dateSource = $row->created_at ?: $row->note_date;
                $rows->push([
                    'type' => 'PN',
                    'number' => (string) ($row->number ?? ''),
                    'date' => $dateSource ? \Carbon\Carbon::parse($dateSource)->format('Y-m-d') : null,
                    'quantity_in' => (int) ($row->quantity ?? 0),
                    'quantity_out' => 0,
                    'name' => (string) ($supplierNames[(int) ($row->supplier_id ?? 0)] ?? 'N/A'),
                    'price' => null,
                    'cost' => (float) ($row->unit_price ?? 0),
                    'status' => (string) ($row->status ?? ''),
                ]);
            }
            foreach ($salesRows as $row) {
                $dateSource = $row->created_at ?: $row->note_date;
                $rows->push([
                    'type' => 'SN',
                    'number' => (string) ($row->number ?? ''),
                    'date' => $dateSource ? \Carbon\Carbon::parse($dateSource)->format('Y-m-d') : null,
                    'quantity_in' => 0,
                    'quantity_out' => (int) ($row->quantity ?? 0) + (int) ($row->additional_qty ?? 0),
                    'name' => (string) ($row->customer_name ?? 'N/A'),
                    'price' => (float) ($row->unit_price ?? 0),
                    'cost' => null,
                    'status' => (string) ($row->status ?? ''),
                ]);
            }

            $rows = $rows->sortByDesc(fn ($row) => (($row['date'] ?? '') . '|' . ($row['number'] ?? '')))->values();

            return response()->json(['success' => true, 'rows' => $rows]);
        } catch (\Throwable $e) {
            return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
        }
    })->name('prod-master.active-notes');

