    Route::match(['GET', 'POST'], '/sales/sales-order/receipt-print', function (Request $request) {
        $user = session('user');
        if (!$user) return response()->json(['error' => 'Unauthorized'], 403);
        try {
            $req = $request->all();

            // PRINT DATE SOURCE OF TRUTH:
            // Always use the saved Sales Order date (sales_orders.created_at) when the
            // exact Sales Order can be resolved. Never let the parent Sales Note/browser
            // payload overwrite the Sales Order issue date on the printed document.
            $printSalesOrder = null;
            $printSalesOrderId = (int) ($req['sales_order_id'] ?? 0);
            if ($printSalesOrderId > 0) {
                    $printSalesOrder = DB::connection('sales')
                        ->table('sales_orders')
                        ->where('id', $printSalesOrderId)
                        ->first(['id', 'order_number', 'invoice_numbers', 'created_at', 'updated_at', 'waybill_date']);
            }

            // Defensive fallback for older browser state: resolve the exact invoice.
            if (!$printSalesOrder) {
                $printInvoiceNumber = trim((string) ($req['invoice_number'] ?? ''));
                $printSalesNumber = trim((string) ($req['sales_number'] ?? ''));
                if ($printInvoiceNumber !== '') {
                    $printOrderQuery = DB::connection('sales')
                        ->table('sales_orders')
                        ->where('invoice_numbers', $printInvoiceNumber);
                    if ($printSalesNumber !== '') {
                        $printOrderQuery->where('order_number', $printSalesNumber);
                    }
                    $printSalesOrder = $printOrderQuery
                        ->orderByDesc('id')
                        ->first(['id', 'order_number', 'invoice_numbers', 'created_at', 'updated_at', 'waybill_date']);
                }
            }

            $printDate = trim((string) ($req['date'] ?? ''));
            $resolvePrintDate = static function ($value): string {
                $value = trim((string) $value);
                if ($value === '' || $value === '0000-00-00' || str_starts_with($value, '0000-00-00')) {
                    return '';
                }

                try {
                    return \Carbon\Carbon::parse($value)->format('Y-m-d');
                } catch (\Throwable $e) {
                    return '';
                }
            };

            if ($printSalesOrder) {
                foreach ([$printSalesOrder->created_at ?? null, $printSalesOrder->waybill_date ?? null, $printSalesOrder->updated_at ?? null] as $candidateDate) {
                    $resolvedDate = $resolvePrintDate($candidateDate);
                    if ($resolvedDate !== '') {
                        $printDate = $resolvedDate;
                        break;
                    }
                }
            }
            $printDate = $resolvePrintDate($printDate);
            $items = json_decode($req['items'] ?? '[]', true);
            $printType = $req['print_type'] ?? 'order';
            $items = array_map(function ($item) use ($printType) {
                $quantity = (float)($item['quantity'] ?? 0);
                $actualQty = array_key_exists('actual_qty', $item) ? (float)$item['actual_qty'] : $quantity;
                $additionalQty = (float)($item['additional_qty'] ?? $item['additional_quantity'] ?? 0);
                $item['additional_qty'] = $additionalQty;
                $item['print_quantity'] = $printType === 'invoice' ? $actualQty : $quantity;
                $item['print_quantity_total'] = $item['print_quantity'] + $additionalQty;
                return $item;
            }, is_array($items) ? $items : []);
            if (!empty($items)) {
                $codes = array_unique(array_filter(array_column($items, 'product_code')));
                $productsByCode = [];
                if (!empty($codes)) {
                    $productRows = DB::connection('masterlist')->table('products')->whereIn('product_code', $codes)->get(['product_code', 'application', 'position']);
                    foreach ($productRows as $p) {
                        $productsByCode[strtoupper(trim($p->product_code))] = $p;
                    }
                }
                foreach ($items as &$item) {
                    $code = strtoupper(trim($item['product_code'] ?? ''));
                    if ($code && isset($productsByCode[$code])) {
                        $p = $productsByCode[$code];
                        $item['application'] = $item['application'] ?? ($p->application ?? '');
                        $item['position'] = $item['position'] ?? ($p->position ?? '');
                    }
                }
                unset($item);
            }
            $customerAddress = '';
            $customerTin = '';
            $terms = '';
            $salesMan = '';
            if (!empty($req['customer_id'])) {
                $row = DB::connection('masterlist')->table('customers')->find($req['customer_id']);
                if ($row) {
                    $customerAddress = $row->address ?? '';
                    $customerTin = $row->tin ?? '';
                    $terms = $row->terms ?? '';
                }
            }
            if (!empty($req['sales_number'])) {
                $note = DB::connection('sales')->table('sales_notes')->where('sales_number', $req['sales_number'])->first();
                if ($note) {
                    $salesMan = $note->salesman ?? '';
                }
            }
