    Route::get('/sales/sales-order/online-invoices-data', function (Request $request) {
        $user = session('user');
        if (!$user) {
            return response()->json(['error' => 'Unauthorized'], 403);
        }

        try {
            $perPage = in_array((int) $request->query('perPage', 50), [25, 50, 100], true)
                ? (int) $request->query('perPage', 50)
                : 50;
            $page = max(1, (int) $request->query('page', 1));
            $rawSearch = $request->query('search', '');
            $search = is_string($rawSearch) ? trim($rawSearch) : '';
            $searchFields = (array) $request->query('search_fields', []);

            $escapeLike = static function ($value) {
                return str_replace(['\\', '%', '_'], ['\\\\', '\%', '\_'], trim((string) $value));
            };

            $query = DB::connection('sales')->table('online_reports')
                ->select('id', 'created_at', 'created_by', 'invoice_numbers', 'sales_note_ids', 'notes_data', 'status');

            $hasSearch = false;
            $applyLike = static function ($q, $column, $value) use ($escapeLike) {
                $term = $escapeLike($value);
                if ($term !== '') {
                    $q->where($column, 'LIKE', '%' . $term . '%');
                }
            };

            $fieldMap = [
                'date' => 'created_at',
                'invoice' => 'invoice_numbers',
                'sales_note' => 'notes_data',
                'customer' => 'notes_data',
                'creator' => 'created_by',
            ];

            foreach ($fieldMap as $field => $column) {
                $value = trim((string) ($searchFields[$field] ?? ''));
                if ($value === '') {
                    continue;
                }
                $hasSearch = true;
                $applyLike($query, $column, $value);
            }

            if (!$hasSearch && $search !== '') {
                $hasSearch = true;
                $term = $escapeLike($search);
                $query->where(function ($q) use ($term) {
                    $like = '%' . $term . '%';
                    $q->where('created_at', 'LIKE', $like)
                        ->orWhere('created_by', 'LIKE', $like)
                        ->orWhere('status', 'LIKE', $like)
                        ->orWhere('invoice_numbers', 'LIKE', $like)
                        ->orWhere('notes_data', 'LIKE', $like);
                });
            }

            $total = null;
            if (!$hasSearch) {
                $total = (clone $query)->count();
            }

            $rows = $query->orderByDesc('id')
                ->skip(($page - 1) * $perPage)
                ->take($perPage + 1)
                ->get();

            $hasMore = $rows->count() > $perPage;
            $rows = $rows->take($perPage)->values();

            $fallbackNoteIds = [];
            $decodedRows = $rows->map(function ($report) use (&$fallbackNoteIds) {
                $invoiceNumbers = json_decode($report->invoice_numbers ?? '[]', true);
                $notesData = json_decode($report->notes_data ?? '[]', true);

                if (!is_array($invoiceNumbers)) {
                    $invoiceNumbers = [];
                }
                if (!is_array($notesData)) {
                    $notesData = [];
                }

                if (empty($notesData)) {
                    $ids = array_filter(array_map('trim', explode(',', (string) $report->sales_note_ids)));
                    $fallbackNoteIds = array_merge($fallbackNoteIds, $ids);
                }

                return compact('report', 'invoiceNumbers', 'notesData');
            });

            $fallbackNotes = collect();
            if (!empty($fallbackNoteIds)) {
                $fallbackNotes = DB::connection('sales')->table('sales_notes')
                    ->whereIn('id', array_unique($fallbackNoteIds))
                    ->get(['id', 'sales_number', 'customer_name', 'net_total'])
                    ->keyBy('id');
            }

            // Build finalized totals from sales_orders, because Online Report
            // notes_data is only a generation snapshot and may still contain
            // old unit prices/subtotals.
            $reportIds = $decodedRows
                ->map(fn ($row) => (int) ($row['report']->id ?? 0))
                ->filter()
                ->unique()
                ->values();

            $reportSalesOrderTotals = collect();
            if ($reportIds->isNotEmpty()) {
                $linkedOrderQuery = DB::connection('sales')->table('sales_orders')
                    ->select(['order_number', 'total_amount'])
                    ->where(function ($q) use ($reportIds) {
                        foreach ($reportIds as $reportId) {
                            $q->orWhere('order_number', 'like', 'ONL-' . $reportId . '-%');
                        }
                    });

                foreach ($linkedOrderQuery->get() as $linkedOrder) {
                    if (preg_match('/^ONL-(\d+)-/i', (string) $linkedOrder->order_number, $match)) {
                        $reportId = (int) $match[1];
                        $reportSalesOrderTotals->put(
                            $reportId,
                            (float) $reportSalesOrderTotals->get($reportId, 0)
                                + (float) ($linkedOrder->total_amount ?? 0)
                        );
                    }
                }
            }

            $allInvoiceNumbers = $decodedRows
                ->flatMap(fn ($row) => $row['invoiceNumbers'] ?? [])
                ->map(fn ($invoice) => trim((string) $invoice))
                ->filter(fn ($invoice) => $invoice !== '')
                ->unique()
                ->values();

            $invoiceSalesOrderTotals = collect();
            if ($allInvoiceNumbers->isNotEmpty()) {
                $linkedInvoices = DB::connection('sales')->table('sales_orders')
                    ->whereIn('invoice_numbers', $allInvoiceNumbers->all())
                    ->get(['invoice_numbers', 'total_amount']);

                foreach ($linkedInvoices as $linkedInvoice) {
                    $invoiceNo = trim((string) ($linkedInvoice->invoice_numbers ?? ''));
                    if ($invoiceNo === '') {
                        continue;
                    }

                    $invoiceSalesOrderTotals->put(
                        $invoiceNo,
                        (float) $invoiceSalesOrderTotals->get($invoiceNo, 0)
                            + (float) ($linkedInvoice->total_amount ?? 0)
                    );
                }
            }

            $reports = $decodedRows->map(function ($row) use (
                $fallbackNotes,
                $reportSalesOrderTotals,
                $invoiceSalesOrderTotals
            ) {
                $report = $row['report'];
                $invoiceNumbers = collect($row['invoiceNumbers'] ?? [])
                    ->map(fn ($invoice) => trim((string) $invoice))
                    ->filter(fn ($invoice) => $invoice !== '')
                    ->unique()
                    ->values();

                $notesData = $row['notesData'];
                $invoiceDisplay = $invoiceNumbers->join(', ');

                $salesNotes = [];
                $customers = [];
                $totalItems = 0;
                $fallbackTotalAmount = 0.0;

                if (!empty($notesData)) {
                    foreach ($notesData as $note) {
                        $salesNotes[] = $note['sales_number'] ?? '';
                        $customers[] = $note['customer_name'] ?? '';
                        $fallbackTotalAmount += (float) ($note['net_total'] ?? 0);

                        $_noteItems = $note['items'] ?? [];
                        if (is_string($_noteItems)) {
                            $_noteItems = json_decode($_noteItems, true) ?? [];
                        }

                        foreach ($_noteItems as $item) {
                            $totalItems++;
                            $fallbackTotalAmount += (float) ($item['subtotal'] ?? 0);
                        }
                    }
                } else {
                    $ids = array_filter(array_map('trim', explode(',', (string) $report->sales_note_ids)));
                    foreach ($ids as $id) {
                        $note = $fallbackNotes->get((int) $id);
                        if (!$note) {
                            continue;
                        }

                        $salesNotes[] = $note->sales_number ?? '';
                        $customers[] = $note->customer_name ?? '';
                        $fallbackTotalAmount += (float) ($note->net_total ?? 0);
                    }
                }

                if ($reportSalesOrderTotals->has((int) $report->id)) {
                    $totalAmount = (float) $reportSalesOrderTotals->get((int) $report->id);
                } else {
                    $invoiceBasedTotal = 0.0;
                    $hasInvoiceSalesOrder = false;

                    foreach ($invoiceNumbers as $invoiceNo) {
                        if ($invoiceSalesOrderTotals->has($invoiceNo)) {
                            $hasInvoiceSalesOrder = true;
                            $invoiceBasedTotal += (float) $invoiceSalesOrderTotals->get($invoiceNo);
                        }
                    }

                    $totalAmount = $hasInvoiceSalesOrder
                        ? $invoiceBasedTotal
                        : $fallbackTotalAmount;
                }

                return [
                    'id' => $report->id,
                    'created_at' => $report->created_at
                        ? date('Y-m-d h:i A', strtotime($report->created_at))
                        : '',
                    'created_by' => $report->created_by ?? '---',
                    'invoice_display' => $invoiceDisplay ?: '---',
                    'sales_notes' => collect($salesNotes)->filter()->unique()->join(', '),
                    'customers' => collect($customers)->filter()->unique()->join(', '),
                    'total_items' => $totalItems,
                    'total_amount' => $totalAmount,
                ];
            });

            $lastPage = $total === null
                ? ($hasMore ? $page + 1 : max(1, $page))
                : max(1, (int) ceil($total / $perPage));

            return response()->json([
                'success' => true,
                'reports' => $reports,
                'total' => $total ?? (($page - 1) * $perPage + $reports->count() + ($hasMore ? 1 : 0)),
                'per_page' => $perPage,
                'current_page' => $page,
                'last_page' => $lastPage,
                'has_more' => $hasMore,
            ]);
        } catch (\Exception $e) {
            return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
        }
    })->name('sales-order.online-invoices-data');
