Route::prefix('regular')->name('regular.')->group(function () {
    Route::get('/profile', function () {
        $user = session('user');
        if (!$user) return redirect()->route('login');
        if (is_array($user)) $user = (object) $user;
        if ((int) ($user->account_type ?? 0) !== 2) return redirect()->route('login');

        $profileUser = \App\Models\Login::where('login_ID', $user->login_ID ?? 0)
            ->orWhere('User_ID', $user->User_ID)
            ->first();

        if (!$profileUser) return redirect()->route('regular.dashboard');

        $accountTypeLabel = match ((int) $profileUser->account_type) {
            1 => 'Admin',
            2 => 'Employee',
            3 => 'Employee',
            4 => 'Developer',
            default => 'Unknown',
        };

        $profilePictureUrl = null;
        $hasPic = Schema::hasColumn('logins', 'profile_picture');
        $hasMime = Schema::hasColumn('logins', 'profile_picture_mime');

        if ($hasPic && !empty($profileUser->profile_picture)) {
            $profilePictureUrl = 'data:' . ($hasMime ? ($profileUser->profile_picture_mime ?: 'image/png') : 'image/png')
                . ';base64,' . base64_encode($profileUser->profile_picture);
        }

        $graphDays = collect(range(6, 0))
            ->map(fn ($daysAgo) => \Carbon\Carbon::today()->subDays($daysAgo))
            ->values();

        $dailyLoginMap = $graphDays->mapWithKeys(fn ($date) => [$date->toDateString() => 0]);
        $totalLoginCount = 0;
        $weeklyLoginCount = 0;
        $latestLoginAt = null;

        if (Schema::hasTable('login_activity_logs')) {
            $loginActivityBaseQuery = DB::table('login_activity_logs')
                ->where('user_id', $profileUser->User_ID);

            $totalLoginCount = (clone $loginActivityBaseQuery)->count();
            $weeklyLoginCount = (clone $loginActivityBaseQuery)
                ->where('logged_in_at', '>=', now()->startOfWeek())
                ->count();
            $latestLoginAt = (clone $loginActivityBaseQuery)->max('logged_in_at');

            $dailyCounts = (clone $loginActivityBaseQuery)
                ->whereBetween('logged_in_at', [
                    $graphDays->first()->copy()->startOfDay(),
                    $graphDays->last()->copy()->endOfDay(),
                ])
                ->selectRaw('DATE(logged_in_at) as login_date, COUNT(*) as total')
                ->groupBy('login_date')
                ->pluck('total', 'login_date');

            foreach ($dailyCounts as $loginDate => $total) {
                if ($dailyLoginMap->has($loginDate)) {
                    $dailyLoginMap->put($loginDate, (int) $total);
                }
            }
        }

        return view('partials.user_account.User-profile', [
            'user' => $user,
            'account_type' => 2,
            'profileUser' => $profileUser,
            'accountTypeLabel' => $accountTypeLabel,
            'profilePictureUrl' => $profilePictureUrl,
            'loginGraphLabels' => $graphDays->map(fn ($date) => $date->format('M d'))->values(),
            'loginGraphData' => $dailyLoginMap->values(),
            'totalLoginCount' => $totalLoginCount,
            'weeklyLoginCount' => $weeklyLoginCount,
            'latestLoginAt' => $latestLoginAt ? \Carbon\Carbon::parse($latestLoginAt)->format('M d, Y h:i A') : 'No login activity yet',
        ]);
    })->name('profile');

    Route::post('/profile/update', function (\Illuminate\Http\Request $request) {
        $user = session('user');
        if (!$user) return response()->json(['error' => 'Unauthorized'], 403);
        if (is_array($user)) $user = (object) $user;
        if ((int) ($user->account_type ?? 0) !== 2) return response()->json(['error' => 'Unauthorized'], 403);

        $validated = $request->validate([
            'User_First_Name' => 'required|string|max:255',
            'User_Middle_Name' => 'nullable|string|max:255',
            'User_Last_Name' => 'required|string|max:255',
        ]);

        $profileUser = \App\Models\Login::where('login_ID', $user->login_ID ?? 0)
            ->orWhere('User_ID', $user->User_ID)
            ->first();

        if (!$profileUser) return response()->json(['error' => 'Profile not found.'], 404);

        $profileUser->User_First_Name = trim($validated['User_First_Name']);
        $profileUser->User_Middle_Name = trim((string) ($validated['User_Middle_Name'] ?? '')) ?: null;
        $profileUser->User_Last_Name = trim($validated['User_Last_Name']);
        $profileUser->save();

        $freshSessionUser = \App\Models\Login::select(hatdogLoginSessionColumns())
            ->where('login_ID', $profileUser->login_ID)
            ->first();

        if ($freshSessionUser) session(['user' => $freshSessionUser]);

        return response()->json([
            'success' => true,
            'message' => 'Profile information updated successfully.',
            'full_name' => trim(collect([$profileUser->User_First_Name, $profileUser->User_Middle_Name, $profileUser->User_Last_Name])->filter()->implode(' ')),
        ]);
    })->name('profile.update');

    Route::post('/profile/picture', function (\Illuminate\Http\Request $request) {
        $user = session('user');
        if (!$user) return response()->json(['error' => 'Unauthorized'], 403);
        if (is_array($user)) $user = (object) $user;
        if ((int) ($user->account_type ?? 0) !== 2) return response()->json(['error' => 'Unauthorized'], 403);

        if (!Schema::hasColumn('logins', 'profile_picture')) {
            return response()->json(['error' => 'Profile picture column is not available yet.'], 422);
        }

        $validated = $request->validate([
            'profile_picture' => 'required|image|max:3072|mimes:jpg,jpeg,png,webp,gif',
        ]);

        $profileUser = \App\Models\Login::where('login_ID', $user->login_ID ?? 0)
            ->orWhere('User_ID', $user->User_ID)
            ->first();

        if (!$profileUser) return response()->json(['error' => 'Profile not found.'], 404);

        $file = $validated['profile_picture'];
        $updatePayload = [
            'profile_picture' => file_get_contents($file->getRealPath()),
            'updated_at' => now(),
        ];

        if (Schema::hasColumn('logins', 'profile_picture_mime')) {
            $updatePayload['profile_picture_mime'] = $file->getMimeType();
        }

        DB::table('logins')
            ->where('login_ID', $profileUser->login_ID)
            ->update($updatePayload);

        return response()->json([
            'success' => true,
            'image_url' => 'data:' . ($file->getMimeType() ?: 'image/png') . ';base64,' . base64_encode(file_get_contents($file->getRealPath())),
        ]);
    })->name('profile.picture');

    Route::get('/dashboard', function () {
        $user = session('user');
        if (!$user) return redirect()->route('login');
        if (is_array($user)) $user = (object) $user;
        if ((int) ($user->account_type ?? 0) !== 2) return redirect()->route('login');

        $welcomeFullName = trim(collect([trim((string) ($user->User_First_Name ?? '')), trim((string) ($user->User_Middle_Name ?? '')), trim((string) ($user->User_Last_Name ?? ''))])->filter()->implode(' '));
        $welcomeGender = (string) ($user->Gender ?? 'Other');
        $welcomeAccountTypeLabel = 'Employee';
        $welcomeProfilePictureUrl = null;

        $dashboardData = Cache::rememberForever('regular_dashboard_summary_v1', function () {
            $totalProducts = DB::connection('masterlist')->table('products')->count();
            $newlyAddedCount = DB::connection('masterlist')->table('products')->where('status', 'Newly')->count();
            $lowStockProducts = DB::connection('masterlist')->table('products')->where('on_hand', '<', 20)->get();
            $lowStockCount = $lowStockProducts->count();
            $totalSuppliers = DB::connection('masterlist')->table('suppliers')->count();
            $totalCustomers = DB::connection('masterlist')->table('customers')->count();
            $outColumn = hatdogSchemaHasColumnCached('ledger', 'product_ledgers', 'out') ? 'out' : 'quantity_out';
            $totalSales = (int) DB::connection('ledger')->table('product_ledgers')->whereNotNull('created_at')->sum($outColumn);
            $totalOnlineInvoice = DB::connection('sales')->table('online_reports')->count();
            $totalSalesReturn = DB::connection('sales')->table('sales_returns')->count();
            $totalWaybill = DB::connection('sales')->table('sales_orders')->where('status', 'Confirmed')->where(function ($q) { $q->whereNull('waybill_no')->orWhere('waybill_no', '')->orWhere('waybill_no', 'NULL'); })->distinct('customer_name')->count('customer_name');

            $categoryRows = DB::connection('masterlist')->table('products')->select('category', DB::raw('COUNT(*) as total'))->whereNotNull('category')->where('category', '!=', '')->groupBy('category')->orderByDesc('total')->limit(8)->get();
            $docCol = hatdogSchemaHasColumnCached('sales', 'sales_notes', 'so_types') ? 'so_types' : 'so_type';
            $docRows = DB::connection('sales')->table('sales_notes')->select("$docCol as doc_type", DB::raw('COUNT(*) as total'))->whereNotNull($docCol)->where($docCol, '!=', '')->groupBy($docCol)->orderByDesc('total')->limit(8)->get();

            return [
                'total_products' => $totalProducts,
                'newly_added_count' => $newlyAddedCount,
                'low_stock_count' => $lowStockCount,
                'total_suppliers' => $totalSuppliers,
                'total_customers' => $totalCustomers,
                'total_sales' => $totalSales,
                'total_online_invoice' => $totalOnlineInvoice,
                'total_sales_return' => $totalSalesReturn,
                'total_waybill' => $totalWaybill,
                'category_distribution_labels' => $categoryRows->pluck('category')->values()->all(),
                'category_distribution_values' => $categoryRows->pluck('total')->map(fn ($v) => (int) $v)->values()->all(),
                'document_distribution_labels' => $docRows->pluck('doc_type')->values()->all(),
                'document_distribution_values' => $docRows->pluck('total')->map(fn ($v) => (int) $v)->values()->all(),
            ];
        });

        try {
            if (Schema::hasTable('logins')) {
                $q = Login::query()->select(['login_ID', 'User_ID', 'Gender']);
                $hasPic = hatdogSchemaHasColumnCached(null, 'logins', 'profile_picture');
                $hasMime = hatdogSchemaHasColumnCached(null, 'logins', 'profile_picture_mime');
                if ($hasPic) $q->addSelect('profile_picture');
                if ($hasMime) $q->addSelect('profile_picture_mime');
                if (!empty($user->login_ID)) $q->where('login_ID', $user->login_ID);
                elseif (!empty($user->User_ID)) $q->where('User_ID', $user->User_ID);
                $found = $q->first();
                if ($found) {
                    $welcomeGender = (string) ($found->Gender ?? $welcomeGender);
                    if ($hasPic && !empty($found->profile_picture)) {
                        $welcomeProfilePictureUrl = 'data:' . ($hasMime ? ($found->profile_picture_mime ?: 'image/png') : 'image/png') . ';base64,' . base64_encode($found->profile_picture);
                    }
                }
            }
        } catch (\Throwable $e) {}

        return view('Regular_User.dashboard.Dashboard', [
            'user' => $user,
            'account_type' => 2,
            'welcome_full_name' => $welcomeFullName ?: 'Employee',
            'welcome_gender' => $welcomeGender,
            'welcome_profile_picture_url' => $welcomeProfilePictureUrl,
            'welcome_account_type_label' => $welcomeAccountTypeLabel,
            'dashboard_table_data_url' => route('regular.dashboard.table-data'),
        ] + $dashboardData);
    })->name('dashboard');

    Route::get('/dashboard/table-data', function (Illuminate\Http\Request $request) {
        $user = session('user');
        if (!$user) return response()->json(['message' => 'Unauthorized'], 403);
        if (is_array($user)) $user = (object) $user;
        if (!in_array((int) ($user->account_type ?? 0), [2, 3])) return response()->json(['message' => 'Unauthorized'], 403);

        $newlyAddedProducts = DB::connection('masterlist')->table('products')->where('status', 'Newly')->orderByDesc('created_at')->limit(100)->get(['id', 'product_code', 'category', 'description']);
        $reorderProducts = DB::connection('masterlist')->table('products')->whereNotNull('Re_order_level')->get(['id', 'product_code', 'category', 'description', 'Re_order_level']);

        $tab1 = $newlyAddedProducts->map(fn ($p) => ['code' => $p->product_code, 'category' => $p->category ?? '', 'qty' => 0, 'desc' => $p->description ?? '']);
        $tab2 = $reorderProducts->map(fn ($p) => ['code' => $p->product_code, 'category' => $p->category ?? '', 'qty' => (int) ($p->on_hand ?? 0), 'desc' => $p->description ?? '']);

        return response()->json(['success' => true, 'tab1_data' => $tab1, 'tab2_data' => $tab2]);
