    Route::match(['GET', 'POST'], '/master-list/product-master/data', function (\Illuminate\Http\Request $req) {
        $user = session('user');
        if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

        $perPage = max(1, (int) $req->query('perPage', 50));
        $page = max(1, (int) $req->query('page', 1));
        $tab = (string) $req->query('tab', 'all');
        $search = $req->query('search', []);
        $search = is_array($search) ? $search : [];
        $filter = $req->query('filter', []);
        $filter = is_array($filter) ? $filter : [];
        $sortBy = $req->query('sort_by');
        $sortDirection = strtolower((string) $req->query('sort_direction', 'asc')) === 'desc' ? 'desc' : 'asc';

        // Product stock lives on the separate ledger MariaDB service in production.
        // Load the ledger balances on that connection and merge them in PHP instead of
        // embedding a cross-server subquery inside the masterlist SQL statement.
        $statProducts = \App\Models\Product::query()
            ->select(['id', 'status', 'Re_order_level'])
            ->get();
        $latestBalances = \App\Services\ProductStockSyncService::latestBalances($statProducts->pluck('id'));

        $query = \App\Models\Product::query()->select('products.*');
        if ($tab === 'newly') {
            $query->where('status', 'Newly');
        }

        $escapeLike = function ($value) {
            return str_replace(['\\', '%', '_'], ['\\\\', '\\%', '\\_'], (string) $value);
        };
        $onHandSearch = null;
        if (!empty($search)) {
            foreach ($search as $col => $val) {
                if ($val === null || $val === '') continue;
                if ($col === 'onHand') {
                    $onHandSearch = (string) $val;
                    continue;
                }

                $db = match($col) {
                    'productCode' => 'product_code',
                    'partNumber' => 'part_number',
                    'restockLevel' => 'Re_order_level',
                    'sellingPrice' => 'selling_price',
                    'priceOnline' => 'price_online',
                    'description' => 'description',
                    'application' => 'application',
                    'specification' => 'specification',
                    'position' => 'position',
                    'category' => 'category',
                    default => $col,
                };
                $term = $escapeLike($val);
                if ($col === 'restockLevel') {
                    $query->whereRaw('CAST(Re_order_level AS CHAR) LIKE ?', ["%{$term}%"]);
                } elseif ($col === 'priceOnline') {
                    $query->whereRaw('price_online LIKE ?', ['%' . $term . '%']);
                } else {
                    $query->where($db, 'LIKE', "%{$term}%");
                }
            }
        }

        if (!empty($filter['category']) && $filter['category'] !== 'all') {
            $query->where('category', 'LIKE', "%{$filter['category']}%");
        }
        if (!empty($filter['application']) && $filter['application'] !== 'all') {
            $query->where('application', 'LIKE', "%{$filter['application']}%");
        }
        if (!empty($filter['status']) && $filter['status'] !== 'all') {
            $query->where('status', $filter['status']);
        }

        $sortableColumns = [
            'productCode' => 'product_code',
            'description' => 'description',
            'application' => 'application',
            'brand' => 'category',
            'partNumber' => 'part_number',
            'position' => 'position',
            'specification' => 'specification',
            'unit' => 'unit',
            'priceOnline' => 'price_online',
            'sellingPrice' => 'selling_price',
            'restockLevel' => 'Re_order_level',
        ];
        if ($sortBy && isset($sortableColumns[$sortBy])) {
            $query->orderBy($sortableColumns[$sortBy], $sortDirection);
        } elseif ($sortBy !== 'onHand') {
            $query->orderBy('created_at', 'desc');
        }

        $candidateProducts = $query->get();
        $candidateProducts->each(function ($product) use ($latestBalances) {
            $product->latest_on_hand = (int) ($latestBalances[(int) $product->id] ?? 0);
            $product->on_hand = $product->latest_on_hand;
        });

        if ($tab === 'low') {
            $candidateProducts = $candidateProducts->filter(function ($product) {
                return $product->Re_order_level !== null
                    && (int) $product->latest_on_hand <= (int) $product->Re_order_level;
            })->values();
        }

        if ($onHandSearch !== null && $onHandSearch !== '') {
            $candidateProducts = $candidateProducts->filter(function ($product) use ($onHandSearch) {
                return str_contains((string) ((int) $product->latest_on_hand), $onHandSearch);
            })->values();
        }

        if ($sortBy === 'onHand') {
            $candidateProducts = $sortDirection === 'desc'
                ? $candidateProducts->sortByDesc(fn ($product) => (int) $product->latest_on_hand)->values()
                : $candidateProducts->sortBy(fn ($product) => (int) $product->latest_on_hand)->values();
        }

        $filteredTotal = $candidateProducts->count();
        $pageItems = $candidateProducts
            ->slice(($page - 1) * $perPage, $perPage)
            ->values();
        $products = new \Illuminate\Pagination\LengthAwarePaginator(
            $pageItems,
            $filteredTotal,
            $perPage,
            $page,
            ['path' => $req->url(), 'query' => $req->query()]
        );

        $products->getCollection()->transform(function ($product) {
            $product->restock_level = $product->Re_order_level;

            // Sanitize text string fields to prevent JSON encoding errors (skip binary/image fields)
            foreach ($product->getAttributes() as $field => $value) {
                if ($field === 'Product_Picture' || $field === 'images') continue;
                if (is_string($value)) {
                    $product->$field = iconv('UTF-8', 'UTF-8//IGNORE', $value);
                }
            }

            // Normalize product image: handle raw binary, JSON arrays, and file paths
            if (!empty($product->Product_Picture)) {
                $pic = $product->Product_Picture;
                $firstByte = $pic[0];
                if (ord($firstByte) === 137 && isset($pic[3]) && ord($pic[1]) === 80 && ord($pic[2]) === 78 && ord($pic[3]) === 71) {
                    $product->Product_Picture = 'data:image/png;base64,' . base64_encode($pic);
                } elseif (ord($firstByte) === 255 && isset($pic[2]) && ord($pic[1]) === 216 && ord($pic[2]) === 255) {
                    $product->Product_Picture = 'data:image/jpeg;base64,' . base64_encode($pic);
                } elseif ($firstByte === '[' || $firstByte === '{') {
                    $decoded = json_decode($pic, true);
                    $product->Product_Picture = empty($decoded) ? null : $decoded;
                } elseif (str_starts_with($pic, 'data:image/')) {
                    // keep as-is
                } elseif (str_starts_with($pic, 'http://') || str_starts_with($pic, 'https://')) {
                    // keep as-is
                } elseif (preg_match('/\.(png|jpg|jpeg|webp|gif|bmp|svg)(\?.*)?$/i', $pic)) {
                    $product->Product_Picture = url($pic);
                } else {
                    $product->Product_Picture = null;
                }
            } else {
                $product->Product_Picture = null;
            }

            return $product;
        });

        $total = $statProducts->count();
        $newly = $statProducts->where('status', 'Newly')->count();
        $low = $statProducts->filter(function ($product) use ($latestBalances) {
            return $product->Re_order_level !== null
                && (int) ($latestBalances[(int) $product->id] ?? 0) <= (int) $product->Re_order_level;
        })->count();

        return response()->json([
            'pagination' => $products,
            'stats' => ['total' => $total, 'newly' => $newly, 'low' => $low],
        ]);
    })->name('prod-master.data');

    Route::post('/master-list/product-master/create', function (\Illuminate\Http\Request $req) {
        $user = session('user'); if (!$user) return response()->json(['error' => 'Unauthorized'], 403);
        try {
            $v = $req->validate(['product_code' => 'required|unique:masterlist.products,product_code', 'pricelist_code' => 'nullable|string|max:255', 'part_number' => 'required|string', 'specification' => 'nullable|string', 'category' => 'required|string', 'description' => 'nullable|string', 'application' => 'nullable|string', 'position' => 'nullable|string', 'unit' => 'nullable|string|max:50', 'on_hand' => 'required|integer|min:0', 'Re_order_level' => 'nullable|integer|min:0', 'status' => 'required|string', 'selling_price' => 'required|numeric|min:0', 'price_online' => 'nullable|numeric|min:0', 'cost' => 'nullable|numeric|min:0', 'date_added' => 'required|date', 'Product_Picture' => 'nullable|string']);
            $v['pricelist_code'] = isset($v['pricelist_code']) && trim((string) $v['pricelist_code']) !== '' ? trim((string) $v['pricelist_code']) : null;
            $v['description'] ??= ''; $v['application'] ??= ''; $v['position'] ??= ''; $v['unit'] ??= ''; $v['cost'] ??= 0; $v['price_online'] = $v['price_online'] ?? 0; $v['specification'] = isset($v['specification']) && trim((string) $v['specification']) !== '' ? trim((string) $v['specification']) : null;
            $product = \App\Models\Product::create($v);
            $actor = hatdogAuditActor($user); $rn = trim((string) ($product->description ?: ($product->part_number ?: $product->product_code)));
            hatdogWriteAuditTrail(['module' => 'product', 'action' => 'Created', 'source_connection' => 'masterlist', 'source_table' => 'products', 'source_id' => $product->id, 'display_id' => (string) ($product->product_code ?? $product->id), 'record_name' => $rn, 'user_name' => $actor['name'], 'user_identifier' => $actor['identifier'], 'audit_data' => ['after' => $product->toArray()]]);
            return response()->json(['success' => true, 'message' => 'Product added successfully', 'product' => $product]);
        } catch (\Exception $e) { return response()->json(['success' => false, 'message' => $e->getMessage()], 422); }
    })->name('prod-master.create');

    Route::post('/master-list/product-master/update/{id}', function (\Illuminate\Http\Request $req, $id) {
        $user = session('user'); if (!$user) return response()->json(['error' => 'Unauthorized'], 403);
        try {
            $product = \App\Models\Product::findOrFail($id); $before = $product->toArray();
            $v = $req->validate(['product_code' => "required|unique:masterlist.products,product_code,$id", 'pricelist_code' => 'nullable|string|max:255', 'part_number' => 'required|string', 'specification' => 'nullable|string', 'category' => 'required|string', 'description' => 'nullable|string', 'application' => 'nullable|string', 'position' => 'nullable|string', 'unit' => 'nullable|string|max:50', 'on_hand' => 'required|integer|min:0', 'Re_order_level' => 'nullable|integer|min:0', 'status' => 'required|string', 'selling_price' => 'required|numeric|min:0', 'price_online' => 'nullable|numeric|min:0', 'cost' => 'nullable|numeric|min:0', 'date_added' => 'required|date', 'Product_Picture' => 'nullable|string']);
            $v['pricelist_code'] = isset($v['pricelist_code']) && trim((string) $v['pricelist_code']) !== '' ? trim((string) $v['pricelist_code']) : null;
            $v['description'] ??= ''; $v['application'] ??= ''; $v['position'] ??= ''; $v['unit'] ??= ''; $v['price_online'] = $v['price_online'] ?? 0; $v['specification'] = isset($v['specification']) && trim((string) $v['specification']) !== '' ? trim((string) $v['specification']) : null;
            // Product Master inline editor must never directly alter inventory or cost.
            $v['on_hand'] = (int) ($product->on_hand ?? 0);
            $v['cost'] = (float) ($product->cost ?? 0);
            $product->update($v); $product->refresh();
            $oldOnlinePrice = round((float) ($before['price_online'] ?? 0), 2);
            $newOnlinePrice = round((float) ($product->price_online ?? 0), 2);
            $priceSyncResult = null;
            if ($oldOnlinePrice !== $newOnlinePrice) {
                try {
                    $priceSyncResult = app(\App\Services\ShopeePriceSyncService::class)->pushSystemPriceToShopee($product, 'regular_product_master_user_update');
                } catch (\Throwable $syncError) {
                    Log::error('Regular Product Master SYSTEM -> SHOPEE price sync failed unexpectedly', ['product_id' => $product->id, 'old_price_online' => $oldOnlinePrice, 'new_price_online' => $newOnlinePrice, 'error' => $syncError->getMessage()]);
                    $priceSyncResult = ['success' => false, 'sync_status' => 'failed', 'message' => 'Product saved, but Shopee price sync failed unexpectedly.', 'error' => $syncError->getMessage()];
                }
            }
            $actor = hatdogAuditActor($user); $rn = trim((string) ($product->description ?: ($product->part_number ?: $product->product_code)));
            hatdogWriteAuditTrail(['module' => 'product', 'action' => 'Updated', 'source_connection' => 'masterlist', 'source_table' => 'products', 'source_id' => $product->id, 'display_id' => (string) ($product->product_code ?? $product->id), 'record_name' => $rn, 'user_name' => $actor['name'], 'user_identifier' => $actor['identifier'], 'audit_data' => ['before' => $before, 'after' => $product->toArray()]]);
            return response()->json(['success' => true, 'message' => 'Product updated successfully', 'product' => $product, 'sync_status' => $priceSyncResult['sync_status'] ?? ($oldOnlinePrice === $newOnlinePrice ? 'not_changed' : null), 'sync_message' => $priceSyncResult['message'] ?? ($oldOnlinePrice === $newOnlinePrice ? 'Online price was not changed; Shopee sync was not needed.' : null), 'sync_error' => $priceSyncResult['error'] ?? (($priceSyncResult['summary']['errors'][0] ?? null) ?: null), 'sync_result' => $priceSyncResult]);
        } catch (\Exception $e) { return response()->json(['success' => false, 'message' => $e->getMessage()], 422); }
    })->name('prod-master.update');

