    Route::post('/master-list/product-master/delete/{id}', function ($id) {
        $user = session('user'); if (!$user) return response()->json(['error' => 'Unauthorized'], 403);
        try {
            if (is_array($user)) $user = (object) $user;
            if (!Schema::connection('ledger')->hasTable('archived_records')) throw new \Exception('Archive table is missing.');
            DB::connection('masterlist')->beginTransaction(); DB::connection('ledger')->beginTransaction();
            $product = \App\Models\Product::query()->lockForUpdate()->findOrFail($id);
            $productData = $product->toArray(); $deletedBy = $user->name ?? $user->username ?? $user->User_ID ?? 'Admin';
            $displayId = (string) ($product->product_code ?? $product->id); $dataName = trim((string) (($product->description ?? '') !== '' ? $product->description : ($product->part_number ?? $product->product_code ?? 'Product')));
            $actor = hatdogAuditActor($user);
            $existingArchive = DB::connection('ledger')->table('archived_records')->where('module', 'product')->whereNull('restored_at')->where('source_connection', 'masterlist')->where('source_table', 'products')->where('source_id', $product->id)->first();
            if ($existingArchive) { DB::connection('masterlist')->rollBack(); DB::connection('ledger')->rollBack(); return response()->json(['success' => false, 'message' => 'Product is already archived.'], 409); }
            DB::connection('ledger')->table('archived_records')->insert(['module' => 'product', 'source_connection' => 'masterlist', 'source_table' => 'products', 'source_id' => $product->id, 'display_id' => $displayId, 'data_name' => $dataName, 'archived_data' => json_encode($productData, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE), 'deleted_by' => (string) $deletedBy, 'deleted_at' => now(), 'expires_at' => now()->addDays(30), 'created_at' => now(), 'updated_at' => now()]);
            $product->delete();
            hatdogWriteAuditTrail(['module' => 'product', 'action' => 'Deleted', 'source_connection' => 'masterlist', 'source_table' => 'products', 'source_id' => $product->id, 'display_id' => $displayId, 'record_name' => $dataName, 'user_name' => $actor['name'], 'user_identifier' => $actor['identifier'], 'audit_data' => ['archived_data' => $productData]]);
            DB::connection('masterlist')->commit(); DB::connection('ledger')->commit();
            return response()->json(['success' => true, 'message' => 'Product archived and deleted successfully']);
        } catch (\Exception $e) { DB::connection('masterlist')->rollBack(); DB::connection('ledger')->rollBack(); return response()->json(['success' => false, 'message' => $e->getMessage()], 500); }
    })->name('prod-master.delete');
