    Route::get('/purchase/purchase-note/details-by-number/{number}', function ($number) {
        $user = session('user');
        if (!$user) {
            return response()->json(['success' => false, 'message' => 'Unauthorized'], 401);
        }

        if (is_array($user)) {
            $user = (object) $user;
        }

        if ((int) ($user->account_type ?? 0) !== 2) {
            return response()->json(['success' => false, 'message' => 'Unauthorized'], 403);
        }

        $note = \App\Models\PurchaseNote::with(['items', 'supplier'])
            ->where('purchase_note_number', $number)
            ->first();

        if (!$note) {
            return response()->json(['success' => false, 'message' => 'Note not found'], 404);
        }

        return response()->json(['success' => true, 'note' => $note]);
    })->name('purchase.note.details-by-number');
