// Admin Dashboard Route
Route::get('/admin/dashboard', function () {
    $user = session('user');
    if (!$user) {
        return redirect()->route('login');
    }
    if (is_array($user)) {
        $user = (object) $user;
    }
    if ($user->account_type != 1) {
        return redirect()->route('login');
    }

    $dashboardData = Cache::rememberForever('admin_dashboard_summary_v1', function () {
        $newlyAddedProducts = DB::connection('masterlist')
            ->table('products')
            ->where('status', 'Newly')
            ->orderByDesc('created_at')
            ->limit(100)
            ->get(['id', 'product_code', 'category', 'description']);

        $reorderProducts = DB::connection('masterlist')
            ->table('products')
            ->whereNotNull('Re_order_level')
            ->get(['id', 'product_code', 'category', 'description', 'Re_order_level']);
        $totalProducts = DB::connection('masterlist')->table('products')->count();

        $newlyAddedCount = DB::connection('masterlist')
            ->table('products')
            ->where('status', 'Newly')
            ->count();

        $dashboardProducts = $newlyAddedProducts
            ->concat($reorderProducts)
            ->filter(fn ($product) => !empty($product->id) || trim((string) ($product->product_code ?? '')) !== '')
            ->unique(fn ($product) => $product->id ?: trim((string) ($product->product_code ?? '')))
            ->values();

        $dashboardProductIds = $dashboardProducts->pluck('id')->filter()->values();
        $ledgerHasProductCode = hatdogSchemaHasColumnCached('ledger', 'product_ledgers', 'product_code');
        $latestBalanceByProductId = collect();
        $latestBalanceByProductCode = collect();

        if ($dashboardProductIds->isNotEmpty()) {
            $dashboardProductCodes = $dashboardProducts
                ->pluck('product_code')
                ->map(fn ($code) => trim((string) $code))
                ->filter()
                ->unique()
                ->values();

            $ledgerQuery = DB::connection('ledger')
                ->table('product_ledgers')
                ->where(function ($query) use ($dashboardProductIds, $dashboardProductCodes, $ledgerHasProductCode) {
                    $query->whereIn('product_id', $dashboardProductIds);

                    if ($ledgerHasProductCode && $dashboardProductCodes->isNotEmpty()) {
                        $query->orWhereIn('product_code', $dashboardProductCodes);
                    }
                });

            $ledgerSelect = ['product_id', 'balance_stock'];
            if ($ledgerHasProductCode) {
                $ledgerSelect[] = 'product_code';
            }

            $pendingProductIds = $dashboardProductIds
                ->map(fn ($id) => (int) $id)
                ->filter()
                ->flip()
                ->all();

            $pendingProductCodes = $ledgerHasProductCode
                ? $dashboardProductCodes->flip()->all()
                : [];

            foreach ($ledgerQuery
                ->select($ledgerSelect)
                ->orderByDesc('date')
                ->orderByDesc('created_at')
                ->orderByDesc('id')
                ->cursor() as $ledgerRow) {
                $ledgerProductId = (int) ($ledgerRow->product_id ?? 0);

                if ($ledgerProductId > 0 && isset($pendingProductIds[$ledgerProductId])) {
                    $latestBalanceByProductId->put($ledgerProductId, (int) $ledgerRow->balance_stock);
                    unset($pendingProductIds[$ledgerProductId]);
                }

                if ($ledgerHasProductCode) {
                    $ledgerProductCode = trim((string) ($ledgerRow->product_code ?? ''));
                    if ($ledgerProductCode !== '' && isset($pendingProductCodes[$ledgerProductCode])) {
                        $latestBalanceByProductCode->put($ledgerProductCode, (int) $ledgerRow->balance_stock);
                        unset($pendingProductCodes[$ledgerProductCode]);
                    }
                }

                if (empty($pendingProductIds) && (!$ledgerHasProductCode || empty($pendingProductCodes))) {
                    break;
                }
            }
        }

        $resolveDashboardQty = function ($product) use ($latestBalanceByProductId, $latestBalanceByProductCode) {
            $productId = $product->id ?? null;
            $productCode = trim((string) ($product->product_code ?? ''));

            if ($productId && $latestBalanceByProductId->has((int) $productId)) {
                return (int) $latestBalanceByProductId->get((int) $productId);
            }

            if ($productCode !== '' && $latestBalanceByProductCode->has($productCode)) {
                return (int) $latestBalanceByProductCode->get($productCode);
            }

            return 0;
        };

        $normalizeDashboardCategory = function ($category) {
            $normalized = trim((string) $category);
            return $normalized !== '' ? $normalized : 'Uncategorized';
        };

        $lowStockProducts = $reorderProducts
            ->map(function ($product) use ($resolveDashboardQty, $normalizeDashboardCategory) {
                $balanceStock = $resolveDashboardQty($product);
                $reorderLevel = (int) $product->Re_order_level;

                return (object) [
                    'id' => $product->id,
                    'product_code' => $product->product_code,
                    'category' => $normalizeDashboardCategory($product->category ?? ''),
                    'description' => $product->description,
                    'qty' => $balanceStock,
                    'reorder_level' => $reorderLevel,
                    'is_low_stock' => $balanceStock <= $reorderLevel,
                ];
            })
            ->filter(fn ($row) => $row->is_low_stock)
            ->values();

        $lowStockCount = $lowStockProducts->count();
        $totalSuppliers = DB::connection('masterlist')->table('suppliers')->count();
        $totalCustomers = DB::connection('masterlist')->table('customers')->count();

        $outColumn = hatdogSchemaHasColumnCached('ledger', 'product_ledgers', 'out')
            ? 'out'
            : 'quantity_out';

        $totalSales = (int) DB::connection('ledger')
            ->table('product_ledgers')
            ->whereNotNull('created_at')
            ->sum($outColumn);

        $totalOnlineInvoice = DB::connection('sales')->table('online_reports')->count();
        $totalSalesReturn = DB::connection('sales')->table('sales_returns')->count();
        $totalWaybill = DB::connection('sales')->table('sales_orders')
            ->where('status', 'Confirmed')
            ->where(function ($q) {
                $q->whereNull('waybill_no')
                    ->orWhere('waybill_no', '')
                    ->orWhere('waybill_no', 'NULL');
            })
            ->distinct('customer_name')
            ->count('customer_name');

        $categoryDistributionRows = DB::connection('masterlist')
            ->table('products')
            ->select('category', DB::raw('COUNT(*) as total'))
            ->whereNotNull('category')
            ->where('category', '!=', '')
            ->groupBy('category')
            ->orderByDesc('total')
            ->limit(8)
            ->get();

        $categoryDistributionLabels = $categoryDistributionRows->pluck('category')->values()->all();
        $categoryDistributionValues = $categoryDistributionRows->pluck('total')->map(fn ($v) => (int) $v)->values()->all();

        $docTypeColumn = hatdogSchemaHasColumnCached('sales', 'sales_notes', 'so_types') ? 'so_types' : 'so_type';
        $documentDistributionRows = DB::connection('sales')
            ->table('sales_notes')
            ->select("$docTypeColumn as doc_type", DB::raw('COUNT(*) as total'))
            ->whereNotNull($docTypeColumn)
            ->where($docTypeColumn, '!=', '')
            ->groupBy($docTypeColumn)
            ->orderByDesc('total')
            ->limit(8)
            ->get();

        $documentDistributionLabels = $documentDistributionRows->pluck('doc_type')->values()->all();
        $documentDistributionValues = $documentDistributionRows->pluck('total')->map(fn ($v) => (int) $v)->values()->all();

        return [
            'total_products' => $totalProducts,
            'newly_added_count' => $newlyAddedCount,
            'low_stock_count' => $lowStockCount,
            'total_suppliers' => $totalSuppliers,
            'total_customers' => $totalCustomers,
            'total_sales' => $totalSales,
            'total_online_invoice' => $totalOnlineInvoice,
            'total_sales_return' => $totalSalesReturn,
            'total_waybill' => $totalWaybill,
            'category_distribution_labels' => $categoryDistributionLabels,
            'category_distribution_values' => $categoryDistributionValues,
            'document_distribution_labels' => $documentDistributionLabels,
            'document_distribution_values' => $documentDistributionValues,
        ];
    });

    $welcomeFirstName = trim((string) ($user->User_First_Name ?? ''));
    $welcomeMiddleName = trim((string) ($user->User_Middle_Name ?? ''));
    $welcomeLastName = trim((string) ($user->User_Last_Name ?? ''));
    $welcomeGender = (string) ($user->Gender ?? 'Other');
    $welcomeFullName = trim(collect([$welcomeFirstName, $welcomeMiddleName, $welcomeLastName])->filter()->implode(' '));
    $welcomeAccountTypeLabel = match ((int) ($user->account_type ?? 1)) {
        1 => 'Admin',
        2 => 'Employee',
        3 => 'Employee',
        4 => 'Developer',
        default => 'User',
    };
    $welcomeProfilePictureUrl = null;

    try {
        if (Schema::hasTable('logins')) {
            $welcomeUserQuery = Login::query()
                ->select(['login_ID', 'User_ID', 'Gender']);

            $hasProfilePictureColumn = hatdogSchemaHasColumnCached(null, 'logins', 'profile_picture');
            $hasProfilePictureMimeColumn = hatdogSchemaHasColumnCached(null, 'logins', 'profile_picture_mime');

            if ($hasProfilePictureColumn) {
                $welcomeUserQuery->addSelect('profile_picture');
            }

            if ($hasProfilePictureMimeColumn) {
                $welcomeUserQuery->addSelect('profile_picture_mime');
            }

            if (!empty($user->login_ID)) {
                $welcomeUserQuery->where('login_ID', $user->login_ID);
            } elseif (!empty($user->User_ID)) {
                $welcomeUserQuery->where('User_ID', $user->User_ID);
            }

            $welcomeUser = $welcomeUserQuery->first();

            if ($welcomeUser) {
                $welcomeGender = (string) ($welcomeUser->Gender ?? $welcomeGender);

                if ($hasProfilePictureColumn && !empty($welcomeUser->profile_picture)) {
                    $welcomeProfilePictureUrl = 'data:' . ($hasProfilePictureMimeColumn ? ($welcomeUser->profile_picture_mime ?: 'image/png') : 'image/png')
                        . ';base64,' . base64_encode($welcomeUser->profile_picture);
                }
            }
        }
    } catch (\Throwable $e) {
        // Keep dashboard rendering even if profile lookup fails.
    }

    return view('Admin.dashboard.Dashboard', [
        'user' => $user,
        'account_type' => 1,
        'welcome_full_name' => $welcomeFullName ?: 'Admin User',
        'welcome_gender' => $welcomeGender,
        'welcome_profile_picture_url' => $welcomeProfilePictureUrl,
        'welcome_account_type_label' => $welcomeAccountTypeLabel,
        'dashboard_table_data_url' => route('admin.dashboard.table-data'),
    ] + $dashboardData);
})->name('admin.dashboard');

Route::get('/admin/dashboard/table-data', function () {
    $user = session('user');
    if (!$user) {
        return response()->json(['message' => 'Unauthorized'], 403);
    }
    if (is_array($user)) {
        $user = (object) $user;
    }
    if ($user->account_type != 1) {
        return response()->json(['message' => 'Unauthorized'], 403);
    }

    return response()->json(hatdogBuildAdminDashboardTableData());
})->name('admin.dashboard.table-data');

// Developer Control Panel Route
Route::get('/developer/control-panel', function () {
    $user = session('user');
    if (!$user) {
        return redirect()->route('login');
    }

    if (is_array($user)) {
        $user = (object) $user;
    }

    if ($user->account_type != 4) {
        return redirect()->route('login');
    }

    $safeTableCount = function (string $connection, string $table, ?callable $queryCallback = null): int {
        try {
            if (!Schema::connection($connection)->hasTable($table)) {
                return 0;
            }

            $query = DB::connection($connection)->table($table);
            if ($queryCallback) {
                $queryCallback($query);
            }

            return (int) $query->count();
        } catch (\Throwable $e) {
            return 0;
        }
    };

    $loginCount = $safeTableCount('mysql', 'logins');
    $productCount = $safeTableCount('masterlist', 'products');
    $supplierCount = $safeTableCount('masterlist', 'suppliers', function ($query) {
        if (Schema::connection('masterlist')->hasColumn('suppliers', 'record_type')) {
            $query->where(function ($query) {
                $query->whereNull('record_type')->orWhere('record_type', 'supplier');
            });
        }
    });
    $customerCount = $safeTableCount('masterlist', 'customers') + $safeTableCount('masterlist', 'suppliers', function ($query) {
        if (Schema::connection('masterlist')->hasColumn('suppliers', 'record_type')) {
            $query->where('record_type', 'customer');
        } else {
            $query->whereRaw('1 = 0');
        }
    });
    $forwarderCount = $safeTableCount('masterlist', 'forwarders');

    $totalData = $loginCount + $productCount + $supplierCount + $customerCount + $forwarderCount;
    $totalDatabases = collect([
        config('database.connections.mysql.database'),
        config('database.connections.masterlist.database'),
    ])->filter()->unique()->count();

    try {
        $suspiciousAttempts = (int) Cache::get('security:suspicious_attempts', 0);
    } catch (\Throwable $e) {
        $suspiciousAttempts = 0;
    }

    $backupPath = storage_path('app/data-ups');
    $backupFiles = File::isDirectory($backupPath)
        ? collect(File::files($backupPath))->sortByDesc(fn ($file) => $file->getMTime())->values()
        : collect();

    $nowManila = now('Asia/Manila');
    $nextBackupAt = $nowManila->copy()->setTime(18, 0);
    if ($nextBackupAt->lessThanOrEqualTo($nowManila)) {
        $nextBackupAt->addDay();
    }

    $themeNow = hatdogSystemThemeNow();
    $activeTheme = hatdogActiveSystemTheme();
    $themeState = hatdogReadSystemThemeState();

    return view('Developer.developer_control_panel', [
        'user' => $user,
        'activeTheme' => $activeTheme,
        'themeOptions' => hatdogSystemThemeOptions(),
        'themeCountdowns' => hatdogBuildSystemThemeCountdowns($themeNow),
        'themeNowMs' => $themeNow->getTimestampMs(),
        'themeState' => $themeState,
        'stats' => [
            'total_data' => $totalData,
            'total_database' => $totalDatabases,
            'suspicious_attempts' => $suspiciousAttempts,
            'logins' => $loginCount,
            'products' => $productCount,
            'suppliers' => $supplierCount,
            'customers' => $customerCount,
            'forwarders' => $forwarderCount,
        ],
        'backup' => [
            'count' => $backupFiles->count(),
            'latest' => $backupFiles->first()?->getFilename(),
            'next_at' => $nextBackupAt->format('M d, Y h:i A'),
            'timezone' => 'Asia/Manila',
            'retention_days' => 7,
        ],
    ]);
})->name('developer.control-panel');


