Route::post('/developer/import', function (Request $request) {
    $user = session('user');
    $accountType = is_array($user) ? ($user['account_type'] ?? null) : ($user->account_type ?? null);
    if (!$user || $accountType != 4) {
        return response()->json(['success' => false, 'message' => 'Unauthorized'], 403);
    }

    $validator = Validator::make($request->all(), [
        'target' => 'required|in:product-list',
        'excel_file' => 'required|file',
        'product_age' => 'required_if:target,product-list|in:new,old',
        'import_date' => 'nullable|required_if:product_age,old|date',
    ]);

    if ($validator->fails()) {
        return response()->json([
            'success' => false,
            'message' => $validator->errors()->first(),
            'errors' => $validator->errors(),
        ], 422);
    }

    $file = $request->file('excel_file');
    if (strtolower($file->getClientOriginalExtension()) !== 'xlsx') {
        return response()->json([
            'success' => false,
            'message' => 'Only .xlsx Excel files are supported for Product List imports.',
        ], 422);
    }

    @ini_set('memory_limit', '512M');
    @set_time_limit(180);

    $normaliseHeader = function (?string $value): string {
        return preg_replace('/[^A-Z0-9]/', '', strtoupper(trim((string) $value))) ?? '';
    };

    $valueFor = function (array $row, array $columnMap, string $field): string {
        $column = $columnMap[$field] ?? null;
        return $column ? trim((string) ($row[$column] ?? '')) : '';
    };

    $parsePrice = function (string $value): ?float {
        $value = trim($value);
        if ($value === '') {
            return 0.0;
        }

        $negative = str_starts_with($value, '(') && str_ends_with($value, ')');
        $clean = preg_replace('/[^\d.\-]/', '', $value) ?? '';

        if (substr_count($clean, '.') > 1) {
            $lastDot = strrpos($clean, '.');
            $clean = str_replace('.', '', substr($clean, 0, $lastDot)).substr($clean, $lastDot);
        }

        if ($clean === '' || $clean === '-' || !is_numeric($clean)) {
            return null;
        }

        $price = (float) $clean;
        return $negative ? -1 * abs($price) : $price;
    };

    try {
        $rows = (new SimpleXlsxReader())->rows($file->getRealPath());
    } catch (\Throwable $e) {
        return response()->json([
            'success' => false,
            'message' => $e->getMessage(),
        ], 422);
    }

    $fieldHeaders = [
        'product_code' => ['ITEMCODE'],
        'part_number' => ['PARTNUMBER'],
        'description' => ['DESCRIPTION'],
        'application' => ['APPLICATION', 'APPLCATION', 'APLICATON'],
        'position' => ['POSITION'],
        'category' => ['CATEGOTY', 'CATEGORY'],
        'selling_price' => ['PRICE'],
    ];

    $headerRowIndex = null;
    $columnMap = [];

    foreach ($rows as $index => $row) {
        $candidate = [];
        foreach ($row as $column => $cellValue) {
            $header = $normaliseHeader($cellValue);
            foreach ($fieldHeaders as $field => $acceptedHeaders) {
                if (in_array($header, $acceptedHeaders, true)) {
                    $candidate[$field] = $column;
                }
            }
        }

        if (isset($candidate['product_code'], $candidate['part_number'], $candidate['description'], $candidate['application'], $candidate['category'], $candidate['selling_price'])) {
            // If position not detected but product_code is 'A', position might be in a nearby column
            $headerRowIndex = $index;
            $columnMap = $candidate;
            break;
        }
    }

    if ($headerRowIndex === null) {
        return response()->json([
            'success' => false,
            'message' => 'The Product List headers were not found. Required headers: ITEMCODE, PART NUMBER, DESCRIPTION, APPLICATION, CATEGORY/CATEGOTY, PRICE.',
        ], 422);
    }

    $isOld = $request->input('product_age') === 'old';
    $dateAdded = $isOld
        ? date('Y-m-d', strtotime($request->input('import_date')))
        : now('Asia/Manila')->toDateString();
    $status = $isOld ? 'Old' : 'Newly';
    $now = now();
    $productsByCode = [];
    $errors = [];
    $duplicateRows = 0;

    foreach (array_slice($rows, $headerRowIndex + 1) as $rowOffset => $row) {
        $excelRowNumber = $headerRowIndex + $rowOffset + 2;
        $productCode = $valueFor($row, $columnMap, 'product_code');
        $partNumber = $valueFor($row, $columnMap, 'part_number');
        $category = $valueFor($row, $columnMap, 'category');
        $price = $parsePrice($valueFor($row, $columnMap, 'selling_price'));

        $hasAnyMappedValue = collect(array_keys($fieldHeaders))
            ->contains(fn (string $field): bool => $valueFor($row, $columnMap, $field) !== '');

        if (!$hasAnyMappedValue) {
            continue;
        }

        if ($productCode === '') {
            $errors[] = "Row {$excelRowNumber}: ITEMCODE is required.";
            continue;
        }

        if ($partNumber === '') {
            $errors[] = "Row {$excelRowNumber}: PART NUMBER is required.";
            continue;
        }

        if ($category === '') {
            $errors[] = "Row {$excelRowNumber}: CATEGORY is required.";
            continue;
        }

        if ($price === null || $price < 0) {
            $errors[] = "Row {$excelRowNumber}: PRICE must be a valid non-negative number.";
            continue;
        }

        if (isset($productsByCode[$productCode])) {
            $duplicateRows++;
        }

        $applicationCol = $columnMap['application'] ?? null;
        $applicationValue = '';
        if ($applicationCol) {
            $parts = [];
            $colIndex = ord($applicationCol);
            for ($c = $colIndex; $c <= $colIndex + 3; $c++) {
                $letter = chr($c);
                $val = trim((string) ($row[$letter] ?? ''));
                if ($val !== '') $parts[] = $val;
            }
            $applicationValue = implode(' ', $parts);
        }

        $productsByCode[$productCode] = [
            'product_code' => $productCode,
            'part_number' => $partNumber,
            'category' => $category,
            'description' => $valueFor($row, $columnMap, 'description'),
            'date_added' => $dateAdded,
            'application' => $applicationValue,
            'position' => $valueFor($row, $columnMap, 'position'),
            'on_hand' => 0,
            'status' => $status,
            'selling_price' => $price,
            'cost' => 0,
            'created_at' => $now,
            'updated_at' => $now,
        ];
    }

    $products = array_values($productsByCode);
    if (count($products) === 0) {
        return response()->json([
            'success' => false,
            'message' => 'No valid Product List rows were found to import.',
            'errors' => array_slice($errors, 0, 20),
        ], 422);
    }

    $productCodes = array_column($products, 'product_code');
    $existingCodes = [];
    foreach (array_chunk($productCodes, 1000) as $chunk) {
        $existingCodes += DB::connection('masterlist')
            ->table('products')
            ->whereIn('product_code', $chunk)
            ->pluck('product_code')
            ->mapWithKeys(fn (string $code): array => [$code => true])
            ->all();
    }

    $createdCount = 0;
    $updatedCount = 0;
    foreach ($productCodes as $code) {
        if (isset($existingCodes[$code])) {
            $updatedCount++;
        } else {
            $createdCount++;
        }
    }

    $updateColumns = [
        'part_number',
        'category',
        'description',
        'date_added',
        'application',
        'position',
        'on_hand',
        'status',
        'selling_price',
        'cost',
        'updated_at',
    ];

    DB::connection('masterlist')->transaction(function () use ($products, $updateColumns): void {
        foreach (array_chunk($products, 500) as $chunk) {
            DB::connection('masterlist')
                ->table('products')
                ->upsert($chunk, ['product_code'], $updateColumns);
        }
    });

    // Create product ledger entries for imported products
    if ($createdCount > 0) {
        $importedProducts = DB::connection('masterlist')
            ->table('products')
            ->whereIn('product_code', $productCodes)
            ->where('on_hand', '>', 0)
            ->get(['id', 'product_code', 'on_hand', 'selling_price', 'cost', 'date_added']);

        if ($importedProducts->isNotEmpty()) {
            $ledgerEntries = [];
            $nowLedger = now();
            $affectedProductIds = [];
            foreach ($importedProducts as $p) {
                $affectedProductIds[] = (int) $p->id;
                $ledgerEntries[] = [
                    'product_id' => $p->id,
                    'transaction_type' => 'IN',
                    'date' => $p->date_added,
                    'transaction_number' => 'IMPORT-' . $p->product_code,
                    'reference_number' => 'BULK-IMPORT',
                    'entity_name' => 'System Import',
                    'quantity_in' => $p->on_hand,
                    'quantity_out' => 0,
                    'balance_stock' => $p->on_hand,
                    'oum' => 'PCS',
                    'price' => $p->selling_price,
                    'cost' => $p->cost,
                    'remarks' => 'Bulk import from Excel',
                    'created_at' => $nowLedger,
                    'updated_at' => $nowLedger,
                ];
            }
            foreach (array_chunk($ledgerEntries, 500) as $chunk) {
                \App\Models\ProductLedger::insert($chunk);
            }
            $uniqueProductIds = array_unique($affectedProductIds);
            \App\Services\ProductStockSyncService::syncProducts($uniqueProductIds);
            $connectedProductIds = \App\Models\OnlineProduct::on('masterlist')
                ->whereIn('product_id', $uniqueProductIds)
                ->where('is_converted', 1)
                ->pluck('product_id');
            foreach ($connectedProductIds as $pid) {
                \App\Jobs\SyncShopeeProductInventory::dispatch((int) $pid)
                    ->onQueue('shopee-stock');
            }
            if ($connectedProductIds->isNotEmpty()) {
                \Illuminate\Support\Facades\Log::info('[SHOPEE STOCK SYNC] Bulk import dispatched sync jobs', [
                    'product_ids' => $connectedProductIds->toArray(),
                ]);
            }
        }
    }

    $totalProducts = DB::connection('masterlist')->table('products')->count();
    $skippedCount = count($errors);

    return response()->json([
        'success' => true,
        'message' => "Product List import completed. {$createdCount} created, {$updatedCount} updated, {$skippedCount} skipped.",
        'summary' => [
            'created' => $createdCount,
            'updated' => $updatedCount,
            'skipped' => $skippedCount,
            'duplicate_excel_rows' => $duplicateRows,
            'total_products' => $totalProducts,
            'date_added' => $dateAdded,
            'status' => $status,
        ],
        'errors' => array_slice($errors, 0, 20),
    ]);
})->name('developer.import');

