Route::get('/developer/data-ups/download/{type}/{filename?}', function (string $type, $filename = null) {
    $user = session('user');
    $accountType = is_array($user) ? ($user['account_type'] ?? null) : ($user->account_type ?? null);
    if (!$user || $accountType != 4) {
        return response()->json(['success' => false, 'message' => 'Unauthorized'], 403);
    }

    $validTypes = ['masterlist', 'purchase', 'sales', 'accounting', 'ledger'];
    if (!in_array($type, $validTypes)) {
        return response()->json(['success' => false, 'message' => 'Invalid type'], 400);
    }

    $connectionMap = [
        'masterlist' => 'masterlist',
        'purchase' => 'purchase',
        'sales' => 'sales',
        'accounting' => 'accounting',
        'ledger' => 'ledger',
    ];

    try {
        @set_time_limit(300);
        $zipPath = hatdogDataupsExportZip($connectionMap[$type], $type);
        $timestamp = now('Asia/Manila')->format('Y-m-d_H-i-s');
        $filename = "hatdog_{$type}_backup_{$timestamp}.zip";
        if (ob_get_level()) { ob_end_clean(); }
        return response()->download($zipPath, $filename, [
            'Content-Type' => 'application/zip',
            'Content-Disposition' => 'attachment; filename="' . $filename . '"; filename*=UTF-8\'\'' . rawurlencode($filename),
        ])->deleteFileAfterSend(true);
    } catch (\Throwable $e) {
        return response()->json(['success' => false, 'message' => $e->getMessage()], 500);
    }
})->where('filename', '[^/]+')->name('developer.data-ups.download');

Route::get('/developer/data-ups/download-all/{filename?}', function ($filename = null) {
    $user = session('user');
    $accountType = is_array($user) ? ($user['account_type'] ?? null) : ($user->account_type ?? null);
    if (!$user || $accountType != 4) {
        return response()->json(['success' => false, 'message' => 'Unauthorized'], 403);
    }

    $timestamp = now('Asia/Manila')->format('Y-m-d_H-i-s');
    $tmp = rtrim(sys_get_temp_dir(), '\/');
    $allZipPath = $tmp . DIRECTORY_SEPARATOR . 'du_all_' . bin2hex(random_bytes(8)) . '.zip';
    $allZip = new ZipArchive();
    if ($allZip->open($allZipPath, ZipArchive::CREATE) !== true) {
        return response()->json(['success' => false, 'message' => 'Failed to create download'], 500);
    }

    $groups = ['masterlist', 'purchase', 'sales', 'accounting', 'ledger'];
    $connectionMap = [
        'masterlist' => 'masterlist',
        'purchase' => 'purchase',
        'sales' => 'sales',
        'accounting' => 'accounting',
        'ledger' => 'ledger',
    ];
    $groupZipPaths = [];

    try {
        @set_time_limit(600);
        foreach ($groups as $group) {
            $groupZip = hatdogDataupsExportZip($connectionMap[$group], $group);
            $groupZipPaths[] = $groupZip;
            $allZip->addFile($groupZip, "hatdog_{$group}_backup_{$timestamp}.zip");
        }
    } catch (\Throwable $e) {
        foreach ($groupZipPaths as $p) { @unlink($p); }
        $allZip->close();
        @unlink($allZipPath);
        return response()->json(['success' => false, 'message' => $e->getMessage()], 500);
    }

    $allZip->close();

    foreach ($groupZipPaths as $p) { @unlink($p); }

    $filename = "hatdog_full_backup_{$timestamp}.zip";
    if (ob_get_level()) { ob_end_clean(); }
    return response()->download($allZipPath, $filename, [
        'Content-Type' => 'application/zip',
        'Content-Disposition' => 'attachment; filename="' . $filename . '"; filename*=UTF-8\'\'' . rawurlencode($filename),
    ])->deleteFileAfterSend(true);
})->where('filename', '[^/]+')->name('developer.data-ups.download-all');

Route::get('/admin/profile', function () {
    $user = session('user');
    if (!$user) {
        return redirect()->route('login');
    }
    if (is_array($user)) {
        $user = (object) $user;
    }
    if ($user->account_type != 1) {
        return redirect()->route('login');
    }

    $profileUser = Login::where('login_ID', $user->login_ID ?? 0)
        ->orWhere('User_ID', $user->User_ID)
        ->first();

    if (!$profileUser) {
        return redirect()->route('admin.dashboard');
    }

    $accountTypeLabel = match ((int) $profileUser->account_type) {
        1 => 'Admin',
        2 => 'Employee',
        3 => 'Employee',
        4 => 'Developer',
        default => 'Unknown',
    };

    $profilePictureUrl = null;
    $hasProfilePictureColumn = Schema::hasColumn('logins', 'profile_picture');
    $hasProfilePictureMimeColumn = Schema::hasColumn('logins', 'profile_picture_mime');

    if ($hasProfilePictureColumn && !empty($profileUser->profile_picture)) {
        $profilePictureUrl = 'data:' . ($hasProfilePictureMimeColumn ? ($profileUser->profile_picture_mime ?: 'image/png') : 'image/png')
            . ';base64,' . base64_encode($profileUser->profile_picture);
    }

    $graphDays = collect(range(6, 0))
        ->map(fn ($daysAgo) => \Carbon\Carbon::today()->subDays($daysAgo))
        ->values();

    $dailyLoginMap = $graphDays->mapWithKeys(fn ($date) => [$date->toDateString() => 0]);
    $totalLoginCount = 0;
    $weeklyLoginCount = 0;
    $latestLoginAt = null;

    if (Schema::hasTable('login_activity_logs')) {
        $loginActivityBaseQuery = DB::table('login_activity_logs')
            ->where('user_id', $profileUser->User_ID);

        $totalLoginCount = (clone $loginActivityBaseQuery)->count();
        $weeklyLoginCount = (clone $loginActivityBaseQuery)
            ->where('logged_in_at', '>=', now()->startOfWeek())
            ->count();
        $latestLoginAt = (clone $loginActivityBaseQuery)->max('logged_in_at');

        $dailyCounts = (clone $loginActivityBaseQuery)
            ->whereBetween('logged_in_at', [
                $graphDays->first()->copy()->startOfDay(),
                $graphDays->last()->copy()->endOfDay(),
            ])
            ->selectRaw('DATE(logged_in_at) as login_date, COUNT(*) as total')
            ->groupBy('login_date')
            ->pluck('total', 'login_date');

        foreach ($dailyCounts as $loginDate => $total) {
            if ($dailyLoginMap->has($loginDate)) {
                $dailyLoginMap->put($loginDate, (int) $total);
            }
        }
    }

    return view('partials.admin.admin-profile', [
        'user' => $user,
        'account_type' => 1,
        'profileUser' => $profileUser,
        'accountTypeLabel' => $accountTypeLabel,
        'profilePictureUrl' => $profilePictureUrl,
        'loginGraphLabels' => $graphDays->map(fn ($date) => $date->format('M d'))->values(),
        'loginGraphData' => $dailyLoginMap->values(),
        'totalLoginCount' => $totalLoginCount,
        'weeklyLoginCount' => $weeklyLoginCount,
        'latestLoginAt' => $latestLoginAt ? \Carbon\Carbon::parse($latestLoginAt)->format('M d, Y h:i A') : 'No login activity yet',
    ]);
})->name('admin.profile');

Route::post('/admin/profile/update', function (Request $request) {
    $user = session('user');
    if (!$user) {
        return response()->json(['error' => 'Unauthorized'], 403);
    }
    if (is_array($user)) {
        $user = (object) $user;
    }
    if ($user->account_type != 1) {
        return response()->json(['error' => 'Unauthorized'], 403);
    }

    $validated = $request->validate([
        'User_First_Name' => 'required|string|max:255',
        'User_Middle_Name' => 'nullable|string|max:255',
        'User_Last_Name' => 'required|string|max:255',
    ]);

    $profileUser = Login::where('login_ID', $user->login_ID ?? 0)
        ->orWhere('User_ID', $user->User_ID)
        ->first();

    if (!$profileUser) {
        return response()->json(['error' => 'Profile not found.'], 404);
    }

    $profileUser->User_First_Name = trim($validated['User_First_Name']);
    $profileUser->User_Middle_Name = trim((string) ($validated['User_Middle_Name'] ?? '')) ?: null;
    $profileUser->User_Last_Name = trim($validated['User_Last_Name']);
    $profileUser->save();

    $freshSessionUser = Login::select(hatdogLoginSessionColumns())
        ->where('login_ID', $profileUser->login_ID)
        ->first();

    if ($freshSessionUser) {
        session(['user' => $freshSessionUser]);
    }

    return response()->json([
        'success' => true,
        'message' => 'Profile information updated successfully.',
        'full_name' => trim(collect([
            $profileUser->User_First_Name,
            $profileUser->User_Middle_Name,
            $profileUser->User_Last_Name,
        ])->filter()->implode(' ')),
    ]);
})->name('admin.profile.update');

Route::post('/admin/profile/picture', function (Request $request) {
    $user = session('user');
    if (!$user) {
        return response()->json(['error' => 'Unauthorized'], 403);
    }
    if (is_array($user)) {
        $user = (object) $user;
    }
    if ($user->account_type != 1) {
        return response()->json(['error' => 'Unauthorized'], 403);
    }

    if (!Schema::hasColumn('logins', 'profile_picture')) {
        return response()->json(['error' => 'Profile picture column is not available yet. Please run the latest migrations first.'], 422);
    }

    $validated = $request->validate([
        'profile_picture' => 'required|image|max:3072|mimes:jpg,jpeg,png,webp,gif',
    ]);

    $profileUser = Login::where('login_ID', $user->login_ID ?? 0)
        ->orWhere('User_ID', $user->User_ID)
        ->first();

    if (!$profileUser) {
        return response()->json(['error' => 'Profile not found.'], 404);
    }

    $file = $validated['profile_picture'];
    $updatePayload = [
        'profile_picture' => file_get_contents($file->getRealPath()),
        'updated_at' => now(),
    ];

    if (Schema::hasColumn('logins', 'profile_picture_mime')) {
        $updatePayload['profile_picture_mime'] = $file->getMimeType();
    }

    DB::table('logins')
        ->where('login_ID', $profileUser->login_ID)
        ->update($updatePayload);

    return response()->json([
        'success' => true,
        'image_url' => 'data:' . ($file->getMimeType() ?: 'image/png') . ';base64,' . base64_encode(file_get_contents($file->getRealPath())),
    ]);
})->name('admin.profile.picture.update');

// Admin USM Route
Route::get('/admin/usm', function () {
    $user = session('user');
    if (!$user) {
        return redirect()->route('login');
    }
    if (is_array($user)) {
        $user = (object) $user;
    }
    if ($user->account_type != 1) {
        return redirect()->route('login');
    }
    
    // Fetch all login records ordered by newest first
    $dbUsers = Login::select(hatdogLoginSessionColumns())->orderBy('created_at', 'desc')->get()->each->makeVisible('Password');

    $sessionTable = config('session.table', 'sessions');
    $sessionLifetimeSeconds = max(1, (int) config('session.lifetime', 120)) * 60;
    $onlineUserIds = collect();

    if (Schema::hasTable($sessionTable)) {
        $onlineUserIds = DB::table($sessionTable)
            ->where('last_activity', '>=', now()->subSeconds($sessionLifetimeSeconds)->timestamp)
            ->pluck('payload')
            ->map(function ($payload) {
                $decodedPayload = base64_decode((string) $payload, true);
                if ($decodedPayload === false || $decodedPayload === '') {
                    return null;
                }

                $sessionData = json_decode($decodedPayload, true);
                if (!is_array($sessionData)) {
                    $sessionData = @unserialize($decodedPayload);
                }

                if (!is_array($sessionData)) {
                    return null;
                }

                $sessionUser = $sessionData['user'] ?? null;

                if (is_array($sessionUser)) {
                    return $sessionUser['User_ID'] ?? null;
                }

                if (is_object($sessionUser)) {
                    return $sessionUser->User_ID ?? null;
                }

                return null;
            })
            ->filter()
            ->unique()
            ->values();
    }
    
    return view('Admin.System Security.USM', [
        'user' => $user,
        'account_type' => 1,
        'dbUsers' => $dbUsers,
        'onlineUserIds' => $onlineUserIds,
    ]);
})->name('admin.usm');

