Route::get('/admin/system-security/archived/data', function (Request $request) {
    $user = session('user');
    if (!$user) return response()->json(['success' => false, 'message' => 'Unauthorized'], 403);
    if (is_array($user)) {
        $user = (object) $user;
    }
    if (($user->account_type ?? null) != 1 && ($user->account_type ?? null) != 4) {
        return response()->json(['success' => false, 'message' => 'Unauthorized'], 403);
    }

    try {
        if (!Schema::connection('ledger')->hasTable('archived_records')) {
            return response()->json([
                'success' => true,
                'items' => [],
                'page' => 1,
                'last_page' => 1,
                'total' => 0,
                'from' => 0,
                'to' => 0,
                'per_page' => 50,
            ]);
        }

        hatdogDeleteExpiredArchivedRecords();

        $page = max(1, (int) $request->query('page', 1));
        $perPage = max(1, min(100, (int) $request->query('perPage', 50)));
        $category = (string) $request->query('category', 'all');
        $search = $request->query('search', []);

        $query = DB::connection('ledger')
            ->table('archived_records')
            ->whereNull('restored_at');

        if ($category !== 'all' && $category !== '') {
            $query->where('module', $category);
        }

        if (!empty($search['id'])) {
            $query->where('display_id', 'like', '%' . $search['id'] . '%');
        }
        if (!empty($search['name'])) {
            $query->where('data_name', 'like', '%' . $search['name'] . '%');
        }
        if (!empty($search['deleted'])) {
            $query->whereDate('deleted_at', $search['deleted']);
        }

        $paginator = $query
            ->orderByDesc('deleted_at')
            ->paginate($perPage, ['*'], 'page', $page);

        $items = collect($paginator->items())->map(function ($row) {
            $deletedAt = $row->deleted_at ? \Carbon\Carbon::parse($row->deleted_at) : null;
            $expiresAt = $row->expires_at ? \Carbon\Carbon::parse($row->expires_at) : null;
            $remainingDays = $expiresAt ? max(0, now()->startOfDay()->diffInDays($expiresAt->startOfDay(), false)) : null;

            return [
                'id' => $row->id,
                'module' => $row->module,
                'display_id' => $row->display_id,
                'data_name' => $row->data_name,
                'deleted_at' => $deletedAt ? $deletedAt->format('Y-m-d H:i:s') : null,
                'expires_at' => $expiresAt ? $expiresAt->format('Y-m-d H:i:s') : null,
                'remaining_days' => $remainingDays === null ? '---' : ($remainingDays . ' day' . ($remainingDays === 1 ? '' : 's')),
            ];
        });

        if (!empty($search['remaining'])) {
            $needle = strtolower((string) $search['remaining']);
            $items = $items->filter(fn ($row) => str_contains(strtolower((string) $row['remaining_days']), $needle))->values();
        }

        return response()->json([
            'success' => true,
            'items' => $items->values(),
            'page' => $paginator->currentPage(),
            'last_page' => $paginator->lastPage(),
            'total' => $paginator->total(),
            'from' => $paginator->firstItem() ?? 0,
            'to' => $paginator->lastItem() ?? 0,
            'per_page' => $paginator->perPage(),
        ]);
    } catch (\Throwable $e) {
        Log::error('Archive data error: ' . $e->getMessage());
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.archived.data');

Route::post('/admin/system-security/archived/restore', function (Request $request) {
    $user = session('user');
    if (!$user) return response()->json(['success' => false, 'message' => 'Unauthorized'], 403);
    if (is_array($user)) {
        $user = (object) $user;
    }
    if (($user->account_type ?? null) != 1 && ($user->account_type ?? null) != 4) {
        return response()->json(['success' => false, 'message' => 'Unauthorized'], 403);
    }

    $module = (string) $request->input('module');
    $id = $request->input('id');

    if (!$id) {
        return response()->json(['success' => false, 'message' => 'Missing archived item ID.'], 422);
    }

    try {
        if (!in_array($module, ['product', 'supplier', 'customer', 'forwarder', 'purchase_note', 'purchase_return', 'sales_note'], true)) {
            return response()->json(['success' => false, 'message' => 'Restore is currently available for Product, Supplier, Customer, Forwarder, Purchase Note, Purchase Return, and Sales Note archives only.'], 422);
        }

        DB::connection('ledger')->beginTransaction();
        DB::connection('masterlist')->beginTransaction();
        if (in_array($module, ['purchase_note', 'purchase_return'], true)) {
            DB::connection('purchase')->beginTransaction();
        }
        if ($module === 'sales_note') {
            DB::connection('sales')->beginTransaction();
        }

        $archive = DB::connection('ledger')
            ->table('archived_records')
            ->where('id', $id)
            ->where('module', $module)
            ->whereNull('restored_at')
            ->lockForUpdate()
            ->first();

        if (!$archive) {
            throw new \Exception('Archived record not found or already restored.');
        }

        $data = json_decode((string) $archive->archived_data, true);
        if (!is_array($data)) {
            throw new \Exception('Archived record data is invalid.');
        }

        $restoreAffectedProductIds = [];

        $normalizeDbDatetime = function ($value, $fallback = null) {
            if ($value instanceof \DateTimeInterface) {
                return \Carbon\Carbon::instance($value)->format('Y-m-d H:i:s');
            }

            if ($value === null || $value === '') {
                if ($fallback instanceof \DateTimeInterface) {
                    return \Carbon\Carbon::instance($fallback)->format('Y-m-d H:i:s');
                }
                return $fallback ? \Carbon\Carbon::parse($fallback)->format('Y-m-d H:i:s') : null;
            }

            try {
                return \Carbon\Carbon::parse((string) $value)->format('Y-m-d H:i:s');
            } catch (\Throwable $e) {
                if ($fallback instanceof \DateTimeInterface) {
                    return \Carbon\Carbon::instance($fallback)->format('Y-m-d H:i:s');
                }
                return $fallback ? \Carbon\Carbon::parse($fallback)->format('Y-m-d H:i:s') : null;
            }
        };

        if ($module === 'product') {
            $productCode = (string) ($data['product_code'] ?? '');
            if ($productCode !== '' && DB::connection('masterlist')->table('products')->where('product_code', $productCode)->exists()) {
                throw new \Exception("Cannot restore product {$productCode} because that product code already exists.");
            }

            $columns = Schema::connection('masterlist')->getColumnListing('products');
            $restoreData = array_intersect_key($data, array_flip($columns));
            $restoreData['created_at'] = $normalizeDbDatetime($restoreData['created_at'] ?? null, now());
            $restoreData['updated_at'] = $normalizeDbDatetime(now(), now());

            DB::connection('masterlist')->table('products')->insert($restoreData);
        } elseif ($module === 'supplier') {
            $supplierCode = (string) ($data['supplier_code'] ?? '');
            if ($supplierCode !== '' && DB::connection('masterlist')->table('suppliers')->where('supplier_code', $supplierCode)->exists()) {
                throw new \Exception("Cannot restore supplier {$supplierCode} because that supplier code already exists.");
            }

            $columns = Schema::connection('masterlist')->getColumnListing('suppliers');
            $restoreData = array_intersect_key($data, array_flip($columns));
            $restoreData['created_at'] = $normalizeDbDatetime($restoreData['created_at'] ?? null, now());
            $restoreData['updated_at'] = $normalizeDbDatetime(now(), now());

            DB::connection('masterlist')->table('suppliers')->insert($restoreData);
        } elseif ($module === 'customer') {
            $customerData = $data['customer'] ?? null;
            if (!is_array($customerData)) {
                throw new \Exception('Archived customer data is invalid.');
            }

            $columns = Schema::connection('masterlist')->getColumnListing('customers');
            $restoreData = array_intersect_key($customerData, array_flip($columns));
            $originalCustomerId = $restoreData['id'] ?? null;

            if ($originalCustomerId && DB::connection('masterlist')->table('customers')->where('id', $originalCustomerId)->exists()) {
                unset($restoreData['id']);
            }

            $restoreData['created_at'] = $normalizeDbDatetime($restoreData['created_at'] ?? null, now());
            $restoreData['updated_at'] = $normalizeDbDatetime(now(), now());

            $newCustomerId = DB::connection('masterlist')->table('customers')->insertGetId($restoreData);

            $bankData = $data['bank_account'] ?? null;
            if (is_array($bankData)) {
                $bankColumns = Schema::connection('masterlist')->getColumnListing('customer_bank_accounts');
                $restoreBankData = array_intersect_key($bankData, array_flip($bankColumns));
                unset($restoreBankData['id']);
                $restoreBankData['customer_id'] = $newCustomerId;
                $restoreBankData['created_at'] = $normalizeDbDatetime($restoreBankData['created_at'] ?? null, now());
                $restoreBankData['updated_at'] = $normalizeDbDatetime(now(), now());

                DB::connection('masterlist')->table('customer_bank_accounts')->insert($restoreBankData);
            }
        } elseif ($module === 'forwarder') {
            $forwarderData = $data['forwarder'] ?? null;
            if (!is_array($forwarderData)) {
                throw new \Exception('Archived forwarder data is invalid.');
            }

            $forwarderCode = (string) ($forwarderData['code'] ?? '');
            if ($forwarderCode !== '' && DB::connection('masterlist')->table('forwarders')->where('code', $forwarderCode)->exists()) {
                throw new \Exception("Cannot restore forwarder {$forwarderCode} because that forwarder code already exists.");
            }

            $forwarderColumns = Schema::connection('masterlist')->getColumnListing('forwarders');
            $restoreForwarderData = array_intersect_key($forwarderData, array_flip($forwarderColumns));
            $restoreForwarderData['created_at'] = $normalizeDbDatetime($restoreForwarderData['created_at'] ?? null, now());
            $restoreForwarderData['updated_at'] = $normalizeDbDatetime(now(), now());

            $newForwarderId = DB::connection('masterlist')->table('forwarders')->insertGetId($restoreForwarderData);

            $contactData = $data['contact'] ?? null;
            if (is_array($contactData)) {
                $contactColumns = Schema::connection('masterlist')->getColumnListing('forwarder_contacts');
                $restoreContactData = array_intersect_key($contactData, array_flip($contactColumns));
                unset($restoreContactData['id']);
                $restoreContactData['forwarder_id'] = $newForwarderId;
                $restoreContactData['created_at'] = $normalizeDbDatetime($restoreContactData['created_at'] ?? null, now());
                $restoreContactData['updated_at'] = $normalizeDbDatetime(now(), now());

                DB::connection('masterlist')->table('forwarder_contacts')->insert($restoreContactData);
            }

            $addressData = $data['address'] ?? null;
            if (is_array($addressData)) {
                $addressColumns = Schema::connection('masterlist')->getColumnListing('forwarder_addresses');
                $restoreAddressData = array_intersect_key($addressData, array_flip($addressColumns));
                unset($restoreAddressData['id']);
                $restoreAddressData['forwarder_id'] = $newForwarderId;
                $restoreAddressData['created_at'] = $normalizeDbDatetime($restoreAddressData['created_at'] ?? null, now());
                $restoreAddressData['updated_at'] = $normalizeDbDatetime(now(), now());

                DB::connection('masterlist')->table('forwarder_addresses')->insert($restoreAddressData);
            }
        } elseif ($module === 'purchase_note') {
            $purchaseNoteData = $data['purchase_note'] ?? null;
            if (!is_array($purchaseNoteData)) {
                throw new \Exception('Archived purchase note data is invalid.');
            }

            $purchaseNoteNumber = (string) ($purchaseNoteData['purchase_note_number'] ?? '');
            if ($purchaseNoteNumber !== '' && DB::connection('purchase')->table('purchase_notes')->where('purchase_note_number', $purchaseNoteNumber)->exists()) {
                throw new \Exception("Cannot restore purchase note {$purchaseNoteNumber} because that purchase note number already exists.");
            }

            $noteColumns = Schema::connection('purchase')->getColumnListing('purchase_notes');
            $restorePurchaseNote = array_intersect_key($purchaseNoteData, array_flip($noteColumns));
            $originalPurchaseNoteId = $restorePurchaseNote['id'] ?? null;
            if ($originalPurchaseNoteId && DB::connection('purchase')->table('purchase_notes')->where('id', $originalPurchaseNoteId)->exists()) {
                unset($restorePurchaseNote['id']);
            }
            $restorePurchaseNote['created_at'] = $normalizeDbDatetime($restorePurchaseNote['created_at'] ?? null, now());
            $restorePurchaseNote['updated_at'] = $normalizeDbDatetime(now(), now());

            $newPurchaseNoteId = DB::connection('purchase')->table('purchase_notes')->insertGetId($restorePurchaseNote);

            $items = $data['items'] ?? [];
            if (is_array($items) && !empty($items)) {
                $itemColumns = Schema::connection('purchase')->getColumnListing('purchase_note_items');
                $restoreItems = collect($items)
                    ->filter(fn ($item) => is_array($item))
                    ->map(function ($item) use ($itemColumns, $newPurchaseNoteId, $normalizeDbDatetime) {
                        $row = array_intersect_key($item, array_flip($itemColumns));
                        unset($row['id']);
                        $row['purchase_note_id'] = $newPurchaseNoteId;
                        $row['created_at'] = $normalizeDbDatetime($row['created_at'] ?? null, now());
                        $row['updated_at'] = $normalizeDbDatetime(now(), now());
                        return $row;
                    })
                    ->values()
                    ->all();

                if (!empty($restoreItems)) {
                    DB::connection('purchase')->table('purchase_note_items')->insert($restoreItems);
                }
            }

            // Restore related Purchase Orders
            $poIdMap = [];
            $restoredPOCount = 0;
            $poData = $data['purchase_orders'] ?? [];
            foreach ($poData as $poRow) {
                if (!is_array($poRow)) continue;
                $poNumber = (string) ($poRow['po_number'] ?? '');
                if ($poNumber !== '' && DB::connection('purchase')->table('purchase_orders')->where('po_number', $poNumber)->exists()) {
                    continue;
                }
                $poColumns = Schema::connection('purchase')->getColumnListing('purchase_orders');
                $restorePO = array_intersect_key($poRow, array_flip($poColumns));
                $originalPOId = $restorePO['id'] ?? null;
                unset($restorePO['id']);
                $restorePO['created_at'] = $normalizeDbDatetime($restorePO['created_at'] ?? null, now());
                $restorePO['updated_at'] = $normalizeDbDatetime(now(), now());
                $newPOId = DB::connection('purchase')->table('purchase_orders')->insertGetId($restorePO);
                if ($originalPOId) {
                    $poIdMap[$originalPOId] = $newPOId;
                }
                $restoredPOCount++;
            }

            // Restore Purchase Order Items
            $restoredPOItemCount = 0;
            $poItemData = $data['purchase_order_items'] ?? [];
            if (!empty($poItemData)) {
                $poItemColumns = Schema::connection('purchase')->getColumnListing('purchase_order_items');
                $restorePOItems = collect($poItemData)
                    ->filter(fn ($item) => is_array($item))
                    ->map(function ($item) use ($poItemColumns, $poIdMap, $normalizeDbDatetime) {
                        $row = array_intersect_key($item, array_flip($poItemColumns));
                        $oldPOId = $row['purchase_order_id'] ?? null;
                        unset($row['id']);
                        $row['purchase_order_id'] = $poIdMap[$oldPOId] ?? $oldPOId;
                        $row['created_at'] = $normalizeDbDatetime($row['created_at'] ?? null, now());
                        $row['updated_at'] = $normalizeDbDatetime(now(), now());
                        return $row;
                    })
                    ->values()
                    ->all();
                if (!empty($restorePOItems)) {
                    DB::connection('purchase')->table('purchase_order_items')->insert($restorePOItems);
                }
                $restoredPOItemCount = count($restorePOItems);
            }

            // Restore Purchase Returns
            $returnIdMap = [];
            $restoredReturnCount = 0;
            $returnData = $data['purchase_returns'] ?? [];
            foreach ($returnData as $returnRow) {
                if (!is_array($returnRow)) continue;
                $returnNumber = (string) ($returnRow['return_number'] ?? '');
                if ($returnNumber !== '' && DB::connection('purchase')->table('purchase_returns')->where('return_number', $returnNumber)->exists()) {
                    continue;
                }
                $returnColumns = Schema::connection('purchase')->getColumnListing('purchase_returns');
                $restoreReturn = array_intersect_key($returnRow, array_flip($returnColumns));
                $originalReturnId = $restoreReturn['id'] ?? null;
                unset($restoreReturn['id']);
                $restoreReturn['po_id'] = $poIdMap[$restoreReturn['po_id']] ?? $restoreReturn['po_id'];
                $restoreReturn['created_at'] = $normalizeDbDatetime($restoreReturn['created_at'] ?? null, now());
                $restoreReturn['updated_at'] = $normalizeDbDatetime(now(), now());
                $newReturnId = DB::connection('purchase')->table('purchase_returns')->insertGetId($restoreReturn);
                if ($originalReturnId) {
                    $returnIdMap[$originalReturnId] = $newReturnId;
                }
                $restoredReturnCount++;
            }

            // Restore Return Items
            $restoredReturnItemCount = 0;
            $returnItemData = $data['purchase_return_items'] ?? [];
            if (!empty($returnItemData)) {
                $riColumns = Schema::connection('purchase')->getColumnListing('purchase_return_items');
                $restoreReturnItems = collect($returnItemData)
                    ->filter(fn ($item) => is_array($item))
                    ->map(function ($item) use ($riColumns, $returnIdMap, $normalizeDbDatetime) {
                        $row = array_intersect_key($item, array_flip($riColumns));
                        $oldReturnId = $row['purchase_return_id'] ?? null;
                        unset($row['id']);
                        $row['purchase_return_id'] = $returnIdMap[$oldReturnId] ?? $oldReturnId;
                        $row['created_at'] = $normalizeDbDatetime($row['created_at'] ?? null, now());
                        $row['updated_at'] = $normalizeDbDatetime(now(), now());
                        return $row;
                    })
                    ->values()
                    ->all();
                if (!empty($restoreReturnItems)) {
                    DB::connection('purchase')->table('purchase_return_items')->insert($restoreReturnItems);
                }
                $restoredReturnItemCount = count($restoreReturnItems);
            }

            $noteItemCount = is_array($items) ? count($items) : 0;
            $restoreMessage = "Purchase Note restored successfully.\nRestored:\n- 1 Purchase Note\n- {$noteItemCount} Purchase Note Items\n- {$restoredPOCount} Purchase Orders\n- {$restoredPOItemCount} Purchase Order Items\n- {$restoredReturnCount} Purchase Returns\n- {$restoredReturnItemCount} Purchase Return Items";
        } elseif ($module === 'purchase_return') {
            $purchaseReturnData = $data['purchase_return'] ?? null;
            if (!is_array($purchaseReturnData)) {
                throw new \Exception('Archived purchase return data is invalid.');
            }

            $returnNumber = (string) ($purchaseReturnData['return_number'] ?? '');
            if ($returnNumber !== '' && DB::connection('purchase')->table('purchase_returns')->where('return_number', $returnNumber)->exists()) {
                throw new \Exception("Cannot restore purchase return {$returnNumber} because that return number already exists.");
            }

            $returnColumns = Schema::connection('purchase')->getColumnListing('purchase_returns');
            $restorePurchaseReturn = array_intersect_key($purchaseReturnData, array_flip($returnColumns));
            $originalPurchaseReturnId = $restorePurchaseReturn['id'] ?? null;
            if ($originalPurchaseReturnId && DB::connection('purchase')->table('purchase_returns')->where('id', $originalPurchaseReturnId)->exists()) {
                unset($restorePurchaseReturn['id']);
            }
            $restorePurchaseReturn['created_at'] = $normalizeDbDatetime($restorePurchaseReturn['created_at'] ?? null, now());
            $restorePurchaseReturn['updated_at'] = $normalizeDbDatetime(now(), now());

            $newPurchaseReturnId = DB::connection('purchase')->table('purchase_returns')->insertGetId($restorePurchaseReturn);

            $items = $data['items'] ?? [];
            $itemColumns = Schema::connection('purchase')->getColumnListing('purchase_return_items');
            $restoreItems = collect($items)
                ->filter(fn ($item) => is_array($item))
                ->map(function ($item) use ($itemColumns, $newPurchaseReturnId, $normalizeDbDatetime) {
                    if (in_array('out_quantity', $itemColumns, true) && !array_key_exists('out_quantity', $item)) {
                        // Archives created before the OUT field existed represented the full return as stock OUT.
                        $item['out_quantity'] = (int) ($item['quantity'] ?? 0);
                    }
                    $row = array_intersect_key($item, array_flip($itemColumns));
                    unset($row['id']);
                    $row['purchase_return_id'] = $newPurchaseReturnId;
                    $row['created_at'] = $normalizeDbDatetime($row['created_at'] ?? null, now());
                    $row['updated_at'] = $normalizeDbDatetime(now(), now());
                    return $row;
                })
                ->values()
                ->all();

            if (!empty($restoreItems)) {
                DB::connection('purchase')->table('purchase_return_items')->insert($restoreItems);
            }

            $restoredPurchaseReturn = \App\Models\PurchaseReturn::with(['items', 'supplier'])
                ->findOrFail($newPurchaseReturnId);

            $restoreAffectedProductIds = app(\App\Services\PurchaseReturnProductLedgerService::class)
                ->replaceForReturn($restoredPurchaseReturn);

            \App\Models\SupplierLedger::create([
                'supplier_id' => $restorePurchaseReturn['supplier_id'] ?? null,
                'date' => $restorePurchaseReturn['date'] ?? now()->toDateString(),
                'transaction_code' => $returnNumber,
                'module_type' => 'Purchase Return',
                'title' => "Purchase Return Processing - {$returnNumber}",
                'credit_amount' => 0,
                'debit_amount' => (float) ($restorePurchaseReturn['total_amount'] ?? 0),
                'reference_no' => $returnNumber,
            ]);
        } elseif ($module === 'sales_note') {
            $salesNoteData = $data['sales_note'] ?? null;
            if (!is_array($salesNoteData)) {
                throw new \Exception('Archived sales note data is invalid.');
            }

            $salesNumber = (string) ($salesNoteData['sales_number'] ?? '');
            if ($salesNumber !== '' && DB::connection('sales')->table('sales_notes')->where('sales_number', $salesNumber)->exists()) {
                throw new \Exception("Cannot restore sales note {$salesNumber} because that sales number already exists.");
            }

            $salesNoteColumns = Schema::connection('sales')->getColumnListing('sales_notes');
            $restoreSalesNote = array_intersect_key($salesNoteData, array_flip($salesNoteColumns));
            $originalSalesNoteId = $restoreSalesNote['id'] ?? null;
            if ($originalSalesNoteId && DB::connection('sales')->table('sales_notes')->where('id', $originalSalesNoteId)->exists()) {
                unset($restoreSalesNote['id']);
            }
            $restoreSalesNote['created_at'] = $normalizeDbDatetime($restoreSalesNote['created_at'] ?? null, now());
            $restoreSalesNote['updated_at'] = $normalizeDbDatetime(now(), now());

            $newSalesNoteId = DB::connection('sales')->table('sales_notes')->insertGetId($restoreSalesNote);

            $items = $data['items'] ?? [];
            if (is_array($items) && !empty($items)) {
                $salesItemColumns = Schema::connection('sales')->getColumnListing('sales_note_items');
                $restoreItems = collect($items)
                    ->filter(fn ($item) => is_array($item))
                    ->map(function ($item) use ($salesItemColumns, $newSalesNoteId, $normalizeDbDatetime) {
                        $row = array_intersect_key($item, array_flip($salesItemColumns));
                        unset($row['id']);
                        $row['sales_note_id'] = $newSalesNoteId;
                        $row['created_at'] = $normalizeDbDatetime($row['created_at'] ?? null, now());
                        $row['updated_at'] = $normalizeDbDatetime(now(), now());
                        return $row;
                    })
                    ->values()
                    ->all();

                if (!empty($restoreItems)) {
                    DB::connection('sales')->table('sales_note_items')->insert($restoreItems);
                }
            }

            // Restore related Sales Orders
            $orderIdMap = [];
            $restoredOrderCount = 0;
            $orderData = $data['sales_orders'] ?? [];
            foreach ($orderData as $orderRow) {
                if (!is_array($orderRow)) continue;
                $originalOrderId = $orderRow['id'] ?? null;
                if ($originalOrderId && DB::connection('sales')->table('sales_orders')->where('id', $originalOrderId)->exists()) {
                    continue;
                }
                $orderColumns = Schema::connection('sales')->getColumnListing('sales_orders');
                $restoreOrder = array_intersect_key($orderRow, array_flip($orderColumns));
                $originalOrderId = $restoreOrder['id'] ?? null;
                unset($restoreOrder['id']);
                $restoreOrder['sales_note_id'] = $newSalesNoteId;
                $restoreOrder['created_at'] = $normalizeDbDatetime($restoreOrder['created_at'] ?? null, now());
                $restoreOrder['updated_at'] = $normalizeDbDatetime(now(), now());
                $newOrderId = DB::connection('sales')->table('sales_orders')->insertGetId($restoreOrder);
                if ($originalOrderId) {
                    $orderIdMap[$originalOrderId] = $newOrderId;
                }
                $restoredOrderCount++;
            }

            // Restore Sales Order Items
            $restoredOrderItemCount = 0;
            $orderItemData = $data['sales_order_items'] ?? [];
            if (!empty($orderItemData)) {
                $oiColumns = Schema::connection('sales')->getColumnListing('sales_order_items');
                $restoreOrderItems = collect($orderItemData)
                    ->filter(fn ($item) => is_array($item))
                    ->map(function ($item) use ($oiColumns, $orderIdMap, $normalizeDbDatetime) {
                        $row = array_intersect_key($item, array_flip($oiColumns));
                        $oldOrderId = $row['sales_order_id'] ?? null;
                        unset($row['id']);
                        $row['sales_order_id'] = $orderIdMap[$oldOrderId] ?? $oldOrderId;
                        $row['created_at'] = $normalizeDbDatetime($row['created_at'] ?? null, now());
                        $row['updated_at'] = $normalizeDbDatetime(now(), now());
                        return $row;
                    })
                    ->values()
                    ->all();
                if (!empty($restoreOrderItems)) {
                    DB::connection('sales')->table('sales_order_items')->insert($restoreOrderItems);
                }
                $restoredOrderItemCount = count($restoreOrderItems);
            }

            // Restore Sales Returns
            $returnIdMap = [];
            $restoredReturnCount = 0;
            $returnData = $data['sales_returns'] ?? [];
            foreach ($returnData as $returnRow) {
                if (!is_array($returnRow)) continue;
                $returnNumber = (string) ($returnRow['return_number'] ?? '');
                if ($returnNumber !== '' && DB::connection('sales')->table('sales_returns')->where('return_number', $returnNumber)->exists()) {
                    continue;
                }
                $returnColumns = Schema::connection('sales')->getColumnListing('sales_returns');
                $restoreReturn = array_intersect_key($returnRow, array_flip($returnColumns));
                $originalReturnId = $restoreReturn['id'] ?? null;
                unset($restoreReturn['id']);
                $restoreReturn['created_at'] = $normalizeDbDatetime($restoreReturn['created_at'] ?? null, now());
                $restoreReturn['updated_at'] = $normalizeDbDatetime(now(), now());
                $newReturnId = DB::connection('sales')->table('sales_returns')->insertGetId($restoreReturn);
                if ($originalReturnId) {
                    $returnIdMap[$originalReturnId] = $newReturnId;
                }
                $restoredReturnCount++;
            }

            // Restore Sales Return Items
            $restoredReturnItemCount = 0;
            $returnItemData = $data['sales_return_items'] ?? [];
            if (!empty($returnItemData)) {
                $riColumns = Schema::connection('sales')->getColumnListing('sales_return_items');
                $restoreReturnItems = collect($returnItemData)
                    ->filter(fn ($item) => is_array($item))
                    ->map(function ($item) use ($riColumns, $returnIdMap, $normalizeDbDatetime) {
                        $row = array_intersect_key($item, array_flip($riColumns));
                        $oldReturnId = $row['sales_return_id'] ?? null;
                        unset($row['id']);
                        $row['sales_return_id'] = $returnIdMap[$oldReturnId] ?? $oldReturnId;
                        $row['created_at'] = $normalizeDbDatetime($row['created_at'] ?? null, now());
                        $row['updated_at'] = $normalizeDbDatetime(now(), now());
                        return $row;
                    })
                    ->values()
                    ->all();
                if (!empty($restoreReturnItems)) {
                    DB::connection('sales')->table('sales_return_items')->insert($restoreReturnItems);
                }
                $restoredReturnItemCount = count($restoreReturnItems);
            }

            $noteItemCount = is_array($items) ? count($items) : 0;
            $restoreMessage = "Sales Note restored successfully.\nRestored:\n- 1 Sales Note\n- {$noteItemCount} Sales Note Items\n- {$restoredOrderCount} Sales Orders\n- {$restoredOrderItemCount} Sales Order Items\n- {$restoredReturnCount} Sales Returns\n- {$restoredReturnItemCount} Sales Return Items";
        }

        $restoredBy = $user->name ?? $user->username ?? $user->User_ID ?? 'Admin';
        DB::connection('ledger')->table('archived_records')->where('id', $archive->id)->update([
            'restored_at' => now(),
            'restored_by' => (string) $restoredBy,
            'updated_at' => now(),
        ]);

        if (in_array($module, ['purchase_note', 'purchase_return'], true)) {
            DB::connection('purchase')->commit();
        }
        if ($module === 'sales_note') {
            DB::connection('sales')->commit();
        }
        DB::connection('masterlist')->commit();
        DB::connection('ledger')->commit();

        if (!empty($restoreAffectedProductIds)) {
            \App\Services\ProductStockSyncService::syncProducts($restoreAffectedProductIds);
        }

        $finalMessage = isset($restoreMessage) ? $restoreMessage : 'The record was restored successfully.';

        return response()->json([
            'success' => true,
            'message' => $finalMessage,
            'restored' => [
                'module' => $module,
                'id' => $id,
            ],
        ]);
    } catch (\Throwable $e) {
        if (DB::connection('sales')->transactionLevel() > 0) DB::connection('sales')->rollBack();
        if (DB::connection('purchase')->transactionLevel() > 0) DB::connection('purchase')->rollBack();
        if (DB::connection('masterlist')->transactionLevel() > 0) DB::connection('masterlist')->rollBack();
        if (DB::connection('ledger')->transactionLevel() > 0) DB::connection('ledger')->rollBack();
        Log::error('Archive restore error: ' . $e->getMessage());
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.archived.restore');

