Route::get('/admin/system-security/audit-trail', function () {
    $user = session('user');
    if (!$user) {
        return redirect()->route('login');
    }
    if (is_array($user)) {
        $user = (object) $user;
    }
    if (($user->account_type ?? null) != 1) {
        return redirect()->route('login');
    }

    $auditPurgeState = hatdogPurgeAuditTrailIfDue();

    $auditViewHtml = view('Admin.System Security.Aduit-trail', [
        'user' => $user,
        'account_type' => 1,
        'audit_purge_at' => $auditPurgeState['due_at'] ?? hatdogAuditTrailPurgeTarget()->toIso8601String(),
    ])->render();

    // Product-only Audit Trail enhancer. This is injected here so the existing Audit Trail
    // Blade/dashboard/cards and every non-product module table remain completely untouched.
    $productAuditScriptPath = public_path('js/audit-product-detail.js');
    if (File::exists($productAuditScriptPath)) {
        $productAuditScriptUrl = asset('js/audit-product-detail.js') . '?v=' . File::lastModified($productAuditScriptPath);
        $productAuditScriptTag = '<script src="' . e($productAuditScriptUrl) . '"></script>';
        $bodyClosePosition = strripos($auditViewHtml, '</body>');

        if ($bodyClosePosition !== false) {
            $auditViewHtml = substr($auditViewHtml, 0, $bodyClosePosition)
                . $productAuditScriptTag
                . substr($auditViewHtml, $bodyClosePosition);
        } else {
            $auditViewHtml .= $productAuditScriptTag;
        }
    }

    return response($auditViewHtml);
})->name('admin.audit-trail');

Route::get('/admin/system-security/audit-trail/data', function (Request $request) {
    $user = session('user');
    if (!$user) return response()->json(['success' => false, 'message' => 'Unauthorized'], 403);
    if (is_array($user)) {
        $user = (object) $user;
    }
    if (($user->account_type ?? null) != 1) {
        return response()->json(['success' => false, 'message' => 'Unauthorized'], 403);
    }

    $auditPurgeState = hatdogPurgeAuditTrailIfDue();

    $page = max(1, (int) $request->query('page', 1));
    $perPage = min(100, max(1, (int) $request->query('perPage', 50)));

    if (!Schema::connection('ledger')->hasTable('audit_trails')) {
        return response()->json([
            'success' => true,
            'items' => [],
            'page' => $page,
            'last_page' => 1,
            'total' => 0,
            'from' => 0,
            'to' => 0,
            'per_page' => $perPage,
        ]);
    }

    $module = trim((string) $request->query('module', 'all'));
    $search = (array) $request->query('search', []);

    $query = DB::connection('ledger')->table('audit_trails');

    if ($module !== '' && $module !== 'all') {
        $query->where('module', $module);
    }

    // Product Masterlist has a dedicated detailed table. Keep only the three actions requested
    // for that table; all other Audit Trail modules continue using their existing action set.
    $isProductAudit = $module === 'product';
    if ($isProductAudit) {
        $query->whereIn('action', ['Created', 'Updated', 'Deleted']);
    }

    $nameSearch = trim((string) ($search['name'] ?? ''));
    $usernameSearch = trim((string) ($search['username'] ?? ''));
    $datetimeSearch = trim((string) ($search['datetime'] ?? ''));
    $actionSearch = trim((string) ($search['action'] ?? ''));
    $moduleSearch = trim((string) ($search['module'] ?? ''));

    if ($nameSearch !== '') {
        $query->where(function ($subQuery) use ($nameSearch) {
            $subQuery->where('record_name', 'like', '%' . $nameSearch . '%')
                ->orWhere('display_id', 'like', '%' . $nameSearch . '%');
        });
    }

    if ($usernameSearch !== '') {
        $query->where('user_name', 'like', '%' . $usernameSearch . '%');
    }

    if ($datetimeSearch !== '') {
        $query->where('created_at', 'like', '%' . $datetimeSearch . '%');
    }

    if ($actionSearch !== '') {
        $query->where('action', 'like', '%' . $actionSearch . '%');
    }

    if ($moduleSearch !== '' && !$isProductAudit) {
        $query->where('module', 'like', '%' . $moduleSearch . '%');
    }

    $total = (clone $query)->count();
    $lastPage = max(1, (int) ceil($total / $perPage));
    $page = min($page, $lastPage);

    $rows = $query
        ->orderByDesc('created_at')
        ->orderByDesc('id')
        ->forPage($page, $perPage)
        ->get();

    $items = $rows->map(function ($row) use ($isProductAudit) {
        $formattedDatetime = null;

        if (!empty($row->created_at)) {
            try {
                $formattedDatetime = \Carbon\Carbon::parse($row->created_at)->format('Y-m-d h:i A');
            } catch (\Throwable $e) {
                $formattedDatetime = (string) $row->created_at;
            }
        }

        $auditData = null;
        $productCode = null;

        if ($isProductAudit) {
            $decodedAuditData = json_decode((string) ($row->audit_data ?? ''), true);
            $auditData = is_array($decodedAuditData) ? $decodedAuditData : [];

            $afterSnapshot = is_array($auditData['after'] ?? null) ? $auditData['after'] : [];
            $beforeSnapshot = is_array($auditData['before'] ?? null) ? $auditData['before'] : [];
            $productCode = trim((string) ($row->display_id ?? ''));

            if ($productCode === '') {
                $productCode = trim((string) (
                    $afterSnapshot['product_code']
                    ?? $beforeSnapshot['product_code']
                    ?? $row->record_name
                    ?? ''
                ));
            }
        }

        return [
            'id' => $row->id,
            'name' => $isProductAudit ? ($productCode ?: $row->record_name) : $row->record_name,
            'username' => $row->user_name,
            'datetime' => $formattedDatetime,
            'action' => $row->action,
            'module' => $row->module,
            'display_id' => $row->display_id,
            'product_code' => $isProductAudit ? $productCode : null,
            'audit_data' => $isProductAudit ? $auditData : null,
        ];
    })->values();

    $from = $total > 0 ? (($page - 1) * $perPage) + 1 : 0;
    $to = $total > 0 ? min($page * $perPage, $total) : 0;

    return response()->json([
        'success' => true,
        'items' => $items,
        'page' => $page,
        'last_page' => $lastPage,
        'total' => $total,
        'from' => $from,
        'to' => $to,
        'per_page' => $perPage,
        'auto_purge' => $auditPurgeState,
    ]);
})->name('admin.audit-trail.data');

