Route::get('/admin/masterlist/product', function () {
    $user = session('user');
    if (!$user) return redirect('/login');

    $stats = Cache::remember('admin_product_master_stats_v4', now()->addSeconds(30), function () {
        $row = DB::connection('masterlist')->selectOne("
            SELECT
                COUNT(*) as total,
                SUM(CASE WHEN status = 'Newly' THEN 1 ELSE 0 END) as newly,
                SUM(CASE WHEN COALESCE(on_hand, 0) < 20 THEN 1 ELSE 0 END) as low
            FROM products
        ");

        return [
            'total' => (int) ($row->total ?? 0),
            'newly' => (int) ($row->newly ?? 0),
            'low' => (int) ($row->low ?? 0),
        ];
    });

    return view('Admin.master_list.Product_Master-list', [
        'user' => $user,
        'total_products' => $stats['total'],
        'newly_added' => $stats['newly'],
        'low_stock' => $stats['low'],
    ]);
})->name('admin.prod-master');

