Route::get('/admin/masterlist/online-product-config/dashboard-counts', function () {
    $user = session('user');
    if (!$user) return response()->json(['success' => false, 'error' => 'Unauthorized'], 403);

    $masterlist = DB::connection('masterlist');
    $onlineProducts = $masterlist->table('online_products');
    $convertedProducts = (clone $onlineProducts)->whereNotNull('product_id')->count();
    $onlineProductTotal = (clone $onlineProducts)->count();
    $onlineProductSource = 'database';

    $service = new \App\Services\ShopeeService();
    if ($service->isReady()) {
        $shopeeResult = $service->searchProducts(1, 1);
        if (($shopeeResult['success'] ?? false) === true) {
            $onlineProductTotal = (int) ($shopeeResult['total'] ?? 0);
            $onlineProductSource = 'shopee';
        }
    }

    $counts = [
        'system_products' => $masterlist->table('products')->count(),
        'online_products' => $onlineProductTotal,
        'total_converted_products' => $convertedProducts,
        'online_not_yet_converted_products' => max(0, $onlineProductTotal - $convertedProducts),
    ];

    return response()->json([
        'success' => true,
        'counts' => $counts,
        'source' => $onlineProductSource,
    ]);
})->name('admin.prod-online-config.dashboard-counts');

if (!function_exists('hatdogOnlineProductConvertedResponse')) {
    function hatdogOnlineProductConvertedResponse(Request $request)
    {
        $search = trim((string) $request->query('search', ''));
        $filters = $request->query('filters', []);
        $filters = is_array($filters) ? $filters : [];
        $page = max(1, (int) $request->query('page', 1));
        $perPage = max(1, min(100, (int) $request->query('per_page', 20)));

        $query = DB::connection('masterlist')
            ->table('online_products as op')
            ->join('products as p', 'op.product_id', '=', 'p.id')
            ->whereNotNull('op.product_id')
            ->select([
                'p.id as product_id',
                'p.product_code as system_product_code',
                'p.description as system_product_name',
                'p.part_number as system_part_number',
                'p.price_online as system_price',
                'op.id as online_product_id',
                'op.name as online_product_name',
                'op.category as online_category',
                'op.product_code as online_product_code',
                'op.price as online_price',
            ])
            ->orderByDesc('op.updated_at')
            ->orderByDesc('op.id');

        if ($search !== '') {
            $query->where(function ($q) use ($search) {
                $q->where('p.description', 'like', "%{$search}%")
                    ->orWhere('p.product_code', 'like', "%{$search}%")
                    ->orWhere('p.part_number', 'like', "%{$search}%")
                    ->orWhere('p.price_online', 'like', "%{$search}%")
                    ->orWhere('op.name', 'like', "%{$search}%")
                    ->orWhere('op.category', 'like', "%{$search}%");
            });
        }

        $filterColumns = [
            'system_name' => ['p.description', 'p.product_code'],
            'system_part_number' => ['p.part_number'],
            'system_price' => ['p.price_online'],
            'online_name' => ['op.name'],
            'online_category' => ['op.category'],
            'online_price' => ['op.price'],
        ];
        foreach ($filterColumns as $filterKey => $columns) {
            $value = trim((string) ($filters[$filterKey] ?? ''));
            if ($value === '') continue;
            $query->where(function ($q) use ($columns, $value) {
                foreach ($columns as $column) {
                    $q->orWhere($column, 'like', "%{$value}%");
                }
            });
        }

        $total = (clone $query)->count();
        $rows = $query->skip(($page - 1) * $perPage)->take($perPage)->get();
        $converted = $rows->map(function ($row) {
            $systemName = trim((string) ($row->system_product_name ?? ''));

            return [
                'system' => [
                    'id' => $row->product_id,
                    'name' => $systemName !== '' ? $systemName : ($row->system_product_code ?? '-'),
                    'part_number' => $row->system_part_number ?? '-',
                    'price' => $row->system_price ?? 0,
                    'product_code' => $row->system_product_code ?? '',
                ],
                'online' => [
                    'id' => $row->online_product_id,
                    'product_id' => $row->product_id,
                    'name' => $row->online_product_name ?? '-',
                    'category' => $row->online_category ?? '-',
                    'product_code' => $row->online_product_code ?? '-',
                    'price' => $row->online_price ?? 0,
                ],
            ];
        })->values();

        return response()->json([
            'success' => true,
            'converted' => $converted,
            'total' => $total,
            'per_page' => $perPage,
            'current_page' => $page,
            'last_page' => max(1, (int) ceil($total / $perPage)),
        ]);
    }
}

if (!function_exists('hatdogNormalizeShopeeOnlineProducts')) {
    function hatdogNormalizeShopeeOnlineProducts(array $products): array
    {
        return collect($products)->map(function ($product) {
            $product = (array) $product;
            $itemId = $product['id'] ?? $product['item_id'] ?? null;
            $productCode = trim((string) ($product['product_code'] ?? ''));
            if ($productCode === '' && $itemId) {
                $productCode = 'SHOPEE-' . $itemId;
            }
            if ($productCode === '') {
                $productCode = trim((string) ($product['sku'] ?? ''));
            }

            $category = trim((string) ($product['category'] ?? ''));
            if ($category === '' && !empty($product['category_id'])) {
                $category = 'Category #' . $product['category_id'];
            }

            return array_merge($product, [
                'id' => $itemId,
                'product_code' => $productCode,
                'sku' => $product['sku'] ?? $productCode,
                'name' => $product['name'] ?? $product['item_name'] ?? $productCode,
                'description' => $product['description'] ?? '',
                'category' => $category,
                'price' => $product['price'] ?? 0,
                'source' => 'shopee',
            ]);
        })->filter(fn ($product) => !empty($product['id']))->values()->all();
    }
}

if (!function_exists('hatdogLinkedOnlineProductCodes')) {
    function hatdogLinkedOnlineProductCodes()
    {
        return DB::connection('masterlist')
            ->table('online_products')
            ->whereNotNull('product_id')
            ->pluck('product_code')
            ->filter()
            ->map(fn ($code) => strtoupper(trim((string) $code)))
            ->values();
    }
}

if (!function_exists('hatdogSyncLinkedOnlineProductPrice')) {
    function hatdogSyncLinkedOnlineProductPrice(\App\Models\OnlineProduct $onlineProduct): ?\App\Models\Product
    {
        if (empty($onlineProduct->product_id)) {
            return null;
        }

        if (!is_numeric($onlineProduct->price)) {
            throw new \RuntimeException('Online product price is not numeric.');
        }

        $product = \App\Models\Product::whereKey((int) $onlineProduct->product_id)
            ->lockForUpdate()
            ->first();

        if (!$product) {
            throw new \RuntimeException('Linked system product was not found.');
        }

        $product->price_online = (float) $onlineProduct->price;
        $product->save();

        return $product->fresh();
    }
}

if (!function_exists('hatdogSyncShopeeProductsIntoOnlineConfig')) {
    function hatdogSyncShopeeProductsIntoOnlineConfig($shopeeProducts): array
    {
        return app(\App\Services\ShopeePriceSyncService::class)->syncProducts($shopeeProducts);
    }
}

Route::get('/admin/masterlist/online-product-config/converted-products', function (Request $request) {
