})->name('admin.prod-online-config.converted-products');

// Online Product Configuration — Fetch Converted Pairs
Route::get('/admin/masterlist/online-product-config/fetch-converted', function (Request $request) {
    $user = session('user');
    if (!$user) return response()->json(['success' => false, 'error' => 'Unauthorized'], 403);
    return hatdogOnlineProductConvertedResponse($request);

    $search = $request->query('search', '');
    $filters = $request->query('filters', []);
    $filters = is_array($filters) ? $filters : [];
    $page = max(1, (int) $request->query('page', 1));
    $perPage = max(1, min(100, (int) $request->query('per_page', 20)));
    $onlineProducts = \App\Models\OnlineProduct::orderBy('created_at', 'desc')->get();
    $converted = [];
    foreach ($onlineProducts as $op) {
        $system = null;
        if (!empty($op->product_id)) {
            $system = \App\Models\Product::find($op->product_id);
        }
        if (!$system) {
            $system = \App\Models\Product::where('product_code', $op->product_code)
                ->orWhere('part_number', $op->sku)
                ->first();
        }
        if (!$system && !$op->is_converted) continue;
        $row = [
            'system' => [
                'id' => $system->id ?? null,
                'name' => $system->description ?? $system->product_code ?? '-',
                'part_number' => $system->part_number ?? '-',
                'price' => $system->price_online ?? $system->selling_price ?? 0,
                'online_price' => $system->price_online ?? null,
                'product_code' => $system->product_code ?? '',
            ],
            'online' => [
                'id' => $op->id,
                'product_id' => $op->product_id ?? null,
                'name' => $op->name ?? '-',
                'sku' => $op->sku ?? $op->product_code ?? '-',
                'product_code' => $op->product_code ?? '-',
                'price' => $op->price ?? 0,
            ],
        ];
        if ($search) {
            $searchable = implode(' ', [
                $row['system']['name'],
                $row['system']['part_number'],
                $row['system']['price'],
                $row['system']['online_price'],
                $row['system']['product_code'],
                $row['online']['name'],
                $row['online']['sku'],
                $row['online']['product_code'],
                $row['online']['price'],
            ]);
            if (stripos($searchable, $search) === false) continue;
        }
        $columnValues = [
            'system_name' => $row['system']['name'],
            'system_part_number' => $row['system']['part_number'],
            'system_price' => $row['system']['price'],
            'online_name' => $row['online']['name'],
            'online_sku' => $row['online']['sku'],
            'online_price' => $row['online']['price'],
        ];
        foreach ($filters as $key => $value) {
            $value = trim((string) $value);
            if ($value === '' || !array_key_exists($key, $columnValues)) continue;
            if (stripos((string) $columnValues[$key], $value) === false) {
                continue 2;
            }
        }
        $converted[] = $row;
    }
    $total = count($converted);
    $converted = array_slice($converted, ($page - 1) * $perPage, $perPage);
    return response()->json([
        'success' => true,
        'converted' => $converted,
        'total' => $total,
        'per_page' => $perPage,
        'current_page' => $page,
        'last_page' => max(1, (int) ceil($total / $perPage)),
    ]);
})->name('admin.prod-online-config.fetch-converted');

// Search Shopee products via API
Route::get('/admin/masterlist/online-product-config/search-shopee', function (Request $request) {
    $user = session('user');
    if (!$user) return response()->json(['success' => false, 'error' => 'Unauthorized'], 403);
    $keyword = trim($request->query('search', ''));
    $page = max(1, (int) $request->query('page', 1));
    $perPage = max(1, min(100, (int) $request->query('per_page', 10)));
    $service = new \App\Services\ShopeeService();
    if (!$service->isReady()) {
        $missing = $service->getMissingCredentials();
        return response()->json([
            'success' => false,
            'error' => 'Shopee API not configured',
            'message' => 'Missing: ' . implode(', ', $missing) . '. Please set these in your .env file or complete the OAuth flow at /shopee/redirect.',
            'products' => [], 'total' => 0, 'per_page' => $perPage, 'current_page' => $page, 'last_page' => 1,
        ]);
    }
    if ($keyword !== '') {
        $offset = (string) $request->query('offset', '');
        $result = $service->searchByKeyword($keyword, $perPage, $offset);
        $result['current_page'] = $page;
        $result['last_page'] = max(1, (int) ceil($result['total'] / $perPage));
    } else {
        $result = $service->searchProducts($page, $perPage);
    }
    return response()->json($result);
})->name('admin.prod-online-config.search-shopee');

Route::post('/admin/masterlist/online-product-config/online-product/{id}/price', function (Request $request, $id) {
    $user = session('user');
    if (!$user) return response()->json(['success' => false, 'message' => 'Unauthorized'], 403);

    $validated = Validator::make($request->all(), [
        'price' => ['required', 'numeric', 'min:0'],
    ]);
    if ($validated->fails()) {
        return response()->json([
            'success' => false,
            'message' => 'Invalid online product price.',
            'errors' => $validated->errors(),
        ], 422);
    }

    try {
        $result = DB::connection('masterlist')->transaction(function () use ($id, $request) {
            $onlineProduct = \App\Models\OnlineProduct::whereKey((int) $id)
                ->lockForUpdate()
                ->first();

            if (!$onlineProduct) {
                throw new \RuntimeException('Online product was not found.');
            }

            $onlineProduct->price = (float) $request->input('price');
            $onlineProduct->save();

            $linkedProduct = hatdogSyncLinkedOnlineProductPrice($onlineProduct);

            return [
                'online_product' => $onlineProduct->fresh(),
                'linked_system_product' => $linkedProduct,
                'synced' => $linkedProduct !== null,
            ];
        });

        return response()->json([
            'success' => true,
            'message' => $result['synced']
                ? 'Online product price updated and linked system product synced.'
                : 'Online product price updated.',
            'online_product' => $result['online_product'],
            'linked_system_product' => $result['linked_system_product'],
            'synced' => $result['synced'],
            'mapping_table' => 'online_products.product_id',
            'online_price_field' => 'online_products.price',
            'system_price_field' => 'products.price_online',
        ]);
    } catch (\RuntimeException $e) {
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    } catch (\Throwable $e) {
        Log::error('Online product price update failed', [
            'online_product_id' => $id,
            'error' => $e->getMessage(),
        ]);
        return response()->json(['success' => false, 'message' => 'Price update failed. Please try again.'], 500);
    }
})->name('admin.prod-online-config.online-product.price');

Route::get('/admin/masterlist/online-product-config/shopee-sync-status', function () {
    $user = session('user');
    if (!$user) return response()->json(['success' => false, 'message' => 'Unauthorized'], 403);

    $syncService = app(\App\Services\ShopeePriceSyncService::class);
    $status = $syncService->latestStatus();
    $fallbackStatus = $syncService->latestFallbackStatus();
    $webhookStatus = $syncService->latestWebhookStatus();
    $now = \Carbon\Carbon::now('Asia/Manila');
    $nextSyncAt = null;
    $secondsUntilStale = 0;
    $intervalMinutes = \App\Services\ShopeePriceSyncService::FALLBACK_INTERVAL_MINUTES;
    $intervalSeconds = $intervalMinutes * 60;

    if (!empty($fallbackStatus['finished_at'])) {
        try {
            $nextSyncAt = \Carbon\Carbon::parse($fallbackStatus['finished_at'], 'Asia/Manila')->addMinutes($intervalMinutes);
            $secondsUntilStale = max(0, $now->diffInSeconds($nextSyncAt, false));
        } catch (\Throwable $e) {
            $nextSyncAt = null;
            $secondsUntilStale = 0;
        }
    }

    return response()->json([
        'success' => true,
        'status' => $status,
        'webhook' => $webhookStatus,
        'fallback' => $fallbackStatus,
        'is_stale' => $syncService->isStatusOlderThanMinutes($intervalMinutes, 'fallback'),
        'sync_interval_seconds' => $intervalSeconds,
        'next_sync_at' => $nextSyncAt ? $nextSyncAt->format('Y-m-d H:i:s') : null,
        'seconds_until_stale' => $secondsUntilStale,
    ]);
})->name('admin.prod-online-config.shopee-sync-status');

Route::post('/admin/masterlist/online-product-config/shopee-sync-auto', function () {
    $user = session('user');
    if (!$user) return response()->json(['success' => false, 'message' => 'Unauthorized'], 403);
    @set_time_limit(0);

    $syncService = app(\App\Services\ShopeePriceSyncService::class);
    $intervalMinutes = \App\Services\ShopeePriceSyncService::FALLBACK_INTERVAL_MINUTES;
    if (!$syncService->isStatusOlderThanMinutes($intervalMinutes, 'fallback')) {
        return response()->json([
            'success' => true,
            'message' => 'Shopee price sync is fresh.',
            'status' => $syncService->latestStatus(),
            'ran' => false,
        ]);
    }

    $lock = Cache::lock('shopee-price-sync', 600);
    if (!$lock->get()) {
        return response()->json([
            'success' => true,
            'message' => 'Shopee price sync is already running.',
            'status' => $syncService->latestStatus(),
            'ran' => false,
            'locked' => true,
        ]);
    }

    try {
        $result = $syncService->syncFromShopee(50);

        return response()->json([
            'success' => (bool) ($result['success'] ?? false),
            'message' => $result['message'] ?? 'Shopee price sync finished.',
            'status' => $result,
            'ran' => true,
        ], ($result['success'] ?? false) ? 200 : 502);
    } finally {
        optional($lock)->release();
    }
})->name('admin.prod-online-config.shopee-sync-auto');

Route::get('/admin/masterlist/online-product-config/fetch-online', function (Request $request) {
    $user = session('user');
    if (!$user) return response()->json(['success' => false, 'error' => 'Unauthorized'], 403);
    $search = trim((string) $request->query('search', ''));
    $filters = $request->query('filters', []);
    $filters = is_array($filters) ? $filters : [];
    $page = max(1, (int) $request->query('page', 1));
    $perPage = max(1, min(100, (int) $request->query('per_page', 20)));

    $service = new \App\Services\ShopeeService();
    if (!$service->isReady()) {
        $missing = $service->getMissingCredentials();
        return response()->json([
            'success' => false,
            'source' => 'shopee',
            'error' => 'Shopee API not configured',
            'message' => 'Missing: ' . implode(', ', $missing) . '. Please set these in your .env file or complete the OAuth flow at /shopee/redirect.',
            'products' => [],
            'total' => 0,
            'per_page' => $perPage,
            'current_page' => $page,
            'last_page' => 1,
        ], 422);
    }

    $keyword = $search;
    $nameFilter = trim((string) ($filters['name'] ?? ''));
    if ($keyword === '' && $nameFilter !== '') {
        $keyword = $nameFilter;
    }

    if ($keyword !== '') {
        $offset = (string) $request->query('offset', '');
        if ($offset === '' && $page > 1) {
            $offset = (string) (($page - 1) * $perPage);
        }
        $result = $service->searchByKeyword($keyword, $perPage, $offset);
        $result['current_page'] = $page;
        $result['last_page'] = max(1, (int) ceil(($result['total'] ?? 0) / $perPage));
    } else {
        $result = $service->searchProducts($page, $perPage);
    }

    if (($result['success'] ?? false) !== true) {
        return response()->json([
            'success' => false,
            'source' => 'shopee',
            'error' => $result['error'] ?? 'Shopee API request failed',
            'message' => $result['error'] ?? 'Shopee API request failed',
            'products' => [],
            'total' => 0,
            'per_page' => $perPage,
            'current_page' => $page,
            'last_page' => 1,
        ], 502);
    }

    $linkedCodes = hatdogLinkedOnlineProductCodes();
    $linkedCount = $linkedCodes->count();
    $products = collect(hatdogNormalizeShopeeOnlineProducts($result['products'] ?? []))
        ->reject(function ($product) use ($linkedCodes) {
            $code = strtoupper(trim((string) ($product['product_code'] ?? '')));
            return $code !== '' && $linkedCodes->contains($code);
        });

    $categoryFilter = trim((string) ($filters['category'] ?? ''));
    if ($categoryFilter !== '') {
        $products = $products->filter(fn ($product) => stripos((string) ($product['category'] ?? ''), $categoryFilter) !== false);
    }

    $priceFilter = trim((string) ($filters['price'] ?? ''));
    if ($priceFilter !== '') {
        $products = $products->filter(fn ($product) => stripos((string) ($product['price'] ?? ''), $priceFilter) !== false);
    }

    $total = max(0, (int) ($result['total'] ?? 0) - $linkedCount);

    return response()->json([
        'success' => true,
        'source' => 'shopee',
        'products' => $products->values(),
        'total' => $total,
        'per_page' => $perPage,
        'current_page' => $page,
        'last_page' => max(1, (int) ceil($total / $perPage)),
        'next_offset' => (string) ($result['next_offset'] ?? ''),
    ]);
})->name('admin.prod-online-config.fetch-online');

Route::get('/admin/masterlist/online-product-config/fetch-system', function (Request $request) {
    $user = session('user');
    if (!$user) return response()->json(['success' => false, 'error' => 'Unauthorized'], 403);
    $search = $request->query('search', '');
    $filters = $request->query('filters', []);
    $filters = is_array($filters) ? $filters : [];
    $page = max(1, (int) $request->query('page', 1));
    $perPage = max(1, min(100, (int) $request->query('per_page', 20)));
    $query = \App\Models\Product::query()
        ->select('products.*')
        ->orderBy('created_at', 'desc');
    if ($search) {
        $query->where(function ($q) use ($search) {
            $q->where('product_code', 'like', "%{$search}%")
              ->orWhere('part_number', 'like', "%{$search}%")
              ->orWhere('description', 'like', "%{$search}%")
              ->orWhere('application', 'like', "%{$search}%")
              ->orWhere('price_online', 'like', "%{$search}%");
        });
    }
    $filterColumns = [
        'product_code' => 'product_code',
        'part_number' => 'part_number',
        'description' => 'description',
        'application' => 'application',
        'price_online' => 'price_online',
    ];
    foreach ($filterColumns as $filterKey => $column) {
        $value = trim((string) ($filters[$filterKey] ?? ''));
        if ($value !== '') {
            $query->where($column, 'like', "%{$value}%");
        }
    }
    $total = $query->count();
    $products = $query->skip(($page - 1) * $perPage)->take($perPage)->get();
    $latestBalances = \App\Services\ProductStockSyncService::latestBalances($products->pluck('id'));
    $products->each(function ($product) use ($latestBalances) {
        $product->latest_on_hand = (int) ($latestBalances[(int) $product->id] ?? 0);
    });
    return response()->json([
        'success' => true,
        'products' => $products,
        'total' => $total,
        'per_page' => $perPage,
        'current_page' => $page,
        'last_page' => max(1, (int) ceil($total / $perPage)),
    ]);
})->name('admin.prod-online-config.fetch-system');

Route::post('/admin/masterlist/online-product-config/confirm-convert', function (Request $request) {
    $user = session('user');
    if (!$user) return response()->json(['success' => false, 'message' => 'Unauthorized'], 403);

    $validated = Validator::make($request->all(), [
        'product_id' => ['required', 'integer'],
        'online_product_id' => ['required', 'integer'],
        'online_product' => ['nullable', 'array'],
    ]);
    if ($validated->fails()) {
        return response()->json([
            'success' => false,
            'message' => 'Invalid convert request.',
            'errors' => $validated->errors(),
        ], 422);
    }

    try {
        $result = DB::connection('masterlist')->transaction(function () use ($request) {
            $product = \App\Models\Product::whereKey((int) $request->input('product_id'))->lockForUpdate()->first();
            if (!$product) {
                throw new \RuntimeException('Selected system product was not found.');
            }

            $onlinePayload = (array) $request->input('online_product', []);
            $onlineProductId = (int) $request->input('online_product_id');
            $onlineProductCode = trim((string) (
                $onlinePayload['product_code']
                ?? $onlinePayload['item_code']
                ?? (!empty($onlinePayload['id']) ? 'SHOPEE-' . $onlinePayload['id'] : '')
            ));
            $onlineProductSource = (string) ($onlinePayload['source'] ?? '');
            $onlineProduct = null;
            if ($onlineProductCode !== '') {
                $onlineProduct = \App\Models\OnlineProduct::where('product_code', $onlineProductCode)->lockForUpdate()->first();
            }
            if (!$onlineProduct && $onlineProductSource !== 'shopee') {
                $onlineProduct = \App\Models\OnlineProduct::whereKey($onlineProductId)->lockForUpdate()->first();
            }
            if (!$onlineProduct) {
                if ($onlineProductCode === '') {
                    throw new \RuntimeException('Selected online product was not found.');
                }
                $onlineProduct = new \App\Models\OnlineProduct();
                $onlineProduct->product_code = $onlineProductCode;
            }

            $payloadPrice = $onlinePayload['price'] ?? $onlinePayload['online_price'] ?? $onlinePayload['shopee_price'] ?? null;
            if ($payloadPrice !== null) {
                $onlineProduct->price = $payloadPrice;
            }
            if (!empty($onlinePayload)) {
                $onlineProduct->name = (string) ($onlinePayload['name'] ?? $onlineProduct->name ?? $onlineProductCode);
                $onlineProduct->description = (string) ($onlinePayload['description'] ?? $onlineProduct->description ?? $onlineProduct->name ?? '');
                $onlineProduct->sku = (string) ($onlinePayload['sku'] ?? $onlinePayload['product_code'] ?? $onlineProduct->sku ?? $onlineProductCode);
                $onlineProduct->category = (string) ($onlinePayload['category'] ?? (!empty($onlinePayload['category_id']) ? 'Category #' . $onlinePayload['category_id'] : ($onlineProduct->category ?? '')));
                $onlineProduct->image_url = (string) ($onlinePayload['image_url'] ?? $onlineProduct->image_url ?? '');
            }

            if (!is_null($onlineProduct->product_id) && (int) $onlineProduct->product_id !== (int) $product->id) {
                throw new \RuntimeException('This online product is already linked to another system product.');
            }

            if (!is_numeric($onlineProduct->price)) {
                throw new \RuntimeException('Selected online product price is not numeric.');
            }

            $onlinePrice = (float) $onlineProduct->price;
            $onlineProduct->product_id = $product->id;
            $onlineProduct->is_converted = true;
            $onlineProduct->save();

            $product = hatdogSyncLinkedOnlineProductPrice($onlineProduct);

            return [
                'product' => $product,
                'online_product' => $onlineProduct->fresh(),
                'online_price' => $onlinePrice,
            ];
        });

        return response()->json([
            'success' => true,
            'message' => 'Products linked and online price synced successfully.',
            'data' => $result,
        ]);
    } catch (\RuntimeException $e) {
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    } catch (\Throwable $e) {
        Log::error('Online product confirm convert failed', [
            'product_id' => $request->input('product_id'),
            'online_product_id' => $request->input('online_product_id'),
            'error' => $e->getMessage(),
        ]);
        return response()->json(['success' => false, 'message' => 'Conversion failed. Please try again.'], 500);
    }
})->name('admin.prod-online-config.confirm-convert');

