// Product Master List Data (Paginated AJAX)
Route::get('/admin/masterlist/product/data', function (Request $request) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

    $tab = $request->query('tab', 'all');
    $perPage = (int) $request->query('perPage', 50);
    $search = $request->query('search', []);
    $filter = $request->query('filter', []);
    $sortBy = $request->query('sort_by');
    $sortDirection = strtolower($request->query('sort_direction', 'asc')) === 'desc' ? 'desc' : 'asc';

    $query = \App\Models\Product::query()
        ->select('products.*');

    // Tab filtering
    if ($tab === 'newly') {
        $query->where('status', 'Newly');
    } elseif ($tab === 'low') {
        $query->whereNotNull('Re_order_level')
            ->whereColumn('on_hand', '<=', 'Re_order_level');
    }

    // Column search filters
    $searchMap = [
        'productCode' => 'product_code',
        'partNumber' => 'part_number',
        'description' => 'description',
        'application' => 'application',
        'specification' => 'specification',
        'position' => 'position',
        'category' => 'category',
        'onHand' => 'on_hand',
        'restockLevel' => 'Re_order_level',
        'sellingPrice' => 'selling_price',
        'priceOnline' => 'price_online',
        'dateAdded' => 'date_added',
    ];

    $escapeLike = function ($value) {
        return str_replace(['\\', '%', '_'], ['\\\\', '\\%', '\\_'], (string) $value);
    };

    foreach ($searchMap as $jsCol => $dbCol) {
        if (!empty($search[$jsCol])) {
            $term = $escapeLike($search[$jsCol]);
            if ($jsCol === 'onHand') {
                $query->whereRaw('CAST(on_hand AS CHAR) like ?', ['%' . $term . '%']);
            } elseif ($jsCol === 'restockLevel') {
                $query->whereRaw('CAST(Re_order_level AS CHAR) like ?', ['%' . $term . '%']);
            } elseif ($jsCol === 'priceOnline') {
                $query->whereRaw('price_online LIKE ?', ['%' . $term . '%']);
            } else {
                $query->where($dbCol, 'like', '%' . $term . '%');
            }
        }
    }

    // Modal filters
    if (!empty($filter['category']) && $filter['category'] !== 'all') {
        $query->where('category', $filter['category']);
    }
    if (!empty($filter['application']) && $filter['application'] !== 'all') {
        $query->where('application', 'like', '%' . $escapeLike($filter['application']) . '%');
    }
    if (!empty($filter['status']) && $filter['status'] !== 'all') {
        $query->where('status', $filter['status']);
    }

    // Dynamic column sorting
    $sortableColumns = [
        'productCode' => 'product_code',
        'description' => 'description',
        'application' => 'application',
        'brand' => 'category',
        'partNumber' => 'part_number',
        'position' => 'position',
        'specification' => 'specification',
        'unit' => 'unit',
        'priceOnline' => 'price_online',
        'sellingPrice' => 'selling_price',
        'onHand' => 'on_hand',
        'restockLevel' => 'Re_order_level',
    ];

    if ($sortBy && isset($sortableColumns[$sortBy])) {
        $query->orderBy($sortableColumns[$sortBy], $sortDirection);
    } else {
        $query->orderBy('created_at', 'desc');
    }

    $pagination = $query->paginate($perPage);

    $productIds = collect($pagination->items())->pluck('id')->filter();

    // Load price codes for all products in one batch
    $priceCodeMap = collect();
    if ($productIds->isNotEmpty()) {
        try {
            $priceCodeMap = \App\Models\ProductPriceCode::whereIn('product_id', $productIds)
                ->orderBy('sort_order')
                ->get()
                ->groupBy('product_id')
                ->map(fn ($rows) => $rows->map(fn ($r) => [
                    'price_code' => $r->price_code,
                    'selling_price' => (float) $r->selling_price,
                ])->values()->toArray());
        } catch (\Throwable $e) {
            $priceCodeMap = collect();
        }
    }

    $pagination->getCollection()->transform(function ($product) use ($priceCodeMap) {
        $product->on_hand = (int) ($product->on_hand ?? 0);
        $product->restock_level = $product->Re_order_level;
        $product->price_codes = $priceCodeMap->get($product->id, []);

        // Sanitize text string fields to prevent JSON encoding errors (skip binary/image fields)
        foreach ($product->getAttributes() as $field => $value) {
            if ($field === 'Product_Picture' || $field === 'images') continue;
            if (is_string($value)) {
                $product->$field = iconv('UTF-8', 'UTF-8//IGNORE', $value);
            }
        }

        // Normalize product image: handle raw binary, JSON arrays, and file paths
        if (!empty($product->Product_Picture)) {
            $pic = $product->Product_Picture;
            $firstByte = $pic[0];
            // 1) Raw PNG binary (starts with PNG magic bytes \x89PNG)
            if (ord($firstByte) === 137 && isset($pic[3]) && ord($pic[1]) === 80 && ord($pic[2]) === 78 && ord($pic[3]) === 71) {
                $product->Product_Picture = 'data:image/png;base64,' . base64_encode($pic);
            }
            // 2) Raw JPG binary (starts with \xFF\xD8\xFF)
            elseif (ord($firstByte) === 255 && isset($pic[2]) && ord($pic[1]) === 216 && ord($pic[2]) === 255) {
                $product->Product_Picture = 'data:image/jpeg;base64,' . base64_encode($pic);
            }
            // 3) JSON array/object of image URLs
            elseif ($firstByte === '[' || $firstByte === '{') {
                $decoded = json_decode($pic, true);
                if (empty($decoded)) {
                    $product->Product_Picture = null;
                } else {
                    $product->Product_Picture = $decoded;
                }
            }
            // 4) Already a data URL — pass through
            elseif (str_starts_with($pic, 'data:image/')) {
                // keep as-is
            }
            // 5) HTTP/HTTPS URL — pass through
            elseif (str_starts_with($pic, 'http://') || str_starts_with($pic, 'https://')) {
                // keep as-is
            }
            // 6) File path — convert to public URL via asset()
            elseif (preg_match('/\.(png|jpg|jpeg|webp|gif|bmp|svg)(\?.*)?$/i', $pic)) {
                $product->Product_Picture = url($pic);
            }
            // 7) Unknown format — set to null
            else {
                $product->Product_Picture = null;
            }
        } else {
            $product->Product_Picture = null;
        }

        return $product;
    });

    // Keep the dashboard counters away from the paginated product query.
    // products.on_hand is maintained from the ledger and keeps this page fast.
    $stats = Cache::remember('admin_product_master_stats_v4', now()->addSeconds(30), function () {
        $row = DB::connection('masterlist')->selectOne("
            SELECT
                COUNT(*) as total,
                SUM(CASE WHEN p.status = 'Newly' THEN 1 ELSE 0 END) as newly,
                SUM(CASE WHEN p.Re_order_level IS NOT NULL AND COALESCE(p.on_hand, 0) <= p.Re_order_level THEN 1 ELSE 0 END) as low
            FROM products p
        ");

        return [
            'total' => (int) ($row->total ?? 0),
            'newly' => (int) ($row->newly ?? 0),
            'low' => (int) ($row->low ?? 0),
        ];
    });

    $totalAll = (int)($stats['total'] ?? 0);
    $totalNewly = (int)($stats['newly'] ?? 0);
    $totalLow = (int)($stats['low'] ?? 0);

    return response()->json([
        'pagination' => $pagination,
        'stats' => [
            'total' => $totalAll,
            'newly' => $totalNewly,
            'low' => $totalLow,
        ],
    ]);
})->name('admin.prod-master.data');

// Create Product
Route::post('/admin/masterlist/product/create', function (Request $request) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

    try {
        $validated = $request->validate([
            'product_code' => 'required|string|unique:masterlist.products,product_code',
            'pricelist_code' => 'nullable|string|max:255',
            'part_number' => 'required|string',
            'specification' => 'nullable|string',
            'description' => 'nullable|string',
            'unit' => 'nullable|string|max:50',
            'application' => 'nullable|string',
            'position' => 'nullable|string',
            'category' => 'required|string',
            'selling_price' => 'required|numeric|min:0',
            'price_online' => 'nullable|numeric|min:0',
            'cost' => 'nullable|numeric|min:0',
            'on_hand' => 'nullable|integer|min:0',
            'Re_order_level' => 'nullable|integer|min:0',
            'date_added' => 'nullable|date',
            'status' => 'nullable|string',
            'Product_Picture' => 'nullable|string',
        ]);

        $validated['pricelist_code'] = isset($validated['pricelist_code']) && trim((string) $validated['pricelist_code']) !== ''
            ? trim((string) $validated['pricelist_code'])
            : null;


        $validated['cost'] = $validated['cost'] ?? 0;
        $validated['on_hand'] = $validated['on_hand'] ?? 0;
        $validated['date_added'] = $validated['date_added'] ?? now('Asia/Manila')->toDateString();
        $validated['status'] = $validated['status'] ?? 'Newly';
        $validated['specification'] = isset($validated['specification']) && trim((string) $validated['specification']) !== ''
            ? trim((string) $validated['specification'])
            : null;
        $validated['price_online'] = $validated['price_online'] ?? 0;

        $product = \App\Models\Product::create($validated);

        return response()->json(['success' => true, 'message' => 'Product added successfully', 'product' => $product]);
    } catch (\Exception $e) {
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.prod-master.create');

// Update Product
Route::post('/admin/masterlist/product/update/{id}', function (Request $request, $id) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

    try {
        $product = \App\Models\Product::findOrFail($id);

        $validated = $request->validate([
            'product_code' => 'required|string|unique:masterlist.products,product_code,' . $id,
            'pricelist_code' => 'nullable|string|max:255',
            'part_number' => 'required|string',
            'specification' => 'nullable|string',
            'description' => 'nullable|string',
            'unit' => 'nullable|string|max:50',
            'application' => 'nullable|string',
            'position' => 'nullable|string',
            'category' => 'required|string',
            'selling_price' => 'required|numeric|min:0',
            'price_online' => 'nullable|numeric|min:0',
            'cost' => 'nullable|numeric|min:0',
            'on_hand' => 'nullable|integer|min:0',
            'Re_order_level' => 'nullable|integer|min:0',
            'date_added' => 'nullable|date',
            'status' => 'nullable|string',
            'Product_Picture' => 'nullable|string',
        ]);

        $validated['pricelist_code'] = isset($validated['pricelist_code']) && trim((string) $validated['pricelist_code']) !== ''
            ? trim((string) $validated['pricelist_code'])
            : null;


        $validated['specification'] = isset($validated['specification']) && trim((string) $validated['specification']) !== ''
            ? trim((string) $validated['specification'])
            : null;
        // Product Master inline editor must never directly alter inventory or cost.
        $validated['on_hand'] = (int) ($product->on_hand ?? 0);
        $validated['cost'] = (float) ($product->cost ?? 0);
        $validated['price_online'] = $validated['price_online'] ?? 0;

        $product->update($validated);

        return response()->json(['success' => true, 'message' => 'Product updated successfully', 'product' => $product->refresh()]);
    } catch (\Exception $e) {
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.prod-master.update');

// Delete Product
Route::post('/admin/masterlist/product/delete/{id}', function ($id) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

    try {
        if (is_array($user)) {
            $user = (object) $user;
        }

        if (!Schema::connection('ledger')->hasTable('archived_records')) {
            throw new \Exception('Archive table is missing. Please run the archive migration first.');
        }

        DB::connection('masterlist')->beginTransaction();
        DB::connection('ledger')->beginTransaction();

        $product = \App\Models\Product::query()->lockForUpdate()->findOrFail($id);
        $productData = $product->toArray();
        $deletedBy = $user->name ?? $user->username ?? $user->User_ID ?? 'Admin';
        $displayId = (string) ($product->product_code ?? $product->id);
        $dataName = trim((string) (($product->description ?? '') !== '' ? $product->description : ($product->part_number ?? $product->product_code ?? 'Product')));

        $existingArchive = DB::connection('ledger')
            ->table('archived_records')
            ->where('module', 'product')
            ->whereNull('restored_at')
            ->where('source_connection', 'masterlist')
            ->where('source_table', 'products')
            ->where('source_id', $product->id)
            ->first();

        if ($existingArchive) {
            throw new \Exception('This product is already archived.');
        }

        DB::connection('ledger')->table('archived_records')->insert([
            'module' => 'product',
            'source_connection' => 'masterlist',
            'source_table' => 'products',
            'source_id' => $product->id,
            'display_id' => $displayId,
            'data_name' => $dataName,
            'archived_data' => json_encode($productData, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE),
            'deleted_by' => (string) $deletedBy,
            'deleted_at' => now(),
            'expires_at' => now()->addDays(30),
            'created_at' => now(),
            'updated_at' => now(),
        ]);

        $product->delete();

        DB::connection('ledger')->commit();
        DB::connection('masterlist')->commit();

        return response()->json(['success' => true, 'message' => 'Product archived successfully']);
    } catch (\Exception $e) {
        if (DB::connection('ledger')->transactionLevel() > 0) DB::connection('ledger')->rollBack();
        if (DB::connection('masterlist')->transactionLevel() > 0) DB::connection('masterlist')->rollBack();
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.prod-master.delete');

// Product Ledger
Route::get('/admin/masterlist/product/ledger/{id}', function ($id) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

    try {
        $product = \App\Models\Product::findOrFail($id);

        $ledger = \App\Models\ProductLedger::where('product_id', $id)
            ->orderBy('date', 'desc')
            ->orderBy('created_at', 'desc')
            ->get();

        $ledger = $ledger->map(function ($entry) use ($product) {
            $entry->price_online = (float) ($product->price_online ?? 0);

            return $entry;
        });

        return response()->json([
            'success' => true,
            'ledger' => $ledger,
            'total_in' => $ledger->sum('quantity_in'),
            'total_out' => $ledger->sum('quantity_out'),
        ]);
    } catch (\Exception $e) {
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.prod-master.ledger');

// Update Product Selection for Report
Route::post('/admin/masterlist/product/select', function (Request $request) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

    try {
        $validator = Validator::make($request->all(), [
            'id' => 'required',
            'is_selected' => 'required|boolean'
        ]);

        if ($validator->fails()) {
            return response()->json(['success' => false, 'message' => $validator->errors()->first()], 422);
        }

        $id = $request->input('id');
        $isSelected = (bool) $request->input('is_selected');

        if ($id === 'all') {
            DB::connection('masterlist')->table('products')->update(['is_selected_for_report' => $isSelected]);
        } else {
            $product = \App\Models\Product::findOrFail($id);
            $product->update(['is_selected_for_report' => $isSelected]);
        }

        return response()->json(['success' => true]);
    } catch (\Exception $e) {
        Log::error('Selection Error: ' . $e->getMessage());
        return response()->json(['success' => false, 'message' => 'Failed to update selection: ' . $e->getMessage()], 422);
    }
})->name('admin.prod-master.select');

