// Fetch suppliers with server-side pagination and column search
Route::get('/admin/masterlist/supplier/data', function (Request $request) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

    $filter = $request->query('filter', []);
    $status = $request->query('status', $filter['status'] ?? 'all');
    $type = $request->query('type', $filter['type'] ?? 'all');
    $search = $request->query('search', []);

    $page = (int) $request->query('page', 1);
    $perPageInput = $request->query('perPage', 50);

    $supplierQuery = function () {
        $query = \App\Models\Supplier::query();

        if (Schema::connection('masterlist')->hasColumn('suppliers', 'record_type')) {
            $query->where(function ($query) {
                $query->whereNull('record_type')
                    ->orWhere('record_type', 'supplier');
            });
        }

        return $query;
    };

    $query = $supplierQuery()->orderBy('created_at', 'desc');

    if (in_array($status, ['Active', 'Inactive'], true)) {
        $query->where('status', $status);
    }

    if (in_array($type, ['new', 'newly'], true)) {
        $query->where('created_at', '>=', now()->subMonths(3));
    } elseif ($type === 'old') {
        $query->where('created_at', '<', now()->subMonths(3));
    }

    // Apply column search across ALL data before pagination
    $searchableColumns = ['supplier_code', 'name', 'contact_number', 'contact_person', 'tin', 'address'];
    $generalSearch = $search['general'] ?? '';
    foreach ($searchableColumns as $col) {
        if (!empty($search[$col])) {
            $query->where($col, 'LIKE', '%' . $search[$col] . '%');
        }
    }
    if ($generalSearch !== '') {
        $query->where(function ($q) use ($generalSearch, $searchableColumns) {
            foreach ($searchableColumns as $col) {
                $q->orWhere($col, 'LIKE', '%' . $generalSearch . '%');
            }
        });
    }

    // Get total matching count before pagination
    $totalMatching = $query->count();

    // Unfiltered stats (whole table)
    $stats = [
        'total' => $supplierQuery()->count(),
        'active' => $supplierQuery()->where('status', 'Active')->count(),
    ];

    // If perPage is 'all', return everything without pagination
    if ($perPageInput === 'all') {
        $suppliers = $query->get();
        return response()->json([
            'suppliers' => $suppliers,
            'stats' => $stats,
            'pagination' => [
                'current_page' => 1,
                'last_page' => 1,
                'per_page' => $totalMatching,
                'total' => $totalMatching,
                'from' => $totalMatching > 0 ? 1 : 0,
                'to' => $totalMatching,
            ],
            'filtered_total' => $totalMatching,
            'filters' => [
                'status' => $status,
                'type' => $type,
            ],
        ]);
    }

    $perPage = max(1, (int) $perPageInput);
    $lastPage = max(1, (int) ceil($totalMatching / $perPage));
    $page = max(1, min($page, $lastPage));

    $suppliers = $query->skip(($page - 1) * $perPage)->take($perPage)->get();

    $from = $totalMatching > 0 ? (($page - 1) * $perPage) + 1 : 0;
    $to = min($page * $perPage, $totalMatching);

    return response()->json([
        'suppliers' => $suppliers,
        'stats' => $stats,
        'pagination' => [
            'current_page' => $page,
            'last_page' => $lastPage,
            'per_page' => $perPage,
            'total' => $totalMatching,
            'from' => $from,
            'to' => $to,
        ],
        'filtered_total' => $totalMatching,
        'filters' => [
            'status' => $status,
            'type' => $type,
        ],
    ]);
})->name('admin.supplier-master.data');

