// Create new supplier
Route::post('/admin/masterlist/supplier/create', function (Request $request) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

    try {
        $validated = $request->validate([
            'supplier_code' => 'required|unique:masterlist.suppliers,supplier_code',
            'name' => 'required|string',
            'contact_person' => 'nullable|string',
            'contact_number' => 'nullable|string',
            'email' => 'nullable|email',
            'address' => 'nullable|string',
            'tin' => 'nullable|string',
            'telefax' => 'nullable|string',
            'payment_terms' => 'nullable|string',
            'status' => 'nullable|in:Active,Inactive',
            'start_date' => 'nullable|date',
            'end_date' => 'nullable|date',
            'Supplier_Image' => 'nullable|string', // Base64
        ]);

        $supplier = \App\Models\Supplier::create($validated);
        $actor = hatdogAuditActor($user);
        $recordName = trim((string) ($supplier->name ?? $supplier->supplier_code ?? 'Supplier'));

        hatdogWriteAuditTrail([
            'module' => 'supplier',
            'action' => 'Created',
            'source_connection' => 'masterlist',
            'source_table' => 'suppliers',
            'source_id' => $supplier->id,
            'display_id' => (string) ($supplier->supplier_code ?? $supplier->id),
            'record_name' => $recordName,
            'user_name' => $actor['name'],
            'user_identifier' => $actor['identifier'],
            'audit_data' => [
                'after' => $supplier->toArray(),
            ],
        ]);

        return response()->json([
            'success' => true,
            'message' => 'Supplier registered successfully',
            'supplier' => $supplier->refresh()
        ]);
    } catch (\Exception $e) {
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.supplier-master.create');

// Update supplier
Route::post('/admin/masterlist/supplier/update/{id}', function (Request $request, $id) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

    try {
        $supplier = \App\Models\Supplier::findOrFail($id);
        $before = $supplier->toArray();
        unset($before['lifecycle']);
        
        $validated = $request->validate([
            'supplier_code' => 'required|unique:masterlist.suppliers,supplier_code,' . $id,
            'name' => 'required|string',
            'contact_person' => 'nullable|string',
            'contact_number' => 'nullable|string',
            'email' => 'nullable|email',
            'address' => 'nullable|string',
            'tin' => 'nullable|string',
            'telefax' => 'nullable|string',
            'payment_terms' => 'nullable|string',
            'status' => 'nullable|in:Active,Inactive',
            'start_date' => 'nullable|date',
            'end_date' => 'nullable|date',
            'Supplier_Image' => 'nullable|string', // Base64
        ]);

        $supplier->update($validated);
        $supplier->refresh();
        $actor = hatdogAuditActor($user);
        $recordName = trim((string) ($supplier->name ?? $supplier->supplier_code ?? 'Supplier'));
        $after = $supplier->toArray();
        unset($after['lifecycle']);

        hatdogWriteAuditTrail([
            'module' => 'supplier',
            'action' => 'Updated',
            'source_connection' => 'masterlist',
            'source_table' => 'suppliers',
            'source_id' => $supplier->id,
            'display_id' => (string) ($supplier->supplier_code ?? $supplier->id),
            'record_name' => $recordName,
            'user_name' => $actor['name'],
            'user_identifier' => $actor['identifier'],
            'audit_data' => [
                'before' => $before,
                'after' => $after,
            ],
        ]);

        return response()->json([
            'success' => true,
            'message' => 'Supplier updated successfully',
            'supplier' => $supplier
        ]);
    } catch (\Exception $e) {
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.supplier-master.update');

// Delete supplier
Route::post('/admin/masterlist/supplier/delete/{id}', function ($id) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

    try {
        if (is_array($user)) {
            $user = (object) $user;
        }

        if (!Schema::connection('ledger')->hasTable('archived_records')) {
            throw new \Exception('Archive table is missing. Please run the archive migration first.');
        }

        DB::connection('masterlist')->beginTransaction();
        DB::connection('ledger')->beginTransaction();

        $supplier = \App\Models\Supplier::query()->lockForUpdate()->findOrFail($id);
        $supplierData = $supplier->toArray();
        unset($supplierData['lifecycle']);

        $deletedBy = $user->name ?? $user->username ?? $user->User_ID ?? 'Admin';
        $displayId = (string) ($supplier->supplier_code ?? $supplier->id);
        $dataName = trim((string) (($supplier->name ?? '') !== '' ? $supplier->name : ($supplier->supplier_code ?? 'Supplier')));
        $actor = hatdogAuditActor($user);

        $existingArchive = DB::connection('ledger')
            ->table('archived_records')
            ->where('module', 'supplier')
            ->whereNull('restored_at')
            ->where('source_connection', 'masterlist')
            ->where('source_table', 'suppliers')
            ->where('source_id', $supplier->id)
            ->first();

        if ($existingArchive) {
            throw new \Exception('This supplier is already archived.');
        }

        DB::connection('ledger')->table('archived_records')->insert([
            'module' => 'supplier',
            'source_connection' => 'masterlist',
            'source_table' => 'suppliers',
            'source_id' => $supplier->id,
            'display_id' => $displayId,
            'data_name' => $dataName,
            'archived_data' => json_encode($supplierData, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE),
            'deleted_by' => (string) $deletedBy,
            'deleted_at' => now(),
            'expires_at' => now()->addDays(30),
            'created_at' => now(),
            'updated_at' => now(),
        ]);

        hatdogWriteAuditTrail([
            'module' => 'supplier',
            'action' => 'Deleted',
            'source_connection' => 'masterlist',
            'source_table' => 'suppliers',
            'source_id' => $supplier->id,
            'display_id' => $displayId,
            'record_name' => $dataName,
            'user_name' => $actor['name'],
            'user_identifier' => $actor['identifier'],
            'audit_data' => [
                'before' => $supplierData,
            ],
        ]);

        $supplier->delete();

        DB::connection('ledger')->commit();
        DB::connection('masterlist')->commit();

        return response()->json(['success' => true, 'message' => 'Supplier archived successfully']);
    } catch (\Exception $e) {
        if (DB::connection('ledger')->transactionLevel() > 0) DB::connection('ledger')->rollBack();
        if (DB::connection('masterlist')->transactionLevel() > 0) DB::connection('masterlist')->rollBack();
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.supplier-master.delete');

// Fetch supplier purchase history (from product_ledgers)
Route::get('/admin/masterlist/supplier/history/{id}', function ($id) {
    $user = session('user');
