// Fetch all customers from core4_masterlist.customers
Route::get('/admin/masterlist/customer/data', function (Request $request) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

    $search = $request->query('search', []);
    $page = (int) $request->query('page', 1);
    $perPageInput = $request->query('perPage', 50);

    $query = \App\Models\Customer::with(['type', 'bankAccount']);

    // Column search across ALL data before pagination
    $searchableColumns = ['name', 'contact_number', 'contact_person', 'address'];
    $generalSearch = $search['general'] ?? '';
    foreach ($searchableColumns as $col) {
        if (!empty($search[$col])) {
            $query->where($col, 'LIKE', '%' . $search[$col] . '%');
        }
    }
    if (!empty($search['type'])) {
        $query->whereHas('type', function ($q) use ($search) {
            $q->where('name', 'LIKE', '%' . $search['type'] . '%');
        });
    }
    if ($generalSearch !== '') {
        $query->where(function ($q) use ($generalSearch) {
            $q->where('name', 'LIKE', '%' . $generalSearch . '%')
              ->orWhere('contact_person', 'LIKE', '%' . $generalSearch . '%')
              ->orWhere('address', 'LIKE', '%' . $generalSearch . '%');
        });
    }

    $totalMatching = $query->count();

    // Unfiltered stats
    $stats = [
        'total' => \App\Models\Customer::count(),
        'regular' => \App\Models\Customer::whereHas('type', fn($q) => $q->where('name', 'Regular'))->count(),
        'b2b' => \App\Models\Customer::whereHas('type', fn($q) => $q->where('name', 'B2B Customer'))->count(),
        'casual' => \App\Models\Customer::whereHas('type', fn($q) => $q->where('name', 'Casual'))->count(),
    ];

    if ($perPageInput === 'all') {
        $customers = $query->orderBy('created_at', 'desc')->get();
        $pagination = [
            'current_page' => 1, 'last_page' => 1, 'per_page' => $totalMatching,
            'total' => $totalMatching, 'from' => $totalMatching > 0 ? 1 : 0, 'to' => $totalMatching,
        ];
    } else {
        $perPage = max(1, (int) $perPageInput);
        $lastPage = max(1, (int) ceil($totalMatching / $perPage));
        $page = max(1, min($page, $lastPage));
        $skip = ($page - 1) * $perPage;

        $customers = $query->orderBy('created_at', 'desc')->skip($skip)->take($perPage)->get();

        $pagination = [
            'current_page' => $page,
            'last_page' => $lastPage,
            'per_page' => $perPage,
            'total' => $totalMatching,
            'from' => $totalMatching > 0 ? $skip + 1 : 0,
            'to' => min($skip + $perPage, $totalMatching),
        ];
    }

    return response()->json([
        'customers' => $customers->map(function ($c) {
            return [
                'id' => $c->id,
                'name' => $c->name,
                'contactNo' => $c->contact_number,
                'contactPerson' => $c->contact_person,
                'address' => $c->address,
                'tin' => $c->tin,
                'pricingRemarks' => $c->pricing_remarks,
                'terms' => $c->terms,
                'type' => $c->type ? $c->type->name : 'Regular',
                'bank' => [
                    'code' => $c->bankAccount ? $c->bankAccount->bank_code : '',
                    'accNo' => $c->bankAccount ? $c->bankAccount->account_number : '',
                    'name' => $c->bankAccount ? $c->bankAccount->bank_name : '',
                    'contactNo' => $c->bankAccount ? $c->bankAccount->bank_contact_number : '',
                    'contactPerson' => $c->bankAccount ? $c->bankAccount->bank_contact_person : '',
                    'address' => $c->bankAccount ? $c->bankAccount->bank_address : '',
                ],
            ];
        })->values(),
        'stats' => $stats,
        'pagination' => $pagination,
    ]);
})->name('admin.customer-master.data');

// Create new customer in core4_masterlist.customers
Route::post('/admin/masterlist/customer/create', function (Request $request) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

    try {
        $validated = $request->validate([
            'name' => 'required|string|max:255',
            'type' => 'required|string|exists:masterlist.customer_types,name',
            'contactNo' => 'nullable|string|max:255',
            'contactPerson' => 'nullable|string|max:255',
            'address' => 'nullable|string',
            'tin' => 'nullable|string|max:255',
            'pricingRemarks' => 'nullable|string',
            'terms' => 'nullable|string|max:255',
            'bankCode' => 'nullable|string|max:255',
            'bankAccNo' => 'nullable|string|max:255',
            'bankName' => 'nullable|string|max:255',
            'bankContact' => 'nullable|string|max:255',
            'bankPerson' => 'nullable|string|max:255',
            'bankAddress' => 'nullable|string',
        ]);

        return DB::connection('masterlist')->transaction(function () use ($validated, $user) {
            $type = \App\Models\CustomerType::where('name', $validated['type'])->first();

            $customer = \App\Models\Customer::create([
                'customer_type_id' => $type->id,
                'name' => $validated['name'],
                'contact_number' => $validated['contactNo'],
                'contact_person' => $validated['contactPerson'],
                'address' => $validated['address'],
                'tin' => $validated['tin'],
                'pricing_remarks' => $validated['pricingRemarks'] ?? null,
                'terms' => $validated['terms'] ?? null,
            ]);

            \App\Models\CustomerBankAccount::create([
                'customer_id' => $customer->id,
                'bank_code' => $validated['bankCode'],
                'account_number' => $validated['bankAccNo'],
                'bank_name' => $validated['bankName'],
                'bank_contact_number' => $validated['bankContact'],
                'bank_contact_person' => $validated['bankPerson'],
                'bank_address' => $validated['bankAddress'],
            ]);

            $customer->load('bankAccount');
            $actor = hatdogAuditActor($user);
            $recordName = trim((string) ($customer->name ?? 'Customer'));

            hatdogWriteAuditTrail([
                'module' => 'customer',
                'action' => 'Created',
                'source_connection' => 'masterlist',
                'source_table' => 'customers',
                'source_id' => $customer->id,
                'display_id' => (string) $customer->id,
                'record_name' => $recordName,
                'user_name' => $actor['name'],
                'user_identifier' => $actor['identifier'],
                'audit_data' => [
                    'after' => [
                        'customer' => $customer->toArray(),
                        'bank_account' => $customer->bankAccount?->toArray(),
                        'customer_type' => $type->name,
                    ],
                ],
            ]);

            return response()->json(['success' => true, 'message' => 'Customer registered successfully']);
        });
    } catch (\Exception $e) {
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.customer-master.create');

// Update customer in core4_masterlist.customers
Route::post('/admin/masterlist/customer/update/{id}', function (Request $request, $id) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

    try {
        $validated = $request->validate([
            'name' => 'required|string|max:255',
            'type' => 'required|string|exists:masterlist.customer_types,name',
            'contactNo' => 'nullable|string|max:255',
            'contactPerson' => 'nullable|string|max:255',
            'address' => 'nullable|string',
            'tin' => 'nullable|string|max:255',
            'pricingRemarks' => 'nullable|string',
            'terms' => 'nullable|string|max:255',
            'bankCode' => 'nullable|string|max:255',
            'bankAccNo' => 'nullable|string|max:255',
            'bankName' => 'nullable|string|max:255',
            'bankContact' => 'nullable|string|max:255',
            'bankPerson' => 'nullable|string|max:255',
            'bankAddress' => 'nullable|string',
        ]);

        return DB::connection('masterlist')->transaction(function () use ($validated, $id, $user) {
            $customer = \App\Models\Customer::findOrFail($id);
            $customer->load('bankAccount', 'type');
            $before = [
                'customer' => $customer->toArray(),
                'bank_account' => $customer->bankAccount?->toArray(),
                'customer_type' => $customer->type?->name,
            ];
            $type = \App\Models\CustomerType::where('name', $validated['type'])->first();

            $customer->update([
                'customer_type_id' => $type->id,
                'name' => $validated['name'],
                'contact_number' => $validated['contactNo'],
                'contact_person' => $validated['contactPerson'],
                'address' => $validated['address'],
                'tin' => $validated['tin'],
                'pricing_remarks' => $validated['pricingRemarks'] ?? null,
                'terms' => $validated['terms'] ?? null,
            ]);

            $bank = \App\Models\CustomerBankAccount::firstOrNew(['customer_id' => $customer->id]);
            $bank->fill([
                'bank_code' => $validated['bankCode'],
                'account_number' => $validated['bankAccNo'],
                'bank_name' => $validated['bankName'],
                'bank_contact_number' => $validated['bankContact'],
                'bank_contact_person' => $validated['bankPerson'],
                'bank_address' => $validated['bankAddress'],
            ])->save();

            $customer->load('bankAccount', 'type');
            $actor = hatdogAuditActor($user);
            $recordName = trim((string) ($customer->name ?? 'Customer'));

            hatdogWriteAuditTrail([
                'module' => 'customer',
                'action' => 'Updated',
                'source_connection' => 'masterlist',
                'source_table' => 'customers',
                'source_id' => $customer->id,
                'display_id' => (string) $customer->id,
                'record_name' => $recordName,
                'user_name' => $actor['name'],
                'user_identifier' => $actor['identifier'],
                'audit_data' => [
                    'before' => $before,
                    'after' => [
                        'customer' => $customer->toArray(),
                        'bank_account' => $customer->bankAccount?->toArray(),
                        'customer_type' => $type->name,
                    ],
                ],
            ]);

            return response()->json(['success' => true, 'message' => 'Customer updated successfully']);
        });
    } catch (\Exception $e) {
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.customer-master.update');

// Delete customer from core4_masterlist.customers
Route::post('/admin/masterlist/customer/delete/{id}', function ($id) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

    try {
        if (is_array($user)) {
            $user = (object) $user;
        }

        if (!Schema::connection('ledger')->hasTable('archived_records')) {
            throw new \Exception('Archive table is missing. Please run the archive migration first.');
        }

        DB::connection('masterlist')->beginTransaction();
        DB::connection('ledger')->beginTransaction();

        $customer = \App\Models\Customer::query()->lockForUpdate()->findOrFail($id);
        $bank = \App\Models\CustomerBankAccount::where('customer_id', $customer->id)->first();

        $customerData = $customer->toArray();
        $bankData = $bank ? $bank->toArray() : null;
        $archivedData = [
            'customer' => $customerData,
            'bank_account' => $bankData,
        ];

        $deletedBy = $user->name ?? $user->username ?? $user->User_ID ?? 'Admin';
        $displayId = (string) ($customer->id);
        $dataName = trim((string) (($customer->name ?? '') !== '' ? $customer->name : 'Customer'));
        $actor = hatdogAuditActor($user);

        $existingArchive = DB::connection('ledger')
            ->table('archived_records')
            ->where('module', 'customer')
            ->whereNull('restored_at')
            ->where('source_connection', 'masterlist')
            ->where('source_table', 'customers')
            ->where('source_id', $customer->id)
            ->first();

        if ($existingArchive) {
            throw new \Exception('This customer is already archived.');
        }

        DB::connection('ledger')->table('archived_records')->insert([
            'module' => 'customer',
            'source_connection' => 'masterlist',
            'source_table' => 'customers',
            'source_id' => $customer->id,
            'display_id' => $displayId,
            'data_name' => $dataName,
            'archived_data' => json_encode($archivedData, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE),
            'deleted_by' => (string) $deletedBy,
            'deleted_at' => now(),
            'expires_at' => now()->addDays(30),
            'created_at' => now(),
            'updated_at' => now(),
        ]);

        hatdogWriteAuditTrail([
            'module' => 'customer',
            'action' => 'Deleted',
            'source_connection' => 'masterlist',
            'source_table' => 'customers',
            'source_id' => $customer->id,
            'display_id' => $displayId,
            'record_name' => $dataName,
            'user_name' => $actor['name'],
            'user_identifier' => $actor['identifier'],
            'audit_data' => [
                'before' => $archivedData,
            ],
        ]);

        $customer->delete();

        DB::connection('ledger')->commit();
        DB::connection('masterlist')->commit();

        return response()->json(['success' => true, 'message' => 'Customer archived successfully']);
    } catch (\Exception $e) {
        if (DB::connection('ledger')->transactionLevel() > 0) DB::connection('ledger')->rollBack();
        if (DB::connection('masterlist')->transactionLevel() > 0) DB::connection('masterlist')->rollBack();
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.customer-master.delete');

// Customer Purchase History - authoritative source: core4_sales_order.sales_orders + sales_order_items
if (!function_exists('hatdogCustomerSalesInvoiceNumbers')) {
    function hatdogCustomerSalesInvoiceNumbers($raw, $fallback = ''): array
    {
        $raw = trim((string) ($raw ?? ''));
        $values = [];

        if ($raw !== '') {
            $decoded = json_decode($raw, true);
            if (is_array($decoded)) {
                $values = $decoded;
            } elseif (is_string($decoded) && trim($decoded) !== '') {
                $values = [$decoded];
            } else {
                $values = preg_split('/[,\r\n]+/', $raw) ?: [];
            }
        }

        $values = collect($values)
            ->map(fn ($value) => trim((string) $value))
            ->filter(fn ($value) => $value !== '')
            ->unique()
            ->values()
            ->all();

        if (empty($values) && trim((string) $fallback) !== '') {
            $values = [trim((string) $fallback)];
        }

        return $values;
    }
}

if (!function_exists('hatdogCustomerNormalizeInvoiceKey')) {
    function hatdogCustomerNormalizeInvoiceKey($value): string
    {
        return strtoupper(preg_replace('/\s+/', '', trim((string) $value)));
    }
}

if (!function_exists('hatdogCustomerSalesOrderOwnershipQuery')) {
    function hatdogCustomerSalesOrderOwnershipQuery($query, int $customerId, string $customerName)
    {
        return $query->where(function ($q) use ($customerId, $customerName) {
            $q->where('so.customer_id', $customerId);
            if ($customerName !== '') {
                $q->orWhereRaw('UPPER(TRIM(so.customer_name)) = ?', [mb_strtoupper(trim($customerName))]);
            }
        });
    }
}

Route::get('/admin/masterlist/customer/purchase-history/{id}', function ($id) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

    try {
        $customer = DB::connection('masterlist')->table('customers')->where('id', $id)->first(['id', 'name']);
        if (!$customer) {
            return response()->json(['success' => false, 'message' => 'Customer not found.'], 404);
        }

        $customerName = trim((string) ($customer->name ?? ''));
        $query = DB::connection('sales')->table('sales_orders as so')
            ->join('sales_order_items as soi', 'soi.sales_order_id', '=', 'so.id')
            ->whereRaw("UPPER(TRIM(COALESCE(so.status, ''))) NOT IN ('CANCELLED', 'VOID')");

        hatdogCustomerSalesOrderOwnershipQuery($query, (int) $customer->id, $customerName);

        $rows = $query->select(
                'so.id as sales_order_id',
                'so.order_number',
                'so.invoice_numbers',
                'so.status as order_status',
                'so.created_at as order_created_at',
                'so.updated_at as order_updated_at',
                'soi.id as sales_order_item_id',
                'soi.product_code',
                'soi.description',
                'soi.quantity',
                'soi.actual_qty',
                'soi.additional_qty',
                'soi.oum',
                'soi.unit_price',
                'soi.discount',
                'soi.additional_discount',
                'soi.subtotal',
                'soi.particulars',
                'soi.created_at as item_created_at'
            )
            ->orderByDesc('so.created_at')
            ->orderByDesc('so.id')
            ->orderBy('soi.id')
            ->get();

        $purchases = $rows->map(function ($row) {
            $invoiceNumbers = hatdogCustomerSalesInvoiceNumbers($row->invoice_numbers ?? null, $row->order_number ?? '');
            $date = $row->order_created_at ?: ($row->item_created_at ?: $row->order_updated_at);

            return [
                // Backward-compatible key; this column is now labelled SO No. in the UI.
                'onhand' => (string) ($row->order_number ?? '---'),
                'order_no' => (string) ($row->order_number ?? '---'),
                'sales_order_id' => (int) $row->sales_order_id,
                'date' => $date ? substr((string) $date, 0, 10) : '---',
                'inv' => !empty($invoiceNumbers) ? implode(', ', $invoiceNumbers) : '---',
                'code' => (string) ($row->product_code ?? '---'),
                'desc' => (string) (($row->description ?? '') !== '' ? $row->description : '---'),
                'qty' => (float) ($row->quantity ?? 0),
                'qplus' => (float) ($row->additional_qty ?? 0),
                'actual_qty' => (float) ($row->actual_qty ?? 0),
                'unit' => (string) (($row->oum ?? '') !== '' ? $row->oum : 'PCS'),
                'price' => (float) ($row->unit_price ?? 0),
                'disc' => (float) ($row->discount ?? 0),
                'additional_discount' => (float) ($row->additional_discount ?? 0),
                'total' => (float) ($row->subtotal ?? 0),
                'particulars' => (string) ($row->particulars ?? ''),
                'order_status' => (string) ($row->order_status ?? ''),
            ];
        })->values()->all();

        return response()->json([
            'success' => true,
            'source' => 'core4_sales_order.sales_orders + core4_sales_order.sales_order_items',
            'purchases' => $purchases,
        ]);
    } catch (\Throwable $e) {
        Log::error('Customer purchase history error: ' . $e->getMessage());
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.customer-master.purchase-history');

// Customer invoice/payment ledger summary. Sales invoices come from core4_sales_order;
// settlements come from the same core4_accounting process-payment tables used by Admin Payments.
Route::get('/admin/masterlist/customer/payment-history/{id}', function ($id) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

    try {
        $customer = DB::connection('masterlist')->table('customers')->where('id', $id)->first(['id', 'name']);
        if (!$customer) {
            return response()->json(['success' => false, 'message' => 'Customer not found.'], 404);
        }

        $customerName = trim((string) ($customer->name ?? ''));
        $orderQuery = DB::connection('sales')->table('sales_orders as so')
            ->whereRaw("UPPER(TRIM(COALESCE(so.status, ''))) NOT IN ('CANCELLED', 'VOID')");
        hatdogCustomerSalesOrderOwnershipQuery($orderQuery, (int) $customer->id, $customerName);

        $orders = $orderQuery->select(
                'so.id', 'so.order_number', 'so.invoice_numbers', 'so.total_amount',
                'so.status', 'so.created_at', 'so.updated_at', 'so.waybill_date'
            )
            ->orderByDesc('so.created_at')
            ->orderByDesc('so.id')
            ->get();

        $orderIds = $orders->pluck('id')->map(fn ($value) => (int) $value)->values();
        $settlements = $orderIds->isEmpty()
            ? collect()
            : DB::connection('accounting')->table('process_payment_invoices as ppi')
                ->join('process_payments as pp', 'pp.id', '=', 'ppi.process_payment_id')
                ->where('ppi.source_type', 'sales_order')
                ->whereIn('ppi.source_id', $orderIds)
                ->whereRaw("UPPER(TRIM(COALESCE(pp.status, 'POSTED'))) = 'POSTED'")
                ->select(
                    'ppi.source_id',
                    DB::raw('COALESCE(SUM(ppi.paid_amount), 0) as paid_total'),
                    DB::raw('COALESCE(SUM(ppi.adjustment), 0) as adjustment_total'),
                    DB::raw('MAX(pp.payment_date) as latest_payment_date'),
                    DB::raw("GROUP_CONCAT(DISTINCT pp.payment_no ORDER BY pp.payment_date DESC, pp.id DESC SEPARATOR ', ') as payment_numbers")
                )
                ->groupBy('ppi.source_id')
                ->get()
                ->keyBy(fn ($row) => (int) $row->source_id);

        $returnQuery = DB::connection('sales')->table('sales_returns as sr')
            ->join('sales_return_items as sri', 'sri.sales_return_id', '=', 'sr.id')
            ->whereNotNull('sr.invoice_no')
            ->whereRaw("UPPER(TRIM(COALESCE(sr.status, ''))) NOT IN ('CANCELLED', 'VOID')")
            ->where(function ($q) use ($customer, $customerName) {
                $q->where('sr.customer_id', (int) $customer->id);
                if ($customerName !== '') {
                    $q->orWhereRaw('UPPER(TRIM(sr.customer_name)) = ?', [mb_strtoupper($customerName)]);
                }
            })
            ->select('sr.invoice_no', DB::raw('COALESCE(SUM(COALESCE(sri.return_amount, sri.subtotal, 0)), 0) as return_total'))
            ->groupBy('sr.invoice_no')
            ->get();

        $returnMap = [];
        foreach ($returnQuery as $returnRow) {
            $raw = trim((string) ($returnRow->invoice_no ?? ''));
            if ($raw === '') continue;
            $amount = (float) ($returnRow->return_total ?? 0);
            $keys = [hatdogCustomerNormalizeInvoiceKey($raw)];
            foreach (preg_split('/[,\s\/]+/', $raw) ?: [] as $token) {
                $token = trim((string) $token);
                if ($token !== '') $keys[] = hatdogCustomerNormalizeInvoiceKey($token);
            }
            foreach (array_unique(array_filter($keys)) as $key) {
                $returnMap[$key] = (float) ($returnMap[$key] ?? 0) + $amount;
            }
        }

        $ledger = $orders->map(function ($order) use ($settlements, $returnMap) {
            $invoiceNumbers = hatdogCustomerSalesInvoiceNumbers($order->invoice_numbers ?? null, $order->order_number ?? '');
            $invoiceDisplay = !empty($invoiceNumbers) ? implode(', ', $invoiceNumbers) : (string) ($order->order_number ?? '---');
            $settlement = $settlements->get((int) $order->id);
            $paid = (float) ($settlement->paid_total ?? 0);
            $recordedAdjustment = (float) ($settlement->adjustment_total ?? 0);
            $returned = 0.0;

            $keys = collect($invoiceNumbers)
                ->push((string) ($order->order_number ?? ''))
                ->map(fn ($value) => hatdogCustomerNormalizeInvoiceKey($value))
                ->filter()
                ->unique();
            foreach ($keys as $key) {
                $returned += (float) ($returnMap[$key] ?? 0);
            }

            $amount = (float) ($order->total_amount ?? 0);
            $effectiveAdjustment = max($returned, $recordedAdjustment);
            $due = max($amount - $paid - $effectiveAdjustment, 0);
            $status = $due <= 0.005
                ? 'Paid'
                : (($paid > 0.005 || $effectiveAdjustment > 0.005) ? 'Partial' : 'Unpaid');
            $date = $order->created_at ?: ($order->waybill_date ?: $order->updated_at);

            return [
                'sales_order_id' => (int) $order->id,
                'date' => $date ? substr((string) $date, 0, 10) : '---',
                'code' => $invoiceDisplay,
                'invoice_no' => $invoiceDisplay,
                'module' => 'Sales Invoice',
                'title' => $status,
                'payment_status' => $status,
                'payment_numbers' => (string) ($settlement->payment_numbers ?? ''),
                'latest_payment_date' => $settlement->latest_payment_date ? substr((string) $settlement->latest_payment_date, 0, 10) : '',
                'debit' => round($amount, 2),
                'paid' => round($paid, 2),
                'return_amount' => round($returned, 2),
                'adjustment' => round($effectiveAdjustment, 2),
                // Credit is total settlement so the existing Ledger columns remain meaningful.
                'credit' => round($paid + $effectiveAdjustment, 2),
                'balance' => round($due, 2),
                'order_status' => (string) ($order->status ?? ''),
            ];
        })->values()->all();

        return response()->json([
            'success' => true,
            'customer_id' => (int) $customer->id,
            'customer_name' => $customerName,
            'ledger' => $ledger,
        ]);
    } catch (\Throwable $e) {
        Log::error('Customer payment history error: ' . $e->getMessage());
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.customer-master.payment-history');

// Payment-History-style ledger detail for one customer Sales Order / invoice.
Route::get('/admin/masterlist/customer/payment-history/{id}/invoice/{salesOrderId}', function ($id, $salesOrderId) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

    try {
        $customer = DB::connection('masterlist')->table('customers')->where('id', $id)->first(['id', 'name']);
        if (!$customer) return response()->json(['success' => false, 'message' => 'Customer not found.'], 404);

        $customerName = trim((string) ($customer->name ?? ''));
        $orderQuery = DB::connection('sales')->table('sales_orders as so')->where('so.id', $salesOrderId);
        hatdogCustomerSalesOrderOwnershipQuery($orderQuery, (int) $customer->id, $customerName);
        $order = $orderQuery->first([
            'so.id', 'so.order_number', 'so.invoice_numbers', 'so.total_amount',
            'so.status', 'so.created_at', 'so.updated_at', 'so.waybill_date'
        ]);
        if (!$order) return response()->json(['success' => false, 'message' => 'Sales invoice not found for this customer.'], 404);

        $invoiceNumbers = hatdogCustomerSalesInvoiceNumbers($order->invoice_numbers ?? null, $order->order_number ?? '');
        $invoiceDisplay = !empty($invoiceNumbers) ? implode(', ', $invoiceNumbers) : (string) ($order->order_number ?? '---');
        $invoiceDate = $order->created_at ?: ($order->waybill_date ?: $order->updated_at);
        $service = app(\App\Services\PaymentHistoryService::class);
        $primaryInvoiceNo = $invoiceNumbers[0] ?? $invoiceDisplay;
        $items = $service->invoiceItems('sales_order', (int) $order->id, $primaryInvoiceNo);
        $rows = [];

        foreach ($items as $index => $item) {
            $rows[] = [
                'invoice_no' => $invoiceDisplay,
                'product_code' => (string) ($item['product_code'] ?? '---'),
                'part_number' => (string) ($item['part_number'] ?? '---'),
                'transaction' => 'INVOICE',
                'transaction_no' => $invoiceDisplay,
                'debit' => (float) ($item['total_amount'] ?? 0),
                'credit' => 0.0,
                'remarks' => (string) ($item['description'] ?? ''),
                'date' => $invoiceDate ? substr((string) $invoiceDate, 0, 10) : '',
                '_sort_at' => ($invoiceDate ?: '0000-00-00') . ' 00:00:00',
                '_sort_id' => 1000 + $index,
            ];

            $returnedAmount = (float) ($item['returned_amount'] ?? 0);
            $returnedQty = (float) ($item['returned_qty'] ?? 0);
            if ($returnedAmount > 0.005 || $returnedQty > 0) {
                $returnDate = (string) ($item['return_date'] ?? '');
                $rows[] = [
                    'invoice_no' => $invoiceDisplay,
                    'product_code' => (string) ($item['product_code'] ?? '---'),
                    'part_number' => (string) ($item['part_number'] ?? '---'),
                    'transaction' => 'SALES RETURN',
                    'transaction_no' => (string) (($item['return_number'] ?? '') ?: '---'),
                    'debit' => 0.0,
                    'credit' => $returnedAmount,
                    'remarks' => $returnedQty > 0 ? ('Returned Qty: ' . rtrim(rtrim(number_format($returnedQty, 2, '.', ''), '0'), '.')) : '',
                    'date' => $returnDate,
                    '_sort_at' => ($returnDate ?: '9999-12-30') . ' 12:00:00',
                    '_sort_id' => 5000 + $index,
                ];
            }
        }

        $payments = DB::connection('accounting')->table('process_payment_invoices as ppi')
            ->join('process_payments as pp', 'pp.id', '=', 'ppi.process_payment_id')
            ->where('ppi.source_type', 'sales_order')
            ->where('ppi.source_id', (int) $order->id)
            ->whereRaw("UPPER(TRIM(COALESCE(pp.status, 'POSTED'))) = 'POSTED'")
            ->select(
                'ppi.id', 'ppi.invoice_no', 'ppi.paid_amount', 'ppi.adjustment', 'ppi.remarks',
                'pp.id as payment_id', 'pp.payment_no', 'pp.payment_date', 'pp.remarks as payment_remarks'
            )
            ->orderBy('pp.payment_date')
            ->orderBy('pp.id')
            ->orderBy('ppi.id')
            ->get();

        foreach ($payments as $payment) {
            $paymentDate = $payment->payment_date ? substr((string) $payment->payment_date, 0, 10) : '';
            $remarks = trim((string) (($payment->remarks ?? '') !== '' ? $payment->remarks : ($payment->payment_remarks ?? '')));
            $rows[] = [
                'invoice_no' => (string) (($payment->invoice_no ?? '') !== '' ? $payment->invoice_no : $invoiceDisplay),
                'product_code' => 'PAYMENT',
                'part_number' => '---',
                'transaction' => 'PAID',
                'transaction_no' => (string) ($payment->payment_no ?? '---'),
                'debit' => 0.0,
                'credit' => (float) ($payment->paid_amount ?? 0),
                'remarks' => $remarks,
                'date' => $paymentDate,
                '_sort_at' => ($paymentDate ?: '9999-12-31') . ' 20:00:00',
                '_sort_id' => 100000 + (int) $payment->id,
            ];

            $adjustment = (float) ($payment->adjustment ?? 0);
            if ($adjustment > 0.005) {
                $rows[] = [
                    'invoice_no' => (string) (($payment->invoice_no ?? '') !== '' ? $payment->invoice_no : $invoiceDisplay),
                    'product_code' => 'ADJUSTMENT',
                    'part_number' => '---',
                    'transaction' => 'ADJUSTMENT',
                    'transaction_no' => (string) ($payment->payment_no ?? '---'),
                    'debit' => 0.0,
                    'credit' => $adjustment,
                    'remarks' => 'Payment adjustment',
                    'date' => $paymentDate,
                    '_sort_at' => ($paymentDate ?: '9999-12-31') . ' 21:00:00',
                    '_sort_id' => 200000 + (int) $payment->id,
                ];
            }
        }

        usort($rows, function ($a, $b) {
            $cmp = strcmp((string) ($a['_sort_at'] ?? ''), (string) ($b['_sort_at'] ?? ''));
            if ($cmp !== 0) return $cmp;
            return ((int) ($a['_sort_id'] ?? 0)) <=> ((int) ($b['_sort_id'] ?? 0));
        });
        $rows = array_map(function ($row) {
            unset($row['_sort_at'], $row['_sort_id']);
            return $row;
        }, $rows);

        $paid = (float) $payments->sum('paid_amount');
        $recordedAdjustment = (float) $payments->sum('adjustment');
        $returned = collect($items)->sum(fn ($item) => (float) ($item['returned_amount'] ?? 0));
        $effectiveAdjustment = max($returned, $recordedAdjustment);
        $amount = (float) ($order->total_amount ?? 0);
        $due = max($amount - $paid - $effectiveAdjustment, 0);
        $status = $due <= 0.005 ? 'Paid' : (($paid > 0.005 || $effectiveAdjustment > 0.005) ? 'Partial' : 'Unpaid');

        return response()->json([
            'success' => true,
            'invoice' => [
                'sales_order_id' => (int) $order->id,
                'invoice_no' => $invoiceDisplay,
                'invoice_date' => $invoiceDate ? substr((string) $invoiceDate, 0, 10) : '---',
                'invoice_amount' => round($amount, 2),
                'paid_amount' => round($paid, 2),
                'return_amount' => round($returned, 2),
                'adjustment' => round($effectiveAdjustment, 2),
                'balance' => round($due, 2),
                'payment_status' => $status,
            ],
            'ledger' => $rows,
        ]);
    } catch (\Throwable $e) {
        Log::error('Customer invoice ledger detail error: ' . $e->getMessage());
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.customer-master.payment-history-detail');

