Route::post('/admin/masterlist/customer/notes/{id}', function (Request $request, $id) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

    try {
        if (!Schema::connection('masterlist')->hasColumn('customers', 'notes')) {
            return response()->json([
                'success' => false,
                'message' => 'Customer notes column is missing. Add core4_masterlist.customers.notes first.',
            ], 422);
        }

        $validated = $request->validate([
            'notes' => 'nullable|string|max:16000',
        ]);

        $customer = DB::connection('masterlist')
            ->table('customers')
            ->where('id', $id)
            ->first(['id', 'name', 'notes']);

        if (!$customer) {
            return response()->json(['success' => false, 'message' => 'Customer not found.'], 404);
        }

        $notes = array_key_exists('notes', $validated) ? (string) ($validated['notes'] ?? '') : '';
        $before = (string) ($customer->notes ?? '');

        if ($before !== $notes) {
            DB::connection('masterlist')->table('customers')->where('id', $id)->update([
                'notes' => $notes !== '' ? $notes : null,
                'updated_at' => now(),
            ]);

            $actor = hatdogAuditActor(is_array($user) ? (object) $user : $user);
            hatdogWriteAuditTrail([
                'module' => 'customer',
                'action' => 'Updated',
                'source_connection' => 'masterlist',
                'source_table' => 'customers',
                'source_id' => (int) $customer->id,
                'display_id' => (string) $customer->id,
                'record_name' => trim((string) ($customer->name ?? 'Customer')),
                'user_name' => $actor['name'],
                'user_identifier' => $actor['identifier'],
                'audit_data' => [
                    'before' => ['notes' => $before],
                    'after' => ['notes' => $notes],
                ],
            ]);
        }

        return response()->json([
            'success' => true,
            'message' => 'Customer notes saved.',
            'notes' => $notes,
        ]);
    } catch (\Illuminate\Validation\ValidationException $e) {
        throw $e;
    } catch (\Throwable $e) {
        Log::error('Customer notes save error: ' . $e->getMessage());
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.customer-master.notes.save');

