$formatForwarder = function (\App\Models\Forwarder $forwarder) {
    return [
        'id' => $forwarder->id,
        'code' => $forwarder->code,
        'name' => $forwarder->name,
        'address' => $forwarder->address?->address,
        'contactNo' => $forwarder->contact?->contact_number,
        'contactPerson' => $forwarder->contact?->contact_person,
        'createdAt' => optional($forwarder->created_at)->toDateTimeString(),
    ];
};

$forwarderStats = function () {
    $now = now();

    return [
        'total' => \App\Models\Forwarder::count(),
        'monthly' => \App\Models\Forwarder::whereYear('created_at', $now->year)
            ->whereMonth('created_at', $now->month)
            ->count(),
        'annual' => \App\Models\Forwarder::whereYear('created_at', $now->year)->count(),
    ];
};

$forwarderPayload = function (array $validated) {
    $nullable = static fn (string $key) => array_key_exists($key, $validated) && $validated[$key] !== ''
        ? $validated[$key]
        : null;

    return [
        'forwarder' => [
            'code' => $validated['code'],
            'name' => $validated['name'],
        ],
        'contact' => [
            'contact_number' => $nullable('contactNo'),
            'contact_person' => $nullable('contactPerson'),
        ],
        'address' => [
            'address' => $nullable('address'),
        ],
    ];
};

// Fetch forwarder table rows and dashboard card counts
Route::get('/admin/masterlist/forwarder/data', function (Request $request) use ($formatForwarder, $forwarderStats) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

    try {
        $page = max(1, (int) $request->get('page', 1));
        $perPage = max(1, (int) $request->get('perPage', 50));
        $search = $request->get('search', []);

        $query = \App\Models\Forwarder::with(['contact', 'address']);

        // Apply search filters across all columns
        if (!empty($search)) {
            if (!empty($search['code'])) {
                $query->where('code', 'LIKE', '%' . $search['code'] . '%');
            }
            if (!empty($search['name'])) {
                $query->where('name', 'LIKE', '%' . $search['name'] . '%');
            }
            if (!empty($search['address'])) {
                $query->whereHas('address', function ($q) use ($search) {
                    $q->where('address', 'LIKE', '%' . $search['address'] . '%');
                });
            }
            if (!empty($search['contactNo'])) {
                $query->whereHas('contact', function ($q) use ($search) {
                    $q->where('contact_number', 'LIKE', '%' . $search['contactNo'] . '%');
                });
            }
            if (!empty($search['contactPerson'])) {
                $query->whereHas('contact', function ($q) use ($search) {
                    $q->where('contact_person', 'LIKE', '%' . $search['contactPerson'] . '%');
                });
            }
        }

        $query->orderBy('created_at', 'desc');

        // Paginate results
        $forwarders = $query->paginate($perPage, ['*'], 'page', $page);

        return response()->json([
            'success' => true,
            'forwarders' => collect($forwarders->items())->map($formatForwarder)->values(),
            'pagination' => [
                'current_page' => $forwarders->currentPage(),
                'last_page' => $forwarders->lastPage(),
                'per_page' => $forwarders->perPage(),
                'total' => $forwarders->total(),
                'from' => $forwarders->firstItem(),
                'to' => $forwarders->lastItem(),
            ],
            'stats' => $forwarderStats(),
        ]);
    } catch (\Throwable $e) {
        return response()->json([
            'success' => false,
            'message' => $e->getMessage(),
        ], 500);
    }
})->name('admin.forwarder-master.data');

