    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

    try {
        $validated = $request->validate([
            'code' => 'required|string|max:255|unique:masterlist.forwarders,code',
            'name' => 'required|string|max:255',
            'contactNo' => 'nullable|string|max:255',
            'contactPerson' => 'nullable|string|max:255',
            'address' => 'nullable|string',
        ]);

        $forwarder = DB::connection('masterlist')->transaction(function () use ($validated, $forwarderPayload, $user) {
            $payload = $forwarderPayload($validated);
            $forwarder = \App\Models\Forwarder::create($payload['forwarder']);
            $forwarder->contact()->create($payload['contact']);
            $forwarder->address()->create($payload['address']);

            $forwarder = $forwarder->load(['contact', 'address']);
            $actor = hatdogAuditActor($user);
            $recordName = trim((string) ($forwarder->name ?? $forwarder->code ?? 'Forwarder'));

            hatdogWriteAuditTrail([
                'module' => 'forwarder',
                'action' => 'Created',
                'source_connection' => 'masterlist',
                'source_table' => 'forwarders',
                'source_id' => $forwarder->id,
                'display_id' => (string) ($forwarder->code ?? $forwarder->id),
                'record_name' => $recordName,
                'user_name' => $actor['name'],
                'user_identifier' => $actor['identifier'],
                'audit_data' => [
                    'after' => [
                        'forwarder' => $forwarder->toArray(),
                        'contact' => $forwarder->contact?->toArray(),
                        'address' => $forwarder->address?->toArray(),
                    ],
                ],
            ]);

            return $forwarder;
        });

        return response()->json([
            'success' => true,
            'message' => 'Forwarder registered successfully',
            'forwarder' => $formatForwarder($forwarder),
            'stats' => $forwarderStats(),
        ]);
    } catch (\Exception $e) {
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.forwarder-master.create');

