// Fetch Products for Inventory Adjustment
Route::get('/admin/inventory/adjustment/data', function (\Illuminate\Http\Request $request) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

    $page = (int) $request->query('page', 1);
    $perPage = 50;

    $search = $request->query('search', []);
    $query = \App\Models\Product::query();

    // Filters
    if (!empty($search['code'])) {
        $query->where('product_code', 'LIKE', '%' . $search['code'] . '%');
    }
    if (!empty($search['name'])) {
        $query->where('part_number', 'LIKE', '%' . $search['name'] . '%');
    }
    if (!empty($search['desc'])) {
        $query->where('description', 'LIKE', '%' . $search['desc'] . '%');
    }
    if (!empty($search['app'])) {
        $query->where('application', 'LIKE', '%' . $search['app'] . '%');
    }
    if (!empty($search['qty'])) {
        $query->where('actual_qty', 'LIKE', '%' . $search['qty'] . '%');
    }

    // Status filters (e.g. New / Old status)
    $status = $request->query('status', 'All');
    if ($status !== 'All') {
        $query->where('status', $status);
    }

    $totalMatching = $query->count();
    $lastPage = max(1, (int) ceil($totalMatching / $perPage));
    $page = max(1, min($page, $lastPage));
    $skip = ($page - 1) * $perPage;

    $products = $query->skip($skip)->take($perPage)->get();

    return response()->json([
        'success' => true,
        'products' => $products->map(function ($p) {
            $actualQty = $p->actual_qty;
            $onHand = $p->on_hand ?? 0;
            $diff = is_null($actualQty) ? 0 : ($actualQty - $onHand);

            return [
                'id' => $p->id,
                'code' => $p->product_code,
                'status' => $p->status,
                'name' => $p->part_number ?? '---',
                'desc' => $p->description ?? '---',
                'app' => $p->application ?? '---',
                'onHand' => $onHand,
                'actualQty' => $actualQty ?? 0,
                'unit' => trim((string) ($p->unit ?? '')),
                'diff' => $diff,
            ];
        }),
        'pagination' => [
            'current_page' => $page,
            'last_page' => $lastPage,
            'per_page' => $perPage,
            'total' => $totalMatching,
            'from' => $totalMatching > 0 ? $skip + 1 : 0,
            'to' => min($skip + $perPage, $totalMatching),
        ],
        'stats' => [
            'total' => \App\Models\Product::count(),
            'new' => \App\Models\Product::where('status', 'New')->count(),
            'old' => \App\Models\Product::where('status', 'Old')->count(),
        ]
    ]);
})->name('admin.inv-adjust.data');

// Adjust Inventory (save actual_qty directly)
Route::post('/admin/inventory/adjustment/adjust', function (\Illuminate\Http\Request $request) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

    try {
        $validated = $request->validate([
            'product_id' => 'required|exists:masterlist.products,id',
            'actual_qty' => 'required|integer|min:0',
            'unit' => 'required|string|max:255',
        ]);

        $product = \App\Models\Product::findOrFail($validated['product_id']);
        $beforeActualQty = (int) ($product->actual_qty ?? 0);
        $beforeOnHand = (int) ($product->on_hand ?? 0);
        $beforeUnit = trim((string) ($product->unit ?? ''));
        $beforeDiff = $beforeActualQty - $beforeOnHand;

        $product->actual_qty = $validated['actual_qty'];
        $product->unit = trim($validated['unit']);
        $product->save();

        $actor = hatdogAuditActor($user);

        // Insert product ledger entry for this adjustment
        $afterActualQty = (int) ($product->actual_qty ?? 0);
        $qtyDiff = $afterActualQty - $beforeOnHand;
        $newBalance = (int) $validated['actual_qty'];
        $transactionType = $qtyDiff >= 0 ? 'IN' : 'OUT';
        $absQtyDiff = abs($qtyDiff);

        try {
            \App\Models\ProductLedger::create([
                'product_id' => $product->id,
                'transaction_type' => $transactionType,
                'date' => now()->toDateString(),
                'transaction_number' => 'ADJ-' . $product->product_code . '-' . now()->format('YmdHis'),
                'reference_number' => 'INVENTORY-ADJUSTMENT',
                'entity_name' => $actor['name'],
                'quantity_in' => $transactionType === 'IN' ? $absQtyDiff : 0,
                'quantity_out' => $transactionType === 'OUT' ? $absQtyDiff : 0,
                'balance_stock' => $newBalance,
                'oum' => trim($validated['unit']),
                'price' => $product->selling_price ?? 0,
                'cost' => $product->cost ?? 0,
                'remarks' => 'Inventory adjustment via admin panel',
            ]);
        } catch (\Throwable $e) {
            \Illuminate\Support\Facades\Log::warning('Failed to write product ledger for adjustment.', [
                'product_id' => $product->id,
                'exception' => $e::class,
                'message' => $e->getMessage(),
            ]);
        }
        $afterOnHand = (int) ($product->on_hand ?? 0);
        $afterDiff = $afterActualQty - $afterOnHand;
        $recordName = trim((string) (($product->description ?? '') !== '' ? $product->description : ($product->part_number ?? $product->product_code ?? 'Inventory Item')));

        hatdogWriteAuditTrail([
            'module' => 'inventory',
            'action' => 'Adjusted',
            'source_connection' => 'masterlist',
            'source_table' => 'products',
            'source_id' => $product->id,
            'display_id' => (string) ($product->product_code ?? $product->id),
            'record_name' => $recordName,
            'user_name' => $actor['name'],
            'user_identifier' => $actor['identifier'],
            'audit_data' => [
                'before' => [
                    'product_id' => $product->id,
                    'product_code' => $product->product_code,
                    'part_number' => $product->part_number,
                    'description' => $product->description,
                    'on_hand' => $beforeOnHand,
                    'actual_qty' => $beforeActualQty,
                    'unit' => $beforeUnit,
                    'difference' => $beforeDiff,
                ],
                'after' => [
                    'product_id' => $product->id,
                    'product_code' => $product->product_code,
                    'part_number' => $product->part_number,
                    'description' => $product->description,
                    'on_hand' => $afterOnHand,
                    'actual_qty' => $afterActualQty,
                    'unit' => trim((string) ($product->unit ?? '')),
                    'difference' => $afterDiff,
                ],
                'adjustment' => $afterActualQty - $beforeActualQty,
            ],
        ]);

        return response()->json([
            'success' => true,
            'message' => 'Inventory adjusted successfully.',
        ]);
    } catch (\Exception $e) {
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.inv-adjust.save');


// Inventory Adjustment - Adjusted ledger rows (50 per page)
Route::get('/admin/inventory/adjustment/adjusted', function (\Illuminate\Http\Request $request) {
    $user = session('user');
    if (!$user) return response()->json(['success' => false, 'message' => 'Unauthorized'], 403);

    $page = max(1, (int) $request->query('page', 1));
    $perPage = 50;
    $search = $request->query('search', []);

    $query = DB::connection('ledger')
        ->table('product_ledgers')
        ->where('reference_number', 'INVENTORY-ADJUSTMENT');

    if (!empty($search['code'])) {
        $adjustedProductIds = DB::connection('ledger')
            ->table('product_ledgers')
            ->where('reference_number', 'INVENTORY-ADJUSTMENT')
            ->distinct()
            ->pluck('product_id')
            ->filter()
            ->values();

        $productIds = $adjustedProductIds->isEmpty()
            ? collect()
            : DB::connection('masterlist')
                ->table('products')
                ->whereIn('id', $adjustedProductIds)
                ->where('product_code', 'LIKE', '%' . $search['code'] . '%')
                ->pluck('id');

        if ($productIds->isEmpty()) {
            $query->whereRaw('1 = 0');
        } else {
            $query->whereIn('product_id', $productIds);
        }
    }

    if (!empty($search['qty'])) {
        $query->whereRaw('CAST(balance_stock AS CHAR) LIKE ?', ['%' . $search['qty'] . '%']);
    }

    if (!empty($search['unit'])) {
        $query->where('oum', 'LIKE', '%' . $search['unit'] . '%');
    }

    $total = $query->count();
    $lastPage = max(1, (int) ceil($total / $perPage));
    $page = min($page, $lastPage);
    $skip = ($page - 1) * $perPage;

    $rows = $query
        ->orderByDesc('created_at')
        ->orderByDesc('id')
        ->skip($skip)
        ->take($perPage)
        ->get(['id', 'product_id', 'balance_stock', 'oum', 'transaction_type', 'quantity_in', 'quantity_out', 'created_at']);

    $products = DB::connection('masterlist')
        ->table('products')
        ->whereIn('id', $rows->pluck('product_id')->filter()->unique()->values())
        ->get(['id', 'product_code', 'part_number'])
        ->keyBy('id');

    return response()->json([
        'success' => true,
        'adjustments' => $rows->map(function ($row) use ($products) {
            $product = $products->get($row->product_id);
            return [
                'id' => (int) $row->id,
                'product_id' => (int) $row->product_id,
                'product_code' => $product->product_code ?? '---',
                'part_number' => $product->part_number ?? '---',
                'adjusted_qty' => (int) $row->balance_stock,
                'unit' => trim((string) ($row->oum ?? '')),
                'created_at' => $row->created_at,
            ];
        })->values(),
        'pagination' => [
            'current_page' => $page,
            'last_page' => $lastPage,
            'per_page' => $perPage,
            'total' => $total,
            'from' => $total > 0 ? $skip + 1 : 0,
            'to' => min($skip + $perPage, $total),
        ],
    ]);
})->name('admin.inv-adjust.adjusted');

// Inventory Adjustment - edit a ledger adjustment row
Route::patch('/admin/inventory/adjustment/adjusted/{id}', function (\Illuminate\Http\Request $request, $id) {
    $user = session('user');
    if (!$user) return response()->json(['success' => false, 'message' => 'Unauthorized'], 403);

    $validated = $request->validate([
        'adjusted_qty' => 'required|integer|min:0',
        'unit' => 'required|string|max:255',
    ]);

    $ledgerDb = DB::connection('ledger');
    $masterDb = DB::connection('masterlist');

    $row = $ledgerDb->table('product_ledgers')
        ->where('id', $id)
        ->where('reference_number', 'INVENTORY-ADJUSTMENT')
        ->first();

    if (!$row) {
        return response()->json(['success' => false, 'message' => 'Adjustment record not found.'], 404);
    }

    $product = $masterDb->table('products')->where('id', $row->product_id)->first();
    if (!$product) {
        return response()->json(['success' => false, 'message' => 'Product not found.'], 404);
    }

    $latestAdjustmentId = $ledgerDb->table('product_ledgers')
        ->where('product_id', $row->product_id)
        ->where('reference_number', 'INVENTORY-ADJUSTMENT')
        ->orderByDesc('created_at')
        ->orderByDesc('id')
        ->value('id');

    $ledgerDb->beginTransaction();
    $masterDb->beginTransaction();

    try {
        $unit = trim($validated['unit']);
        $newBalance = (int) $validated['adjusted_qty'];

        // Rebuild the movement from the stock immediately before this adjustment.
        // balance_after = balance_before + quantity_in - quantity_out
        // therefore: balance_before = balance_after - quantity_in + quantity_out.
        $balanceBeforeAdjustment = (int) ($row->balance_stock ?? 0)
            - (int) ($row->quantity_in ?? 0)
            + (int) ($row->quantity_out ?? 0);
        $movement = $newBalance - $balanceBeforeAdjustment;
        $transactionType = $movement >= 0 ? 'IN' : 'OUT';
        $quantityIn = $movement > 0 ? abs($movement) : 0;
        $quantityOut = $movement < 0 ? abs($movement) : 0;

        $ledgerDb->table('product_ledgers')->where('id', $row->id)->update([
            'transaction_type' => $transactionType,
            'quantity_in' => $quantityIn,
            'quantity_out' => $quantityOut,
            'balance_stock' => $newBalance,
            'oum' => $unit,
            'updated_at' => now(),
        ]);

        // Keep the product master synchronized only when editing its newest adjustment.
        if ((int) $latestAdjustmentId === (int) $row->id) {
            $masterDb->table('products')->where('id', $row->product_id)->update([
                'actual_qty' => (int) $validated['adjusted_qty'],
                'unit' => $unit,
                'updated_at' => now(),
            ]);
        }

        $actor = hatdogAuditActor($user);
        hatdogWriteAuditTrail([
            'module' => 'inventory',
            'action' => 'Updated',
            'source_connection' => 'ledger',
            'source_table' => 'product_ledgers',
            'source_id' => (int) $row->id,
            'display_id' => (string) ($product->product_code ?? $row->id),
            'record_name' => (string) ($product->part_number ?? $product->product_code ?? 'Inventory Adjustment'),
            'user_name' => $actor['name'],
            'user_identifier' => $actor['identifier'],
            'audit_data' => [
                'before' => [
                    'transaction_type' => (string) ($row->transaction_type ?? ''),
                    'quantity_in' => (int) ($row->quantity_in ?? 0),
                    'quantity_out' => (int) ($row->quantity_out ?? 0),
                    'adjusted_qty' => (int) $row->balance_stock,
                    'unit' => (string) ($row->oum ?? ''),
                ],
                'after' => [
                    'transaction_type' => $transactionType,
                    'quantity_in' => $quantityIn,
                    'quantity_out' => $quantityOut,
                    'adjusted_qty' => $newBalance,
                    'unit' => $unit,
                ],
            ],
        ]);

        $ledgerDb->commit();
        $masterDb->commit();

        return response()->json(['success' => true, 'message' => 'Adjustment updated successfully.']);
    } catch (\Throwable $e) {
        if ($ledgerDb->transactionLevel() > 0) $ledgerDb->rollBack();
        if ($masterDb->transactionLevel() > 0) $masterDb->rollBack();
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.inv-adjust.adjusted.update');

// Inventory Adjustment - delete a ledger adjustment row
Route::delete('/admin/inventory/adjustment/adjusted/{id}/delete', function ($id) {
    $user = session('user');
    if (!$user) return response()->json(['success' => false, 'message' => 'Unauthorized'], 403);

    $ledgerDb = DB::connection('ledger');
    $masterDb = DB::connection('masterlist');

    $row = $ledgerDb->table('product_ledgers')
        ->where('id', $id)
        ->where('reference_number', 'INVENTORY-ADJUSTMENT')
        ->first();

    if (!$row) {
        return response()->json(['success' => false, 'message' => 'Adjustment record not found.'], 404);
    }

    $product = $masterDb->table('products')->where('id', $row->product_id)->first();
    $latestAdjustmentId = $ledgerDb->table('product_ledgers')
        ->where('product_id', $row->product_id)
        ->where('reference_number', 'INVENTORY-ADJUSTMENT')
        ->orderByDesc('created_at')
        ->orderByDesc('id')
        ->value('id');

    $previousAdjustment = null;
    if ((int) $latestAdjustmentId === (int) $row->id) {
        $previousAdjustment = $ledgerDb->table('product_ledgers')
            ->where('product_id', $row->product_id)
            ->where('reference_number', 'INVENTORY-ADJUSTMENT')
            ->where('id', '<>', $row->id)
            ->orderByDesc('created_at')
            ->orderByDesc('id')
            ->first(['balance_stock', 'oum']);
    }

    $ledgerDb->beginTransaction();
    $masterDb->beginTransaction();

    try {
        $ledgerDb->table('product_ledgers')->where('id', $row->id)->delete();

        // If the deleted row was the newest adjustment, restore the prior adjusted stock.
        if ($product && (int) $latestAdjustmentId === (int) $row->id) {
            $restoreQty = $previousAdjustment ? (int) $previousAdjustment->balance_stock : (int) ($product->on_hand ?? 0);
            $restoreUnit = $previousAdjustment && trim((string) ($previousAdjustment->oum ?? '')) !== ''
                ? trim((string) $previousAdjustment->oum)
                : trim((string) ($product->unit ?? ''));

            $masterDb->table('products')->where('id', $row->product_id)->update([
                'actual_qty' => $restoreQty,
                'unit' => $restoreUnit,
                'updated_at' => now(),
            ]);
        }

        if ($product) {
            $actor = hatdogAuditActor($user);
            hatdogWriteAuditTrail([
                'module' => 'inventory',
                'action' => 'Deleted',
                'source_connection' => 'ledger',
                'source_table' => 'product_ledgers',
                'source_id' => (int) $row->id,
                'display_id' => (string) ($product->product_code ?? $row->id),
                'record_name' => (string) ($product->part_number ?? $product->product_code ?? 'Inventory Adjustment'),
                'user_name' => $actor['name'],
                'user_identifier' => $actor['identifier'],
                'audit_data' => [
                    'before' => [
                        'adjusted_qty' => (int) $row->balance_stock,
                        'unit' => (string) ($row->oum ?? ''),
                        'transaction_number' => (string) ($row->transaction_number ?? ''),
                    ],
                ],
            ]);
        }

        $ledgerDb->commit();
        $masterDb->commit();

        return response()->json(['success' => true, 'message' => 'Adjustment deleted successfully.']);
    } catch (\Throwable $e) {
        if ($ledgerDb->transactionLevel() > 0) $ledgerDb->rollBack();
        if ($masterDb->transactionLevel() > 0) $masterDb->rollBack();
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.inv-adjust.adjusted.delete');

// ─── Admin Item Convert ──────────────────────────────────────────────────────
Route::get('/admin/inventory/item-convert', function () {
    $user = session('user');
    if (!$user) return redirect('/login');
    if (is_array($user)) $user = (object) $user;
    $accountType = (int) ($user->account_type ?? 0);
    if (!in_array($accountType, [1])) return redirect()->route('login');

    $profileUser = Login::where('login_ID', $user->login_ID ?? 0)
        ->orWhere('User_ID', $user->User_ID)
        ->first();

    $welcomeFullName = trim(collect([trim((string) ($profileUser->User_First_Name ?? '')), trim((string) ($profileUser->User_Middle_Name ?? '')), trim((string) ($profileUser->User_Last_Name ?? ''))])->filter()->implode(' '));
    if (empty($welcomeFullName)) $welcomeFullName = $profileUser->User_ID ?? 'Admin';

    $profilePictureUrl = null;
    $hasPp = Schema::hasColumn('logins', 'profile_picture');
    $hasPpMime = Schema::hasColumn('logins', 'profile_picture_mime');
    if ($hasPp && !empty($profileUser->profile_picture)) {
        $mime = $hasPpMime && !empty($profileUser->profile_picture_mime) ? $profileUser->profile_picture_mime : 'image/png';
        $profilePictureUrl = 'data:' . $mime . ';base64,' . base64_encode($profileUser->profile_picture);
    }

    return view('Admin.Inventory.item-convert', [
        'user' => $user,
        'sidebarAvatarUrl' => $profilePictureUrl ?? '',
        'sidebarFullName' => $welcomeFullName,
        'sidebarRoleLabel' => 'Admin',
    ]);
})->name('admin.item-convert');

Route::get('/admin/inventory/item-convert/data', function (\Illuminate\Http\Request $request) {
    $user = session('user');
    if (!$user) return response()->json(['success' => false, 'error' => 'Unauthorized'], 403);
    if (is_array($user)) $user = (object) $user;
    if ((int) ($user->account_type ?? 0) !== 1) return response()->json(['success' => false, 'error' => 'Forbidden'], 403);

    $perPage = 50;
    $page = (int) $request->query('page', 1);
    $search = $request->query('search', []);
    $statusFilter = $request->query('status', 'pending');
    // Map frontend status names to DB values
    $dbStatus = $statusFilter;
    if ($dbStatus === 'converted') $dbStatus = 'confirmed';

    $query = DB::connection('masterlist')
        ->table('product_conversion_requests');

    if (!empty($search['code'])) $query->where('source_product_code', 'LIKE', '%' . $search['code'] . '%');
    if (!empty($search['target'])) $query->where('target_product_code', 'LIKE', '%' . $search['target'] . '%');
    if (!empty($search['requestor'])) $query->where('requestor_name', 'LIKE', '%' . $search['requestor'] . '%');

    // Auto-accept check only runs when viewing pending requests
    $autoAccepted = false;
    $autoAcceptedItems = [];
    if ($statusFilter === 'pending' && Schema::connection('masterlist')->hasTable('auto_accept_config')) {
        $configRow = DB::connection('masterlist')->table('auto_accept_config')
            ->where('key', 'conversion_auto_accept')
            ->first();
        if ($configRow && $configRow->value) {
            $config = json_decode($configRow->value, true);
            if ($config && !empty($config['enabled']) && $config['enabled'] !== '0') {
                // Only run if schedule_active is true
                $scheduleActive = !empty($config['schedule_active']) && $config['schedule_active'] !== '0';
                if ($scheduleActive) {
                    $lastRun = $config['last_auto_accept_run'] ?? null;

                    // Check if already ran today
                    $shouldRun = true;
                    if ($lastRun) {
                        $phToday = now()->setTimezone('Asia/Manila')->format('Y-m-d');
                        $lastRunDate = \Carbon\Carbon::parse($lastRun)->setTimezone('Asia/Manila')->format('Y-m-d');
                        if ($lastRunDate === $phToday) $shouldRun = false;
                    }

                    // Skip weekends if configured
                    $excludeWeekends = !empty($config['exclude_weekends']);
                    if ($shouldRun && $excludeWeekends) {
                        $dayOfWeek = (int) now()->setTimezone('Asia/Manila')->format('N');
                        if ($dayOfWeek >= 6) $shouldRun = false;
                    }

                    if ($shouldRun) {
                        $pendingRequests = DB::connection('masterlist')
                            ->table('product_conversion_requests')
                            ->where('status', 'pending')
                            ->get();

                        foreach ($pendingRequests as $req) {
                            DB::connection('masterlist')
                                ->table('product_conversion_requests')
                                ->where('id', $req->id)
                                ->update([
                                    'status' => 'confirmed',
                                    'reviewed_by' => 0,
                                    'reviewed_at' => now(),
                                    'updated_at' => now(),
                                ]);
                            $autoAcceptedItems[] = [
                                'source_code' => $req->source_product_code,
                                'target_code' => $req->target_product_code,
                                'qty' => (int) $req->converted_qty,
                                'requestor' => $req->requestor_name ?? 'Unknown',
                            ];
                        }

                        $autoAccepted = count($pendingRequests) > 0;

                        $config['last_auto_accept_run'] = now()->toDateTimeString();
                        DB::connection('masterlist')->table('auto_accept_config')
                            ->where('key', 'conversion_auto_accept')
                            ->update(['value' => json_encode($config)]);
                    }
                }
            }
        }
    }

    // Always count all statuses for stats
    $totalPending = (clone $query)->where('status', 'pending')->count();
    $totalConverted = (clone $query)->where('status', 'confirmed')->count();
    $totalRejected = (clone $query)->where('status', 'rejected')->count();
    $totalAll = $totalPending + $totalConverted + $totalRejected;

    // Fetch items for the requested status
    $itemsQuery = (clone $query)->where('status', $dbStatus)->orderBy('created_at', 'desc');
    $requests = $itemsQuery->paginate($perPage, ['*'], 'page', $page);

    $items = collect($requests->items())->map(function ($r) {
        return [
            'id' => $r->id,
            'product_code' => $r->source_product_code,
            'converted_qty' => (int) $r->converted_qty,
            'requestor' => $r->requestor_name ?? 'Unknown',
            'date' => $r->created_at,
            'status' => $r->status ?? 'pending',
            'source_code' => $r->source_product_code,
            'source_part' => $r->source_part_number,
            'source_desc' => $r->source_description,
            'source_app' => $r->source_application,
            'source_pos' => $r->source_position,
            'source_avail' => (int) ($r->source_available_qty ?? 0),
            'target_code' => $r->target_product_code,
            'target_part' => $r->target_part_number,
            'target_desc' => $r->target_description,
            'target_app' => $r->target_application,
            'target_pos' => $r->target_position,
            'target_avail' => (int) ($r->target_available_qty ?? 0),
        ];
    })->values();

    return response()->json([
        'success' => true,
        'items' => $items,
        'pagination' => [
            'current_page' => $requests->currentPage(),
            'last_page' => $requests->lastPage(),
            'per_page' => $requests->perPage(),
            'total' => $requests->total(),
        ],
        'stats' => [
            'total_pending' => $totalPending,
            'converted' => $totalConverted,
            'rejected' => $totalRejected,
            'total' => $totalAll,
        ],
        'auto_accepted' => $autoAccepted,
        'auto_accepted_items' => $autoAcceptedItems,
    ]);
})->name('admin.item-convert.data');

Route::post('/admin/inventory/item-convert/review', function (\Illuminate\Http\Request $request) {
    $user = session('user');
    if (!$user) return response()->json(['success' => false, 'error' => 'Unauthorized'], 403);
    if (is_array($user)) $user = (object) $user;
    if ((int) ($user->account_type ?? 0) !== 1) return response()->json(['success' => false, 'error' => 'Forbidden'], 403);

    $data = $request->json()->all();
    $requestId = $data['request_id'] ?? null;
    $action = $data['action'] ?? '';

    if (!$requestId || !in_array($action, ['confirm', 'reject'])) {
        return response()->json(['success' => false, 'error' => 'Invalid parameters.']);
    }

    $convRequest = DB::connection('masterlist')
        ->table('product_conversion_requests')
        ->where('id', $requestId)
        ->where('status', 'pending')
        ->first();

    if (!$convRequest) {
        return response()->json(['success' => false, 'error' => 'Request not found or already processed.']);
    }

    DB::connection('masterlist')->beginTransaction();
    DB::connection('ledger')->beginTransaction();
    try {
        if ($action === 'confirm') {
            // Ledger rows already inserted at submission time, nothing to update
        } elseif ($action === 'reject') {
            $qty = (int) $convRequest->converted_qty;
            $srcId = $convRequest->source_product_id;
            $tgtId = $convRequest->target_product_id;

            // Find and delete the deduct ledger row for source
            $deductLedger = DB::connection('ledger')
                ->table('product_ledgers')
                ->where('product_id', $srcId)
                ->where('transaction_type', 'CONVERSION_DEDUCT')
                ->where('quantity_out', $qty)
                ->orderBy('id', 'desc')
                ->first();

            if ($deductLedger) {
                DB::connection('ledger')->table('product_ledgers')->where('id', $deductLedger->id)->delete();
            }

            // Find and delete the add ledger row for target
            $addLedger = DB::connection('ledger')
                ->table('product_ledgers')
                ->where('product_id', $tgtId)
                ->where('transaction_type', 'CONVERSION_ADD')
                ->where('quantity_in', $qty)
                ->orderBy('id', 'desc')
                ->first();

            if ($addLedger) {
                DB::connection('ledger')->table('product_ledgers')->where('id', $addLedger->id)->delete();
            }

            $convProductIds = array_filter([$srcId, $tgtId], fn ($id) => $id > 0);
            if (!empty($convProductIds)) {
                \App\Services\ProductStockSyncService::syncProducts($convProductIds);
            }
        }

        DB::connection('masterlist')
            ->table('product_conversion_requests')
            ->where('id', $requestId)
            ->update([
                'status' => $action === 'confirm' ? 'confirmed' : 'rejected',
                'reviewed_by' => $user->login_ID ?? 0,
                'reviewed_at' => now(),
                'updated_at' => now(),
            ]);

        DB::connection('masterlist')->commit();
        DB::connection('ledger')->commit();
        return response()->json(['success' => true, 'message' => 'Request ' . ($action === 'confirm' ? 'confirmed' : 'rejected') . ' successfully.']);
    } catch (\Exception $e) {
        DB::connection('masterlist')->rollBack();
        DB::connection('ledger')->rollBack();
        return response()->json(['success' => false, 'error' => $e->getMessage()], 422);
    }
})->name('admin.item-convert.review');

// Auto-accept settings for conversion requests
Route::post('/admin/inventory/item-convert/auto-accept', function (\Illuminate\Http\Request $request) {
    $user = session('user');
    if (!$user) return response()->json(['success' => false, 'error' => 'Unauthorized'], 403);
    if (is_array($user)) $user = (object) $user;
    if ((int) ($user->account_type ?? 0) !== 1) return response()->json(['success' => false, 'error' => 'Forbidden'], 403);

    if (!Schema::connection('masterlist')->hasTable('auto_accept_config')) {
        Schema::connection('masterlist')->create('auto_accept_config', function ($table) {
            $table->id();
            $table->string('key')->unique();
            $table->text('value')->nullable();
            $table->timestamps();
        });
    }

    $data = $request->json()->all();
    $enabled = !empty($data['enabled']) ? '1' : '0';
    $scheduleActive = !empty($data['schedule_active']) ? '1' : '0';
    $mode = $data['mode'] ?? 'daily';
    $configTime = $data['time'] ?? '18:00';
    $intervalValue = (int) ($data['interval_value'] ?? 1);
    $intervalUnit = $data['interval_unit'] ?? 'days';
    $excludeWeekends = !empty($data['exclude_weekends']) ? '1' : '0';

    // Preserve existing last_auto_accept_run from config
    $existing = DB::connection('masterlist')->table('auto_accept_config')
        ->where('key', 'conversion_auto_accept')
        ->first();
    $lastRun = null;
    if ($existing && $existing->value) {
        $existingParsed = json_decode($existing->value, true);
        if ($existingParsed && !empty($existingParsed['last_auto_accept_run'])) {
            $lastRun = $existingParsed['last_auto_accept_run'];
        }
    }

    $settings = json_encode([
        'enabled' => $enabled,
        'schedule_active' => $scheduleActive,
        'mode' => $mode,
        'time' => $configTime,
        'timezone' => 'Asia/Manila',
        'interval_value' => $intervalValue,
        'interval_unit' => $intervalUnit,
        'exclude_weekends' => $excludeWeekends,
        'last_auto_accept_run' => $lastRun,
    ]);

    DB::connection('masterlist')->table('auto_accept_config')
        ->updateOrInsert(['key' => 'conversion_auto_accept'], [
            'value' => $settings,
            'updated_at' => now(),
        ]);

    // Immediately confirm all pending requests when enabling auto-accept
    $confirmedCount = 0;
    $confirmedItems = [];
    if ($enabled === '1') {
        $pendingRequests = DB::connection('masterlist')
            ->table('product_conversion_requests')
            ->where('status', 'pending')
            ->get();

        foreach ($pendingRequests as $req) {
            DB::connection('masterlist')
                ->table('product_conversion_requests')
                ->where('id', $req->id)
                ->update([
                    'status' => 'confirmed',
                    'reviewed_by' => 0,
                    'reviewed_at' => now(),
                    'updated_at' => now(),
                ]);
            $confirmedItems[] = [
                'source_code' => $req->source_product_code,
                'target_code' => $req->target_product_code,
                'qty' => (int) $req->converted_qty,
                'requestor' => $req->requestor_name ?? 'Unknown',
            ];
        }
        $confirmedCount = count($pendingRequests);

        // Update last_auto_accept_run so schedule doesn't re-trigger today
        $settingsObj = json_decode($settings, true);
        $settingsObj['last_auto_accept_run'] = now()->toDateTimeString();
        DB::connection('masterlist')->table('auto_accept_config')
            ->where('key', 'conversion_auto_accept')
            ->update(['value' => json_encode($settingsObj)]);
    }

    $statsPending = DB::connection('masterlist')->table('product_conversion_requests')->where('status', 'pending')->count();
    $statsConverted = DB::connection('masterlist')->table('product_conversion_requests')->where('status', 'confirmed')->count();
    $statsRejected = DB::connection('masterlist')->table('product_conversion_requests')->where('status', 'rejected')->count();

    return response()->json([
        'success' => true,
        'confirmed_count' => $confirmedCount,
        'confirmed_items' => $confirmedItems,
        'stats' => [
            'total_pending' => $statsPending,
            'converted' => $statsConverted,
            'rejected' => $statsRejected,
            'total' => $statsPending + $statsConverted + $statsRejected,
        ],
    ]);
})->name('admin.item-convert.auto-accept.save');

Route::get('/admin/inventory/item-convert/auto-accept', function () {
    $user = session('user');
    if (!$user) return response()->json(['success' => false, 'error' => 'Unauthorized'], 403);
    if (is_array($user)) $user = (object) $user;
    if ((int) ($user->account_type ?? 0) !== 1) return response()->json(['success' => false, 'error' => 'Forbidden'], 403);

    $settings = ['enabled' => false, 'schedule_active' => false, 'mode' => 'daily', 'time' => '18:00', 'timezone' => 'Asia/Manila', 'interval_value' => 1, 'interval_unit' => 'days', 'exclude_weekends' => true, 'last_auto_accept_run' => null];

    if (Schema::connection('masterlist')->hasTable('auto_accept_config')) {
        $row = DB::connection('masterlist')->table('auto_accept_config')
            ->where('key', 'conversion_auto_accept')
            ->first();
        if ($row && $row->value) {
            $decoded = json_decode($row->value, true);
            if ($decoded) {
                $settings = array_merge($settings, $decoded);
                $settings['enabled'] = ($settings['enabled'] === '1' || $settings['enabled'] === true);
            }
        }
    }

    $settings['current_ph_time'] = now()->setTimezone('Asia/Manila')->format('h:i A');

    return response()->json(['success' => true, 'settings' => $settings]);
})->name('admin.item-convert.auto-accept');

