// Sales Junk Items Data
Route::get('/admin/inventory/sales-junk/data', function (Request $request) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

    try {
        // Get all sales return items with their return numbers
        $returnItems = DB::connection('sales')->table('sales_return_items as sri')
            ->join('sales_returns as sr', 'sr.id', '=', 'sri.sales_return_id')
            ->select(
                'sri.product_id',
                'sri.product_code',
                'sri.part_number',
                'sri.description',
                'sri.application',
                'sri.quantity',
                'sr.return_number'
            )
            ->get();

        // Get all product_ledgers good items entries from sales returns
        $goodEntries = DB::connection('ledger')->table('product_ledgers')
            ->where('transaction_type', 'IN')
            ->where('remarks', 'like', 'Sales Return Good Items%')
            ->select('product_id', 'transaction_number', 'quantity_in')
            ->get();

        // Get all product_ledgers restored junk entries (subtract from junk qty)
        $restoredEntries = DB::connection('ledger')->table('product_ledgers')
            ->where('transaction_type', 'IN')
            ->where('remarks', 'like', 'Restored from Junk%')
            ->select('product_id', DB::raw('SUM(quantity_in) as restored_qty'))
            ->groupBy('product_id')
            ->get();

        // Build lookup: product_id|transaction_number => good_qty
        $goodMap = [];
        foreach ($goodEntries as $entry) {
            $key = $entry->product_id . '|' . $entry->transaction_number;
            $goodMap[$key] = ($goodMap[$key] ?? 0) + (int) $entry->quantity_in;
        }

        // Build lookup: product_id => restored_qty
        $restoredMap = [];
        foreach ($restoredEntries as $entry) {
            $restoredMap[(int) $entry->product_id] = (int) $entry->restored_qty;
        }

        // Compute junk per unique product, subtracting restored quantities
        $junkMap = [];
        foreach ($returnItems as $item) {
            $key = $item->product_id . '|' . $item->return_number;
            $goodQty = $goodMap[$key] ?? 0;
            $rawJunkQty = (int) $item->quantity - (int) $goodQty;
            if ($rawJunkQty > 0) {
                $pk = (int) $item->product_id;
                if (!isset($junkMap[$pk])) {
                    $junkMap[$pk] = [
                        'product_id' => $pk,
                        'product_code' => $item->product_code ?? '',
                        'part_number' => $item->part_number ?? '',
                        'description' => $item->description ?? '',
                        'application' => $item->application ?? '',
                        'total_qty' => 0,
                        'good_qty' => 0,
                        'raw_junk_qty' => 0,
                        'junk_qty' => 0,
                    ];
                }
                $junkMap[$pk]['total_qty'] += (int) $item->quantity;
                $junkMap[$pk]['good_qty'] += $goodQty;
                $junkMap[$pk]['raw_junk_qty'] += $rawJunkQty;
            }
        }

        // Subtract already-restored quantities from junk qty
        foreach ($junkMap as $pk => &$junk) {
            $alreadyRestored = $restoredMap[$pk] ?? 0;
            $junk['junk_qty'] = max(0, $junk['raw_junk_qty'] - $alreadyRestored);
        }
        unset($junk);

        // Remove items where junk_qty hit zero after subtracting restored
        $junkMap = array_filter($junkMap, function ($j) {
            return $j['junk_qty'] > 0;
        });

        $junkItems = array_values($junkMap);

        // Compute stats
        $totalJunkItems = count($junkItems);
        $totalJunkQty = array_sum(array_column($junkItems, 'junk_qty'));
        $categories = array_unique(array_filter(array_column($junkItems, 'application')));
        $totalCategories = count($categories);

        // Restored today count
        $restoredToday = DB::connection('ledger')->table('product_ledgers')
            ->where('remarks', 'like', 'Restored from Junk%')
            ->whereDate('created_at', now()->toDateString())
            ->sum('quantity_in');

        return response()->json([
            'success' => true,
            'junk_items' => $junkItems,
            'stats' => [
                'total_items' => $totalJunkItems,
                'total_qty' => $totalJunkQty,
                'total_categories' => $totalCategories,
                'restored_today' => (int) $restoredToday,
            ],
        ]);
    } catch (\Exception $e) {
        return response()->json(['success' => false, 'message' => $e->getMessage()], 500);
    }
})->name('admin.sales-junk.data');

// Sales Junk Items Restore
Route::post('/admin/inventory/sales-junk/restore', function (Request $request) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

    try {
        $productId = (int) $request->input('product_id');
        $junkQty = (int) $request->input('junk_qty');
        if ($productId <= 0 || $junkQty <= 0) {
            return response()->json(['success' => false, 'message' => 'Invalid product or quantity'], 422);
        }

        $product = \App\Models\Product::on('masterlist')
            ->where('id', $productId)
            ->lockForUpdate()
            ->first();

        if (!$product) {
            return response()->json(['success' => false, 'message' => 'Product not found'], 404);
        }

        $currentStock = (int) $product->on_hand;
        $newBalance = $currentStock + $junkQty;

        \App\Models\ProductLedger::create([
            'product_id' => $productId,
            'customer_id' => null,
            'transaction_type' => 'IN',
            'date' => now()->toDateString(),
            'transaction_number' => 'JUNK-RESTORE-' . now()->format('YmdHis'),
            'reference_number' => '',
            'entity_name' => '',
            'quantity_in' => $junkQty,
            'quantity_out' => 0,
            'balance_stock' => $newBalance,
            'oum' => 'PCS',
            'price' => (float) ($product->price ?? 0),
            'cost' => (float) ($product->cost ?? 0),
            'remarks' => 'Restored from Junk - Sales Return',
        ]);

        $product->on_hand = $newBalance;
        $product->save();

        return response()->json([
            'success' => true,
            'message' => 'Item restored successfully',
            'new_balance' => $newBalance,
        ]);
    } catch (\Exception $e) {
        if (DB::connection('ledger')->transactionLevel() > 0) DB::connection('ledger')->rollBack();
        if (DB::connection('masterlist')->transactionLevel() > 0) DB::connection('masterlist')->rollBack();
        return response()->json(['success' => false, 'message' => $e->getMessage()], 500);
    }
})->name('admin.sales-junk.restore');

