// Purchase Order Active List API
Route::get('/admin/purchase/purchase-order/active', function (Request $request) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

    try {

    $search = $request->query('search', []);
    $page = (int) $request->query('page', 1);
    $perPage = min(50, max(1, (int) $request->query('perPage', $request->query('per_page', 50))));

    $query = \App\Models\PurchaseNote::with('supplier')
        ->whereNotIn('status', ['Closed']);

    // Supplier lives in core4_masterlist, while Purchase Notes live in core4_purchase.
    // Do not use whereHas() here: Eloquent would generate a subquery against
    // `suppliers` on the purchase connection and cause a 500 during search.
    if (!empty($search['supplierCode']) || !empty($search['name'])) {
        $supplierQuery = DB::connection('masterlist')->table('suppliers')->select('id');
        if (!empty($search['supplierCode'])) {
            $supplierQuery->where('supplier_code', 'LIKE', '%' . trim((string) $search['supplierCode']) . '%');
        }
        if (!empty($search['name'])) {
            $supplierQuery->where('name', 'LIKE', '%' . trim((string) $search['name']) . '%');
        }
        $supplierIds = $supplierQuery->pluck('id')->map(fn ($id) => (int) $id)->all();
        $supplierIds ? $query->whereIn('supplier_id', $supplierIds) : $query->whereRaw('1 = 0');
    }
    if (!empty($search['transNo'])) {
        $query->where('reference_number', 'LIKE', '%' . $search['transNo'] . '%');
    }
    if (!empty($search['date'])) {
        $query->where('date', 'LIKE', '%' . $search['date'] . '%');
    }
    if (!empty($search['currency'])) {
        $query->where('currency', 'LIKE', '%' . $search['currency'] . '%');
    }
    if (!empty($search['status'])) {
        $query->where('status', 'LIKE', '%' . $search['status'] . '%');
    }

    $totalMatching = $query->count();
    $lastPage = max(1, (int) ceil($totalMatching / $perPage));
    $page = max(1, min($page, $lastPage));
    $skip = ($page - 1) * $perPage;

    $orders = $query->orderBy('created_at', 'desc')->skip($skip)->take($perPage)->get();

    $orderLinkKeys = $orders->flatMap(function ($order) {
        return collect([
            (string) ($order->purchase_note_number ?? ''),
            (string) ($order->reference_number ?? ''),
        ])->filter();
    })->unique()->values();

    $existingInvoiceMap = \App\Models\PurchaseOrder::query()
        ->select('reference_number', 'supplier_invoice_number')
        ->whereIn('reference_number', $orderLinkKeys)
        ->whereNotNull('supplier_invoice_number')
        ->get()
        ->groupBy('reference_number')
        ->map(function ($rows) {
            return $rows->flatMap(function ($row) {
                return collect(explode(',', (string) ($row->supplier_invoice_number ?? '')))
                    ->map(fn ($invoice) => trim((string) $invoice))
                    ->filter();
            })->unique()->values()->all();
        });

    return response()->json([
        'success' => true,
        'orders' => $orders->map(function ($o) use ($existingInvoiceMap) {
            return [
                'id' => $o->id,
                'supplierCode' => $o->supplier ? $o->supplier->supplier_code : '---',
                'name' => $o->supplier ? $o->supplier->name : '---',
                'transNo' => $o->reference_number ?? $o->purchase_note_number,
                'date' => $o->date,
                'status' => $o->status,
                'po_number' => $o->purchase_note_number,
                'total_amount' => $o->total_amount,
                'actual_total_amount' => $o->total_amount,
                'remarks' => $o->remarks,
                'receiving_number' => '',
                'currency' => $o->currency ?? 'PHP',
                'conversion_rate' => $o->conversion_rate,
                'existing_invoice_numbers' => collect([
                    ...$existingInvoiceMap->get((string) ($o->reference_number ?? ''), []),
                    ...$existingInvoiceMap->get((string) ($o->purchase_note_number ?? ''), []),
                ])->filter()->unique()->values()->all(),
            ];
        }),
        'pagination' => [
            'current_page' => $page,
            'last_page' => $lastPage,
            'per_page' => $perPage,
            'total' => $totalMatching,
            'from' => $totalMatching > 0 ? $skip + 1 : 0,
            'to' => min($skip + $perPage, $totalMatching),
        ],
    ]);
    } catch (\Throwable $e) {
        Log::error('Purchase Order active search error: ' . $e->getMessage());
        return response()->json(['success' => false, 'message' => $e->getMessage()], 500);
    }
})->name('admin.purchase-order.active');

// Purchase Order History List API
Route::get('/admin/purchase/purchase-order/history', function (Request $request) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

    try {

    $search = $request->query('search', []);
    $page = (int) $request->query('page', 1);
    $perPage = min(50, max(1, (int) $request->query('perPage', $request->query('per_page', 50))));

    $query = \App\Models\PurchaseOrder::with('supplier');

    // Column search
    $colMap = [
        'date' => 'date',
        'recNo' => 'receiving_number',
        'poNo' => 'po_number',
        'invNo' => 'supplier_invoice_number',
        'remarks' => 'remarks',
    ];
    foreach ($colMap as $key => $col) {
        if (!empty($search[$key])) {
            $query->where($col, 'LIKE', '%' . $search[$key] . '%');
        }
    }
    if (!empty($search['name'])) {
        // Supplier is stored on the masterlist connection. Resolve matching IDs there
        // first instead of issuing a cross-connection whereHas() subquery.
        $supplierIds = DB::connection('masterlist')->table('suppliers')
            ->where('name', 'LIKE', '%' . trim((string) $search['name']) . '%')
            ->pluck('id')
            ->map(fn ($id) => (int) $id)
            ->all();
        $supplierIds ? $query->whereIn('supplier_id', $supplierIds) : $query->whereRaw('1 = 0');
    }
    if (!empty($search['totalAmount'])) {
        $amountSearch = preg_replace('/[^0-9.\-]/', '', (string) $search['totalAmount']);
        if ($amountSearch !== '') {
            $query->whereRaw('CAST(actual_total_amount AS CHAR) LIKE ?', ['%' . $amountSearch . '%']);
        }
    }

    $totalMatching = $query->count();
    $lastPage = max(1, (int) ceil($totalMatching / $perPage));
    $page = max(1, min($page, $lastPage));
    $skip = ($page - 1) * $perPage;

    $orders = $query->orderBy('created_at', 'desc')->skip($skip)->take($perPage)->get();

    return response()->json([
        'success' => true,
        'orders' => $orders->map(function ($o) {
            $currency = $o->currency ?? 'PHP';
            $convRate = $o->conversion_rate ?? 1;
            return [
                'id' => $o->id,
                'date' => $o->date,
                'receivingNo' => $o->receiving_number,
                'poNo' => $o->po_number,
                'supplierInvoice' => $o->supplier_invoice_number,
                'name' => $o->supplier ? $o->supplier->name : '---',
                'totalAmount' => $o->actual_total_amount,
                'orderedTotalAmount' => $o->total_amount,
                'actualAmount' => $o->actual_total_amount,
                'additional_discount_percent' => $o->additional_discount_percent ?? 0,
                'additional_discount_amount' => $o->additional_discount_amount ?? 0,
                'remarks' => $o->remarks,
                'currency' => $currency,
                'conversionRate' => $convRate,
                'displayTotal' => $currency === 'PHP' ? $o->actual_total_amount : $o->actual_total_amount / $convRate,
                'displayActual' => $currency === 'PHP' ? $o->actual_total_amount : $o->actual_total_amount / $convRate,
            ];
        }),
        'pagination' => [
            'current_page' => $page,
            'last_page' => $lastPage,
            'per_page' => $perPage,
            'total' => $totalMatching,
            'from' => $totalMatching > 0 ? $skip + 1 : 0,
            'to' => min($skip + $perPage, $totalMatching),
        ],
    ]);
    } catch (\Throwable $e) {
        Log::error('Purchase Order history search error: ' . $e->getMessage());
        return response()->json(['success' => false, 'message' => $e->getMessage()], 500);
    }
})->name('admin.purchase-order.history');

// Fetch Purchase Order Items for History View Modal
Route::get('/admin/purchase/purchase-order/po-items/{poId}', function (Request $request, $poId) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

    try {
        $po = \App\Models\PurchaseOrder::with(['items.product', 'supplier'])->find($poId);
        if (!$po) {
            return response()->json(['success' => false, 'message' => 'Purchase order not found'], 404);
        }

        $currency = $po->currency ?? 'PHP';
        $convRate = (float) ($po->conversion_rate ?? 1);
        if ($convRate <= 0) $convRate = 1;

        // No schema column is needed for arrangement.  Resolve the linked Purchase
        // Note and derive its line order from the existing purchase_note_items IDs.
        // PO quantities/costs are never changed by this ordering operation.
        $purchaseNote = \App\Models\PurchaseNote::where(function ($query) use ($po) {
            $reference = trim((string) ($po->reference_number ?? ''));
            $query->where('purchase_note_number', $reference)
                ->orWhere('reference_number', $reference);
        })->first();

        $normalizeCode = fn ($value) => mb_strtolower(preg_replace('/\s+/u', ' ', trim((string) $value)) ?? '');
        $pnOrderByProductId = [];
        $pnOrderByCode = [];

        if ($purchaseNote) {
            $pnRows = \App\Models\PurchaseNoteItem::where('purchase_note_id', $purchaseNote->id)
                ->orderBy('id')
                ->get(['id', 'product_id', 'product_code']);

            foreach ($pnRows as $position => $pnItem) {
                $order = $position + 1;
                $productId = (int) ($pnItem->product_id ?? 0);
                if ($productId > 0 && !isset($pnOrderByProductId[$productId])) {
                    $pnOrderByProductId[$productId] = $order;
                }

                $code = $normalizeCode($pnItem->product_code ?? '');
                if ($code !== '' && !isset($pnOrderByCode[$code])) {
                    $pnOrderByCode[$code] = $order;
                }
            }
        }

        $poItems = $po->items
            ->map(function ($item, $originalIndex) use ($pnOrderByProductId, $pnOrderByCode, $normalizeCode) {
                $productId = (int) ($item->product_id ?? 0);
                $code = $normalizeCode($item->product_code ?? '');
                $pnOrder = $productId > 0 ? ($pnOrderByProductId[$productId] ?? null) : null;
                if ($pnOrder === null && $code !== '') {
                    $pnOrder = $pnOrderByCode[$code] ?? null;
                }
                $item->setAttribute('_pn_order', $pnOrder);
                $item->setAttribute('_original_order', $originalIndex);
                return $item;
            })
            ->sort(function ($a, $b) {
                $aOrder = $a->getAttribute('_pn_order');
                $bOrder = $b->getAttribute('_pn_order');
                $aMatched = $aOrder !== null;
                $bMatched = $bOrder !== null;

                if ($aMatched && $bMatched && $aOrder !== $bOrder) return $aOrder <=> $bOrder;
                if ($aMatched !== $bMatched) return $aMatched ? -1 : 1;

                // Different/unmatched PO items are deliberately left in their
                // original PO sequence after all PN-matched items.
                return ((int) $a->getAttribute('_original_order')) <=> ((int) $b->getAttribute('_original_order'));
            })
            ->values();

        $items = $poItems->map(function ($item) use ($currency, $convRate) {
            $actualQty = (float) ($item->actual_quantity ?? $item->quantity ?? 0);
            $unitPrice = (float) ($item->unit_price ?? 0);
            $discountPercent = (float) ($item->discount_percent ?? 0);
            $actualDiscountAmount = ($actualQty * $unitPrice) * ($discountPercent / 100);
            $actualSubtotalPHP = (float) ($item->actual_subtotal ?? (($actualQty * $unitPrice) - $actualDiscountAmount));
            $actualSubtotalDisplay = $currency === 'PHP' ? $actualSubtotalPHP : $actualSubtotalPHP / $convRate;
            $product = $item->product;
            $partNumber = trim((string) ($product?->part_number ?? ''));
            $description = trim((string) ($item->description ?? ''));

            if ($description === '') {
                $description = trim((string) ($product?->description ?? ''));
            }

            return [
                'id' => $item->id,
                'product_id' => $item->product_id,
                'product_code' => trim((string) ($item->product_code ?? '')) !== '' ? $item->product_code : ($product?->product_code ?? ''),
                'part_number' => $partNumber,
                'description' => $description,
                'quantity' => (float) ($item->quantity ?? 0),
                'actual_quantity' => $actualQty,
                'unit_price' => $unitPrice,
                'unit_price_converted' => (float) ($item->unit_price_converted ?? 0),
                'discount_percent' => $discountPercent,
                // History is an actual receiving record, so discount/subtotal are
                // based on Actual QTY, not the original/requested QTY.
                'discount_amount' => $actualDiscountAmount,
                'ordered_subtotal' => (float) ($item->subtotal ?? 0),
                'actual_subtotal' => $actualSubtotalPHP,
                'subtotal' => $actualSubtotalPHP,
                'subtotal_display' => $actualSubtotalDisplay,
                'currency' => $item->currency ?? $currency,
                'unit' => $item->unit ?? '',
                'pn_order' => $item->getAttribute('_pn_order'),
            ];
        });

        $invoiceNumbers = array_filter(explode(',', (string) ($po->supplier_invoice_number ?? '')));
        $invoiceNumbers = array_values(array_map('trim', $invoiceNumbers));

        return response()->json([
            'success' => true,
            'items' => $items,
            'note' => [
                'id' => $po->id,
                'supplier_code' => $po->supplier ? $po->supplier->supplier_code : '',
                'supplier_name' => $po->supplier ? $po->supplier->name : '',
                'receiving_no' => $po->receiving_number ?? '',
                'po_number' => $po->po_number ?? '',
                'purchase_note_number' => $po->reference_number ?? '',
                'currency' => $currency,
                'conversion_rate' => $convRate,
                'additional_discount_percent' => (float) ($po->additional_discount_percent ?? 0),
                'invoice_numbers' => $invoiceNumbers,
            ],
        ]);
    } catch (\Exception $e) {
        return response()->json(['success' => false, 'message' => $e->getMessage()], 500);
    }
})->name('admin.purchase-order.po-items');

// Fetch Purchase Note Items for Processing Modal
Route::get('/admin/purchase/purchase-order/items/{purchaseNoteId}', function (Request $request, $purchaseNoteId) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

    try {
        $purchaseNote = \App\Models\PurchaseNote::find($purchaseNoteId);
        if (!$purchaseNote) {
            return response()->json(['success' => false, 'message' => 'Purchase note not found'], 404);
        }

        $purchaseOrderLinkValues = collect([
            (string) ($purchaseNote->reference_number ?? ''),
            (string) ($purchaseNote->purchase_note_number ?? ''),
        ])->filter()->unique()->values();

        $relatedPurchaseOrders = \App\Models\PurchaseOrder::with('items')
            ->whereIn('reference_number', $purchaseOrderLinkValues)
            ->orderBy('id', 'asc')
            ->get();

        $existingInvoices = $relatedPurchaseOrders
            ->pluck('supplier_invoice_number')
            ->flatMap(function ($invoiceText) {
                return collect(explode(',', (string) $invoiceText))
                    ->map(fn ($invoice) => trim((string) $invoice))
                    ->filter();
            })
            ->unique()
            ->values()
            ->all();

        // purchase_note_items.quantity is the authoritative current remainder.
        // Historical PO quantity rows are snapshots of each partial transaction and
        // must never be summed as though they were separate original orders.
        // Zero-QTY rows can be intentional placeholders on a newly created
        // Purchase Note. Keep them available in the Proceed modal until that
        // specific product has actually been processed by a Purchase Order.
        // Fully processed zero-balance rows remain hidden.
        $latestProcessedAtByProductId = [];
        $latestProcessedAtByCode = [];
        foreach ($relatedPurchaseOrders as $relatedPurchaseOrder) {
            $processedAt = $relatedPurchaseOrder->updated_at ?? $relatedPurchaseOrder->created_at;
            foreach ($relatedPurchaseOrder->items as $processedItem) {
                $processedProductId = (int) ($processedItem->product_id ?? 0);
                if ($processedProductId > 0) {
                    $latestProcessedAtByProductId[$processedProductId] = $processedAt;
                }

                $processedCode = mb_strtolower(preg_replace('/\s+/u', ' ', trim((string) ($processedItem->product_code ?? ''))) ?? '');
                if ($processedCode !== '') {
                    $latestProcessedAtByCode[$processedCode] = $processedAt;
                }
            }
        }

        $activeNoteItems = \App\Models\PurchaseNoteItem::where('purchase_note_id', $purchaseNoteId)
            ->withoutForceCancelled()
            ->orderBy('id')
            ->get()
            ->filter(function ($item) use ($latestProcessedAtByProductId, $latestProcessedAtByCode) {
                if ((float) ($item->quantity ?? 0) > 0) {
                    return true;
                }

                $productId = (int) ($item->product_id ?? 0);
                $normalizedCode = mb_strtolower(preg_replace('/\s+/u', ' ', trim((string) ($item->product_code ?? ''))) ?? '');
                $processedAt = $productId > 0
                    ? ($latestProcessedAtByProductId[$productId] ?? null)
                    : null;

                if (!$processedAt && $normalizedCode !== '') {
                    $processedAt = $latestProcessedAtByCode[$normalizedCode] ?? null;
                }

                // Never processed: this is a valid zero-QTY placeholder line.
                if (!$processedAt) {
                    return true;
                }

                // If the Purchase Note item was added/edited after the last PO
                // snapshot for this product, treat it as a new unprocessed line.
                return $item->updated_at && $item->updated_at->gt($processedAt);
            })
            ->values();

        $productIds = $activeNoteItems->pluck('product_id')->filter()->unique()->values();
        $productsById = \App\Models\Product::on('masterlist')
            ->whereIn('id', $productIds)
            ->get()
            ->keyBy('id');

        $items = $activeNoteItems
            ->groupBy(function ($item) {
                if ((int) ($item->product_id ?? 0) > 0) {
                    return 'id:' . (int) $item->product_id;
                }

                return 'code:' . mb_strtolower(preg_replace('/\s+/u', ' ', trim((string) $item->product_code)) ?? '');
            })
            ->map(function ($group) use ($productsById) {
                $first = $group->first();
                $last = $group->last();
                $product = $productsById->get($first->product_id);
                $quantity = (float) $group->sum('quantity');
                $unitPrice = (float) ($last->unit_price ?? 0);
                $partNumber = trim((string) ($first->part_number ?? ''));
                $description = trim((string) ($first->description ?? ''));

                if ($partNumber === '') {
                    $partNumber = trim((string) ($product?->part_number ?? ''));
                }
                if ($description === '') {
                    $description = trim((string) ($product?->description ?? ''));
                }

                return [
                    'id' => $first->id,
                    'product_id' => $first->product_id,
                    'product_code' => trim((string) ($first->product_code ?? '')) !== '' ? $first->product_code : ($product?->product_code ?? ''),
                    'part_number' => $partNumber,
                    'description' => $description,
                    'quantity' => $quantity,
                    'actual_quantity' => $quantity,
                    'unit_price' => $unitPrice,
                    'total_price' => $quantity * $unitPrice,
                    'currency' => $last->currency ?? 'PHP',
                    'conversion_rate' => $last->conversion_rate,
                    'unit_price_converted' => $last->unit_price_converted,
                    'total_price_converted' => $last->total_price_converted,
                    'unit' => $last->unit ?? ($product?->unit ?? ''),
                    'pn_order' => (int) $group->min('id'),
                ];
            })
            ->sortBy('pn_order')
            ->values();

        $statusResult = app(\App\Services\PurchaseNoteStatusService::class)
            ->syncFromRemainingItems($purchaseNote);
        $purchaseNote->refresh();

        return response()->json([
            'success' => true,
            'note' => [
                'id' => $purchaseNote->id,
                'purchase_note_number' => $purchaseNote->purchase_note_number,
                'date' => $purchaseNote->date,
                'supplier_code' => $purchaseNote->supplier->supplier_code ?? '',
                'supplier_name' => $purchaseNote->supplier->name ?? '',
                'total_amount' => $purchaseNote->total_amount,
                'status' => $purchaseNote->status,
                'reference_number' => $purchaseNote->reference_number,
                'existing_invoice_numbers' => $existingInvoices,
                'currency' => $purchaseNote->currency ?? 'PHP',
                'conversion_rate' => $purchaseNote->conversion_rate,
            ],
            'items' => $items,
        ]);
    } catch (\Exception $e) {
        return response()->json(['success' => false, 'message' => $e->getMessage()], 500);
    }
})->name('admin.purchase-order.items');

Route::post('/admin/purchase/purchase-order/force-close/{purchaseNoteId}/passcode', function (Request $request, $purchaseNoteId) {
    $user = session('user');
    if (!$user) return response()->json(['success' => false, 'message' => 'Unauthorized'], 403);

    // Backward-compatible endpoint only. Purchase Note force close no longer
    // requires or generates a passcode.
    try {
        $result = app(\App\Services\PurchaseNoteForceCloseService::class)
            ->generatePasscode((int) $purchaseNoteId, $user);

        return response()->json([
            'success' => true,
            'passcode_required' => false,
            'passcode' => null,
            'expires_at' => null,
            'summary' => $result['summary'],
        ]);
    } catch (\Throwable $error) {
        return response()->json(['success' => false, 'message' => $error->getMessage()], 422);
    }
})->name('admin.purchase-order.force-close.passcode');

Route::post('/admin/purchase/purchase-order/force-close/{purchaseNoteId}', function (Request $request, $purchaseNoteId) {
    $user = session('user');
    if (!$user) return response()->json(['success' => false, 'message' => 'Unauthorized'], 403);

    try {
        $result = app(\App\Services\PurchaseNoteForceCloseService::class)
            ->forceClose((int) $purchaseNoteId, $user, $request);

        return response()->json([
            'success' => true,
            'message' => 'Purchase Note force closed successfully.',
            'purchase_note_number' => $result['purchase_note_number'],
            'force_close_reference' => $result['force_close_reference'],
            'deleted_remaining_item_count' => $result['deleted_remaining_item_count'],
            'deleted_remaining_quantity' => $result['deleted_remaining_quantity'],
            'summary' => $result['summary'],
        ]);
    } catch (\Throwable $error) {
        \Log::error('Purchase Note force close failed.', [
            'purchase_note_id' => (int) $purchaseNoteId,
            'error' => $error->getMessage(),
        ]);

        return response()->json([
            'success' => false,
            'message' => 'Unable to force close Purchase Note: ' . $error->getMessage(),
        ], 422);
    }
})->name('admin.purchase-order.force-close.submit');

// Fetch Purchase Orders linked to a Purchase Note (by note number)
Route::get('/admin/purchase/purchase-order/by-note/{purchaseNoteNumber}', function ($purchaseNoteNumber) {
    try {
        $note = \App\Models\PurchaseNote::where('purchase_note_number', $purchaseNoteNumber)->first();
        if ($note && strcasecmp((string) $note->status, 'Closed') !== 0) {
            app(\App\Services\PurchaseNoteStatusService::class)->syncFromRemainingItems($note);
            $note->refresh();
        }
        $noteStatus = $note ? $note->status : null;

        $purchaseOrders = \App\Models\PurchaseOrder::where('reference_number', $purchaseNoteNumber)
            ->orderBy('date', 'desc')
            ->get(['id', 'po_number', 'receiving_number', 'supplier_invoice_number', 'date', 'status']);

        // For closed notes, use the note's status for all POs; otherwise show real PO status
        if ($noteStatus && strtoupper($noteStatus) === 'CLOSED') {
            $purchaseOrders->each(function ($po) use ($noteStatus) {
                $po->status = $noteStatus;
            });
        }

        // Use current Purchase Note item quantities directly. They already store
        // the unreceived balance after every processing transaction.
        $remainingItems = [];
        if ($note && strtoupper((string) $note->status) !== 'CLOSED') {
            $pnItems = \App\Models\PurchaseNoteItem::where('purchase_note_id', $note->id)
                ->withoutForceCancelled()
                ->where('quantity', '>', 0)
                ->orderBy('id')
                ->get();

            $productIds = $pnItems->pluck('product_id')->filter()->unique()->values();
            $productsById = \App\Models\Product::on('masterlist')
                ->whereIn('id', $productIds)
                ->get()
                ->keyBy('id');

            $remainingItems = $pnItems
                ->groupBy(function ($item) {
                    if ((int) ($item->product_id ?? 0) > 0) {
                        return 'id:' . (int) $item->product_id;
                    }

                    return 'code:' . mb_strtolower(preg_replace('/\s+/u', ' ', trim((string) $item->product_code)) ?? '');
                })
                ->map(function ($group) use ($productsById) {
                    $first = $group->first();
                    $last = $group->last();
                    $product = $productsById->get($first->product_id);
                    $quantity = (float) $group->sum('quantity');
                    $partNumber = trim((string) ($first->part_number ?? '')) ?: trim((string) ($product?->part_number ?? ''));
                    $description = trim((string) ($first->description ?? '')) ?: trim((string) ($product?->description ?? ''));

                    return [
                        'id' => $first->id,
                        'product_id' => $first->product_id,
                        'product_code' => trim((string) ($first->product_code ?? '')) !== '' ? $first->product_code : ($product?->product_code ?? ''),
                        'part_number' => $partNumber,
                        'description' => $description,
                        'quantity' => $quantity,
                        'unit_price' => (float) ($last->unit_price ?? 0),
                        'unit' => $last->unit ?? ($product?->unit ?? ''),
                    ];
                })
                ->filter(fn ($item) => (float) ($item['quantity'] ?? 0) > 0)
                ->values()
                ->all();

            $hasPartial = $purchaseOrders->contains(fn ($po) => strtoupper((string) $po->status) === 'PARTIAL');
            if ($hasPartial && count($remainingItems) > 0) {
                $purchaseOrders->push((object) [
                    'id' => 0,
                    'po_number' => $purchaseNoteNumber,
                    'receiving_number' => '',
                    'supplier_invoice_number' => '',
                    'date' => null,
                    'status' => 'Open',
                ]);
            }
        }

        return response()->json([
            'success' => true,
            'invoices' => $purchaseOrders,
            'note_status' => $noteStatus,
            'remaining_items' => $remainingItems,
        ]);
    } catch (\Exception $e) {
        return response()->json(['success' => false, 'message' => $e->getMessage()], 500);
    }
})->name('admin.purchase-order.by-note');

// Fetch Purchase Order Detail with Items (for editing)
Route::get('/admin/purchase/purchase-order/detail/{poId}', function ($poId) {
    try {
        $po = \App\Models\PurchaseOrder::with(['items.product', 'supplier'])->findOrFail($poId);

        return response()->json([
            'success' => true,
            'po' => [
                'id' => $po->id,
                'po_number' => $po->po_number,
                'receiving_number' => $po->receiving_number,
                'supplier_invoice_number' => $po->supplier_invoice_number,
                'supplier_id' => $po->supplier_id,
                'supplier_code' => $po->supplier?->supplier_code ?? '',
                'supplier_name' => $po->supplier?->name ?? '',
                'date' => $po->date,
                'currency' => $po->currency,
                'conversion_rate' => $po->conversion_rate,
                'additional_discount_percent' => $po->additional_discount_percent,
                'additional_discount_amount' => $po->additional_discount_amount,
                'total_amount' => $po->total_amount,
                'actual_total_amount' => $po->actual_total_amount,
                'status' => $po->status,
                'remarks' => $po->remarks,
                'reference_number' => $po->reference_number,
            ],
            'items' => $po->items->map(function ($item) {
                $product = $item->product;
                $description = trim((string) ($item->description ?? ''));
                if ($description === '') {
                    $description = trim((string) ($product?->description ?? ''));
                }

                return [
                    'id' => $item->id,
                    'product_id' => $item->product_id ?? null,
                    'product_code' => trim((string) ($item->product_code ?? '')) !== '' ? $item->product_code : ($product?->product_code ?? ''),
                    'part_number' => trim((string) ($product?->part_number ?? '')),
                    'description' => $description,
                    'quantity' => $item->quantity,
                    'actual_quantity' => $item->actual_quantity,
                    'received_quantity' => $item->received_quantity,
                    'unit_price' => $item->unit_price,
                    'discount_percent' => $item->discount_percent ?? 0,
                    'discount_amount' => $item->discount_amount ?? 0,
                    'subtotal' => $item->subtotal,
                    'actual_subtotal' => $item->actual_subtotal,
                    'unit' => $item->unit ?? '',
                ];
            })
        ]);
    } catch (\Exception $e) {
        return response()->json(['success' => false, 'message' => $e->getMessage()], 500);
    }
})->name('admin.purchase-order.detail');

// Process Purchase Order
Route::post('/admin/purchase/purchase-order/process', function (Request $request) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

    try {
        $data = $request->validate([
            'po_number' => 'required|string',
            'supplier_invoice_number' => 'nullable|string',
            'trans_no' => 'required|string', // This is PN Number from Active PO
            'supplier_code' => 'required|string',
            'date' => 'required|date',
            'total_amount' => 'required|numeric',
            'actual_total_amount' => 'required|numeric',
            'additional_discount_percent' => 'nullable|numeric',
            'additional_discount_amount' => 'nullable|numeric',
            'currency' => 'nullable|string|max:10',
            'conversion_rate' => 'nullable|numeric|min:0',
            'remarks' => 'nullable|string',
            'items' => 'required|array',
            'items.*.product_id' => 'nullable|integer',
            'items.*.product_code' => 'required|string',
            'items.*.part_number' => 'nullable|string',
            'items.*.description' => 'nullable|string',
            'items.*.quantity' => 'required|numeric',
            'items.*.actual_quantity' => 'required|numeric',
            'items.*.unit_price' => 'required|numeric',
            'items.*.discount_percent' => 'nullable|numeric',
            'items.*.discount_amount' => 'nullable|numeric',
            'items.*.unit' => 'nullable|string|max:50',
            'items.*.subtotal' => 'required|numeric',
            'items.*.actual_subtotal' => 'required|numeric',
        ]);

        $data['items'] = collect($data['items'])
            ->filter(fn ($item) => trim((string) ($item['product_code'] ?? '')) !== '')
            ->values()
            ->all();

        if (empty($data['items'])) {
            throw new \Exception('Please select at least one item to process.');
        }

        return DB::connection('purchase')->transaction(function () use ($data, $user) {
            $normalizePurchaseItemText = function ($value) {
                return preg_replace('/\s+/', ' ', trim((string) $value));
            };

            $roundMoney = fn ($value) => round((float) $value, 2);

            // 1. Find Supplier
            $supplier = \App\Models\Supplier::where('supplier_code', $data['supplier_code'])->first();
            if (!$supplier) throw new \Exception("Supplier with code {$data['supplier_code']} not found.");

            // 2. Find the original Purchase Note (using trans_no which is purchase_note_number)
            $purchaseNote = \App\Models\PurchaseNote::where(function ($query) use ($data) {
                $query->where('purchase_note_number', $data['trans_no'])
                    ->orWhere('reference_number', $data['trans_no']);
            })->first();
            if (!$purchaseNote) throw new \Exception("Original Purchase Note {$data['trans_no']} not found.");
            $purchaseNoteBefore = $purchaseNote->toArray();

            // Keep every new Purchase Order in the same item arrangement as its
            // Purchase Note.  This is derived from existing PN item IDs and does
            // not require an arrangement/order column in the database.
            $pnOrderByProductId = [];
            $pnOrderByCode = [];
            $pnOrderRows = \App\Models\PurchaseNoteItem::where('purchase_note_id', $purchaseNote->id)
                ->orderBy('id')
                ->get(['id', 'product_id', 'product_code']);
            foreach ($pnOrderRows as $position => $pnOrderItem) {
                $order = $position + 1;
                $productId = (int) ($pnOrderItem->product_id ?? 0);
                if ($productId > 0 && !isset($pnOrderByProductId[$productId])) {
                    $pnOrderByProductId[$productId] = $order;
                }
                $normalizedCode = mb_strtolower(preg_replace('/\s+/u', ' ', trim((string) ($pnOrderItem->product_code ?? ''))) ?? '');
                if ($normalizedCode !== '' && !isset($pnOrderByCode[$normalizedCode])) {
                    $pnOrderByCode[$normalizedCode] = $order;
                }
            }

            $data['items'] = collect($data['items'])
                ->map(function ($item, $originalIndex) use ($pnOrderByProductId, $pnOrderByCode) {
                    $productId = (int) ($item['product_id'] ?? 0);
                    $normalizedCode = mb_strtolower(preg_replace('/\s+/u', ' ', trim((string) ($item['product_code'] ?? ''))) ?? '');
                    $pnOrder = $productId > 0 ? ($pnOrderByProductId[$productId] ?? null) : null;
                    if ($pnOrder === null && $normalizedCode !== '') {
                        $pnOrder = $pnOrderByCode[$normalizedCode] ?? null;
                    }
                    $item['_pn_order'] = $pnOrder;
                    $item['_original_order'] = $originalIndex;
                    return $item;
                })
                ->sort(function ($a, $b) {
                    $aOrder = $a['_pn_order'];
                    $bOrder = $b['_pn_order'];
                    $aMatched = $aOrder !== null;
                    $bMatched = $bOrder !== null;
                    if ($aMatched && $bMatched && $aOrder !== $bOrder) return $aOrder <=> $bOrder;
                    if ($aMatched !== $bMatched) return $aMatched ? -1 : 1;
                    return $a['_original_order'] <=> $b['_original_order'];
                })
                ->map(function ($item) {
                    unset($item['_pn_order'], $item['_original_order']);
                    return $item;
                })
                ->values()
                ->all();

            $matchingItem = function ($items, array $incomingItem) use ($normalizePurchaseItemText, $roundMoney) {
                $incomingProductId = !empty($incomingItem['product_id']) ? (int) $incomingItem['product_id'] : null;
                $incomingCode = $normalizePurchaseItemText($incomingItem['product_code'] ?? '');
                $incomingDescription = $normalizePurchaseItemText($incomingItem['description'] ?? '');

                return collect($items)->first(function ($existingItem) use ($incomingProductId, $incomingCode, $incomingDescription, $incomingItem, $normalizePurchaseItemText, $roundMoney) {
                    $sameIdentity = false;
                    if ($incomingProductId && (int) ($existingItem->product_id ?? 0) === $incomingProductId) {
                        $sameIdentity = true;
                    }

                    $existingCode = $normalizePurchaseItemText($existingItem->product_code ?? '');
                    $existingDescription = $normalizePurchaseItemText($existingItem->description ?? '');
                    if (!$sameIdentity && $incomingCode !== '' && $existingCode === $incomingCode) {
                        $sameIdentity = true;
                    }
                    if (!$sameIdentity && $incomingDescription !== '' && $existingDescription === $incomingDescription) {
                        $sameIdentity = true;
                    }

                    return $sameIdentity
                        && (float) ($existingItem->actual_quantity ?? 0) === (float) ($incomingItem['actual_quantity'] ?? 0)
                        && abs($roundMoney($existingItem->actual_subtotal ?? 0) - $roundMoney($incomingItem['actual_subtotal'] ?? 0)) <= 0.01;
                });
            };

            $existingProcessingEvent = \App\Models\PurchaseOrder::with('items')
                ->where('supplier_id', $supplier->id)
                ->where('po_number', $data['po_number'])
                ->where('reference_number', $data['trans_no'])
                ->where('supplier_invoice_number', $data['supplier_invoice_number'])
                ->whereBetween('actual_total_amount', [$roundMoney($data['actual_total_amount']) - 0.01, $roundMoney($data['actual_total_amount']) + 0.01])
                ->latest('id')
                ->get()
                ->first(function ($existingPo) use ($data, $matchingItem) {
                    if ($existingPo->items->count() !== count($data['items'])) {
                        return false;
                    }

                    foreach ($data['items'] as $incomingItem) {
                        if (!$matchingItem($existingPo->items, $incomingItem)) {
                            return false;
                        }
                    }

                    return true;
                });

            if ($existingProcessingEvent) {
                // Repair legacy/stale notes from the old ordering bug as well. At
                // this point a matching Purchase Order already exists, so a note
                // with no remaining items must resolve to Closed.
                $existingStatusResult = app(\App\Services\PurchaseNoteStatusService::class)
                    ->syncFromRemainingItems($purchaseNote, true);
                if ((string) $existingProcessingEvent->status !== (string) $existingStatusResult['status']) {
                    $existingProcessingEvent->update(['status' => $existingStatusResult['status']]);
                }

                $existingSupplierLedger = \App\Models\SupplierLedger::where('source_purchase_order_id', $existingProcessingEvent->id)->first();
                if ($existingSupplierLedger) {
                    $existingChildTotal = $roundMoney($existingSupplierLedger->items()->sum('subtotal'));
                    if (abs($existingChildTotal - $roundMoney($existingSupplierLedger->credit_amount)) <= 0.01) {
                        $costSync = app(\App\Services\PurchaseOrderProductCostSyncService::class)
                            ->syncPurchaseOrder($existingProcessingEvent->id);

                        if (!$costSync['success']) {
                            return response()->json([
                                'success' => false,
                                'message' => 'Purchase Order was already processed, but product cost sync needs retry.',
                                'po_id' => $existingProcessingEvent->id,
                                'status' => $existingProcessingEvent->status,
                                'can_resync' => true,
                                'sync_status' => $costSync,
                            ]);
                        }

                        return response()->json([
                            'success' => true,
                            'message' => 'Purchase Order was already processed successfully',
                            'po_id' => $existingProcessingEvent->id,
                            'status' => $existingProcessingEvent->status,
                            'sync_status' => $costSync,
                        ]);
                    }
                }
            }

            // 3. Apply receipts to every matching active PN row, then derive the
            // header status from the actual remaining quantities.
            $purchaseNoteStatusService = app(\App\Services\PurchaseNoteStatusService::class);

            foreach ($data['items'] as $itemData) {
                $purchaseNoteStatusService->applyReceipt($purchaseNote, $itemData);
            }

            $statusResult = $purchaseNoteStatusService->syncFromRemainingItems($purchaseNote, true);
            $status = $statusResult['status'];
            $newPnTotal = $statusResult['remaining_total'];
            $purchaseNote->refresh();

            // 4. Create Purchase Order (The Transaction Record for History)
            // Generate a unique Receiving Number for this specific transaction
            $recCount = (\App\Models\PurchaseOrder::max('id') ?? 0) + 1;
            $receivingNo = 'REC-' . str_pad($recCount, 7, '0', STR_PAD_LEFT);
            while (\App\Models\PurchaseOrder::where('receiving_number', $receivingNo)->exists()) {
                $recCount++;
                $receivingNo = 'REC-' . str_pad($recCount, 7, '0', STR_PAD_LEFT);
            }

            $po = \App\Models\PurchaseOrder::create([
                'receiving_number' => $receivingNo,
                'po_number' => $data['po_number'], // The 7-digit order number
                'supplier_invoice_number' => $data['supplier_invoice_number'],
                'reference_number' => $data['trans_no'],
                'supplier_id' => $supplier->id,
                'date' => $data['date'],
                'total_amount' => $data['total_amount'],
                'actual_total_amount' => $data['actual_total_amount'],
                'additional_discount_percent' => $data['additional_discount_percent'] ?? 0,
                'additional_discount_amount' => $data['additional_discount_amount'] ?? 0,
                'status' => $status,
                'remarks' => $data['remarks'],
                'currency' => $data['currency'],
                'conversion_rate' => $data['conversion_rate'] ?? 1.0000
            ]);

            // The first status calculation happens before this Purchase Order exists.
            // Re-evaluate immediately after creating the PO so a fully consumed Open
            // Purchase Note is Closed instead of remaining Open simply because it had
            // no PO history a few lines earlier.
            $finalStatusResult = $purchaseNoteStatusService->syncFromRemainingItems($purchaseNote->fresh(), true);
            $status = $finalStatusResult['status'];
            $newPnTotal = $finalStatusResult['remaining_total'];
            $purchaseNote->refresh();
            if ((string) $po->status !== (string) $status) {
                $po->update(['status' => $status]);
            }

            $purchaseOrderLinkValues = collect([
                (string) ($purchaseNote->purchase_note_number ?? ''),
                (string) ($purchaseNote->reference_number ?? ''),
                (string) ($data['trans_no'] ?? ''),
            ])->filter()->unique()->values();

            $historicalPoItems = \App\Models\PurchaseOrderItem::whereHas('purchaseOrder', function ($query) use ($purchaseOrderLinkValues, $po) {
                    $query->whereIn('reference_number', $purchaseOrderLinkValues)
                        ->where('id', '<>', $po->id);
                })
                ->orderBy('id', 'asc')
                ->get();

            $resolveOriginalOrderedQuantity = function (array $itemData) use ($historicalPoItems, $normalizePurchaseItemText) {
                $incomingProductId = !empty($itemData['product_id']) ? (int) $itemData['product_id'] : null;
                $incomingCode = $normalizePurchaseItemText($itemData['product_code'] ?? '');
                $incomingDescription = $normalizePurchaseItemText($itemData['description'] ?? '');

                $historicalItem = $historicalPoItems->first(function ($existingItem) use ($incomingProductId, $incomingCode, $incomingDescription, $normalizePurchaseItemText) {
                    if ($incomingProductId && (int) ($existingItem->product_id ?? 0) === $incomingProductId) {
                        return true;
                    }

                    $existingCode = $normalizePurchaseItemText($existingItem->product_code ?? '');
                    $existingDescription = $normalizePurchaseItemText($existingItem->description ?? '');

                    return ($incomingCode !== '' && $existingCode === $incomingCode)
                        || ($incomingDescription !== '' && $existingDescription === $incomingDescription);
                });

                return $historicalItem ? (float) $historicalItem->quantity : (float) $itemData['quantity'];
            };

            // 5. Create PO Items and Ledger Entries
            $processedPoItems = [];
            foreach ($data['items'] as $itemData) {
                // Find the real master-list product and preserve its printable data.
                $product = null;
                if (!empty($itemData['product_id'])) {
                    $product = \App\Models\Product::on('masterlist')->find((int) $itemData['product_id']);
                }

                if (!$product) {
                    $normalizedIncomingCode = trim((string) ($itemData['product_code'] ?? ''));
                    $product = \App\Models\Product::on('masterlist')
                        ->whereRaw('TRIM(product_code) = ?', [$normalizedIncomingCode])
                        ->first();
                }

                if (!$product) {
                    throw new \Exception('Master-list product not found for ' . ($itemData['product_code'] ?? 'unknown item') . '.');
                }

                $resolvedProductCode = trim((string) ($itemData['product_code'] ?? '')) !== ''
                    ? $itemData['product_code']
                    : $product->product_code;
                $resolvedDescription = trim((string) ($itemData['description'] ?? '')) !== ''
                    ? $itemData['description']
                    : ($product->description ?? '');

                $itemData['product_id'] = $product->id;
                $itemData['product_code'] = $resolvedProductCode;
                $itemData['description'] = $resolvedDescription;

                $originalOrderedQuantity = $resolveOriginalOrderedQuantity($itemData);

                $purchaseOrderItem = \App\Models\PurchaseOrderItem::create([
                    'purchase_order_id' => $po->id,
                    'product_id' => $product->id,
                    'product_code' => $resolvedProductCode,
                    'description' => $resolvedDescription,
                    'quantity' => $itemData['quantity'],
                    'actual_quantity' => $itemData['actual_quantity'],
                    'unit_price' => $itemData['unit_price'],
                    'discount_percent' => $itemData['discount_percent'] ?? 0,
                    'discount_amount' => $itemData['discount_amount'] ?? 0,
                    'subtotal' => $itemData['subtotal'],
                    'actual_subtotal' => $itemData['actual_subtotal'],
                    'unit' => $itemData['unit'] ?? null,
                ]);

                $processedPoItems[] = [
                    'purchase_order_item' => $purchaseOrderItem,
                    'product' => $product,
                    'item_data' => $itemData,
                    'original_quantity' => $originalOrderedQuantity,
                ];

                // Create Product Ledger Entry (IN) - This uses 'ledger' connection
                try {
                    // Get the latest balance from product_ledgers for this product
                    $latestLedger = \App\Models\ProductLedger::where('product_id', $product->id)
                        ->orderBy('id', 'desc')
                        ->first();
                    
                    $previousBalance = $latestLedger ? $latestLedger->balance_stock : 0;
                    $newBalance = $previousBalance + $itemData['actual_quantity'];
                    
                    \App\Models\ProductLedger::create([
                    'product_id' => $product->id,
                    'supplier_id' => $supplier->id,
    'source_type' => 'purchase_order',
    'source_id' => $po->id,
    'source_item_id' => $purchaseOrderItem->id,
    'processed_actual_qty' => (float) $itemData['actual_quantity'],
    'transaction_type' => 'IN',
    'date' => $data['date'],
    'transaction_number' => $po->supplier_invoice_number ?: $po->po_number,
    'reference_number' => $po->supplier_invoice_number ?: $po->reference_number,
    'entity_name' => $supplier->name,
    'quantity_in' => $itemData['actual_quantity'],
    'quantity_out' => 0,
                        'balance_stock' => $newBalance,
                        'oum' => $itemData['unit'] ?? $product->unit,
                        // Purchase Order ledger movements store acquisition cost only.
                        // Leave product_ledgers.price and price_online at their database defaults.
                        'cost' => $itemData['unit_price'],
'remarks' => 'Purchase Order Processing',
'idempotency_key' => 'purchase_order:' . $po->id . ':item:' . $purchaseOrderItem->id,
                    ]);
                } catch (\Exception $ledgerError) {
                    // Log the error but don't stop the transaction
                    \Log::error('ProductLedger creation failed', [
                        'error' => $ledgerError->getMessage(),
                        'product_code' => $itemData['product_code'],
                        'po_number' => $po->po_number
                    ]);
                    throw new \Exception("Failed to create product ledger entry: " . $ledgerError->getMessage());
                }

                // Update product stock
                if ($product) {
                    $product->increment('on_hand', $itemData['actual_quantity']);
                }
            }

            // 6. Create Supplier Ledger Entry (Credit) and child movement rows atomically.
            DB::connection('ledger')->transaction(function () use ($data, $po, $status, $supplier, $processedPoItems, $roundMoney) {
                $parentCreditAmount = $roundMoney($data['actual_total_amount']);
                $movementBaseTotal = $roundMoney(collect($processedPoItems)->sum(fn ($row) => (float) ($row['item_data']['actual_subtotal'] ?? 0)));

                $supplierLedger = \App\Models\SupplierLedger::where('source_purchase_order_id', $po->id)->first();
                if ($supplierLedger && (
                    (string) ($supplierLedger->transaction_code ?? '') !== (string) ($po->po_number ?? '')
                    || (int) ($supplierLedger->supplier_id ?? 0) !== (int) $supplier->id
                )) {
                    \Log::warning('PO process: detached mismatched supplier ledger source link before creating current ledger.', [
                        'supplier_ledger_id' => $supplierLedger->id,
                        'stale_source_purchase_order_id' => $po->id,
                        'stale_transaction_code' => $supplierLedger->transaction_code,
                        'current_transaction_code' => $po->po_number,
                    ]);

                    $supplierLedger->update(['source_purchase_order_id' => null]);
                    $supplierLedger = null;
                }

                if (!$supplierLedger) {
                    $supplierLedger = \App\Models\SupplierLedger::create([
                        'source_purchase_order_id' => $po->id,
                        'supplier_id' => $supplier->id,
                        'date' => $data['date'],
                        'transaction_code' => $po->po_number,
                        'module_type' => 'Purchase Order',
                        'title' => "Purchase Order Processing - {$status}",
                        'credit_amount' => $parentCreditAmount,
                        'debit_amount' => 0,
                        'reference_no' => $data['trans_no'],
                    ]);
                }

                if ($supplierLedger->items()->exists()) {
                    $existingItemTotal = $roundMoney($supplierLedger->items()->sum('subtotal'));
                    if (abs($existingItemTotal - $parentCreditAmount) > 0.01) {
                        throw new \Exception('Existing supplier ledger item total does not match the supplier ledger credit amount.');
                    }

                    return;
                }

                $remainingParentTotal = $parentCreditAmount;
                $remainingBaseTotal = $movementBaseTotal;
                $ledgerItemRows = [];
                $lastIndex = count($processedPoItems) - 1;

                foreach ($processedPoItems as $index => $row) {
                    $itemData = $row['item_data'];
                    $purchaseOrderItem = $row['purchase_order_item'];
                    $product = $row['product'];
                    $actualQuantity = (float) ($itemData['actual_quantity'] ?? 0);
                    $unitPrice = (float) ($itemData['unit_price'] ?? 0);
                    $grossMovementAmount = $roundMoney($actualQuantity * $unitPrice);
                    $baseLineSubtotal = $roundMoney($itemData['actual_subtotal'] ?? ($grossMovementAmount - ($grossMovementAmount * ((float) ($itemData['discount_percent'] ?? 0) / 100))));

                    if ($movementBaseTotal <= 0 && $parentCreditAmount <= 0) {
                        $ledgerSubtotal = 0;
                    } elseif ($actualQuantity <= 0 || $baseLineSubtotal <= 0) {
                        continue;
                    } elseif ($index === $lastIndex || $remainingBaseTotal <= 0) {
                        $ledgerSubtotal = $roundMoney($remainingParentTotal);
                    } else {
                        $ledgerSubtotal = $roundMoney($parentCreditAmount * ($baseLineSubtotal / $movementBaseTotal));
                        $remainingParentTotal = $roundMoney($remainingParentTotal - $ledgerSubtotal);
                        $remainingBaseTotal = $roundMoney($remainingBaseTotal - $baseLineSubtotal);
                    }

                    $discountAmount = $roundMoney(max(0, $grossMovementAmount - $ledgerSubtotal));
                    $effectiveDiscountPercent = $grossMovementAmount > 0
                        ? $roundMoney(($discountAmount / $grossMovementAmount) * 100)
                        : 0;

                    $ledgerItemRows[] = [
                        'source_purchase_order_item_id' => $purchaseOrderItem->id,
                        'supplier_ledger_id' => $supplierLedger->id,
                        'product_id' => $product ? $product->id : null,
                        'product_code' => $itemData['product_code'],
                        'unit' => $itemData['unit'] ?? ($product ? $product->unit : null),
                        'description' => $itemData['description'] ?? null,
                        'quantity' => (float) $row['original_quantity'],
                        'actual_quantity' => $actualQuantity,
                        'unit_price' => $unitPrice,
                        'discount_percent' => $effectiveDiscountPercent,
                        'discount_amount' => $discountAmount,
                        'subtotal' => $ledgerSubtotal,
                        'created_at' => now(),
                        'updated_at' => now(),
                    ];
                }

                $childTotal = $roundMoney(array_sum(array_column($ledgerItemRows, 'subtotal')));
                if (empty($ledgerItemRows) || abs($childTotal - $parentCreditAmount) > 0.01) {
                    throw new \Exception('Supplier ledger item total does not match the supplier ledger credit amount.');
                }

                foreach ($ledgerItemRows as $ledgerItemRow) {
                    $sourceItemId = (int) ($ledgerItemRow['source_purchase_order_item_id'] ?? 0);
                    if ($sourceItemId <= 0) {
                        continue;
                    }

                    \App\Models\SupplierLedgerItem::where('source_purchase_order_item_id', $sourceItemId)
                        ->where(function ($query) use ($supplierLedger, $ledgerItemRow) {
                            $query->where('supplier_ledger_id', '<>', $supplierLedger->id)
                                ->orWhere('product_code', '<>', $ledgerItemRow['product_code'] ?? '');
                        })
                        ->update(['source_purchase_order_item_id' => null]);
                }

                \App\Models\SupplierLedgerItem::insert($ledgerItemRows);
            });

            // 7. Keep core4_masterlist.products.cost aligned with the finalized PO unit price.
            $costSyncItems = collect($processedPoItems)->map(function ($row) {
                return [
                    'product_id' => $row['product'] ? $row['product']->id : ($row['item_data']['product_id'] ?? null),
                    'product_code' => $row['item_data']['product_code'] ?? '',
                    'unit_price' => $row['item_data']['unit_price'] ?? null,
                ];
            })->all();

            $costSync = app(\App\Services\PurchaseOrderProductCostSyncService::class)
                ->syncItems($costSyncItems);

            if (!$costSync['success']) {
                return response()->json([
                    'success' => false,
                    'message' => 'Purchase Order was saved, but product cost sync needs retry.',
                    'po_id' => $po->id,
                    'status' => $status,
                    'can_resync' => true,
                    'sync_status' => $costSync,
                ]);
            }

            $po->load(['items', 'supplier']);
            $actor = hatdogAuditActor($user);
            $recordName = trim((string) ($supplier->name ?? ('Purchase Order ' . ($po->po_number ?? $po->id))));

            hatdogWriteAuditTrail([
                'module' => 'purchase_order',
                'action' => 'Processed',
                'source_connection' => 'purchase',
                'source_table' => 'purchase_orders',
                'source_id' => $po->id,
                'display_id' => (string) ($po->po_number ?? $po->id),
                'record_name' => $recordName,
                'user_name' => $actor['name'],
                'user_identifier' => $actor['identifier'],
                'audit_data' => [
                    'purchase_order' => $po->toArray(),
                    'supplier' => $supplier->toArray(),
                    'items' => $po->items->map(fn ($item) => $item->toArray())->values()->all(),
                    'purchase_note_before' => $purchaseNoteBefore,
                    'purchase_note_after' => $purchaseNote->fresh()->toArray(),
                ],
            ]);

            return response()->json([
                'success' => true,
                'message' => 'Purchase Order processed successfully',
                'po_id' => $po->id,
                'status' => $status,
                'sync_status' => $costSync,
            ]);
        });

    } catch (\Illuminate\Validation\ValidationException $e) {
        $errors = implode(', ', \Illuminate\Support\Arr::flatten($e->errors()));
        \Log::error('PO Process validation error: ' . $errors);
        return response()->json(['success' => false, 'message' => 'Validation error: ' . $errors], 422);
    } catch (\Exception $e) {
        \Log::error('PO Process error: ' . $e->getMessage());
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.purchase-order.process');

Route::post('/admin/purchase/purchase-order/{poId}/resync-product-costs', function (Request $request, $poId) {
    $user = session('user');
    if (!$user) return response()->json(['success' => false, 'message' => 'Unauthorized'], 403);

    try {
        $costSync = app(\App\Services\PurchaseOrderProductCostSyncService::class)
            ->syncPurchaseOrder((int) $poId);

        if (!$costSync['success']) {
            return response()->json([
                'success' => false,
                'message' => 'Product cost sync still needs attention.',
                'po_id' => (int) $poId,
                'can_resync' => true,
                'sync_status' => $costSync,
            ], 422);
        }

        return response()->json([
            'success' => true,
            'message' => 'Product costs re-synced successfully.',
            'po_id' => (int) $poId,
            'sync_status' => $costSync,
        ]);
    } catch (\Throwable $error) {
        \Log::error('Purchase Order product cost re-sync failed', [
            'po_id' => (int) $poId,
            'error' => $error->getMessage(),
        ]);

        return response()->json([
            'success' => false,
            'message' => $error->getMessage(),
            'po_id' => (int) $poId,
            'can_resync' => true,
        ], 422);
    }
})->name('admin.purchase-order.resync-product-costs');

// Purchase Order Update Route
Route::post('/admin/purchase/purchase-order/update', function (Request $request) {
    $user = session('user');
    if (!$user) return response()->json(['success' => false, 'message' => 'Unauthorized'], 403);

    try {
        $data = $request->validate([
            'po_id' => 'required|integer',
            'receiving_no' => 'nullable|string',
            'date' => 'nullable|date',
            'currency' => 'required|string|max:3',
            'conversion_rate' => 'nullable|numeric|min:0',
            'additional_discount_percent' => 'nullable|numeric|min:0',
            'invoice_numbers' => 'nullable|array',
            'invoice_numbers.*' => 'nullable|string',
            'items' => 'required|array',
            'items.*.id' => 'nullable|integer',
            'items.*.product_id' => 'nullable|integer',
            'items.*.product_code' => 'required|string',
            'items.*.description' => 'nullable|string',
            'items.*.quantity' => 'required|numeric',
            'items.*.actual_quantity' => 'required|numeric',
            'items.*.unit_price' => 'required|numeric',
            'items.*.discount_percent' => 'nullable|numeric',
            'items.*.unit' => 'nullable|string|max:50',
        ]);

        $po = \App\Models\PurchaseOrder::with('supplier')->find($data['po_id']);
        if (!$po) throw new \Exception("Purchase Order not found.");

        DB::connection('purchase')->beginTransaction();
        DB::connection('ledger')->beginTransaction();
        DB::connection('masterlist')->beginTransaction();
$poBefore = $po->toArray();
$poBeforeItems = $po->items->toArray();

$legacyLedgerTransactionNumbers = collect([
    (string) ($po->po_number ?? ''),
    (string) ($po->supplier_invoice_number ?? ''),
])
    ->map(fn ($value) => trim((string) $value))
    ->filter(fn ($value) => $value !== '')
    ->unique()
    ->values()
    ->all();

$po->update([
            'receiving_number' => $data['receiving_no'] ?? $po->receiving_number,
            'date' => $data['date'] ?? $po->date,
            'currency' => $data['currency'],
            'conversion_rate' => $data['conversion_rate'] ?? $po->conversion_rate,
            'additional_discount_percent' => $data['additional_discount_percent'] ?? $po->additional_discount_percent,
            'supplier_invoice_number' => isset($data['invoice_numbers']) && is_array($data['invoice_numbers']) ? implode(', ', $data['invoice_numbers']) : ($data['invoice_numbers'] ?? $po->supplier_invoice_number),
        ]);

        $totalAmount = 0;
        $actualTotalAmount = 0;
        $newItemIds = [];

        foreach ($data['items'] as $itemData) {
            $itemQty = (float)$itemData['quantity'];
            $itemActualQty = (float)$itemData['actual_quantity'];
            $itemUnitPrice = (float)$itemData['unit_price'];
            $itemDiscPercent = (float)($itemData['discount_percent'] ?? 0);
            $discountAmount = $itemQty * $itemUnitPrice * ($itemDiscPercent / 100);
            $subtotal = ($itemQty * $itemUnitPrice) - $discountAmount;
            $actualSubtotal = ($itemActualQty * $itemUnitPrice) - ($itemActualQty * $itemUnitPrice * ($itemDiscPercent / 100));

            // Resolve every edited item against the master-list primary key. This
            // also handles product codes that are stored with leading spaces.
            $product = null;
            if (!empty($itemData['product_id'])) {
                $product = \App\Models\Product::on('masterlist')->find((int) $itemData['product_id']);
            }
            if (!$product) {
                $normalizedProductCode = trim((string) ($itemData['product_code'] ?? ''));
                $product = \App\Models\Product::on('masterlist')
                    ->whereRaw('TRIM(product_code) = ?', [$normalizedProductCode])
                    ->first();
            }
            if (!$product) {
                throw new \Exception('Master-list product not found for ' . ($itemData['product_code'] ?? 'unknown item') . '.');
            }

            $resolvedProductCode = trim((string) ($itemData['product_code'] ?? '')) !== ''
                ? $itemData['product_code']
                : $product->product_code;
            $resolvedDescription = trim((string) ($itemData['description'] ?? '')) !== ''
                ? $itemData['description']
                : ($product->description ?? '');

            if (!empty($itemData['id'])) {
                \App\Models\PurchaseOrderItem::where('id', $itemData['id'])
                    ->where('purchase_order_id', $po->id)
                    ->update([
                        'product_id' => $product->id,
                        'product_code' => $resolvedProductCode,
                        'description' => $resolvedDescription,
                        'quantity' => $itemQty,
                        'actual_quantity' => $itemActualQty,
                        'unit_price' => $itemUnitPrice,
                        'discount_percent' => $itemDiscPercent,
                        'discount_amount' => $discountAmount,
                        'subtotal' => $subtotal,
                        'actual_subtotal' => $actualSubtotal,
                        'unit' => $itemData['unit'] ?? null,
                    ]);
                $newItemIds[] = $itemData['id'];
            } else {
                // INSERT new PO item with complete printable product details.
                $poItem = \App\Models\PurchaseOrderItem::create([
                    'purchase_order_id' => $po->id,
                    'product_id' => $product->id,
                    'product_code' => $resolvedProductCode,
                    'description' => $resolvedDescription,
                    'quantity' => $itemQty,
                    'actual_quantity' => $itemActualQty,
                    'received_quantity' => 0,
                    'unit_price' => $itemUnitPrice,
                    'discount_percent' => $itemDiscPercent,
                    'discount_amount' => $discountAmount,
                    'subtotal' => $subtotal,
                    'actual_subtotal' => $actualSubtotal,
                    'unit' => $itemData['unit'] ?? null,
                ]);
                $newItemIds[] = $poItem->id;

                // Ledger and stock changes are intentionally deferred until the
                // full Purchase Order snapshot has been saved. The reconciliation
                // service below is the single source of truth for add/delete/update.
            }

            $totalAmount += $subtotal;
            $actualTotalAmount += $actualSubtotal;
        }

        \App\Models\PurchaseOrderItem::where('purchase_order_id', $po->id)
            ->when(!empty($newItemIds), function ($query) use ($newItemIds) {
                $query->whereNotIn('id', $newItemIds);
            })
            ->delete();

        // Product costs are synchronized by PurchaseOrderLedgerReconciliationService.

        $addlDiscPercent = (float) ($data['additional_discount_percent'] ?? 0);
        $addlDiscAmount = 0;
        if ($addlDiscPercent > 0) {
            $addlDiscAmount = $totalAmount * ($addlDiscPercent / 100);
            $addlActualDiscAmount = $actualTotalAmount * ($addlDiscPercent / 100);
            $totalAmount -= $addlDiscAmount;
            $actualTotalAmount -= $addlActualDiscAmount;
        }

        $po->update([
            'total_amount' => $totalAmount,
            'actual_total_amount' => $actualTotalAmount,
            'additional_discount_amount' => $addlDiscAmount,
        ]);

        // The saved PO snapshot is authoritative. Reconcile product_ledgers and
        // supplier_ledger_items only after every add/delete/unit/cost/QTY change
        // has been finalized in purchase_order_items.
        $ledgerSync = app(\App\Services\PurchaseOrderLedgerReconciliationService::class)
    ->reconcile(
        $po->fresh(['items', 'supplier']),
        $legacyLedgerTransactionNumbers
    );

        // Recalculate the source Purchase Note from the latest PO snapshot for
        // each product. This closes a fully received note and avoids the legacy
        // bug that summed every historical PO quantity and left it Partial.
        $purchaseNoteStatus = null;
        $linkedPurchaseNote = \App\Models\PurchaseNote::where(function ($query) use ($po) {
            $query->where('purchase_note_number', $po->reference_number)
                ->orWhere('reference_number', $po->reference_number);
        })->first();

        if ($linkedPurchaseNote) {
            $purchaseNoteStatus = app(\App\Services\PurchaseNoteStatusService::class)
                ->syncFromLatestPurchaseOrderSnapshots($linkedPurchaseNote);

            $po->update(['status' => $purchaseNoteStatus['status']]);
        }

        $po->load(['items', 'supplier']);
        $actor = hatdogAuditActor($user);
        $recordName = trim((string) (($po->supplier->name ?? '') . ' - ' . ($po->po_number ?? $po->id)));

        hatdogWriteAuditTrail([
            'module' => 'purchase_order',
            'action' => 'Updated',
            'source_connection' => 'purchase',
            'source_table' => 'purchase_orders',
            'source_id' => $po->id,
            'display_id' => (string) ($po->po_number ?? $po->id),
            'record_name' => $recordName,
            'user_name' => $actor['name'],
            'user_identifier' => $actor['identifier'],
            'audit_data' => [
                'before' => $poBefore,
                'after' => $po->toArray(),
                'items' => $po->items->map(fn ($item) => $item->toArray())->values()->all(),
            ],
        ]);

        DB::connection('purchase')->commit();
        DB::connection('ledger')->commit();
        DB::connection('masterlist')->commit();

        return response()->json([
            'success' => true,
            'message' => 'Purchase Order has been successfully updated!',
            'po_id' => $po->id,
            'status' => $po->status,
            'purchase_note_status' => $purchaseNoteStatus['status'] ?? null,
            'ledger_sync' => $ledgerSync,
        ]);

    } catch (\Exception $e) {
        foreach (['purchase', 'ledger', 'masterlist'] as $connection) {
            try {
                if (DB::connection($connection)->transactionLevel() > 0) {
                    DB::connection($connection)->rollBack();
                }
            } catch (\Throwable $rollbackError) {
                \Log::warning('PO update rollback failed', [
                    'connection' => $connection,
                    'error' => $rollbackError->getMessage(),
                ]);
            }
        }
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.purchase-order.update');

