// Purchase Return - Fetch eligible invoices (POs with Partial or Closed status)
Route::get('/admin/purchase/purchase-return/invoices', function () {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

    try {
        $purchaseOrders = \App\Models\PurchaseOrder::query()
            ->whereIn('status', ['Partial', 'Closed'])
            ->orderBy('date', 'desc')
            ->get();

        $suppliersById = \App\Models\Supplier::query()
            ->whereIn('id', $purchaseOrders->pluck('supplier_id')->filter()->unique()->values())
            ->get()
            ->keyBy('id');

        $invoices = $purchaseOrders
            ->filter(fn ($po) => !empty($po->supplier_id) && $suppliersById->has($po->supplier_id))
            ->map(function ($po) use ($suppliersById) {
                $supplier = $suppliersById->get($po->supplier_id);

                return [
                    'po_id' => $po->id,
                    'supplier_id' => $po->supplier_id,
                    'invoice_no' => $po->supplier_invoice_number ?? $po->po_number,
                    'customer_name' => $supplier?->name ?? 'N/A',
                    'contact_no' => $supplier?->contact_number ?? 'N/A',
                    'contact_person' => $supplier?->contact_person ?? 'N/A',
                    'billing_address' => $supplier?->address ?? 'N/A',
                ];
            });

        return response()->json([
            'success' => true,
            'invoices' => $invoices,
        ]);
    } catch (\Exception $e) {
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.purchase-return.invoices');

