// Purchase Return - Process return submission
Route::post('/admin/purchase/purchase-return/process', function (Request $request) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

    try {
        $data = $request->validate([
            'return_date' => 'required|date',
            'slip_no' => 'nullable|string|max:100',
            'po_id' => 'required|integer',
            'supplier_id' => 'required|integer',
            'remarks' => 'nullable|string',
            'additional_discount_percent' => 'nullable|numeric|min:0',
            'additional_discount_amount' => 'nullable|numeric|min:0',
            'items' => 'required|array',
            'items.*.product_id' => 'nullable|integer',
            'items.*.product_code' => 'required|string',
            'items.*.description' => 'nullable|string',
            'items.*.price_code' => 'nullable|string|max:100',
            'items.*.quantity' => 'required|integer|min:0',
            'items.*.out_quantity' => 'nullable|integer|min:0',
            'items.*.unit_price' => 'required|numeric|min:0',
            'items.*.discount' => 'nullable|numeric|min:0',
            'items.*.subtotal' => 'required|numeric|min:0',
            'items.*.unit' => 'nullable|string|max:50',
        ]);

        // Generate the next return number from the highest RET sequence, not row count.
        // Using count() + 1 can reuse an existing number after a return is deleted/archived.
        $maxReturnSequenceRow = \App\Models\PurchaseReturn::query()
            ->whereRaw("return_number REGEXP '^RET-[0-9]+$'")
            ->selectRaw("MAX(CAST(SUBSTRING(return_number, 5) AS UNSIGNED)) AS max_sequence")
            ->first();
        $nextReturnSequence = ((int) ($maxReturnSequenceRow->max_sequence ?? 0)) + 1;

        $subtotal = collect($data['items'])->sum('subtotal');
        $additionalDiscPercent = (float)($data['additional_discount_percent'] ?? 0);
        $additionalDiscAmount = $subtotal * ($additionalDiscPercent / 100);
        $totalAmount = $subtotal - $additionalDiscAmount;

        // Create the header with duplicate protection for simultaneous submissions.
        $purchaseReturn = null;
        $returnNumber = '';
        for ($attempt = 0; $attempt < 25; $attempt++) {
            $returnNumber = 'RET-' . str_pad($nextReturnSequence, 7, '0', STR_PAD_LEFT);

            // Skip any number that already exists (including gaps caused by deleted rows).
            if (\App\Models\PurchaseReturn::where('return_number', $returnNumber)->exists()) {
                $nextReturnSequence++;
                continue;
            }

            try {
                $purchaseReturn = \App\Models\PurchaseReturn::create([
                    'return_number' => $returnNumber,
                    'slip_no' => isset($data['slip_no']) && trim((string) $data['slip_no']) !== '' ? trim((string) $data['slip_no']) : null,
                    'po_id' => $data['po_id'],
                    'supplier_id' => $data['supplier_id'],
                    'date' => $data['return_date'],
                    'total_amount' => $totalAmount,
                    'additional_discount_percent' => $additionalDiscPercent,
                    'additional_discount_amount' => $additionalDiscAmount,
                    'remarks' => $data['remarks'],
                    'status' => 'Completed',
                ]);
                break;
            } catch (\Illuminate\Database\QueryException $e) {
                $driverCode = (int) (($e->errorInfo[1] ?? 0));
                $duplicateReturnNumber = $driverCode === 1062
                    && str_contains($e->getMessage(), 'purchase_returns_return_number_unique');

                if (!$duplicateReturnNumber) {
                    throw $e;
                }

                // Another request claimed this sequence between the exists() check and insert.
                $nextReturnSequence++;
            }
        }

        if (!$purchaseReturn) {
            throw new \RuntimeException('Unable to generate a unique Purchase Return number. Please try again.');
        }

        // Re-read the value from the database so create/detail/edit use the exact persisted Slip No.
        $purchaseReturn->refresh();

        $supplier = \App\Models\Supplier::find($data['supplier_id']);
        $purchaseOrder = \App\Models\PurchaseOrder::with(['items', 'supplier'])->find($data['po_id']);

        foreach ($data['items'] as $itemData) {
            $resolvedProductId = !empty($itemData['product_id']) ? (int) $itemData['product_id'] : null;
            if (!$resolvedProductId) {
                $resolvedProductId = (int) (\App\Models\Product::where('product_code', $itemData['product_code'])->value('id') ?? 0) ?: null;
            }

            \App\Models\PurchaseReturnItem::create([
                'purchase_return_id' => $purchaseReturn->id,
                'product_id' => $resolvedProductId,
                'product_code' => $itemData['product_code'],
                'description' => $itemData['description'],
                'quantity' => $itemData['quantity'],
                'out_quantity' => (int) ($itemData['out_quantity'] ?? 0),
                'oum' => $itemData['unit'] ?? '',
                'unit_price' => $itemData['unit_price'],
                'discount' => $itemData['discount'] ?? 0,
                'subtotal' => $itemData['subtotal'],
            ]);
        }

        // Rebuild Purchase Return product ledger rows. OUT affects stock; JUNK is recorded only.
        $affectedProductIds = app(\App\Services\PurchaseReturnProductLedgerService::class)
            ->replaceForReturn($purchaseReturn->fresh(['items', 'supplier']));

        // Create Supplier Ledger Entry (Debit)
        \App\Models\SupplierLedger::create([
            'supplier_id' => $data['supplier_id'],
            'date' => $data['return_date'],
            'transaction_code' => $returnNumber,
            'module_type' => 'Purchase Return',
            'title' => "Purchase Return Processing - {$returnNumber}",
            'credit_amount' => 0,
            'debit_amount' => $purchaseReturn->total_amount,
            'reference_no' => $returnNumber,
        ]);

        if (!empty($affectedProductIds)) {
            \App\Services\ProductStockSyncService::syncProducts($affectedProductIds);
        }

        $purchaseReturn->load(['items', 'supplier', 'purchaseOrder']);
        $actor = hatdogAuditActor($user);
        $recordName = trim((string) (($supplier?->name ?? '') !== '' ? $supplier->name : ('Purchase Return ' . $returnNumber)));

        hatdogWriteAuditTrail([
            'module' => 'purchase_return',
            'action' => 'Processed',
            'source_connection' => 'purchase',
            'source_table' => 'purchase_returns',
            'source_id' => $purchaseReturn->id,
            'display_id' => $returnNumber,
            'record_name' => $recordName,
            'user_name' => $actor['name'],
            'user_identifier' => $actor['identifier'],
            'audit_data' => [
                'purchase_return' => $purchaseReturn->toArray(),
                'supplier' => $supplier?->toArray(),
                'purchase_order' => $purchaseOrder?->toArray(),
                'items' => $purchaseReturn->items->map(fn ($item) => $item->toArray())->values()->all(),
            ],
        ]);

        return response()->json([
            'success' => true,
            'message' => 'Purchase Return processed successfully',
            'return_number' => $returnNumber,
            'slip_no' => $purchaseReturn->slip_no ?? '',
        ]);
    } catch (\Exception $e) {
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.purchase-return.process');

Route::post('/admin/purchase/purchase-return/update/{id}', function (Request $request, $id) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

    try {
        $data = $request->validate([
            'return_date' => 'required|date',
            'slip_no' => 'nullable|string|max:100',
            'remarks' => 'nullable|string',
            'additional_discount_percent' => 'nullable|numeric|min:0',
            'additional_discount_amount' => 'nullable|numeric|min:0',
            'items' => 'required|array',
            'items.*.product_id' => 'nullable|integer',
            'items.*.product_code' => 'required|string',
            'items.*.description' => 'nullable|string',
            'items.*.price_code' => 'nullable|string|max:100',
            'items.*.quantity' => 'required|integer|min:0',
            'items.*.out_quantity' => 'nullable|integer|min:0',
            'items.*.unit_price' => 'required|numeric|min:0',
            'items.*.discount' => 'nullable|numeric|min:0',
            'items.*.subtotal' => 'required|numeric|min:0',
            'items.*.unit' => 'nullable|string|max:50',
        ]);

        $purchaseReturn = \App\Models\PurchaseReturn::with(['items', 'supplier', 'purchaseOrder'])->findOrFail($id);

        $subtotal = collect($data['items'])->sum('subtotal');
        $additionalDiscPercent = (float)($data['additional_discount_percent'] ?? 0);
        $additionalDiscAmount = $subtotal * ($additionalDiscPercent / 100);
        $totalAmount = $subtotal - $additionalDiscAmount;
        $returnNumber = $purchaseReturn->return_number;

        // Update purchase return header
        $purchaseReturn->update([
            'slip_no' => isset($data['slip_no']) && trim((string) $data['slip_no']) !== '' ? trim((string) $data['slip_no']) : null,
            'date' => $data['return_date'],
            'total_amount' => $totalAmount,
            'additional_discount_percent' => $additionalDiscPercent,
            'additional_discount_amount' => $additionalDiscAmount,
            'remarks' => $data['remarks'],
        ]);

        // Delete existing items and re-insert
        $purchaseReturn->items()->delete();

        foreach ($data['items'] as $itemData) {
            $resolvedProductId = !empty($itemData['product_id']) ? (int) $itemData['product_id'] : null;
            if (!$resolvedProductId) {
                $resolvedProductId = (int) (\App\Models\Product::where('product_code', $itemData['product_code'])->value('id') ?? 0) ?: null;
            }

            \App\Models\PurchaseReturnItem::create([
                'purchase_return_id' => $purchaseReturn->id,
                'product_id' => $resolvedProductId,
                'product_code' => $itemData['product_code'],
                'description' => $itemData['description'],
                'quantity' => $itemData['quantity'],
                'out_quantity' => (int) ($itemData['out_quantity'] ?? 0),
                'oum' => $itemData['unit'] ?? '',
                'unit_price' => $itemData['unit_price'],
                'discount' => $itemData['discount'] ?? 0,
                'subtotal' => $itemData['subtotal'],
            ]);
        }

        // Rebuild the linked OUT/JUNK ledger rows and recalculate every later balance.
        $affectedProductIds = app(\App\Services\PurchaseReturnProductLedgerService::class)
            ->replaceForReturn($purchaseReturn->fresh(['items', 'supplier']));

        // Update supplier ledger entry
        \App\Models\SupplierLedger::where('transaction_code', $returnNumber)
            ->where('module_type', 'Purchase Return')
            ->update([
                'date' => $data['return_date'],
                'debit_amount' => $totalAmount,
            ]);

        if (!empty($affectedProductIds)) {
            \App\Services\ProductStockSyncService::syncProducts($affectedProductIds);
        }

        $actor = hatdogAuditActor($user);
        $supplierName = trim((string) (optional($purchaseReturn->supplier)->name ?? ''));
        $recordName = $supplierName !== '' ? $supplierName : ('Purchase Return ' . $returnNumber);

        hatdogWriteAuditTrail([
            'module' => 'purchase_return',
            'action' => 'Updated',
            'source_connection' => 'purchase',
            'source_table' => 'purchase_returns',
            'source_id' => $purchaseReturn->id,
            'display_id' => $returnNumber,
            'record_name' => $recordName,
            'user_name' => $actor['name'],
            'user_identifier' => $actor['identifier'],
            'audit_data' => [
                'purchase_return' => $purchaseReturn->fresh()->toArray(),
                'items' => $purchaseReturn->fresh('items')->items->map(fn ($item) => $item->toArray())->values()->all(),
            ],
        ]);

        return response()->json([
            'success' => true,
            'message' => 'Purchase Return updated successfully',
            'return_number' => $returnNumber,
            'slip_no' => $purchaseReturn->fresh()->slip_no ?? '',
        ]);
    } catch (\Exception $e) {
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.purchase-return.update');

Route::post('/admin/purchase/purchase-return/delete/{id}', function ($id) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

    if (is_array($user)) {
        $user = (object) $user;
    }

    $purchaseTransactionStarted = false;
    $ledgerTransactionStarted = false;

    try {
        if (!Schema::connection('ledger')->hasTable('archived_records')) {
            throw new \Exception('Archive table is missing. Please run the archive migration first.');
        }

        DB::connection('purchase')->beginTransaction();
        $purchaseTransactionStarted = true;
        DB::connection('ledger')->beginTransaction();
        $ledgerTransactionStarted = true;

        $purchaseReturn = \App\Models\PurchaseReturn::with(['items', 'supplier', 'purchaseOrder'])
            ->lockForUpdate()
            ->findOrFail($id);

        $items = $purchaseReturn->items->map(fn ($item) => $item->toArray())->values()->all();
        $supplierName = trim((string) optional($purchaseReturn->supplier)->name);
        $actor = hatdogAuditActor($user);

        $archivedData = [
            'purchase_return' => $purchaseReturn->toArray(),
            'items' => $items,
        ];

        $deletedBy = $user->name ?? $user->username ?? $user->User_ID ?? 'Admin';
        $displayId = (string) ($purchaseReturn->return_number ?? $purchaseReturn->id);
        $dataName = $supplierName !== '' ? $supplierName : ('Purchase Return ' . $displayId);

        $existingArchive = DB::connection('ledger')
            ->table('archived_records')
            ->where('module', 'purchase_return')
            ->whereNull('restored_at')
            ->where('source_connection', 'purchase')
            ->where('source_table', 'purchase_returns')
            ->where('source_id', $purchaseReturn->id)
            ->first();

        if ($existingArchive) {
            throw new \Exception('This purchase return is already archived.');
        }

        DB::connection('ledger')->table('archived_records')->insert([
            'module' => 'purchase_return',
            'source_connection' => 'purchase',
            'source_table' => 'purchase_returns',
            'source_id' => $purchaseReturn->id,
            'display_id' => $displayId,
            'data_name' => $dataName,
            'archived_data' => json_encode($archivedData, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE),
            'deleted_by' => (string) $deletedBy,
            'deleted_at' => now(),
            'expires_at' => now()->addDays(30),
            'created_at' => now(),
            'updated_at' => now(),
        ]);

        hatdogWriteAuditTrail([
            'module' => 'purchase_return',
            'action' => 'Deleted',
            'source_connection' => 'purchase',
            'source_table' => 'purchase_returns',
            'source_id' => $purchaseReturn->id,
            'display_id' => $displayId,
            'record_name' => $dataName,
            'user_name' => $actor['name'],
            'user_identifier' => $actor['identifier'],
            'audit_data' => [
                'before' => [
                    'purchase_return' => $purchaseReturn->toArray(),
                    'supplier' => $purchaseReturn->supplier?->toArray(),
                    'purchase_order' => $purchaseReturn->purchaseOrder?->toArray(),
                    'items' => $items,
                ],
            ],
        ]);

        // Delete this Purchase Return's OUT/JUNK ledger rows and repair all later balances.
        $affectedProductIds = app(\App\Services\PurchaseReturnProductLedgerService::class)
            ->deleteForReturn($purchaseReturn);

        DB::connection('ledger')->table('supplier_ledgers')
            ->where('supplier_id', $purchaseReturn->supplier_id)
            ->where('module_type', 'Purchase Return')
            ->where(function ($q) use ($purchaseReturn) {
                $q->where('transaction_code', $purchaseReturn->return_number)
                    ->orWhere('reference_no', $purchaseReturn->return_number);
            })
            ->delete();

        $purchaseReturn->items()->delete();
        $purchaseReturn->delete();

        DB::connection('ledger')->commit();
        $ledgerTransactionStarted = false;
        DB::connection('purchase')->commit();
        $purchaseTransactionStarted = false;

        if (!empty($affectedProductIds)) {
            \App\Services\ProductStockSyncService::syncProducts($affectedProductIds);
        }

        return response()->json([
            'success' => true,
            'message' => 'Purchase Return archived successfully',
        ]);
    } catch (\Throwable $e) {
        if ($ledgerTransactionStarted && DB::connection('ledger')->transactionLevel() > 0) {
            DB::connection('ledger')->rollBack();
        }
        if ($purchaseTransactionStarted && DB::connection('purchase')->transactionLevel() > 0) {
            DB::connection('purchase')->rollBack();
        }

        Log::error('Purchase Return delete failed.', [
            'purchase_return_id' => (int) $id,
            'error' => $e->getMessage(),
        ]);

        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.purchase-return.delete');

// Purchase Return - History data
Route::get('/admin/purchase/purchase-return/history', function () {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

    try {
        $resolveSupplierInfo = function ($supplierId, $supplierModel = null) {
            if ($supplierModel) {
                return [
                    'name' => $supplierModel->name ?: 'N/A',
                    'contact_number' => $supplierModel->contact_number ?: 'N/A',
                    'contact_person' => $supplierModel->contact_person ?: 'N/A',
                    'address' => $supplierModel->address ?: 'N/A',
                ];
            }

            if (!$supplierId || !Schema::connection('ledger')->hasTable('archived_records')) {
                return [
                    'name' => 'N/A',
                    'contact_number' => 'N/A',
                    'contact_person' => 'N/A',
                    'address' => 'N/A',
                ];
            }

            $archived = DB::connection('ledger')
                ->table('archived_records')
                ->where('module', 'supplier')
                ->where('source_connection', 'masterlist')
                ->where('source_table', 'suppliers')
                ->where('source_id', $supplierId)
                ->orderByDesc('id')
                ->first();

            $archivedData = $archived ? json_decode((string) $archived->archived_data, true) : null;

            return [
                'name' => trim((string) ($archivedData['name'] ?? '')) ?: 'N/A',
                'contact_number' => trim((string) ($archivedData['contact_number'] ?? '')) ?: 'N/A',
                'contact_person' => trim((string) ($archivedData['contact_person'] ?? '')) ?: 'N/A',
                'address' => trim((string) ($archivedData['address'] ?? '')) ?: 'N/A',
            ];
        };

        $history = \App\Models\PurchaseReturn::with(['purchaseOrder', 'supplier'])
            ->orderBy('date', 'desc')
            ->get()
            ->map(function ($ret) use ($resolveSupplierInfo) {
                $supplierInfo = $resolveSupplierInfo($ret->supplier_id, $ret->supplier);
                return [
                    'id' => $ret->id,
                    'return_number' => $ret->return_number,
                    'invoice_no' => $ret->purchaseOrder?->supplier_invoice_number ?? $ret->purchaseOrder?->po_number ?? 'N/A',
                    'supplier_name' => $supplierInfo['name'],
                    'contact_no' => $supplierInfo['contact_number'],
                    'contact_person' => $supplierInfo['contact_person'],
                    'billing_address' => $supplierInfo['address'],
                    'date' => $ret->date,
                    'total_amount' => $ret->total_amount,
                    'remarks' => $ret->remarks,
                ];
            });

        return response()->json([
            'success' => true,
            'history' => $history,
        ]);
    } catch (\Exception $e) {
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.purchase-return.history');

