                ];
            }

            if (!$supplierId || !Schema::connection('ledger')->hasTable('archived_records')) {
                return ['name' => 'N/A'];
            }

            $archived = DB::connection('ledger')
                ->table('archived_records')
                ->where('module', 'supplier')
                ->where('source_connection', 'masterlist')
                ->where('source_table', 'suppliers')
                ->where('source_id', $supplierId)
                ->orderByDesc('id')
                ->first();

            $archivedData = $archived ? json_decode((string) $archived->archived_data, true) : null;

            return [
                'name' => trim((string) ($archivedData['name'] ?? '')) ?: 'N/A',
            ];
        };

        $return = \App\Models\PurchaseReturn::with(['items', 'purchaseOrder', 'supplier'])
            ->findOrFail($id);

        $supplierInfo = $resolveSupplierInfo($return->supplier_id, $return->supplier);

        $slipNo = '';
        if (Schema::connection('purchase')->hasColumn('purchase_returns', 'slip_no')) {
            $slipNo = trim((string) DB::connection('purchase')
                ->table('purchase_returns')
                ->where('id', $return->id)
                ->value('slip_no'));
        }

        // Older imported returns stored the return-slip number inside remarks.
        // Keep those records readable without changing the remarks field.
        if ($slipNo === '' && preg_match('/\bRS-[A-Z0-9-]+\b/i', (string) ($return->remarks ?? ''), $legacySlipMatch)) {
            $slipNo = strtoupper($legacySlipMatch[0]);
        }

        $poItems = \App\Models\PurchaseOrderItem::where('purchase_order_id', $return->po_id)->get();

        return response()->json([
            'success' => true,
            'return' => [
                'return_number' => $return->return_number,
                'slip_no' => $slipNo,
                'date' => $return->date,
                'invoice_no' => $return->purchaseOrder?->supplier_invoice_number ?? $return->purchaseOrder?->po_number ?? 'N/A',
                'supplier_name' => $supplierInfo['name'],
                'total_amount' => $return->total_amount,
                'additional_discount_percent' => $return->additional_discount_percent ?? 0,
                'additional_discount_amount' => $return->additional_discount_amount ?? 0,
                'remarks' => $return->remarks ?? '---',
                'items' => $return->items->map(function ($item) use ($poItems) {
                    $product = $item->product_id ? \App\Models\Product::on('masterlist')->find($item->product_id) : null;
                    $poItem = $poItems->first(function ($candidate) use ($item) {
                        if (!empty($item->product_id) && (int) $candidate->product_id === (int) $item->product_id) {
                            return true;
                        }
                        return trim((string) $candidate->product_code) !== ''
                            && trim((string) $candidate->product_code) === trim((string) $item->product_code);
                    });
                    $totalQty = (int) ($poItem?->received_quantity ?: $poItem?->actual_quantity ?: $poItem?->quantity ?: $item->quantity);
                    $outQty = max(0, (int) ($item->out_quantity ?? 0));
                    $junkQty = max(0, (int) $item->quantity - $outQty);
                    $descParts = [$item->description];
                    if ($product->application ?? false) $descParts[] = $product->application;
                    if ($product->Position ?? false) $descParts[] = $product->Position;
                    return [
                        'product_id' => $item->product_id,
                        'product_code' => (string) ($item->product_code ?? ''),
                        'description' => implode(' | ', $descParts),
                        'original_description' => $item->description,
                        'part_number' => $product ? $product->part_number : '',
                        'application' => $product ? $product->application : '',
                        'category' => $product ? $product->category : '',
                        'quantity' => $item->quantity,
                        'total_quantity' => max((int) $item->quantity, $totalQty),
                        'out_quantity' => $outQty,
                        'junk_quantity' => $junkQty,
                        'additional_qty' => $item->additional_qty,
                        'oum' => $item->oum,
                        'unit_price' => $item->unit_price,
                        'discount' => $item->discount ?? 0,
                        'subtotal' => $item->subtotal,
                    ];
                }),
            ],
        ]);
    } catch (\Exception $e) {
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.purchase-return.detail');


// Sales Note - Rush Notifications (overdue rush orders) - MUST BE BEFORE main sales-note route
Route::get('/admin/sales/sales-note/rush-notifications', function (\Illuminate\Http\Request $request) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

    try {
        // Get rush orders that are Open or Partial status and older than 1 day
        $oneDayAgo = \Carbon\Carbon::now()->subDay();
        
        $overdueRushNotes = \App\Models\SalesNote::where('is_rush', 1)
            ->whereIn('status', ['Open', 'Partial'])
            ->where('created_at', '<=', $oneDayAgo)
            ->orderBy('created_at', 'asc')
            ->get()
            ->map(function ($note) {
                $daysOverdue = \Carbon\Carbon::parse($note->created_at)->diffInDays(\Carbon\Carbon::now());
                return [
                    'id' => $note->id,
                    'sales_number' => $note->sales_number,
                    'customer_name' => $note->customer_name,
                    'order_date' => $note->order_date,
                    'created_at' => $note->created_at,
                    'days_overdue' => $daysOverdue,
                    'net_total' => $note->net_total,
                    'salesman' => $note->salesman,
                    'status' => $note->status,
                ];
            });

        return response()->json([
            'success' => true,
            'count' => $overdueRushNotes->count(),
            'notifications' => $overdueRushNotes,
        ]);
    } catch (\Exception $e) {
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.sales-note.rush-notifications');

// Overdue Invoices Notifications
Route::get('/admin/payments/overdue-notifications', function (\Illuminate\Http\Request $request) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

    try {
        // Customer terms live on the masterlist MariaDB service. Resolve them
        // first, then query sales orders on the sales service.
        $customerTerms = DB::connection('masterlist')->table('customers')
            ->whereNotNull('terms')
            ->where('terms', '>', 0)
            ->pluck('terms', 'id');

        $overdueInvoices = collect();
        if ($customerTerms->isNotEmpty()) {
            $overdueInvoices = DB::connection('sales')
                ->table('sales_orders as so')
                ->whereIn('so.customer_id', $customerTerms->keys()->all())
                ->whereIn('so.status', ['Confirmed', 'Partial'])
                ->select(
                    'so.id',
                    'so.order_number',
                    'so.customer_id',
                    'so.customer_name',
                    'so.total_amount',
                    'so.status',
                    'so.created_at'
                )
                ->get()
                ->map(function ($invoice) use ($customerTerms) {
                    $createdDate = \Carbon\Carbon::parse($invoice->created_at);
                    $daysOld = $createdDate->diffInDays(\Carbon\Carbon::now());
                    $terms = (int) ($customerTerms->get((int) $invoice->customer_id) ?? 0);
                    $daysOverdue = $daysOld - $terms;

                    if ($daysOverdue > 0) {
                        return [
                            'id' => $invoice->id,
                            'order_number' => $invoice->order_number,
                            'customer_id' => $invoice->customer_id,
                            'customer_name' => $invoice->customer_name,
                            'total_amount' => $invoice->total_amount,
                            'status' => $invoice->status,
                            'created_at' => $invoice->created_at,
                            'invoice_age_days' => $daysOld,
                            'customer_terms' => $terms,
                            'days_overdue' => $daysOverdue,
                        ];
                    }
                    return null;
                })
                ->filter()
                ->sortByDesc('days_overdue')
                ->values();
        }

        return response()->json([
            'success' => true,
            'count' => $overdueInvoices->count(),
            'notifications' => $overdueInvoices,
        ]);
    } catch (\Exception $e) {
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.payments.overdue-notifications');

