// Sales Note - Customer list
Route::get('/admin/sales/sales-note/customers', function () {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

    try {
        $page = (int) request()->get('page', 1);
        $perPage = (int) request()->get('perPage', 50);
        $perPage = max(1, min(200, $perPage));

        $q = \App\Models\Customer::query()->orderBy('name');
        $search = request()->get('search', []);
        if (is_array($search) && !empty($search)) {
            $code = trim((string) ($search['code'] ?? ''));
            $name = trim((string) ($search['name'] ?? ''));
            $contact = trim((string) ($search['contact_number'] ?? ''));
            $person = trim((string) ($search['contact_person'] ?? ''));
            $address = trim((string) ($search['address'] ?? ''));

            if ($code !== '') {
                $normalized = strtoupper($code);
                $digits = preg_replace('/\D+/', '', $normalized);
                if ($digits !== '') {
                    $q->where(function ($sub) use ($digits, $normalized) {
                        $sub->where('id', (int) $digits)
                            ->orWhereRaw("CONCAT('CUS-', LPAD(id, 4, '0')) LIKE ?", ['%' . $normalized . '%']);
                    });
                } else {
                    $q->whereRaw("CONCAT('CUS-', LPAD(id, 4, '0')) LIKE ?", ['%' . $normalized . '%']);
                }
            }
            if ($name !== '') $q->where('name', 'like', '%' . $name . '%');
            if ($contact !== '') $q->where('contact_number', 'like', '%' . $contact . '%');
            if ($person !== '') $q->where('contact_person', 'like', '%' . $person . '%');
            if ($address !== '') $q->where('address', 'like', '%' . $address . '%');
        }
        $customers = $q->paginate($perPage, ['*'], 'page', $page);

        $rows = $customers->getCollection()->map(function ($c) {
            return [
                'id' => $c->id,
                'code' => 'CUS-' . str_pad($c->id, 4, '0', STR_PAD_LEFT),
                'name' => $c->name,
                'contact_number' => $c->contact_number ?? 'N/A',
                'contact_person' => $c->contact_person ?? 'N/A',
                'address' => $c->address ?? 'N/A',
            ];
        })->values();

        return response()->json([
            'success' => true,
            'customers' => $rows,
            'pagination' => [
                'current_page' => $customers->currentPage(),
                'last_page' => $customers->lastPage(),
                'per_page' => $customers->perPage(),
                'total' => $customers->total(),
                'from' => $customers->firstItem(),
                'to' => $customers->lastItem(),
            ],
        ]);
    } catch (\Exception $e) {
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.sales-note.customers');

// Sales Note - Product list
// Shared by Admin, Regular, and Special users. Stock remains authoritative
// from the latest product_ledgers.balance_stock row; products.on_hand is not used.
if (!function_exists('hatdogSalesNoteProductsResponse')) {
    function hatdogSalesNoteProductsResponse(Request $request)
    {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

    try {
        $idsOnly = $request->query('ids_only') === '1';
        $page = max(1, (int) $request->query('page', 1));
        $perPage = $idsOnly ? 100000 : max(1, min(100, (int) $request->query('perPage', 50)));
        $search = $request->query('search', []);

        $code = trim((string) ($search['code'] ?? ''));
        $desc = trim((string) ($search['description'] ?? ''));
        $part = trim((string) ($search['part_number'] ?? ''));
        $app = trim((string) ($search['application'] ?? ''));
        $unit = trim((string) ($search['oum'] ?? ''));
        $price = trim((string) ($search['price'] ?? ''));
        $position = trim((string) ($search['position'] ?? ''));
        $specification = trim((string) ($search['specification'] ?? ''));

        $query = \App\Models\Product::query();
        if ($code !== '') $query->where('product_code', 'like', '%' . $code . '%');
        if ($desc !== '') $query->where('description', 'like', '%' . $desc . '%');
        if ($part !== '') $query->where('part_number', 'like', '%' . $part . '%');
        if ($app !== '') $query->where('application', 'like', '%' . $app . '%');
        if ($unit !== '' && stripos('PCS', $unit) === false) {
            return response()->json([
                'success' => true,
                'products' => [],
                'pagination' => [
                    'current_page' => 1,
                    'last_page' => 1,
                    'per_page' => $perPage,
                    'total' => 0,
                    'from' => null,
                    'to' => null,
                ],
            ]);
        }
        if ($price !== '') $query->where('selling_price', 'like', '%' . $price . '%');
        if ($position !== '') $query->where('position', 'like', '%' . $position . '%');
        if ($specification !== '') $query->where('specification', 'like', '%' . $specification . '%');

        $products = $query->orderBy('product_code')->paginate($perPage, [
            'id',
            'product_code',
            'description',
            'part_number',
            'application',
            'category',
            'unit',
            'selling_price',
            'price_online',
            'position',
            'specification',
        ], 'page', $page);

        $productIds = $products->getCollection()->pluck('id')->map(fn ($id) => (int) $id)->all();
        $balanceMap = [];
        $priceCodeMap = [];
        if (!empty($productIds)) {
            $latestCreatedAtQuery = DB::connection('ledger')
                ->table('product_ledgers as pl')
                ->selectRaw('pl.product_id, MAX(pl.created_at) as max_created_at')
                ->whereIn('pl.product_id', $productIds)
                ->groupBy('pl.product_id');

            $latestIdsQuery = DB::connection('ledger')
                ->table('product_ledgers as pl')
                ->joinSub($latestCreatedAtQuery, 'lc', function ($join) {
                    $join->on('pl.product_id', '=', 'lc.product_id')
                        ->on('pl.created_at', '=', 'lc.max_created_at');
                })
                ->selectRaw('MAX(pl.id) as id')
                ->groupBy('pl.product_id');

            $latestRows = DB::connection('ledger')
                ->table('product_ledgers')
                ->whereIn('id', $latestIdsQuery)
                ->get(['product_id', 'balance_stock']);

            foreach ($latestRows as $r) {
                $balanceMap[(int) $r->product_id] = (float) ($r->balance_stock ?? 0);
            }

            $priceCodeRows = DB::connection('masterlist')
                ->table('product_price_codes')
                ->whereIn('product_id', $productIds)
                ->orderBy('product_id')
                ->orderBy('sort_order')
                ->orderBy('id')
                ->get(['product_id', 'price_code', 'selling_price', 'sort_order']);

            foreach ($priceCodeRows as $row) {
                $pid = (int) $row->product_id;
                $priceCodeMap[$pid][] = [
                    'price_code' => $row->price_code,
                    'selling_price' => (float) ($row->selling_price ?? 0),
                    'sort_order' => (int) ($row->sort_order ?? 0),
                ];
            }
        }

        $stockFilter = trim((string) ($search['on_hand'] ?? ''));
        $rows = $products->getCollection()->map(function ($p) use ($balanceMap, $priceCodeMap) {
            return [
                'id' => $p->id,
                'product_code' => $p->product_code,
                'description' => $p->description,
                'part_number' => $p->part_number ?? 'N/A',
                'application' => $p->application ?? 'N/A',
                'category' => $p->category ?? 'N/A',
                'position' => $p->position ?? '',
                'specification' => $p->specification ?? '',
                'oum' => $p->unit ?? '',
                'price' => $p->selling_price ?? 0,
                'price_online' => $p->price_online ?? 0,
                'price_codes' => $priceCodeMap[(int) $p->id] ?? [],
                'on_hand' => $balanceMap[(int) $p->id] ?? 0,
            ];
        });

        if ($stockFilter !== '') {
            $rows = $rows->filter(function ($row) use ($stockFilter) {
                return str_contains((string) $row['on_hand'], $stockFilter);
            })->values();
        }

        if ($idsOnly) {
            return response()->json([
                'success' => true,
                'products' => $rows->map(fn ($r) => ['id' => $r['id']])->values(),
            ]);
        }

        return response()->json([
            'success' => true,
            'products' => $rows,
            'pagination' => [
                'current_page' => $products->currentPage(),
                'last_page' => $products->lastPage(),
                'per_page' => $products->perPage(),
                'total' => $products->total(),
                'from' => $products->firstItem(),
                'to' => $products->lastItem(),
            ],
        ]);
    } catch (\Throwable $e) {
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }

    }
}

