Route::post('/admin/sales/sales-note/check-stock', function (Request $request) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

    try {
        $data = $request->validate([
            'items' => 'required|array|min:1',
            'items.*.product_id' => 'nullable|integer',
            'items.*.product_code' => 'required|string',
            'items.*.description' => 'nullable|string',
            'items.*.quantity' => 'required|integer|min:0',
            'items.*.additional_qty' => 'nullable|integer|min:0',
        ]);
        
        $items = $data['items'];
        
        $normalized = [];
        foreach ($items as $item) {
            $pid = (int) ($item['product_id'] ?? 0);
            if (!$pid) {
                $p = DB::connection('masterlist')->table('products')->where('product_code', $item['product_code'])->first(['id']);
                $pid = $p ? (int) $p->id : 0;
            }
            $qty = (int) ($item['quantity'] ?? 0);
            $add = (int) ($item['additional_qty'] ?? 0);
            $reqQty = $qty + $add;

            $normalized[] = [
                'product_id' => $pid,
                'product_code' => (string) ($item['product_code'] ?? ''),
                'description' => (string) ($item['description'] ?? ''),
                'requested_qty' => $reqQty,
            ];
        }

        $requestedByPid = [];
        $metaByPid = [];
        $issues = [];

        foreach ($normalized as $i) {
            $pid = (int) ($i['product_id'] ?? 0);
            if ($pid <= 0) {
                $issues[] = [
                    'product_id' => 0,
                    'product_code' => $i['product_code'],
                    'description' => $i['description'],
                    'requested_qty' => (float) $i['requested_qty'],
                    'available_stock' => 0,
                    'reason' => 'Product not found',
                ];
                continue;
            }

            $requestedByPid[$pid] = (float) ($requestedByPid[$pid] ?? 0) + (float) $i['requested_qty'];
            if (!isset($metaByPid[$pid])) {
                $metaByPid[$pid] = [
                    'product_code' => $i['product_code'],
                    'description' => $i['description'],
                ];
            }
        }

        $productIds = array_keys($requestedByPid);
        if (empty($productIds)) {
            return response()->json([
                'success' => true,
                'ok' => empty($issues),
                'issues' => $issues,
            ]);
        }

        $latestCreatedAtQuery = DB::connection('ledger')
            ->table('product_ledgers as pl')
            ->selectRaw('pl.product_id, MAX(pl.created_at) as max_created_at')
            ->whereIn('pl.product_id', $productIds)
            ->groupBy('pl.product_id');

        $latestIdsQuery = DB::connection('ledger')
            ->table('product_ledgers as pl')
            ->joinSub($latestCreatedAtQuery, 'lc', function ($join) {
                $join->on('pl.product_id', '=', 'lc.product_id')
                    ->on('pl.created_at', '=', 'lc.max_created_at');
            })
            ->selectRaw('MAX(pl.id) as id')
            ->groupBy('pl.product_id');

        $latestRows = DB::connection('ledger')
            ->table('product_ledgers')
            ->whereIn('id', $latestIdsQuery)
            ->get(['product_id', 'balance_stock']);

        $balanceMap = [];
        foreach ($latestRows as $r) {
            $balanceMap[(int) $r->product_id] = (float) ($r->balance_stock ?? 0);
        }

        // Default to 0 for products with no ledger entries (user requirement)
        foreach ($requestedByPid as $pid => $_) {
            if (!isset($balanceMap[(int) $pid])) {
                $balanceMap[(int) $pid] = 0;
            }
        }

        foreach ($requestedByPid as $pid => $requestedQty) {
            $available = (float) ($balanceMap[(int) $pid] ?? 0);
            if ($available < (float) $requestedQty) {
                $meta = $metaByPid[(int) $pid] ?? ['product_code' => '', 'description' => ''];
                $issues[] = [
                    'product_id' => (int) $pid,
                    'product_code' => $meta['product_code'],
                    'description' => $meta['description'],
                    'requested_qty' => (float) $requestedQty,
                    'available_stock' => $available,
                    'reason' => $available <= 0 ? 'Out of stock' : 'Not enough stock',
                ];
            }
        }

        return response()->json([
            'success' => true,
            'ok' => empty($issues),
            'issues' => $issues,
        ]);
    } catch (\Throwable $e) {
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.sales-note.check-stock');

// Sales Note - Process submission
Route::post('/admin/sales/sales-note/process', function (Request $request) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

    try {
        $data = $request->validate([
            'so_type' => 'required|string',
            'order_date' => 'required|date',
            'customer_id' => 'required|integer',
            'customer_name' => 'required|string',
            'salesman' => 'nullable|string',
            'prepared_by' => 'nullable|string',
            'checked_by' => 'nullable|string',
            'packed_by' => 'nullable|string',
            'is_rush' => 'required|boolean',
            'gross_total' => 'required|numeric',
            'total_discount' => 'required|numeric',
            'net_total' => 'required|numeric',
            'remarks' => 'nullable|string',
            'items' => 'array',
            'items.*.product_id' => 'nullable|integer',
            'items.*.product_code' => 'required|string',
            'items.*.description' => 'nullable|string',
            'items.*.price_code' => 'nullable|string|max:100',
            'items.*.quantity' => 'required|integer|min:0',
            'items.*.oum' => 'nullable|string',
            'items.*.unit_price' => 'required|numeric|min:0',
            'items.*.discount' => 'nullable|numeric|min:0',
            'items.*.additional_qty' => 'nullable|integer|min:0',
            'items.*.subtotal' => 'required|numeric|min:0',
            'converted_items' => 'nullable|array',
            'converted_items.*.source_note_id' => 'nullable|integer',
            'converted_items.*.sales_order_id' => 'nullable|integer',
            'converted_items.*.sales_order_item_id' => 'nullable|integer',
            'converted_items.*.product_id' => 'nullable|integer',
            'converted_items.*.converted_qty' => 'nullable|numeric',
            'converted_items.*.converted_amount' => 'nullable|numeric',
        ]);

        $ignoreStock = (bool) ($data['ignore_stock'] ?? $request->input('ignore_stock', false));

        $normalized = [];
        foreach ($data['items'] as $item) {
            $pid = (int) ($item['product_id'] ?? 0);
            if (!$pid) {
                $p = DB::connection('masterlist')->table('products')->where('product_code', $item['product_code'])->first(['id']);
                $pid = $p ? (int) $p->id : 0;
            }
            $qty = (int) ($item['quantity'] ?? 0);
            $add = (int) ($item['additional_qty'] ?? 0);
            $reqQty = $qty + $add;
            $normalized[] = [
                'product_id' => $pid,
                'product_code' => (string) ($item['product_code'] ?? ''),
                'description' => (string) ($item['description'] ?? ''),
                'requested_qty' => $reqQty,
            ];
        }

        $requestedByPid = [];
        $metaByPid = [];
        $issues = [];

        foreach ($normalized as $i) {
            $pid = (int) ($i['product_id'] ?? 0);
            if ($pid <= 0) {
                $issues[] = [
                    'product_id' => 0,
                    'product_code' => $i['product_code'],
                    'description' => $i['description'],
                    'requested_qty' => (float) $i['requested_qty'],
                    'available_stock' => 0,
                    'reason' => 'Product not found',
                ];
                continue;
            }

            $requestedByPid[$pid] = (float) ($requestedByPid[$pid] ?? 0) + (float) $i['requested_qty'];
            if (!isset($metaByPid[$pid])) {
                $metaByPid[$pid] = [
                    'product_code' => $i['product_code'],
                    'description' => $i['description'],
                ];
            }
        }

        $productIds = array_keys($requestedByPid);
        if (empty($productIds) && !$ignoreStock) {
            return response()->json([
                'success' => false,
                'message' => 'Stock check failed: product not found.',
                'stock_issues' => $issues,
            ], 422);
        }

        $balanceMap = [];

        if (!empty($productIds)) {
            $latestCreatedAtQuery = DB::connection('ledger')
                ->table('product_ledgers as pl')
                ->selectRaw('pl.product_id, MAX(pl.created_at) as max_created_at')
                ->whereIn('pl.product_id', $productIds)
                ->groupBy('pl.product_id');

            $latestIdsQuery = DB::connection('ledger')
                ->table('product_ledgers as pl')
                ->joinSub($latestCreatedAtQuery, 'lc', function ($join) {
                    $join->on('pl.product_id', '=', 'lc.product_id')
                        ->on('pl.created_at', '=', 'lc.max_created_at');
                })
                ->selectRaw('MAX(pl.id) as id')
                ->groupBy('pl.product_id');

            $latestRows = DB::connection('ledger')
                ->table('product_ledgers')
                ->whereIn('id', $latestIdsQuery)
                ->get(['product_id', 'balance_stock']);

            foreach ($latestRows as $r) {
                $balanceMap[(int) $r->product_id] = (float) ($r->balance_stock ?? 0);
            }

            foreach ($requestedByPid as $pid => $requestedQty) {
                $available = (float) ($balanceMap[(int) $pid] ?? 0);
                if ($available < (float) $requestedQty) {
                    $meta = $metaByPid[(int) $pid] ?? ['product_code' => '', 'description' => ''];
                    $issues[] = [
                        'product_id' => (int) $pid,
                        'product_code' => $meta['product_code'],
                        'description' => $meta['description'],
                        'requested_qty' => (float) $requestedQty,
                        'available_stock' => $available,
                        'reason' => $available <= 0 ? 'Out of stock' : 'Not enough stock',
                    ];
                }
            }

            if (!empty($issues) && !$ignoreStock) {
                return response()->json([
                    'success' => false,
                    'message' => 'Stock is not enough. Please adjust QTY or replace the item.',
                    'stock_issues' => $issues,
                ], 422);
            }
        }

        $customer = \App\Models\Customer::on('masterlist')->find($data['customer_id']);

        $salesNoteItemsHaveProductCode = \Illuminate\Support\Facades\Schema::connection('sales')->hasColumn('sales_note_items', 'product_code');

        list($salesNote, $salesNumber) = DB::connection('sales')->transaction(function () use ($data, $balanceMap, $metaByPid, $ignoreStock, $salesNoteItemsHaveProductCode) {
            $maxNum = \App\Models\SalesNote::on('sales')
                ->where(function ($q) {
                    $q->whereRaw("sales_number REGEXP '^000[0-9]{5}$'")
                      ->orWhereRaw("sales_number REGEXP '^SN-000[0-9]{5}$'");
                })
                ->selectRaw("COALESCE(MAX(CAST(REPLACE(sales_number, 'SN-', '') AS UNSIGNED)), 0) as max_num")
                ->value('max_num');
            do {
                $nextNum = ($maxNum ?: 0) + 1;
                $salesNumber = 'SN-' . str_pad($nextNum, 7, '0', STR_PAD_LEFT);
                $maxNum = $nextNum;
            } while (\App\Models\SalesNote::on('sales')->where('sales_number', $salesNumber)->exists());

            $note = \App\Models\SalesNote::create([
                'sales_number' => $salesNumber,
                'so_type' => $data['so_type'],
                'order_date' => $data['order_date'],
                'customer_id' => $data['customer_id'],
                'customer_name' => $data['customer_name'],
                'salesman' => $data['salesman'],
                'prepared_by' => $data['prepared_by'],
                'checked_by' => $data['checked_by'],
                'packed_by' => $data['packed_by'],
                'is_rush' => $data['is_rush'],
                'gross_total' => $data['gross_total'],
                'total_discount' => $data['total_discount'],
                'net_total' => $data['net_total'],
                'status' => 'Open',
                'remarks' => $data['remarks'],
            ]);

            $outSoFarByPid = [];
            foreach ($data['items'] as $itemData) {
                $product = null;
                if (!empty($itemData['product_id'])) {
                    $product = \App\Models\Product::on('masterlist')->find($itemData['product_id']);
                }
                if (!$product) {
                    $product = \App\Models\Product::on('masterlist')->where('product_code', $itemData['product_code'])->first();
                }
                $outQty = (int) ($itemData['quantity'] ?? 0) + (int) ($itemData['additional_qty'] ?? 0);
                $pid = (int) ($product?->id ?? 0);
                $availableStart = $pid > 0 ? (float) ($balanceMap[$pid] ?? 0) : 0;
                $alreadyOut = (float) ($outSoFarByPid[$pid] ?? 0);
                $availableNow = $availableStart - $alreadyOut;
                $newBalance = $availableNow - $outQty;

                if (($pid <= 0 || $newBalance < 0) && !$ignoreStock) {
                    throw new \RuntimeException('Stock is not enough. Please adjust QTY or replace the item.');
                }

                $salesNoteItemPayload = [
                    'sales_note_id' => $note->id,
                    'product_id' => $product?->id ?? 0,
                    'price_code' => trim((string) ($itemData['price_code'] ?? '')) !== '' ? trim((string) $itemData['price_code']) : null,
                    'description' => $itemData['description'],
                    'quantity' => $itemData['quantity'],
                    'oum' => $itemData['oum'] ?? '',
                    'unit_price' => $itemData['unit_price'],
                    'discount' => $itemData['discount'] ?? 0,
                    'additional_qty' => $itemData['additional_qty'] ?? 0,
                    'subtotal' => $itemData['subtotal'],
                ];

                if ($salesNoteItemsHaveProductCode) {
                    $salesNoteItemPayload['product_code'] = $itemData['product_code'];
                }

                \App\Models\SalesNoteItem::create($salesNoteItemPayload);

                $outSoFarByPid[$pid] = $alreadyOut + $outQty;
            }

            // Process converted items from partial sales notes
            $convertedItems = $data['converted_items'] ?? [];
            $sourceNoteIdsToCheck = [];

            foreach ($convertedItems as $convItem) {
                $convertedQty = (float) ($convItem['converted_qty'] ?? 0);
                if ($convertedQty <= 0) continue;

                $sourceSalesNoteItem = null;
                $sourceNoteId = (int) ($convItem['source_note_id'] ?? 0);

                if (!empty($convItem['sales_order_item_id'])) {
                    // Item came from a SalesOrder (was previously invoiced)
                    $sourceItem = \App\Models\SalesOrderItem::on('sales')->find($convItem['sales_order_item_id']);
                    if (!$sourceItem) continue;

                    // Update actual_qty in source sales_order_item
                    $sourceItem->actual_qty += $convertedQty;
                    $sourceItem->save();

                    // Get source sales_note_item for tracking
                    $sourceSalesOrder = \App\Models\SalesOrder::on('sales')->find($sourceItem->sales_order_id);
                    if ($sourceSalesOrder) {
                        $sourceNoteId = (int) $sourceSalesOrder->sales_note_id;
                        $sourceSalesNoteItem = \App\Models\SalesNoteItem::on('sales')
                            ->where('sales_note_id', $sourceSalesOrder->sales_note_id)
                            ->where('product_id', $convItem['product_id'])
                            ->first();
                    }
                } else {
                    // Item came directly from a SalesNoteItem (never invoiced)
                    $sourceSalesNoteItem = \App\Models\SalesNoteItem::on('sales')
                        ->where('sales_note_id', $sourceNoteId)
                        ->where('product_id', $convItem['product_id'])
                        ->first();
                }

                if (!$sourceSalesNoteItem) {
                    throw new \RuntimeException('Source sales note item was not found for converted item.');
                }

                $newSourceQty = (float) $sourceSalesNoteItem->quantity - $convertedQty;
                if ($newSourceQty < -0.0001) {
                    throw new \RuntimeException("Cannot convert more than remaining quantity for item {$sourceSalesNoteItem->product_code}.");
                }
                $newSourceQty = max(0, $newSourceQty);
                $newSourceSubtotal = $newSourceQty * (float) $sourceSalesNoteItem->unit_price * (1 - ((float) $sourceSalesNoteItem->discount / 100));

                $sourceSalesNoteItem->quantity = (int) $newSourceQty;
                $sourceSalesNoteItem->subtotal = round($newSourceSubtotal, 2);
                $sourceSalesNoteItem->save();

                // Create conversion tracking record
                \App\Models\SalesNoteConvertedItem::create([
                    'source_sales_note_id' => $sourceNoteId ?: $sourceSalesNoteItem->sales_note_id,
                    'source_sales_note_item_id' => $sourceSalesNoteItem->id,
                    'target_sales_note_id' => $note->id,
                    'sales_order_id' => $convItem['sales_order_id'] ?? null,
                    'sales_order_item_id' => $convItem['sales_order_item_id'],
                    'product_id' => $convItem['product_id'],
                    'converted_qty' => $convertedQty,
                    'converted_amount' => $convItem['converted_amount'] ?? 0,
                ]);

                // Track source note IDs for auto-close check
                $sourceNoteIdToCheck = $sourceNoteId ?: (int) $sourceSalesNoteItem->sales_note_id;
                if ($sourceNoteIdToCheck) {
                    $sourceNoteIdsToCheck[$sourceNoteIdToCheck] = true;
                }
            }

            // Auto-close source notes after all conversions are processed
            foreach (array_keys($sourceNoteIdsToCheck) as $sourceNoteId) {
                $sourceNote = \App\Models\SalesNote::on('sales')->find($sourceNoteId);
                if (!$sourceNote || $sourceNote->status !== 'Partial') continue;

                $remainingSourceItems = \App\Models\SalesNoteItem::on('sales')
                    ->where('sales_note_id', $sourceNote->id)
                    ->where('quantity', '>', 0)
                    ->get();

                $grossTotal = 0;
                $totalDiscount = 0;
                $netTotal = 0;
                foreach ($remainingSourceItems as $sourceItemRow) {
                    $rowGross = (float) $sourceItemRow->quantity * (float) $sourceItemRow->unit_price;
                    $grossTotal += $rowGross;
                    $totalDiscount += $rowGross * ((float) $sourceItemRow->discount / 100);
                    $netTotal += (float) $sourceItemRow->subtotal;
                }

                $sourceNote->gross_total = round($grossTotal, 2);
                $sourceNote->total_discount = round($totalDiscount, 2);
                $sourceNote->net_total = round($netTotal, 2);

                // Check if all sales_order_items are fully processed
                $salesOrders = \App\Models\SalesOrder::on('sales')
                    ->where('sales_note_id', $sourceNote->id)
                    ->get();

                $allSalesOrderItemsDone = true;
                foreach ($salesOrders as $so) {
                    $soItems = \App\Models\SalesOrderItem::on('sales')
                        ->where('sales_order_id', $so->id)
                        ->get();
                    foreach ($soItems as $item) {
                        if ($item->quantity > $item->actual_qty) {
                            $allSalesOrderItemsDone = false;
                            break 2;
                        }
                    }
                }

                // Check if all note-only items (never invoiced) were converted
                $allNoteItemsConverted = true;
                $noteItems = \App\Models\SalesNoteItem::on('sales')
                    ->where('sales_note_id', $sourceNote->id)
                    ->get();

                foreach ($noteItems as $ni) {
                    // Check if this note item has a corresponding sales_order_item
                    $hasOrderItem = false;
                    foreach ($salesOrders as $so) {
                        $exists = \App\Models\SalesOrderItem::on('sales')
                            ->where('sales_order_id', $so->id)
                            ->where('product_id', $ni->product_id)
                            ->exists();
                        if ($exists) {
                            $hasOrderItem = true;
                            break;
                        }
                    }

                    // If this note item was never in a sales order, check if it was converted
                    if (!$hasOrderItem) {
                        $converted = \App\Models\SalesNoteConvertedItem::on('sales')
                            ->where('source_sales_note_id', $sourceNote->id)
                            ->where('product_id', $ni->product_id)
                            ->exists();
                        if (!$converted) {
                            $allNoteItemsConverted = false;
                            break;
                        }
                    }
                }

                if ($remainingSourceItems->isEmpty() || ($allSalesOrderItemsDone && $allNoteItemsConverted)) {
                    $sourceNote->status = 'Closed';
                } elseif ($remainingSourceItems->isNotEmpty()) {
                    $sourceNote->status = 'Partial';
                }
                $sourceNote->save();
            }

            return [$note, $salesNumber];
        });

        $salesNote->load('items');
        $actor = hatdogAuditActor($user);
        $recordName = trim((string) (($data['customer_name'] ?? '') !== '' ? $data['customer_name'] : ('Sales Note ' . $salesNumber)));

        hatdogWriteAuditTrail([
            'module' => 'sales_note',
            'action' => 'Processed',
            'source_connection' => 'sales',
            'source_table' => 'sales_notes',
            'source_id' => $salesNote->id,
            'display_id' => $salesNumber,
            'record_name' => $recordName,
            'user_name' => $actor['name'],
            'user_identifier' => $actor['identifier'],
            'audit_data' => [
                'sales_note' => $salesNote->toArray(),
                'customer' => $customer?->toArray(),
                'items' => $salesNote->items->map(fn ($item) => $item->toArray())->values()->all(),
            ],
        ]);

        return response()->json([
            'success' => true,
            'message' => 'Sales Note processed successfully',
            'sales_number' => $salesNumber,
        ]);
    } catch (\Throwable $e) {
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.sales-note.process');

