// Sales Note - Active list (Open status)
Route::get('/admin/sales/sales-note/active', function (Request $request) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

    try {
        $page = $request->get('page', 1);
        $perPage = $request->get('perPage', 50);
        $search = $request->get('search', []);

        $query = \App\Models\SalesNote::on('sales')
            ->whereIn('status', ['Open', 'Partial']);

        // Apply search filters
        if (!empty($search)) {
            if (!empty($search['date'])) {
                $query->where('order_date', 'LIKE', '%' . $search['date'] . '%');
            }
            if (!empty($search['sales_number'])) {
                $query->where('sales_number', 'LIKE', '%' . $search['sales_number'] . '%');
            }
            if (!empty($search['customer_name'])) {
                $query->where('customer_name', 'LIKE', '%' . $search['customer_name'] . '%');
            }
            if (!empty($search['net_total'])) {
                $query->where('net_total', 'LIKE', '%' . $search['net_total'] . '%');
            }
            if (!empty($search['salesman'])) {
                $query->where('salesman', 'LIKE', '%' . $search['salesman'] . '%');
            }
            if (!empty($search['status'])) {
                $query->where('status', 'LIKE', '%' . $search['status'] . '%');
            }
            if (!empty($search['checked_by'])) {
                $query->where('checked_by', 'LIKE', '%' . $search['checked_by'] . '%');
            }
            if (!empty($search['remarks'])) {
                $query->where('remarks', 'LIKE', '%' . $search['remarks'] . '%');
            }
        }

        $query->orderBy('created_at', 'desc');
        $notes = $query->paginate($perPage, ['*'], 'page', $page);

        $formatted = $notes->getCollection()->map(function ($note) {
            return [
                'id' => $note->id,
                'sales_number' => $note->sales_number,
                'so_type' => $note->so_type,
                'customer_name' => $note->customer_name,
                'net_total' => $note->net_total,
                'order_date' => $note->order_date,
                'salesman' => $note->salesman,
                'status' => $note->status,
                'checked_by' => $note->checked_by,
                'remarks' => $note->remarks,
            ];
        });

        return response()->json([
            'success' => true,
            'notes' => $formatted,
            'pagination' => [
                'current_page' => $notes->currentPage(),
                'last_page' => $notes->lastPage(),
                'per_page' => $notes->perPage(),
                'total' => $notes->total(),
                'from' => $notes->firstItem(),
                'to' => $notes->lastItem(),
            ],
        ]);
    } catch (\Exception $e) {
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.sales-note.active');

