Route::post('/admin/sales/sales-note/update/{id}', function (Request $request, $id) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

    try {
        $data = $request->validate([
            'so_type' => 'required|string',
            'order_date' => 'required|date',
            'customer_id' => 'required|integer',
            'customer_name' => 'required|string',
            'salesman' => 'nullable|string',
            'prepared_by' => 'nullable|string',
            'checked_by' => 'nullable|string',
            'packed_by' => 'nullable|string',
            'is_rush' => 'required|boolean',
            'gross_total' => 'required|numeric',
            'total_discount' => 'required|numeric',
            'net_total' => 'required|numeric',
            'remarks' => 'nullable|string',
            'items' => 'array',
            'items.*.product_id' => 'nullable|integer',
            'items.*.product_code' => 'required|string',
            'items.*.description' => 'nullable|string',
            'items.*.price_code' => 'nullable|string|max:100',
            'items.*.quantity' => 'required|integer|min:0',
            'items.*.oum' => 'nullable|string',
            'items.*.unit_price' => 'required|numeric|min:0',
            'items.*.discount' => 'nullable|numeric|min:0',
            'items.*.additional_qty' => 'nullable|integer|min:0',
            'items.*.subtotal' => 'required|numeric|min:0',
            'items.*.sales_note_item_id' => 'nullable|integer',
            'items.*.sales_order_item_id' => 'nullable|integer',
            'items.*.actual_qty' => 'nullable|numeric|min:0',
            'items.*.remaining_qty' => 'nullable|numeric|min:0',
            'items.*._changed' => 'nullable|boolean',
            'sales_order_id' => 'nullable|integer',
            'deleted_item_ids' => 'nullable|array',
            'deleted_item_ids.*' => 'integer|min:1',
        ]);

        $ignoreStock = (bool) ($request->input('ignore_stock', false));

        $salesNote = \App\Models\SalesNote::on('sales')->with('items')->findOrFail($id);
        $noteStatus = $salesNote->status;

        // CRITICAL FIX: Build map of existing item quantities BEFORE normalization
        $existingQtyMap = [];
        foreach ($salesNote->items as $ei) {
            $pid = (int) $ei->product_id;
            $existingQtyMap[$pid] = (float) ($ei->quantity ?? 0) + (float) ($ei->additional_qty ?? 0);
        }

        $normalized = [];
        foreach ($data['items'] as $item) {
            $pid = (int) ($item['product_id'] ?? 0);
            if (!$pid) {
                $p = DB::connection('masterlist')->table('products')->where('product_code', $item['product_code'])->first(['id']);
                $pid = $p ? (int) $p->id : 0;
            }
            $qty = (int) ($item['quantity'] ?? 0);
            $add = (int) ($item['additional_qty'] ?? 0);
            $reqQty = $qty + $add;
            $normalized[] = [
                'product_id' => $pid,
                'product_code' => (string) ($item['product_code'] ?? ''),
                'description' => (string) ($item['description'] ?? ''),
                'requested_qty' => $reqQty,
            ];
        }

        $requestedByPid = [];
        $metaByPid = [];
        $issues = [];

        foreach ($normalized as $i) {
            $pid = (int) ($i['product_id'] ?? 0);
            if ($pid <= 0) {
                $issues[] = [
                    'product_id' => 0,
                    'product_code' => $i['product_code'],
                    'description' => $i['description'],
                    'requested_qty' => (float) $i['requested_qty'],
                    'available_stock' => 0,
                    'reason' => 'Product not found',
                ];
                continue;
            }

            // Calculate NET INCREASE only (not total quantity)
            $existingQty = (float) ($existingQtyMap[$pid] ?? 0);
            $newQty = (float) $i['requested_qty'];
            $netIncrease = max(0, $newQty - $existingQty); // Only check if increasing

            if ($netIncrease > 0) {
                // Only track items that need MORE stock
                $requestedByPid[$pid] = (float) ($requestedByPid[$pid] ?? 0) + $netIncrease;
                if (!isset($metaByPid[$pid])) {
                    $metaByPid[$pid] = [
                        'product_code' => $i['product_code'],
                        'description' => $i['description'],
                    ];
                }
            }
        }

        $productIds = array_keys($requestedByPid);
        // No stock check is required when the edit does not increase any item quantity.
        if (empty($productIds) && !$ignoreStock && !empty($issues)) {
            return response()->json([
                'success' => false,
                'message' => 'Stock check failed: product not found.',
                'stock_issues' => $issues,
            ], 422);
        }

        $balanceMap = [];

        if (!empty($productIds)) {
            $latestCreatedAtQuery = DB::connection('ledger')
                ->table('product_ledgers as pl')
                ->selectRaw('pl.product_id, MAX(pl.created_at) as max_created_at')
                ->whereIn('pl.product_id', $productIds)
                ->groupBy('pl.product_id');

            $latestIdsQuery = DB::connection('ledger')
                ->table('product_ledgers as pl')
                ->joinSub($latestCreatedAtQuery, 'lc', function ($join) {
                    $join->on('pl.product_id', '=', 'lc.product_id')
                        ->on('pl.created_at', '=', 'lc.max_created_at');
                })
                ->selectRaw('MAX(pl.id) as id')
                ->groupBy('pl.product_id');

            $latestRows = DB::connection('ledger')
                ->table('product_ledgers')
                ->whereIn('id', $latestIdsQuery)
                ->get(['product_id', 'balance_stock']);

            foreach ($latestRows as $r) {
                $balanceMap[(int) $r->product_id] = (float) ($r->balance_stock ?? 0);
            }

            foreach ($requestedByPid as $pid => $requestedQty) {
                $available = (float) ($balanceMap[(int) $pid] ?? 0);
                if ($available < (float) $requestedQty) {
                    $meta = $metaByPid[(int) $pid] ?? ['product_code' => '', 'description' => ''];
                    $issues[] = [
                        'product_id' => (int) $pid,
                        'product_code' => $meta['product_code'],
                        'description' => $meta['description'],
                        'requested_qty' => (float) $requestedQty,
                        'available_stock' => $available,
                        'reason' => $available <= 0 ? 'Out of stock' : 'Not enough stock',
                    ];
                }
            }

            if (!empty($issues) && !$ignoreStock) {
                return response()->json([
                    'success' => false,
                    'message' => 'Stock is not enough. Please adjust QTY or replace the item.',
                    'stock_issues' => $issues,
                ], 422);
            }
        }

        $originalNoteData = $salesNote->toArray();
        $originalItemsData = $salesNote->items->map(fn ($item) => $item->toArray())->values()->all();

        $customer = \App\Models\Customer::on('masterlist')->find($data['customer_id']);

        $salesNote->update([
            'so_type' => $data['so_type'],
            'customer_id' => $data['customer_id'],
            'customer_name' => $data['customer_name'],
            'order_date' => $data['order_date'],
            'salesman' => $data['salesman'],
            'prepared_by' => $data['prepared_by'],
            'checked_by' => $data['checked_by'],
            'packed_by' => $data['packed_by'],
            'is_rush' => $data['is_rush'],
            'gross_total' => $data['gross_total'],
            'total_discount' => $data['total_discount'],
            'net_total' => $data['net_total'],
            'remarks' => $data['remarks'] ?? $salesNote->remarks ?? '',
        ]);

        $salesOrderId = $request->filled('sales_order_id')
            ? (int) $request->input('sales_order_id')
            : null;
        $editingSpecificInvoice = $salesOrderId !== null;

        // Process explicit deletions (staged from frontend, not orphan cleanup)
        $deletedItemIds = $request->input('deleted_item_ids', []);
        if (!empty($deletedItemIds)) {
            // Validate all IDs belong to this sales note
            $validIds = \App\Models\SalesNoteItem::on('sales')
                ->where('sales_note_id', $salesNote->id)
                ->whereIn('id', $deletedItemIds)
                ->pluck('id')
                ->toArray();

            $invalidIds = array_diff($deletedItemIds, $validIds);
            if (!empty($invalidIds)) {
                throw new \Exception('Invalid item IDs for deletion: ' . implode(', ', $invalidIds));
            }

            // Processed/invoiced items are intentionally allowed to be removed here.
            // When a specific invoice is being edited, the selected Sales Order
            // snapshot is reshaped below and its Product Ledger OUT movement is
            // finalized only when the user confirms the Sales Order edit.

            \App\Models\SalesNoteItem::on('sales')
                ->whereIn('id', $validIds)
                ->delete();

            // Do not touch product_ledgers here. The selected Sales Order snapshot
            // is synchronized below, and ledger deletion is deferred until the
            // Sales Order Final Save/Confirm action.
        }

        // Smart update sales_note_items
        $salesNoteItemsHaveProductCode = \Illuminate\Support\Facades\Schema::connection('sales')->hasColumn('sales_note_items', 'product_code');
        $submittedSniIds = [];
        foreach ($data['items'] as $itemData) {
            $sniId = !empty($itemData['sales_note_item_id']) ? (int) $itemData['sales_note_item_id'] : null;
            $changed = isset($itemData['_changed']) ? (bool) $itemData['_changed'] : true;
            $product = null;
            if (!empty($itemData['product_id'])) {
                $product = \App\Models\Product::on('masterlist')->find($itemData['product_id']);
            }
            if (!$product) {
                $product = \App\Models\Product::on('masterlist')->where('product_code', $itemData['product_code'])->first();
            }
            $itemPayload = [
                'product_id' => $product?->id ?? 0,
                'price_code' => trim((string) ($itemData['price_code'] ?? '')) !== '' ? trim((string) $itemData['price_code']) : null,
                'description' => $itemData['description'],
                'quantity' => $itemData['quantity'],
                'oum' => $itemData['oum'] ?? '',
                'unit_price' => $itemData['unit_price'],
                'discount' => $itemData['discount'] ?? 0,
                'additional_qty' => $itemData['additional_qty'] ?? 0,
                'subtotal' => $itemData['subtotal'],
            ];
            if ($salesNoteItemsHaveProductCode) {
                $itemPayload['product_code'] = $itemData['product_code'];
            }

            $salesNoteItem = null;
            if ($sniId && $sniId > 0) {
                $salesNoteItem = \App\Models\SalesNoteItem::on('sales')
                    ->where('sales_note_id', $salesNote->id)
                    ->where('id', $sniId)
                    ->first();
            }
            if (!$salesNoteItem && !empty($itemPayload['product_id'])) {
                $salesNoteItem = \App\Models\SalesNoteItem::on('sales')
                    ->where('sales_note_id', $salesNote->id)
                    ->where('product_id', $itemPayload['product_id'])
                    ->first();
            }

            if ($salesNoteItem) {
                $submittedSniIds[] = $salesNoteItem->id;
                if ($changed) {
                    $salesNoteItem->update($itemPayload);
                }
            } else {
                $newItem = \App\Models\SalesNoteItem::on('sales')->create(array_merge($itemPayload, [
                    'sales_note_id' => $salesNote->id,
                ]));
                $submittedSniIds[] = $newItem->id;
            }
        }

        // Recalculate total from saved items (authoritative)
        $finalItems = \App\Models\SalesNoteItem::on('sales')
            ->where('sales_note_id', $salesNote->id)
            ->get();
        $calculatedGross = 0;
        $calculatedDiscount = 0;
        foreach ($finalItems as $fi) {
            $qty = (float) ($fi->quantity ?? 0);
            $price = (float) ($fi->unit_price ?? 0);
            $discPct = (float) ($fi->discount ?? 0);
            $totalPrice = (float) ($fi->subtotal ?? 0);
            $rowGross = $qty * $price;
            $rowDiscount = $rowGross * ($discPct / 100);
            $calculatedGross += $rowGross;
            $calculatedDiscount += $rowDiscount;
        }
        $calculatedNet = $calculatedGross - $calculatedDiscount;

        $salesNote->update([
            'gross_total' => $calculatedGross,
            'total_discount' => $calculatedDiscount,
            'net_total' => $calculatedNet,
        ]);

        $addedItems = [];
        $deletedItems = [];
        $updatedItems = [];
        $salesOrder = null;

        // Sync the selected invoice even while the parent note is still Partial.
        // Closed notes without a selected invoice keep the existing fallback flow.
        // This changes only the Sales Order item snapshot; product_ledgers are
        // reconciled later when the user confirms Edit Sales Order.
        if ($editingSpecificInvoice || strcasecmp($noteStatus, 'Closed') === 0) {
            $salesOrder = $salesOrderId
                ? \App\Models\SalesOrder::on('sales')
                    ->where('id', $salesOrderId)
                    ->where('sales_note_id', $salesNote->id)
                    ->first()
                : \App\Models\SalesOrder::on('sales')->where('sales_note_id', $salesNote->id)->first();

            if ($salesOrder) {
                $soPayload = [
                    'customer_id' => $data['customer_id'],
                    'customer_name' => $data['customer_name'],
                ];
                $salesOrder->update($soPayload);

                // Sync sales_order_items: match by product_id
                $submittedSoiPids = [];
                foreach ($data['items'] as $itemData) {
                    $pid = !empty($itemData['product_id']) ? (int) $itemData['product_id'] : 0;
                    if (!$pid) continue;
                    $submittedSoiPids[] = $pid;
                    $salesOrderItemId = !empty($itemData['sales_order_item_id'])
                        ? (int) $itemData['sales_order_item_id']
                        : null;
                    $soi = $salesOrderItemId
                        ? \App\Models\SalesOrderItem::on('sales')
                            ->where('sales_order_id', $salesOrder->id)
                            ->where('id', $salesOrderItemId)
                            ->first()
                        : null;
                    if (!$soi) {
                        $soi = \App\Models\SalesOrderItem::on('sales')
                            ->where('sales_order_id', $salesOrder->id)
                            ->where('product_id', $pid)
                            ->first();
                    }
                    $qty = (int) ($itemData['quantity'] ?? 0) + (int) ($itemData['additional_qty'] ?? 0);
                    $unitPrice = (float) ($itemData['unit_price'] ?? 0);
                    $discount = (float) ($itemData['discount'] ?? 0);
                    $subtotal = array_key_exists('subtotal', $itemData)
                        ? (float) $itemData['subtotal']
                        : $qty * $unitPrice * (1 - ($discount / 100));

                    if ($soi) {
                        $beforeSoi = $soi->toArray();
                        $changed = isset($itemData['_changed']) ? (bool) $itemData['_changed'] : true;
                        if ($changed) {
                            $soi->update([
                                'quantity' => $qty,
                                'additional_qty' => $itemData['additional_qty'] ?? 0,
                                'oum' => $itemData['oum'] ?? $soi->oum,
                                'unit_price' => $unitPrice,
                                'discount' => $discount,
                                'subtotal' => $subtotal,
                                'description' => $itemData['description'] ?? '',
                                'product_code' => $itemData['product_code'] ?? '',
                                'price_code' => $itemData['price_code'] ?? '',
                                'particulars' => $itemData['particulars'] ?? $soi->particulars,
                            ]);
                            $soi->refresh();
                            $changes = [];
                            foreach (['quantity', 'actual_qty', 'additional_qty', 'oum', 'unit_price', 'discount'] as $field) {
                                $beforeValue = $beforeSoi[$field] ?? null;
                                $afterValue = $soi->{$field};
                                if ((string) $beforeValue !== (string) $afterValue) {
                                    $changes[$field] = ['before' => $beforeValue, 'after' => $afterValue];
                                }
                            }
                            if (!empty($changes)) {
                                $updatedItems[] = [
                                    'id' => (int) $soi->id,
                                    'product_id' => (int) $soi->product_id,
                                    'product_code' => (string) $soi->product_code,
                                    'changes' => $changes,
                                ];
                            }
                        }
                    } else {
                        // No ledger entry is created here. New invoice lines are
                        // finalized into product_ledgers only when Edit SO is saved.
                        $newSoi = \App\Models\SalesOrderItem::on('sales')->create([
                            'sales_order_id' => $salesOrder->id,
                            'product_id' => $pid,
                            'product_code' => $itemData['product_code'] ?? '',
                            'price_code' => $itemData['price_code'] ?? '',
                            'description' => $itemData['description'] ?? '',
                            'quantity' => $qty,
                            'actual_qty' => $qty,
                            'additional_qty' => $itemData['additional_qty'] ?? 0,
                            'oum' => $itemData['oum'] ?? '',
                            'unit_price' => $unitPrice,
                            'discount' => $discount,
                            'additional_discount' => $itemData['additional_discount'] ?? 0,
                            'subtotal' => $subtotal,
                            'particulars' => $itemData['particulars'] ?? '',
                        ]);
                        $addedItems[] = [
                            'id' => (int) $newSoi->id,
                            'product_id' => (int) $newSoi->product_id,
                            'product_code' => (string) $newSoi->product_code,
                            'price_code' => (string) ($newSoi->price_code ?? ''),
                            'description' => (string) ($newSoi->description ?? ''),
                            'quantity' => (float) ($newSoi->quantity ?? 0),
                            'actual_qty' => (float) ($newSoi->actual_qty ?? 0),
                            'additional_qty' => (float) ($newSoi->additional_qty ?? 0),
                            'oum' => (string) ($newSoi->oum ?? ''),
                            'unit_price' => (float) ($newSoi->unit_price ?? 0),
                            'discount' => (float) ($newSoi->discount ?? 0),
                            'additional_discount' => (float) ($newSoi->additional_discount ?? 0),
                            'subtotal' => (float) ($newSoi->subtotal ?? 0),
                            'particulars' => (string) ($newSoi->particulars ?? ''),
                        ];
                    }
                }

                // Remove invoice rows that were deleted from the Sales Note.
                // Capture their full values first so the Sales Order edit modal can
                // reconstruct them in maroon/yellow for final confirmation.
                $removeQuery = \App\Models\SalesOrderItem::on('sales')
                    ->where('sales_order_id', $salesOrder->id);
                if (!empty($submittedSoiPids)) {
                    $removeQuery->whereNotIn('product_id', array_values(array_unique($submittedSoiPids)));
                }
                $removedSalesOrderItems = $removeQuery->get();
                foreach ($removedSalesOrderItems as $removedItem) {
                    $deletedItems[(int) $removedItem->product_id] = [
                        'id' => (int) $removedItem->id,
                        'product_id' => (int) $removedItem->product_id,
                        'product_code' => (string) ($removedItem->product_code ?? ''),
                        'price_code' => (string) ($removedItem->price_code ?? ''),
                        'description' => (string) ($removedItem->description ?? ''),
                        'quantity' => (float) ($removedItem->quantity ?? 0),
                        'actual_qty' => (float) ($removedItem->actual_qty ?? 0),
                        'additional_qty' => (float) ($removedItem->additional_qty ?? 0),
                        'oum' => (string) ($removedItem->oum ?? ''),
                        'unit_price' => (float) ($removedItem->unit_price ?? 0),
                        'discount' => (float) ($removedItem->discount ?? 0),
                        'additional_discount' => (float) ($removedItem->additional_discount ?? 0),
                        'subtotal' => (float) ($removedItem->subtotal ?? 0),
                        'particulars' => (string) ($removedItem->particulars ?? ''),
                    ];
                }
                if ($removedSalesOrderItems->isNotEmpty()) {
                    \App\Models\SalesOrderItem::on('sales')
                        ->whereIn('id', $removedSalesOrderItems->pluck('id')->all())
                        ->delete();
                }

                // The selected invoice total reflects the reshaped snapshot, not
                // the deleted rows that are shown only as review metadata.

                $salesOrder->update([
                    'total_amount' => (float) $salesOrder->items()->sum('subtotal'),
                ]);
                $salesOrder->refresh()->load('items');
            } else {
                if ($editingSpecificInvoice) {
                    throw new \Exception('Selected sales order does not belong to this sales note.');
                }

                // Create new sales_order if none exists
                $orderNumber = 'SN-EDIT-' . $salesNote->id;
                $salesOrder = \App\Models\SalesOrder::on('sales')->create([
                    'sales_note_id' => $salesNote->id,
                    'order_number' => $orderNumber,
                    'customer_id' => $data['customer_id'],
                    'customer_name' => $data['customer_name'],
                    'total_amount' => $data['net_total'],
                    'status' => 'Confirmed',
                ]);

                foreach ($data['items'] as $itemData) {
                    $pid = !empty($itemData['product_id']) ? (int) $itemData['product_id'] : 0;
                    if (!$pid) continue;
                    $qty = (int) ($itemData['quantity'] ?? 0) + (int) ($itemData['additional_qty'] ?? 0);
                    $unitPrice = (float) ($itemData['unit_price'] ?? 0);
                    \App\Models\SalesOrderItem::on('sales')->create([
                        'sales_order_id' => $salesOrder->id,
                        'product_id' => $pid,
                        'product_code' => $itemData['product_code'] ?? '',
                        'price_code' => $itemData['price_code'] ?? '',
                        'description' => $itemData['description'] ?? '',
                        'quantity' => $qty,
                        'actual_qty' => $qty,
                        'additional_qty' => $itemData['additional_qty'] ?? 0,
                        'oum' => $itemData['oum'] ?? '',
                        'unit_price' => $unitPrice,
                        'discount' => $itemData['discount'] ?? 0,
                        'subtotal' => $itemData['subtotal'] ?? ($qty * $unitPrice),
                    ]);
                }
            }
        }

        $salesNote->load('items');
        $actor = hatdogAuditActor($user);
        $recordName = trim((string) (($data['customer_name'] ?? '') !== '' ? $data['customer_name'] : ('Sales Note ' . $salesNote->sales_number)));

        hatdogWriteAuditTrail([
            'module' => 'sales_note',
            'action' => 'Updated',
            'source_connection' => 'sales',
            'source_table' => 'sales_notes',
            'source_id' => $salesNote->id,
            'display_id' => $salesNote->sales_number,
            'record_name' => $recordName,
            'user_name' => $actor['name'],
            'user_identifier' => $actor['identifier'],
            'audit_data' => [
                'before' => [
                    'sales_note' => $originalNoteData,
                    'items' => $originalItemsData,
                ],
                'after' => [
                    'sales_note' => $salesNote->toArray(),
                    'customer' => $customer?->toArray(),
                    'items' => $salesNote->items->map(fn ($item) => $item->toArray())->values()->all(),
                ]
            ],
        ]);

        return response()->json([
            'success' => true,
            'message' => 'Sales Note updated successfully',
            'sales_number' => $salesNote->sales_number,
            'sales_order_id' => $salesOrder?->id ?? $salesOrderId,
            'added_items' => array_values($addedItems),
            'deleted_items' => array_values($deletedItems),
            'updated_items' => array_values($updatedItems),
        ]);
    } catch (\Throwable $e) {
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.sales-note.update');

// Sales Note - Detail view (header + items)
Route::get('/admin/sales/sales-note/detail/{id}', function ($id) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

    try {
        $note = \App\Models\SalesNote::on('sales')->with('items')->findOrFail($id);

        $items = $note->items;

        // Bulk fetch balance_stock from product_ledgers
        $productIds = $items->pluck('product_id')->filter()->unique()->toArray();
        $balanceStocks = [];
        $priceCodeMap = [];
        if (!empty($productIds)) {
            $ledgers = \Illuminate\Support\Facades\DB::connection('ledger')
                ->table('product_ledgers')
                ->whereIn('product_id', $productIds)
                ->orderBy('date', 'desc')
                ->orderBy('id', 'desc')
                ->get()
                ->groupBy('product_id')
                ->map->first();
            foreach ($ledgers as $pid => $ledger) {
                $balanceStocks[$pid] = (int) ($ledger->balance_stock ?? 0);
            }

            $priceCodeRows = DB::connection('masterlist')
                ->table('product_price_codes')
                ->whereIn('product_id', $productIds)
                ->orderBy('product_id')
                ->orderBy('sort_order')
                ->orderBy('id')
                ->get(['product_id', 'price_code', 'selling_price', 'sort_order']);

            foreach ($priceCodeRows as $row) {
                $pid = (int) $row->product_id;
                $priceCodeMap[$pid][] = [
                    'price_code' => $row->price_code,
                    'selling_price' => (float) ($row->selling_price ?? 0),
                    'sort_order' => (int) ($row->sort_order ?? 0),
                ];
            }
        }

        return response()->json([
            'success' => true,
            'note' => [
                'sales_number' => $note->sales_number,
                'so_type' => $note->so_type,
                'order_date' => $note->order_date,
                'customer_name' => $note->customer_name,
                'customer_id' => $note->customer_id,
                'salesman' => $note->salesman,
                'prepared_by' => $note->prepared_by,
                'checked_by' => $note->checked_by,
                'packed_by' => $note->packed_by,
                'is_rush' => $note->is_rush,
                'gross_total' => $note->gross_total,
                'total_discount' => $note->total_discount,
                'net_total' => $note->net_total,
                'status' => $note->status,
                'remarks' => $note->remarks ?? '---',
                'items' => $items->map(function ($item) use ($balanceStocks, $priceCodeMap) {
                    $product = \App\Models\Product::on('masterlist')->find($item->product_id);
                    return [
                        'item_id' => $item->id,
                        'product_id' => (int)($item->product_id ?? 0),
                        'price_code' => $item->price_code,
                        'product_code' => $item->product_code ?? ($product ? $product->product_code : ''),
                        'description' => $item->description,
                        'part_number' => $product ? $product->part_number : '',
                        'quantity' => $item->quantity,
                        'additional_qty' => $item->additional_qty,
                        'oum' => $item->oum,
                        'unit_price' => $item->unit_price,
                        'discount' => $item->discount,
                        'subtotal' => $item->subtotal,
                        'on_hand' => $balanceStocks[$item->product_id] ?? 0,
                        'cost' => $product ? $product->cost : 0,
                        'selling_price' => $product ? $product->selling_price : 0,
                        'price_online' => $product ? $product->price_online : 0,
                        'price_codes' => $priceCodeMap[(int) $item->product_id] ?? [],
                    ];
                }),
            ],
        ]);
    } catch (\Exception $e) {
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.sales-note.detail');

// Sales Note - Report data (for Online Report modal)
Route::post('/admin/sales/sales-note/report', function (Request $request) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

    $ids = $request->input('ids', []);
    $type = $request->input('type', 'note');
    if (empty($ids)) return response()->json(['success' => false, 'message' => 'No IDs provided.'], 422);

    $isNoteUnserved = $type === 'note-unserved';

    // Collect all product IDs for ledger queries (resolve product_code when product_id=0)
    $allProductIds = [];
    $codesToResolve = [];
    $notesTemp = \App\Models\SalesNote::on('sales')->with('items')
        ->whereIn('id', $ids)
        ->where('sales_number', 'NOT LIKE', 'PURRTN%')
        ->get();
    foreach ($notesTemp as $n) {
        foreach ($n->items as $itm) {
            if ($itm->product_id) {
                $allProductIds[(int)$itm->product_id] = true;
            } elseif ($itm->product_code) {
                $codesToResolve[strtoupper(trim($itm->product_code))] = true;
            }
        }
    }
    // Resolve product codes to IDs for items where product_id=0
    $codeToIdMap = [];
    if (!empty($codesToResolve)) {
        $resolved = \App\Models\Product::on('masterlist')
            ->whereIn('product_code', array_keys($codesToResolve))
            ->pluck('id', 'product_code');
        foreach ($resolved as $code => $id) {
            $codeToIdMap[strtoupper(trim($code))] = (int)$id;
            $allProductIds[(int)$id] = true;
        }
    }
    $allProductIds = array_keys($allProductIds);

    // Get latest balance_stock from product_ledgers per product
    $onHandMap = [];
    if (!empty($allProductIds)) {
        $latestIds = DB::connection('ledger')
            ->table('product_ledgers')
            ->whereIn('product_id', $allProductIds)
            ->selectRaw('MAX(id) as id')
            ->groupBy('product_id')
            ->pluck('id');

        if ($latestIds->isNotEmpty()) {
            $onHandMap = DB::connection('ledger')
                ->table('product_ledgers')
                ->whereIn('id', $latestIds)
                ->pluck('balance_stock', 'product_id')
                ->toArray();
        }
    }

    $notes = \App\Models\SalesNote::on('sales')->with('items')
        ->whereIn('id', $ids)
        ->where('sales_number', 'NOT LIKE', 'PURRTN%')
        ->orderBy('created_at', 'desc')
        ->get()
        ->map(function ($note) use ($onHandMap, $codeToIdMap) {
            $customer = \App\Models\Customer::on('masterlist')->find($note->customer_id);
            return [
                'id' => $note->id,
                'sales_number' => $note->sales_number,
                'customer_id' => $note->customer_id,
                'customer_name' => $note->customer_name,
                'order_date' => $note->order_date,
                'salesman' => $note->salesman,
                'prepared_by' => $note->prepared_by,
                'packed_by' => $note->packed_by,
                'checked_by' => $note->checked_by,
                'net_total' => $note->net_total,
                'status' => $note->status,
                'remarks' => $note->remarks,
                'items' => $note->items
                    ->map(function ($item) use ($onHandMap, $codeToIdMap) {
                        $resolvedProductId = (int)$item->product_id;
                        if (!$resolvedProductId && $item->product_code && isset($codeToIdMap[strtoupper(trim($item->product_code))])) {
                            $resolvedProductId = $codeToIdMap[strtoupper(trim($item->product_code))];
                        }
                        $product = $resolvedProductId ? \App\Models\Product::on('masterlist')->find($resolvedProductId) : null;
                        return [
                            'product_id' => $item->product_id,
                            'product_code' => (string) ($item->product_code ?? ''),
                            'description' => $item->description,
                            'part_number' => $product ? $product->part_number : '',
                            'quantity' => $item->quantity,
                            'additional_qty' => $item->additional_qty,
                            'oum' => trim((string) ($product->unit ?? '')),
                            'unit_price' => $item->unit_price,
                            'discount' => $item->discount,
                            'subtotal' => $item->subtotal,
'on_hand' => $onHandMap[$resolvedProductId] ?? 0,
                            'cost' => $product ? $product->cost : 0,
                            'selling_price' => $product ? $product->selling_price : 0,
                            'price_online' => $product ? $product->price_online : 0,
                        ];
                    })
                    ->values(),
            ];
        });

    if ($isNoteUnserved) {
        $notes = $notes->map(function ($note) {
            $so = \App\Models\SalesOrder::on('sales')
                ->with('items')
                ->where('order_number', $note['sales_number'])
                ->first();

            if (!$so) {
                $note['items'] = collect([
                    [
                        'product_id' => null,
                        'product_code' => '',
                        'description' => 'NONE',
                        'part_number' => '',
                        'quantity' => 0,
                        'additional_qty' => 0,
                        'print_qty_label' => 'NONE',
                        'print_qty' => 0,
                        'oum' => '',
                        'unit_price' => 0,
                        'discount' => 0,
                        'subtotal' => 0,
                        'on_hand' => 0,
                        'cost' => 0,
                        'selling_price' => 0,
                        'price_online' => 0,
                    ],
                ]);
                return $note;
            }

            $diffByProduct = $so->items
                ->groupBy('product_id')
                ->map(function ($rows) {
                    $qty = (int) $rows->sum(fn ($r) => (int) $r->quantity + (int) ($r->additional_qty ?? 0));
                    $actual = (int) $rows->sum(fn ($r) => (int) ($r->actual_qty ?? 0));
                    return max(0, $qty - $actual);
                })
                ->toArray();

            $note['items'] = collect($note['items'])
                ->map(function ($item) use ($diffByProduct) {
                    if (array_key_exists($item['product_id'], $diffByProduct)) {
                        $orderedDiff = (int) $diffByProduct[$item['product_id']];
                    } else {
                        $orderedDiff = (int) $item['quantity'] + (int) ($item['additional_qty'] ?? 0);
                    }
                    $item['print_qty'] = $orderedDiff;
                    return $item;
                })
                ->filter(fn ($item) => (int) ($item['print_qty'] ?? 0) > 0)
                ->values();

            if ($note['items']->count() === 0) {
                $note['items'] = collect([
                    [
                        'product_id' => null,
                        'product_code' => '',
                        'description' => 'NONE',
                        'part_number' => '',
                        'quantity' => 0,
                        'additional_qty' => 0,
                        'print_qty_label' => 'NONE',
                        'print_qty' => 0,
                        'oum' => '',
                        'unit_price' => 0,
                        'discount' => 0,
                        'subtotal' => 0,
                        'on_hand' => 0,
                        'cost' => 0,
                        'selling_price' => 0,
                        'price_online' => 0,
                    ],
                ]);
            }

            return $note;
        });
    }

    return response()->json(['success' => true, 'notes' => $notes]);
})->name('admin.sales-note.report');

// Sales Note - Get Invoices (for edit modal Step 2)
Route::get('/admin/sales/sales-note/{noteId}/invoices', function ($noteId) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);
    try {
        $note = \App\Models\SalesNote::on('sales')->findOrFail($noteId);
        
        // Get all sales_orders where order_number matches sales_number
        $invoices = \Illuminate\Support\Facades\DB::connection('sales')
            ->table('sales_orders')
            ->where('order_number', $note->sales_number)
            ->orderBy('created_at', 'desc')
            ->get()
            ->map(function ($so) {
                // Count items for this invoice
                $itemCount = \Illuminate\Support\Facades\DB::connection('sales')
                    ->table('sales_order_items')
                    ->where('sales_order_id', $so->id)
                    ->count();
                
                return [
                    'id' => $so->id,
                    'invoice_numbers' => $so->invoice_numbers,
                    'created_at' => date('M d, Y', strtotime($so->created_at)),
                    'total_amount' => (float) $so->total_amount,
                    'item_count' => $itemCount,
                    'status' => $so->status ?? 'Confirmed',
                    'waybill_no' => $so->waybill_no,
                    'waybill_date' => $so->waybill_date,
                ];
            });
        
        // Get remaining items from the original Sales Note quantity minus the
        // served quantity across every invoice. Never use Sales Order quantity
        // as the source of truth for the original order quantity.
        $noteSalesOrders = \App\Models\SalesOrder::on('sales')
            ->where('sales_note_id', $noteId)
            ->pluck('id');
        $servedByProduct = collect();
        if ($noteSalesOrders->isNotEmpty()) {
            $servedByProduct = \App\Models\SalesOrderItem::on('sales')
                ->whereIn('sales_order_id', $noteSalesOrders)
                ->selectRaw('product_id, SUM(COALESCE(actual_qty, 0)) as served_qty')
                ->groupBy('product_id')
                ->pluck('served_qty', 'product_id');
        }
        $noteItems = \App\Models\SalesNoteItem::on('sales')
            ->where('sales_note_id', $noteId)
            ->get();
        $priceCodeMap = [];
        $noteProductIds = $noteItems->pluck('product_id')->filter()->unique()->values()->all();
        if (!empty($noteProductIds)) {
            $priceCodeRows = DB::connection('masterlist')
                ->table('product_price_codes')
                ->whereIn('product_id', $noteProductIds)
                ->orderBy('product_id')
                ->orderBy('sort_order')
                ->orderBy('id')
                ->get(['product_id', 'price_code', 'selling_price', 'sort_order']);

            foreach ($priceCodeRows as $row) {
                $pid = (int) $row->product_id;
                $priceCodeMap[$pid][] = [
                    'price_code' => $row->price_code,
                    'selling_price' => (float) ($row->selling_price ?? 0),
                    'sort_order' => (int) ($row->sort_order ?? 0),
                ];
            }
        }

        $mapNoteItem = function ($item) use ($servedByProduct, $priceCodeMap) {
            $product = \App\Models\Product::on('masterlist')->find($item->product_id);
            $orderedQty = (float) ($item->quantity ?? 0);
            $actualQty = (float) ($servedByProduct->get($item->product_id) ?? 0);
            $remainingQty = max(0, $orderedQty - $actualQty);

            return [
                'id' => $item->id,
                'product_id' => $item->product_id,
                'price_code' => $item->price_code,
                'product_code' => $item->product_code ?? ($product ? $product->product_code : ''),
                'description' => $item->description,
                'quantity' => $orderedQty,
                'ordered_qty' => $orderedQty,
                'actual_qty' => $actualQty,
                'remaining_qty' => $remainingQty,
                'additional_qty' => $item->additional_qty ?? 0,
                'oum' => $item->oum,
                'unit_price' => (float) $item->unit_price,
                'discount' => (float) $item->discount,
                'subtotal' => round(
                    $orderedQty * (float) $item->unit_price * (1 - ((float) $item->discount / 100)),
                    2
                ),
                'particulars' => $item->particulars ?? '',
                'on_hand' => $product ? (float) $product->on_hand : 0,
                'selling_price' => $product ? (float) $product->selling_price : 0,
                'price_codes' => $priceCodeMap[(int) $item->product_id] ?? [],
            ];
        };

        $allNoteItems = $noteItems
            ->map($mapNoteItem)
            ->filter()
            ->values();

        $remainingItems = $allNoteItems
            ->filter(fn ($item) => (float) ($item['remaining_qty'] ?? 0) > 0)
            ->values();

        $invoicedItems = $allNoteItems
            ->filter(fn ($item) => (float) ($item['actual_qty'] ?? 0) > 0)
            ->values();

        return response()->json([
            'success' => true,
            'note' => [
                'id' => $note->id,
                'sales_number' => $note->sales_number,
                'customer_name' => $note->customer_name,
                'status' => $note->status,
            ],
            'invoices' => $invoices,
            'remaining_items' => $remainingItems,
            'remaining_items_count' => $remainingItems->count(),
            'invoiced_items' => $invoicedItems,
            'invoiced_items_count' => $invoicedItems->count(),
        ]);
    } catch (\Exception $e) {
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.sales-note.invoices');

// Sales Note - Get Items for Specific Invoice (for edit Step 3)
Route::get('/admin/sales/sales-note/invoice/{invoiceId}/items', function ($invoiceId) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);
    try {
        $salesOrder = \App\Models\SalesOrder::on('sales')->with('items')->findOrFail($invoiceId);
        $noteItemsByProduct = \App\Models\SalesNoteItem::on('sales')
            ->where('sales_note_id', $salesOrder->sales_note_id)
            ->get()
            ->keyBy('product_id');
        $salesOrderIds = \App\Models\SalesOrder::on('sales')
            ->where('sales_note_id', $salesOrder->sales_note_id)
            ->pluck('id');
        $servedByProduct = \App\Models\SalesOrderItem::on('sales')
            ->whereIn('sales_order_id', $salesOrderIds)
            ->selectRaw('product_id, SUM(COALESCE(actual_qty, 0)) as served_qty')
            ->groupBy('product_id')
            ->pluck('served_qty', 'product_id');
        $priceCodeMap = [];
        $orderProductIds = $salesOrder->items->pluck('product_id')->filter()->unique()->values()->all();
        if (!empty($orderProductIds)) {
            $priceCodeRows = DB::connection('masterlist')
                ->table('product_price_codes')
                ->whereIn('product_id', $orderProductIds)
                ->orderBy('product_id')
                ->orderBy('sort_order')
                ->orderBy('id')
                ->get(['product_id', 'price_code', 'selling_price', 'sort_order']);

            foreach ($priceCodeRows as $row) {
                $pid = (int) $row->product_id;
                $priceCodeMap[$pid][] = [
                    'price_code' => $row->price_code,
                    'selling_price' => (float) ($row->selling_price ?? 0),
                    'sort_order' => (int) ($row->sort_order ?? 0),
                ];
            }
        }
        
        $items = $salesOrder->items->map(function ($item) use ($salesOrder, $noteItemsByProduct, $servedByProduct, $priceCodeMap) {
            $product = \App\Models\Product::on('masterlist')->find($item->product_id);
            $salesNoteItem = $noteItemsByProduct->get($item->product_id);
            $orderedQty = (float) ($salesNoteItem?->quantity ?? $item->quantity ?? 0);
            $actualQty = (float) ($item->actual_qty ?? 0);
            $servedQty = (float) ($servedByProduct->get($item->product_id) ?? $actualQty);
            $remainingQty = max(0, $orderedQty - $servedQty);
            return [
                'id' => $item->id,
                'sales_order_item_id' => $item->id,
                'sales_note_item_id' => $salesNoteItem?->id,
                'product_id' => $item->product_id,
                'price_code' => $salesNoteItem?->price_code,
                'product_code' => $item->product_code,
                'description' => $item->description,
                'part_number' => $product ? $product->part_number : '',
                'quantity' => $orderedQty,
                'ordered_qty' => $orderedQty,
                'actual_qty' => $actualQty,
                'served_qty' => $servedQty,
                'remaining_qty' => $remainingQty,
                'additional_qty' => $item->additional_qty ?? 0,
                'oum' => $item->oum,
                'unit_price' => (float) $item->unit_price,
                'discount' => (float) $item->discount,
                'additional_discount' => (float) ($item->additional_discount ?? 0),
                'subtotal' => (float) ($salesNoteItem?->subtotal
                    ?? ($orderedQty * (float) $item->unit_price * (1 - ((float) $item->discount / 100)))),
                'particulars' => $item->particulars ?? '',
                'on_hand' => $product ? (float) $product->on_hand : 0,
                'cost' => $product ? (float) $product->cost : 0,
                'selling_price' => $product ? (float) $product->selling_price : 0,
                'price_codes' => $priceCodeMap[(int) $item->product_id] ?? [],
            ];
        })->values();
        
        return response()->json([
            'success' => true,
            'invoice' => [
                'id' => $salesOrder->id,
                'invoice_numbers' => $salesOrder->invoice_numbers,
                'sales_note_id' => $salesOrder->sales_note_id,
                'order_number' => $salesOrder->order_number,
                'total_amount' => (float) $salesOrder->total_amount,
            ],
            'items' => $items
        ]);
    } catch (\Exception $e) {
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.sales-note.invoice.items');

// Sales Note - Check Partial Sales Notes for Customer
Route::get('/admin/sales/sales-note/customer/{customerId}/partials', function ($customerId) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

    try {
        $partialNotes = \App\Models\SalesNote::on('sales')
            ->where('customer_id', $customerId)
            ->where('status', 'Partial')
            ->orderBy('created_at', 'desc')
            ->get(['id', 'sales_number', 'customer_name', 'order_date', 'net_total', 'remarks']);

        $result = $partialNotes->map(function ($note) {
            $salesOrderIds = \App\Models\SalesOrder::on('sales')
                ->where('sales_note_id', $note->id)
                ->pluck('id');

            $noteItems = \App\Models\SalesNoteItem::on('sales')
                ->where('sales_note_id', $note->id)
                ->get()
                ->keyBy('product_id');

            $invoicedProductIds = [];
            $itemsCount = 0;
            $remainingAmount = 0;

            if ($salesOrderIds->isNotEmpty()) {
                $orderItems = \App\Models\SalesOrderItem::on('sales')
                    ->whereIn('sales_order_id', $salesOrderIds)
                    ->get();

                foreach ($orderItems as $item) {
                    $invoicedProductIds[] = $item->product_id;
                    $remainingQty = (float) $item->quantity - (float) $item->actual_qty;
                    if ($remainingQty <= 0) continue;

                    $itemsCount++;
                    $remainingAmount += $remainingQty * (float) $item->unit_price * (1 - ((float) $item->discount / 100));
                }
            }

            foreach ($noteItems as $noteItem) {
                if (in_array($noteItem->product_id, $invoicedProductIds)) continue;
                if ((float) $noteItem->quantity <= 0) continue;

                $itemsCount++;
                $remainingAmount += (float) $noteItem->quantity * (float) $noteItem->unit_price * (1 - ((float) $noteItem->discount / 100));
            }

            if ($itemsCount <= 0) return null;

            return [
                'id' => $note->id,
                'sales_number' => $note->sales_number,
                'customer_name' => $note->customer_name,
                'order_date' => $note->order_date,
                'total_items' => $itemsCount,
                'remaining_amount' => round($remainingAmount, 2),
            ];
        })->filter()->values();

        return response()->json(['success' => true, 'partial_notes' => $result]);
    } catch (\Exception $e) {
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.sales-note.customer.partials');

// Sales Note - Get Remaining Items from Partial Note
Route::get('/admin/sales/sales-note/{noteId}/remaining-items', function ($noteId) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

    try {
        $note = \App\Models\SalesNote::on('sales')->find($noteId);
        if (!$note) {
            return response()->json(['success' => false, 'message' => 'Sales note not found'], 404);
        }

        // Get all sales orders for this note
        $salesOrders = \App\Models\SalesOrder::on('sales')
            ->where('sales_note_id', $noteId)
            ->pluck('id');

        $remainingItems = [];
        $invoicedProductIds = [];

        // Build a map of note item quantity by product_id
        $noteItems = \App\Models\SalesNoteItem::on('sales')
            ->where('sales_note_id', $noteId)
            ->get()
            ->keyBy('product_id');

        // Check for partially-invoiced items in SalesOrderItems
        if ($salesOrders->isNotEmpty()) {
            $orderItems = \App\Models\SalesOrderItem::on('sales')
                ->whereIn('sales_order_id', $salesOrders)
                ->get();

            foreach ($orderItems as $item) {
                $invoicedProductIds[] = $item->product_id;
                $remainingQty = $item->quantity - $item->actual_qty;

                if ($remainingQty > 0) {
                    $remainingAmount = $remainingQty * $item->unit_price * (1 - $item->discount / 100);
                    $noteItem = $noteItems->get($item->product_id);

                    $remainingItems[] = [
                        'from' => 'sales_order',
                        'sales_order_id' => $item->sales_order_id,
                        'sales_order_item_id' => $item->id,
                        'product_id' => $item->product_id,
                        'product_code' => (string) ($item->product_code ?? ''),
                        'description' => $item->description,
                        'quantity' => $item->quantity,
                        'actual_qty' => $item->actual_qty,
                        'remaining_qty' => $remainingQty,
                        'unit_price' => $item->unit_price,
                        'discount' => $item->discount,
                        'remaining_amount' => round($remainingAmount, 2),
                        'oum' => $item->oum,
                        'note_qty' => $noteItem ? (int) $noteItem->quantity : 0,
                    ];
                }
            }
        }

        // Also check for note items that were NEVER invoiced (not in any SalesOrder)
        foreach ($noteItems as $noteItem) {
            if (!in_array($noteItem->product_id, $invoicedProductIds)) {
                if ((float) $noteItem->quantity <= 0) continue;

                $remainingAmount = $noteItem->quantity * $noteItem->unit_price * (1 - $noteItem->discount / 100);

                $remainingItems[] = [
                    'from' => 'sales_note',
                    'sales_order_id' => null,
                    'sales_order_item_id' => null,
                    'product_id' => $noteItem->product_id,
                    'product_code' => $noteItem->product_code ?? '',
                    'description' => $noteItem->description ?? '',
                    'quantity' => $noteItem->quantity,
                    'actual_qty' => 0,
                    'remaining_qty' => $noteItem->quantity,
                    'unit_price' => $noteItem->unit_price,
                    'discount' => $noteItem->discount,
                    'remaining_amount' => round($remainingAmount, 2),
                    'oum' => $noteItem->oum ?? '',
                    'note_qty' => (int) $noteItem->quantity,
                ];
            }
        }

        return response()->json([
            'success' => true,
            'note' => [
                'id' => $note->id,
                'sales_number' => $note->sales_number,
                'customer_name' => $note->customer_name,
            ],
            'remaining_items' => $remainingItems,
        ]);
    } catch (\Exception $e) {
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.sales-note.remaining-items');

// Sales Note - Online Price Editor Page
Route::get('/admin/sales/sales-note/report/online-prices', function (Request $request) {
    $user = session('user');
    if (!$user) return redirect('/login');

    $ids = explode(',', $request->query('ids', ''));
    if (empty($ids)) return redirect()->back()->with('error', 'No sales notes selected.');

    $notes = \App\Models\SalesNote::on('sales')->with('items')
        ->whereIn('id', $ids)
        ->orderBy('created_at', 'desc')
        ->get();

    // Collect all unique products from all items
    $items = [];
    foreach ($notes as $note) {
        foreach ($note->items as $item) {
            $product = \App\Models\Product::on('masterlist')->find($item->product_id);
            $descParts = array_filter([$item->description, $product ? $product->application : '', $product ? $product->Position : '']);
            $items[] = [
                'item_id' => $item->id,
                'product_id' => $item->product_id,
                'product_code' => $item->product_code,
                'description' => implode(' | ', $descParts),
                'quantity' => $item->quantity,
                'oum' => $item->oum,
                'sales_number' => $note->sales_number,
                'price_online' => $product ? $product->price_online : 0,
            ];
        }
    }

    return view('Admin.sales.online-price-editor', [
        'items' => $items,
        'noteIds' => implode(',', $ids),
        'reportType' => $request->query('type', 'note'),
        'rangeType' => $request->query('range_type', 'annual'),
        'fromDate' => $request->query('from_date', date('Y')),
        'toDate' => $request->query('to_date', date('Y') + 1),
        'outDate1' => $request->query('outDate1', ''),
        'outDate2' => $request->query('outDate2', ''),
        'outDate3' => $request->query('outDate3', ''),
    ]);
})->name('admin.sales-note.online-prices');

// Sales Note - Save Online Prices
Route::post('/admin/sales/sales-note/report/online-prices/save', function (Request $request) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

    try {
        $prices = $request->input('prices', []);
        $updatedIds = [];
        
        foreach ($prices as $productId => $price) {
            $affected = \Illuminate\Support\Facades\DB::connection('masterlist')
                ->table('products')
                ->where('id', $productId)
                ->update(['price_online' => $price]);
            
            if ($affected) {
                $updatedIds[] = $productId;
            }
        }
        
        \Illuminate\Support\Facades\Log::info('Online prices save request:', [
            'input_count' => count($prices),
            'updated_count' => count($updatedIds),
            'updated_ids' => $updatedIds
        ]);

        return response()->json([
            'success' => true, 
            'updated_count' => count($updatedIds),
            'message' => 'Successfully updated ' . count($updatedIds) . ' products.'
        ]);
    } catch (\Exception $e) {
        \Illuminate\Support\Facades\Log::error('Error saving online prices: ' . $e->getMessage());
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.sales-note.online-prices.save');

// Sales Note - Report Redirect (back from online price editor)
Route::get('/admin/sales/sales-note/report/redirect', function (Request $request) {
    $user = session('user');
    if (!$user) return redirect('/login');

    $ids = $request->query('ids', '');
    $type = $request->query('type', 'note');
    $outDate1 = $request->query('outDate1', date('Y'));
    $outDate2 = $request->query('outDate2', date('Y') + 1);
    $outDate3 = $request->query('outDate3', '');
    $onlinePrices = $request->query('online_prices', '0');

    return view('Admin.sales.sales-note', [
        'report_ids' => $ids,
        'report_type' => $type,
        'report_out_date1' => $outDate1,
        'report_out_date2' => $outDate2,
        'report_out_date3' => $outDate3,
        'online_prices_confirmed' => $onlinePrices === '1',
    ]);
})->name('admin.sales-note.report-redirect');

// Sales Note - Print Report View
Route::get('/admin/sales/sales-note/report/print', function (Request $request) {
    $user = session('user');
    if (!$user) return redirect('/login');

    $ids = explode(',', $request->query('ids', ''));
    $type = $request->query('type', 'note');
    
    // Get 3 selectable date ranges for OUT columns
    $outDate1 = $request->query('outDate1', '2025');
    $outDate2 = $request->query('outDate2', '2026');
    $outDate3 = $request->query('outDate3', '');
    $paymentType = $request->query('payment_type', 'none');
    
    $yearRange = [];
    if ($outDate1) $yearRange[] = $outDate1;
    if ($outDate2) $yearRange[] = $outDate2;
    if ($outDate3) $yearRange[] = $outDate3;

    if (empty($ids)) return redirect()->back()->with('error', 'No sales notes selected.');

    $isNoteUnserved = $type === 'note-unserved';

    // Collect all product IDs for ledger queries (resolve product_code when product_id=0)
    $allProductIds = [];
    $codesToResolve = [];
    $notesTemp = \App\Models\SalesNote::on('sales')->with('items')
        ->whereIn('id', $ids)
        ->where('sales_number', 'NOT LIKE', 'PURRTN%')
        ->get();
    foreach ($notesTemp as $n) {
        foreach ($n->items as $itm) {
            if ($itm->product_id) {
                $allProductIds[(int)$itm->product_id] = true;
            } elseif ($itm->product_code) {
                $codesToResolve[strtoupper(trim($itm->product_code))] = true;
            }
        }
    }
    // Resolve product codes to IDs for items where product_id=0
    $codeToIdMap = [];
    if (!empty($codesToResolve)) {
        $resolved = \App\Models\Product::on('masterlist')
            ->whereIn('product_code', array_keys($codesToResolve))
            ->pluck('id', 'product_code');
        foreach ($resolved as $code => $id) {
            $codeToIdMap[strtoupper(trim($code))] = (int)$id;
            $allProductIds[(int)$id] = true;
        }
    }
    $allProductIds = array_keys($allProductIds);

    // Get latest purchased unit price from supplier_ledger_items per product (Latest Cost)
    $latestCostByProductId = [];
    if (!empty($allProductIds)) {
        $costRows = DB::connection('ledger')
            ->table('supplier_ledger_items as sli')
            ->join('supplier_ledgers as sl', 'sl.id', '=', 'sli.supplier_ledger_id')
            ->whereIn('sli.product_id', $allProductIds)
            ->where('sl.module_type', 'Purchase Order')
            ->whereNotNull('sli.unit_price')
            ->orderByDesc('sl.date')
            ->orderByDesc('sl.created_at')
            ->orderByDesc('sl.id')
            ->orderByDesc('sli.id')
            ->select('sli.product_id', 'sli.unit_price')
            ->get()
            ->unique('product_id');
        foreach ($costRows as $row) {
            $latestCostByProductId[(int)$row->product_id] = (float)$row->unit_price;
        }
    }

    // Get latest balance_stock from product_ledgers per product
    $onHandMap = [];
    if (!empty($allProductIds)) {
        $latestRows = DB::connection('ledger')
            ->table('product_ledgers')
            ->whereIn('product_id', $allProductIds)
            ->orderBy('date', 'desc')
            ->orderBy('id', 'desc')
            ->select('product_id', 'balance_stock')
            ->get()
            ->unique('product_id');

        if ($latestRows->isNotEmpty()) {
            $onHandMap = $latestRows->pluck('balance_stock', 'product_id')->toArray();
        }
    }

    // Fetch actual yearly OUT sales from product_ledgers for all products in yearRange
    $yearlyOutMap = [];
    if (!empty($yearRange) && !empty($allProductIds)) {
        foreach ($yearRange as $yr) {
            $ledgerRows = DB::connection('ledger')
                ->table('product_ledgers')
                ->whereIn('product_id', $allProductIds)
                ->whereYear('date', (int)$yr)
                ->selectRaw("product_id,
                    SUM(CASE
                        WHEN transaction_type IN ('ADJUST','ADJUSTENTRY') THEN 0
                        WHEN LOWER(COALESCE(reference_number,'')) LIKE '%adj%' OR LOWER(COALESCE(remarks,'')) LIKE '%adjust%' THEN 0
                        WHEN transaction_type = 'OUT' AND (LOWER(COALESCE(remarks,'')) LIKE '%purrtn%' OR LOWER(COALESCE(remarks,'')) LIKE '%purchase return%') THEN -quantity_out
                        WHEN transaction_type = 'OUT' AND (LOWER(COALESCE(reference_number,'')) LIKE '%ret%' OR LOWER(COALESCE(reference_number,'')) LIKE '%return%') THEN -quantity_out
                        WHEN transaction_type = 'IN' AND (LOWER(COALESCE(remarks,'')) LIKE '%salrtn%' OR LOWER(COALESCE(remarks,'')) LIKE '%sales return%') THEN -quantity_in
                        WHEN transaction_type IN ('OUT','CHGINVC') THEN quantity_out
                        ELSE 0
                    END) as total_out")
                ->groupBy('product_id')
                ->pluck('total_out', 'product_id');
            foreach ($ledgerRows as $pid => $total) {
                $yearlyOutMap[$pid][$yr] = (int)$total;
            }
        }
    }

    $notes = \App\Models\SalesNote::on('sales')->with('items')
        ->whereIn('id', $ids)
        ->where('sales_number', 'NOT LIKE', 'PURRTN%')
        ->orderBy('created_at', 'desc')
        ->get()
        ->map(function ($note) use ($isNoteUnserved, $yearlyOutMap, $yearRange, $onHandMap, $codeToIdMap, $latestCostByProductId) {
            $customer = \App\Models\Customer::on('masterlist')->find($note->customer_id);
            $diffByProduct = [];

            if ($isNoteUnserved) {
                $so = \App\Models\SalesOrder::on('sales')
                    ->with('items')
                    ->where('order_number', $note->sales_number)
                    ->first();

                if ($so) {
                    $diffByProduct = $so->items
                        ->groupBy('product_id')
                        ->map(function ($rows) {
                            $qty = (int) $rows->sum(fn ($r) => (int) $r->quantity + (int) ($r->additional_qty ?? 0));
                            $actual = (int) $rows->sum(fn ($r) => (int) ($r->actual_qty ?? 0));
                            return max(0, $qty - $actual);
                        })
                        ->toArray();
                }
            }

            $items = $note->items
                ->map(function ($item) use ($diffByProduct, $isNoteUnserved, $yearlyOutMap, $yearRange, $onHandMap, $codeToIdMap, $latestCostByProductId) {
                    // Resolve product_id: use direct product_id if available, fallback to product_code lookup
                    $resolvedProductId = (int)$item->product_id;
                    if (!$resolvedProductId && $item->product_code && isset($codeToIdMap[strtoupper(trim($item->product_code))])) {
                        $resolvedProductId = $codeToIdMap[strtoupper(trim($item->product_code))];
                    }
                    $product = $resolvedProductId ? \App\Models\Product::on('masterlist')->find($resolvedProductId) : null;
                    $descParts = array_filter([$item->description, $product ? $product->application : '', $product ? $product->Position : '']);
                    $latestCost = $latestCostByProductId[$resolvedProductId] ?? 0;

                    if ($isNoteUnserved) {
                        if (array_key_exists($resolvedProductId, $diffByProduct)) {
                            $printQty = (int) $diffByProduct[$resolvedProductId];
                        } else {
                            $printQty = (int) $item->quantity + (int) ($item->additional_qty ?? 0);
                        }
                    } else {
                        $printQty = (int) $item->quantity + (int) ($item->additional_qty ?? 0);
                    }

                    // Build display_qty: show "10 (+2)" when additional_qty > 0, else just "10"
                    $mainQty = (int) $item->quantity;
                    $addQty  = (int) ($item->additional_qty ?? 0);
                    $displayQty = $addQty > 0 ? "{$mainQty} (+{$addQty})" : (string) $mainQty;

                    // Build per-year OUT sales from product_ledgers
                    $yearlySales = [];
                    foreach ($yearRange as $yr) {
                        $yearlySales[$yr] = (int) ($yearlyOutMap[$resolvedProductId][$yr] ?? 0);
                    }

                    return [
                        'product_id' => $resolvedProductId,
                        'product_code' => (string) ($item->product_code ?? ''),
                        'description' => implode(' | ', $descParts),
                        'part_number' => $product ? $product->part_number : '',
                        'quantity' => $item->quantity,
                        'additional_qty' => $item->additional_qty,
                        'display_qty' => $displayQty,
                        'print_qty' => $printQty,
                        'oum' => $item->oum,
                        'unit_price' => $item->unit_price,
                        'on_hand' => $onHandMap[(int)$item->product_id] ?? 0,
                        'cost' => $latestCost,
                        'price_online' => $product ? $product->price_online : 0,
                        'yearly_sales' => $yearlySales,
                    ];
                });

            if ($isNoteUnserved) {
                $items = $items->filter(fn ($item) => (int) ($item['print_qty'] ?? 0) > 0)->values();
                if ($items->count() === 0) {
                    $items = collect([
                        [
                            'product_id' => 0,
                            'product_code' => '',
                            'description' => 'NONE',
                            'part_number' => '',
                            'quantity' => 0,
                            'additional_qty' => 0,
                            'print_qty_label' => 'NONE',
                            'print_qty' => 0,
                            'oum' => '',
                            'unit_price' => 0,
                            'on_hand' => 0,
                            'cost' => 0,
                            'price_online' => 0,
                        ],
                    ]);
                }
            } else {
                $items = $items->values();
            }

            return [
                'sales_number' => $note->sales_number,
                'customer_name' => $note->customer_name,
                'customer_address' => $customer ? $customer->address : '',
                'order_date' => $note->order_date,
                'salesman' => $note->salesman,
                'prepared_by' => $note->prepared_by,
                'packed_by' => $note->packed_by,
                'checked_by' => $note->checked_by,
                'is_rush' => $note->is_rush ?? false,
                'net_total' => $note->net_total,
                'remarks' => $note->remarks,
                'items' => $items,
            ];
        });

    return view('Admin.sales.sales-note-print', [
        'notes' => $notes,
        'type' => $type,
        'yearRange' => $yearRange,
        'paymentType' => $paymentType,
        'latestCostByProductId' => $latestCostByProductId,
    ]);
})->name('admin.sales-note.print');

