// Sales Order - Counter Part Product Search
Route::get('/admin/sales/sales-order/counter-part/products', function (Request $request) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

    try {
        $page = max(1, (int) $request->query('page', 1));
        $perPage = max(1, min(100, (int) $request->query('per_page', $request->query('perPage', 25))));
        $search = $request->query('search', '');
        $fieldFilters = is_array($search) ? $search : [];
        $keyword = is_array($search) ? trim((string) $request->query('keyword', '')) : trim((string) $search);

        $fieldMap = [
            'code' => 'product_code',
            'product_code' => 'product_code',
            'item_code' => 'product_code',
            'part' => 'part_number',
            'part_number' => 'part_number',
            'description' => 'description',
            'application' => 'application',
            'position' => 'Position',
            'brand' => 'category',
            'category' => 'category',
        ];

        $escapeLike = static function (string $value): string {
            return '%' . str_replace(['\\', '%', '_'], ['\\\\', '\\%', '\\_'], $value) . '%';
        };

        $query = DB::connection('masterlist')->table('products');

        if ($keyword !== '') {
            $keywordLike = $escapeLike($keyword);
            $query->where(function ($q) use ($keywordLike) {
                $q->where('product_code', 'like', $keywordLike)
                    ->orWhere('part_number', 'like', $keywordLike)
                    ->orWhere('description', 'like', $keywordLike)
                    ->orWhere('application', 'like', $keywordLike)
                    ->orWhere('Position', 'like', $keywordLike)
                    ->orWhere('category', 'like', $keywordLike);
            });
        }

        foreach ($fieldFilters as $field => $value) {
            $value = trim((string) $value);
            if ($value === '' || !isset($fieldMap[$field])) {
                continue;
            }

            $fieldLike = $escapeLike($value);
            if ($field === 'application') {
                $query->where(function ($q) use ($fieldLike) {
                    $q->where('application', 'like', $fieldLike)
                        ->orWhere('Position', 'like', $fieldLike);
                });
                continue;
            }

            $query->where($fieldMap[$field], 'like', $fieldLike);
        }

        $products = $query
            ->orderBy('product_code')
            ->paginate($perPage, [
                'id',
                'product_code',
                'description',
                'part_number',
                'application',
                'category',
                DB::raw('`Position` as position'),
            ], 'page', $page);

        $rows = $products->getCollection()->map(function ($p) {
            return [
                'id' => (int) $p->id,
                'product_code' => $p->product_code,
                'description' => $p->description ?? '',
                'part_number' => $p->part_number ?? '',
                'application' => $p->application ?? '',
                'position' => $p->position ?? '',
                'category' => $p->category ?? '',
            ];
        })->values();

        return response()->json([
            'success' => true,
            'products' => $rows,
            'pagination' => [
                'current_page' => $products->currentPage(),
                'last_page' => $products->lastPage(),
                'per_page' => $products->perPage(),
                'total' => $products->total(),
                'from' => $products->firstItem(),
                'to' => $products->lastItem(),
            ],
        ]);
    } catch (\Throwable $e) {
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.sales-order.counter-part.products');

// Sales Order - Active list
Route::get('/admin/sales/sales-order/active', function (Request $request) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);
    try {
        $perPage = min((int) $request->query('perPage', 50), 100);
        $page = (int) $request->query('page', 1);
        $search = $request->query('search', '');

        $query = \App\Models\SalesNote::on('sales')
            ->with('items')
            ->where('so_type', 'Sales Order')
            ->whereIn('status', ['Open', 'Partial']);

        if ($search !== '') {
            $query->where(function ($q) use ($search) {
                $q->where('sales_number', 'like', "%{$search}%")
                  ->orWhere('customer_name', 'like', "%{$search}%")
                  ->orWhere('order_date', 'like', "%{$search}%")
                  ->orWhere('status', 'like', "%{$search}%");
            });
        }

        $notes = $query->orderBy('created_at', 'desc')
            ->paginate($perPage, ['*'], 'page', $page);

        $notes->getCollection()->transform(function ($note) {
            $hasPriceChange = false;
            $items = $note->items;
            if ($items->isNotEmpty()) {
                $productIds = $items->pluck('product_id')->filter()->unique()->values()->all();
                if (!empty($productIds)) {
                    $products = DB::connection('masterlist')->table('products')
                        ->whereIn('id', $productIds)
                        ->pluck('selling_price', 'id');
                    foreach ($items as $item) {
                        $dbPrice = (float) ($products->get($item->product_id) ?? 0);
                        $notePrice = (float) ($item->unit_price ?? 0);
                        if ($dbPrice > 0 && abs($dbPrice - $notePrice) > 0.001) {
                            $hasPriceChange = true;
                            break;
                        }
                    }
                }
            }
            return [
                'id' => $note->id,
                'sales_number' => $note->sales_number,
                'customer_name' => $note->customer_name,
                'net_total' => $note->net_total,
                'order_date' => $note->order_date,
                'salesman' => $note->salesman,
                'status' => $note->status,
                'has_price_change' => $hasPriceChange,
            ];
        });

        return response()->json([
            'success' => true,
            'data' => $notes->items(),
            'current_page' => $notes->currentPage(),
            'per_page' => $notes->perPage(),
            'last_page' => $notes->lastPage(),
            'total' => $notes->total(),
        ]);
    } catch (\Exception $e) {
        return response()->json(['success' => false, 'message' => 'Unable to load active notes.'], 500);
    }
})->name('admin.sales-order.active');

