Route::get('/admin/sales/sales-order/history-data', function (Request $request) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);
    try {
        $perPage = in_array((int)$request->query('perPage', 50), [25, 50, 100]) ? (int)$request->query('perPage', 50) : 50;
        $page = max(1, (int)$request->query('page', 1));
        $search = trim($request->query('search', ''));
        $query = \App\Models\SalesOrder::on('sales');
        if ($search !== '') {
            $query->where(function ($q) use ($search) {
                $q->where('order_number', 'like', "%{$search}%")
                  ->orWhere('customer_name', 'like', "%{$search}%")
                  ->orWhere('invoice_numbers', 'like', "%{$search}%")
                  ->orWhere('waybill_no', 'like', "%{$search}%");
            });
        }
        $total = $query->count();
        $orders = $query->orderBy('created_at', 'desc')
            ->skip(($page - 1) * $perPage)
            ->take($perPage)
            ->get()
            ->map(function ($so) {
                return [
                    'id' => $so->id,
                    'sales_number' => $so->order_number,
                    'customer_name' => $so->customer_name,
                    'order_date' => date('Y-m-d', strtotime($so->created_at)),
                    'date_issue' => date('Y-m-d', strtotime($so->created_at)),
                    'invoice_no' => $so->invoice_numbers ?? '',
                    'waybill_no' => $so->waybill_no ?? '',
                    'waybill_date' => $so->waybill_date ?? '',
                    'total_amount' => $so->total_amount,
                    'remarks' => $so->remarks ?? '',
                    'status' => $so->status ?? 'Confirmed',
                ];
            });
        return response()->json([
            'success' => true, 'orders' => $orders,
            'total' => $total, 'per_page' => $perPage,
            'current_page' => $page, 'last_page' => max(1, (int)ceil($total / $perPage)),
        ]);
    } catch (\Exception $e) {
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.sales-order.history-data');

// Sales Order - History Destroy
Route::delete('/admin/sales/sales-order/history-destroy/{id}', function ($id) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);
    try {
        $so = \App\Models\SalesOrder::on('sales')->with('items')->find($id);
        if (!$so) {
            return response()->json(['success' => false, 'message' => 'Sales order not found.'], 404);
        }

        $orderNumber = $so->order_number;
        $salesNoteId = $so->sales_note_id;
        $invoiceNumbers = $so->invoice_numbers;

        // Collect product IDs from SO items for stock recalculation
        $productIds = [];
        foreach ($so->items as $item) {
            $pid = (int) ($item->product_id ?? 0);
            if ($pid > 0) $productIds[$pid] = true;
        }

        // Find related ledger entries
        $ledgerQuery = \App\Models\ProductLedger::where('transaction_type', 'OUT')
            ->where('transaction_number', $orderNumber);

        if (!empty($invoiceNumbers)) {
            $ledgerQuery->where('reference_number', $invoiceNumbers);
        }

        $ledgerRows = $ledgerQuery->get();

        // Collect additional product IDs from ledger
        foreach ($ledgerRows as $lr) {
            $pid = (int) ($lr->product_id ?? 0);
            if ($pid > 0) $productIds[$pid] = true;
        }

        \Illuminate\Support\Facades\Log::info("Sales Order #{$id} delete: {$ledgerRows->count()} ledger rows found.");

        // Delete ledger rows
        if ($ledgerRows->isNotEmpty()) {
            \App\Models\ProductLedger::where('transaction_type', 'OUT')
                ->where('transaction_number', $orderNumber)
                ->when(!empty($invoiceNumbers), fn ($q) => $q->where('reference_number', $invoiceNumbers))
                ->delete();
        }

        // Delete SO items
        \Illuminate\Support\Facades\DB::connection('sales')
            ->table('sales_order_items')
            ->where('sales_order_id', $id)
            ->delete();

        // Delete the SO
        $so->delete();

        // Update source SalesNote status if it exists
        if ($salesNoteId) {
            $note = \App\Models\SalesNote::on('sales')->find($salesNoteId);
            if ($note) {
                $remainingSOs = \App\Models\SalesOrder::on('sales')
                    ->where('sales_note_id', $salesNoteId)
                    ->count();
                if ($remainingSOs === 0) {
                    $note->status = 'Open';
                    $note->save();
                }
            }
        }

        // Sync stock
        if (!empty($productIds)) {
            \App\Services\ProductStockSyncService::syncProducts(array_keys($productIds));
        }

        return response()->json(['success' => true, 'message' => 'Sales order deleted successfully.']);
    } catch (\Exception $e) {
        \Illuminate\Support\Facades\Log::error("Sales Order #{$id} delete error: " . $e->getMessage());
        return response()->json(['success' => false, 'message' => 'Unable to delete the Sales Order.'], 500);
    }
})->name('admin.sales-order.history-destroy');

// Sales Order - All list (for dashboard filter tab)
Route::get('/admin/sales/sales-order/all', function (Request $request) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);
    try {
        $statusFilter = $request->query('status', '');
        $query = \App\Models\SalesNote::on('sales')
            ->where('so_type', 'Sales Order');
        if ($statusFilter !== '' && $statusFilter !== 'All') {
            $statuses = array_map('trim', explode(',', $statusFilter));
            $query->whereIn('status', $statuses);
        } else {
            $query->whereIn('status', ['Open', 'Partial', 'Closed']);
        }
        $notes = $query->orderBy('created_at', 'desc')->get()->map(function ($note) {
            return [
                'id' => $note->id,
                'sales_number' => $note->sales_number,
                'customer_name' => $note->customer_name,
                'net_total' => $note->net_total,
                'order_date' => $note->order_date,
                'salesman' => $note->salesman,
                'status' => $note->status,
            ];
        });
        return response()->json(['success' => true, 'notes' => $notes]);
    } catch (\Exception $e) {
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.sales-order.all');

// Sales Order - All list (server-side paginated)
Route::get('/admin/sales/sales-order/all-orders-data', function (Request $request) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);
    try {
        $perPage = in_array((int)$request->query('perPage', 50), [25, 50, 100]) ? (int)$request->query('perPage', 50) : 50;
        $page = max(1, (int)$request->query('page', 1));
        $search = trim($request->query('search', ''));
        $statusFilter = $request->query('status', '');
        $query = \App\Models\SalesNote::on('sales')
            ->where('so_type', 'Sales Order');
        if ($statusFilter !== '' && $statusFilter !== 'All') {
            $statuses = array_map('trim', explode(',', $statusFilter));
            $query->whereIn('status', $statuses);
        } else {
            $query->whereIn('status', ['Open', 'Partial', 'Closed']);
        }
        if ($search !== '') {
            $query->where(function ($q) use ($search) {
                $q->where('sales_number', 'like', "%{$search}%")
                  ->orWhere('customer_name', 'like', "%{$search}%")
                  ->orWhere('salesman', 'like', "%{$search}%");
            });
        }

        // Build lookup: sales_note_id → online_report_id for source_type detection
        $noteToOnlineReport = [];
        $onlineReports = \App\Models\OnlineReport::on('sales')
            ->where('status', 'migrated')
            ->get(['id', 'sales_note_ids']);
        foreach ($onlineReports as $or) {
            $ids = explode(',', $or->sales_note_ids);
            foreach ($ids as $nid) {
                $nid = trim($nid);
                if ($nid !== '') {
                    $noteToOnlineReport[(int)$nid] = $or->id;
                }
            }
        }

        $total = $query->count();
        $notes = $query->orderBy('created_at', 'desc')
            ->skip(($page - 1) * $perPage)
            ->take($perPage)
            ->get()
            ->map(function ($note) use ($noteToOnlineReport) {
                $hasOnlineReport = isset($noteToOnlineReport[$note->id]);
                return [
                    'id' => $note->id,
                    'sales_number' => $note->sales_number,
                    'customer_name' => $note->customer_name,
                    'net_total' => $note->net_total,
                    'order_date' => $note->order_date,
                    'salesman' => $note->salesman,
                    'status' => $note->status,
                    'source_type' => $hasOnlineReport ? 'online_report' : 'sales_order',
                    'online_report_id' => $hasOnlineReport ? $noteToOnlineReport[$note->id] : null,
                ];
            });
        return response()->json([
            'success' => true, 'notes' => $notes,
            'total' => $total, 'per_page' => $perPage,
            'current_page' => $page, 'last_page' => max(1, (int)ceil($total / $perPage)),
        ]);
    } catch (\Exception $e) {
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.sales-order.all-orders-data');

// Sales Order - Detail view
Route::get('/admin/sales/sales-order/detail/{id}', function (Request $request, $id) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);
    try {
        // Check if this is a sales_order_id or sales_note_id based on for_proceed parameter
        $forProceed = $request->boolean('for_proceed');
        
        if ($forProceed) {
            // For proceed modal: load sales NOTE and show remaining items
            $note = \App\Models\SalesNote::on('sales')->with('items')->findOrFail($id);
            $customer = \App\Models\Customer::on('masterlist')->find($note->customer_id);

            // Get all existing invoices for this sales note
            $existingInvoices = \Illuminate\Support\Facades\DB::connection('sales')
                ->table('sales_orders')
                ->where('sales_note_id', $note->id)
                ->pluck('invoice_numbers') // Fixed: was invoice_number, should be invoice_numbers
                ->filter()
                ->values()
                ->all();

            // Calculate served quantities across ALL invoices for this sales note
            $servedRows = DB::connection('sales')
                ->table('sales_orders as so')
                ->join('sales_order_items as soi', 'soi.sales_order_id', '=', 'so.id')
                ->where('so.sales_note_id', $note->id)
                ->select([
                    'soi.product_id as product_id',
                    DB::raw('SUM(COALESCE(soi.actual_qty, 0)) as served_qty'),
                ])
                ->groupBy('soi.product_id')
                ->get();

            $servedMap = [];
            foreach ($servedRows as $row) {
                $servedMap[(int) $row->product_id] = (float) ($row->served_qty ?? 0);
            }

            $items = $note->items
                ->map(function ($item) use ($servedMap) {
                    $product = \App\Models\Product::on('masterlist')->find($item->product_id);
                    // Use ONLY the description from sales_note_items (already concatenated when saved)
                    $description = $item->description ?? '';

                    $orderedQty = (float) ($item->quantity ?? 0);
                    $servedQty = (float) ($servedMap[(int) $item->product_id] ?? 0);
                    $remainingQty = max(0, $orderedQty - $servedQty);

                    $dbPrice = $product ? (float) ($product->selling_price ?? 0) : 0;
                    $notePrice = (float) ($item->unit_price ?? 0);
                    $hasPriceChange = $dbPrice > 0 && abs($dbPrice - $notePrice) > 0.001;

                    return [
                        'product_id' => $item->product_id,
                        'product_code' => $item->product_code ?? ($product ? $product->product_code : ''),
                        'price_code' => $item->price_code ?? '',
                        'description' => $description,
                        'application' => $product ? ($product->application ?? '') : '',
                        'part_number' => $product ? $product->part_number : '',
                        'quantity' => $remainingQty, // Show only remaining for proceed
                        'actual_qty' => $remainingQty,
                        'served_qty' => $servedQty,
                        'remaining_qty' => $remainingQty,
                        'additional_qty' => $item->additional_qty,
                        'oum' => $item->oum,
                        'unit_price' => $item->unit_price,
                        'discount' => $item->discount,
                        'subtotal' => $item->subtotal,
                        'particulars' => $item->particulars ?? '',
                        'on_hand' => $product ? $product->on_hand : 0,
                        'cost' => $product ? $product->cost : 0,
                        'price_online' => $product ? $product->price_online : 0,
                        'has_price_change' => $hasPriceChange,
                    ];
                })
                ->filter(function ($item) {
                    return ((float) ($item['quantity'] ?? 0)) > 0; // Only show items with remaining qty
                })
                ->values();

            return response()->json([
                'success' => true,
                'order' => [
                    'id' => $note->id,
                    'sales_number' => $note->sales_number,
                    'so_type' => $note->so_type,
                    'order_date' => $note->order_date,
                    'customer_name' => $note->customer_name,
                    'customer_id' => $note->customer_id,
                    'salesman' => $note->salesman,
                    'prepared_by' => $note->prepared_by,
                    'checked_by' => $note->checked_by,
                    'packed_by' => $note->packed_by,
                    'is_rush' => $note->is_rush,
                    'gross_total' => $note->gross_total,
                    'net_total' => $note->net_total,
                    'status' => $note->status,
                    'existing_invoice_numbers' => $existingInvoices,
                    'items' => $items,
                ],
            ]);
        } else {
            // For view/print: load specific INVOICE (sales_order)
                $salesOrder = \App\Models\SalesOrder::on('sales')->with(['items', 'salesNote'])->findOrFail($id);
            $customer = \App\Models\Customer::on('masterlist')->find($salesOrder->customer_id);

            // Build invoice movement: original A/R debit, Sales Return credits, and Payment credits.
            // This intentionally uses existing tables only; no database revision is required.
           
            $rawInvoiceNumbers = trim((string) ($salesOrder->invoice_numbers ?? ''));
            $decodedInvoiceNumbers = json_decode($rawInvoiceNumbers, true);
            if (is_array($decodedInvoiceNumbers)) {
                $invoiceNumbers = collect($decodedInvoiceNumbers);
            } else {
                $invoiceNumbers = collect(preg_split('/\s*,\s*/', $rawInvoiceNumbers, -1, PREG_SPLIT_NO_EMPTY));
            }

            $invoiceNumbers = $invoiceNumbers
                ->map(fn ($value) => trim((string) $value))
                ->filter(fn ($value) => $value !== '')
                ->unique()
                ->values();

            if ($invoiceNumbers->isEmpty() && $rawInvoiceNumbers !== '') {
                $invoiceNumbers = collect([$rawInvoiceNumbers]);
            }

            $normalizeInvoiceNumber = static fn ($value) => strtoupper(preg_replace('/\s+/', '', trim((string) $value)));
            $normalizedInvoiceNumbers = $invoiceNumbers
                ->map($normalizeInvoiceNumber)
                ->filter(fn ($value) => $value !== '')
                ->unique()
                ->values();

            $invoiceNumber = (string) ($invoiceNumbers->first() ?? $rawInvoiceNumbers);
            $salesNote = $salesOrder->salesNote;
            $salesNoteNumber = trim((string) ($salesNote->sales_number ?? ''));
            $invoiceMovement = collect();


            $invoiceMovement->push([
                'transaction' => 'PENDING PAY',
                'transaction_no' => $salesNoteNumber !== '' ? $salesNoteNumber : ((string) ($salesOrder->order_number ?? $invoiceNumber)),
                'debit' => (float) ($salesOrder->total_amount ?? 0),
                'credit' => 0.0,
                'remarks' => '',
                'date' => $salesOrder->created_at ? \Carbon\Carbon::parse($salesOrder->created_at)->format('Y-m-d') : '',
                '_sort_at' => $salesOrder->created_at ? \Carbon\Carbon::parse($salesOrder->created_at)->format('Y-m-d H:i:s') : '0000-00-00 00:00:00',
                '_sort_id' => 0,
            ]);

            if ($normalizedInvoiceNumbers->isNotEmpty()) {
                $salesReturns = DB::connection('sales')
                    ->table('sales_returns')
                    ->whereRaw("UPPER(TRIM(COALESCE(status, ''))) NOT IN ('CANCELLED', 'VOID')")
                    ->where(function ($q) use ($normalizedInvoiceNumbers) {
                        foreach ($normalizedInvoiceNumbers as $index => $normalizedInvoiceNumber) {
                            if ($index === 0) {
                                $q->whereRaw("UPPER(REPLACE(TRIM(invoice_no), ' ', '')) = ?", [$normalizedInvoiceNumber]);
                            } else {
                                $q->orWhereRaw("UPPER(REPLACE(TRIM(invoice_no), ' ', '')) = ?", [$normalizedInvoiceNumber]);
                            }
                        }
                    })
                    ->orderBy('created_at')
                    ->orderBy('id')
                    ->get(['id', 'return_number', 'total_amount', 'remarks', 'created_at']);

                foreach ($salesReturns as $returnRow) {
                    $invoiceMovement->push([
                        'transaction' => 'SALES RETURN',
                        'transaction_no' => (string) ($returnRow->return_number ?? ''),
                        'debit' => 0.0,
                        'credit' => (float) ($returnRow->total_amount ?? 0),
                        'remarks' => (string) ($returnRow->remarks ?? ''),
                        'date' => $returnRow->created_at ? \Carbon\Carbon::parse($returnRow->created_at)->format('Y-m-d') : '',
                        '_sort_at' => $returnRow->created_at ? \Carbon\Carbon::parse($returnRow->created_at)->format('Y-m-d H:i:s') : '9999-12-31 23:59:59',
                        '_sort_id' => (int) ($returnRow->id ?? 0),
                    ]);
                }

                $paymentRows = DB::connection('accounting')
                    ->table('process_payment_invoices as ppi')
                    ->leftJoin('process_payments as pp', 'pp.id', '=', 'ppi.process_payment_id')
                    ->whereIn('ppi.source_type', ['sales_order', 'online_report'])
                    ->where('ppi.paid_amount', '>', 0)
                    ->where(function ($statusQuery) {
                        $statusQuery->whereNull('pp.id')
                            ->orWhereRaw("UPPER(TRIM(COALESCE(pp.status, ''))) NOT IN ('CANCELLED', 'VOID')");
                    })
                    ->where(function ($q) use ($salesOrder, $normalizedInvoiceNumbers) {
                        if ($normalizedInvoiceNumbers->isNotEmpty()) {
                            // Once this Sales Order has an invoice number, PAID rows must
                            // match that invoice number exactly. Do not match every
                            // Online Report attached to the same Sales Note.
                            $q->where(function ($invoiceMatch) use ($normalizedInvoiceNumbers) {
                                foreach ($normalizedInvoiceNumbers as $index => $normalizedInvoiceNumber) {
                                    $sql = "UPPER(REPLACE(TRIM(COALESCE(ppi.invoice_no, '')), ' ', '')) = ?";
                                    if ($index === 0) {
                                        $invoiceMatch->whereRaw($sql, [$normalizedInvoiceNumber]);
                                    } else {
                                        $invoiceMatch->orWhereRaw($sql, [$normalizedInvoiceNumber]);
                                    }
                                }
                            });
                        } else {
                            // Legacy fallback only for old local Sales Orders that truly
                            // have no invoice number stored.
                            $q->where('ppi.source_type', 'sales_order')
                                ->where('ppi.source_id', (int) $salesOrder->id);
                        }
                    })
                    ->orderByRaw('COALESCE(pp.payment_date, DATE(ppi.created_at))')
                    ->orderBy('ppi.created_at')
                    ->orderBy('ppi.id')
                    ->get([
                        'ppi.id',
                        'ppi.process_payment_id',
                        'ppi.paid_amount',
                        'ppi.remarks as invoice_remarks',
                        'ppi.created_at as invoice_payment_created_at',
                        'pp.payment_no',
                        'pp.payment_date',
                        'pp.remarks as payment_remarks',
                        'pp.created_at as payment_created_at',
                    ]);

                foreach ($paymentRows as $paymentRow) {
                    $invoiceRemarks = trim((string) ($paymentRow->invoice_remarks ?? ''));
                    $paymentRemarks = $invoiceRemarks !== ''
                        ? $invoiceRemarks
                        : trim((string) ($paymentRow->payment_remarks ?? ''));

                    $paymentCreatedAt = $paymentRow->payment_created_at
                        ?: $paymentRow->invoice_payment_created_at;

                    $paymentDate = $paymentRow->payment_date
                        ? \Carbon\Carbon::parse($paymentRow->payment_date)->format('Y-m-d')
                        : ($paymentCreatedAt
                            ? \Carbon\Carbon::parse($paymentCreatedAt)->format('Y-m-d')
                            : '');

                    if ($paymentRow->payment_date) {
                        $paymentSortDate = \Carbon\Carbon::parse($paymentRow->payment_date)->format('Y-m-d');
                        $paymentSortTime = $paymentCreatedAt
                            ? \Carbon\Carbon::parse($paymentCreatedAt)->format('H:i:s')
                            : '00:00:00';
                        $paymentSortAt = $paymentSortDate . ' ' . $paymentSortTime;
                    } else {
                        $paymentSortAt = $paymentCreatedAt
                            ? \Carbon\Carbon::parse($paymentCreatedAt)->format('Y-m-d H:i:s')
                            : '9999-12-31 23:59:59';
                    }

                    $paymentTransactionNo = trim((string) ($paymentRow->payment_no ?? ''));
                    if ($paymentTransactionNo === '') {
                        $paymentTransactionNo = 'PAYMENT #' . (int) ($paymentRow->process_payment_id ?? 0);
                    }

                    $invoiceMovement->push([
                        'transaction' => 'PAID',
                        'transaction_no' => $paymentTransactionNo,
                        'debit' => 0.0,
                        'credit' => (float) ($paymentRow->paid_amount ?? 0),
                        'remarks' => $paymentRemarks,
                        'date' => $paymentDate,
                        '_sort_at' => $paymentSortAt,
                        '_sort_id' => (int) ($paymentRow->id ?? 0),
                    ]);
                }
            }


            $invoiceMovement = $invoiceMovement
                ->sortBy(fn ($row) =>
                    ($row['_sort_at'] ?? '') . '|' .
                    str_pad((string) ($row['_sort_id'] ?? 0), 12, '0', STR_PAD_LEFT)
                )
                ->values()
                ->map(function ($row) {
                    unset($row['_sort_at'], $row['_sort_id']);
                    return $row;
                });

            $items = $salesOrder->items->map(function ($item) {
                $product = \App\Models\Product::on('masterlist')->find($item->product_id);

                // Use ONLY the description from sales_order_items
                $description = $item->description ?? '';

                return [
                    'product_id' => $item->product_id,
                    'product_code' => (string) ($item->product_code ?? ''),
                    'price_code' => $item->price_code ?? '',
                    'description' => $description,
                    'application' => $product ? ($product->application ?? '') : '',
                    'quantity' => $item->quantity,
                    'actual_qty' => $item->actual_qty,
                    'additional_qty' => $item->additional_qty,
                    'oum' => $item->oum,
                    'unit_price' => $item->unit_price,
                    'discount' => $item->discount,
                    'additional_discount' => $item->additional_discount,
                    'subtotal' => $item->subtotal,
                    'particulars' => $item->particulars ?? '',
                ];
            })->values();

            return response()->json([
                'success' => true,
                'order' => [
                    'id' => $salesOrder->id,
                    'sales_number' => $salesOrder->order_number,
                    'sales_note_number' => $salesNoteNumber !== ''
                        ? $salesNoteNumber
                        : $salesOrder->order_number,
                    'invoice_number' => $salesOrder->invoice_numbers,
                    'order_date' => date('Y-m-d', strtotime($salesOrder->created_at)),
                    'date_issue' => date('Y-m-d', strtotime($salesOrder->created_at)),
                    'customer_name' => $salesOrder->customer_name,
                    'customer_id' => $salesOrder->customer_id,
                    'salesman' => (string) ($salesNote->salesman ?? ''),
                    'total_amount' => $salesOrder->total_amount,
                    'waybill_no' => $salesOrder->waybill_no,
                    'waybill_date' => $salesOrder->waybill_date,
                    'status' => $salesOrder->status,
                    'is_rush' => $salesOrder->salesNote
                        ? (bool) $salesOrder->salesNote->is_rush
                        : false,
                    'remarks' => $salesOrder->remarks,
                    'movement' => $invoiceMovement,
                    'items' => $items,
                ],
            ]);
        }
    } catch (\Exception $e) {
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.sales-order.detail');

