// Sales Order - Check Stock
Route::post('/admin/sales/sales-order/check-stock', function (Request $request) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

    try {
        $data = $request->validate([
            'items' => 'required|array|min:1',
            'items.*.product_id' => 'nullable|integer',
            'items.*.product_code' => 'required|string',
            'items.*.description' => 'nullable|string',
            'items.*.actual_qty' => 'required|integer|min:1',
            'items.*.additional_qty' => 'nullable|integer|min:0',
        ]);

        $items = $data['items'];

        $normalized = [];
        foreach ($items as $item) {
            $pid = (int) ($item['product_id'] ?? 0);
            if (!$pid) {
                $p = DB::connection('masterlist')->table('products')->where('product_code', $item['product_code'])->first(['id']);
                $pid = $p ? (int) $p->id : 0;
            }
            $actualQty = (int) ($item['actual_qty'] ?? 0);
            $add = (int) ($item['additional_qty'] ?? 0);
            $reqQty = $actualQty + $add;

            $normalized[] = [
                'product_id' => $pid,
                'product_code' => (string) ($item['product_code'] ?? ''),
                'description' => (string) ($item['description'] ?? ''),
                'requested_qty' => $reqQty,
            ];
        }

        $requestedByPid = [];
        $metaByPid = [];
        $issues = [];

        foreach ($normalized as $i) {
            $pid = (int) ($i['product_id'] ?? 0);
            if ($pid <= 0) {
                $issues[] = [
                    'product_id' => 0,
                    'product_code' => $i['product_code'],
                    'description' => $i['description'],
                    'requested_qty' => (float) $i['requested_qty'],
                    'available_stock' => 0,
                    'reason' => 'Product not found',
                ];
                continue;
            }

            $requestedByPid[$pid] = (float) ($requestedByPid[$pid] ?? 0) + (float) $i['requested_qty'];
            if (!isset($metaByPid[$pid])) {
                $metaByPid[$pid] = [
                    'product_code' => $i['product_code'],
                    'description' => $i['description'],
                ];
            }
        }

        $productIds = array_keys($requestedByPid);
        if (empty($productIds)) {
            return response()->json([
                'success' => true,
                'ok' => empty($issues),
                'issues' => $issues,
            ]);
        }

        // Build latest ledger balance map using the corrected query
        $latestCreatedAtQuery = DB::connection('ledger')
            ->table('product_ledgers as pl')
            ->selectRaw('pl.product_id, MAX(pl.created_at) as max_created_at')
            ->whereIn('pl.product_id', $productIds)
            ->groupBy('pl.product_id');

        $latestIdsQuery = DB::connection('ledger')
            ->table('product_ledgers as pl')
            ->joinSub($latestCreatedAtQuery, 'lc', function ($join) {
                $join->on('pl.product_id', '=', 'lc.product_id')
                    ->on('pl.created_at', '=', 'lc.max_created_at');
            })
            ->selectRaw('MAX(pl.id) as id')
            ->groupBy('pl.product_id');

        $latestRows = DB::connection('ledger')
            ->table('product_ledgers')
            ->whereIn('id', $latestIdsQuery)
            ->get(['product_id', 'balance_stock']);

        $balanceMap = [];
        foreach ($latestRows as $r) {
            $balanceMap[(int) $r->product_id] = (float) ($r->balance_stock ?? 0);
        }

        // Default to 0 for products with no ledger entries (user requirement)
        foreach ($requestedByPid as $pid => $_) {
            if (!isset($balanceMap[(int) $pid])) {
                $balanceMap[(int) $pid] = 0;
            }
        }

        // LOG: Stock check balance map
        \Log::info('[STOCK CHECK] Balance map built', [
            'requested_products' => $requestedByPid,
            'balance_map' => $balanceMap,
            'endpoint' => 'proceed-check-stock',
        ]);

        // Check stock availability and build issues list
        foreach ($requestedByPid as $pid => $requestedQty) {
            $available = (float) ($balanceMap[(int) $pid] ?? 0);
            if ($available < (float) $requestedQty) {
                $meta = $metaByPid[(int) $pid] ?? ['product_code' => '', 'description' => ''];
                $issues[] = [
                    'product_id' => (int) $pid,
                    'product_code' => $meta['product_code'],
                    'description' => $meta['description'],
                    'requested_qty' => (float) $requestedQty,
                    'available_stock' => $available,
                    'reason' => $available <= 0 ? 'Out of stock' : 'Not enough stock',
                ];
            }
        }

        return response()->json([
            'success' => true,
            'ok' => empty($issues),
            'issues' => $issues,
        ]);
    } catch (\Throwable $e) {
        \Log::error('Stock check failed', [
            'message' => $e->getMessage(),
            'file' => $e->getFile(),
            'line' => $e->getLine(),
            'trace' => $e->getTraceAsString()
        ]);
        return response()->json([
            'success' => false, 
            'message' => 'Stock check failed: ' . $e->getMessage()
        ], 422);
    }
})->name('admin.sales-order.check-stock');

// Sales Order - Edit Check Stock (checks NET INCREASE and identifies NEW items)
Route::post('/admin/sales/sales-order/edit-check-stock', function (Request $request) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

    try {
        $data = $request->validate([
            'items' => 'required|array|min:1',
            'items.*.product_id' => 'nullable|integer',
            'items.*.product_code' => 'required|string',
            'items.*.description' => 'nullable|string',
            'items.*.actual_qty' => 'required|numeric|min:0',
            'items.*.additional_qty' => 'nullable|numeric|min:0',
            'items.*.old_qty' => 'nullable|numeric|min:0',
            'note_id' => 'required|integer',
            'order_number' => 'required|string', // To check if item has ledger entry
        ]);

        $items = $data['items'];
        $noteId = $data['note_id'];
        $orderNumber = $data['order_number'];

        $requestedByPid = [];
        $metaByPid = [];
        $issues = [];

        foreach ($items as $item) {
            $pid = (int) ($item['product_id'] ?? 0);
            if (!$pid) {
                $p = DB::connection('masterlist')->table('products')->where('product_code', $item['product_code'])->first(['id']);
                $pid = $p ? (int) $p->id : 0;
            }
            
            if ($pid <= 0) {
                $issues[] = [
                    'product_id' => 0,
                    'product_code' => $item['product_code'],
                    'description' => $item['description'] ?? '',
                    'requested_qty' => 0,
                    'available_stock' => 0,
                    'reason' => 'Product not found',
                ];
                continue;
            }

            $newQty = (float) ($item['actual_qty'] ?? 0);
            $oldQty = (float) ($item['old_qty'] ?? 0);
            
            // Check if this item has a ledger entry with this transaction_number
            $hasLedgerEntry = DB::connection('ledger')->table('product_ledgers')
                ->where('product_id', $pid)
                ->where('transaction_number', $orderNumber)
                ->exists();
            
            // If item has NO ledger entry with this order number, it's NEW (added via Sales Note)
            // We need to check FULL quantity for new items
            if (!$hasLedgerEntry) {
                // Item is in SO but has no ledger entry = NEW item from Sales Note sync
                // Check FULL quantity
                $netIncrease = $newQty;
            } else {
                // Old item that has ledger entry - check only the INCREASE
                $diff = $newQty - $oldQty;
                $netIncrease = max(0, $diff);
            }

            // Only add to check if there's stock needed
            if ($netIncrease > 0) {
                $requestedByPid[$pid] = (float) ($requestedByPid[$pid] ?? 0) + $netIncrease;
                if (!isset($metaByPid[$pid])) {
                    $metaByPid[$pid] = [
                        'product_code' => $item['product_code'],
                        'description' => $item['description'] ?? '',
                        'is_new' => !$hasLedgerEntry,
                    ];
                }
            }
        }

        $productIds = array_keys($requestedByPid);
        if (empty($productIds)) {
            // No net increase - stock check passes
            return response()->json([
                'success' => true,
                'ok' => true,
                'issues' => [],
            ]);
        }

        // Build latest ledger balance map
        $latestCreatedAtQuery = DB::connection('ledger')
            ->table('product_ledgers as pl')
            ->selectRaw('pl.product_id, MAX(pl.created_at) as max_created_at')
            ->whereIn('pl.product_id', $productIds)
            ->groupBy('pl.product_id');

        $latestIdsQuery = DB::connection('ledger')
            ->table('product_ledgers as pl')
            ->joinSub($latestCreatedAtQuery, 'lc', function ($join) {
                $join->on('pl.product_id', '=', 'lc.product_id')
                    ->on('pl.created_at', '=', 'lc.max_created_at');
            })
            ->selectRaw('MAX(pl.id) as id')
            ->groupBy('pl.product_id');

        $latestRows = DB::connection('ledger')
            ->table('product_ledgers')
            ->whereIn('id', $latestIdsQuery)
            ->get(['product_id', 'balance_stock']);

        $balanceMap = [];
        foreach ($latestRows as $r) {
            $balanceMap[(int) $r->product_id] = (float) ($r->balance_stock ?? 0);
        }

        // Fallback: If no ledger entry exists, use products.on_hand (or treat as 0)
        foreach ($requestedByPid as $pid => $_) {
            if (!isset($balanceMap[(int) $pid])) {
                $p = \App\Models\Product::on('masterlist')->find((int) $pid);
                // For items without ANY ledger history, use on_hand or default to 0
                $balanceMap[(int) $pid] = $p ? (float) ($p->on_hand ?? 0) : 0;
            }
        }

        // Check stock availability and build issues list
        foreach ($requestedByPid as $pid => $requestedQty) {
            $available = (float) ($balanceMap[(int) $pid] ?? 0);
            if ($available < (float) $requestedQty) {
                $meta = $metaByPid[(int) $pid] ?? ['product_code' => '', 'description' => '', 'is_new' => false];
                $reason = $available <= 0 ? 'Out of stock' : 'Not enough stock';
                if ($meta['is_new']) {
                    $reason .= ' (New item)';
                }
                
                $issues[] = [
                    'product_id' => (int) $pid,
                    'product_code' => $meta['product_code'],
                    'description' => $meta['description'],
                    'requested_qty' => (float) $requestedQty,
                    'available_stock' => $available,
                    'reason' => $reason,
                ];
            }
        }

        return response()->json([
            'success' => true,
            'ok' => empty($issues),
            'issues' => $issues,
        ]);
    } catch (\Throwable $e) {
        \Log::error('Edit stock check error', ['error' => $e->getMessage()]);
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.sales-order.edit-check-stock');

// Sales Order - Proceed (process order)
// Sales Order - Force close a Partial Sales Note while preserving invoiced Sales Order history.
Route::post('/admin/sales/sales-order/force-close-note/{salesNoteId}', function ($salesNoteId) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

    try {
        $result = DB::connection('sales')->transaction(function () use ($salesNoteId) {
            $note = \App\Models\SalesNote::on('sales')
                ->whereKey($salesNoteId)
                ->lockForUpdate()
                ->first();

            if (!$note) {
                throw new \RuntimeException('Sales Note not found.');
            }

            if (strcasecmp(trim((string) $note->status), 'Partial') !== 0) {
                throw new \RuntimeException('Only Partial Sales Notes can be force closed.');
            }

            $noteBefore = $note->toArray();
            $noteItems = \App\Models\SalesNoteItem::on('sales')
                ->where('sales_note_id', $note->id)
                ->orderBy('id')
                ->lockForUpdate()
                ->get();
            $itemsBefore = $noteItems->map(fn ($item) => $item->toArray())->values()->all();

            // Invoiced/served quantity is stored in sales_order_items.actual_qty.
            // Allocate it across matching Sales Note rows in ID order so duplicate
            // product rows are handled without counting the same invoiced quantity twice.
            $servedRows = DB::connection('sales')
                ->table('sales_orders as so')
                ->join('sales_order_items as soi', 'soi.sales_order_id', '=', 'so.id')
                ->where('so.sales_note_id', $note->id)
                ->select([
                    'soi.product_id',
                    DB::raw('SUM(COALESCE(soi.actual_qty, 0)) as served_qty'),
                ])
                ->groupBy('soi.product_id')
                ->get();

            $servedRemaining = [];
            foreach ($servedRows as $row) {
                $servedRemaining[(int) $row->product_id] = max(0, (float) ($row->served_qty ?? 0));
            }

            $deletedItemCount = 0;
            $trimmedItemCount = 0; // Kept in the response for older front-end compatibility; force close no longer trims rows.
            $removedQuantity = 0.0;
            $preservedInvoicedQuantity = 0.0;

            foreach ($noteItems as $item) {
                $productId = (int) $item->product_id;
                $orderedQty = max(0, (float) ($item->quantity ?? 0));
                $availableServed = max(0, (float) ($servedRemaining[$productId] ?? 0));
                $invoicedQtyForRow = min($orderedQty, $availableServed);
                $remainingQtyForRow = max(0, $orderedQty - $invoicedQtyForRow);

                $servedRemaining[$productId] = max(0, $availableServed - $invoicedQtyForRow);
                $preservedInvoicedQuantity += $invoicedQtyForRow;

                if ($remainingQtyForRow <= 0) {
                    // Fully invoiced Sales Note item: keep the note row unchanged.
                    continue;
                }

                $removedQuantity += $remainingQtyForRow;

                // Purchase-style force close: if this Sales Note row still has any
                // outstanding quantity, remove the row instead of rewriting it to the
                // invoiced quantity. The invoiced quantity/history is already preserved
                // in sales_orders and sales_order_items.actual_qty and is never deleted here.
                // Example: ordered 10, invoiced 6, remaining 4 => preserve invoice 6,
                // delete this remaining Sales Note row, then close the Sales Note.
                $item->delete();
                $deletedItemCount++;
            }

            $note->status = 'Closed';
            $note->save();

            $invoiceCount = DB::connection('sales')
                ->table('sales_orders')
                ->where('sales_note_id', $note->id)
                ->count();

            $itemsAfter = \App\Models\SalesNoteItem::on('sales')
                ->where('sales_note_id', $note->id)
                ->orderBy('id')
                ->get()
                ->map(fn ($item) => $item->toArray())
                ->values()
                ->all();

            return [
                'note_before' => $noteBefore,
                'note_after' => $note->fresh()->toArray(),
                'items_before' => $itemsBefore,
                'items_after' => $itemsAfter,
                'deleted_item_count' => $deletedItemCount,
                'trimmed_item_count' => $trimmedItemCount,
                'removed_quantity' => $removedQuantity,
                'preserved_invoiced_quantity' => $preservedInvoicedQuantity,
                'invoice_count' => $invoiceCount,
            ];
        });

        $actor = hatdogAuditActor($user);
        hatdogWriteAuditTrail([
            'module' => 'sales_order',
            'action' => 'Force Closed Sales Note',
            'source_connection' => 'sales',
            'source_table' => 'sales_notes',
            'source_id' => (int) $salesNoteId,
            'display_id' => (string) ($result['note_after']['sales_number'] ?? $salesNoteId),
            'record_name' => (string) ($result['note_after']['customer_name'] ?? 'Sales Note'),
            'user_name' => $actor['name'],
            'user_identifier' => $actor['identifier'],
            'audit_data' => $result,
        ]);

        return response()->json([
            'success' => true,
            'message' => 'Sales Note force closed successfully. Remaining items were removed and invoiced items were preserved.',
            'note_status' => 'Closed',
            'deleted_item_count' => $result['deleted_item_count'],
            'trimmed_item_count' => $result['trimmed_item_count'],
            'removed_quantity' => $result['removed_quantity'],
            'preserved_invoiced_quantity' => $result['preserved_invoiced_quantity'],
            'invoice_count' => $result['invoice_count'],
        ]);
    } catch (\RuntimeException $e) {
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    } catch (\Throwable $e) {
        \Log::error('Sales Note force close failed.', [
            'sales_note_id' => $salesNoteId,
            'message' => $e->getMessage(),
        ]);
        return response()->json(['success' => false, 'message' => 'Unable to force close Sales Note: ' . $e->getMessage()], 422);
    }
})->name('admin.sales-order.force-close-note');

Route::post('/admin/sales/sales-order/proceed', function (Request $request) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);
    try {
        $noteId = $request->input('sales_note_id');
        $note = \App\Models\SalesNote::on('sales')->find($noteId);
        if (!$note) return response()->json(['success' => false, 'message' => 'Sales note not found.'], 404);

        $invoiceNumber = trim((string) $request->input('invoice_number')); // Single invoice per proceed
        $items = $request->input('items', []); // Only checked items from Step 2
        $orderDate = trim((string) $request->input('order_date', now()->toDateString()));

        if (!preg_match('/^\d{4}-\d{2}-\d{2}$/', $orderDate)) {
            return response()->json(['success' => false, 'message' => 'Sales Order date must be a valid date.'], 422);
        }
        try {
            $selectedOrderDate = \Carbon\Carbon::createFromFormat('Y-m-d', $orderDate);
            if (!$selectedOrderDate || $selectedOrderDate->format('Y-m-d') !== $orderDate) {
                throw new \RuntimeException('Invalid date.');
            }
        } catch (\Throwable $dateError) {
            return response()->json(['success' => false, 'message' => 'Sales Order date must be a valid date.'], 422);
        }
        $currentClock = now();
        $salesOrderCreatedAt = $selectedOrderDate->copy()->setTime(
            $currentClock->hour,
            $currentClock->minute,
            $currentClock->second
        );

        if (empty($invoiceNumber)) {
            return response()->json(['success' => false, 'message' => 'Invoice number is required.'], 422);
        }

        try {
            \Illuminate\Support\Facades\DB::connection('sales')->beginTransaction();
            \Illuminate\Support\Facades\DB::connection('ledger')->beginTransaction();
            \Illuminate\Support\Facades\DB::connection('masterlist')->beginTransaction();

            $existingInvoice = \Illuminate\Support\Facades\DB::connection('sales')
                ->table('sales_orders')
                ->where('sales_note_id', $noteId)
                ->where('invoice_numbers', $invoiceNumber)
                ->lockForUpdate()
                ->first();

            if ($existingInvoice) {
                throw new \Exception("Invoice number {$invoiceNumber} was already processed for this Sales Note.");
            }
            
            $noteBefore = $note->toArray();
            $customer = null;
            if (!empty($note->customer_id)) {
                $customer = \App\Models\Customer::on('masterlist')->find($note->customer_id);
            }

            // Get sales note items for validation
            $noteItems = DB::connection('sales')
                ->table('sales_note_items')
                ->where('sales_note_id', $note->id)
                ->get(['product_id', 'quantity'])
                ->keyBy('product_id');

            // Calculate already served quantities across ALL existing invoices for this sales note
            $servedRows = DB::connection('sales')
                ->table('sales_orders as so')
                ->join('sales_order_items as soi', 'soi.sales_order_id', '=', 'so.id')
                ->where('so.order_number', $note->sales_number) // Same order_number (sales_number)
                ->select(['soi.product_id', DB::raw('SUM(COALESCE(soi.actual_qty, 0)) as served_qty')])
                ->groupBy('soi.product_id')
                ->get();

            $servedMap = [];
            foreach ($servedRows as $row) {
                $servedMap[(int) $row->product_id] = (float) ($row->served_qty ?? 0);
            }

            // Create NEW sales order record for THIS invoice (same order_number, different invoice_numbers)
            $salesOrderId = \Illuminate\Support\Facades\DB::connection('sales')->table('sales_orders')->insertGetId([
                'sales_note_id' => $noteId,
                'order_number' => $note->sales_number, // Same order_number for all invoices from this sales note
                'customer_id' => $note->customer_id,
                'customer_name' => $note->customer_name,
                'invoice_numbers' => trim($invoiceNumber), // Store as single invoice (not comma-separated)
                'total_amount' => 0, // Will be calculated from items
                'status' => 'Confirmed',
                // created_at is the Sales Order issue date used throughout History/Edit/Print.
                // Step 1 lets the user choose the date while keeping the current clock time.
                'created_at' => $salesOrderCreatedAt,
                'updated_at' => now(),
            ]);

            // Process ONLY the checked items from Step 2
            $processedCount = 0;
            $requestTotalAmount = 0;
            $requestServedAdds = [];
            $productsToSync = [];
            
            foreach ($items as $itemData) {
                $productId = (int)($itemData['product_id'] ?? 0);
                $actualQty = (float) ($itemData['actual_qty'] ?? 0);
                
                if ($actualQty <= 0) continue;

                $submittedQty = (float) ($itemData['quantity'] ?? 0);
                if ($actualQty > $submittedQty) {
                    throw new \Exception(
                        "Actual QTY ($actualQty) cannot exceed QTY ($submittedQty) for "
                        . ($itemData['product_code'] ?? "product ID $productId")
                        . '.'
                    );
                }

                $orderedQty = (float) (($noteItems->get($productId)->quantity ?? 0));
                $alreadyServed = (float) ($servedMap[$productId] ?? 0);
                $remainingBefore = max(0, $orderedQty - $alreadyServed);

                // Validation: can't exceed remaining quantity
                if ($actualQty > $remainingBefore) {
                    throw new \Exception("Actual QTY ($actualQty) exceeds remaining QTY ($remainingBefore) for product ID $productId.");
                }

                // Insert item into THIS invoice's sales order
                $salesOrderItemId = \Illuminate\Support\Facades\DB::connection('sales')->table('sales_order_items')->insertGetId([
                    'sales_order_id' => $salesOrderId,
                    'product_id' => $productId,
                    'product_code' => $itemData['product_code'] ?? '',
                    'price_code' => $itemData['price_code'] ?? '',
                    'description' => $itemData['description'] ?? '',
                    'quantity' => $submittedQty > 0 ? $submittedQty : $orderedQty,
                    'actual_qty' => $actualQty,
                    'additional_qty' => $itemData['additional_qty'] ?? 0,
                    'oum' => $itemData['oum'] ?? '',
                    'unit_price' => $itemData['unit_price'] ?? 0,
                    'discount' => $itemData['discount'] ?? 0,
                    'additional_discount' => $itemData['additional_discount'] ?? 0,
                    'subtotal' => $itemData['subtotal'] ?? 0,
                    'particulars' => $itemData['particulars'] ?? '',
                    'created_at' => now(),
                    'updated_at' => now(),
                ]);

                $requestTotalAmount += (float) ($itemData['subtotal'] ?? 0);

                // Record OUT movement via shared service.
                // Bonus QTY is additional free quantity: stock movement = Actual QTY + Bonus QTY.
                // It never affects billable values (subtotal, remaining qty) stored on the item.
                $previousActualQty = 0; // This is always a new item in proceed mode
                $totalOut = (float) $actualQty + (float) ($itemData['additional_qty'] ?? 0);
                $result = SalesOrderLedgerService::recordOutMovement([
                    'product_id' => $productId,
                    'customer_id' => $note->customer_id,
                    'customer_name' => $note->customer_name,
                    'transaction_number' => $note->sales_number,
                    'reference_number' => $invoiceNumber,
                    'source_id' => $salesOrderId,
                    'source_item_id' => $salesOrderItemId,
                    'previous_actual_qty' => $previousActualQty,
                    'new_actual_qty' => $totalOut,
                    'oum' => $itemData['oum'] ?? 'PCS',
                    'unit_price' => $itemData['unit_price'] ?? 0,
                    'cost' => 0,
                    'remarks_prefix' => 'Sales Order Processing',
                ]);

                if ($result['created']) {
                    $processedCount++;
                    $productsToSync[] = $productId;
                }

                $requestServedAdds[$productId] = ($requestServedAdds[$productId] ?? 0) + $actualQty;
            }

            // Update the new sales order total
            \Illuminate\Support\Facades\DB::connection('sales')->table('sales_orders')
                ->where('id', $salesOrderId)
                ->update([
                    'total_amount' => $requestTotalAmount,
                    'updated_at' => now(),
                ]);

            // Determine if sales note has remaining items (partial status)
            $hasRemaining = false;
            foreach ($noteItems as $pId => $ni) {
                $orderedQty = (float) ($ni->quantity ?? 0);
                $alreadyServed = (float) ($servedMap[(int) $pId] ?? 0);
                $addedThisRequest = (float) ($requestServedAdds[(int) $pId] ?? 0);
                $remaining = $orderedQty - $alreadyServed - $addedThisRequest;
                if ($remaining > 0) { 
                    $hasRemaining = true; 
                    break; 
                }
            }

            // Update sales note status based on whether unchecked items remain
            $note->status = $hasRemaining ? 'Partial' : 'Closed';
            $note->save();

            $salesOrderAfter = \App\Models\SalesOrder::on('sales')->with('items')->find($salesOrderId);
            $actor = hatdogAuditActor($user);
            $recordName = trim((string) (($note->customer_name ?? '') !== '' ? $note->customer_name : ('Sales Order ' . ($note->sales_number ?? $salesOrderId))));

            hatdogWriteAuditTrail([
                'module' => 'sales_order',
                'action' => 'Processed',
                'source_connection' => 'sales',
                'source_table' => 'sales_orders',
                'source_id' => $salesOrderId,
                'display_id' => (string) ($invoiceNumber ?? $salesOrderId),
                'record_name' => $recordName,
                'user_name' => $actor['name'],
                'user_identifier' => $actor['identifier'],
                'audit_data' => [
                    'sales_order_after' => $salesOrderAfter?->toArray(),
                    'sales_order_items_after' => $salesOrderAfter?->items?->map(fn ($item) => $item->toArray())->values()->all() ?? [],
                    'sales_note_before' => $noteBefore,
                    'sales_note_after' => $note->fresh()->toArray(),
                    'customer' => $customer?->toArray(),
                    'invoice_number' => $invoiceNumber,
                    'request_items' => collect($items)->values()->all(),
                ],
            ]);

            \Illuminate\Support\Facades\DB::connection('sales')->commit();
            \Illuminate\Support\Facades\DB::connection('ledger')->commit();
            \Illuminate\Support\Facades\DB::connection('masterlist')->commit();

            // Sync products.on_hand after ledger commit
            $syncCount = 0;
            foreach (array_unique($productsToSync) as $syncPid) {
                try {
                    ProductStockSyncService::syncProduct($syncPid);
                    $syncCount++;
                } catch (\Exception $syncEx) {
                    \Illuminate\Support\Facades\Log::warning(
                        '[SALES ORDER LEDGER] ProductStockSync failed for product ' . $syncPid . ': ' . $syncEx->getMessage()
                    );
                }
            }

            \Illuminate\Support\Facades\Log::info('Sales Order Processed (Per Invoice):', [
                'sales_number' => $note->sales_number,
                'invoice_number' => $invoiceNumber,
                'items_received' => count($items),
                'ledger_entries_created' => $processedCount,
                'products_synced' => $syncCount,
            ]);

            return response()->json([
                'success' => true, 
                'note_status' => $note->status,
                'sales_order_id' => $salesOrderId,
                'invoice_number' => $invoiceNumber,
                'order_date' => $salesOrderCreatedAt->format('Y-m-d')
            ]);

        } catch (\Exception $dbEx) {
            if (\Illuminate\Support\Facades\DB::connection('sales')->transactionLevel() > 0) {
                \Illuminate\Support\Facades\DB::connection('sales')->rollBack();
            }
            if (\Illuminate\Support\Facades\DB::connection('ledger')->transactionLevel() > 0) {
                \Illuminate\Support\Facades\DB::connection('ledger')->rollBack();
            }
            if (\Illuminate\Support\Facades\DB::connection('masterlist')->transactionLevel() > 0) {
                \Illuminate\Support\Facades\DB::connection('masterlist')->rollBack();
            }
            throw $dbEx;
        }
    } catch (\Exception $e) {
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.sales-order.proceed');

// Sales Order - Edit detail (returns SalesOrder data for a note)
Route::get('/admin/sales/sales-order/edit-detail/{salesOrderId}', function ($salesOrderId) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);
    try {
        // Load specific sales_order (invoice)
        $so = \App\Models\SalesOrder::on('sales')->with('items')->find($salesOrderId);
        if (!$so) return response()->json(['success' => false, 'message' => 'Sales order not found.'], 404);

        $note = \App\Models\SalesNote::on('sales')->find($so->sales_note_id);
        $customer = \App\Models\Customer::on('masterlist')->find($so->customer_id);

        return response()->json([
            'success' => true,
            'sales_order' => [
                'id' => $so->id,
                'sales_note_id' => $so->sales_note_id,
                'order_number' => $so->order_number,
                'customer_id' => $so->customer_id,
                'customer_name' => $so->customer_name,
                'invoice_numbers' => $so->invoice_numbers,
                'waybill_no' => $so->waybill_no,
                'waybill_date' => $so->waybill_date,
                'total_amount' => $so->total_amount,
                'status' => $so->status,
                'remarks' => $so->remarks,
                'note_status' => $note ? $note->status : '',
                'note_gross_total' => $note ? $note->gross_total : 0,
                'note_net_total' => $note ? $note->net_total : 0,
                'order_date' => $so->created_at ? date('Y-m-d', strtotime($so->created_at)) : '',
                'items' => $so->items->map(function ($item) use ($so) {
                    $product = \App\Models\Product::on('masterlist')->find($item->product_id);
                    
                    // Check if this item has a ledger entry with this invoice's reference
                    $hasLedgerEntry = DB::connection('ledger')->table('product_ledgers')
                        ->where('product_id', $item->product_id)
                        ->where('transaction_number', $so->order_number)
                        ->where('reference_number', $so->invoice_numbers)
                        ->exists();
                    
                    // If item has ledger entry, old_qty = actual_qty; otherwise old_qty = 0 (NEW item)
                    $oldQtyLedger = $hasLedgerEntry ? $item->actual_qty : 0;
                    
                    // Fallback: if sales_order_items.price_code is empty, check sales_note_items
                    $priceCode = $item->price_code;
                    if (empty($priceCode) && $so->sales_note_id && $item->product_id) {
                        $sni = \App\Models\SalesNoteItem::on('sales')
                            ->where('sales_note_id', $so->sales_note_id)
                            ->where('product_id', $item->product_id)
                            ->first();
                        $priceCode = $sni ? $sni->price_code : '';
                    }
                    
                    return [
                        'id' => $item->id,
                        'product_id' => $item->product_id,
                        'product_code' => (string) ($item->product_code ?? ''),
                        'price_code' => $priceCode ?: '',
                        'description' => $item->description,
                        'quantity' => $item->quantity,
                        'actual_qty' => $item->actual_qty,
                        'additional_qty' => $item->additional_qty,
                        'oum' => $item->oum,
                        'unit_price' => $item->unit_price,
                        'discount' => $item->discount,
                        'additional_discount' => $item->additional_discount,
                        'subtotal' => $item->subtotal,
                        'particulars' => $item->particulars,
                        'on_hand' => $product ? $product->on_hand : 0,
                        'cost' => $product ? $product->cost : 0,
                        'old_qty_ledger' => $oldQtyLedger,
                        'has_ledger_entry' => $hasLedgerEntry,
                    ];
                }),
            ],
        ]);
    } catch (\Exception $e) {
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.sales-order.edit-detail');

// Sales Order - Update (authoritative item snapshot + ledger reconciliation)
Route::post('/admin/sales/sales-order/update/{salesOrderId}', function (Request $request, $salesOrderId) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

    try {
        $so = \App\Models\SalesOrder::on('sales')->with('items')->find($salesOrderId);
        if (!$so) return response()->json(['success' => false, 'message' => 'Sales order not found.'], 404);

        $note = \App\Models\SalesNote::on('sales')->find($so->sales_note_id);
        if (!$note) return response()->json(['success' => false, 'message' => 'Sales note not found.'], 404);

        $validator = Validator::make($request->all(), [
            'invoice_number' => 'nullable|string',
            'invoices' => 'nullable|array',
            'invoices.*' => 'nullable|string',
            'order_date' => 'required|date_format:Y-m-d',
            'waybill_no' => 'nullable|string',
            'waybill_date' => 'nullable|date',
            'remarks' => 'nullable|string',
            'items' => 'present|array',
            'items.*.sales_order_item_id' => 'nullable|integer',
            'items.*.product_id' => 'required|integer|min:1',
            'items.*.product_code' => 'required|string',
            'items.*.description' => 'nullable|string',
            'items.*.quantity' => 'required|numeric|min:0',
            'items.*.actual_qty' => 'required|numeric|min:0',
            'items.*.additional_qty' => 'nullable|numeric|min:0',
            'items.*.oum' => 'nullable|string',
            'items.*.unit_price' => 'required|numeric|min:0',
            'items.*.discount' => 'nullable|numeric|min:0',
            'items.*.additional_discount' => 'nullable|numeric|min:0',
            'items.*.price_code' => 'nullable|string',
            'items.*.subtotal' => 'required|numeric|min:0',
            'items.*.particulars' => 'nullable|string',
        ]);

        $validator->after(function ($validator) use ($request) {
            $seenProductIds = [];
            $seenItemIds = [];
            foreach ((array) $request->input('items', []) as $index => $item) {
                $qty = (float) ($item['quantity'] ?? 0);
                $actualQty = (float) ($item['actual_qty'] ?? 0);
                if ($actualQty > $qty) {
                    $validator->errors()->add(
                        "items.$index.actual_qty",
                        'Actual QTY cannot exceed QTY for item ' . ($item['product_code'] ?? ($index + 1)) . '.'
                    );
                }

                $productId = (int) ($item['product_id'] ?? 0);
                if ($productId > 0 && isset($seenProductIds[$productId])) {
                    $validator->errors()->add("items.$index.product_id", 'Duplicate products are not allowed in one Sales Order.');
                }
                if ($productId > 0) $seenProductIds[$productId] = true;

                $itemId = (int) ($item['sales_order_item_id'] ?? 0);
                if ($itemId > 0 && isset($seenItemIds[$itemId])) {
                    $validator->errors()->add("items.$index.sales_order_item_id", 'Duplicate Sales Order item IDs are not allowed.');
                }
                if ($itemId > 0) $seenItemIds[$itemId] = true;
            }
        });

        if ($validator->fails()) {
            return response()->json([
                'success' => false,
                'message' => $validator->errors()->first(),
                'errors' => $validator->errors(),
            ], 422);
        }

        $data = $validator->validated();

        // The Sales Order date is stored in sales_orders.created_at because the current
        // schema has no separate order_date column. Preserve the original clock time so
        // changing the date does not destroy the record's within-day ordering.
        $existingCreatedAt = $so->created_at ? \Carbon\Carbon::parse($so->created_at) : now();
        $salesOrderCreatedAt = \Carbon\Carbon::createFromFormat('Y-m-d', $data['order_date'])->setTime(
            $existingCreatedAt->hour,
            $existingCreatedAt->minute,
            $existingCreatedAt->second
        );

        DB::connection('sales')->beginTransaction();
        DB::connection('ledger')->beginTransaction();
        DB::connection('masterlist')->beginTransaction();

        try {
            $soBefore = $so->toArray();
            $noteBefore = $note->toArray();
            $existingItems = $so->items()->lockForUpdate()->get()->keyBy('id');
            $keptItemIds = [];
            $requestTotalAmount = 0.0;

            foreach ($data['items'] as $itemData) {
                $productId = (int) ($itemData['product_id'] ?? 0);
                $product = \App\Models\Product::on('masterlist')->find($productId);
                if (!$product) {
                    throw new \RuntimeException('Master-list product not found for ' . ($itemData['product_code'] ?? ('ID ' . $productId)) . '.');
                }

                $payload = [
                    'product_id' => $productId,
                    'product_code' => trim((string) ($itemData['product_code'] ?? '')) ?: (string) $product->product_code,
                    'price_code' => $itemData['price_code'] ?? '',
                    'description' => $itemData['description'] ?? ($product->description ?? ''),
                    'quantity' => (float) ($itemData['quantity'] ?? 0),
                    'actual_qty' => (float) ($itemData['actual_qty'] ?? 0),
                    'additional_qty' => (float) ($itemData['additional_qty'] ?? 0),
                    'oum' => trim((string) ($itemData['oum'] ?? '')) ?: 'PCS',
                    'unit_price' => (float) ($itemData['unit_price'] ?? 0),
                    'discount' => (float) ($itemData['discount'] ?? 0),
                    'additional_discount' => (float) ($itemData['additional_discount'] ?? 0),
                    'subtotal' => (float) ($itemData['subtotal'] ?? 0),
                    'particulars' => $itemData['particulars'] ?? '',
                ];

                $requestedItemId = (int) ($itemData['sales_order_item_id'] ?? 0);
                if ($requestedItemId > 0) {
                    $existingItem = $existingItems->get($requestedItemId);
                    if (!$existingItem) {
                        throw new \RuntimeException('Sales Order item #' . $requestedItemId . ' does not belong to this invoice.');
                    }
                    $existingItem->fill($payload);
                    $existingItem->save();
                    $savedItem = $existingItem;
                } else {
                    $payload['sales_order_id'] = (int) $so->id;
                    $savedItem = \App\Models\SalesOrderItem::on('sales')->create($payload);
                }

                $keptItemIds[] = (int) $savedItem->id;
                $requestTotalAmount += (float) $payload['subtotal'];
            }

            // Physical removal from the invoice snapshot. The ledger reconciler
            // below physically removes the matching OUT movement as well.
            $deleteQuery = \App\Models\SalesOrderItem::on('sales')->where('sales_order_id', $so->id);
            if (!empty($keptItemIds)) {
                $deleteQuery->whereNotIn('id', $keptItemIds);
            }
            $deleteQuery->delete();

            $normalizedInvoices = collect((array) ($data['invoices'] ?? []))
                ->map(fn ($value) => trim((string) $value))
                ->filter(fn ($value) => $value !== '')
                ->unique()
                ->values();
            if ($normalizedInvoices->isEmpty() && trim((string) ($data['invoice_number'] ?? '')) !== '') {
                $normalizedInvoices->push(trim((string) $data['invoice_number']));
            }
            $invoiceText = $normalizedInvoices->isNotEmpty()
                ? $normalizedInvoices->implode(', ')
                : (string) ($so->invoice_numbers ?? '');

            $so->invoice_numbers = $invoiceText;
            $so->waybill_no = trim((string) ($data['waybill_no'] ?? '')) !== '' ? $data['waybill_no'] : $so->waybill_no;
            $so->waybill_date = trim((string) ($data['waybill_date'] ?? '')) !== '' ? $data['waybill_date'] : $so->waybill_date;
            $so->total_amount = $requestTotalAmount;
            $so->remarks = trim((string) ($data['remarks'] ?? '')) !== '' ? $data['remarks'] : $so->remarks;
            $so->created_at = $salesOrderCreatedAt;
            $so->save();

            // The saved invoice snapshot is authoritative for product_ledgers.
            $ledgerSync = app(\App\Services\SalesOrderLedgerReconciliationService::class)
                ->reconcile($so->fresh(['items']));

            // Recalculate the Sales Note status across all invoices from this note.
            $hasRemaining = false;
            $noteItemsForStatus = DB::connection('sales')
                ->table('sales_note_items')
                ->where('sales_note_id', $note->id)
                ->get(['product_id', 'quantity']);
            $allServed = DB::connection('sales')
                ->table('sales_orders as so')
                ->join('sales_order_items as soi', 'soi.sales_order_id', '=', 'so.id')
                ->where('so.sales_note_id', $note->id)
                ->select('soi.product_id', DB::raw('SUM(COALESCE(soi.actual_qty, 0)) as total_served'))
                ->groupBy('soi.product_id')
                ->get()
                ->keyBy('product_id');

            foreach ($noteItemsForStatus as $noteItem) {
                $orderedQty = (float) ($noteItem->quantity ?? 0);
                $servedQty = (float) (($allServed->get($noteItem->product_id)->total_served ?? 0));
                if ($orderedQty > $servedQty) {
                    $hasRemaining = true;
                    break;
                }
            }
            $note->status = $hasRemaining ? 'Partial' : 'Closed';
            $note->save();

            $soAfter = \App\Models\SalesOrder::on('sales')->with('items')->find($so->id);
            $customer = !empty($so->customer_id) ? \App\Models\Customer::on('masterlist')->find($so->customer_id) : null;
            $actor = hatdogAuditActor($user);
            $recordName = trim((string) (($so->customer_name ?? '') !== '' ? $so->customer_name : ('Sales Order ' . ($so->order_number ?? $so->id))));

            hatdogWriteAuditTrail([
                'module' => 'sales_order',
                'action' => 'Updated',
                'source_connection' => 'sales',
                'source_table' => 'sales_orders',
                'source_id' => $so->id,
                'display_id' => (string) ($so->order_number ?? $so->id),
                'record_name' => $recordName,
                'user_name' => $actor['name'],
                'user_identifier' => $actor['identifier'],
                'audit_data' => [
                    'sales_order_before' => $soBefore,
                    'sales_order_after' => $soAfter?->toArray(),
                    'sales_order_items_after' => $soAfter?->items?->map(fn ($item) => $item->toArray())->values()->all() ?? [],
                    'sales_note_before' => $noteBefore,
                    'sales_note_after' => $note->fresh()->toArray(),
                    'customer' => $customer?->toArray(),
                    'invoice_numbers' => $normalizedInvoices->values()->all(),
                    'request_items' => collect($data['items'])->values()->all(),
                    'ledger_sync' => $ledgerSync,
                ],
            ]);

            DB::connection('sales')->commit();
            DB::connection('ledger')->commit();
            DB::connection('masterlist')->commit();

            return response()->json([
                'success' => true,
                'note_status' => $note->status,
                'order_date' => $salesOrderCreatedAt->format('Y-m-d'),
                'ledger_sync' => $ledgerSync,
            ]);
        } catch (\Throwable $error) {
            foreach (['sales', 'ledger', 'masterlist'] as $connection) {
                try {
                    if (DB::connection($connection)->transactionLevel() > 0) {
                        DB::connection($connection)->rollBack();
                    }
                } catch (\Throwable $rollbackError) {
                    \Log::warning('Sales Order edit rollback failed', [
                        'connection' => $connection,
                        'error' => $rollbackError->getMessage(),
                    ]);
                }
            }
            throw $error;
        }
    } catch (\Throwable $e) {
        \Log::error('Sales Order update failed', [
            'sales_order_id' => (int) $salesOrderId,
            'error' => $e->getMessage(),
        ]);
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.sales-order.update');

// Sales Order - Ledger (by sales number)
