// Sales Order - Receipt print
Route::match(['GET', 'POST'], '/admin/sales/sales-order/receipt-print', function (Request $request) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);
    try {
        $req = $request->all();

        // PRINT DATE SOURCE OF TRUTH:
        // Always use the saved Sales Order date (sales_orders.created_at) when the
        // exact Sales Order can be resolved. Never let the parent Sales Note/browser
        // payload overwrite the Sales Order issue date on the printed document.
        $printSalesOrder = null;
        $printSalesOrderId = (int) ($req['sales_order_id'] ?? 0);
        if ($printSalesOrderId > 0) {
            $printSalesOrder = DB::connection('sales')
                ->table('sales_orders')
                ->where('id', $printSalesOrderId)
                ->first(['id', 'order_number', 'invoice_numbers', 'created_at', 'updated_at', 'waybill_date']);
        }

        // Defensive fallback for older browser state: resolve the exact invoice.
        if (!$printSalesOrder) {
            $printInvoiceNumber = trim((string) ($req['invoice_number'] ?? ''));
            $printSalesNumber = trim((string) ($req['sales_number'] ?? ''));
            if ($printInvoiceNumber !== '') {
                $printOrderQuery = DB::connection('sales')
                    ->table('sales_orders')
                    ->where('invoice_numbers', $printInvoiceNumber);
                if ($printSalesNumber !== '') {
                    $printOrderQuery->where('order_number', $printSalesNumber);
                }
                $printSalesOrder = $printOrderQuery
                    ->orderByDesc('id')
                    ->first(['id', 'order_number', 'invoice_numbers', 'created_at', 'updated_at', 'waybill_date']);
            }
        }

        $printDate = trim((string) ($req['date'] ?? ''));
        $resolvePrintDate = static function ($value): string {
            $value = trim((string) $value);
            if ($value === '' || $value === '0000-00-00' || str_starts_with($value, '0000-00-00')) {
                return '';
            }

            try {
                return \Carbon\Carbon::parse($value)->format('Y-m-d');
            } catch (\Throwable $e) {
                return '';
            }
        };

        if ($printSalesOrder) {
            foreach ([$printSalesOrder->created_at ?? null, $printSalesOrder->waybill_date ?? null, $printSalesOrder->updated_at ?? null] as $candidateDate) {
                $resolvedDate = $resolvePrintDate($candidateDate);
                if ($resolvedDate !== '') {
                    $printDate = $resolvedDate;
                    break;
                }
            }
        }
        $printDate = $resolvePrintDate($printDate);

        $items = json_decode($req['items'] ?? '[]', true);
        $printType = $req['print_type'] ?? 'order';
        $items = array_map(function ($item) use ($printType) {
            $quantity = (float)($item['quantity'] ?? 0);
            $actualQty = array_key_exists('actual_qty', $item) ? (float)$item['actual_qty'] : $quantity;
            $additionalQty = (float)($item['additional_qty'] ?? $item['additional_quantity'] ?? 0);
            $item['additional_qty'] = $additionalQty;
            $item['print_quantity'] = $printType === 'invoice' ? $actualQty : $quantity;
            $item['print_quantity_total'] = $item['print_quantity'] + $additionalQty;
            return $item;
        }, is_array($items) ? $items : []);
        if (!empty($items)) {
            $codes = array_unique(array_filter(array_column($items, 'product_code')));
            $productsByCode = [];
            if (!empty($codes)) {
                $productRows = DB::connection('masterlist')->table('products')->whereIn('product_code', $codes)->get(['product_code', 'application', 'position']);
                foreach ($productRows as $p) {
                    $productsByCode[strtoupper(trim($p->product_code))] = $p;
                }
            }
            foreach ($items as &$item) {
                $code = strtoupper(trim($item['product_code'] ?? ''));
                if ($code && isset($productsByCode[$code])) {
                    $p = $productsByCode[$code];
                    $item['application'] = $item['application'] ?? ($p->application ?? '');
                    $item['position'] = $item['position'] ?? ($p->position ?? '');
                }
            }
            unset($item);
        }
        $customerAddress = '';
        $customerTin = '';
        $terms = '';
        $salesMan = '';
        if (!empty($req['customer_id'])) {
            $row = DB::connection('masterlist')->table('customers')->find($req['customer_id']);
            if ($row) {
                $customerAddress = $row->address ?? '';
                $customerTin = $row->tin ?? '';
                $terms = $row->terms ?? '';
            }
        }
        if (!empty($req['sales_number'])) {
            $note = DB::connection('sales')->table('sales_notes')->where('sales_number', $req['sales_number'])->first();
            if ($note) {
                $salesMan = $note->salesman ?? '';
            }
        }
        return view('Admin.sales.receipt-print', [
            'customerName' => $req['customer_name'] ?? '',
            'customerAddress' => $customerAddress,
            'customerTin' => $customerTin,
            'date' => $printDate,
            'salesNumber' => $req['sales_number'] ?? '',
            'terms' => $terms,
            'salesMan' => $salesMan,
            'items' => $items,
            'totalQty' => array_sum(array_column($items, 'print_quantity_total')),
            'grossTotal' => (float)($req['gross_total'] ?? 0),
            'rushText' => $req['rush_text'] ?? '',
            'totalAddlDiscount' => (float)($req['total_addl_discount'] ?? 0),
            'addlDiscountRate' => (float)($req['addl_discount_rate'] ?? 0),
            'netAfterAddl' => (float)($req['net_total'] ?? 0),
            'printType' => $printType,
            'vatRate' => (float)($req['vat_rate'] ?? 12),
            'vatAmount' => (float)($req['vat_amount'] ?? 0),
            'grandTotal' => (float)($req['grand_total'] ?? ($req['net_total'] ?? 0)),
        ]);
    } catch (\Exception $e) {
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.sales-order.receipt-print');

// Online Report - Generate and save
Route::post('/admin/sales/sales-order/report/online-generate', function (Request $request) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

    try {
        $data = $request->input('data', []);
        $noteIds = $data['note_ids'] ?? [];

        if (empty($noteIds)) {
            return response()->json(['success' => false, 'message' => 'No sales notes selected.'], 422);
        }

        $noteIds = array_values($noteIds);
        $prices = $data['prices'] ?? [];

        $report = \App\Models\OnlineReport::create([
            'sales_note_ids' => implode(',', $noteIds),
            'created_by' => is_array($user) ? ($user['name'] ?? $user['username'] ?? 'Unknown') : ($user->name ?? $user->username ?? 'Unknown'),
            'date_ranges' => $data['date_ranges'] ?? [],
            'prices' => $prices,
            'counter_parts' => $data['counter_parts'] ?? [],
            'invoice_numbers' => $data['invoice_numbers'] ?? [],
            'addresses' => $data['addresses'] ?? [],
            'notes_data' => $data['notes'] ?? [],
            'status' => 'generated',
        ]);

        foreach (array_values($noteIds) as $noteIdx => $noteId) {
            $note = \App\Models\SalesNote::on('sales')->find($noteId);
            if (!$note) continue;

            $invoiceNo = $data['invoice_numbers'][(string)$noteIdx] ?? '';
            if ($invoiceNo) {
                $note->remarks = trim(($note->remarks ? $note->remarks . ' | ' : '') . 'Invoice: ' . $invoiceNo);
                $note->save();
            }

            // Get merged items from notes_data (includes both original + added items with quantities)
            $noteData = $data['notes'][$noteIdx] ?? [];
            $mergedItems = $noteData['items'] ?? [];
            $origItemCount = $note->items()->count();
            $hasOrigItems = $origItemCount > 0;

            // Create sales_order
            $orderNumber = 'ONL-' . $report->id . '-' . $noteIdx;
            $existingSO = \Illuminate\Support\Facades\DB::connection('sales')
                ->table('sales_orders')
                ->where('order_number', $orderNumber)
                ->first();

            $totalAmount = 0;
            if (!$existingSO) {
                $salesOrderId = \Illuminate\Support\Facades\DB::connection('sales')
                    ->table('sales_orders')
                    ->insertGetId([
                        'sales_note_id' => $noteId,
                        'order_number' => $orderNumber,
                        'customer_id' => $note->customer_id,
                        'customer_name' => $note->customer_name,
                        'invoice_numbers' => $invoiceNo,
                        'total_amount' => 0,
                        'status' => 'Confirmed',
                        'created_at' => now(),
                        'updated_at' => now(),
                    ]);
            } else {
                $salesOrderId = $existingSO->id;
            }

            foreach ($mergedItems as $item) {
                $pid = (int)($item['product_id'] ?? 0);
                if (!$pid) continue;

                $product = \App\Models\Product::on('masterlist')->find($pid);
                if (!$product) continue;

                // Bonus QTY is additional free quantity: it affects stock movement only.
                // Billable values (quantity, actual_qty, subtotal) exclude Bonus QTY.
                $actualQty = (float) ($item['quantity'] ?? 0);
                $bonusQty = (float) ($item['additional_qty'] ?? 0);
                $totalOut = $actualQty + $bonusQty;
                $oum = trim((string) ($product->unit ?? ''));
                $price = isset($prices[(string)$pid]) ? (float)$prices[(string)$pid] : (float)($product->price_online ?? 0);
                $cost = (float)($product->cost ?? 0);
                $onHand = (int)($product->on_hand ?? 0);
                $newBalance = max(0, $onHand - $totalOut);
                $subtotal = $actualQty * $price;

                // Check stock (stock availability must cover Actual QTY + Bonus QTY)
                if ($onHand < $totalOut) {
                    return response()->json([
                        'success' => false,
                        'message' => 'Cannot proceed. Insufficient stock for ' . ($product->product_code ?? 'ID-' . $pid) . '. Available: ' . $onHand . ', Requested: ' . $totalOut,
                    ], 422);
                }

                // Update product price only (balance_stock is handled by ledger service)
                if (isset($prices[(string)$pid])) {
                    $product->price_online = (float)$prices[(string)$pid];
                }
                $product->save();

                // Insert sales_order_items
                $totalAmount += $subtotal;
                \Illuminate\Support\Facades\DB::connection('sales')
                    ->table('sales_order_items')
                    ->insert([
                        'sales_order_id' => $salesOrderId,
                        'product_id' => $pid,
                    'product_code' => $item['product_code'] ?? ($product ? $product->product_code : ''),
                        'description' => $item['description'] ?? '',
                        'quantity' => $actualQty,
                        'actual_qty' => $actualQty,
                        'additional_qty' => $bonusQty,
                        'oum' => $oum,
                        'unit_price' => $price,
                        'discount' => $item['discount'] ?? 0,
                        'subtotal' => $subtotal,
                        'particulars' => $item['particulars'] ?? '',
                        'created_at' => now(),
                        'updated_at' => now(),
                    ]);

                // Product Ledger rows are synchronized by the explicit pre-print
                // verification endpoint so the loader is visible on every report.
            }

            // Update sales_order total
            \Illuminate\Support\Facades\DB::connection('sales')
                ->table('sales_orders')
                ->where('id', $salesOrderId)
                ->update([
                    'total_amount' => $totalAmount,
                    'updated_at' => now(),
                ]);

            // Close note if it had original items
            if ($hasOrigItems) {
                $note->status = 'Closed';
                $note->save();
            }
        }

        return response()->json([
            'success' => true,
            'online_report_id' => $report->id,
            'report_id' => $report->id,
            'print_url' => route('admin.sales-order.online-print', ['id' => $report->id]),
            'message' => 'Online Report created.',
        ]);
    } catch (\Exception $e) {
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.sales-order.online-generate');

