// Online Report Ledger Sync - Execute Sync
Route::post('/admin/sales/sales-order/report/online-sync/{reportId}', function ($reportId) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

    try {
        $result = \App\Services\OnlineReportProductLedgerSyncService::syncByReportId((int) $reportId);

        // Make sure Product Ledger price matches the Online Invoice Unit Price.
        $items = DB::connection('sales')
            ->table('sales_orders as so')
            ->join('sales_order_items as soi', 'soi.sales_order_id', '=', 'so.id')
            ->where('so.order_number', 'like', 'ONL-' . (int) $reportId . '-%')
            ->get([
                'soi.id',
                'soi.unit_price',
            ]);

        foreach ($items as $item) {
            DB::connection('ledger')
                ->table('product_ledgers')
                ->where('source_type', 'online_report')
                ->where('source_id', (int) $reportId)
                ->where('source_item_id', (int) $item->id)
                ->update([
                    'price' => (float) ($item->unit_price ?? 0),
                    'updated_at' => now(),
                ]);
        }

        return response()->json(array_merge($result, ['success' => true]));
    } catch (\Exception $e) {
        return response()->json([
            'success' => false,
            'message' => $e->getMessage()
        ], 422);
    }
})->name('admin.sales-order.online-sync');
// Online Report - Verify Product Ledger (syncs missing entries, returns can_print status)
Route::post('/admin/sales/sales-order/report/verify-product-ledger/{reportId}', function ($reportId) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);
    try {
        $verifyResult = \App\Services\OnlineReportProductLedgerSyncService::verifyByReportId((int)$reportId);
        $existingBefore = (int) ($verifyResult['existing_entries'] ?? 0);
        $syncResult = [
            'status' => 'already_synced',
            'inserted_entries' => 0,
            'errors' => [],
        ];

        if (!($verifyResult['verified'] ?? false)) {
            $syncResult = \App\Services\OnlineReportProductLedgerSyncService::syncByReportId((int)$reportId);
            $verifyResult = \App\Services\OnlineReportProductLedgerSyncService::verifyByReportId((int)$reportId);
        }

        $canPrint = (bool) ($verifyResult['verified'] ?? false);
        $insertedEntries = (int) ($syncResult['inserted_entries'] ?? 0);
        $missingEntries = (int) ($verifyResult['missing_entries'] ?? 0);
        $status = $canPrint
            ? ($insertedEntries > 0 ? 'synced' : 'already_synced')
            : 'failed';

        $message = $canPrint
            ? ($insertedEntries > 0
                ? 'Online Report successfully inserted into Product Ledger.'
                : 'Online Report is already synchronized with Product Ledger.')
            : 'Online Report was created, but Product Ledger synchronization failed.';

        $payload = [
            'success' => true,
            'can_print' => $canPrint,
            'status' => $status,
            'online_report_id' => (int) $reportId,
            'expected_entries' => (int) ($verifyResult['expected_entries'] ?? 0),
            'existing_entries' => $existingBefore,
            'inserted_entries' => $insertedEntries,
            'missing_entries' => $missingEntries,
            'duplicate_entries' => (int) ($verifyResult['duplicate_entries'] ?? 0),
            'print_url' => route('admin.sales-order.online-print', ['id' => (int) $reportId]),
            'message' => $message,
            'verified' => $canPrint,
            'total_items' => $verifyResult['total_items'] ?? 0,
            'synced_items' => $verifyResult['synced_items'] ?? 0,
            'missing_items' => $verifyResult['missing_items'] ?? [],
            'errors' => $syncResult['errors'] ?? [],
        ];

        return response()->json($payload, $canPrint ? 200 : 422);
    } catch (\Exception $e) {
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.sales-order.online-verify-product-ledger');

// Online Invoices - List
Route::get('/admin/sales/sales-order/online-invoices', function () {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);
    try {
        $reports = \App\Models\OnlineReport::on('sales')
            ->orderBy('created_at', 'desc')
            ->get()
            ->map(function ($report) {
                $noteIds = explode(',', $report->sales_note_ids);
                $notes = \App\Models\SalesNote::on('sales')
                    ->whereIn('id', $noteIds)
                    ->get(['id', 'sales_number', 'customer_name', 'net_total']);
                $invoiceNumbers = $report->invoice_numbers ?? [];
                $invoiceDisplay = is_array($invoiceNumbers) ? implode(', ', array_filter(array_values($invoiceNumbers))) : (string)$invoiceNumbers;
                $totalItems = 0;
                $totalAmount = 0;
                $notesData = $report->notes_data ?? [];
                foreach ($notes as $note) {
                    $totalItems += $note->items()->count();
                    $totalAmount += (float)$note->net_total;
                }
                foreach ($notesData as $nd) {
                    if (isset($nd['items'])) {
                        $_ndItems = is_string($nd['items']) ? (json_decode($nd['items'], true) ?? []) : $nd['items'];
                        $totalItems += count($_ndItems);
                        foreach ($_ndItems as $item) {
                            $totalAmount += (float)($item['subtotal'] ?? 0);
                        }
                    }
                }
                return [
                    'id' => $report->id,
                    'created_at' => $report->created_at ? date('Y-m-d h:i A', strtotime($report->created_at)) : '',
                    'created_by' => $report->created_by ?? '---',
                    'invoice_display' => $invoiceDisplay ?: '---',
                    'sales_notes' => $notes->pluck('sales_number')->join(', '),
                    'customers' => $notes->pluck('customer_name')->unique()->join(', '),
                    'total_items' => $totalItems,
                    'total_amount' => $totalAmount,
                ];
            });
        return response()->json(['success' => true, 'reports' => $reports]);
    } catch (\Exception $e) {
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.sales-order.online-invoices');

// Online Invoices - server-side paginated
Route::get('/admin/sales/sales-order/online-invoices-data', function (Request $request) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);
    try {
        $perPage = in_array((int)$request->query('perPage', 50), [25, 50, 100]) ? (int)$request->query('perPage', 50) : 50;
        $page = max(1, (int)$request->query('page', 1));
        $search = trim($request->query('search', ''));
        $query = \App\Models\OnlineReport::on('sales');
        if ($search !== '') {
            $query->where(function ($q) use ($search) {
                $q->where('created_by', 'like', "%{$search}%")
                  ->orWhere('status', 'like', "%{$search}%")
                  ->orWhereRaw('JSON_SEARCH(invoice_numbers, \'one\', ?) IS NOT NULL', ["%{$search}%"])
                  ->orWhereExists(function ($sub) use ($search) {
                      $sub->select(\Illuminate\Support\Facades\DB::raw(1))
                          ->from('sales_notes')
                          ->whereRaw('FIND_IN_SET(sales_notes.id, online_reports.sales_note_ids) > 0')
                          ->where(function ($inner) use ($search) {
                              $inner->where('sales_notes.customer_name', 'like', "%{$search}%")
                                    ->orWhere('sales_notes.sales_number', 'like', "%{$search}%");
                          });
                  });
            });
        }

        $total = $query->count();
        $reportRows = $query->orderBy('created_at', 'desc')
            ->skip(($page - 1) * $perPage)
            ->take($perPage)
            ->get();

        // Online Invoices must use the finalized Sales Order totals — the same
        // source used by Sales History. online_reports.notes_data can contain
        // the pre-generation price/subtotal and becomes stale after online prices
        // are applied while the Sales Order is generated.
        $reportIds = $reportRows->pluck('id')
            ->map(fn ($id) => (int) $id)
            ->filter()
            ->unique()
            ->values();

        $reportSalesOrderTotals = collect();
        if ($reportIds->isNotEmpty()) {
            $linkedOrderQuery = DB::connection('sales')->table('sales_orders')
                ->select(['order_number', 'total_amount'])
                ->where(function ($q) use ($reportIds) {
                    foreach ($reportIds as $reportId) {
                        $q->orWhere('order_number', 'like', 'ONL-' . $reportId . '-%');
                    }
                });

            foreach ($linkedOrderQuery->get() as $linkedOrder) {
                if (preg_match('/^ONL-(\d+)-/i', (string) $linkedOrder->order_number, $match)) {
                    $reportId = (int) $match[1];
                    $reportSalesOrderTotals->put(
                        $reportId,
                        (float) $reportSalesOrderTotals->get($reportId, 0) + (float) ($linkedOrder->total_amount ?? 0)
                    );
                }
            }
        }

        // Fallback for older/migrated reports whose order_number does not use ONL-{id}-*.
        $allInvoiceNumbers = $reportRows
            ->flatMap(function ($report) {
                $invoiceNumbers = $report->invoice_numbers ?? [];
                return is_array($invoiceNumbers) ? $invoiceNumbers : [$invoiceNumbers];
            })
            ->map(fn ($invoice) => trim((string) $invoice))
            ->filter(fn ($invoice) => $invoice !== '')
            ->unique()
            ->values();

        $invoiceSalesOrderTotals = collect();
        if ($allInvoiceNumbers->isNotEmpty()) {
            $linkedInvoices = DB::connection('sales')->table('sales_orders')
                ->whereIn('invoice_numbers', $allInvoiceNumbers->all())
                ->get(['id', 'invoice_numbers', 'total_amount']);

            foreach ($linkedInvoices as $linkedInvoice) {
                $invoiceNo = trim((string) ($linkedInvoice->invoice_numbers ?? ''));
                if ($invoiceNo === '') continue;
                $invoiceSalesOrderTotals->put(
                    $invoiceNo,
                    (float) $invoiceSalesOrderTotals->get($invoiceNo, 0) + (float) ($linkedInvoice->total_amount ?? 0)
                );
            }
        }

        $reports = $reportRows->map(function ($report) use ($reportSalesOrderTotals, $invoiceSalesOrderTotals) {
            $noteIds = array_filter(array_map('trim', explode(',', (string) $report->sales_note_ids)));
            $notes = \App\Models\SalesNote::on('sales')
                ->whereIn('id', $noteIds)
                ->get(['id', 'sales_number', 'customer_name', 'net_total']);

            $invoiceNumbers = $report->invoice_numbers ?? [];
            $invoiceNumbers = is_array($invoiceNumbers) ? $invoiceNumbers : [$invoiceNumbers];
            $invoiceNumbers = collect($invoiceNumbers)
                ->map(fn ($invoice) => trim((string) $invoice))
                ->filter(fn ($invoice) => $invoice !== '')
                ->unique()
                ->values();
            $invoiceDisplay = $invoiceNumbers->join(', ');

            $totalItems = 0;
            $fallbackTotalAmount = 0.0;
            $notesData = $report->notes_data ?? [];
            if (!is_array($notesData)) $notesData = [];

            foreach ($notesData as $nd) {
                if (!isset($nd['items'])) continue;
                $_ndItems = is_string($nd['items']) ? (json_decode($nd['items'], true) ?? []) : $nd['items'];
                $totalItems += count($_ndItems);
                foreach ($_ndItems as $item) {
                    $fallbackTotalAmount += (float) ($item['subtotal'] ?? 0);
                }
            }

            foreach ($notes as $note) {
                if (empty($notesData)) {
                    $totalItems += $note->items()->count();
                }
                $fallbackTotalAmount += (float) $note->net_total;
            }

            if ($reportSalesOrderTotals->has((int) $report->id)) {
                $totalAmount = (float) $reportSalesOrderTotals->get((int) $report->id);
            } else {
                $invoiceBasedTotal = 0.0;
                $hasInvoiceSalesOrder = false;
                foreach ($invoiceNumbers as $invoiceNo) {
                    if ($invoiceSalesOrderTotals->has($invoiceNo)) {
                        $hasInvoiceSalesOrder = true;
                        $invoiceBasedTotal += (float) $invoiceSalesOrderTotals->get($invoiceNo);
                    }
                }
                $totalAmount = $hasInvoiceSalesOrder ? $invoiceBasedTotal : $fallbackTotalAmount;
            }

            return [
                'id' => $report->id,
                'created_at' => $report->created_at ? date('Y-m-d h:i A', strtotime($report->created_at)) : '',
                'created_by' => $report->created_by ?? '---',
                'invoice_display' => $invoiceDisplay ?: '---',
                'sales_notes' => $notes->pluck('sales_number')->join(', '),
                'customers' => $notes->pluck('customer_name')->unique()->join(', '),
                'total_items' => $totalItems,
                'total_amount' => $totalAmount,
            ];
        });

        return response()->json([
            'success' => true, 'reports' => $reports,
            'total' => $total, 'per_page' => $perPage,
            'current_page' => $page, 'last_page' => max(1, (int)ceil($total / $perPage)),
        ]);
    } catch (\Exception $e) {
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.sales-order.online-invoices-data');


// Online Report - Edit fetch
Route::get('/admin/sales/sales-order/report/online-edit/{id}', function ($id) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);
    try {
        $report = \App\Models\OnlineReport::on('sales')->find($id);
        if (!$report) {
            return response()->json(['success' => false, 'message' => 'Online invoice not found.'], 404);
        }

        $noteIds = array_values(array_filter(array_map('trim', explode(',', (string) $report->sales_note_ids))));
        $notesById = \App\Models\SalesNote::on('sales')
            ->whereIn('id', $noteIds)
            ->get(['id', 'sales_number', 'customer_name', 'net_total'])
            ->keyBy(fn ($note) => (string) $note->id);

        $invoiceNumbers = $report->invoice_numbers ?? [];
        $addresses = $report->addresses ?? [];
        $dateRanges = $report->date_ranges ?? [];
        $prices = $report->prices ?? [];
        $counterParts = $report->counter_parts ?? [];
        $notesData = $report->notes_data ?? [];

        // Use the exact same unit-price precedence as the online print route.
        $allProductIds = collect($notesData)
            ->flatMap(function ($noteData) {
                $items = $noteData['items'] ?? [];
                if (is_string($items)) $items = json_decode($items, true) ?? [];
                return collect($items)->pluck('product_id');
            })
            ->map(fn ($id) => (int) $id)
            ->filter(fn ($id) => $id > 0)
            ->unique()
            ->values();
        $productsById = \App\Models\Product::on('masterlist')
        ->whereIn('id', $allProductIds)
        ->get(['id', 'price_online', 'selling_price', 'unit'])
        ->keyBy('id');

        $notesResponse = [];
        foreach ($noteIds as $noteIdx => $noteId) {
            $note = $notesById->get((string) $noteId);
            if (!$note) continue;

            $noteData = $notesData[$noteIdx] ?? [];
            $items = $noteData['items'] ?? [];
            if (is_string($items)) $items = json_decode($items, true) ?? [];

            $items = collect($items)->values()->map(function ($item) use ($prices, $productsById, $noteIdx) {
                $item = is_array($item) ? $item : (array) $item;
                $productId = (int) ($item['product_id'] ?? 0);
                $product = $productsById->get($productId);

                $resolvedPrice = 0.0;
                if ($productId > 0 && isset($prices[(string) $productId]) && (float) $prices[(string) $productId] > 0) {
                    $resolvedPrice = (float) $prices[(string) $productId];
                }
                if ($resolvedPrice <= 0 && !empty($item['id'])) {
                    $itemPriceKey = $noteIdx . '-' . $item['id'];
                    if (isset($prices[$itemPriceKey]) && (float) $prices[$itemPriceKey] > 0) {
                        $resolvedPrice = (float) $prices[$itemPriceKey];
                    }
                }
                if ($resolvedPrice <= 0 && $product && (float) ($product->price_online ?? 0) > 0) {
                    $resolvedPrice = (float) $product->price_online;
                }
                if ($resolvedPrice <= 0 && (float) ($item['unit_price'] ?? 0) > 0) {
                    $resolvedPrice = (float) $item['unit_price'];
                }
                if ($resolvedPrice <= 0 && $product && (float) ($product->selling_price ?? 0) > 0) {
                    $resolvedPrice = (float) $product->selling_price;
                }

                $item['resolved_unit_price'] = $resolvedPrice;
                $item['oum'] = trim((string) ($product->unit ?? ''));

            return $item;
            })->all();

            $notesResponse[] = [
                'id' => $note->id,
                'sales_number' => $note->sales_number,
                'customer_name' => $note->customer_name,
                'net_total' => (float) ($note->net_total ?? 0),
                'invoice_no' => (string)($invoiceNumbers[(string)$noteIdx] ?? ''),
                'address' => (string)($addresses[(string)$noteIdx] ?? ''),
                'items' => $items,
            ];
        }

        return response()->json([
            'success' => true,
            'report' => [
                'id' => $report->id,
                'sales_note_ids' => $report->sales_note_ids,
                'created_by' => $report->created_by,
                'status' => $report->status,
                'created_at' => $report->created_at,
            ],
            'notes' => $notesResponse,
            'date_ranges' => $dateRanges,
            'prices' => $prices,
            'counter_parts' => $counterParts,
        ]);
    } catch (\Exception $e) {
        return response()->json(['success' => false, 'message' => $e->getMessage()], 500);
    }
})->name('admin.sales-order.online-edit');

// Online Report - Update
Route::put('/admin/sales/sales-order/report/online-update/{id}', function (Request $request, $id) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);
    try {
        $report = \App\Models\OnlineReport::on('sales')->find($id);
        if (!$report) {
            return response()->json(['success' => false, 'message' => 'Online invoice not found.'], 404);
        }

        $data = $request->input('data', []);
        $noteIds = $data['note_ids'] ?? [];
        if (empty($noteIds)) {
            return response()->json(['success' => false, 'message' => 'No sales notes selected.'], 422);
        }

        $prices = $data['prices'] ?? [];
        $invoiceNumbers = $data['invoice_numbers'] ?? [];
        $addresses = $data['addresses'] ?? [];
        $dateRanges = $data['date_ranges'] ?? [];
        $counterParts = $data['counter_parts'] ?? [];
        $notesData = $data['notes'] ?? [];
        $itemsQty = $data['items_qty'] ?? [];
        $itemsUnit = $data['items_unit'] ?? [];

        // --- Update Online Invoice snapshot, then reconcile Sales Order + Product Ledger rows ---
        $report->update([
            'date_ranges' => $dateRanges,
            'prices' => $prices,
            'counter_parts' => $counterParts,
            'invoice_numbers' => $invoiceNumbers,
            'addresses' => $addresses,
            'notes_data' => $notesData,
        ]);

        // The edited snapshot is authoritative:
        // - retained items update their existing ledger OUT row
        // - added items create a new Sales Order Item + ledger OUT row
        // - removed items delete their Sales Order Item + matching ledger OUT row
        // - every affected balance_stock is rebuilt chronologically
        $ledgerEditResult = \App\Services\OnlineReportProductLedgerSyncService::reconcileEditedReport(
            (int) $report->id
        );

        \Illuminate\Support\Facades\Log::info(
            "Online Invoice #{$id} update completed: " .
            (int) ($ledgerEditResult['product_ledgers_updated'] ?? 0) .
            " Product Ledger row(s) updated, " .
            (int) ($ledgerEditResult['product_ledgers_created'] ?? 0) .
            " created, " .
            (int) ($ledgerEditResult['product_ledgers_deleted'] ?? 0) .
            " deleted."
        );

        return response()->json([
            'success' => true,
            'message' => 'Online Invoice updated successfully.',
            'ledger_sync' => $ledgerEditResult,
        ]);
    } catch (\Exception $e) {
        \Illuminate\Support\Facades\Log::error("Online Invoice #{$id} update error: " . $e->getMessage());
        return response()->json(['success' => false, 'message' => 'Unable to update the Online Invoice.'], 500);
    }
})->name('admin.sales-order.online-update');

// Online Report - Destroy
Route::delete('/admin/sales/sales-order/report/online-destroy/{id}', function ($id) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);
    try {
        $report = \App\Models\OnlineReport::on('sales')->find($id);
        if (!$report) {
            return response()->json(['success' => false, 'message' => 'The selected Online Invoice no longer exists.'], 404);
        }

        $noteIds = array_filter(array_map('trim', explode(',', $report->sales_note_ids)));
        $noteRecords = \App\Models\SalesNote::on('sales')
            ->whereIn('id', $noteIds)
            ->get(['id', 'sales_number']);
        $salesNumbers = $noteRecords->pluck('sales_number')->filter()->values()->toArray();

        // Collect old product IDs for stock recalculation
        $oldProductIds = [];
        $notesData = $report->notes_data ?? [];
        foreach ($notesData as $nd) {
            $ndItems = $nd['items'] ?? [];
            if (is_string($ndItems)) $ndItems = json_decode($ndItems, true) ?? [];
            foreach ($ndItems as $item) {
                $pid = (int)($item['product_id'] ?? 0);
                if ($pid) $oldProductIds[$pid] = true;
            }
        }

        // --- Identify related ledger rows ---
        $ledgerRows = collect();
        if (!empty($salesNumbers)) {
            $ledgerRows = \App\Models\ProductLedger::where('remarks', 'Online Report Generation')
                ->whereIn('transaction_number', $salesNumbers)
                ->get();
        }

        $totalExpectedItems = 0;
        foreach ($notesData as $nd) {
            $ndItems = $nd['items'] ?? [];
            if (is_string($ndItems)) $ndItems = json_decode($ndItems, true) ?? [];
            $totalExpectedItems += count($ndItems);
        }

        $totalLedgerRows = $ledgerRows->count();

        \Illuminate\Support\Facades\Log::info("Online Invoice #{$id} delete: {$totalLedgerRows} ledger rows found, {$totalExpectedItems} expected items from notes_data.");

        // Safety: if there ARE sales numbers but the ledger query returned 0 while notes_data has items, log a warning
        if (!empty($salesNumbers) && $totalLedgerRows === 0 && $totalExpectedItems > 0) {
            \Illuminate\Support\Facades\Log::warning("Online Invoice #{$id} delete: No ledger rows found for sales numbers: " . implode(',', $salesNumbers) . " but notes_data has {$totalExpectedItems} items.");
        }

        // --- Delete ledger rows ---
        if ($ledgerRows->isNotEmpty()) {
            \App\Models\ProductLedger::where('remarks', 'Online Report Generation')
                ->whereIn('transaction_number', $salesNumbers)
                ->delete();
            \Illuminate\Support\Facades\Log::info("Online Invoice #{$id} delete: Deleted {$totalLedgerRows} ledger rows.");
        }

        // --- Recalculate stock for affected products ---
        $affectedProductIds = array_keys($oldProductIds);
        if (!empty($affectedProductIds)) {
            \App\Services\ProductStockSyncService::syncProducts($affectedProductIds);
            \Illuminate\Support\Facades\Log::info("Online Invoice #{$id} delete: Stock synced for " . count($affectedProductIds) . " products.");
        }

        // --- Delete the report ---
        $report->delete();

        return response()->json(['success' => true, 'message' => 'Online Invoice deleted successfully.']);
    } catch (\Exception $e) {
        \Illuminate\Support\Facades\Log::error("Online Invoice #{$id} delete error: " . $e->getMessage());
        return response()->json(['success' => false, 'message' => 'Unable to delete the Online Invoice.'], 500);
    }
})->name('admin.sales-order.online-destroy');

