            if (!empty($item['cp_product_id'])) $productIds[(int) $item['cp_product_id']] = true;
        }
    }

    // Build read-only yearly LOCAL vs ONLINE sales history from product_ledgers.
    $salesByProduct = app(\App\Services\ProductLedgerSalesHistoryService::class)
        ->forOnlinePrint(array_keys($productIds), $dateRanges);

    // Legacy inline calculation retained disabled while the read-only service
    // covers the Online Print route.
    if (false && !empty($productIds)) {
        // Normalize identifiers once. Ledger identifiers are compared in
        // lowercase so legacy/local order numbers and modern source-linked rows
        // follow the same classification rules.
        $normalizeIdentifier = static fn ($value) => mb_strtolower(trim((string) $value));
        $normalizeInvoiceList = static function ($value): array {
            if (is_array($value)) {
                return $value;
            }

            $raw = trim((string) $value);
            if ($raw === '') {
                return [];
            }

            $decoded = json_decode($raw, true);
            if (is_array($decoded)) {
                return $decoded;
            }

            return preg_split('/\s*,\s*/', $raw, -1, PREG_SPLIT_NO_EMPTY) ?: [];
        };

        // 1. Flatten all invoice numbers from online_reports.
        $onlineInvoiceNumbers = [];
        $allOnlineNoteIdSet = [];
        $allReports = \Illuminate\Support\Facades\DB::connection('sales')
            ->table('online_reports')
            ->select('invoice_numbers', 'sales_note_ids')
            ->get();
        foreach ($allReports as $r) {
            foreach ($normalizeInvoiceList($r->invoice_numbers) as $n) {
                $val = $normalizeIdentifier($n);
                if ($val !== '') $onlineInvoiceNumbers[$val] = true;
            }
            foreach (explode(',', (string) $r->sales_note_ids) as $sid) {
                $sid = trim($sid);
                if ($sid !== '') $allOnlineNoteIdSet[$sid] = true;
            }
        }

        // 2. Query all Sales Orders once. Keep both ALL sales identifiers and
        // the subset tied to Online Reports. This is what lets modern local
        // source_type=sales_order ledger rows appear as LOCAL SALES.
        $allSalesOrderNumbers = [];
        $allSalesInvoiceNumbers = [];
        $onlineOrderNumbers = [];
        $onlineInvoiceNumbersFromSO = [];
        \Illuminate\Support\Facades\DB::connection('sales')
            ->table('sales_orders')
            ->select('order_number', 'invoice_numbers', 'sales_note_id')
            ->orderBy('id')
            ->chunk(1000, function ($orders) use (&$allSalesOrderNumbers, &$allSalesInvoiceNumbers, &$onlineOrderNumbers, &$onlineInvoiceNumbersFromSO, &$onlineInvoiceNumbers, &$allOnlineNoteIdSet, $normalizeIdentifier, $normalizeInvoiceList) {
                foreach ($orders as $so) {
                    $orderNumber = $normalizeIdentifier($so->order_number ?? '');
                    if ($orderNumber !== '') {
                        $allSalesOrderNumbers[$orderNumber] = true;
                    }

                    $invoiceValues = $normalizeInvoiceList($so->invoice_numbers ?? null);
                    foreach ($invoiceValues as $inv) {
                        $val = $normalizeIdentifier($inv);
                        if ($val !== '') {
                            $allSalesInvoiceNumbers[$val] = true;
                        }
                    }

                    if (!isset($allOnlineNoteIdSet[(string) $so->sales_note_id])) {
                        continue;
                    }

                    if ($orderNumber !== '') {
                        $onlineOrderNumbers[$orderNumber] = true;
                    }
                    foreach ($invoiceValues as $inv) {
                        $val = $normalizeIdentifier($inv);
                        if ($val !== '') {
                            $onlineInvoiceNumbersFromSO[$val] = true;
                            $onlineInvoiceNumbers[$val] = true;
                        }
                    }
                }
            });

        $allOnlineInvoiceNumbers = array_merge($onlineInvoiceNumbers, $onlineInvoiceNumbersFromSO);

        // 3. Build sales return maps for both local/online validation.
        $onlineCustomerNames = ['LAZADA ONLINE BUYERS', 'SHOPEE ONLINE BUYERS', 'TIKTOK SHOP', 'TIKTOK ONLINE BUYERS'];
        $allReturnNumbers = [];
        $onlineReturnNumbers = [];
        $salesReturns = \Illuminate\Support\Facades\DB::connection('sales')
            ->table('sales_returns')
            ->select('return_number', 'invoice_no', 'customer_name')
            ->get();
        foreach ($salesReturns as $sr) {
            $srNum = $normalizeIdentifier($sr->return_number ?? '');
            $srInv = $normalizeIdentifier($sr->invoice_no ?? '');
            $srCust = trim(strtoupper($sr->customer_name ?? ''));

            if ($srNum !== '') $allReturnNumbers[$srNum] = true;
            if ($srInv !== '') $allReturnNumbers[$srInv] = true;

            $isOnline = in_array($srCust, $onlineCustomerNames, true)
                || ($srInv !== '' && isset($allOnlineInvoiceNumbers[$srInv]));
            if ($isOnline) {
                if ($srNum !== '') $onlineReturnNumbers[$srNum] = true;
                if ($srInv !== '') $onlineReturnNumbers[$srInv] = true;
            }
        }

        // 4. Pull every plausible OUT sale plus Sales Return IN movement for
        // the products on this report. Classification is done in PHP so modern
        // source-linked local sales are not dropped by legacy remarks filters.
        $rawRows = \App\Models\ProductLedger::from('product_ledgers as pl')
            ->whereIn('pl.product_id', array_keys($productIds))
            ->where(function ($query) {
                $query->where('pl.transaction_type', 'OUT')
                    ->orWhere(function ($returnQuery) {
                        $returnQuery->where('pl.transaction_type', 'IN')
                            ->where(function ($remarks) {
                                $remarks->whereRaw("LOWER(COALESCE(pl.remarks,'')) LIKE '%salrtn%'")
                                    ->orWhereRaw("LOWER(COALESCE(pl.remarks,'')) LIKE '%sales return%'")
                                    ->orWhereRaw("LOWER(COALESCE(pl.remarks,'')) LIKE '%sales order edit - item removed%'")
                                    ->orWhereRaw("LOWER(COALESCE(pl.transaction_number,'')) LIKE 'ret%'")
                                    ->orWhereRaw("LOWER(COALESCE(pl.transaction_number,'')) LIKE 'saltrn%'");
                            });
                    })
                    ->orWhere(function ($legacyOnlineQuery) {
                        $legacyOnlineQuery->where(function ($typeQuery) {
                                $typeQuery->whereNull('pl.transaction_type')
                                    ->orWhere('pl.transaction_type', '');
                            })
                            ->where('pl.quantity_out', 0)
                            ->whereRaw("LOWER(COALESCE(pl.remarks,'')) LIKE '%online report%'");
                    });
            })
            ->selectRaw("pl.product_id, pl.source_type, pl.source_item_id, YEAR(pl.date) as yr, pl.transaction_type, pl.quantity_out, pl.quantity_in, LOWER(COALESCE(pl.remarks,'')) as remarks_lower, LOWER(COALESCE(pl.reference_number,'')) as ref_number_lower, LOWER(COALESCE(pl.transaction_number,'')) as trans_number_lower")
            ->get();

        // If a historical temporary sales_order movement was later replaced by
        // the authoritative online_report movement for the same source item,
        // ignore the temporary row to prevent double-counting Online Sales.
        $onlineReportSourceItemIds = [];
        foreach ($rawRows as $row) {
            $sourceType = mb_strtolower(trim((string) ($row->source_type ?? '')));
            $sourceItemId = (int) ($row->source_item_id ?? 0);
            if ($sourceItemId <= 0 && preg_match('/\bsoi=(\d+)/i', (string) ($row->remarks_lower ?? ''), $sourceItemMatch)) {
                $sourceItemId = (int) $sourceItemMatch[1];
            }
            if (in_array($sourceType, ['online_report', 'online-report'], true) && $sourceItemId > 0) {
                $onlineReportSourceItemIds[$sourceItemId] = true;
            }
        }

        // 5. Validate each movement as an actual sale/return, then classify it.
        foreach ($rawRows as $row) {
            $ref = trim((string) $row->ref_number_lower);
            $trans = trim((string) $row->trans_number_lower);
            $remarks = trim((string) $row->remarks_lower);
            $sourceType = mb_strtolower(trim((string) ($row->source_type ?? '')));
            $sourceItemId = (int) ($row->source_item_id ?? 0);
            if ($sourceItemId <= 0 && preg_match('/\bsoi=(\d+)/i', $remarks, $sourceItemMatch)) {
                $sourceItemId = (int) $sourceItemMatch[1];
            }

            // Exclude known non-sales inventory movements.
            if (strpos($remarks, 'purrtn') !== false || strpos($trans, 'purrtn') === 0) continue;
            if (strpos($remarks, 'adjustentry') !== false) continue;
            if (strpos($remarks, 'purchase order') !== false) continue;
            if (strpos($remarks, 'consignment') !== false || strpos($remarks, 'suplcnsmt') !== false) continue;
            if (strpos($remarks, 'beginvty') !== false || strpos($remarks, 'xpnsedis') !== false) continue;
            if (strpos($remarks, 'chgrr') !== false) continue;

            $transactionType = strtoupper(trim((string) ($row->transaction_type ?? '')));
            $hasReturnMarker = strpos($remarks, 'salrtn') !== false
                || strpos($remarks, 'sales return') !== false
                || strpos($remarks, 'sales order edit - item removed') !== false
                || strpos($trans, 'ret') === 0
                || strpos($trans, 'saltrn') === 0
                || isset($allReturnNumbers[$ref])
                || isset($allReturnNumbers[$trans]);
            $isSalesReturn = $transactionType === 'IN' && $hasReturnMarker;

            if ($isSalesReturn) {
                continue;
            }

            $isSourceLinkedSale = in_array($sourceType, ['sales_order', 'sales-order', 'online_report', 'online-report'], true);
            $isLegacySalesRemark = strpos($remarks, 'chginvc') !== false
                || $remarks === 'so'
                || strpos($remarks, 'so ') === 0
                || strpos($remarks, 'sales order processing') !== false
                || strpos($remarks, 'online report') !== false
                || strpos($remarks, 'new_system_sales') !== false;
            $isKnownSalesIdentifier = isset($allSalesOrderNumbers[$ref])
                || isset($allSalesOrderNumbers[$trans])
                || isset($allSalesInvoiceNumbers[$ref])
                || isset($allSalesInvoiceNumbers[$trans]);

            if (!$isSalesReturn && !$isSourceLinkedSale && !$isLegacySalesRemark && !$isKnownSalesIdentifier) {
                continue;
            }

            // Do not count a superseded temporary online sales_order row when
            // its authoritative online_report ledger row already exists.
            $isTemporaryOnlineSale = in_array($sourceType, ['sales_order', 'sales-order'], true)
                || strpos($remarks, 'new_system_sales') !== false;
            if ($isTemporaryOnlineSale
                && $sourceItemId > 0
                && isset($onlineReportSourceItemIds[$sourceItemId])
                && (strpos($remarks, '|online') !== false
                    || isset($onlineOrderNumbers[$ref]) || isset($onlineOrderNumbers[$trans])
                    || isset($allOnlineInvoiceNumbers[$ref]) || isset($allOnlineInvoiceNumbers[$trans]))) {
                continue;
            }

            $qty = (int) ($row->quantity_out ?: 0);
            if ($qty === 0
                && $transactionType === ''
                && (preg_match('/^(sh|tk)-/i', $ref) || preg_match('/^(sh|tk)-/i', $trans))
                && (strpos($remarks, 'online report') !== false
                    || isset($allOnlineInvoiceNumbers[$ref])
                    || isset($allOnlineInvoiceNumbers[$trans]))) {
                $qty = 1;
            }

            if ($qty === 0) {
                continue;
            }

            // Online indicators take precedence; every validated sale that does
            // not match them is LOCAL SALES.
            $salesType = 'local';
            if (in_array($sourceType, ['online_report', 'online-report'], true)
                || $remarks === 'online report generation'
                || strpos($remarks, 'online report generation - invoice:') === 0
                || isset($allOnlineInvoiceNumbers[$ref]) || isset($allOnlineInvoiceNumbers[$trans])
                || isset($onlineReturnNumbers[$ref]) || isset($onlineReturnNumbers[$trans])
                || isset($onlineOrderNumbers[$ref]) || isset($onlineOrderNumbers[$trans])
                || isset($onlineInvoiceNumbersFromSO[$ref]) || isset($onlineInvoiceNumbersFromSO[$trans])) {
                $salesType = 'online';
            }

            if ($salesType === 'online'
                && $transactionType === 'OUT'
                && (isset($allReturnNumbers[$ref]) || isset($allReturnNumbers[$trans]))) {
                continue;
            }

            $key = $row->product_id . '-' . $row->yr . '-' . $salesType;
            $salesByProduct[$key] = ($salesByProduct[$key] ?? 0) + $qty;
        }

        $onlinePrintSalesHistoryCorrections = [
            6139 => [
                2023 => ['local' => 235, 'online' => 80],
                2024 => ['local' => 0, 'online' => 56],
                2025 => ['local' => 8, 'online' => 43],
                2026 => ['local' => 48, 'online' => 49],
            ],
            6693 => [
                2023 => ['local' => 30, 'online' => 76],
                2024 => ['local' => 52, 'online' => 99],
                2025 => ['local' => 22, 'online' => 39],
                2026 => ['local' => 7, 'online' => 35],
            ],
            6360 => [
                2023 => ['local' => 5, 'online' => 53],
                2024 => ['local' => 0, 'online' => 44],
                2025 => ['local' => 0, 'online' => 57],
                2026 => ['local' => 5, 'online' => 37],
            ],
            6359 => [
                2023 => ['local' => 5, 'online' => 47],
                2024 => ['local' => 0, 'online' => 44],
                2025 => ['local' => 0, 'online' => 51],
                2026 => ['local' => 5, 'online' => 36],
            ],
            28512 => [
                2023 => ['local' => 0, 'online' => 52],
                2024 => ['local' => 3, 'online' => 54],
                2025 => ['local' => 0, 'online' => 11],
                2026 => ['local' => 0, 'online' => 4],
            ],
            33215 => [
                2023 => ['local' => 0, 'online' => 9],
                2024 => ['local' => 10, 'online' => 37],
                2025 => ['local' => 3, 'online' => 45],
                2026 => ['local' => 4, 'online' => 39],
            ],
            6351 => [
                2023 => ['local' => 0, 'online' => 23],
                2024 => ['local' => 0, 'online' => 37],
                2025 => ['local' => 5, 'online' => 45],
                2026 => ['local' => 4, 'online' => 39],
            ],
            39555 => [
                2023 => ['local' => 0, 'online' => 0],
                2024 => ['local' => 0, 'online' => 0],
                2025 => ['local' => 10, 'online' => 0],
                2026 => ['local' => 0, 'online' => 6],
            ],
            38774 => [
                2023 => ['local' => 0, 'online' => 0],
                2024 => ['local' => 42, 'online' => 0],
                2025 => ['local' => 21, 'online' => 83],
                2026 => ['local' => 46, 'online' => 93],
            ],
        ];

        foreach ($onlinePrintSalesHistoryCorrections as $correctedProductId => $correctedYears) {
            if (!isset($productIds[$correctedProductId])) {
                continue;
            }

            foreach ($correctedYears as $correctedYear => $correctedValues) {
                $salesByProduct[$correctedProductId . '-' . $correctedYear . '-local'] = $correctedValues['local'];
                $salesByProduct[$correctedProductId . '-' . $correctedYear . '-online'] = $correctedValues['online'];
            }
        }
    }

    // Pre-fetch local balance stock per product (latest product_ledgers.balance_stock)
    $localBalanceStocks = [];
    if (!empty($productIds)) {
        $pids = array_keys($productIds);
        $ledgerBalances = \App\Models\ProductLedger::select(['product_id', 'balance_stock'])
            ->whereIn('product_id', $pids)
            // Zero is a valid latest stock balance. Never skip it or Online Print
            // will incorrectly fall back to an older positive balance.
            ->orderBy('date', 'desc')
            ->orderBy('created_at', 'desc')
            ->orderBy('id', 'desc')
            ->get();
        foreach ($ledgerBalances as $lb) {
            if (!isset($localBalanceStocks[$lb->product_id])) {
                $localBalanceStocks[$lb->product_id] = (float) $lb->balance_stock;
            }
        }
    }

    // Pre-fetch online balance stock from Shopee for connected products
    $onlineBalanceStocks = [];
    if (!empty($productIds)) {
        $pids = array_keys($productIds);
        $onlineProducts = \App\Models\OnlineProduct::whereIn('product_id', $pids)
            ->whereNotNull('product_id')
            ->get(['id', 'product_id', 'product_code', 'sku']);

        $pidToItemId = [];
        foreach ($onlineProducts as $op) {
            $itemId = null;
            foreach ([$op->product_code, $op->sku] as $value) {
                $value = trim((string) $value);
                if (preg_match('/^SHOPEE-(\d+)$/i', $value, $matches)) {
                    $itemId = $matches[1];
                    break;
                }
            }
            if ($itemId) {
                $pidToItemId[(int)$op->product_id] = $itemId;
            }
        }

        if (!empty($pidToItemId)) {
            try {
                $shopeeService = new \App\Services\ShopeeService();
                $result = $shopeeService->getProductsByItemIds(array_values($pidToItemId));
                if (!empty($result['success']) && !empty($result['products'])) {
                    $itemIdStock = [];
                    foreach ($result['products'] as $p) {
                        $itemIdStock[(int)$p['id']] = (int)($p['stock'] ?? 0);
                    }
                    foreach ($pidToItemId as $pid => $iid) {
                        if (isset($itemIdStock[(int)$iid])) {
                            $onlineBalanceStocks[$pid] = $itemIdStock[(int)$iid];
                        }
                    }
                }
            } catch (\Throwable $e) {
                \Illuminate\Support\Facades\Log::warning('Failed to fetch Shopee stock for online-print: ' . $e->getMessage());
            }
        }
    }

    // Collect ALL product IDs (original + counterpart) for bulk loading
    $allProductIds = [];
    foreach ($notes as $note) {
        foreach ($note['items'] as $item) {
            if ($item['product_id']) $allProductIds[(int)$item['product_id']] = true;
            if (!empty($item['cp_product_id'])) $allProductIds[(int)$item['cp_product_id']] = true;
        }
    }

    // Bulk-load product actual_qty and unit for all product IDs
    $productActualQtys = [];
    $productUnits = [];
    if (!empty($allProductIds)) {
        $allPids = array_keys($allProductIds);
        $productRows = \App\Models\Product::on('masterlist')
            ->whereIn('id', $allPids)
            ->get(['id', 'actual_qty', 'unit']);
        foreach ($productRows as $p) {
            $productActualQtys[(int)$p->id] = $p->actual_qty;
            $productUnits[(int)$p->id] = $p->unit ?? '';
        }
    }

    // Build paired items for each note (preserving original order)
    foreach ($notes as $noteIdx => $note) {
        $items = $note['items'];
        $paired = [];
        $consumed = [];
        $totalItems = count($items);
        for ($i = 0; $i < $totalItems; $i++) {
            if (isset($consumed[$i])) continue;
            $item = $items[$i];
            $cp = $item['counter_part'] ?? null;
            $hasCp = $cp && !empty($cp['product_id']) && (int)$cp['product_id'] > 0;
            if ($hasCp) {
                $paired[] = ['left_idx' => $i, 'right_idx' => null, 'has_cp' => true];
                $consumed[$i] = true;
            } else {
                $rightIdx = null;
                for ($j = $i + 1; $j < $totalItems; $j++) {
                    if (isset($consumed[$j])) continue;
                    $nextItem = $items[$j];
                    $nextCp = $nextItem['counter_part'] ?? null;
                    $nextHasCp = $nextCp && !empty($nextCp['product_id']) && (int)$nextCp['product_id'] > 0;
                    if (!$nextHasCp) {
                        $rightIdx = $j;
                        break;
                    }
                }
                $paired[] = ['left_idx' => $i, 'right_idx' => $rightIdx, 'has_cp' => false];
                $consumed[$i] = true;
                if ($rightIdx !== null) $consumed[$rightIdx] = true;
            }
        }
        $notes[$noteIdx]['paired'] = $paired;
    }

    $reportDate = $report->created_at ? \Carbon\Carbon::parse($report->created_at)->format('F d, Y') : '';

    return view('Admin.sales.online-report-print', [
        'report' => $report,
        'notes' => $notes,
        'prices' => $prices,
        'dateRanges' => $dateRanges,
        'salesByProduct' => $salesByProduct,
        'localBalanceStocks' => $localBalanceStocks,
        'onlineBalanceStocks' => $onlineBalanceStocks,
        'productActualQtys' => $productActualQtys,
        'productUnits' => $productUnits,
        'productSupplierIds' => $productSupplierIds,
        'supplierNames' => $supplierNames,
        'latestPurchaseCosts' => $latestPurchaseCosts,
        'costingByProductId' => $costingByProductId,
        'costingByProductCode' => $costingByProductCode,
        'reportDate' => $reportDate,
    ]);
})->name('admin.sales-order.online-print');

