// Waybill - Finalize (Update SO with waybill info)
Route::post('/admin/sales/waybill/finalize', function (Request $request) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);
    try {
        $orderIds = $request->input('order_ids', []);
        $forwarder = $request->input('forwarder');
        $totalValue = $request->input('total_value', 0);
        $declaredValue = $request->input('declared_value', 0);
        $cargoItems = $request->input('cargo_items', []);
        $actor = hatdogAuditActor($user);

        if (empty($orderIds)) return response()->json(['success' => false, 'message' => 'No orders selected.'], 422);
        if (empty($forwarder)) return response()->json(['success' => false, 'message' => 'Forwarder is required.'], 422);

        // Check for duplicates: any selected order already assigned to another waybill
        $alreadyAssigned = DB::connection('sales')->table('sales_orders')
            ->whereIn('id', $orderIds)
            ->whereNotNull('waybill_id')
            ->where('waybill_id', '!=', '')
            ->pluck('order_number')
            ->toArray();
        if (!empty($alreadyAssigned)) {
            return response()->json([
                'success' => false,
                'message' => 'The following orders are already assigned to a waybill: ' . implode(', ', $alreadyAssigned),
            ], 422);
        }

        // Generate waybill number: WB-XXXXXXX
        $maxNum = DB::connection('sales')->table('waybills')->max(DB::raw("CAST(SUBSTRING(waybill_sequence, 4) AS UNSIGNED)"));
        $nextNum = ($maxNum ?: 0) + 1;
        $waybillSequence = 'WB-' . str_pad($nextNum, 7, '0', STR_PAD_LEFT);
        $waybillNoInput = $request->input('waybill_no');

        DB::connection('sales')->beginTransaction();
        $salesOrdersBefore = DB::connection('sales')->table('sales_orders')
            ->whereIn('id', $orderIds)
            ->get()
            ->map(fn ($row) => (array) $row)
            ->values()
            ->all();
        $forwarderRow = DB::connection('masterlist')->table('forwarders')
            ->where('name', $forwarder)
            ->first();

        // 1. Insert into waybills table
        $waybillId = DB::connection('sales')->table('waybills')->insertGetId([
            'waybill_sequence' => $waybillSequence,
            'waybill_no' => $waybillNoInput,
            'waybill_date' => now()->toDateString(),
            'forwarder' => $forwarder,
            'total_value' => $totalValue,
            'declared_value' => $declaredValue,
            'created_at' => now(),
            'updated_at' => now()
        ]);

        // 2. Insert into waybill_cargo table
        foreach ($cargoItems as $item) {
            DB::connection('sales')->table('waybill_cargo')->insert([
                'waybill_id' => $waybillId,
                'quantity' => $item['qty'] ?? 0,
                'unit' => $item['unit'] ?? 'PCS',
                'description' => $item['desc'] ?? '',
                'created_at' => now(),
                'updated_at' => now()
            ]);
        }

        // 3. Update sales_orders table
        DB::connection('sales')->table('sales_orders')
            ->whereIn('id', $orderIds)
            ->update([
                'waybill_no' => $waybillSequence,
                'waybill_id' => $waybillId,
                'waybill_date' => now()->toDateString(),
                'remarks' => DB::raw("CONCAT(IFNULL(CONCAT(remarks, ' '), ''), '[Forwarder: $forwarder]')"),
                'updated_at' => now()
            ]);

        $waybill = DB::connection('sales')->table('waybills')->where('id', $waybillId)->first();
        $waybillCargo = DB::connection('sales')->table('waybill_cargo')
            ->where('waybill_id', $waybillId)
            ->get()
            ->map(fn ($row) => (array) $row)
            ->values()
            ->all();
        $salesOrdersAfter = DB::connection('sales')->table('sales_orders')
            ->whereIn('id', $orderIds)
            ->get()
            ->map(fn ($row) => (array) $row)
            ->values()
            ->all();
        $recordName = trim((string) ($forwarder ?: ('Waybill ' . $waybillSequence)));

        hatdogWriteAuditTrail([
            'module' => 'waybill',
            'action' => 'Processed',
            'source_connection' => 'sales',
            'source_table' => 'waybills',
            'source_id' => $waybillId,
            'display_id' => $waybillSequence,
            'record_name' => $recordName,
            'user_name' => $actor['name'],
            'user_identifier' => $actor['identifier'],
            'audit_data' => [
                'waybill' => $waybill ? (array) $waybill : null,
                'cargo' => $waybillCargo,
                'sales_orders_before' => $salesOrdersBefore,
                'sales_orders_after' => $salesOrdersAfter,
                'forwarder' => $forwarderRow ? (array) $forwarderRow : ['name' => $forwarder],
                'request_payload' => [
                    'order_ids' => collect($orderIds)->values()->all(),
                    'total_value' => $totalValue,
                    'declared_value' => $declaredValue,
                    'cargo_items' => collect($cargoItems)->values()->all(),
                ],
            ],
        ]);

        DB::connection('sales')->commit();

        \Illuminate\Support\Facades\Log::info('Waybill finalized:', [
            'waybill_sequence' => $waybillSequence,
            'waybill_no' => $waybillNoInput,
            'order_ids' => $orderIds,
            'cargo_count' => count($cargoItems),
        ]);

        return response()->json([
    'success' => true,
    'waybill_id' => $waybillId,
    'waybill_sequence' => $waybillSequence,
    'waybill_no' => $waybillNoInput,
    'display_waybill_no' => $waybillNoInput ?: $waybillSequence,
        ]);
    } catch (\Exception $e) {
        DB::connection('sales')->rollBack();
        \Illuminate\Support\Facades\Log::error('Waybill finalize error: ' . $e->getMessage());
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.waybill.finalize');

