// Waybill - History
Route::get('/admin/sales/waybill/history', function (Request $request) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);
    try {
        $searchWb = trim((string) $request->query('waybill', ''));
        $searchCust = trim((string) $request->query('customer', ''));
        $searchInv = trim((string) $request->query('invoice', ''));
        $search = trim((string) $request->query('search', ''));
        $page = (int)$request->query('page', 1);
        $perPage = 50;

        $query = DB::connection('sales')->table('waybills');

        if ($search) {
            $query->where(function($q) use ($search) {
                $q->where('waybill_sequence', 'LIKE', "%{$search}%")
                  ->orWhere('waybill_no', 'LIKE', "%{$search}%")
                  ->orWhere('forwarder', 'LIKE', "%{$search}%")
                  ->orWhereIn('id', function($sq) use ($search) {
                      $sq->select('waybill_id')
                         ->from('sales_orders')
                         ->whereNotNull('waybill_id')
                         ->where(function($inner) use ($search) {
                             $inner->where('customer_name', 'LIKE', "%{$search}%")
                                   ->orWhere('invoice_numbers', 'LIKE', "%{$search}%")
                                   ->orWhere('order_number', 'LIKE', "%{$search}%");
                         });
                  });
            });
        } else {
            if ($searchWb) {
                $query->where(function($q) use ($searchWb) {
                    $q->where('waybill_sequence', 'LIKE', "%{$searchWb}%")
                      ->orWhere('waybill_no', 'LIKE', "%{$searchWb}%");
                });
            }
            if ($searchCust !== '') {
                $query->whereIn('id', function($q) use ($searchCust) {
                    $q->select('waybill_id')
                      ->from('sales_orders')
                      ->whereNotNull('waybill_id')
                      ->where('customer_name', 'LIKE', "%{$searchCust}%");
                });
            }
            if ($searchInv !== '') {
                $query->whereIn('id', function($q) use ($searchInv) {
                    $q->select('waybill_id')
                      ->from('sales_orders')
                      ->whereNotNull('waybill_id')
                      ->where('invoice_numbers', 'LIKE', "%{$searchInv}%");
                });
            }
        }

        $totalCount = $query->count();
        $waybills = $query->orderBy('created_at', 'desc')
            ->offset(($page - 1) * $perPage)
            ->limit($perPage)
            ->get()
            ->map(function($wb) {
                // Get invoices linked to this waybill
                $invoices = DB::connection('sales')->table('sales_orders')
                    ->where('waybill_id', $wb->id)
                    ->pluck('invoice_numbers')
                    ->filter()
                    ->toArray();
                
                // Get customer name from the first linked SO
                $firstSO = DB::connection('sales')->table('sales_orders')
                    ->where('waybill_id', $wb->id)
                    ->first();

                return [
                    'id' => $wb->id,
                    'waybill_sequence' => $wb->waybill_sequence,
                    'waybill_no' => $wb->waybill_no,
                    'display_waybill_no' => $wb->waybill_no ?: $wb->waybill_sequence,
                    'customer_name' => $firstSO ? $firstSO->customer_name : '---',
                    'invoice_count' => count($invoices),
                    'invoice_numbers' => implode(', ', $invoices),
                    'waybill_date' => $wb->waybill_date,
                    'forwarder' => $wb->forwarder,
                    'total_value' => $wb->total_value,
                    'declared_value' => $wb->declared_value
                ];
            });
            
        return response()->json([
            'success' => true, 
            'history' => $waybills,
            'total' => $totalCount,
            'page' => $page,
            'last_page' => ceil($totalCount / $perPage)
        ]);
    } catch (\Exception $e) {
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.waybill.history');

