// Waybill - Update
Route::put('/admin/sales/waybill/{id}', function (Request $request, $id) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);
    try {
        $waybill = DB::connection('sales')->table('waybills')->where('id', $id)->first();
        if (!$waybill) throw new \Exception('Waybill not found');

        $forwarder = $request->input('forwarder');
        $waybillDate = $request->input('waybill_date');
        $totalValue = $request->input('total_value', 0);
        $declaredValue = $request->input('declared_value', 0);
        $waybillNoInput = $request->input('waybill_no');
        $cargoItems = $request->input('cargo_items', []);
        $invoiceIds = $request->input('invoice_ids', []);
        $actor = hatdogAuditActor($user);

        if (empty($forwarder)) return response()->json(['success' => false, 'message' => 'Forwarder is required.'], 422);

        // Check for duplicates: any newly attached invoice already assigned to a different waybill
        if (!empty($invoiceIds)) {
            $alreadyAssigned = DB::connection('sales')->table('sales_orders')
                ->whereIn('id', $invoiceIds)
                ->whereNotNull('waybill_id')
                ->where('waybill_id', '!=', '')
                ->where('waybill_id', '!=', $id)
                ->pluck('order_number')
                ->toArray();
            if (!empty($alreadyAssigned)) {
                return response()->json([
                    'success' => false,
                    'message' => 'The following orders are already assigned to a different waybill: ' . implode(', ', $alreadyAssigned),
                ], 422);
            }
        }

        $beforeSnapshot = (array) $waybill;
        $beforeSOs = DB::connection('sales')->table('sales_orders')
            ->where('waybill_id', $id)
            ->get()
            ->map(fn ($r) => (array) $r)
            ->values()
            ->all();
        $beforeCargo = DB::connection('sales')->table('waybill_cargo')
            ->where('waybill_id', $id)
            ->get()
            ->map(fn ($r) => (array) $r)
            ->values()
            ->all();

        DB::connection('sales')->beginTransaction();

        // 1. Update waybills table
        DB::connection('sales')->table('waybills')->where('id', $id)->update([
            'waybill_no' => $waybillNoInput,
            'waybill_date' => $waybillDate,
            'forwarder' => $forwarder,
            'total_value' => $totalValue,
            'declared_value' => $declaredValue,
            'updated_at' => now()
        ]);

        // 2. Sync invoices: detach removed, attach new
        if (!empty($invoiceIds)) {
            $attachedIds = DB::connection('sales')->table('sales_orders')
                ->where('waybill_id', $id)
                ->pluck('id')
                ->toArray();

            $toDetach = array_diff($attachedIds, $invoiceIds);
            $toAttach = array_diff($invoiceIds, $attachedIds);

            if (!empty($toDetach)) {
                DB::connection('sales')->table('sales_orders')
                    ->whereIn('id', $toDetach)
                    ->update(['waybill_id' => null, 'waybill_no' => null, 'waybill_date' => null, 'updated_at' => now()]);
            }
            if (!empty($toAttach)) {
                DB::connection('sales')->table('sales_orders')
                    ->whereIn('id', $toAttach)
                    ->update([
                        'waybill_id' => $id,
                        'waybill_no' => $waybill->waybill_sequence,
                        'waybill_date' => $waybillDate ?? now()->toDateString(),
                        'updated_at' => now()
                    ]);
            }
        }

        // 3. Delete existing cargo, re-insert
        DB::connection('sales')->table('waybill_cargo')->where('waybill_id', $id)->delete();
        foreach ($cargoItems as $item) {
            DB::connection('sales')->table('waybill_cargo')->insert([
                'waybill_id' => $id,
                'quantity' => $item['qty'] ?? 0,
                'unit' => $item['unit'] ?? 'PCS',
                'description' => $item['desc'] ?? '',
                'created_at' => now(),
                'updated_at' => now()
            ]);
        }

        $afterSnapshot = (array) DB::connection('sales')->table('waybills')->where('id', $id)->first();
        $afterSOs = DB::connection('sales')->table('sales_orders')
            ->where('waybill_id', $id)
            ->get()
            ->map(fn ($r) => (array) $r)
            ->values()
            ->all();
        $afterCargo = DB::connection('sales')->table('waybill_cargo')
            ->where('waybill_id', $id)
            ->get()
            ->map(fn ($r) => (array) $r)
            ->values()
            ->all();

        $recordName = trim((string) ($forwarder ?: ('Waybill ' . $waybill->waybill_sequence)));

        hatdogWriteAuditTrail([
            'module' => 'waybill',
            'action' => 'Updated',
            'source_connection' => 'sales',
            'source_table' => 'waybills',
            'source_id' => $id,
            'display_id' => $waybill->waybill_sequence,
            'record_name' => $recordName,
            'user_name' => $actor['name'],
            'user_identifier' => $actor['identifier'],
            'audit_data' => [
                'before' => ['waybill' => $beforeSnapshot, 'sales_orders' => $beforeSOs, 'cargo' => $beforeCargo],
                'after' => ['waybill' => $afterSnapshot, 'sales_orders' => $afterSOs, 'cargo' => $afterCargo],
            ],
        ]);

        DB::connection('sales')->commit();

        return response()->json(['success' => true, 'message' => 'Waybill updated successfully.']);
    } catch (\Exception $e) {
        DB::connection('sales')->rollBack();
        \Illuminate\Support\Facades\Log::error('Waybill update error: ' . $e->getMessage());
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.waybill.update');

