// Waybill - Delete
Route::delete('/admin/sales/waybill/{id}', function (Request $request, $id) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);
    try {
        $waybill = DB::connection('sales')->table('waybills')->where('id', $id)->first();
        if (!$waybill) {
            return response()->json(['success' => false, 'message' => 'Waybill not found.'], 404);
        }

        $actor = hatdogAuditActor($user);
        $beforeSOs = DB::connection('sales')->table('sales_orders')
            ->where('waybill_id', $id)
            ->get()
            ->map(fn ($r) => (array) $r)
            ->values()
            ->all();
        $beforeCargo = DB::connection('sales')->table('waybill_cargo')
            ->where('waybill_id', $id)
            ->get()
            ->map(fn ($r) => (array) $r)
            ->values()
            ->all();

        DB::connection('sales')->beginTransaction();

        // 1. Detach all linked sales orders
        DB::connection('sales')->table('sales_orders')
            ->where('waybill_id', $id)
            ->update(['waybill_id' => null, 'waybill_no' => null, 'waybill_date' => null, 'updated_at' => now()]);

        // 2. Delete cargo rows
        DB::connection('sales')->table('waybill_cargo')->where('waybill_id', $id)->delete();

        // 3. Delete waybill
        DB::connection('sales')->table('waybills')->where('id', $id)->delete();

                $recordName = trim((string) ($waybill->forwarder ?: ('Waybill ' . $waybill->waybill_sequence)));

        hatdogWriteAuditTrail([
            'module' => 'waybill',
            'action' => 'Deleted',
            'source_connection' => 'sales',
            'source_table' => 'waybills',
            'source_id' => $id,
            'display_id' => $waybill->waybill_sequence,
            'record_name' => $recordName,
            'user_name' => $actor['name'],
            'user_identifier' => $actor['identifier'],
            'audit_data' => [
                'waybill' => (array) $waybill,
                'sales_orders' => $beforeSOs,
                'cargo' => $beforeCargo,
            ],
        ]);

        DB::connection('sales')->commit();

        \Illuminate\Support\Facades\Log::info('Waybill deleted:', [
            'waybill_sequence' => $waybill->waybill_sequence,
            'waybill_no' => $waybill->waybill_no,
            'id' => $id,
        ]);

        return response()->json(['success' => true, 'message' => 'Waybill deleted successfully.']);
    } catch (\Exception $e) {
        DB::connection('sales')->rollBack();
        \Illuminate\Support\Facades\Log::error('Waybill delete error: ' . $e->getMessage());
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.waybill.destroy');

