// Sales Return - Invoices API (only Closed sales notes)

Route::get('/admin/sales/sales-return/invoices', function (Request $request) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

    try {
        $search = trim((string) $request->query('search', ''));
        $page = max(1, (int) $request->query('page', 1));
        $perPage = min(100, max(1, (int) $request->query('per_page', 25)));
        $searchLower = mb_strtolower($search);
        $isSourceSearch = in_array($searchLower, ['local', 'online'], true);

        $searchDate = null;
        if ($search !== '' && !$isSourceSearch) {
            foreach (['Y-m-d', 'm/d/Y', 'm/d/y'] as $format) {
                try {
                    $parsed = \Carbon\Carbon::createFromFormat($format, $search, 'Asia/Manila');
                    if ($parsed && $parsed->format($format) === $search) {
                        $searchDate = $parsed->toDateString();
                        break;
                    }
                } catch (\Throwable $e) {
                    // Keep trying the next supported date format.
                }
            }
        }

        // Each source only returns enough sorted candidates for the requested page.
        // We no longer load/JSON-decode the complete migrated Online history.
        $rowsNeeded = ($page * $perPage) + $perPage;
        $candidateLimit = min(5000, max(150, $rowsNeeded));

        $applySalesOrderSearch = static function ($query) use ($search, $isSourceSearch, $searchDate) {
            if ($search === '' || $isSourceSearch) return;

            if ($searchDate) {
                $query->whereDate('created_at', $searchDate);
                return;
            }

            $query->where(function ($q) use ($search) {
                $q->where('invoice_numbers', 'LIKE', "%{$search}%")
                    ->orWhere('customer_name', 'LIKE', "%{$search}%");
            });
        };

        $localInvoices = [];
        $localTotal = 0;

        if (!($isSourceSearch && $searchLower === 'online')) {
            $localBase = DB::connection('sales')
                ->table('sales_orders')
                ->whereIn('status', ['Confirmed', 'Closed'])
                ->whereNotNull('invoice_numbers')
                ->where('invoice_numbers', '<>', '')
                ->where('order_number', 'NOT LIKE', 'ONL-%');

            $applySalesOrderSearch($localBase);

            if ($search === '' || $isSourceSearch) {
                $localTotal = Cache::remember(
                    'sales_return:invoice_count:local:v5',
                    now()->addSeconds(60),
                    fn () => (clone $localBase)->count()
                );
            } else {
                $localTotal = (clone $localBase)->count();
            }

            $localInvoices = $localBase
                ->select('id', 'sales_note_id', 'invoice_numbers', 'customer_id', 'customer_name', 'total_amount', 'created_at')
                ->orderByDesc('created_at')
                ->orderByDesc('id')
                ->limit($candidateLimit)
                ->get()
                ->map(function ($order) {
                    return [
                        'id' => (int) ($order->sales_note_id ?: $order->id),
                        'no' => trim((string) $order->invoice_numbers),
                        'customer_id' => (int) ($order->customer_id ?? 0),
                        'customer' => $order->customer_name ?? '---',
                        'amount' => (float) ($order->total_amount ?? 0),
                        'created_at' => $order->created_at,
                        'source_type' => 'local',
                        // Exact sales_orders.id; the JS passes this back to the items endpoint.
                        'source_id' => (int) $order->id,
                    ];
                })
                ->all();
        }

        $generatedInvoices = [];
        $generatedTotal = 0;
        $migratedInvoices = [];
        $migratedTotal = 0;

        if (!($isSourceSearch && $searchLower === 'local')) {
            // Persisted generated Online invoices: cheap sales_orders query, no online_reports JSON needed.
            $generatedBase = DB::connection('sales')
                ->table('sales_orders')
                ->whereIn('status', ['Confirmed', 'Closed'])
                ->whereNotNull('invoice_numbers')
                ->where('invoice_numbers', '<>', '')
                ->where('order_number', 'LIKE', 'ONL-%');

            $applySalesOrderSearch($generatedBase);

            if ($search === '' || $isSourceSearch) {
                $generatedTotal = Cache::remember(
                    'sales_return:invoice_count:online_generated:v5',
                    now()->addSeconds(60),
                    fn () => (clone $generatedBase)->count()
                );
            } else {
                $generatedTotal = (clone $generatedBase)->count();
            }

            $generatedInvoices = $generatedBase
                ->select('id', 'order_number', 'invoice_numbers', 'customer_id', 'customer_name', 'total_amount', 'created_at')
                ->orderByDesc('created_at')
                ->orderByDesc('id')
                ->limit($candidateLimit)
                ->get()
                ->map(function ($order) {
                    $reportId = 0;
                    if (preg_match('/^ONL-(\d+)-/', (string) $order->order_number, $matches)) {
                        $reportId = (int) $matches[1];
                    }

                    return [
                        // For generated Online invoices this is sales_orders.id, so item lookup can use the PK.
                        'id' => (int) $order->id,
                        'no' => trim((string) $order->invoice_numbers),
                        'customer_id' => (int) ($order->customer_id ?? 0),
                        'customer' => $order->customer_name ?? '---',
                        'amount' => (float) ($order->total_amount ?? 0),
                        'created_at' => $order->created_at,
                        'source_type' => 'online_report',
                        'source_id' => $reportId,
                    ];
                })
                ->all();

            // Migrated reports are the expensive legacy source. The old code selected full notes_data
            // (including every item) and decoded it for hundreds of reports on every modal open.
            // This version asks MariaDB for only the small scalar fields needed by the list.
            $migratedBase = DB::connection('sales')
                ->table('online_reports')
                ->where('status', 'migrated');

            if ($search !== '' && !$isSourceSearch) {
                if ($searchDate) {
                    $migratedBase->whereRaw(
                        'JSON_UNQUOTE(JSON_EXTRACT(notes_data, \'$[0].order_date\')) = ?',
                        [$searchDate]
                    );
                } else {
                    $migratedBase->where(function ($q) use ($search) {
                        $q->where('invoice_numbers', 'LIKE', "%{$search}%")
                            ->orWhereRaw(
                                'JSON_UNQUOTE(JSON_EXTRACT(notes_data, \'$[0].customer_name\')) LIKE ?',
                                ["%{$search}%"]
                            );
                    });
                }
            }

            if ($search === '' || $isSourceSearch) {
                $migratedTotal = Cache::remember(
                    'sales_return:invoice_count:online_migrated:v5',
                    now()->addSeconds(60),
                    fn () => (clone $migratedBase)->count()
                );
            } else {
                $migratedTotal = (clone $migratedBase)->count();
            }

            $migratedRows = $migratedBase
                ->select([
                    'id',
                    'invoice_numbers',
                    'created_at',
                    DB::raw('JSON_LENGTH(invoice_numbers) as sr_invoice_count'),
                    DB::raw('JSON_UNQUOTE(JSON_EXTRACT(notes_data, \'$[0].customer_id\')) as sr_customer_id'),
                    DB::raw('JSON_UNQUOTE(JSON_EXTRACT(notes_data, \'$[0].customer_name\')) as sr_customer_name'),
                    DB::raw('JSON_UNQUOTE(JSON_EXTRACT(notes_data, \'$[0].order_date\')) as sr_order_date'),
                    DB::raw('JSON_UNQUOTE(JSON_EXTRACT(notes_data, \'$[0].net_total\')) as sr_net_total'),
                ])
                ->orderByDesc('id')
                ->limit($candidateLimit * 2)
                ->get();

            $multiReportIds = [];
            foreach ($migratedRows as $report) {
                $invNumbers = json_decode($report->invoice_numbers ?? '[]', true);
                if (!is_array($invNumbers)) $invNumbers = [];
                $invNumbers = array_values(array_filter(array_map(fn ($v) => trim((string) $v), $invNumbers)));
                if (empty($invNumbers)) continue;

                if (count($invNumbers) > 1) {
                    $multiReportIds[] = (int) $report->id;
                    continue;
                }

                $invoiceDate = trim((string) ($report->sr_order_date ?? '')) ?: $report->created_at;
                $migratedInvoices[] = [
                    'id' => (int) $report->id,
                    'no' => $invNumbers[0],
                    'customer_id' => (int) ($report->sr_customer_id ?? 0),
                    'customer' => trim((string) ($report->sr_customer_name ?? '')) ?: '---',
                    'amount' => (float) ($report->sr_net_total ?? 0),
                    'created_at' => $invoiceDate,
                    'source_type' => 'online_report',
                    'source_id' => (int) $report->id,
                ];
            }

            // Multi-invoice migrated reports are expanded separately; only these rare rows transfer notes_data.
            if (!empty($multiReportIds)) {
                $multiReports = DB::connection('sales')
                    ->table('online_reports')
                    ->whereIn('id', array_values(array_unique($multiReportIds)))
                    ->get(['id', 'invoice_numbers', 'notes_data', 'created_at']);

                foreach ($multiReports as $report) {
                    $invNumbers = json_decode($report->invoice_numbers ?? '[]', true);
                    $notesData = json_decode($report->notes_data ?? '[]', true);
                    if (!is_array($invNumbers)) $invNumbers = [];
                    if (!is_array($notesData)) $notesData = [];

                    foreach ($invNumbers as $i => $rawInvoiceNo) {
                        $invNo = trim((string) $rawInvoiceNo);
                        if ($invNo === '') continue;

                        $note = $notesData[$i] ?? (count($notesData) === 1 ? $notesData[0] : null);
                        $customerName = is_array($note) ? trim((string) ($note['customer_name'] ?? '')) : '';
                        $invoiceDate = is_array($note) && !empty($note['order_date'])
                            ? $note['order_date']
                            : $report->created_at;

                        if ($search !== '' && !$isSourceSearch) {
                            $formattedDate = $invoiceDate ? date('m/d/Y', strtotime($invoiceDate)) : '';
                            $haystack = mb_strtolower($invNo . '|' . $customerName . '|' . (string) $invoiceDate . '|' . $formattedDate);
                            if (mb_strpos($haystack, $searchLower) === false) continue;
                        }

                        $migratedInvoices[] = [
                            'id' => (int) $report->id,
                            'no' => $invNo,
                            'customer_id' => (int) (is_array($note) ? ($note['customer_id'] ?? 0) : 0),
                            'customer' => $customerName !== '' ? $customerName : '---',
                            'amount' => (float) (is_array($note) ? ($note['net_total'] ?? 0) : 0),
                            'created_at' => $invoiceDate,
                            'source_type' => 'online_report',
                            'source_id' => (int) $report->id,
                        ];
                    }
                }
            }
        }

        $all = array_merge($localInvoices, $generatedInvoices, $migratedInvoices);

        usort($all, function ($a, $b) {
            $aTs = !empty($a['created_at']) ? strtotime((string) $a['created_at']) : 0;
            $bTs = !empty($b['created_at']) ? strtotime((string) $b['created_at']) : 0;
            if ($aTs !== $bTs) return $bTs <=> $aTs;
            return strcmp((string) ($b['no'] ?? ''), (string) ($a['no'] ?? ''));
        });

        // Generated ONL sales_orders and migrated online_reports can represent the same invoice.
        $seenOnlineInvoices = [];
        $all = array_values(array_filter($all, function ($row) use (&$seenOnlineInvoices) {
            if (($row['source_type'] ?? '') !== 'online_report') return true;

            $key = mb_strtoupper(preg_replace('/\s+/', '', trim((string) ($row['no'] ?? ''))));
            if ($key === '') return true;
            if (isset($seenOnlineInvoices[$key])) return false;
            $seenOnlineInvoices[$key] = true;
            return true;
        }));

        $estimatedTotal = $localTotal + $generatedTotal + $migratedTotal;
        $lastPage = max(1, (int) ceil(max($estimatedTotal, count($all)) / $perPage));
        if ($page > $lastPage) $page = $lastPage;

        $from = ($page - 1) * $perPage;
        $items = array_slice($all, $from, $perPage);

        return response()->json([
            'success' => true,
            'data' => array_values($items),
            'pagination' => [
                'current_page' => $page,
                'per_page' => $perPage,
                'total' => $estimatedTotal,
                'last_page' => $lastPage,
                'from' => empty($items) ? 0 : $from + 1,
                'to' => empty($items) ? 0 : $from + count($items),
            ],
            'invoices' => array_values($items),
            'total' => $estimatedTotal,
            'page' => $page,
            'last_page' => $lastPage,
        ]);
    } catch (\Throwable $e) {
        Log::error('Sales Return Invoices Error: ' . $e->getMessage(), [
            'file' => $e->getFile(),
            'line' => $e->getLine(),
        ]);

        return response()->json([
            'success' => false,
            'message' => $e->getMessage(),
        ], 422);
    }
})->name('admin.sales-return.invoices');

Route::get('/admin/sales/sales-return/items/{noteId}', function (Request $request, $noteId) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

    try {
        $sourceType = (string) $request->query('type', '');
        $reportId = (int) $request->query('report_id', 0);
        $salesOrderId = (int) $request->query('sales_order_id', 0);
        $invoiceNo = trim((string) $request->query('invoice_no', ''));
        $invoiceKey = $invoiceNo;
        $rawItems = collect();

        // Enrich all products in ONE masterlist query instead of one query per item.
        $enrichItems = static function ($rows) {
            $rows = collect($rows)->values();
            if ($rows->isEmpty()) return collect();

            $read = static function ($row, string $key, $default = null) {
                return is_array($row) ? ($row[$key] ?? $default) : ($row->{$key} ?? $default);
            };

            $productIds = $rows
                ->map(fn ($row) => (int) $read($row, 'product_id', 0))
                ->filter(fn ($id) => $id > 0)
                ->unique()
                ->values();

            $products = $productIds->isEmpty()
                ? collect()
                : DB::connection('masterlist')
                    ->table('products')
                    ->whereIn('id', $productIds)
                    ->get(['id', 'product_code', 'part_number', 'application', 'unit'])
                    ->keyBy('id');

            return $rows->map(function ($row) use ($read, $products) {
                $productId = (int) $read($row, 'product_id', 0);
                $product = $products->get($productId);

                return [
                    'product_id' => $productId,
                    'product_code' => (string) ($read($row, 'product_code', '') ?: ($product->product_code ?? '')),
                    'part_number' => (string) ($read($row, 'part_number', '') ?: ($product->part_number ?? '')),
                    'description' => (string) $read($row, 'description', ''),
                    'application' => (string) ($read($row, 'application', '') ?: ($product->application ?? '')),
                    'oum' => (string) ($read($row, 'oum', '') ?: ($product->unit ?? '')),
                    'unit_price' => (float) $read($row, 'unit_price', 0),
                    'quantity' => (float) $read($row, 'quantity', 0),
                    'subtotal' => (float) $read($row, 'subtotal', 0),
                    'discount' => (float) $read($row, 'discount', 0),
                    'additional_discount' => (float) $read($row, 'additional_discount', 0),
                ];
            });
        };

        if ($sourceType === 'online_report') {
            $salesOrder = null;

            // Generated Online invoices pass sales_orders.id as noteId.
            // Try the primary key first: this is much faster than scanning by order_number.
            if ((int) $noteId > 0) {
                $orderQuery = DB::connection('sales')
                    ->table('sales_orders')
                    ->where('id', (int) $noteId)
                    ->where('order_number', 'LIKE', 'ONL-%');

                if ($invoiceNo !== '') {
                    $orderQuery->where('invoice_numbers', $invoiceNo);
                }

                $salesOrder = $orderQuery->first();
            }

            // Backward-compatible fallback for generated reports.
            if (!$salesOrder && $reportId > 0) {
                $orderQuery = DB::connection('sales')
                    ->table('sales_orders')
                    ->where('order_number', 'LIKE', 'ONL-' . $reportId . '-%');

                if ($invoiceNo !== '') {
                    $orderQuery->where('invoice_numbers', $invoiceNo);
                }

                $salesOrder = $orderQuery->orderByDesc('id')->first();
            }

            if ($salesOrder) {
                $invoiceKey = $invoiceNo !== ''
                    ? $invoiceNo
                    : trim((string) ($salesOrder->invoice_numbers ?? ''));

                $rawItems = DB::connection('sales')
                    ->table('sales_order_items')
                    ->where('sales_order_id', $salesOrder->id)
                    ->get();
            } else {
                // Migrated Online report: only this path needs notes_data JSON.
                $report = DB::connection('sales')
                    ->table('online_reports')
                    ->where('id', $reportId ?: (int) $noteId)
                    ->first(['id', 'invoice_numbers', 'notes_data']);

                if ($report) {
                    $invNumbers = json_decode($report->invoice_numbers ?? '[]', true);
                    $notesData = json_decode($report->notes_data ?? '[]', true);
                    if (!is_array($invNumbers)) $invNumbers = [];
                    if (!is_array($notesData)) $notesData = [];

                    $trimmedInvoices = array_map(fn ($value) => trim((string) $value), $invNumbers);
                    $idx = $invoiceNo !== '' ? array_search($invoiceNo, $trimmedInvoices, true) : false;
                    if ($idx === false && count($trimmedInvoices) === 1) $idx = 0;

                    $note = ($idx !== false && isset($notesData[$idx]))
                        ? $notesData[$idx]
                        : (count($notesData) === 1 ? $notesData[0] : null);

                    if ($invoiceKey === '' && $idx !== false && isset($trimmedInvoices[$idx])) {
                        $invoiceKey = $trimmedInvoices[$idx];
                    }

                    $rawItems = collect(
                        $note && is_array($note) && isset($note['items']) && is_array($note['items'])
                            ? $note['items']
                            : []
                    );
                }
            }
        } else {
            // Local invoice: use the exact sales_orders.id sent by the JS whenever available.
            $salesOrder = null;

            if ($salesOrderId > 0) {
                $orderQuery = DB::connection('sales')
                    ->table('sales_orders')
                    ->where('id', $salesOrderId)
                    ->where('order_number', 'NOT LIKE', 'ONL-%');

                if ($invoiceNo !== '') {
                    $orderQuery->where('invoice_numbers', $invoiceNo);
                }

                $salesOrder = $orderQuery->first();
            }

            if (!$salesOrder) {
                $orderQuery = DB::connection('sales')
                    ->table('sales_orders')
                    ->where('sales_note_id', $noteId)
                    ->where('order_number', 'NOT LIKE', 'ONL-%');

                if ($invoiceNo !== '') {
                    $orderQuery->where('invoice_numbers', $invoiceNo);
                }

                $salesOrder = $orderQuery->orderByDesc('id')->first();
            }

            if (!$salesOrder) {
                $fallbackQuery = DB::connection('sales')
                    ->table('sales_orders')
                    ->where('id', (int) $noteId)
                    ->where('order_number', 'NOT LIKE', 'ONL-%');

                if ($invoiceNo !== '') {
                    $fallbackQuery->where('invoice_numbers', $invoiceNo);
                }

                $salesOrder = $fallbackQuery->first();
            }

            if (!$salesOrder) {
                return response()->json(['success' => false, 'message' => 'Sales order not found'], 404);
            }

            $invoiceKey = $invoiceNo !== ''
                ? $invoiceNo
                : trim((string) ($salesOrder->invoice_numbers ?? ''));

            $rawItems = DB::connection('sales')
                ->table('sales_order_items')
                ->where('sales_order_id', $salesOrder->id)
                ->get();
        }

        $items = $enrichItems($rawItems);

        // Previously returned quantities for this exact invoice.
        // The new DB indexes make this lookup direct instead of scanning the full returns tables.
        $prevMap = [];
        if ($invoiceKey !== '') {
            $prevRows = DB::connection('sales')
                ->table('sales_return_items as sri')
                ->join('sales_returns as sr', 'sr.id', '=', 'sri.sales_return_id')
                ->where('sr.invoice_no', $invoiceKey)
                ->select('sri.product_id', DB::raw('SUM(sri.quantity) as total_returned'))
                ->groupBy('sri.product_id')
                ->get();

            foreach ($prevRows as $row) {
                $prevMap[(int) $row->product_id] = (int) $row->total_returned;
            }
        }

        $finalItems = $items
            ->map(function ($item) use ($prevMap) {
                $qty = (int) ($item['quantity'] ?? 0);
                $productId = (int) ($item['product_id'] ?? 0);
                $prev = $prevMap[$productId] ?? 0;

                return array_merge($item, [
                    'previously_returned' => $prev,
                    'remaining' => max(0, $qty - $prev),
                ]);
            })
            ->filter(fn ($item) => $item['remaining'] > 0)
            ->values();

        return response()->json(['success' => true, 'items' => $finalItems]);
    } catch (\Throwable $e) {
        Log::error('Sales Return Items Error: ' . $e->getMessage(), [
            'note_id' => $noteId,
            'invoice_no' => $request->query('invoice_no'),
            'source_type' => $request->query('type'),
        ]);

        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.sales-return.items');
