// Helper function for capturing old voucher state for audit trail
if (!function_exists('captureOldVoucherState')) {
    /**
     * Capture the complete state of a voucher for audit trail purposes.
     * 
     * @param int $voucherId The ID of the voucher to capture
     * @return array Combined data structure containing voucher, invoices, sudden_returns, and payment
     */
    function captureOldVoucherState(int $voucherId): array
    {
        return [
            'voucher' => DB::connection('accounting')
                ->table('payable_cheque_vouchers')
                ->where('id', $voucherId)
                ->first(),
            'invoices' => DB::connection('accounting')
                ->table('payable_cheque_voucher_invoices')
                ->where('payable_cheque_voucher_id', $voucherId)
                ->get()
                ->map(fn ($row) => (array) $row)
                ->all(),
            'sudden_returns' => DB::connection('accounting')
                ->table('payable_cheque_voucher_sudden_returns')
                ->where('payable_cheque_voucher_id', $voucherId)
                ->get()
                ->map(fn ($row) => (array) $row)
                ->all(),
            'payment' => DB::connection('accounting')
                ->table('payable_cheque_voucher_payments')
                ->where('payable_cheque_voucher_id', $voucherId)
                ->first(),
        ];
    }
}

