if (!function_exists('hatdogEnsureExpenseChequeVoucherParticularsTable')) {
    /**
     * Ensure the grouped-particulars storage exists for Expense Cheque Vouchers.
     * This keeps deployed installations backward-compatible even when the SQL
     * migration has not yet been applied manually. Existing voucher data is
     * backfilled exactly once per parent voucher.
     */
    function hatdogEnsureExpenseChequeVoucherParticularsTable(): bool
    {
        $schema = Schema::connection('accounting');
        $connection = DB::connection('accounting');

        if (!$schema->hasTable('expense_cheque_voucher_particulars')) {
            $schema->create('expense_cheque_voucher_particulars', function ($table) {
                $table->id();
                $table->unsignedBigInteger('expense_cheque_voucher_id');
                $table->text('particulars')->nullable();
                $table->date('billing_date')->nullable();
                $table->string('expense_type', 50);
                $table->decimal('amount', 15, 2)->default(0);
                $table->decimal('paid_amount', 15, 2)->default(0);
                $table->string('payment_method', 50)->default('Cash');
                $table->string('account_no')->nullable();
                $table->date('check_date')->nullable();
                $table->string('check_no')->nullable();
                $table->timestamps();
                $table->index('expense_cheque_voucher_id', 'idx_ecv_particulars_voucher');
            });
        }

        // Backfill legacy one-row vouchers only when they do not yet have child rows.
        $parents = $connection->table('expense_cheque_vouchers as e')
            ->leftJoin('expense_cheque_voucher_particulars as p', 'p.expense_cheque_voucher_id', '=', 'e.id')
            ->whereNull('p.id')
            ->select([
                'e.id', 'e.particulars', 'e.billing_date', 'e.expense_type', 'e.amount',
                'e.paid_amount', 'e.payment_method', 'e.account_no', 'e.check_date',
                'e.check_no', 'e.created_at', 'e.updated_at',
            ])
            ->get();

        if ($parents->isNotEmpty()) {
            $rows = $parents->map(fn ($row) => [
                'expense_cheque_voucher_id' => (int) $row->id,
                'particulars' => $row->particulars,
                'billing_date' => $row->billing_date,
                'expense_type' => $row->expense_type ?: 'One time',
                'amount' => (float) ($row->amount ?? 0),
                'paid_amount' => (float) ($row->paid_amount ?? 0),
                'payment_method' => $row->payment_method ?: 'Cash',
                'account_no' => $row->account_no,
                'check_date' => $row->check_date,
                'check_no' => $row->check_no,
                'created_at' => $row->created_at,
                'updated_at' => $row->updated_at,
            ])->all();
            $connection->table('expense_cheque_voucher_particulars')->insert($rows);
        }

        return true;
    }
}

Route::get('/admin/accounting/expense-cheque-voucher', function () {
    $user = session('user');
    if (!$user) return redirect()->route('login');

    try {
        hatdogEnsureExpenseChequeVoucherParticularsTable();
    } catch (\Throwable $e) {
        // Never turn the page itself into a 500 because a legacy database has not
        // been migrated yet. The data endpoint still has a legacy-row fallback.
        Log::warning('Expense cheque voucher particulars schema initialization skipped: ' . $e->getMessage());
    }

    return view('Admin.Accounting.Expense-Cheque-Voucher');
})->name('admin.expense-cheque-voucher');

