// Expense Cheque Voucher - Data (one voucher header + grouped particulars)
Route::get('/admin/accounting/expense-cheque-voucher/data', function (Request $request) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

    try {
        try {
            hatdogEnsureExpenseChequeVoucherParticularsTable();
        } catch (\Throwable $schemaError) {
            Log::warning('Expense cheque voucher data using legacy fallback: ' . $schemaError->getMessage());
        }

        $headers = DB::connection('accounting')->table('expense_cheque_vouchers')
            ->orderBy('created_at', 'desc')
            ->orderBy('id', 'desc')
            ->get();

        $hasParticularsTable = Schema::connection('accounting')->hasTable('expense_cheque_voucher_particulars');
        $particularRows = collect();
        if ($hasParticularsTable && $headers->isNotEmpty()) {
            $particularRows = DB::connection('accounting')->table('expense_cheque_voucher_particulars')
                ->whereIn('expense_cheque_voucher_id', $headers->pluck('id'))
                ->orderBy('id')
                ->get()
                ->groupBy('expense_cheque_voucher_id');
        }

        $vouchers = $headers->map(function ($header) use ($particularRows) {
            $details = $particularRows->get($header->id, collect());

            // Backward-compatible fallback for a legacy voucher not yet backfilled.
            if ($details->isEmpty()) {
                $details = collect([(object) [
                    'id' => null,
                    'particulars' => $header->particulars,
                    'billing_date' => $header->billing_date,
                    'expense_type' => $header->expense_type,
                    'amount' => $header->amount,
                    'paid_amount' => $header->paid_amount,
                    'payment_method' => $header->payment_method,
                    'account_no' => $header->account_no,
                    'check_date' => $header->check_date,
                    'check_no' => $header->check_no,
                ]]);
            }

            return [
                'id'           => (int) $header->id,
                'voucherNo'    => (string) $header->voucher_no,
                'name'         => (string) ($header->supplier_name ?? ''),
                'supplierId'   => (int) ($header->supplier_id ?? 0),
                'supplierCode' => (string) ($header->supplier_code ?? ''),
                'remarks'      => (string) ($header->ref ?? ''),
                'totalAmount'  => (float) $details->sum('amount'),
                'totalPaid'    => (float) $details->sum('paid_amount'),
                'items'        => $details->values()->map(function ($row) {
                    return [
                        'id'            => $row->id !== null ? (int) $row->id : null,
                        'particulars'   => (string) ($row->particulars ?? ''),
                        'billingDate'   => $row->billing_date,
                        'expenseType'   => (string) ($row->expense_type ?? ''),
                        'amount'        => (float) ($row->amount ?? 0),
                        'paidAmount'    => (float) ($row->paid_amount ?? 0),
                        'paymentMethod' => (string) ($row->payment_method ?? ''),
                        'accountNo'     => $row->account_no,
                        'checkDate'     => $row->check_date,
                        'checkNo'       => $row->check_no,
                    ];
                })->all(),
            ];
        })->values();

        // Dashboard remains supplier-based. When particulars exist, use their own expense types.
        if ($hasParticularsTable && $particularRows->isNotEmpty()) {
            $headerById = $headers->keyBy('id');
            $typedSupplierIds = ['Monthly' => [], 'Yearly' => [], 'One time' => []];
            $voucherIdsWithParticulars = [];
            foreach ($particularRows as $voucherId => $details) {
                $voucherIdsWithParticulars[(int) $voucherId] = true;
                $supplierId = (int) ($headerById->get($voucherId)->supplier_id ?? 0);
                foreach ($details as $detail) {
                    if ($supplierId > 0 && array_key_exists($detail->expense_type, $typedSupplierIds)) {
                        $typedSupplierIds[$detail->expense_type][$supplierId] = true;
                    }
                }
            }
            foreach ($headers as $header) {
                if (isset($voucherIdsWithParticulars[(int) $header->id])) continue;
                $supplierId = (int) ($header->supplier_id ?? 0);
                if ($supplierId > 0 && array_key_exists($header->expense_type, $typedSupplierIds)) {
                    $typedSupplierIds[$header->expense_type][$supplierId] = true;
                }
            }
            $monthlySuppliers = count($typedSupplierIds['Monthly']);
            $yearlySuppliers = count($typedSupplierIds['Yearly']);
            $oneTimeSuppliers = count($typedSupplierIds['One time']);
        } else {
            $monthlySuppliers = $headers->where('expense_type', 'Monthly')->pluck('supplier_id')->filter()->unique()->count();
            $yearlySuppliers = $headers->where('expense_type', 'Yearly')->pluck('supplier_id')->filter()->unique()->count();
            $oneTimeSuppliers = $headers->where('expense_type', 'One time')->pluck('supplier_id')->filter()->unique()->count();
        }
        $totalSuppliers = $headers->pluck('supplier_id')->filter()->unique()->count();

        $maxNum = DB::connection('accounting')->table('expense_cheque_vouchers')
            ->max(DB::raw("CAST(SUBSTRING(voucher_no, 5) AS UNSIGNED)"));
        $nextVoucherNo = 'ECV-' . str_pad(((int) $maxNum) + 1, 4, '0', STR_PAD_LEFT);

        return response()->json([
            'success' => true,
            'vouchers' => $vouchers,
            'stats' => [
                'total' => $totalSuppliers,
                'monthly' => $monthlySuppliers,
                'yearly' => $yearlySuppliers,
                'oneTime' => $oneTimeSuppliers,
            ],
            'nextVoucherNo' => $nextVoucherNo,
        ]);
    } catch (\Throwable $e) {
        Log::error('Expense cheque voucher data error: ' . $e->getMessage());
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.expense-cheque-voucher.data');

// Expense Cheque Voucher - Create a voucher or append more particulars to an existing voucher.
Route::post('/admin/accounting/expense-cheque-voucher/store', function (Request $request) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

    try {
        hatdogEnsureExpenseChequeVoucherParticularsTable();
    } catch (\Throwable $schemaError) {
        Log::error('Expense cheque voucher particulars schema initialization failed: ' . $schemaError->getMessage());
        return response()->json([
            'success' => false,
            'message' => 'Unable to initialize Expense Voucher particulars storage: ' . $schemaError->getMessage(),
        ], 422);
    }

    $rules = [
        'voucher_no'    => 'required|string|max:50',
        'supplier_id'   => 'required|integer',
        'supplier_code' => 'required|string|max:255',
        'supplier_name' => 'required|string|max:255',
        'ref'           => 'nullable|string|max:255',
        'items'         => 'required|array|min:1',
        'items.*.particulars'    => 'required|string',
        'items.*.billing_date'   => 'nullable|date',
        'items.*.expense_type'   => 'required|string|in:Monthly,Yearly,One time',
        'items.*.amount'         => 'required|numeric|min:0',
        'items.*.paid_amount'    => 'required|numeric|min:0',
        'items.*.payment_method' => 'required|string|in:Gcash,Cash,Bank',
        'items.*.account_no'     => 'nullable|string|max:255',
        'items.*.check_date'     => 'nullable|date',
        'items.*.check_no'       => 'nullable|string|max:255',
    ];
    $data = $request->validate($rules);
    $items = $data['items'];

    try {
        $connection = DB::connection('accounting');
        $connection->beginTransaction();
        $now = now();

        $voucher = $connection->table('expense_cheque_vouchers')
            ->where('voucher_no', $data['voucher_no'])
            ->lockForUpdate()
            ->first();

        $isAppend = (bool) $voucher;
        if ($voucher) {
            if ((int) $voucher->supplier_id !== (int) $data['supplier_id']) {
                throw new \RuntimeException('The selected voucher belongs to a different supplier.');
            }
            $voucherId = (int) $voucher->id;
        } else {
            $first = $items[0];
            $voucherId = $connection->table('expense_cheque_vouchers')->insertGetId([
                'voucher_no' => $data['voucher_no'],
                'expense_type' => $first['expense_type'],
                'supplier_id' => $data['supplier_id'],
                'supplier_code' => $data['supplier_code'],
                'supplier_name' => $data['supplier_name'],
                'ref' => $data['ref'] ?? null,
                'particulars' => $first['particulars'],
                'billing_date' => $first['expense_type'] === 'One time' ? null : ($first['billing_date'] ?? null),
                'amount' => 0,
                'paid_amount' => 0,
                'payment_method' => $first['payment_method'],
                'account_no' => $first['payment_method'] === 'Bank' ? ($first['account_no'] ?? null) : null,
                'check_date' => $first['payment_method'] === 'Bank' ? ($first['check_date'] ?? null) : null,
                'check_no' => $first['payment_method'] === 'Bank' ? ($first['check_no'] ?? null) : null,
                'status' => 'Posted',
                'created_at' => $now,
                'updated_at' => $now,
            ]);
        }

        $insertedIds = [];
        foreach ($items as $item) {
            $paymentMethod = $item['payment_method'];
            $insertedIds[] = $connection->table('expense_cheque_voucher_particulars')->insertGetId([
                'expense_cheque_voucher_id' => $voucherId,
                'particulars' => $item['particulars'],
                'billing_date' => $item['expense_type'] === 'One time' ? null : ($item['billing_date'] ?? null),
                'expense_type' => $item['expense_type'],
                'amount' => $item['amount'],
                'paid_amount' => $item['paid_amount'],
                'payment_method' => $paymentMethod,
                'account_no' => $paymentMethod === 'Bank' ? ($item['account_no'] ?? null) : null,
                'check_date' => $paymentMethod === 'Bank' ? ($item['check_date'] ?? null) : null,
                'check_no' => $paymentMethod === 'Bank' ? ($item['check_no'] ?? null) : null,
                'created_at' => $now,
                'updated_at' => $now,
            ]);
        }

        $totals = $connection->table('expense_cheque_voucher_particulars')
            ->where('expense_cheque_voucher_id', $voucherId)
            ->selectRaw('COALESCE(SUM(amount), 0) as total_amount, COALESCE(SUM(paid_amount), 0) as total_paid')
            ->first();

        $connection->table('expense_cheque_vouchers')->where('id', $voucherId)->update([
            'supplier_id' => $data['supplier_id'],
            'supplier_code' => $data['supplier_code'],
            'supplier_name' => $data['supplier_name'],
            'ref' => $data['ref'] ?? ($voucher->ref ?? null),
            'amount' => (float) ($totals->total_amount ?? 0),
            'paid_amount' => (float) ($totals->total_paid ?? 0),
            'updated_at' => $now,
        ]);

        $connection->commit();

        $actor = hatdogAuditActor($user);
        $supplier = \App\Models\Supplier::on('masterlist')->find($data['supplier_id']);
        hatdogWriteAuditTrail([
            'module' => 'expense_cheque_voucher',
            'action' => $isAppend ? 'Added Particulars' : 'Created',
            'source_connection' => 'accounting',
            'source_table' => 'expense_cheque_vouchers',
            'source_id' => $voucherId,
            'display_id' => (string) $data['voucher_no'],
            'record_name' => trim((string) $data['supplier_name']),
            'user_name' => $actor['name'],
            'user_identifier' => $actor['identifier'],
            'audit_data' => [
                'inserted_particular_ids' => $insertedIds,
                'supplier' => $supplier?->toArray(),
                'request_payload' => ['voucher_no' => $data['voucher_no'], 'ref' => $data['ref'] ?? null, 'items' => $items],
            ],
        ]);

        return response()->json([
            'success' => true,
            'voucher_id' => $voucherId,
            'inserted_particular_ids' => $insertedIds,
            'mode' => $isAppend ? 'append' : 'create',
        ]);
    } catch (\Throwable $e) {
        if (isset($connection) && $connection->transactionLevel() > 0) $connection->rollBack();
        Log::error('Expense cheque voucher store error: ' . $e->getMessage());
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.expense-cheque-voucher.store');

