// Expense Cheque Voucher V2 - Admin redesign (voucher header + expense items + bank details).
if (!function_exists('hatdogExpenseChequeVoucherV2TablesReady')) {
    function hatdogExpenseChequeVoucherV2TablesReady(): bool
    {
        $schema = Schema::connection('accounting');
        return $schema->hasTable('expense_cheque_voucher_items')
            && $schema->hasTable('expense_cheque_voucher_bank_details');
    }
}

Route::get('/admin/accounting/expense-cheque-voucher/v2/data', function () {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

    try {
        if (!hatdogExpenseChequeVoucherV2TablesReady()) {
            return response()->json([
                'success' => false,
                'message' => 'Expense Voucher V2 database tables are missing. Run the provided Expense Cheque Voucher V2 SQL command first.',
            ], 422);
        }

        $connection = DB::connection('accounting');
        $headers = $connection->table('expense_cheque_vouchers')
            ->orderByDesc('created_at')
            ->orderByDesc('id')
            ->get();

        $itemsByVoucher = collect();
        $banksByVoucher = collect();
        if ($headers->isNotEmpty()) {
            $voucherIds = $headers->pluck('id');
            $itemsByVoucher = $connection->table('expense_cheque_voucher_items')
                ->whereIn('expense_cheque_voucher_id', $voucherIds)
                ->orderBy('sort_order')
                ->orderBy('id')
                ->get()
                ->groupBy('expense_cheque_voucher_id');
            $banksByVoucher = $connection->table('expense_cheque_voucher_bank_details')
                ->whereIn('expense_cheque_voucher_id', $voucherIds)
                ->orderBy('sort_order')
                ->orderBy('id')
                ->get()
                ->groupBy('expense_cheque_voucher_id');
        }

        $vouchers = $headers->map(function ($header) use ($itemsByVoucher, $banksByVoucher) {
            $expenseItems = $itemsByVoucher->get($header->id, collect())->values()->map(function ($item) {
                return [
                    'id' => (int) $item->id,
                    'particularItem' => (string) ($item->particular_item ?? ''),
                    'unit' => $item->unit,
                    'qty' => (float) ($item->qty ?? 0),
                    'unitPrice' => (float) ($item->unit_price ?? 0),
                    'amount' => (float) ($item->amount ?? 0),
                    'sortOrder' => (int) ($item->sort_order ?? 0),
                ];
            });

            $bankDetails = $banksByVoucher->get($header->id, collect())->values()->map(function ($bank) {
                return [
                    'id' => (int) $bank->id,
                    'bankName' => (string) ($bank->bank_name ?? ''),
                    'checkNo' => $bank->check_no,
                    'checkDate' => $bank->check_date,
                    'creditAmount' => (float) ($bank->credit_amount ?? 0),
                    'sortOrder' => (int) ($bank->sort_order ?? 0),
                ];
            });

            $totalAmount = $expenseItems->isNotEmpty()
                ? round((float) $expenseItems->sum('amount'), 2)
                : round((float) ($header->amount ?? 0), 2);

            $checkDates = $bankDetails->pluck('checkDate')->filter()->implode(' ');
            $bankNames = $bankDetails->pluck('bankName')->filter()->implode(' ');
            $checkNos = $bankDetails->pluck('checkNo')->filter()->implode(' ');
            $checkAmounts = $bankDetails->pluck('creditAmount')->map(fn ($amount) => number_format((float) $amount, 2, '.', '') . ' ' . number_format((float) $amount, 2))->implode(' ');

            return [
                'id' => (int) $header->id,
                'voucherNo' => (string) $header->voucher_no,
                'supplierId' => (int) ($header->supplier_id ?? 0),
                'supplierCode' => (string) ($header->supplier_code ?? ''),
                'supplierName' => (string) ($header->supplier_name ?? ''),
                'particular' => (string) ($header->particulars ?? ''),
                'remarks' => (string) ($header->ref ?? ''),
                'date' => $header->billing_date ?: (!empty($header->created_at) ? substr((string) $header->created_at, 0, 10) : null),
                'totalAmount' => $totalAmount,
                'totalCreditAmount' => round((float) $bankDetails->sum('creditAmount'), 2),
                'expenseItems' => $expenseItems->all(),
                'bankDetails' => $bankDetails->all(),
                'checkDateSearch' => $checkDates,
                'bankSearch' => $bankNames,
                'checkNoSearch' => $checkNos,
                'checkAmountSearch' => $checkAmounts,
            ];
        })->values();

        $maxNum = $connection->table('expense_cheque_vouchers')
            ->max(DB::raw("CAST(SUBSTRING(voucher_no, 5) AS UNSIGNED)"));
        $nextVoucherNo = 'ECV-' . str_pad(((int) $maxNum) + 1, 4, '0', STR_PAD_LEFT);

        return response()->json([
            'success' => true,
            'vouchers' => $vouchers,
            'nextVoucherNo' => $nextVoucherNo,
        ]);
    } catch (\Throwable $e) {
        Log::error('Expense cheque voucher V2 data error: ' . $e->getMessage());
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.expense-cheque-voucher.v2.data');

Route::post('/admin/accounting/expense-cheque-voucher/v2/store', function (Request $request) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

    $data = $request->validate([
        'voucher_no' => 'required|string|max:50',
        'supplier_id' => 'required|integer',
        'supplier_code' => 'required|string|max:255',
        'supplier_name' => 'required|string|max:255',
        'particular' => 'required|string|max:1000',
        'ref' => 'nullable|string|max:255',
        'date' => 'required|date',
        'expense_items' => 'required|array|min:1',
        'expense_items.*.particular_item' => 'required|string|max:1000',
        'expense_items.*.unit' => 'nullable|string|max:50',
        'expense_items.*.qty' => 'required|numeric|gt:0',
        'expense_items.*.unit_price' => 'required|numeric|min:0',
        'bank_details' => 'nullable|array',
        'bank_details.*.bank_name' => 'nullable|string|max:255',
        'bank_details.*.check_no' => 'nullable|string|max:255',
        'bank_details.*.check_date' => 'nullable|date',
        'bank_details.*.credit_amount' => 'required|numeric',
    ]);

    try {
        if (!hatdogExpenseChequeVoucherV2TablesReady()) {
            return response()->json(['success' => false, 'message' => 'Expense Voucher V2 database tables are missing. Run the provided SQL command first.'], 422);
        }

        $connection = DB::connection('accounting');
        $connection->beginTransaction();
        $now = now();

        $duplicate = $connection->table('expense_cheque_vouchers')
            ->where('voucher_no', $data['voucher_no'])
            ->lockForUpdate()
            ->first();
        if ($duplicate) {
            throw new \RuntimeException('Voucher number ' . $data['voucher_no'] . ' already exists. Refresh the page and try again.');
        }

        $expenseItems = collect($data['expense_items'])->values()->map(function ($item, $index) {
            $qty = (float) $item['qty'];
            $unitPrice = (float) $item['unit_price'];
            return [
                'particular_item' => trim((string) $item['particular_item']),
                'unit' => isset($item['unit']) && trim((string) $item['unit']) !== '' ? trim((string) $item['unit']) : null,
                'qty' => $qty,
                'unit_price' => $unitPrice,
                'amount' => round($qty * $unitPrice, 2),
                'sort_order' => $index + 1,
            ];
        });
        $bankDetails = collect($data['bank_details'] ?? [])->values();
        $totalAmount = round((float) $expenseItems->sum('amount'), 2);
        $totalCredit = round((float) $bankDetails->sum(fn ($bank) => (float) ($bank['credit_amount'] ?? 0)), 2);
        $firstBank = $bankDetails->first();

        $voucherId = $connection->table('expense_cheque_vouchers')->insertGetId([
            'voucher_no' => $data['voucher_no'],
            'expense_type' => 'One time',
            'supplier_id' => $data['supplier_id'],
            'supplier_code' => $data['supplier_code'],
            'supplier_name' => $data['supplier_name'],
            'ref' => $data['ref'] ?? null,
            'particulars' => $data['particular'],
            'billing_date' => $data['date'],
            'amount' => $totalAmount,
            'paid_amount' => $totalCredit,
            'payment_method' => $firstBank ? 'Bank' : 'Cash',
            'account_no' => $firstBank['bank_name'] ?? null,
            'check_date' => $firstBank['check_date'] ?? null,
            'check_no' => $firstBank['check_no'] ?? null,
            'status' => 'Posted',
            'created_at' => $now,
            'updated_at' => $now,
        ]);

        foreach ($expenseItems as $item) {
            $connection->table('expense_cheque_voucher_items')->insert([
                'expense_cheque_voucher_id' => $voucherId,
                'legacy_particular_id' => null,
                ...$item,
                'created_at' => $now,
                'updated_at' => $now,
            ]);
        }

        foreach ($bankDetails as $index => $bank) {
            $connection->table('expense_cheque_voucher_bank_details')->insert([
                'expense_cheque_voucher_id' => $voucherId,
                'legacy_particular_id' => null,
                'bank_name' => trim((string) ($bank['bank_name'] ?? '')),
                'check_no' => $bank['check_no'] ?? null,
                'check_date' => $bank['check_date'] ?? null,
                'credit_amount' => round((float) $bank['credit_amount'], 2),
                'sort_order' => $index + 1,
                'created_at' => $now,
                'updated_at' => $now,
            ]);
        }

        $connection->commit();

        $actor = hatdogAuditActor($user);
        $supplier = \App\Models\Supplier::on('masterlist')->find($data['supplier_id']);
        hatdogWriteAuditTrail([
            'module' => 'expense_cheque_voucher',
            'action' => 'Created V2',
            'source_connection' => 'accounting',
            'source_table' => 'expense_cheque_vouchers',
            'source_id' => $voucherId,
            'display_id' => (string) $data['voucher_no'],
            'record_name' => trim((string) $data['supplier_name']),
            'user_name' => $actor['name'],
            'user_identifier' => $actor['identifier'],
            'audit_data' => [
                'supplier' => $supplier?->toArray(),
                'particular' => $data['particular'],
                'ref' => $data['ref'] ?? null,
                'date' => $data['date'],
                'total_amount' => $totalAmount,
                'expense_items' => $expenseItems->all(),
                'bank_details' => $bankDetails->all(),
            ],
        ]);

        return response()->json(['success' => true, 'voucher_id' => $voucherId]);
    } catch (\Throwable $e) {
        if (isset($connection) && $connection->transactionLevel() > 0) $connection->rollBack();
        Log::error('Expense cheque voucher V2 store error: ' . $e->getMessage());
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.expense-cheque-voucher.v2.store');

Route::put('/admin/accounting/expense-cheque-voucher/v2/update/{id}', function (Request $request, $id) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

    $data = $request->validate([
        'voucher_no' => 'required|string|max:50',
        'supplier_id' => 'required|integer',
        'supplier_code' => 'required|string|max:255',
        'supplier_name' => 'required|string|max:255',
        'particular' => 'required|string|max:1000',
        'ref' => 'nullable|string|max:255',
        'date' => 'required|date',
        'expense_items' => 'required|array|min:1',
        'expense_items.*.particular_item' => 'required|string|max:1000',
        'expense_items.*.unit' => 'nullable|string|max:50',
        'expense_items.*.qty' => 'required|numeric|gt:0',
        'expense_items.*.unit_price' => 'required|numeric|min:0',
        'bank_details' => 'nullable|array',
        'bank_details.*.bank_name' => 'nullable|string|max:255',
        'bank_details.*.check_no' => 'nullable|string|max:255',
        'bank_details.*.check_date' => 'nullable|date',
        'bank_details.*.credit_amount' => 'required|numeric',
    ]);

    try {
        if (!hatdogExpenseChequeVoucherV2TablesReady()) {
            return response()->json(['success' => false, 'message' => 'Expense Voucher V2 database tables are missing. Run the provided SQL command first.'], 422);
        }

        $connection = DB::connection('accounting');
        $connection->beginTransaction();
        $now = now();

        $voucher = $connection->table('expense_cheque_vouchers')->where('id', $id)->lockForUpdate()->first();
        if (!$voucher) {
            $connection->rollBack();
            return response()->json(['success' => false, 'message' => 'Voucher not found.'], 404);
        }
        if ((string) $voucher->voucher_no !== (string) $data['voucher_no']) {
            throw new \RuntimeException('Voucher number cannot be changed.');
        }

        $beforeItems = $connection->table('expense_cheque_voucher_items')->where('expense_cheque_voucher_id', $id)->orderBy('sort_order')->orderBy('id')->get();
        $beforeBanks = $connection->table('expense_cheque_voucher_bank_details')->where('expense_cheque_voucher_id', $id)->orderBy('sort_order')->orderBy('id')->get();

        $expenseItems = collect($data['expense_items'])->values()->map(function ($item, $index) {
            $qty = (float) $item['qty'];
            $unitPrice = (float) $item['unit_price'];
            return [
                'particular_item' => trim((string) $item['particular_item']),
                'unit' => isset($item['unit']) && trim((string) $item['unit']) !== '' ? trim((string) $item['unit']) : null,
                'qty' => $qty,
                'unit_price' => $unitPrice,
                'amount' => round($qty * $unitPrice, 2),
                'sort_order' => $index + 1,
            ];
        });
        $bankDetails = collect($data['bank_details'] ?? [])->values();
        $totalAmount = round((float) $expenseItems->sum('amount'), 2);
        $totalCredit = round((float) $bankDetails->sum(fn ($bank) => (float) ($bank['credit_amount'] ?? 0)), 2);
        $firstBank = $bankDetails->first();

        $connection->table('expense_cheque_voucher_items')->where('expense_cheque_voucher_id', $id)->delete();
        $connection->table('expense_cheque_voucher_bank_details')->where('expense_cheque_voucher_id', $id)->delete();

        foreach ($expenseItems as $item) {
            $connection->table('expense_cheque_voucher_items')->insert([
                'expense_cheque_voucher_id' => (int) $id,
                'legacy_particular_id' => null,
                ...$item,
                'created_at' => $now,
                'updated_at' => $now,
            ]);
        }
        foreach ($bankDetails as $index => $bank) {
            $connection->table('expense_cheque_voucher_bank_details')->insert([
                'expense_cheque_voucher_id' => (int) $id,
                'legacy_particular_id' => null,
                'bank_name' => trim((string) ($bank['bank_name'] ?? '')),
                'check_no' => $bank['check_no'] ?? null,
                'check_date' => $bank['check_date'] ?? null,
                'credit_amount' => round((float) $bank['credit_amount'], 2),
                'sort_order' => $index + 1,
                'created_at' => $now,
                'updated_at' => $now,
            ]);
        }

        $connection->table('expense_cheque_vouchers')->where('id', $id)->update([
            'expense_type' => 'One time',
            'supplier_id' => $data['supplier_id'],
            'supplier_code' => $data['supplier_code'],
            'supplier_name' => $data['supplier_name'],
            'ref' => $data['ref'] ?? null,
            'particulars' => $data['particular'],
            'billing_date' => $data['date'],
            'amount' => $totalAmount,
            'paid_amount' => $totalCredit,
            'payment_method' => $firstBank ? 'Bank' : 'Cash',
            'account_no' => $firstBank['bank_name'] ?? null,
            'check_date' => $firstBank['check_date'] ?? null,
            'check_no' => $firstBank['check_no'] ?? null,
            'updated_at' => $now,
        ]);

        $updatedVoucher = $connection->table('expense_cheque_vouchers')->where('id', $id)->first();
        $connection->commit();

        $actor = hatdogAuditActor($user);
        $supplier = \App\Models\Supplier::on('masterlist')->find($data['supplier_id']);
        hatdogWriteAuditTrail([
            'module' => 'expense_cheque_voucher',
            'action' => 'Updated V2',
            'source_connection' => 'accounting',
            'source_table' => 'expense_cheque_vouchers',
            'source_id' => (int) $id,
            'display_id' => (string) $voucher->voucher_no,
            'record_name' => trim((string) $data['supplier_name']),
            'user_name' => $actor['name'],
            'user_identifier' => $actor['identifier'],
            'audit_data' => [
                'before' => (array) $voucher,
                'before_expense_items' => $beforeItems->map(fn ($row) => (array) $row)->all(),
                'before_bank_details' => $beforeBanks->map(fn ($row) => (array) $row)->all(),
                'after' => $updatedVoucher ? (array) $updatedVoucher : null,
                'expense_items' => $expenseItems->all(),
                'bank_details' => $bankDetails->all(),
                'supplier' => $supplier?->toArray(),
            ],
        ]);

        return response()->json(['success' => true]);
    } catch (\Throwable $e) {
        if (isset($connection) && $connection->transactionLevel() > 0) $connection->rollBack();
        Log::error('Expense cheque voucher V2 update error: ' . $e->getMessage());
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.expense-cheque-voucher.v2.update');

