Route::get('/admin/accounting/payable-cheque-voucher/data', function (Request $request) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

    try {
        $invoiceSearch = trim((string) $request->input('invoice', ''));

        $paidRows = DB::connection('accounting')->table('payable_cheque_voucher_invoices')
            ->select('purchase_order_id', DB::raw('SUM(amount_paid + COALESCE(amount_due * discount_1 / 100, 0) + COALESCE(amount_due * discount_2 / 100, 0)) as paid_total'))
            ->whereNotNull('purchase_order_id')
            ->groupBy('purchase_order_id')
            ->get()
            ->keyBy('purchase_order_id');
        $srTotals = DB::connection('accounting')->table('payable_cheque_voucher_sudden_returns as sr')
            ->join('payable_cheque_voucher_invoices as i', 'sr.payable_cheque_voucher_invoice_id', '=', 'i.id')
            ->select('i.purchase_order_id', DB::raw('COALESCE(SUM(sr.return_amount), 0) as sr_total'))
            ->groupBy('i.purchase_order_id')
            ->get()
            ->keyBy('purchase_order_id');
        foreach ($srTotals as $poId => $sr) {
            if ($paidRows->has($poId)) {
                $paidRows[$poId]->paid_total += $sr->sr_total;
            } else {
                $paidRows->put($poId, (object) ['purchase_order_id' => $poId, 'paid_total' => $sr->sr_total]);
            }
        }
        $itemTotals = DB::connection('purchase')->table('purchase_order_items')
            ->select('purchase_order_id', DB::raw('SUM(COALESCE(NULLIF(actual_subtotal, 0), subtotal, 0)) as item_total'))
            ->groupBy('purchase_order_id')
            ->get()
            ->keyBy('purchase_order_id');

        $orders = DB::connection('purchase')->table('purchase_orders')
            ->whereNotIn('status', ['Cancelled', 'Void'])
            ->where('supplier_id', '>', 0)
            ->when($invoiceSearch !== '', function ($query) use ($invoiceSearch) {
                $query->where('supplier_invoice_number', 'like', '%' . $invoiceSearch . '%');
            })
            ->select('id', 'po_number', 'supplier_invoice_number', 'supplier_id', 'date', 'total_amount', 'actual_total_amount', 'status', 'created_at')
            ->get();

        $returnTotals = DB::connection('purchase')->table('purchase_returns')
            ->select('po_id', DB::raw('COALESCE(SUM(total_amount), 0) as return_amount'))
            ->whereIn('po_id', $orders->pluck('id'))
            ->groupBy('po_id')
            ->get()
            ->keyBy('po_id');

        $usedReturnKeys = hatdogUsedPurchaseReturnKeys($orders->pluck('id'));
        $unusedReturnPoIds = DB::connection('purchase')->table('purchase_returns')
            ->whereIn('po_id', $orders->pluck('id'))
            ->get(['po_id', 'return_number'])
            ->filter(function ($row) use ($usedReturnKeys) {
                $key = (int) $row->po_id . '|' . hatdogNormalizeLookupKey($row->return_number ?? '');
                return !isset($usedReturnKeys[$key]);
            })
            ->pluck('po_id')
            ->map(fn ($id) => (int) $id)
            ->unique()
            ->values()
            ->all();

        $orders = $orders
            ->map(function ($order) use ($paidRows, $itemTotals, $returnTotals, $unusedReturnPoIds) {
                $amount = (float) ($order->actual_total_amount ?: $order->total_amount ?: ($itemTotals->get($order->id)->item_total ?? 0));
                $paid = (float) ($paidRows->get($order->id)->paid_total ?? 0);
                $returnAmt = (float) ($returnTotals->get($order->id)->return_amount ?? 0);
                $order->invoice_amount = $amount;
                $order->paid_amount = $paid;
                $order->due_amount = max($amount - $paid - $returnAmt, 0);
                $order->has_unused_return = in_array((int) $order->id, $unusedReturnPoIds, true);
                return $order;
            })
            ->filter(fn ($order) => $order->invoice_amount > 0 && ((float) $order->due_amount > 0 || $order->has_unused_return));

        $supplierIds = $orders->pluck('supplier_id')->filter()->unique()->values();
        $suppliers = DB::connection('masterlist')->table('suppliers')
            ->whereIn('id', $supplierIds)
            ->get()
            ->keyBy('id');

        $agingStats = ['30' => 0, '60' => 0, '90' => 0, '120' => 0, '150' => 0];
        $today = now()->startOfDay();

        $supplierIdsWithSudden = $orders
            ->filter(fn ($order) => !empty($order->has_unused_return))
            ->pluck('supplier_id')
            ->map(fn ($id) => (int) $id)
            ->unique()
            ->values()
            ->all();

        $fiveMonthsAgo = now()->subMonths(5)->startOfDay();

        $rows = $orders
            ->groupBy('supplier_id')
            ->map(function ($docs, $supplierId) use ($suppliers, &$agingStats, $today, $supplierIdsWithSudden, $fiveMonthsAgo) {
                $supplier = $suppliers->get($supplierId);
                if (!$supplier) return null;

                $oldest = $docs->sortBy(fn ($doc) => $doc->date ?: $doc->created_at)->first();
                $ageDays = $oldest && ($oldest->date || $oldest->created_at)
                    ? \Carbon\Carbon::parse($oldest->date ?: $oldest->created_at)->startOfDay()->diffInDays($today)
                    : 0;
                $bucket = match (true) {
                    $ageDays <= 31 => '30',
                    $ageDays <= 61 => '60',
                    $ageDays <= 91 => '90',
                    $ageDays <= 121 => '120',
                    default => '150',
                };
                $agingStats[$bucket]++;

                return [
                    'id' => $supplier->id,
                    'supplier' => $supplier->name,
                    'contact' => $supplier->contact_number,
                    'contactPerson' => $supplier->contact_person,
                    'address' => $supplier->address,
                    'notPaid' => $docs->filter(fn ($doc) => (float) $doc->paid_amount <= 0)->count(),
                    'partialPaid' => $docs->filter(fn ($doc) => (float) $doc->paid_amount > 0 && (float) $doc->due_amount > 0)->count(),
                    'totalAmount' => round($docs->sum('due_amount'), 2),
                    'aging' => (int) $bucket,
                    'hasOldInvoices' => $docs->contains(function ($doc) use ($fiveMonthsAgo) {
                        $docDate = $doc->date ?: $doc->created_at;
                        return $docDate
                            && (float) ($doc->due_amount ?? 0) > 0
                            && \Carbon\Carbon::parse($docDate)->lt($fiveMonthsAgo);
                    }),
                    'hasSuddenReturns' => in_array((int) $supplier->id, $supplierIdsWithSudden),
                    'invoices' => [],
                ];
            })
            ->filter()
            ->sortBy('supplier')
            ->values();

        return response()->json([
            'success' => true,
            'suppliers' => $rows,
            'aging_stats' => $agingStats,
        ]);
    } catch (\Throwable $e) {
        Log::error('Payable cheque voucher data error: ' . $e->getMessage());
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.payable-cheque-voucher.data');

Route::get('/admin/accounting/payable-cheque-voucher/returns/{poId}', function ($poId) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

    try {
        $returns = DB::connection('purchase')->table('purchase_returns')
            ->where('po_id', $poId)
            ->orderBy('date', 'desc')
            ->get();
        $orderInfo = DB::connection('purchase')->table('purchase_orders')
            ->where('id', $poId)
            ->first(['id', 'po_number', 'supplier_invoice_number']);

        $returnIds = $returns->pluck('id');

        $items = collect();
        if ($returnIds->isNotEmpty()) {
            $items = hatdogEnrichPurchaseReturnItems(
                DB::connection('purchase')->table('purchase_return_items')
                    ->whereIn('purchase_return_items.purchase_return_id', $returnIds)
                    ->select(
                        'purchase_return_items.purchase_return_id',
                        'purchase_return_items.product_id',
                        'purchase_return_items.product_code',
                        'purchase_return_items.description',
                        'purchase_return_items.quantity',
                        'purchase_return_items.unit_price',
                        'purchase_return_items.subtotal'
                    )
                    ->orderBy('purchase_return_items.id')
                    ->get()
            )->groupBy('purchase_return_id');
        }

        $supplierId = $returns->first() ? DB::connection('purchase')->table('purchase_orders')
            ->where('id', $poId)->value('supplier_id') : null;

        $supplierName = $supplierId ? DB::connection('masterlist')->table('suppliers')
            ->where('id', $supplierId)->value('name') : null;

        $result = $returns->map(function ($ret) use ($items, $orderInfo) {
            return [
                'id' => $ret->id,
                'po_id' => $ret->po_id,
                'po_number' => $orderInfo->po_number ?? '---',
                'invoice_no' => $orderInfo->supplier_invoice_number ?: ($orderInfo->po_number ?? '---'),
                'return_number' => $ret->return_number,
                'date' => $ret->date,
                'total_amount' => (float) $ret->total_amount,
                'remarks' => $ret->remarks,
                'items' => ($items->get($ret->id) ?? collect())->map(function ($item) {
                    return [
                        'product_code' => (string) ($item->product_code ?? ''),
                        'product_name' => $item->product_name,
                        'part_number' => $item->part_number,
                        'description' => $item->description,
                        'application' => $item->application,
                        'quantity' => (float) ($item->quantity ?? 0),
                        'unit_price' => (float) ($item->unit_price ?? 0),
                        'subtotal' => (float) ($item->subtotal ?? 0),
                        'amount' => (float) ($item->subtotal ?? 0),
                    ];
                })->values()->all(),
            ];
        })->values()->all();

        return response()->json([
            'success' => true,
            'supplier_name' => $supplierName,
            'returns' => $result,
        ]);
    } catch (\Throwable $e) {
        Log::error('Payable cheque voucher returns error: ' . $e->getMessage());
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.payable-cheque-voucher.returns');

Route::get('/admin/accounting/payable-cheque-voucher/sudden-returns/{supplierId}', function (Request $request, $supplierId) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

    try {
        // LOG: Capture the request
        \Log::info('=== SUDDEN RETURNS API REQUEST ===');
        \Log::info('Request URL: ' . $request->fullUrl());
        \Log::info('Supplier ID: ' . $supplierId);
        \Log::info('PO IDs from request: ' . json_encode($request->input('po_ids', [])));
        
        $supplier = DB::connection('masterlist')->table('suppliers')->where('id', $supplierId)->first();
        if (!$supplier) throw new \Exception('Supplier not found.');

        // Get current voucher's PO IDs from request (if creating new voucher)
        $currentPoIds = $request->input('po_ids', []);
        
        $currentPoIds = collect($currentPoIds)
            ->map(fn ($id) => (int) $id)
            ->filter()
            ->unique()
            ->values()
            ->all();

        // If no PO IDs are provided, fall back to this supplier's active POs.
        // A supplier can have several invoices for one purchase note, and the
        // return may belong to an invoice that has not been paid by PCV yet.
        if (empty($currentPoIds)) {
            $currentPoIds = DB::connection('purchase')->table('purchase_orders')
                ->where('supplier_id', $supplierId)
                ->whereNotIn('status', ['Cancelled', 'Void'])
                ->pluck('id')
                ->toArray();
        }

        $voucherId = $request->input('voucher_id');
        if ($voucherId) {
            // Edit mode: exclude return numbers used by OTHER vouchers, but include those used by this voucher
            $usedByOtherVouchers = DB::connection('accounting')->table('payable_cheque_voucher_sudden_returns as sr')
                ->join('payable_cheque_voucher_invoices as inv', 'sr.payable_cheque_voucher_invoice_id', '=', 'inv.id')
                ->where('inv.payable_cheque_voucher_id', '!=', $voucherId)
                ->pluck('sr.return_number')
                ->unique()
                ->values()
                ->all();
        } else {
            $usedReturnNumbers = DB::connection('accounting')->table('payable_cheque_voucher_invoices')
                ->whereNotNull('return_number')
                ->where('return_number', '!=', '')
                ->pluck('return_number')
                ->flatMap(fn ($v) => array_map('trim', explode(',', $v)))
                ->filter()
                ->unique()
                ->values()
                ->all();
        }

        $returns = collect();
        if (!empty($currentPoIds)) {
            $retQuery = DB::connection('purchase')->table('purchase_returns')
                ->whereIn('po_id', $currentPoIds)  // Only from current voucher's POs!
                ->orderBy('date', 'desc');
            if ($voucherId) {
                if (!empty($usedByOtherVouchers)) {
                    $retQuery = $retQuery->whereNotIn('return_number', $usedByOtherVouchers);
                }
            } else {
                if (!empty($usedReturnNumbers)) {
                    $retQuery = $retQuery->whereNotIn('return_number', $usedReturnNumbers);
                }
            }
            $returns = $retQuery->get();
        }

        $returnIds = $returns->pluck('id');

        $items = collect();
        if ($returnIds->isNotEmpty()) {
            $items = hatdogEnrichPurchaseReturnItems(
                DB::connection('purchase')->table('purchase_return_items')
                    ->whereIn('purchase_return_items.purchase_return_id', $returnIds)
                    ->select(
                        'purchase_return_items.purchase_return_id',
                        'purchase_return_items.product_id',
                        'purchase_return_items.product_code',
                        'purchase_return_items.description',
                        'purchase_return_items.quantity',
                        'purchase_return_items.unit_price',
                        'purchase_return_items.subtotal'
                    )
                    ->orderBy('purchase_return_items.id')
                    ->get()
            )->groupBy('purchase_return_id');
        }

        $ordersById = DB::connection('purchase')->table('purchase_orders')
            ->whereIn('id', $currentPoIds)
            ->get(['id', 'po_number', 'supplier_invoice_number'])
            ->keyBy('id');

        $result = $returns->map(function ($ret) use ($items, $ordersById) {
            $order = $ordersById->get($ret->po_id);
            return [
                'id' => $ret->id,
                'po_id' => $ret->po_id,
                'po_number' => $order->po_number ?? '---',
                'invoice_no' => $order ? ($order->supplier_invoice_number ?: $order->po_number) : '---',
                'return_number' => $ret->return_number,
                'date' => $ret->date,
                'total_amount' => (float) $ret->total_amount,
                'remarks' => $ret->remarks,
                'items' => ($items->get($ret->id) ?? collect())->map(function ($item) {
                    return [
                        'product_code' => (string) ($item->product_code ?? ''),
                        'product_name' => $item->product_name,
                        'part_number' => $item->part_number,
                        'description' => $item->description,
                        'application' => $item->application,
                        'quantity' => (float) ($item->quantity ?? 0),
                        'unit_price' => (float) ($item->unit_price ?? 0),
                        'subtotal' => (float) ($item->subtotal ?? 0),
                        'amount' => (float) ($item->subtotal ?? 0),
                    ];
                })->values()->all(),
            ];
        })->values()->all();

        // LOG: Capture the response
        \Log::info('API Response - Returned PO IDs: ' . json_encode(array_unique(array_column($result, 'po_id'))));
        \Log::info('API Response - Return Count: ' . count($result));
        \Log::info('API Response Data: ' . json_encode($result));
        \Log::info('=== SUDDEN RETURNS API RESPONSE END ===');

        return response()->json([
            'success' => true,
            'supplier_name' => $supplier->name,
            'returns' => $result,
        ]);
    } catch (\Throwable $e) {
        Log::error('Payable cheque voucher sudden returns error: ' . $e->getMessage());
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.payable-cheque-voucher.sudden-returns');

