Route::get('/admin/accounting/payable-cheque-voucher/history/supplier/{supplierId}/vouchers', function ($supplierId) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);
    try {
        // Get all vouchers for this supplier
        $vouchers = DB::connection('accounting')->table('payable_cheque_vouchers')
            ->where('supplier_id', $supplierId)
            ->where('is_draft', false)
            ->orderBy('voucher_date', 'desc')
            ->get();

        // Check which vouchers have sudden returns
        $voucherIds = $vouchers->pluck('id');
        $vouchersWithSuddenReturns = DB::connection('accounting')->table('payable_cheque_voucher_sudden_returns')
            ->whereIn('payable_cheque_voucher_id', $voucherIds)
            ->select('payable_cheque_voucher_id')
            ->distinct()
            ->pluck('payable_cheque_voucher_id')
            ->toArray();

        // Get invoice totals per voucher
        $invoiceTotals = DB::connection('accounting')->table('payable_cheque_voucher_invoices')
            ->whereIn('payable_cheque_voucher_id', $voucherIds)
            ->select(
                'payable_cheque_voucher_id',
                DB::raw('COUNT(*) as total_invoices'),
                DB::raw('COALESCE(SUM(amount_paid), 0) as total_amount')
            )
            ->groupBy('payable_cheque_voucher_id')
            ->get()
            ->keyBy('payable_cheque_voucher_id');

        $rows = $vouchers->map(function ($v) use ($vouchersWithSuddenReturns, $invoiceTotals) {
            $totals = $invoiceTotals->get($v->id);
            return [
                'id' => $v->id,
                'voucher_no' => $v->voucher_no,
                'voucher_date' => $v->voucher_date,
                'total_invoices' => (int) ($totals->total_invoices ?? 0),
                'total_amount' => (float) ($totals->total_amount ?? 0),
                'has_sudden_returns' => in_array($v->id, $vouchersWithSuddenReturns),
            ];
        })->values();

        return response()->json(['success' => true, 'vouchers' => $rows]);
    } catch (\Throwable $e) {
        Log::error('Supplier vouchers fetch error: ' . $e->getMessage());
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.payable-cheque-voucher.supplier-vouchers');

