Route::get('/admin/accounting/payable-cheque-voucher/supplier/{supplierId}', function (Request $request, $supplierId) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

    $voucherId = $request->input('voucher_id');

    try {
        $supplier = DB::connection('masterlist')->table('suppliers')->where('id', $supplierId)->first();
        if (!$supplier) throw new \Exception('Supplier not found.');

        $paidRows = DB::connection('accounting')->table('payable_cheque_voucher_invoices')
            ->select('purchase_order_id', DB::raw('SUM(amount_paid + COALESCE(amount_due * discount_1 / 100, 0) + COALESCE(amount_due * discount_2 / 100, 0)) as paid_total'))
            ->whereNotNull('purchase_order_id')
            ->groupBy('purchase_order_id')
            ->get()
            ->keyBy('purchase_order_id');
        $srTotals = DB::connection('accounting')->table('payable_cheque_voucher_sudden_returns as sr')
            ->join('payable_cheque_voucher_invoices as i', 'sr.payable_cheque_voucher_invoice_id', '=', 'i.id')
            ->select('i.purchase_order_id', DB::raw('COALESCE(SUM(sr.return_amount), 0) as sr_total'))
            ->groupBy('i.purchase_order_id')
            ->get()
            ->keyBy('purchase_order_id');
        foreach ($srTotals as $poId => $sr) {
            if ($paidRows->has($poId)) {
                $paidRows[$poId]->paid_total += $sr->sr_total;
            } else {
                $paidRows->put($poId, (object) ['purchase_order_id' => $poId, 'paid_total' => $sr->sr_total]);
            }
        }
        $itemTotals = DB::connection('purchase')->table('purchase_order_items')
            ->select('purchase_order_id', DB::raw('SUM(COALESCE(NULLIF(actual_subtotal, 0), subtotal, 0)) as item_total'))
            ->groupBy('purchase_order_id')
            ->get()
            ->keyBy('purchase_order_id');

        $orders = DB::connection('purchase')->table('purchase_orders')
            ->where('supplier_id', $supplierId)
            ->whereNotIn('status', ['Cancelled', 'Void'])
            ->select('id', 'po_number', 'supplier_invoice_number', 'date', 'total_amount', 'actual_total_amount', 'status')
            ->orderBy('date', 'desc')
            ->get();

        $orderIds = $orders->pluck('id');

        // All Purchase Return rows are read from purchase. Used-return keys are
        // read separately from accounting and matched in Laravel by (PO, return no.).
        $hasPurchaseReturnSlipNo = Schema::connection('purchase')->hasColumn('purchase_returns', 'slip_no');
        $returnColumns = ['id', 'po_id', 'return_number', 'total_amount'];
        if ($hasPurchaseReturnSlipNo) {
            $returnColumns[] = 'slip_no';
        }

        $allReturnRows = DB::connection('purchase')->table('purchase_returns')
            ->whereIn('po_id', $orderIds)
            ->orderBy('id')
            ->get($returnColumns);

        $allReturnTotals = $allReturnRows->groupBy(fn ($row) => (int) $row->po_id)
            ->map(fn ($rows, $poId) => (object) [
                'po_id' => (int) $poId,
                'return_amount' => (float) $rows->sum(fn ($row) => (float) ($row->total_amount ?? 0)),
                'total_returns' => $rows->count(),
            ]);

        $usedReturnKeys = hatdogUsedPurchaseReturnKeys($orderIds);
        $unusedReturnRows = $allReturnRows->filter(function ($row) use ($usedReturnKeys) {
            $key = (int) $row->po_id . '|' . hatdogNormalizeLookupKey($row->return_number ?? '');
            return !isset($usedReturnKeys[$key]);
        })->values();

        $unusedReturnTotals = $unusedReturnRows->groupBy(fn ($row) => (int) $row->po_id)
            ->map(fn ($rows, $poId) => (object) [
                'po_id' => (int) $poId,
                'return_amount' => (float) $rows->sum(fn ($row) => (float) ($row->total_amount ?? 0)),
                'total_returns' => $rows->count(),
            ]);

        $unusedReturnNumbers = $unusedReturnRows->groupBy(fn ($row) => (int) $row->po_id)
            ->map(function ($rows, $poId) use ($hasPurchaseReturnSlipNo) {
                return (object) [
                    'po_id' => (int) $poId,
                    'return_numbers' => $rows->pluck('return_number')
                        ->map(fn ($value) => trim((string) ($value ?? '')))
                        ->filter()->implode(', '),
                    'slip_nos' => $hasPurchaseReturnSlipNo
                        ? $rows->pluck('slip_no')->map(fn ($value) => trim((string) ($value ?? '')))->filter()->implode(', ')
                        : '',
                ];
            });

        $invoices = $orders
            ->map(function ($order) use ($paidRows, $itemTotals, $allReturnTotals, $unusedReturnTotals, $unusedReturnNumbers) {
                $allReturnData = $allReturnTotals->get($order->id);
                $allReturnAmount = (float) ($allReturnData->return_amount ?? 0);
                $unusedData = $unusedReturnTotals->get($order->id);
                $unusedReturnAmount = (float) ($unusedData->return_amount ?? 0);
                $unusedCount = (int) ($unusedData->total_returns ?? 0);
                $amount = (float) ($order->actual_total_amount ?: $order->total_amount ?: ($itemTotals->get($order->id)->item_total ?? 0));
                $paidToDate = (float) ($paidRows->get($order->id)->paid_total ?? 0);
                // Use ALL returns for due calculation (returns reduce what we owe even if previously used)
                $due = max($amount - $paidToDate - $allReturnAmount, 0);

                return [
                    'id' => 'po-' . $order->id,
                    'sourceType' => 'purchase_order',
                    'sourceId' => $order->id,
                    'purchaseNo' => $order->po_number,
                    'invoiceNo' => $order->supplier_invoice_number ?: $order->po_number,
                    'invoiceAmount' => $amount,
                    'paidToDate' => $paidToDate,
                    'amountDue' => $due,
                    'returnAmount' => $unusedReturnAmount,
                    'totalReturns' => $unusedCount,
                    'unusedReturnAmount' => $unusedReturnAmount,
                    'unusedReturnCount' => $unusedCount,
                    'amountPaid' => 0,
                    'remarks' => $paidToDate > 0 ? 'Partial Paid' : 'Not Paid',
                    'rsDetails' => '',
                    'returnNumber' => $unusedReturnNumbers->get($order->id)->return_numbers ?? '',
                    'slipNo' => $unusedReturnNumbers->get($order->id)->slip_nos ?? '',
                    'date' => $order->date,
                ];
            })
            ->filter(fn ($invoice) => $invoice['amountDue'] > 0 || $invoice['unusedReturnAmount'] > 0 || $invoice['unusedReturnCount'] > 0)
            ->values()
            ->keyBy('sourceId');

        // If editing, merge in invoices already attached to this voucher (even if fully paid)
        if ($voucherId) {
            $existingInvoiceRows = DB::connection('accounting')->table('payable_cheque_voucher_invoices')
                ->where('payable_cheque_voucher_id', $voucherId)
                ->get();
            foreach ($existingInvoiceRows as $existing) {
                $sourceId = (int) $existing->purchase_order_id;
                if ($sourceId && $invoices->has($sourceId)) {
                    // Update existing record with the voucher's values
                    $existingData = $invoices->get($sourceId);
                    $existingData['amountPaid'] = (float) ($existing->amount_paid ?? 0);
                    $existingData['remarks'] = $existing->remarks ?? ($existingData['paidToDate'] > 0 ? 'Partial Paid' : 'Not Paid');
                    $existingData['discount1'] = (float) ($existing->discount_1 ?? 0);
                    $existingData['discount2'] = (float) ($existing->discount_2 ?? 0);
                    $existingData['rsDetails'] = $existing->rs_details ?? '';
                    $existingData['returnNumber'] = $existing->return_number ?? '';
                    if (!empty($existing->return_number) && Schema::connection('purchase')->hasColumn('purchase_returns', 'slip_no')) {
                        $existingReturnNumbers = collect(preg_split('/\s*,\s*/', (string) $existing->return_number, -1, PREG_SPLIT_NO_EMPTY) ?: [])
                            ->map(fn ($value) => trim((string) $value))
                            ->filter()
                            ->values();
                        $existingData['slipNo'] = $existingReturnNumbers->isEmpty() ? '' : DB::connection('purchase')->table('purchase_returns')
                            ->where('po_id', $sourceId)
                            ->whereIn('return_number', $existingReturnNumbers->all())
                            ->orderBy('id')
                            ->pluck('slip_no')
                            ->map(fn ($value) => trim((string) ($value ?? '')))
                            ->filter()
                            ->unique()
                            ->implode(', ');
                    }
                    // Keep it even if amountDue is 0 since it's already in this voucher
                    $invoices->put($sourceId, $existingData);
                } elseif ($sourceId) {
                    // Invoice is already paid in full via this voucher but not in open POs - add it back
                    $po = DB::connection('purchase')->table('purchase_orders')
                        ->where('id', $sourceId)
                        ->select('id', 'po_number', 'supplier_invoice_number', 'date', 'total_amount', 'actual_total_amount')
                        ->first();
                    if ($po) {
                        $amount = (float) ($po->actual_total_amount ?: $po->total_amount ?: 0);
                        // Check if this PO was already paid via OTHER vouchers
                        $otherPaidTotal = DB::connection('accounting')->table('payable_cheque_voucher_invoices')
                            ->where('purchase_order_id', $sourceId)
                            ->where('payable_cheque_voucher_id', '!=', $voucherId)
                            ->sum('amount_paid');
                        $otherSrTotal = DB::connection('accounting')->table('payable_cheque_voucher_sudden_returns as sr')
                            ->join('payable_cheque_voucher_invoices as inv', 'sr.payable_cheque_voucher_invoice_id', '=', 'inv.id')
                            ->where('inv.purchase_order_id', $sourceId)
                            ->where('inv.payable_cheque_voucher_id', '!=', $voucherId)
                            ->sum('sr.return_amount');
                        $totalOtherPaid = $otherPaidTotal + $otherSrTotal;
                        // Only include if NOT fully paid by other vouchers (prevent duplicate payment)
                        if ($totalOtherPaid < $amount) {
                            $invoices->put($sourceId, [
                                'id' => 'po-' . $sourceId,
                                'sourceType' => 'purchase_order',
                                'sourceId' => $sourceId,
                                'purchaseNo' => $po->po_number,
                                'invoiceNo' => $po->supplier_invoice_number ?: $po->po_number,
                                'invoiceAmount' => $amount,
                                'paidToDate' => (float) ($existing->amount_paid ?? 0) + $otherPaidTotal,
                                'amountDue' => max($amount - $totalOtherPaid, 0),
                                'returnAmount' => 0,
                                'totalReturns' => 0,
                                'amountPaid' => (float) ($existing->amount_paid ?? 0),
                                'remarks' => $existing->remarks ?? 'Paid',
                                'rsDetails' => $existing->rs_details ?? '',
                                'returnNumber' => $existing->return_number ?? '',
                                'slipNo' => (!empty($existing->return_number) && Schema::connection('purchase')->hasColumn('purchase_returns', 'slip_no'))
                                    ? DB::connection('purchase')->table('purchase_returns')
                                        ->where('po_id', $sourceId)
                                        ->whereIn('return_number', collect(preg_split('/\s*,\s*/', (string) $existing->return_number, -1, PREG_SPLIT_NO_EMPTY) ?: [])->map(fn ($value) => trim((string) $value))->filter()->all())
                                        ->orderBy('id')
                                        ->pluck('slip_no')
                                        ->map(fn ($value) => trim((string) ($value ?? '')))
                                        ->filter()
                                        ->unique()
                                        ->implode(', ')
                                    : '',
                                'date' => $po->date,
                                'discount1' => (float) ($existing->discount_1 ?? 0),
                                'discount2' => (float) ($existing->discount_2 ?? 0),
                            ]);
                        }
                    }
                }
            }
            // Also add any POs that are in this voucher but NOT in the supplier's open POs at all
            // (handled above by the else-if branch)
        }

        $invoices = $invoices->values();

        $maxNum = DB::connection('accounting')->table('payable_cheque_vouchers')
            ->max(DB::raw("CAST(SUBSTRING(voucher_no, 5) AS UNSIGNED)"));
        $voucherNo = 'PCV-' . str_pad(((int) $maxNum) + 1, 7, '0', STR_PAD_LEFT);

        return response()->json([
            'success' => true,
            'voucher_no' => $voucherNo,
            'supplier' => [
                'id' => $supplier->id,
                'supplier' => $supplier->name,
                'contact' => $supplier->contact_number,
                'contactPerson' => $supplier->contact_person,
                'address' => $supplier->address,
                'totalAmount' => round($invoices->sum('amountDue'), 2),
            ],
            'invoices' => $invoices,
        ]);
    } catch (\Throwable $e) {
        Log::error('Payable cheque voucher supplier error: ' . $e->getMessage());
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.payable-cheque-voucher.supplier');

Route::post('/admin/accounting/payable-cheque-voucher/process', function (Request $request) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

    // LOG: Capture the complete payload
    \Log::info('=== PROCESS VOUCHER REQUEST ===');
    \Log::info('Request URL: ' . $request->fullUrl());
    \Log::info('Selected Invoice PO IDs: ' . json_encode(array_column($request->input('invoices', []), 'sourceId')));
    \Log::info('Sudden Returns in Payload: ' . json_encode($request->input('sudden_returns', [])));
    \Log::info('Complete Payload: ' . json_encode($request->all()));


        $data = $request->validate([
            'supplier_id' => 'required|integer',
            'supplier_name' => 'required|string',
            'voucher_no' => 'required|string',
            'voucher_date' => 'required|date',
            'reference_no' => 'nullable|string',
            'particulars' => 'nullable|string',
            'payment_method' => 'required|string',
            'invoices' => 'required|array|min:1',
            'invoices.*.sourceId' => 'required|integer',
            'invoices.*.purchaseNo' => 'required|string',
            'invoices.*.invoiceNo' => 'required|string',
            'invoices.*.invoiceAmount' => 'required|numeric',
            'invoices.*.amountDue' => 'required|numeric',
            'invoices.*.amountPaid' => 'required|numeric|min:0',
            'invoices.*.remarks' => 'nullable|string',
            'invoices.*.discount1' => 'nullable|numeric|min:0|max:100',
            'invoices.*.discount2' => 'nullable|numeric|min:0|max:100',
            'invoices.*.returnAmount' => 'nullable|numeric',
            'invoices.*.totalReturns' => 'nullable|integer',
            'invoices.*.rsDetails' => 'nullable|string',
            'invoices.*.returnNumber' => 'nullable|string',
        'global_discount' => 'nullable|numeric|min:0|max:100',
        'global_discount_amount' => 'nullable|numeric',
        'additional_discount' => 'nullable|numeric|min:0',
        'additional_discount_amount' => 'nullable|numeric|min:0',
    // Old single-payment fields kept for backward compatibility.
'payment' => 'nullable|array',
'payment.payment_method' => 'nullable|string',
'payment.account_no' => 'nullable|string',
'payment.bank_name' => 'nullable|string',
'payment.check_no' => 'nullable|string',
'payment.check_date' => 'nullable|date',
'payment.payment_date' => 'nullable|date',
'payment.reference_no' => 'nullable|string|max:255',
'payment.credit_amount' => 'nullable|numeric',

// Multiple Payment Details
'payments' => 'nullable|array|min:1',
'payments.*.payment_method' => 'required_with:payments|string',
'payments.*.account_no' => 'nullable|string',
'payments.*.bank_name' => 'nullable|string',
'payments.*.check_no' => 'nullable|string',
'payments.*.check_date' => 'nullable|date',
'payments.*.payment_date' => 'nullable|date',
'payments.*.reference_no' => 'nullable|string|max:255',
'payments.*.credit_amount' => 'required_with:payments|numeric',

'payment_total' => 'nullable|numeric',
        'sudden_returns' => 'nullable|array',
        'sudden_returns.*.po_id' => 'required|integer',
        'sudden_returns.*.return_number' => 'required|string',
        'sudden_returns.*.total_amount' => 'required|numeric',
        'sudden_returns.*.remarks' => 'nullable|string',
    ]);

    try {
        DB::connection('accounting')->beginTransaction();
        $actor = hatdogAuditActor($user);
        $supplier = \App\Models\Supplier::on('masterlist')->find($data['supplier_id']);

        $suddenReturnsByPoId = collect($data['sudden_returns'] ?? [])->groupBy('po_id');
        $totalPaid = collect($data['invoices'])->sum(fn ($invoice) => (float) $invoice['amountPaid']);
        $voucherId = DB::connection('accounting')->table('payable_cheque_vouchers')->insertGetId([
            'voucher_no' => $data['voucher_no'],
            'supplier_id' => $data['supplier_id'],
            'supplier_name' => $data['supplier_name'],
            'voucher_date' => $data['voucher_date'],
            'reference_no' => $data['reference_no'] ?? null,
            'particulars' => $data['particulars'] ?? null,
            'payment_method' => $data['payment_method'],
            'total_paid' => $totalPaid,
            'global_discount' => $data['global_discount'] ?? 0,
            'global_discount_amount' => $data['global_discount_amount'] ?? 0,
            'additional_discount' => $data['additional_discount'] ?? 0,
            'additional_discount_amount' => $data['additional_discount_amount'] ?? 0,
            'status' => 'Posted',
            'created_at' => now(),
            'updated_at' => now(),
        ]);

        foreach ($data['invoices'] as $invoice) {
            $due = (float) $invoice['amountDue'];
            $paid = (float) $invoice['amountPaid'];
            $discount1 = (float) ($invoice['discount1'] ?? 0);
            $netDue = $discount1 > 0 ? $due - ($due * $discount1 / 100) : $due;

            $srRows = $suddenReturnsByPoId->get($invoice['sourceId'], collect());
            if ($srRows->isNotEmpty()) {
                $retAmt = (float) $srRows->sum(fn ($sr) => (float) ($sr['total_amount'] ?? 0));
                $retNum = $srRows->pluck('return_number')->filter()->unique()->implode(', ');
                $retCount = $srRows->count();
            } else {
                // Normal Purchase Return deductions are already carried by the invoice row.
                // Preserve their Return No. so history/print can resolve purchase_returns.slip_no.
                $retAmt = (float) ($invoice['returnAmount'] ?? 0);
                $retNum = trim((string) ($invoice['returnNumber'] ?? ''));
                $retCount = (int) ($invoice['totalReturns'] ?? 0);
            }

            DB::connection('accounting')->table('payable_cheque_voucher_invoices')->insert([
                'payable_cheque_voucher_id' => $voucherId,
                'purchase_order_id' => $invoice['sourceId'],
                'purchase_no' => $invoice['purchaseNo'],
                'invoice_no' => $invoice['invoiceNo'],
                'invoice_amount' => $invoice['invoiceAmount'],
                'amount_due' => $due,
                'amount_paid' => $paid,
                'discount_1' => $discount1,
                'discount_2' => $invoice['discount2'] ?? 0,
                'return_amount' => $retAmt,
                'total_returns' => $retCount,
                'return_number' => $retNum ?: null,
                'rs_details' => $invoice['rsDetails'] ?? null,
                'remarks' => $invoice['remarks'] ?? null,
                'payment_status' => $paid >= ($netDue - 0.005) ? 'Full' : 'Partial',
                'created_at' => now(),
                'updated_at' => now(),
            ]);
        }

        // Save every Payment Details row separately.
// Negative Credit Amount is ONLY a payment adjustment.
// It must NOT be inserted into Returns or Suddenly Returns.
$payments = $data['payments'] ?? [];

if (empty($payments)) {
    $legacyPayment = $data['payment'] ?? [];

    $payments = [[
        'payment_method' => $legacyPayment['payment_method'] ?? $data['payment_method'],
        'account_no' => $legacyPayment['account_no'] ?? null,
        'bank_name' => $legacyPayment['bank_name'] ?? null,
        'check_no' => $legacyPayment['check_no'] ?? null,
        'check_date' => $legacyPayment['check_date'] ?? null,
        'payment_date' => $legacyPayment['payment_date'] ?? null,
        'reference_no' => (($legacyPayment['payment_method'] ?? $data['payment_method']) === 'Gcash') ? ($legacyPayment['reference_no'] ?? null) : null,
        'credit_amount' => $legacyPayment['credit_amount'] ?? $totalPaid,
    ]];
}

foreach ($payments as $payment) {
    DB::connection('accounting')
        ->table('payable_cheque_voucher_payments')
        ->insert([
            'payable_cheque_voucher_id' => $voucherId,
            'payment_method' => $payment['payment_method'] ?? $data['payment_method'],
            'account_no' => $payment['account_no'] ?? null,
            'bank_name' => $payment['bank_name'] ?? null,
            'check_no' => $payment['check_no'] ?? null,
            'check_date' => $payment['check_date'] ?? null,
            'payment_date' => $payment['payment_date'] ?? null,
            'reference_no' => (($payment['payment_method'] ?? $data['payment_method']) === 'Gcash') ? ($payment['reference_no'] ?? null) : null,
            'credit_amount' => (float) ($payment['credit_amount'] ?? 0),
            'created_at' => now(),
            'updated_at' => now(),
        ]);
}

        // Store sudden returns in dedicated table
        \Log::info('=== SUDDEN RETURNS DEBUG START ===');
        \Log::info('Sudden returns from request:', ['data' => $data['sudden_returns'] ?? []]);
        
        $allVoucherInvoiceIds = DB::connection('accounting')->table('payable_cheque_voucher_invoices')
            ->where('payable_cheque_voucher_id', $voucherId)
            ->pluck('purchase_order_id', 'id');
        
        \Log::info('All voucher invoice IDs:', ['map' => $allVoucherInvoiceIds->toArray()]);
        
        foreach ($data['sudden_returns'] ?? [] as $sr) {
            \Log::info('Processing sudden return:', ['sr' => $sr]);
            $targetInvoiceId = null;
            $targetPoId = null;
            
            // Try to match SR's PO to a selected invoice
            foreach ($allVoucherInvoiceIds as $invId => $invPoId) {
                if ((int) $invPoId === (int) $sr['po_id']) {
                    $targetInvoiceId = $invId;
                    $targetPoId = $invPoId;
                    break;
                }
            }
            
            if ($targetInvoiceId) {
                // SR matches a specific selected PO - attribute all to that invoice
                \Log::info('Matched SR PO to invoice', ['invoice_id' => $targetInvoiceId, 'po_id' => $targetPoId]);
                $insertData = [
                    'payable_cheque_voucher_id' => $voucherId,
                    'payable_cheque_voucher_invoice_id' => $targetInvoiceId,
                    'purchase_order_id' => $targetPoId,
                    'return_number' => $sr['return_number'],
                    'return_date' => $sr['date'] ?? null,
                    'return_amount' => $sr['total_amount'],
                    'remarks' => $sr['remarks'] ?? null,
                    'created_at' => now(),
                    'updated_at' => now(),
                ];
                \Log::info('INSERTING sudden return (matched): ' . json_encode($insertData));
                DB::connection('accounting')->table('payable_cheque_voucher_sudden_returns')->insert($insertData);
            } else {
                // Preserve existing fallback: if the selected return is not tied
                // to one selected PO, distribute it across voucher invoices.
                $count = $allVoucherInvoiceIds->count();
                $sharePerInvoice = $count > 0 ? $sr['total_amount'] / $count : $sr['total_amount'];
                \Log::info('Distributing SR proportionally', ['total' => $sr['total_amount'], 'count' => $count, 'share' => $sharePerInvoice]);

                foreach ($allVoucherInvoiceIds as $invId => $invPoId) {
                    $insertData = [
                        'payable_cheque_voucher_id' => $voucherId,
                        'payable_cheque_voucher_invoice_id' => $invId,
                        'purchase_order_id' => $invPoId,
                        'return_number' => $sr['return_number'],
                        'return_date' => $sr['date'] ?? null,
                        'return_amount' => $sharePerInvoice,
                        'remarks' => $sr['remarks'] ?? null,
                        'created_at' => now(),
                        'updated_at' => now(),
                    ];
                    \Log::info('INSERTING sudden return share: ' . json_encode($insertData));
                    DB::connection('accounting')->table('payable_cheque_voucher_sudden_returns')->insert($insertData);
                }
            }
        }
        
        \Log::info('=== SUDDEN RETURNS DEBUG END ===');

        $voucher = DB::connection('accounting')->table('payable_cheque_vouchers')->where('id', $voucherId)->first();
        $voucherInvoices = DB::connection('accounting')->table('payable_cheque_voucher_invoices')
            ->where('payable_cheque_voucher_id', $voucherId)
            ->get()
            ->map(fn ($row) => (array) $row)
            ->values()
            ->all();
        $voucherPayments = DB::connection('accounting')->table('payable_cheque_voucher_payments')
            ->where('payable_cheque_voucher_id', $voucherId)
            ->get()
            ->map(fn ($row) => (array) $row)
            ->values()
            ->all();
        $recordName = trim((string) (($data['supplier_name'] ?? '') !== '' ? $data['supplier_name'] : ('Payable Cheque Voucher ' . $data['voucher_no'])));

        hatdogWriteAuditTrail([
            'module' => 'payable_cheque_voucher',
            'action' => 'Processed',
            'source_connection' => 'accounting',
            'source_table' => 'payable_cheque_vouchers',
            'source_id' => $voucherId,
            'display_id' => (string) $data['voucher_no'],
            'record_name' => $recordName,
            'user_name' => $actor['name'],
            'user_identifier' => $actor['identifier'],
            'audit_data' => [
                'voucher' => $voucher ? (array) $voucher : null,
                'supplier' => $supplier?->toArray(),
                'voucher_invoices' => $voucherInvoices,
                'voucher_payments' => $voucherPayments,
                'request_payload' => [
                    'voucher_date' => $data['voucher_date'],
                    'reference_no' => $data['reference_no'] ?? null,
                    'particulars' => $data['particulars'] ?? null,
                    'payment_method' => $data['payment_method'],
                    'invoices' => collect($data['invoices'])->values()->all(),
                    'sudden_returns' => $data['sudden_returns'] ?? [],
                    'payment' => $data['payment'] ?? null,
                ],
            ],
        ]);

        DB::connection('accounting')->commit();
        return response()->json(['success' => true, 'voucher_id' => $voucherId]);
    } catch (\Throwable $e) {
        DB::connection('accounting')->rollBack();
        Log::error('Payable cheque voucher process error: ' . $e->getMessage());
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.payable-cheque-voucher.process');

Route::put('/admin/accounting/payable-cheque-voucher/update/{voucherId}', function (Request $request, $voucherId) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

    $data = $request->validate([
        'voucher_id' => 'required|integer',
        'reference_no' => 'nullable|string|max:255',
        'particulars' => 'nullable|string|max:1000',
        'payment_method' => 'required|in:Gcash,Cash,Cheque,Bank Transfer',
        'invoices' => 'required|array|min:1',
        'invoices.*.id' => 'required|integer',
        'invoices.*.sourceId' => 'required|integer',
        'invoices.*.amountPaid' => 'required|numeric|min:0',
        'invoices.*.discount1' => 'nullable|numeric|min:0|max:100',
        'invoices.*.discount2' => 'nullable|numeric|min:0|max:100',
        'sudden_returns' => 'nullable|array',
        'sudden_returns.*.invoice_id' => 'required_with:sudden_returns|integer',
        'sudden_returns.*.po_id' => 'required_with:sudden_returns|integer',
        'sudden_returns.*.return_number' => 'required_with:sudden_returns|string',
        'sudden_returns.*.total_amount' => 'required_with:sudden_returns|numeric',
        'payment' => 'nullable|array',
        'payment.credit_amount' => 'required|numeric|min:0.01',
        'global_discount' => 'nullable|numeric|min:0|max:100',
    ]);

    try {
        DB::connection('accounting')->beginTransaction();
        
        $voucher = DB::connection('accounting')->table('payable_cheque_vouchers')
            ->where('id', $voucherId)->lockForUpdate()->first();
        
        if (!$voucher) {
            DB::connection('accounting')->rollBack();
            return response()->json(['success' => false, 'message' => 'Voucher not found'], 404);
        }

        $oldInvoices = DB::connection('accounting')->table('payable_cheque_voucher_invoices')
            ->where('payable_cheque_voucher_id', $voucherId)->get()->map(fn ($row) => (array) $row)->all();
        $oldSuddenReturns = DB::connection('accounting')->table('payable_cheque_voucher_sudden_returns')
            ->where('payable_cheque_voucher_id', $voucherId)->get()->map(fn ($row) => (array) $row)->all();
        $oldPayment = DB::connection('accounting')->table('payable_cheque_voucher_payments')
            ->where('payable_cheque_voucher_id', $voucherId)->first();

        $totalPaid = collect($data['invoices'])->sum(fn ($invoice) => (float) $invoice['amountPaid']);

        DB::connection('accounting')->table('payable_cheque_vouchers')->where('id', $voucherId)->update([
            'reference_no' => $data['reference_no'] ?? null,
            'particulars' => $data['particulars'] ?? null,
            'payment_method' => $data['payment_method'],
            'total_paid' => $totalPaid,
            'global_discount' => $data['global_discount'] ?? 0,
            'global_discount_amount' => $data['global_discount_amount'] ?? 0,
            'updated_at' => now(),
        ]);

        foreach ($data['invoices'] as $invoice) {
            $due = (float) $invoice['amountDue'];
            $paid = (float) $invoice['amountPaid'];
            $discount1 = (float) ($invoice['discount1'] ?? 0);
            $discount2 = (float) ($invoice['discount2'] ?? 0);
            
            $netDue = $due;
            if ($discount1 > 0) $netDue = $netDue - ($netDue * $discount1 / 100);
            if ($discount2 > 0) $netDue = $netDue - ($netDue * $discount2 / 100);
            
            $paymentStatus = ($paid >= ($netDue - 0.005)) ? 'Full' : 'Partial';

            DB::connection('accounting')->table('payable_cheque_voucher_invoices')->where('id', $invoice['id'])->update([
                'amount_paid' => $paid,
                'discount_1' => $discount1,
                'discount_2' => $discount2,
                'return_amount' => $invoice['returnAmount'] ?? 0,
                'total_returns' => $invoice['totalReturns'] ?? 0,
                'return_number' => $invoice['returnNumber'] ?? null,
                'rs_details' => $invoice['rsDetails'] ?? null,
                'remarks' => $invoice['remarks'] ?? null,
                'payment_status' => $paymentStatus,
                'updated_at' => now(),
            ]);
        }

        DB::connection('accounting')->table('payable_cheque_voucher_sudden_returns')
            ->where('payable_cheque_voucher_id', $voucherId)->delete();
        
        foreach ($data['sudden_returns'] ?? [] as $sr) {
            $targetInvoiceId = $sr['invoice_id'];
            // Look up the invoice's actual PO to correctly attribute SR in paidRows
            $targetInvoicePo = DB::connection('accounting')->table('payable_cheque_voucher_invoices')
                ->where('id', $targetInvoiceId)->value('purchase_order_id');
            DB::connection('accounting')->table('payable_cheque_voucher_sudden_returns')->insert([
                'payable_cheque_voucher_id' => $voucherId,
                'payable_cheque_voucher_invoice_id' => $targetInvoiceId,
                'purchase_order_id' => $targetInvoicePo ?: $sr['po_id'],
                'return_number' => $sr['return_number'],
                'return_date' => $sr['return_date'] ?? null,
                'return_amount' => $sr['total_amount'],
                'remarks' => $sr['remarks'] ?? null,
                'created_at' => now(),
                'updated_at' => now(),
            ]);
        }

        DB::connection('accounting')->table('payable_cheque_voucher_payments')
            ->where('payable_cheque_voucher_id', $voucherId)->delete();
        
        $payment = $data['payment'] ?? [];
        DB::connection('accounting')->table('payable_cheque_voucher_payments')->insert([
            'payable_cheque_voucher_id' => $voucherId,
            'payment_method' => $data['payment_method'],
            'account_no' => $payment['account_no'] ?? null,
            'bank_name' => $payment['bank_name'] ?? null,
            'check_no' => $payment['check_no'] ?? null,
            'check_date' => $payment['check_date'] ?? null,
            'payment_date' => $payment['payment_date'] ?? null,
            'credit_amount' => $payment['credit_amount'] ?? $totalPaid,
            'created_at' => now(),
            'updated_at' => now(),
        ]);

        $newInvoices = DB::connection('accounting')->table('payable_cheque_voucher_invoices')
            ->where('payable_cheque_voucher_id', $voucherId)->get()->map(fn ($row) => (array) $row)->all();
        $newSuddenReturns = DB::connection('accounting')->table('payable_cheque_voucher_sudden_returns')
            ->where('payable_cheque_voucher_id', $voucherId)->get()->map(fn ($row) => (array) $row)->all();
        $newPayment = DB::connection('accounting')->table('payable_cheque_voucher_payments')
            ->where('payable_cheque_voucher_id', $voucherId)->first();
        $updatedVoucher = DB::connection('accounting')->table('payable_cheque_vouchers')
            ->where('id', $voucherId)->first();

        $actor = hatdogAuditActor($user);
        hatdogWriteAuditTrail([
            'module' => 'payable_cheque_voucher',
            'action' => 'edit',
            'source_connection' => 'accounting',
            'source_table' => 'payable_cheque_vouchers',
            'source_id' => $voucherId,
            'display_id' => $voucher->voucher_no,
            'record_name' => $voucher->supplier_name,
            'user_name' => $actor['name'],
            'user_identifier' => $actor['identifier'],
            'audit_data' => [
                'old' => [
                    'voucher' => (array) $voucher,
                    'invoices' => $oldInvoices,
                    'sudden_returns' => $oldSuddenReturns,
                    'payment' => $oldPayment ? (array) $oldPayment : null,
                ],
                'new' => [
                    'voucher' => (array) $updatedVoucher,
                    'invoices' => $newInvoices,
                    'sudden_returns' => $newSuddenReturns,
                    'payment' => $newPayment ? (array) $newPayment : null,
                ],
            ],
        ]);

        DB::connection('accounting')->commit();
        return response()->json(['success' => true, 'message' => 'Voucher updated successfully', 'voucher_no' => $voucher->voucher_no]);
    } catch (\Throwable $e) {
        DB::connection('accounting')->rollBack();
        Log::error('Payable cheque voucher update error: ' . $e->getMessage());
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.payable-cheque-voucher.update');

