// Payable Cheque Voucher - Delete
Route::delete('/admin/accounting/payable-cheque-voucher/delete/{id}', function ($id) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

    try {
        $voucher = DB::connection('accounting')->table('payable_cheque_vouchers')->where('id', $id)->first();
        if (!$voucher) return response()->json(['success' => false, 'message' => 'Voucher not found.'], 404);

        $actor = hatdogAuditActor($user);

        DB::connection('accounting')->beginTransaction();

        // 1. Delete sudden returns (releases them for reuse)
        DB::connection('accounting')->table('payable_cheque_voucher_sudden_returns')
            ->where('payable_cheque_voucher_id', $id)->delete();

        // 2. Delete invoice rows
        DB::connection('accounting')->table('payable_cheque_voucher_invoices')
            ->where('payable_cheque_voucher_id', $id)->delete();

        // 3. Delete payment rows
        DB::connection('accounting')->table('payable_cheque_voucher_payments')
            ->where('payable_cheque_voucher_id', $id)->delete();

        // 4. Delete the voucher itself
        DB::connection('accounting')->table('payable_cheque_vouchers')
            ->where('id', $id)->delete();

        DB::connection('accounting')->commit();

        hatdogWriteAuditTrail([
            'module' => 'payable_cheque_voucher',
            'action' => 'Deleted',
            'source_connection' => 'accounting',
            'source_table' => 'payable_cheque_vouchers',
            'source_id' => (int) $id,
            'display_id' => (string) ($voucher->voucher_no ?? $id),
            'record_name' => trim((string) ($voucher->supplier_name ?? '')),
            'user_name' => $actor['name'],
            'user_identifier' => $actor['identifier'],
            'audit_data' => [
                'before' => (array) $voucher,
            ],
        ]);

        return response()->json(['success' => true, 'message' => 'Voucher deleted successfully.']);
    } catch (\Throwable $e) {
        DB::connection('accounting')->rollBack();
        Log::error('Payable cheque voucher delete error: ' . $e->getMessage());
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.payable-cheque-voucher.delete');


if (!function_exists('hatdogBuildOnlineInvoices')) {
    /**
     * Decode Online Report invoices into one payable row per exact invoice.
     *
     * Amount precedence matches online-print, but all product prices and ONL
     * orders are batch-loaded to avoid thousands of queries on /payments/data.
     */
    function hatdogBuildOnlineInvoices(?int $customerId = null, string $search = '')
    {
        $rows = [];
        $searchLower = mb_strtolower(trim($search));
        $isSourceSearch = $searchLower === 'online' || $searchLower === 'local';
        $normalizeInvoice = static fn ($value) => strtoupper(preg_replace('/\s+/', '', trim((string) $value)));

        $reportsQ = DB::connection('sales')->table('online_reports')
            ->select('id', 'status', 'prices', 'invoice_numbers', 'notes_data', 'created_at')
            ->whereIn('status', ['generated', 'migrated']);

        if ($customerId !== null) {
            $reportsQ->where(function ($q) use ($customerId) {
                $q->where('notes_data', 'LIKE', '%"customer_id":' . $customerId . ',%')
                    ->orWhere('notes_data', 'LIKE', '%"customer_id":' . $customerId . '}%');
            });
        }

        if ($search !== '' && !$isSourceSearch) {
            $reportsQ->where(function ($q) use ($search) {
                $q->where('invoice_numbers', 'LIKE', "%{$search}%")
                    ->orWhere('notes_data', 'LIKE', "%{$search}%")
                    ->orWhereRaw('CAST(created_at AS CHAR) LIKE ?', ["%{$search}%"]);
            });
        }

        $reports = $reportsQ->orderBy('created_at', 'desc')->get();

        // First pass: gather all product IDs. This avoids one product query per item.
        $productIdSet = [];
        foreach ($reports as $report) {
            $notesData = json_decode($report->notes_data ?? '[]', true);
            if (!is_array($notesData)) continue;

            foreach ($notesData as $note) {
                if (!is_array($note) || !isset($note['items']) || !is_array($note['items'])) continue;
                foreach ($note['items'] as $item) {
                    if (!is_array($item)) continue;
                    $productId = (int) ($item['product_id'] ?? 0);
                    if ($productId > 0) $productIdSet[$productId] = true;
                }
            }
        }

        $productMap = collect();
        foreach (array_chunk(array_keys($productIdSet), 1000) as $productIdChunk) {
            $chunk = DB::connection('masterlist')->table('products')
                ->whereIn('id', $productIdChunk)
                ->get(['id', 'price_online', 'selling_price'])
                ->keyBy('id');
            $productMap = $productMap->merge($chunk);
        }

        // Batch-load ONL orders and key them by report + exact invoice number.
        $onlineOrderMap = [];
        if ($reports->contains(fn ($report) => $report->status === 'generated')) {
            $onlineOrders = DB::connection('sales')->table('sales_orders')
                ->where('order_number', 'LIKE', 'ONL-%')
                ->whereIn('status', ['Confirmed', 'Closed'])
                ->get();

            foreach ($onlineOrders as $order) {
                if (!preg_match('/^ONL-(\d+)-/', (string) $order->order_number, $matches)) continue;
                $reportId = (int) $matches[1];
                $invoiceValues = json_decode((string) ($order->invoice_numbers ?? ''), true);
                if (!is_array($invoiceValues)) {
                    $invoiceValues = array_map('trim', explode(',', (string) ($order->invoice_numbers ?? '')));
                }
                foreach ($invoiceValues as $invoiceValue) {
                    $invoiceKey = $normalizeInvoice($invoiceValue);
                    if ($invoiceKey !== '') $onlineOrderMap[$reportId][$invoiceKey] = $order;
                }
            }
        }

        foreach ($reports as $report) {
            $invoiceNumbers = json_decode($report->invoice_numbers ?? '[]', true);
            $notesData = json_decode($report->notes_data ?? '[]', true);
            $prices = json_decode($report->prices ?? '[]', true);
            if (!is_array($invoiceNumbers)) $invoiceNumbers = [];
            if (!is_array($notesData)) $notesData = [];
            if (!is_array($prices)) $prices = [];

            $count = max(count($invoiceNumbers), count($notesData));
            for ($noteIndex = 0; $noteIndex < $count; $noteIndex++) {
                $invoiceNo = trim((string) ($invoiceNumbers[$noteIndex] ?? ''));
                if ($invoiceNo === '') continue;

                $note = $notesData[$noteIndex] ?? (count($notesData) === 1 ? $notesData[0] : null);
                $note = is_array($note) ? $note : null;
                $customerName = ($note['customer_name'] ?? '') !== '' ? $note['customer_name'] : '';

                if ($search !== '' && !$isSourceSearch) {
                    $reportDate = $report->created_at ? date('m/d/Y', strtotime($report->created_at)) : '';
                    $haystack = mb_strtolower($invoiceNo . '|' . $customerName . '|' . $report->created_at . '|' . $reportDate);
                    if (mb_strpos($haystack, $searchLower) === false) continue;
                }

                $rowKey = (int) $report->id . ':' . $invoiceNo;
                if (isset($rows[$rowKey])) continue;

                $noteItems = ($note && isset($note['items']) && is_array($note['items'])) ? $note['items'] : [];
                $amount = 0.0;

                foreach ($noteItems as $item) {
                    if (!is_array($item)) continue;
                    $quantity = (float) ($item['quantity'] ?? 0);
                    if ($quantity <= 0) continue;

                    $productId = (int) ($item['product_id'] ?? 0);
                    $itemId = $item['id'] ?? null;
                    $product = $productId > 0 ? $productMap->get($productId) : null;
                    $resolvedPrice = 0.0;

                    if ($productId > 0 && isset($prices[(string) $productId]) && (float) $prices[(string) $productId] > 0) {
                        $resolvedPrice = (float) $prices[(string) $productId];
                    }
                    if ($resolvedPrice <= 0 && $itemId !== null) {
                        $itemPriceKey = $noteIndex . '-' . $itemId;
                        if (isset($prices[$itemPriceKey]) && (float) $prices[$itemPriceKey] > 0) {
                            $resolvedPrice = (float) $prices[$itemPriceKey];
                        }
                    }
                    if ($resolvedPrice <= 0 && $product && (float) ($product->price_online ?? 0) > 0) {
                        $resolvedPrice = (float) $product->price_online;
                    }
                    if ($resolvedPrice <= 0 && (float) ($item['unit_price'] ?? 0) > 0) {
                        $resolvedPrice = (float) $item['unit_price'];
                    }
                    if ($resolvedPrice <= 0 && $product && (float) ($product->selling_price ?? 0) > 0) {
                        $resolvedPrice = (float) $product->selling_price;
                    }

                                 $amount += $quantity * $resolvedPrice;
                }

                $invoiceKey = $normalizeInvoice($invoiceNo);
                $order = $onlineOrderMap[(int) $report->id][$invoiceKey] ?? null;

                // The finalized ONL Sales Order is the authoritative invoice amount.
                // Use it even when the total is exactly 0.00; online_reports.notes_data
                // is only a generation snapshot and can contain stale prices/subtotals.
                if ($order && $order->total_amount !== null) {
                    $amount = (float) $order->total_amount;
                } else {
                    if ($amount <= 0) {
                        $amount = (float) (($note['net_total'] ?? 0) ?: 0);
                    }

                    if ($amount <= 0 && count($noteItems) > 0) {
                        $amount = array_sum(array_map(
                            static fn ($item) => is_array($item)
                                ? (float) ($item['subtotal'] ?? 0)
                                : 0.0,
                            $noteItems
                        ));
                    }
                }
                if ($order && $customerName === '') {
                    $customerName = $order->customer_name ?? '';
                }

                $rows[$rowKey] = (object) [
                    'source_type' => 'online_report',
                    'source_id' => (int) $report->id,
                    'invoice_index' => $noteIndex,
                    'po_no' => $invoiceNo,
                    'sales_note_no' => null,
                    'sales_note_amount' => null,
                    'invoice_no' => $invoiceNo,
                    'customer_id' => (int) (($note['customer_id'] ?? 0) ?: ($order->customer_id ?? 0)),
                    'customer_name' => $customerName !== '' ? $customerName : ($order->customer_name ?? '---'),
                    'amount' => round($amount, 2),
                    'status' => $report->status,
                    // Invoice Date must follow the finalized ONL Sales Order
                    // creation timestamp, not the marketplace/order transaction date.
                    'created_at' => $order->created_at ?? $report->created_at,
                    'updated_at' => $order->updated_at ?? $order->created_at ?? $report->created_at,
                    'order_date' => null,
                    'waybill_date' => null,
                ];
            }
        }

        return array_values($rows);
    }
}

if (!function_exists('hatdogBuildPaymentOnlineInvoices')) {
    /**
     * Decode Online Report invoices into one payable row per exact invoice.
     *
     * IMPORTANT: THIS IS NOW A CODE FIX, NOT A DATABASE FIX.
     * DO NOT CHANGE OR REPAIR HISTORICAL DATABASE ROWS HERE. Payments must
     * resolve damaged Online Report snapshots safely at read time.
     *
     * ONLINE authority:
     * 1) finalized ONL Sales Order
     * 2) Sales Order items subtotal
     * 3) Online Report snapshot
     * 4) Product Ledger (read-only historical fallback)
     */
    function hatdogBuildPaymentOnlineInvoices(?int $customerId = null, string $search = '')
    {
        $rows = [];
        $rowAuthority = [];
        $rowTimestamp = [];
        $searchLower = mb_strtolower(trim($search));
        $isSourceSearch = $searchLower === 'online' || $searchLower === 'local';
        $normalizeInvoice = static fn ($value) => strtoupper(preg_replace('/\s+/', '', trim((string) $value)));

        $parseInvoiceValues = static function ($value): array {
            if (is_array($value)) {
                return array_values(array_filter(array_map(
                    static fn ($invoice) => trim((string) $invoice),
                    $value
                ), static fn ($invoice) => $invoice !== ''));
            }

            $raw = trim((string) ($value ?? ''));
            if ($raw === '') return [];

            $decoded = json_decode($raw, true);
            if (is_array($decoded)) {
                return array_values(array_filter(array_map(
                    static fn ($invoice) => trim((string) $invoice),
                    $decoded
                ), static fn ($invoice) => $invoice !== ''));
            }

            return array_values(array_filter(array_map(
                static fn ($invoice) => trim((string) $invoice),
                explode(',', $raw)
            ), static fn ($invoice) => $invoice !== ''));
        };

        // Payments-only alias. Do not merge or rewrite customer rows in Masterlist.
        $shopeePaymentCustomerIds = [1029, 1433];
        $paymentCustomerIds = $customerId === null
            ? []
            : (in_array((int) $customerId, $shopeePaymentCustomerIds, true)
                ? $shopeePaymentCustomerIds
                : [(int) $customerId]);

        // Resolve finalized ONL Sales Orders BEFORE applying Online Report JSON filters.
        $onlineOrdersQ = DB::connection('sales')->table('sales_orders')
            ->where('order_number', 'LIKE', 'ONL-%')
            ->whereIn('status', ['Confirmed', 'Closed']);

        if ($customerId !== null) {
            $onlineOrdersQ->whereIn('customer_id', $paymentCustomerIds);
        }

        $onlineOrders = $onlineOrdersQ
            ->get([
                'id',
                'order_number',
                'customer_id',
                'customer_name',
                'invoice_numbers',
                'total_amount',
                'status',
                'created_at',
                'updated_at',
            ]);

        $onlineOrdersByReportIndex = [];
        $orderReportIds = [];
        $onlineOrderIds = [];

        foreach ($onlineOrders as $order) {
            if (!preg_match('/^ONL-(\d+)-(\d+)/', (string) $order->order_number, $matches)) continue;

            $reportId = (int) $matches[1];
            $orderIndex = (int) $matches[2];

            $onlineOrdersByReportIndex[$reportId][$orderIndex] = $order;
            $orderReportIds[$reportId] = true;
            $onlineOrderIds[(int) $order->id] = true;
        }

        $reportsQ = DB::connection('sales')->table('online_reports')
            ->select('id', 'status', 'prices', 'invoice_numbers', 'notes_data', 'created_at', 'updated_at')
            ->whereIn('status', ['generated', 'migrated']);

        if ($customerId !== null) {
            // A matching finalized ONL Sales Order always keeps its report eligible.
            // notes_data customer matching is fallback-only for legacy/migrated rows.
            $reportIdsFromOrders = array_keys($orderReportIds);

            $reportsQ->where(function ($q) use ($reportIdsFromOrders, $paymentCustomerIds) {
                if (!empty($reportIdsFromOrders)) {
                    $q->whereIn('id', $reportIdsFromOrders)
                        ->orWhere(function ($notesQ) use ($paymentCustomerIds) {
                            foreach ($paymentCustomerIds as $index => $candidateId) {
                                $method = $index === 0 ? 'where' : 'orWhere';
                                $notesQ->{$method}(function ($idQ) use ($candidateId) {
                                    $idQ->where('notes_data', 'LIKE', '%"customer_id":' . $candidateId . '%')
                                        ->orWhere('notes_data', 'LIKE', '%"customer_id": ' . $candidateId . '%');
                                });
                            }
                        });
                } else {
                    $q->where(function ($notesQ) use ($paymentCustomerIds) {
                        foreach ($paymentCustomerIds as $index => $candidateId) {
                            $method = $index === 0 ? 'where' : 'orWhere';
                            $notesQ->{$method}(function ($idQ) use ($candidateId) {
                                $idQ->where('notes_data', 'LIKE', '%"customer_id":' . $candidateId . '%')
                                    ->orWhere('notes_data', 'LIKE', '%"customer_id": ' . $candidateId . '%');
                            });
                        }
                    });
                }
            });
        }

        // Do not pre-filter invoice/customer search against Online Report snapshot fields.
        // Search is applied after the authoritative Sales Order has been resolved.
        $reports = $reportsQ->orderBy('created_at', 'desc')->get();

        // Some historical finalized ONL Sales Orders have no surviving online_reports row.
        // Keep them readable by synthesizing metadata in memory only.
        $reportIdsLoaded = $reports->pluck('id')->map(fn ($id) => (int) $id)->flip();
        foreach ($onlineOrdersByReportIndex as $reportId => $ordersForReport) {
            if ($reportIdsLoaded->has((int) $reportId)) continue;

            $firstOrder = collect($ordersForReport)->sortKeys()->first();
            $reports->push((object) [
                'id' => (int) $reportId,
                'status' => 'generated',
                'prices' => '[]',
                'invoice_numbers' => '[]',
                'notes_data' => '[]',
                'created_at' => $firstOrder->created_at ?? null,
                'updated_at' => $firstOrder->updated_at ?? $firstOrder->created_at ?? null,
            ]);
        }

        // First pass: gather product IDs for Online Report snapshot fallback and identify
        // only the damaged legacy reports that may need a read-only Product Ledger fallback.
        $productIdSet = [];
        $ledgerFallbackReportIds = [];

        foreach ($reports as $report) {
            $reportId = (int) $report->id;
            $reportInvoiceValues = $parseInvoiceValues($report->invoice_numbers ?? null);
            $notesData = json_decode($report->notes_data ?? '[]', true);
            if (!is_array($notesData)) $notesData = [];

            $hasPositiveSnapshotAmount = false;
            foreach ($notesData as $note) {
                if (!is_array($note)) continue;

                if ((float) ($note['net_total'] ?? 0) > 0) {
                    $hasPositiveSnapshotAmount = true;
                }

                if (!isset($note['items']) || !is_array($note['items'])) continue;
                foreach ($note['items'] as $item) {
                    if (!is_array($item)) continue;

                    $productId = (int) ($item['product_id'] ?? 0);
                    if ($productId > 0) $productIdSet[$productId] = true;

                    if ((float) ($item['subtotal'] ?? 0) > 0) {
                        $hasPositiveSnapshotAmount = true;
                    }
                }
            }

            if (!isset($onlineOrdersByReportIndex[$reportId])
                && (empty($reportInvoiceValues) || !$hasPositiveSnapshotAmount)) {
                $ledgerFallbackReportIds[$reportId] = true;
            }
        }

        $productMap = collect();
        foreach (array_chunk(array_keys($productIdSet), 1000) as $productIdChunk) {
            $chunk = DB::connection('masterlist')->table('products')
                ->whereIn('id', $productIdChunk)
                ->get(['id', 'price_online', 'selling_price'])
                ->keyBy('id');
            $productMap = $productMap->merge($chunk);
        }

        // Sales Order item subtotal is the first amount fallback after sales_orders.total_amount.
        $onlineOrderItemTotals = [];
        foreach (array_chunk(array_keys($onlineOrderIds), 1000) as $orderIdChunk) {
            $itemTotals = DB::connection('sales')->table('sales_order_items')
                ->whereIn('sales_order_id', $orderIdChunk)
                ->select('sales_order_id', DB::raw('SUM(subtotal) as subtotal_total'))
                ->groupBy('sales_order_id')
                ->get();

            foreach ($itemTotals as $itemTotal) {
                $onlineOrderItemTotals[(int) $itemTotal->sales_order_id] = (float) ($itemTotal->subtotal_total ?? 0);
            }
        }

        // Product Ledger is read-only and queried only for damaged historical reports that
        // have neither a finalized ONL Sales Order nor a usable Online Report snapshot.
        $ledgerFallbackByReport = [];
        foreach (array_chunk(array_keys($ledgerFallbackReportIds), 1000) as $reportIdChunk) {
            $ledgerRows = DB::connection('ledger')->table('product_ledgers')
                ->where('source_type', 'online_report')
                ->whereIn('source_id', $reportIdChunk)
                ->get([
                    'source_id',
                    'reference_number',
                    'customer_id',
                    'entity_name',
                    'quantity_out',
                    'price',
                    'created_at',
                ]);

            foreach ($ledgerRows as $ledgerRow) {
                $reportId = (int) $ledgerRow->source_id;
                $referenceNo = trim((string) ($ledgerRow->reference_number ?? ''));
                $invoiceKey = $normalizeInvoice($referenceNo);
                if ($invoiceKey === '') $invoiceKey = '__NO_INVOICE__';

                if (!isset($ledgerFallbackByReport[$reportId][$invoiceKey])) {
                    $ledgerFallbackByReport[$reportId][$invoiceKey] = [
                        'invoice_no' => $referenceNo,
                        'customer_id' => (int) ($ledgerRow->customer_id ?? 0),
                        'customer_name' => trim((string) ($ledgerRow->entity_name ?? '')),
                        'amount' => 0.0,
                        'created_at' => $ledgerRow->created_at ?? null,
                    ];
                }

                $ledgerFallbackByReport[$reportId][$invoiceKey]['amount'] +=
                    (float) ($ledgerRow->quantity_out ?? 0) * (float) ($ledgerRow->price ?? 0);
            }
        }

        foreach ($reports as $report) {
            $reportId = (int) $report->id;
            $invoiceNumbers = $parseInvoiceValues($report->invoice_numbers ?? null);
            $notesData = json_decode($report->notes_data ?? '[]', true);
            $prices = json_decode($report->prices ?? '[]', true);
            if (!is_array($notesData)) $notesData = [];
            if (!is_array($prices)) $prices = [];

            $ordersForReport = $onlineOrdersByReportIndex[$reportId] ?? [];
            $orderCount = empty($ordersForReport) ? 0 : (max(array_keys($ordersForReport)) + 1);
            $count = max(count($invoiceNumbers), count($notesData), $orderCount);

            for ($noteIndex = 0; $noteIndex < $count; $noteIndex++) {
                $order = $ordersForReport[$noteIndex] ?? null;
                $orderInvoiceValues = $order ? $parseInvoiceValues($order->invoice_numbers ?? null) : [];

                // Finalized ONL Sales Order invoice number wins over Online Report JSON.
                $invoiceNo = trim((string) ($orderInvoiceValues[0] ?? ($invoiceNumbers[$noteIndex] ?? '')));

                $note = $notesData[$noteIndex] ?? (count($notesData) === 1 ? $notesData[0] : null);
                $note = is_array($note) ? $note : null;
                $noteItems = ($note && isset($note['items']) && is_array($note['items'])) ? $note['items'] : [];

                $ledgerCandidates = $ledgerFallbackByReport[$reportId] ?? [];
                $ledgerInfo = null;

                if (!empty($ledgerCandidates)) {
                    $invoiceKey = $normalizeInvoice($invoiceNo);
                    if ($invoiceKey !== '' && isset($ledgerCandidates[$invoiceKey])) {
                        $ledgerInfo = $ledgerCandidates[$invoiceKey];
                    } elseif (count($ledgerCandidates) === 1) {
                        $ledgerInfo = reset($ledgerCandidates);
                    } elseif ($invoiceNo === '') {
                        $ledgerInfo = collect($ledgerCandidates)->values()->get($noteIndex)
                            ?? collect($ledgerCandidates)->values()->first();
                    }
                }

                if ($invoiceNo === '' && $ledgerInfo) {
                    $invoiceNo = trim((string) ($ledgerInfo['invoice_no'] ?? ''));
                }
                if ($invoiceNo === '') continue;

                $resolvedCustomerId = $order && (int) ($order->customer_id ?? 0) > 0
                    ? (int) $order->customer_id
                    : (int) (($note['customer_id'] ?? 0) ?: ($ledgerInfo['customer_id'] ?? 0));

                $resolvedCustomerName = $order && trim((string) ($order->customer_name ?? '')) !== ''
                    ? trim((string) $order->customer_name)
                    : trim((string) (($note['customer_name'] ?? '') ?: ($ledgerInfo['customer_name'] ?? '')));

                // Apply customer filtering only after the authoritative ONL Sales Order is resolved.
                if ($customerId !== null && !in_array($resolvedCustomerId, $paymentCustomerIds, true)) {
                    continue;
                }

                // Treat historical 1029/1433 Shopee IDs as one Payments read group only.
                $outputCustomerId = $resolvedCustomerId;
                if (in_array($resolvedCustomerId, $shopeePaymentCustomerIds, true)) {
                    $outputCustomerId = $customerId !== null && in_array((int) $customerId, $shopeePaymentCustomerIds, true)
                        ? (int) $customerId
                        : 1029;

                    if ($outputCustomerId === 1029 && $resolvedCustomerId === 1433) {
                        $resolvedCustomerName = 'SHOPEE ONLINE BUYERS';
                    }
                }

                if ($search !== '' && !$isSourceSearch) {
                    $documentDate = $order->created_at ?? $report->created_at ?? null;
                    $displayDate = $documentDate ? date('m/d/Y', strtotime($documentDate)) : '';
                    $haystack = mb_strtolower(
                        $invoiceNo . '|' .
                        $resolvedCustomerName . '|' .
                        ($order->order_number ?? '') . '|' .
                        ($documentDate ?? '') . '|' .
                        $displayDate
                    );
                    if (mb_strpos($haystack, $searchLower) === false) continue;
                }

                // Existing Online Report price/item calculation is retained only as fallback.
                $reportAmount = 0.0;
                foreach ($noteItems as $item) {
                    if (!is_array($item)) continue;

                    $quantity = (float) ($item['quantity'] ?? 0);
                    if ($quantity <= 0) continue;

                    $productId = (int) ($item['product_id'] ?? 0);
                    $itemId = $item['id'] ?? null;
                    $product = $productId > 0 ? $productMap->get($productId) : null;
                    $resolvedPrice = 0.0;

                    if ($productId > 0 && isset($prices[(string) $productId]) && (float) $prices[(string) $productId] > 0) {
                        $resolvedPrice = (float) $prices[(string) $productId];
                    }
                    if ($resolvedPrice <= 0 && $itemId !== null) {
                        $itemPriceKey = $noteIndex . '-' . $itemId;
                        if (isset($prices[$itemPriceKey]) && (float) $prices[$itemPriceKey] > 0) {
                            $resolvedPrice = (float) $prices[$itemPriceKey];
                        }
                    }
                    if ($resolvedPrice <= 0 && $product && (float) ($product->price_online ?? 0) > 0) {
                        $resolvedPrice = (float) $product->price_online;
                    }
                    if ($resolvedPrice <= 0 && (float) ($item['unit_price'] ?? 0) > 0) {
                        $resolvedPrice = (float) $item['unit_price'];
                    }
                    if ($resolvedPrice <= 0 && $product && (float) ($product->selling_price ?? 0) > 0) {
                        $resolvedPrice = (float) $product->selling_price;
                    }

                    $reportAmount += $quantity * $resolvedPrice;
                }

                if ($reportAmount <= 0) {
                    $reportAmount = (float) (($note['net_total'] ?? 0) ?: 0);
                }

                if ($reportAmount <= 0 && count($noteItems) > 0) {
                    $reportAmount = array_sum(array_map(
                        static fn ($item) => is_array($item)
                            ? (float) ($item['subtotal'] ?? 0)
                            : 0.0,
                        $noteItems
                    ));
                }

                $amount = 0.0;
                $authorityRank = 0;

                $salesOrderTotal = $order ? (float) ($order->total_amount ?? 0) : 0.0;
                $salesOrderItemTotal = $order
                    ? (float) ($onlineOrderItemTotals[(int) $order->id] ?? 0)
                    : 0.0;
                $ledgerAmount = (float) ($ledgerInfo['amount'] ?? 0);

                if ($order && $salesOrderTotal > 0) {
                    $amount = $salesOrderTotal;
                    $authorityRank = 4;
                } elseif ($order && $salesOrderItemTotal > 0) {
                    $amount = $salesOrderItemTotal;
                    $authorityRank = 3;
                } elseif ($reportAmount > 0) {
                    $amount = $reportAmount;
                    $authorityRank = 2;
                } elseif ($ledgerAmount > 0) {
                    $amount = $ledgerAmount;
                    $authorityRank = 1;
                }

                $rowKey = $normalizeInvoice($invoiceNo);
                if ($rowKey === '') continue;

                $candidateTimestamp = strtotime((string) (
                    $order->updated_at
                    ?? $order->created_at
                    ?? $report->updated_at
                    ?? $report->created_at
                    ?? '1970-01-01'
                )) ?: 0;

                if (isset($rows[$rowKey])) {
                    $existingRank = (int) ($rowAuthority[$rowKey] ?? 0);
                    $existingTimestamp = (int) ($rowTimestamp[$rowKey] ?? 0);

                    if ($authorityRank < $existingRank
                        || ($authorityRank === $existingRank && $candidateTimestamp <= $existingTimestamp)) {
                        continue;
                    }
                }

                $rows[$rowKey] = (object) [
                    'source_type' => 'online_report',
                    'source_id' => $reportId,
                    'invoice_index' => $noteIndex,
                    'po_no' => $invoiceNo,
                    'sales_note_no' => null,
                    'sales_note_amount' => null,
                    'invoice_no' => $invoiceNo,
                    'customer_id' => $outputCustomerId,
                    'customer_name' => $resolvedCustomerName !== '' ? $resolvedCustomerName : '---',
                    'amount' => round($amount, 2),
                    'status' => $order->status ?? $report->status,
                    // Invoice Date follows the finalized ONL Sales Order when available.
                    'created_at' => $order->created_at ?? $ledgerInfo['created_at'] ?? $report->created_at,
                    'updated_at' => $order->updated_at
                        ?? $order->created_at
                        ?? $report->updated_at
                        ?? $report->created_at,
                    'order_date' => null,
                    'waybill_date' => null,
                ];
                $rowAuthority[$rowKey] = $authorityRank;
                $rowTimestamp[$rowKey] = $candidateTimestamp;
            }
        }

        return array_values($rows);
    }
}

Route::get('/admin/payments/data', function () {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

    try {
        $paidRows = DB::connection('accounting')->table('process_payment_invoices')
            ->select(
                'source_type',
                'source_id',
                DB::raw('SUM(paid_amount) as paid_total'),
                DB::raw('SUM(adjustment) as adjustment_total'),
                DB::raw('MAX(created_at) as latest_payment_at')
            )
            ->groupBy('source_type', 'source_id')
            ->get()
            ->keyBy(fn ($row) => $row->source_type . ':' . $row->source_id);

        // Online payments are keyed per exact invoice number (one report can hold several invoices)
        $onlinePaidRows = DB::connection('accounting')->table('process_payment_invoices')
            ->select(
                'source_type',
                'source_id',
                'invoice_no',
                DB::raw('SUM(paid_amount) as paid_total'),
                DB::raw('SUM(adjustment) as adjustment_total'),
                DB::raw('MAX(created_at) as latest_payment_at')
            )
            ->where('source_type', 'online_report')
            ->groupBy('source_type', 'source_id', 'invoice_no')
            ->get()
            ->keyBy(fn ($row) => $row->source_type . ':' . $row->source_id . ':' . $row->invoice_no);

        $normalizeInvKey = static fn ($v) => strtoupper(preg_replace('/\s+/', '', trim((string) $v)));

        $rawReturnRows = DB::connection('sales')->table('sales_returns as sr')
            ->join('sales_return_items as sri', 'sri.sales_return_id', '=', 'sr.id')
            ->whereNotNull('sr.invoice_no')
            ->whereRaw("UPPER(TRIM(COALESCE(sr.status, ''))) NOT IN ('CANCELLED', 'VOID')")
            ->select(
                'sr.invoice_no',
                'sr.status',
                DB::raw("SUM(COALESCE(sri.return_amount, sri.subtotal, 0)) as return_total"),
                DB::raw("SUM(sri.quantity) as return_qty")
            )
            ->groupBy('sr.invoice_no', 'sr.status')
            ->get();

        // Preserve the existing LOCAL return behavior, but ONLINE may subtract only
        // valid Completed returns from its authoritative invoice amount.
        $returnMap = [];
        $returnQtyMap = [];
        $onlineReturnMap = [];
        $onlineReturnQtyMap = [];
        foreach ($rawReturnRows as $row) {
            $rawInvoice = (string) ($row->invoice_no ?? '');
            $total = (float) ($row->return_total ?? 0);
            if ($rawInvoice === '' || $total <= 0) continue;
            $qty = (int) ($row->return_qty ?? 0);
            $isCompletedReturn = strtoupper(trim((string) ($row->status ?? ''))) === 'COMPLETED';

            $keys = [];
            $keys[] = $normalizeInvKey($rawInvoice);

            foreach (preg_split('/[,\s\/]+/', $rawInvoice) as $token) {
                $token = trim((string) $token);
                if ($token === '') continue;
                $keys[] = $normalizeInvKey($token);
            }

            if (preg_match_all('/SN-\d+/i', $rawInvoice, $m) && !empty($m[0])) {
                foreach ($m[0] as $sn) {
                    $sn = trim((string) $sn);
                    if ($sn === '') continue;
                    $keys[] = $normalizeInvKey($sn);
                }
            }

            $keys = array_values(array_unique(array_filter($keys, fn ($k) => $k !== '')));
            foreach ($keys as $k) {
                $returnMap[$k] = (float) ($returnMap[$k] ?? 0) + $total;
                $returnQtyMap[$k] = (int) ($returnQtyMap[$k] ?? 0) + $qty;

                if ($isCompletedReturn) {
                    $onlineReturnMap[$k] = (float) ($onlineReturnMap[$k] ?? 0) + $total;
                    $onlineReturnQtyMap[$k] = (int) ($onlineReturnQtyMap[$k] ?? 0) + $qty;
                }
            }
        }

        $salesOrders = DB::connection('sales')->table('sales_orders as so')
            ->leftJoin('sales_notes as sn', 'sn.id', '=', 'so.sales_note_id')
            ->where('so.order_number', 'NOT LIKE', 'ONL-%')
            ->where(function ($query) {
                $query->whereIn('so.status', ['Closed', 'Confirmed'])
                    ->orWhere('sn.status', 'Closed');
            })
            ->select(
                DB::raw("'sales_order' as source_type"),
                'so.id as source_id',
                'so.order_number as po_no',
                'sn.sales_number as sales_note_no',
                'sn.net_total as sales_note_amount',
                'sn.order_date',
                DB::raw("COALESCE(NULLIF(so.invoice_numbers, ''), so.order_number) as invoice_no"),
                'so.customer_id',
                'so.customer_name',
                'so.total_amount as amount',
                'so.status',
                'so.created_at',
                'so.updated_at',
                'so.waybill_date'
            )
            ->get();

        $consignmentInvoices = DB::connection('sales')->table('consignment_invoices')
            ->whereNotIn('status', ['Cancelled', 'Void'])
            ->select(
                DB::raw("'consignment_invoice' as source_type"),
                'id as source_id',
                DB::raw('invoice_number as po_no'),
                'invoice_number as invoice_no',
                'customer_id',
                'customer_name',
                'total_amount as amount',
                'status',
                'created_at',
                'updated_at',
                DB::raw('NULL as order_date'),
                DB::raw('NULL as waybill_date')
            )
            ->get();

        $onlineInvoices = hatdogBuildPaymentOnlineInvoices();

        $documents = $salesOrders->concat($consignmentInvoices)->concat($onlineInvoices)
            ->filter(fn ($doc) => $doc->customer_id && (float) $doc->amount > 0)
            ->map(function ($doc) use ($paidRows, $onlinePaidRows, $returnMap, $returnQtyMap, $onlineReturnMap, $onlineReturnQtyMap, $normalizeInvKey) {
                $isOnline = $doc->source_type === 'online_report';
                $paidKey = $isOnline
                    ? $doc->source_type . ':' . $doc->source_id . ':' . $doc->invoice_no
                    : $doc->source_type . ':' . $doc->source_id;
                $paidRow = $isOnline ? $onlinePaidRows->get($paidKey) : $paidRows->get($paidKey);
                $paid = (float) ($paidRow->paid_total ?? 0);
                $recordedAdjustment = (float) ($paidRow->adjustment_total ?? 0);
                $latestPayment = $paidRow->latest_payment_at ?? null;
                $amount = (float) $doc->amount;

                $invoiceList = collect(explode(',', (string) ($doc->invoice_no ?? '')))
                    ->map(fn ($v) => $normalizeInvKey($v))
                    ->filter(fn ($v) => $v !== '')
                    ->merge([$normalizeInvKey($doc->po_no ?? '')])
                    ->merge([$normalizeInvKey($doc->sales_note_no ?? '')])
                    ->unique()
                    ->values();
                $activeReturnMap = $isOnline ? $onlineReturnMap : $returnMap;
                $activeReturnQtyMap = $isOnline ? $onlineReturnQtyMap : $returnQtyMap;
                $returned = (float) $invoiceList->sum(function ($inv) use ($activeReturnMap) {
                    return (float) ($activeReturnMap[$inv] ?? 0);
                });
                $returnedQty = (int) $invoiceList->sum(function ($inv) use ($activeReturnQtyMap) {
                    return (int) ($activeReturnQtyMap[$inv] ?? 0);
                });
                $salesNoteAmount = (float) ($doc->sales_note_amount ?? 0);
                $effectiveAdjustment = max($returned, $recordedAdjustment);
                $remainingReturnAdjustment = min(max($returned - $recordedAdjustment, 0), max($amount - $paid, 0));
                $autoSettledByReturn = $returned > 0 && (
                    $returned >= $amount
                    || ($salesNoteAmount > 0 && $returned >= $salesNoteAmount)
                    || $paid >= ($amount / 2)
                );
                $documentDateCandidates = collect([
                    $doc->order_date ?? null,
                    $doc->waybill_date ?? null,
                    $doc->created_at ?? null,
                    $doc->updated_at ?? null,
                ])->filter();
                $effectiveDate = $documentDateCandidates->isNotEmpty()
                    ? $documentDateCandidates->map(fn ($value) => \Carbon\Carbon::parse($value))->sort()->first()
                    : null;

                $doc->paid_amount = $paid;
                $doc->recorded_adjustment = $recordedAdjustment;
                $doc->return_amount = $returned;
                $doc->return_qty = $returnedQty;
                $doc->remaining_return_adjustment = $remainingReturnAdjustment;
                // ONLINE active-invoice rule is exact: authoritative amount - real paid - valid returns.
                // Keep the existing LOCAL/consignment settlement behavior unchanged.
                $doc->due_amount = $isOnline
                    ? max($amount - $paid - $returned, 0)
                    : ($autoSettledByReturn ? 0 : max($amount - $paid - $effectiveAdjustment, 0));
                $doc->latest_payment_at = $latestPayment;
                $doc->effective_date = $effectiveDate?->copy();
                return $doc;
            });

        $customerTermsMap = DB::connection('masterlist')->table('customers')
            ->whereIn('id', $documents->pluck('customer_id')->filter()->unique()->values())
            ->pluck('terms', 'id');

        $unpaidDocuments = $documents->filter(fn ($doc) => $doc->due_amount > 0);
        $agingStats = ['30' => 0, '60' => 0, '90' => 0, '120' => 0, '150' => 0];
        $today = now()->startOfDay();

        $unpaidDocuments
            ->groupBy('customer_id')
            ->each(function ($docs) use (&$agingStats, $today) {
                $oldest = $docs
                    ->filter(fn ($doc) => !empty($doc->effective_date))
                    ->sortBy(fn ($doc) => $doc->effective_date?->timestamp)
                    ->first();

                $ageDays = $oldest && $oldest->effective_date
                    ? $oldest->effective_date->copy()->startOfDay()->diffInDays($today)
                    : 0;

                // The business aging cards roll over the day after a full month:
                // May 1 still counts in 30 on June 1, then moves to 60 on June 2.
                $bucket = match (true) {
                    $ageDays <= 31 => '30',
                    $ageDays <= 61 => '60',
                    $ageDays <= 91 => '90',
                    $ageDays <= 121 => '120',
                    default => '150',
                };

                $agingStats[$bucket]++;
            });

        $payors = $documents
            ->groupBy('customer_id')
            ->map(function ($docs) use ($customerTermsMap, $today) {
                $unpaidDocs = $docs->filter(fn ($doc) => $doc->due_amount > 0);
                $actionableDocs = $docs->filter(function ($doc) {
                    if ($doc->source_type === 'online_report') {
                        return $doc->due_amount > 0;
                    }

                    return $doc->due_amount > 0
                        || (float) ($doc->remaining_return_adjustment ?? 0) > 0;
                });
                if ($actionableDocs->isEmpty()) {
                    return null;
                }

                $first = $docs->first();
                $latest = $actionableDocs->sortByDesc(fn ($doc) => $doc->effective_date?->timestamp ?? 0)->first();
                $partialDocs = $docs->filter(fn ($doc) => $doc->paid_amount > 0 && $doc->due_amount > 0);
                $paidDocs = $docs->filter(fn ($doc) => $doc->paid_amount > 0 && $doc->due_amount <= 0);
                $todayString = now()->toDateString();
                $partialToday = $partialDocs->filter(fn ($doc) => $doc->latest_payment_at && \Carbon\Carbon::parse($doc->latest_payment_at)->toDateString() === $todayString);
                $paidToday = $paidDocs->filter(fn ($doc) => $doc->latest_payment_at && \Carbon\Carbon::parse($doc->latest_payment_at)->toDateString() === $todayString);
                $latestPartialPayment = $partialDocs->pluck('latest_payment_at')->filter()->sortDesc()->first();
                $latestPaidPayment = $paidDocs->pluck('latest_payment_at')->filter()->sortDesc()->first();
                $termsValue = $customerTermsMap->get($first->customer_id);
                $termsDays = is_numeric($termsValue) ? max((int) $termsValue, 0) : null;
                $overdueDocs = $unpaidDocs->filter(function ($doc) use ($termsDays, $today) {
                    if ($termsDays === null || empty($doc->effective_date)) {
                        return false;
                    }

                    $ageDays = $doc->effective_date->copy()->startOfDay()->diffInDays($today);
                    return $ageDays > $termsDays;
                });
                $oldestOverdue = $overdueDocs->sortBy(fn ($doc) => $doc->effective_date?->timestamp ?? PHP_INT_MAX)->first();
                $oldestOverdueAgeDays = ($oldestOverdue && $oldestOverdue->effective_date)
                    ? $oldestOverdue->effective_date->copy()->startOfDay()->diffInDays($today)
                    : null;

                return [
                    'customer_id' => $first->customer_id,
                    'name' => $first->customer_name,
                    'po_numbers' => $actionableDocs->pluck('po_no')->filter()->unique()->values()->all(),
                    'invoice_count' => $docs->count(),
                    'partial_count' => $partialDocs->count(),
                    'partial_new_count' => $partialToday->count(),
                    'partial_latest_date' => $latestPartialPayment ? \Carbon\Carbon::parse($latestPartialPayment)->format('Y-m-d') : null,
                    'paid_count' => $paidDocs->count(),
                    'paid_new_count' => $paidToday->count(),
                    'paid_latest_date' => $latestPaidPayment ? \Carbon\Carbon::parse($latestPaidPayment)->format('Y-m-d') : null,
                    'total_due' => $unpaidDocs->sum('due_amount'),
                    'latest_date' => $latest?->effective_date?->format('Y/m/d'),
                    'terms_days' => $termsDays,
                    'has_overdue' => $overdueDocs->isNotEmpty(),
                    'overdue_invoice_count' => $overdueDocs->count(),
                    'oldest_overdue_days' => $oldestOverdueAgeDays,
                    'oldest_overdue_by_days' => ($termsDays !== null && $oldestOverdueAgeDays !== null)
                        ? max($oldestOverdueAgeDays - $termsDays, 0)
                        : null,
                ];
            })
            ->filter()
            ->sortBy('name')
            ->values();

        $page = max((int) request()->query('page', 1), 1);
        $perPage = 50;
        $total = $payors->count();
        $pagedPayors = $payors->slice(($page - 1) * $perPage, $perPage)->values();

        return response()->json([
            'success' => true,
            'payors' => $pagedPayors,
            'aging_stats' => $agingStats,
            'page' => $page,
            'per_page' => $perPage,
            'total' => $total,
            'last_page' => max((int) ceil($total / $perPage), 1),
        ]);
    } catch (\Throwable $e) {
        Log::error('Payments data error: ' . $e->getMessage());
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.payments.data');

Route::get('/admin/payments/customer/{customerId}', function ($customerId) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

    try {
        $customer = DB::connection('masterlist')->table('customers')->where('id', $customerId)->first();
        if (!$customer) {
            $customer = DB::connection('sales')->table('sales_orders')
                ->where('customer_id', $customerId)
                ->select('customer_id as id', 'customer_name as name')
                ->first();
        }
        if (!$customer) {
            // Online-only buyers (e.g. LAZADA/SHOPEE) have no masterlist/sales-order record.
            $onlineBuyer = DB::connection('sales')->table('online_reports')
                ->where(function ($q) use ($customerId) {
                    $q->where('notes_data', 'LIKE', '%"customer_id":' . $customerId . ',%')
                        ->orWhere('notes_data', 'LIKE', '%"customer_id":' . $customerId . '}%');
                })
                ->orderBy('created_at', 'desc')
                ->first();
            if ($onlineBuyer) {
                $buyerNotes = json_decode($onlineBuyer->notes_data ?? '[]', true);
                $buyerName = 'Online Buyer';
                if (is_array($buyerNotes)) {
                    foreach ($buyerNotes as $buyerNote) {
                        if (is_array($buyerNote) && (int) ($buyerNote['customer_id'] ?? 0) === (int) $customerId) {
                            $buyerName = (string) ($buyerNote['customer_name'] ?? 'Online Buyer');
                            break;
                        }
                    }
                }
                $customer = (object) ['id' => (int) $customerId, 'name' => $buyerName];
            }
        }
        if (!$customer) throw new \Exception('Customer not found.');

        $banks = DB::connection('masterlist')->table('customer_bank_accounts')
            ->where('customer_id', $customerId)
            ->orderBy('id')
            ->get();

        $paidRows = DB::connection('accounting')->table('process_payment_invoices')
            ->select('source_type', 'source_id', DB::raw('SUM(paid_amount) as paid_total'), DB::raw('SUM(adjustment) as adjustment_total'))
            ->groupBy('source_type', 'source_id')
            ->get()
            ->keyBy(fn ($row) => $row->source_type . ':' . $row->source_id);

        // Online payments are keyed per exact invoice number (one report can hold several invoices)
        $onlinePaidRows = DB::connection('accounting')->table('process_payment_invoices')
            ->select('source_type', 'source_id', 'invoice_no', DB::raw('SUM(paid_amount) as paid_total'), DB::raw('SUM(adjustment) as adjustment_total'))
            ->where('source_type', 'online_report')
            ->groupBy('source_type', 'source_id', 'invoice_no')
            ->get()
            ->keyBy(fn ($row) => $row->source_type . ':' . $row->source_id . ':' . $row->invoice_no);

        $normalizeInvKey = static fn ($v) => strtoupper(preg_replace('/\s+/', '', trim((string) $v)));

        $rawReturnRows = DB::connection('sales')->table('sales_returns as sr')
            ->join('sales_return_items as sri', 'sri.sales_return_id', '=', 'sr.id')
            ->whereNotNull('sr.invoice_no')
            ->whereRaw("UPPER(TRIM(COALESCE(sr.status, ''))) NOT IN ('CANCELLED', 'VOID')")
            ->select(
                'sr.invoice_no',
                'sr.status',
                DB::raw("SUM(COALESCE(sri.return_amount, sri.subtotal, 0)) as return_total"),
                DB::raw("SUM(sri.quantity) as return_qty")
            )
            ->groupBy('sr.invoice_no', 'sr.status')
            ->get();

        // Preserve the existing LOCAL return behavior, but ONLINE may subtract only
        // valid Completed returns from its authoritative invoice amount.
        $returnMap = [];
        $returnQtyMap = [];
        $onlineReturnMap = [];
        $onlineReturnQtyMap = [];
        foreach ($rawReturnRows as $row) {
            $rawInvoice = (string) ($row->invoice_no ?? '');
            $total = (float) ($row->return_total ?? 0);
            if ($rawInvoice === '' || $total <= 0) continue;
            $qty = (int) ($row->return_qty ?? 0);
            $isCompletedReturn = strtoupper(trim((string) ($row->status ?? ''))) === 'COMPLETED';

            $keys = [];
            $keys[] = $normalizeInvKey($rawInvoice);

            foreach (preg_split('/[,\s\/]+/', $rawInvoice) as $token) {
                $token = trim((string) $token);
                if ($token === '') continue;
                $keys[] = $normalizeInvKey($token);
            }

            if (preg_match_all('/SN-\d+/i', $rawInvoice, $m) && !empty($m[0])) {
                foreach ($m[0] as $sn) {
                    $sn = trim((string) $sn);
                    if ($sn === '') continue;
                    $keys[] = $normalizeInvKey($sn);
                }
            }

            $keys = array_values(array_unique(array_filter($keys, fn ($k) => $k !== '')));
            foreach ($keys as $k) {
                $returnMap[$k] = (float) ($returnMap[$k] ?? 0) + $total;
                $returnQtyMap[$k] = (int) ($returnQtyMap[$k] ?? 0) + $qty;

                if ($isCompletedReturn) {
                    $onlineReturnMap[$k] = (float) ($onlineReturnMap[$k] ?? 0) + $total;
                    $onlineReturnQtyMap[$k] = (int) ($onlineReturnQtyMap[$k] ?? 0) + $qty;
                }
            }
        }

        $salesOrders = DB::connection('sales')->table('sales_orders as so')
            ->leftJoin('sales_notes as sn', 'sn.id', '=', 'so.sales_note_id')
            ->where('so.customer_id', $customerId)
            ->where('so.order_number', 'NOT LIKE', 'ONL-%')
            ->where(function ($query) {
                $query->whereIn('so.status', ['Closed', 'Confirmed'])
                    ->orWhere('sn.status', 'Closed');
            })
            ->select(
                DB::raw("'sales_order' as source_type"),
                'so.id as source_id',
                'so.order_number as po_no',
                'sn.sales_number as sales_note_no',
                'sn.net_total as sales_note_amount',
                'sn.order_date',
                DB::raw("COALESCE(NULLIF(so.invoice_numbers, ''), so.order_number) as invoice_no"),
                'so.total_amount as amount',
                'so.status',
                'so.created_at',
                'so.updated_at',
                'so.waybill_date'
            )
            ->get();

        $consignmentInvoices = DB::connection('sales')->table('consignment_invoices')
            ->where('customer_id', $customerId)
            ->whereNotIn('status', ['Cancelled', 'Void'])
            ->select(
                DB::raw("'consignment_invoice' as source_type"),
                'id as source_id',
                DB::raw('invoice_number as po_no'),
                'invoice_number as invoice_no',
                'total_amount as amount',
                'status',
                'created_at',
                'updated_at',
                DB::raw('NULL as order_date'),
                DB::raw('NULL as waybill_date')
            )
            ->get();

        $termsDays = is_numeric($customer->terms ?? null) ? max((int) $customer->terms, 0) : null;
        $today = now()->startOfDay();

        $onlineInvoices = hatdogBuildPaymentOnlineInvoices((int) $customerId);

        $invoices = $salesOrders->concat($consignmentInvoices)->concat($onlineInvoices)
            ->map(function ($doc) use ($paidRows, $onlinePaidRows, $returnMap, $returnQtyMap, $onlineReturnMap, $onlineReturnQtyMap, $normalizeInvKey, $termsDays, $today) {
                $isOnline = $doc->source_type === 'online_report';
                $paidKey = $isOnline
                    ? $doc->source_type . ':' . $doc->source_id . ':' . $doc->invoice_no
                    : $doc->source_type . ':' . $doc->source_id;
                $settlementRow = $isOnline ? $onlinePaidRows->get($paidKey) : $paidRows->get($paidKey);
                $paid = (float) ($settlementRow->paid_total ?? 0);
                $recordedAdjustment = (float) ($settlementRow->adjustment_total ?? 0);
                $amount = (float) $doc->amount;

                $invoiceList = collect(explode(',', (string) ($doc->invoice_no ?? '')))
                    ->map(fn ($v) => $normalizeInvKey($v))
                    ->filter(fn ($v) => $v !== '')
                    ->merge([$normalizeInvKey($doc->po_no ?? '')])
                    ->merge([$normalizeInvKey($doc->sales_note_no ?? '')])
                    ->unique()
                    ->values();
                $activeReturnMap = $isOnline ? $onlineReturnMap : $returnMap;
                $activeReturnQtyMap = $isOnline ? $onlineReturnQtyMap : $returnQtyMap;
                $returned = (float) $invoiceList->sum(function ($inv) use ($activeReturnMap) {
                    return (float) ($activeReturnMap[$inv] ?? 0);
                });
                $returnedQty = (int) $invoiceList->sum(function ($inv) use ($activeReturnQtyMap) {
                    return (int) ($activeReturnQtyMap[$inv] ?? 0);
                });
                $salesNoteAmount = (float) ($doc->sales_note_amount ?? 0);
                $effectiveAdjustment = max($returned, $recordedAdjustment);
                $remainingReturnAdjustment = min(max($returned - $recordedAdjustment, 0), max($amount - $paid, 0));
                $autoSettledByReturn = $returned > 0 && (
                    $returned >= $amount
                    || ($salesNoteAmount > 0 && $returned >= $salesNoteAmount)
                    || $paid >= ($amount / 2)
                );
                              $documentDateCandidates = collect([
                    $doc->order_date ?? null,
                    $doc->waybill_date ?? null,
                    $doc->created_at ?? null,
                    $doc->updated_at ?? null,
                ])->filter();

                // Keep aging calculation separate from the displayed Invoice Date.
                $effectiveDate = $documentDateCandidates->isNotEmpty()
                    ? $documentDateCandidates
                        ->map(fn ($value) => \Carbon\Carbon::parse($value))
                        ->sort()
                        ->first()
                    : null;

                // Actual invoice creation date for every source. Online rows from
                // hatdogBuildPaymentOnlineInvoices already use the finalized ONL Sales Order
                // created_at (falling back to the Online Report only for legacy rows).
                $invoiceDateValue = $doc->created_at ?? null;

                $invoiceDate = $invoiceDateValue
                    ? \Carbon\Carbon::parse($invoiceDateValue)
                    : null;

                $ageDays = $effectiveDate
                    ? $effectiveDate->copy()->startOfDay()->diffInDays($today)
                    : null;

                $hasExceededTerms =
                    $termsDays !== null
                    && $ageDays !== null
                    && $ageDays > $termsDays;

                return [
                    'source_type' => $doc->source_type,
                    'source_id' => $doc->source_id,
                    'po_no' => $doc->po_no,
                    'invoice_no' => $doc->invoice_no,
                    'amount' => $amount,
                    'paid_to_date' => $paid,
                    'returned_amount' => $returned,
                    'returned_qty' => $returnedQty,
                    'adjustment' => $remainingReturnAdjustment,
                    'recorded_adjustment' => $recordedAdjustment,
                    'due' => $isOnline
                        ? max($amount - $paid - $returned, 0)
                        : ($autoSettledByReturn
                            ? 0
                            : max($amount - $paid - $effectiveAdjustment, 0)),
                    'status' => $doc->status,

                    // What Process Payment displays.
                    'date' => $invoiceDate?->format('Y-m-d'),
                    'invoice_date' => $invoiceDate?->format('Y-m-d'),

                    // Keep this for payment terms/aging.
                    'aging_date' => $effectiveDate?->format('Y-m-d'),

                    'terms_days' => $termsDays,
                    'age_days' => $ageDays,
                    'has_exceeded_terms' => $hasExceededTerms,
                    'overdue_days' => $hasExceededTerms
                        ? max($ageDays - $termsDays, 0)
                        : 0,
                ];
            })
            ->filter(function ($doc) {
                if (($doc['source_type'] ?? '') === 'online_report') {
                    return (float) ($doc['due'] ?? 0) > 0;
                }

                return (float) ($doc['due'] ?? 0) > 0
                    || (float) ($doc['adjustment'] ?? 0) > 0;
            })
            ->values();

        $maxNum = DB::connection('accounting')->table('process_payments')
            ->max(DB::raw("CAST(SUBSTRING(payment_no, 5) AS UNSIGNED)"));
        $paymentNo = 'PAY-' . str_pad(((int) $maxNum) + 1, 7, '0', STR_PAD_LEFT);

        return response()->json([
            'success' => true,
            'payment_no' => $paymentNo,
            'customer' => $customer,
            'banks' => $banks,
            'terms_days' => $termsDays,
            'invoices' => $invoices,
        ]);
    } catch (\Throwable $e) {
        Log::error('Payments customer error: ' . $e->getMessage());
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.payments.customer');

Route::get('/admin/payments/customer/{customerId}/returns', function ($customerId) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

    try {
        $usageRows = DB::connection('accounting')->table('process_payment_returns')
            ->whereNotNull('sales_return_id')
            ->orderByDesc('id')
            ->get(['sales_return_id', 'process_payment_id', 'process_payment_invoice_id'])
            ->groupBy('sales_return_id');

        $returns = DB::connection('sales')->table('sales_returns as sr')
            ->where('sr.customer_id', $customerId)
            ->whereRaw("UPPER(TRIM(COALESCE(sr.status, ''))) NOT IN ('CANCELLED', 'VOID')")
            ->select(
                'sr.id',
                'sr.return_number',
                'sr.created_at',
                'sr.invoice_no',
                'sr.total_amount',
                'sr.remarks'
            )
            ->orderByDesc('sr.id')
            ->get()
            ->map(function ($ret) use ($usageRows) {
                $items = DB::connection('sales')->table('sales_return_items')
                    ->where('sales_return_id', $ret->id)
                    ->select('product_code', 'application', 'description', 'quantity', 'subtotal', 'return_amount')
                    ->get();
                $usage = $usageRows->get((int) $ret->id, collect())->first();
                return [
                    'id' => (int) $ret->id,
                    'return_order_id' => (int) $ret->id,
                    'return_number' => (string) $ret->return_number,
                    'return_date' => (string) ($ret->created_at ? date('Y-m-d', strtotime($ret->created_at)) : ''),
                    'invoice_no' => (string) ($ret->invoice_no ?? ''),
                    'total_amount' => (float) ($ret->total_amount ?? 0),
                    'wallet_adjustment' => (float) ($ret->total_amount ?? 0),
                    'remarks' => (string) ($ret->remarks ?? ''),
                    'is_used' => (bool) $usage,
                    'used_by_payment_id' => $usage ? (int) $usage->process_payment_id : null,
                    'used_process_payment_invoice_id' => ($usage && $usage->process_payment_invoice_id) ? (int) $usage->process_payment_invoice_id : null,
                    'items' => $items->map(fn ($item) => [
                        'product_code' => (string) ($item->product_code ?? ''),
                        'application' => (string) ($item->application ?? ''),
                        'description' => (string) ($item->description ?? ''),
                        'quantity' => (float) ($item->quantity ?? 0),
                        'amount' => (float) (($item->return_amount ?? 0) ?: ($item->subtotal ?? 0)),
                    ])->values()->all(),
                ];
            })
            ->values();

        return response()->json([
            'success' => true,
            'returns' => $returns,
        ]);
    } catch (\Throwable $e) {
        Log::error('Payments customer returns error: ' . $e->getMessage());
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.payments.customer.returns');

// Payments - Manual Return Order lookup. Used only when the user types a Return Order ID.
Route::get('/admin/payments/return/{returnId}', function (int $returnId) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

    try {
        $header = DB::connection('sales')->table('sales_returns')->where('id', $returnId)->first();
        if (!$header) {
            return response()->json(['success' => false, 'message' => 'Return Order ID not found.'], 404);
        }

        $items = DB::connection('sales')->table('sales_return_items')
            ->where('sales_return_id', $returnId)
            ->get();

        $total = isset($header->total_amount) ? (float) $header->total_amount : 0.0;
        if (abs($total) < 0.00001) {
            $total = (float) $items->sum(function ($item) {
                $amount = isset($item->return_amount) ? (float) $item->return_amount : 0.0;
                if (abs($amount) < 0.00001 && isset($item->subtotal)) {
                    $amount = (float) $item->subtotal;
                }
                return $amount;
            });
        }

        $productIds = $items->pluck('product_id')->filter()->map(fn ($id) => (int) $id)->unique()->values();
        $products = $productIds->isEmpty()
            ? collect()
            : DB::connection('masterlist')->table('products')->whereIn('id', $productIds)->get()->keyBy('id');

        $returnItems = $items->map(function ($item) use ($products) {
            $product = isset($item->product_id) ? $products->get((int) $item->product_id) : null;
            $amount = isset($item->return_amount) ? (float) $item->return_amount : 0.0;
            if (abs($amount) < 0.00001 && isset($item->subtotal)) {
                $amount = (float) $item->subtotal;
            }
            return [
                'product_code' => (string) ($item->product_code ?? ($product->item_code ?? $product->product_code ?? '')),
                'application' => (string) ($item->application ?? ($product->application ?? '')),
                'description' => (string) ($item->description ?? ($product->description ?? $product->part_number ?? '')),
                'quantity' => (float) ($item->quantity ?? 0),
                'amount' => $amount,
            ];
        })->values()->all();

        return response()->json([
            'success' => true,
            'return' => [
                'id' => (int) $header->id,
                'return_order_id' => (int) $header->id,
                'sales_return_id' => (int) $header->id,
                'customer_id' => isset($header->customer_id) ? (int) $header->customer_id : null,
                'return_number' => (string) ($header->return_number ?? ''),
                'return_date' => !empty($header->created_at) ? date('Y-m-d', strtotime((string) $header->created_at)) : '',
                'invoice_no' => (string) ($header->invoice_no ?? ''),
                'total_amount' => round($total, 2),
                'wallet_adjustment' => round($total, 2),
                'return_amount' => round($total, 2),
                'remarks' => (string) ($header->remarks ?? ''),
                'items' => $returnItems,
            ],
        ]);
    } catch (\Throwable $e) {
        Log::error('Payments manual return lookup error: ' . $e->getMessage());
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.payments.return.lookup');

$hatdogProcessPayment = function (Request $request) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

    $data = $request->validate([
        'customer_id' => 'required|integer',
        'customer_name' => 'required|string',
        'payment_no' => 'required|string',
        'payment_date' => 'required|date',
        'invoices' => 'required|array|min:1',
        'invoices.*.source_type' => 'required|string',
        'invoices.*.source_id' => 'required|integer',
        'invoices.*.invoice_no' => 'required|string',
        'invoices.*.invoice_amount' => 'required|numeric',
        'invoices.*.due_amount' => 'required|numeric',
        'invoices.*.adjustment' => 'nullable|numeric',
        'invoices.*.paid_amount' => 'required|numeric|min:0',
        'invoices.*.remarks' => 'nullable|string',
        'checks' => 'nullable|array',
        'checks.*.customer_bank_account_id' => 'nullable|integer',
        'checks.*.bank_name' => 'nullable|string',
        'checks.*.account_number' => 'nullable|string',
        'checks.*.check_no' => 'nullable|string',
        'checks.*.check_date' => 'nullable|date',
        'checks.*.credit_amount' => 'nullable|numeric',
        'returns' => 'nullable|array',
        'returns.*.sales_return_id' => 'required|integer',
        'returns.*.return_number' => 'required|string',
        'returns.*.return_amount' => 'required|numeric',
        'returns.*.source_type' => 'nullable|string',
        'returns.*.source_id' => 'nullable|integer',
        'returns.*.invoice_no' => 'nullable|string',
        'payment_invoice_group_id' => 'nullable|integer',
        'online_percent' => 'nullable|numeric|min:0|max:100',
        'online_payment' => 'nullable|numeric',
        'retotal_amount' => 'nullable|numeric',
    ]);

    try {
        foreach ($data['invoices'] as $invoice) {
            $due = max((float) ($invoice['due_amount'] ?? 0), 0);
            $paid = max((float) ($invoice['paid_amount'] ?? 0), 0);
            if ($due > 0.00001 && $paid <= 0) {
                throw new \InvalidArgumentException('Paid amount must be greater than zero when an invoice still has an amount due.');
            }
        }

        DB::connection('accounting')->beginTransaction();
        $actor = hatdogAuditActor($user);
        $customer = \App\Models\Customer::on('masterlist')->find($data['customer_id']);

        $totalPaid = collect($data['invoices'])->sum(fn ($invoice) => (float) $invoice['paid_amount']);
        $paymentInsert = [
            'payment_no' => $data['payment_no'],
            'customer_id' => $data['customer_id'],
            'customer_name' => $data['customer_name'],
            'payment_date' => $data['payment_date'],
            'total_paid' => $totalPaid,
            'status' => 'Posted',
            'created_at' => now(),
            'updated_at' => now(),
        ];
        $paymentSchema = Schema::connection('accounting');
        if ($paymentSchema->hasColumn('process_payments', 'payment_invoice_group_id')) {
            $paymentInsert['payment_invoice_group_id'] = $data['payment_invoice_group_id'] ?? null;
        }
        if ($paymentSchema->hasColumn('process_payments', 'online_percent')) {
            $paymentInsert['online_percent'] = (float) ($data['online_percent'] ?? 0);
        }
        if ($paymentSchema->hasColumn('process_payments', 'online_payment')) {
            $paymentInsert['online_payment'] = (float) ($data['online_payment'] ?? 0);
        }
        if ($paymentSchema->hasColumn('process_payments', 'retotal_amount')) {
            $paymentInsert['retotal_amount'] = (float) ($data['retotal_amount'] ?? collect($data['invoices'])->sum(fn ($invoice) => (float) ($invoice['invoice_amount'] ?? 0)));
        }
        $paymentId = DB::connection('accounting')->table('process_payments')->insertGetId($paymentInsert);

        $insertedInvoiceIds = [];
        $insertedInvoiceMap = [];
        foreach ($data['invoices'] as $invoice) {
            $due = (float) $invoice['due_amount'];
            $paid = (float) $invoice['paid_amount'];
            $invId = DB::connection('accounting')->table('process_payment_invoices')->insertGetId([
                'process_payment_id' => $paymentId,
                'source_type' => $invoice['source_type'],
                'source_id' => $invoice['source_id'],
                'invoice_no' => $invoice['invoice_no'],
                'invoice_amount' => $invoice['invoice_amount'],
                'due_amount' => $due,
                'adjustment' => $invoice['adjustment'] ?? 0,
                'paid_amount' => $paid,
                'payment_status' => $paid >= $due ? 'Full' : 'Partial',
                'remarks' => $invoice['remarks'] ?? null,
                'created_at' => now(),
                'updated_at' => now(),
            ]);
            $insertedInvoiceIds[] = $invId;
            $invoiceMapKey = (string) $invoice['source_type'] . ':' . (int) $invoice['source_id'] . ':' . strtoupper(preg_replace('/\s+/', '', trim((string) $invoice['invoice_no'])));
            $insertedInvoiceMap[$invoiceMapKey] = $invId;
        }

        foreach (($data['returns'] ?? []) as $ret) {
            $linkedInvoiceId = null;
            if (!empty($ret['source_type']) && !empty($ret['source_id'])) {
                $returnInvoiceNo = strtoupper(preg_replace('/\s+/', '', trim((string) ($ret['invoice_no'] ?? ''))));
                $returnMapKey = (string) $ret['source_type'] . ':' . (int) $ret['source_id'] . ':' . $returnInvoiceNo;
                $linkedInvoiceId = $insertedInvoiceMap[$returnMapKey] ?? null;
            }
            if (!$linkedInvoiceId && !empty($ret['invoice_no'])) {
                $normalizedReturnNo = strtoupper(preg_replace('/\s+/', '', trim((string) $ret['invoice_no'])));
                foreach ($data['invoices'] as $invoiceIndex => $invoiceRow) {
                    $normalizedInvoiceNo = strtoupper(preg_replace('/\s+/', '', trim((string) ($invoiceRow['invoice_no'] ?? ''))));
                    if ($normalizedReturnNo !== '' && $normalizedReturnNo === $normalizedInvoiceNo) {
                        $linkedInvoiceId = $insertedInvoiceIds[$invoiceIndex] ?? null;
                        break;
                    }
                }
            }

            DB::connection('accounting')->table('process_payment_returns')->insert([
                'process_payment_id' => $paymentId,
                'process_payment_invoice_id' => $linkedInvoiceId,
                'sales_return_id' => $ret['sales_return_id'],
                'return_number' => $ret['return_number'],
                'return_amount' => $ret['return_amount'],
                'created_at' => now(),
                'updated_at' => now(),
            ]);
        }

        foreach (($data['checks'] ?? []) as $check) {
            if (empty($check['bank_name']) && empty($check['account_number']) && empty($check['check_no']) && empty($check['credit_amount'])) {
                continue;
            }

            DB::connection('accounting')->table('process_payment_checks')->insert([
                'process_payment_id' => $paymentId,
                'customer_bank_account_id' => $check['customer_bank_account_id'] ?? null,
                'bank_name' => $check['bank_name'] ?? null,
                'account_number' => $check['account_number'] ?? null,
                'check_no' => $check['check_no'] ?? null,
                'check_date' => $check['check_date'] ?? null,
                'credit_amount' => $check['credit_amount'] ?? 0,
                'created_at' => now(),
                'updated_at' => now(),
            ]);
        }

        $payment = DB::connection('accounting')->table('process_payments')->where('id', $paymentId)->first();
        $paymentInvoices = DB::connection('accounting')->table('process_payment_invoices')
            ->where('process_payment_id', $paymentId)
            ->get()
            ->map(fn ($row) => (array) $row)
            ->values()
            ->all();
        $paymentChecks = DB::connection('accounting')->table('process_payment_checks')
            ->where('process_payment_id', $paymentId)
            ->get()
            ->map(fn ($row) => (array) $row)
            ->values()
            ->all();
        $recordName = trim((string) (($data['customer_name'] ?? '') !== '' ? $data['customer_name'] : ('Payment ' . $data['payment_no'])));

        hatdogWriteAuditTrail([
            'module' => 'payments',
            'action' => 'Processed',
            'source_connection' => 'accounting',
            'source_table' => 'process_payments',
            'source_id' => $paymentId,
            'display_id' => (string) $data['payment_no'],
            'record_name' => $recordName,
            'user_name' => $actor['name'],
            'user_identifier' => $actor['identifier'],
            'audit_data' => [
                'payment' => $payment ? (array) $payment : null,
                'customer' => $customer?->toArray(),
                'payment_invoices' => $paymentInvoices,
                'payment_checks' => $paymentChecks,
                'request_payload' => [
                    'payment_date' => $data['payment_date'],
                    'invoices' => collect($data['invoices'])->values()->all(),
                    'checks' => collect($data['checks'] ?? [])->values()->all(),
                    'returns' => collect($data['returns'] ?? [])->values()->all(),
                    'payment_invoice_group_id' => $data['payment_invoice_group_id'] ?? null,
                    'online_percent' => (float) ($data['online_percent'] ?? 0),
                    'online_payment' => (float) ($data['online_payment'] ?? 0),
                    'retotal_amount' => (float) ($data['retotal_amount'] ?? 0),
                ],
            ],
        ]);

        DB::connection('accounting')->commit();
        return response()->json(['success' => true, 'payment_id' => $paymentId]);
    } catch (\Throwable $e) {
        DB::connection('accounting')->rollBack();
        Log::error('Process payment error: ' . $e->getMessage());
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
};

Route::post('/admin/payments/process', $hatdogProcessPayment)->name('admin.payments.process');

$hatdogBuildProcessPaymentDetail = function (int $paymentId): array {
    $payment = DB::connection('accounting')->table('process_payments')->where('id', $paymentId)->first();
    if (!$payment) {
        throw new \Exception('Payment record not found.');
    }

    $customer = DB::connection('masterlist')->table('customers')->where('id', $payment->customer_id)->first();
    if (!$customer) {
        $customer = (object) [
            'id' => $payment->customer_id,
            'name' => $payment->customer_name,
            'contact_number' => null,
            'contact_person' => null,
            'address' => null,
            'terms' => null,
        ];
    }

    $banks = DB::connection('masterlist')->table('customer_bank_accounts')
        ->where('customer_id', $payment->customer_id)
        ->orderBy('id')
        ->get()
        ->values();

    $invoiceRows = DB::connection('accounting')->table('process_payment_invoices')
        ->where('process_payment_id', $paymentId)
        ->orderBy('id')
        ->get();

    $checkRows = DB::connection('accounting')->table('process_payment_checks')
        ->where('process_payment_id', $paymentId)
        ->orderBy('id')
        ->get();

    $returnRows = DB::connection('accounting')->table('process_payment_returns')
        ->where('process_payment_id', $paymentId)
        ->orderBy('id')
        ->get();

    $salesOrderIds = $invoiceRows->where('source_type', 'sales_order')->pluck('source_id')->unique()->values();
    $consignmentIds = $invoiceRows->where('source_type', 'consignment_invoice')->pluck('source_id')->unique()->values();
    $onlineInvoiceRows = $invoiceRows->where('source_type', 'online_report')->values();
    $normalizeHistoryInvoice = static fn ($value) => strtoupper(preg_replace('/\s+/', '', trim((string) $value)));

    $salesOrderMap = $salesOrderIds->isEmpty()
        ? collect()
        : DB::connection('sales')->table('sales_orders as so')
            ->leftJoin('sales_notes as sn', 'sn.id', '=', 'so.sales_note_id')
            ->whereIn('so.id', $salesOrderIds)
            ->select(
                'so.id as source_id',
                'so.order_number as po_no',
                'sn.sales_number as sales_note_no',
                'sn.order_date',
                'so.waybill_date',
                'so.created_at',
                'so.updated_at'
            )
            ->get()
            ->keyBy('source_id');

    $consignmentMap = $consignmentIds->isEmpty()
        ? collect()
        : DB::connection('sales')->table('consignment_invoices')
            ->whereIn('id', $consignmentIds)
            ->select(
                'id as source_id',
                DB::raw('invoice_number as po_no'),
                'created_at',
                'updated_at',
                DB::raw('NULL as sales_note_no'),
                DB::raw('NULL as order_date'),
                DB::raw('NULL as waybill_date')
            )
            ->get()
            ->keyBy('source_id');

    // Payment History only needs the exact online invoices saved on this Payment No.
    // Do not call hatdogBuildOnlineInvoices(customer): that scans all online reports and
    // all ONL Sales Orders for the customer before the History modal can open.
    $onlineMap = collect();
    if ($onlineInvoiceRows->isNotEmpty()) {
        $onlineReportIds = $onlineInvoiceRows->pluck('source_id')->map('intval')->unique()->values();
        $onlineReports = DB::connection('sales')->table('online_reports')
            ->whereIn('id', $onlineReportIds)
            ->get(['id', 'created_at', 'updated_at'])
            ->keyBy('id');

        $onlineOrdersQuery = DB::connection('sales')->table('sales_orders')
            ->whereIn('status', ['Confirmed', 'Closed'])
            ->where(function ($q) use ($onlineReportIds) {
                foreach ($onlineReportIds as $reportId) {
                    $q->orWhere('order_number', 'LIKE', 'ONL-' . (int) $reportId . '-%');
                }
            })
            ->orderByDesc('id')
            ->get(['id', 'order_number', 'invoice_numbers', 'created_at', 'updated_at']);

        foreach ($onlineOrdersQuery as $order) {
            if (!preg_match('/^ONL-(\d+)-/', (string) $order->order_number, $match)) continue;
            $reportId = (int) $match[1];
            $invoiceValues = json_decode((string) ($order->invoice_numbers ?? ''), true);
            if (!is_array($invoiceValues)) {
                $invoiceValues = preg_split('/[,\n\r]+/', (string) ($order->invoice_numbers ?? '')) ?: [];
            }
            foreach ($invoiceValues as $invoiceValue) {
                $key = $reportId . ':' . $normalizeHistoryInvoice($invoiceValue);
                if (!isset($onlineMap[$key])) {
                    $onlineMap[$key] = (object) [
                        'source_id' => $reportId,
                        'po_no' => (string) $invoiceValue,
                        'created_at' => $order->created_at,
                        'updated_at' => $order->updated_at ?? $order->created_at,
                        'order_date' => null,
                        'waybill_date' => null,
                    ];
                }
            }
        }

        foreach ($onlineInvoiceRows as $invoiceRow) {
            $key = (int) $invoiceRow->source_id . ':' . $normalizeHistoryInvoice($invoiceRow->invoice_no);
            if (isset($onlineMap[$key])) continue;
            $report = $onlineReports->get((int) $invoiceRow->source_id);
            $onlineMap[$key] = (object) [
                'source_id' => (int) $invoiceRow->source_id,
                'po_no' => (string) $invoiceRow->invoice_no,
                'created_at' => $report->created_at ?? null,
                'updated_at' => $report->updated_at ?? ($report->created_at ?? null),
                'order_date' => null,
                'waybill_date' => null,
            ];
        }
    }

    $invoiceNumbers = $invoiceRows->pluck('invoice_no')->filter()->unique()->values();
    $returnInfoMap = [];
    if ($invoiceNumbers->isNotEmpty()) {
        $salesReturnRows = DB::connection('sales')->table('sales_returns as sr')
            ->leftJoin('sales_return_items as sri', 'sri.sales_return_id', '=', 'sr.id')
            ->whereIn('sr.invoice_no', $invoiceNumbers)
            ->whereRaw("UPPER(TRIM(COALESCE(sr.status, ''))) NOT IN ('CANCELLED', 'VOID')")
            ->select(
                'sr.id', 'sr.invoice_no', 'sr.return_number', 'sr.created_at',
                DB::raw('SUM(COALESCE(sri.return_amount, sri.subtotal, 0)) as return_amount')
            )
            ->groupBy('sr.id', 'sr.invoice_no', 'sr.return_number', 'sr.created_at')
            ->get();

        foreach ($salesReturnRows as $returnRow) {
            $key = $normalizeHistoryInvoice($returnRow->invoice_no ?? '');
            if ($key === '') continue;
            $returnInfoMap[$key] ??= ['numbers' => [], 'amount' => 0.0, 'dates' => []];
            if (!empty($returnRow->return_number)) $returnInfoMap[$key]['numbers'][] = (string) $returnRow->return_number;
            $returnInfoMap[$key]['amount'] += (float) ($returnRow->return_amount ?? 0);
            if (!empty($returnRow->created_at)) $returnInfoMap[$key]['dates'][] = substr((string) $returnRow->created_at, 0, 10);
        }
    }

    $termsDays = is_numeric($customer->terms ?? null) ? max((int) $customer->terms, 0) : null;
    $today = now()->startOfDay();

    $invoices = $invoiceRows->map(function ($row) use ($salesOrderMap, $consignmentMap, $onlineMap, $normalizeHistoryInvoice, $returnInfoMap, $payment, $termsDays, $today) {
        if ($row->source_type === 'sales_order') {
            $sourceDoc = $salesOrderMap->get($row->source_id);
        } elseif ($row->source_type === 'consignment_invoice') {
            $sourceDoc = $consignmentMap->get($row->source_id);
        } elseif ($row->source_type === 'online_report') {
            $sourceDoc = $onlineMap->get((int) $row->source_id . ':' . $normalizeHistoryInvoice($row->invoice_no));
        } else {
            $sourceDoc = null;
        }

        $documentDateCandidates = collect([
            $sourceDoc->order_date ?? null,
            $sourceDoc->waybill_date ?? null,
            $sourceDoc->created_at ?? null,
            $sourceDoc->updated_at ?? null,
        ])->filter();

        $effectiveDate = $documentDateCandidates->isNotEmpty()
            ? $documentDateCandidates->map(fn ($value) => \Carbon\Carbon::parse($value))->sort()->first()
            : null;

        $ageDays = $effectiveDate
            ? $effectiveDate->copy()->startOfDay()->diffInDays($today)
            : null;
        $hasExceededTerms = $termsDays !== null && $ageDays !== null && $ageDays > $termsDays;
        $invoiceCreatedDate = !empty($sourceDoc?->created_at)
            ? \Carbon\Carbon::parse($sourceDoc->created_at)->format('Y-m-d')
            : null;
        $returnInfo = $returnInfoMap[$normalizeHistoryInvoice($row->invoice_no)] ?? ['numbers' => [], 'amount' => 0.0, 'dates' => []];

        return [
            'id' => (int) $row->id,
            'source_type' => (string) $row->source_type,
            'source_id' => (int) $row->source_id,
            'po_no' => (string) ($sourceDoc->po_no ?? $row->invoice_no),
            'invoice_no' => (string) $row->invoice_no,
            'amount' => (float) $row->invoice_amount,
            'invoice_amount' => (float) $row->invoice_amount,
            'due' => (float) $row->due_amount,
            'due_amount' => (float) $row->due_amount,
            'adjustment' => (float) $row->adjustment,
            'paid_amount' => (float) $row->paid_amount,
            'remarks' => $row->remarks,
            'payment_status' => (string) $row->payment_status,
            'return_number' => implode(', ', array_values(array_unique($returnInfo['numbers'] ?? []))),
            'return_amount' => round((float) ($returnInfo['amount'] ?? 0), 2),
            'invoice_date' => $invoiceCreatedDate,
            'date_created' => $invoiceCreatedDate,
            'date' => $invoiceCreatedDate,
            'payment_date' => $payment->payment_date ? \Carbon\Carbon::parse($payment->payment_date)->format('Y-m-d') : null,
            'terms_days' => $termsDays,
            'age_days' => $ageDays,
            'has_exceeded_terms' => $hasExceededTerms,
            'overdue_days' => $hasExceededTerms ? max($ageDays - $termsDays, 0) : 0,
        ];
    })->values();

    $checks = $checkRows->map(fn ($row) => [
        'id' => (int) $row->id,
        'customer_bank_account_id' => $row->customer_bank_account_id ? (int) $row->customer_bank_account_id : null,
        'bank_name' => (string) ($row->bank_name ?? ''),
        'account_number' => (string) ($row->account_number ?? ''),
        'check_no' => (string) ($row->check_no ?? ''),
        'check_date' => $row->check_date,
        'credit_amount' => (float) $row->credit_amount,
    ])->values();

    $returnSalesIds = $returnRows->pluck('sales_return_id')->map('intval')->filter()->unique()->values();
    $salesReturnMap = $returnSalesIds->isEmpty()
        ? collect()
        : DB::connection('sales')->table('sales_returns')
            ->whereIn('id', $returnSalesIds)
            ->get(['id', 'invoice_no', 'created_at', 'remarks'])
            ->keyBy('id');

    $returns = $returnRows->map(function ($row) use ($salesReturnMap) {
        $salesReturn = $salesReturnMap->get((int) $row->sales_return_id);
        return [
            'id' => (int) $row->id,
            'process_payment_id' => (int) $row->process_payment_id,
            'process_payment_invoice_id' => $row->process_payment_invoice_id ? (int) $row->process_payment_invoice_id : null,
            'sales_return_id' => (int) $row->sales_return_id,
            'return_order_id' => (int) $row->sales_return_id,
            'return_number' => (string) $row->return_number,
            'return_amount' => (float) $row->return_amount,
            'wallet_adjustment' => (float) $row->return_amount,
            'invoice_no' => (string) ($salesReturn->invoice_no ?? ''),
            'return_date' => $salesReturn?->created_at ? substr((string) $salesReturn->created_at, 0, 10) : '',
            'remarks' => (string) ($salesReturn->remarks ?? ''),
        ];
    })->values();

    // A group-level Online Percent/Online Payment was historically allocated into
    // process_payment_invoices.adjustment. Resolve the originating group so the
    // UI/print layer can separate that group-level amount from real invoice
    // adjustments (for example sales returns) without changing settlement math.
    $groupDiscount = null;
    $hasNewGroupFields = Schema::connection('accounting')->hasColumn('process_payments', 'payment_invoice_group_id')
        && !empty($payment->payment_invoice_group_id);
    if ($hasNewGroupFields) {
        $groupDiscount = [
            'group_id' => (int) $payment->payment_invoice_group_id,
            'discount_percent' => (float) ($payment->online_percent ?? 0),
            'discount_amount' => (float) ($payment->online_payment ?? 0),
            'online_percent' => (float) ($payment->online_percent ?? 0),
            'online_payment' => (float) ($payment->online_payment ?? 0),
            'retotal_amount' => (float) ($payment->retotal_amount ?? 0),
            'is_new_group_flow' => true,
        ];
    }
    try {
        if (!$hasNewGroupFields && $invoiceRows->isNotEmpty()
            && \Illuminate\Support\Facades\Schema::connection('accounting')->hasTable('payment_invoice_group_items')
            && \Illuminate\Support\Facades\Schema::connection('accounting')->hasTable('payment_invoice_groups')
            && \Illuminate\Support\Facades\Schema::connection('accounting')->hasColumn('payment_invoice_groups', 'discount_percent')
            && \Illuminate\Support\Facades\Schema::connection('accounting')->hasColumn('payment_invoice_groups', 'discount_amount')) {
            $candidateGroupIds = null;

            foreach ($invoiceRows as $invoiceRow) {
                $groupIds = DB::connection('accounting')->table('payment_invoice_group_items')
                    ->where('source_type', (string) $invoiceRow->source_type)
                    ->where('invoice_id', (int) $invoiceRow->source_id)
                    ->when((string) $invoiceRow->source_type === 'online_report', function ($q) use ($invoiceRow) {
                        $q->where('invoice_no', (string) $invoiceRow->invoice_no);
                    })
                    ->pluck('payment_invoice_group_id')
                    ->map(fn ($id) => (int) $id)
                    ->unique()
                    ->values()
                    ->all();

                $candidateGroupIds = $candidateGroupIds === null
                    ? $groupIds
                    : array_values(array_intersect($candidateGroupIds, $groupIds));

                if (empty($candidateGroupIds)) {
                    break;
                }
            }

            if (!empty($candidateGroupIds)) {
                $matchedGroup = DB::connection('accounting')->table('payment_invoice_groups')
                    ->whereIn('id', $candidateGroupIds)
                    ->orderByDesc('updated_at')
                    ->orderByDesc('id')
                    ->first();

                if ($matchedGroup) {
                    $groupDiscount = [
                        'group_id' => (int) $matchedGroup->id,
                        'discount_percent' => (float) ($matchedGroup->discount_percent ?? 0),
                        'discount_amount' => (float) ($matchedGroup->discount_amount ?? 0),
                    ];
                }
            }
        }
    } catch (\Throwable $groupResolveError) {
        // Payment detail/printing must remain available even if an old database
        // does not yet contain the optional group-discount columns.
        $groupDiscount = null;
    }

    return [
        'payment' => [
            'id' => (int) $payment->id,
            'payment_no' => (string) $payment->payment_no,
            'customer_id' => (int) $payment->customer_id,
            'customer_name' => (string) $payment->customer_name,
            'payment_date' => (string) $payment->payment_date,
            'total_paid' => (float) $payment->total_paid,
            'payment_invoice_group_id' => isset($payment->payment_invoice_group_id) && $payment->payment_invoice_group_id ? (int) $payment->payment_invoice_group_id : null,
            'online_percent' => (float) ($payment->online_percent ?? 0),
            'online_payment' => (float) ($payment->online_payment ?? 0),
            'retotal_amount' => (float) ($payment->retotal_amount ?? 0),
            'status' => (string) ($payment->status ?? 'Posted'),
            'remarks' => $payment->remarks,
            'created_at' => $payment->created_at,
            'updated_at' => $payment->updated_at,
        ],
        'customer' => $customer,
        'banks' => $banks,
        'checks' => $checks,
        'invoices' => $invoices,
        'returns' => $returns,
        'terms_days' => $termsDays,
        'group_discount' => $groupDiscount,
    ];
};

Route::get('/admin/payments/history/data', function (Request $request) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

    try {
        $page = max((int) $request->query('page', 1), 1);
        $perPage = 20;
        $search = trim((string) $request->query('search', ''));
        $paymentNo = trim((string) $request->query('payment_no', ''));
        $invoiceSearch = trim((string) $request->query('invoices', ''));
        $paymentDate = trim((string) $request->query('payment_date', ''));
        $amount = trim((string) $request->query('amount', ''));

        $baseQuery = DB::connection('accounting')->table('process_payments');

        if ($search !== '') {
            $like = "%{$search}%";
            $baseQuery->where(function ($q) use ($like) {
                $q->where('customer_name', 'LIKE', $like)
                  ->orWhere('payment_no', 'LIKE', $like)
                  ->orWhere('payment_date', 'LIKE', $like)
                  ->orWhereRaw('CAST(total_paid AS CHAR) LIKE ?', [$like])
                  ->orWhereIn('id', function ($sub) use ($like) {
                      $sub->select('process_payment_id')
                          ->from('process_payment_invoices')
                          ->where('invoice_no', 'LIKE', $like);
                  });
            });
        }
        if ($paymentNo !== '') {
            $baseQuery->where('payment_no', 'LIKE', '%' . $paymentNo . '%');
        }
        if ($invoiceSearch !== '') {
            $baseQuery->whereIn('id', function ($sub) use ($invoiceSearch) {
                $sub->select('process_payment_id')
                    ->from('process_payment_invoices')
                    ->where('invoice_no', 'LIKE', '%' . $invoiceSearch . '%');
            });
        }
        if ($paymentDate !== '') {
            $baseQuery->where('payment_date', 'LIKE', '%' . $paymentDate . '%');
        }
        if ($amount !== '') {
            $normalizedAmount = str_replace([',', 'PHP', 'php', '₱', ' '], '', $amount);
            $baseQuery->whereRaw('CAST(total_paid AS CHAR) LIKE ?', ['%' . $normalizedAmount . '%']);
        }

        $total = (clone $baseQuery)->count();
        $payments = $baseQuery
            ->orderByDesc('payment_date')
            ->orderByDesc('id')
            ->offset(($page - 1) * $perPage)
            ->limit($perPage)
            ->get();

        $paymentIds = $payments->pluck('id')->values();
        $invoiceGroups = $paymentIds->isEmpty()
            ? collect()
            : DB::connection('accounting')->table('process_payment_invoices')
                ->whereIn('process_payment_id', $paymentIds)
                ->orderBy('id')
                ->get()
                ->groupBy('process_payment_id');

        $rows = $payments->map(function ($payment) use ($invoiceGroups) {
            $invoiceRows = $invoiceGroups->get($payment->id, collect());
            $invoiceNumbers = $invoiceRows->pluck('invoice_no')->filter()->unique()->values();

            return [
                'id' => (int) $payment->id,
                'payment_no' => (string) $payment->payment_no,
                'customer_name' => (string) $payment->customer_name,
                'invoice_paid' => $invoiceNumbers->implode(', ') ?: '---',
                'invoice_numbers' => $invoiceNumbers->all(),
                'invoice_count' => $invoiceRows->count(),
                'payment_date' => $payment->payment_date ? \Carbon\Carbon::parse($payment->payment_date)->format('Y-m-d') : '---',
                'total_paid' => (float) $payment->total_paid,
                'status' => (string) ($payment->status ?? 'Posted'),
            ];
        })->values();

        return response()->json([
            'success' => true,
            'rows' => $rows,
            'page' => $page,
            'per_page' => $perPage,
            'total' => $total,
            'last_page' => max((int) ceil($total / $perPage), 1),
        ]);
    } catch (\Throwable $e) {
        Log::error('Payments history data error: ' . $e->getMessage());
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.payments.history.data');

