Route::post('/admin/payments/history/print', function (Request $request) use ($hatdogBuildProcessPaymentDetail) {
    $user = session('user');
    if (!$user) {
        return response()->json(['error' => 'Unauthorized'], 403);
    }

    try {
        $invoiceIds = array_values(array_unique(array_map('intval', $request->input('invoice_ids', []))));
        if (empty($invoiceIds)) {
            return response()->json(['success' => false, 'message' => 'Select at least one item to print.'], 422);
        }

        $rows = DB::connection('accounting')->table('process_payment_invoices')->whereIn('id', $invoiceIds)->get();
        if ($rows->count() !== count($invoiceIds)) {
            return response()->json(['success' => false, 'message' => 'One or more selected invoices no longer exist.'], 422);
        }

        $paymentIds = array_values(array_unique($rows->pluck('process_payment_id')->map('intval')->all()));
        $receipts = [];

        foreach ($paymentIds as $paymentId) {
            $payment = DB::connection('accounting')->table('process_payments')->where('id', $paymentId)->first();
            if (!$payment) {
                return response()->json(['success' => false, 'message' => 'Payment record not found.'], 422);
            }
            if (strtolower((string) ($payment->status ?? 'posted')) !== 'posted') {
                return response()->json(['success' => false, 'message' => 'Payment ' . $payment->payment_no . ' is not Posted and cannot be printed.'], 422);
            }

            $detail = $hatdogBuildProcessPaymentDetail($paymentId);

            $selectedForPayment = $rows->where('process_payment_id', $paymentId)->pluck('id')->map('intval')->all();
            $detail['invoices'] = collect($detail['invoices'] ?? [])->filter(function ($inv) use ($selectedForPayment) {
                return in_array((int) ($inv['id'] ?? 0), $selectedForPayment, true);
            })->values()->all();

            $receipts[] = $detail;
        }

        return response()->json(['success' => true, 'receipts' => $receipts]);
    } catch (\Throwable $e) {
        Log::error('Payments history print error: ' . $e->getMessage());
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.payments.history.print');

