Route::put('/admin/payments/history/{paymentId}', function (Request $request, int $paymentId) use ($hatdogBuildProcessPaymentDetail) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

    $data = $request->validate([
        'customer_id' => 'required|integer',
        'customer_name' => 'required|string',
        'payment_no' => 'required|string',
        'payment_date' => 'required|date',
        'invoices' => 'required|array|min:1',
        'invoices.*.source_type' => 'required|string',
        'invoices.*.source_id' => 'required|integer',
        'invoices.*.invoice_no' => 'required|string',
        'invoices.*.invoice_amount' => 'required|numeric',
        'invoices.*.due_amount' => 'required|numeric',
        'invoices.*.adjustment' => 'nullable|numeric',
        'invoices.*.paid_amount' => 'required|numeric|min:0',
        'invoices.*.remarks' => 'nullable|string',
        'checks' => 'nullable|array',
        'checks.*.customer_bank_account_id' => 'nullable|integer',
        'checks.*.bank_name' => 'nullable|string',
        'checks.*.account_number' => 'nullable|string',
        'checks.*.check_no' => 'nullable|string',
        'checks.*.check_date' => 'nullable|date',
        'checks.*.credit_amount' => 'nullable|numeric',
        'returns' => 'nullable|array',
        'returns.*.sales_return_id' => 'required|integer',
        'returns.*.return_number' => 'required|string',
        'returns.*.return_amount' => 'required|numeric',
        'returns.*.source_type' => 'nullable|string',
        'returns.*.source_id' => 'nullable|integer',
        'returns.*.invoice_no' => 'nullable|string',
    ]);

    try {
        foreach ($data['invoices'] as $invoice) {
            $due = max((float) ($invoice['due_amount'] ?? 0), 0);
            $paid = max((float) ($invoice['paid_amount'] ?? 0), 0);
            if ($due > 0.00001 && $paid <= 0) {
                throw new \InvalidArgumentException('Paid amount must be greater than zero when an invoice still has an amount due.');
            }
        }

        DB::connection('accounting')->beginTransaction();

        $paymentExists = DB::connection('accounting')->table('process_payments')->where('id', $paymentId)->exists();
        if (!$paymentExists) {
            throw new \Exception('Payment record not found.');
        }

        $before = $hatdogBuildProcessPaymentDetail($paymentId);
        $actor = hatdogAuditActor($user);
        $customer = \App\Models\Customer::on('masterlist')->find($data['customer_id']);
        $totalPaid = collect($data['invoices'])->sum(fn ($invoice) => (float) $invoice['paid_amount']);

        DB::connection('accounting')->table('process_payments')->where('id', $paymentId)->update([
            'payment_no' => $data['payment_no'],
            'customer_id' => $data['customer_id'],
            'customer_name' => $data['customer_name'],
            'payment_date' => $data['payment_date'],
            'total_paid' => $totalPaid,
            'status' => 'Posted',
            'updated_at' => now(),
        ]);

        // Preserve Group -> Process Payment Invoice links before recreating invoice rows.
        $oldPaymentInvoices = DB::connection('accounting')->table('process_payment_invoices')
            ->where('process_payment_id', $paymentId)
            ->get(['id', 'source_type', 'source_id', 'invoice_no']);
        $oldInvoiceIds = $oldPaymentInvoices->pluck('id')->map(fn ($id) => (int) $id)->values()->all();
        $groupLinks = empty($oldInvoiceIds)
            ? collect()
            : DB::connection('accounting')->table('payment_invoice_group_items')
                ->whereIn('process_payment_invoice_id', $oldInvoiceIds)
                ->get(['id', 'process_payment_invoice_id']);
        $oldInvoiceById = $oldPaymentInvoices->keyBy('id');
        $groupItemIdsByInvoiceKey = [];
        foreach ($groupLinks as $link) {
            $oldInvoice = $oldInvoiceById->get((int) $link->process_payment_invoice_id);
            if (!$oldInvoice) continue;
            $key = (string) $oldInvoice->source_type . ':' . (int) $oldInvoice->source_id . ':' . strtoupper(preg_replace('/\s+/', '', trim((string) $oldInvoice->invoice_no)));
            $groupItemIdsByInvoiceKey[$key][] = (int) $link->id;
        }

        // Clear every old Group -> PPI link before recreating the payment invoice rows.
        // Re-selected invoices are linked to their new PPI below; unselected invoices
        // remain null, which makes them unpaid and eligible in Process Payment again.
        if (!empty($oldInvoiceIds)) {
            DB::connection('accounting')->table('payment_invoice_group_items')
                ->whereIn('process_payment_invoice_id', $oldInvoiceIds)
                ->update(['process_payment_invoice_id' => null, 'updated_at' => now()]);
        }

        DB::connection('accounting')->table('process_payment_invoices')->where('process_payment_id', $paymentId)->delete();
        DB::connection('accounting')->table('process_payment_checks')->where('process_payment_id', $paymentId)->delete();
        // Manual Returns fields in the Payments modal are print-only and are not part of payment processing.
        // Preserve any historical process_payment_returns rows unless an explicit backend caller sends a returns payload.
        if ($request->has('returns')) {
            DB::connection('accounting')->table('process_payment_returns')->where('process_payment_id', $paymentId)->delete();
        }

        $insertedInvoiceIds = [];
        $insertedInvoiceMap = [];
        foreach ($data['invoices'] as $invoice) {
            $due = (float) $invoice['due_amount'];
            $paid = (float) $invoice['paid_amount'];

            $invId = DB::connection('accounting')->table('process_payment_invoices')->insertGetId([
                'process_payment_id' => $paymentId,
                'source_type' => $invoice['source_type'],
                'source_id' => $invoice['source_id'],
                'invoice_no' => $invoice['invoice_no'],
                'invoice_amount' => $invoice['invoice_amount'],
                'due_amount' => $due,
                'adjustment' => $invoice['adjustment'] ?? 0,
                'paid_amount' => $paid,
                'payment_status' => $paid >= $due ? 'Full' : 'Partial',
                'remarks' => $invoice['remarks'] ?? null,
                'created_at' => now(),
                'updated_at' => now(),
            ]);
            $insertedInvoiceIds[] = $invId;
            $invoiceMapKey = (string) $invoice['source_type'] . ':' . (int) $invoice['source_id'] . ':' . strtoupper(preg_replace('/\s+/', '', trim((string) $invoice['invoice_no'])));
            $insertedInvoiceMap[$invoiceMapKey] = $invId;

            foreach (($groupItemIdsByInvoiceKey[$invoiceMapKey] ?? []) as $groupItemId) {
                DB::connection('accounting')->table('payment_invoice_group_items')
                    ->where('id', $groupItemId)
                    ->update(['process_payment_invoice_id' => $invId, 'updated_at' => now()]);
            }
        }

        foreach (($data['checks'] ?? []) as $check) {
            if (empty($check['bank_name']) && empty($check['account_number']) && empty($check['check_no']) && empty($check['credit_amount'])) {
                continue;
            }

            DB::connection('accounting')->table('process_payment_checks')->insert([
                'process_payment_id' => $paymentId,
                'customer_bank_account_id' => $check['customer_bank_account_id'] ?? null,
                'bank_name' => $check['bank_name'] ?? null,
                'account_number' => $check['account_number'] ?? null,
                'check_no' => $check['check_no'] ?? null,
                'check_date' => $check['check_date'] ?? null,
                'credit_amount' => $check['credit_amount'] ?? 0,
                'created_at' => now(),
                'updated_at' => now(),
            ]);
        }

        if ($request->has('returns')) {
            foreach (($data['returns'] ?? []) as $ret) {
                $linkedInvoiceId = null;
                if (!empty($ret['source_type']) && !empty($ret['source_id'])) {
                    $returnInvoiceNo = strtoupper(preg_replace('/\s+/', '', trim((string) ($ret['invoice_no'] ?? ''))));
                    $returnMapKey = (string) $ret['source_type'] . ':' . (int) $ret['source_id'] . ':' . $returnInvoiceNo;
                    $linkedInvoiceId = $insertedInvoiceMap[$returnMapKey] ?? null;
                }
                if (!$linkedInvoiceId && !empty($ret['invoice_no'])) {
                    $normalizedReturnNo = strtoupper(preg_replace('/\s+/', '', trim((string) $ret['invoice_no'])));
                    foreach ($data['invoices'] as $invoiceIndex => $invoiceRow) {
                        $normalizedInvoiceNo = strtoupper(preg_replace('/\s+/', '', trim((string) ($invoiceRow['invoice_no'] ?? ''))));
                        if ($normalizedReturnNo !== '' && $normalizedReturnNo === $normalizedInvoiceNo) {
                            $linkedInvoiceId = $insertedInvoiceIds[$invoiceIndex] ?? null;
                            break;
                        }
                    }
                }

                DB::connection('accounting')->table('process_payment_returns')->insert([
                    'process_payment_id' => $paymentId,
                    'process_payment_invoice_id' => $linkedInvoiceId,
                    'sales_return_id' => $ret['sales_return_id'],
                    'return_number' => $ret['return_number'],
                    'return_amount' => $ret['return_amount'],
                    'created_at' => now(),
                    'updated_at' => now(),
                ]);
            }
        }

        $after = $hatdogBuildProcessPaymentDetail($paymentId);
        $recordName = trim((string) (($data['customer_name'] ?? '') !== '' ? $data['customer_name'] : ('Payment ' . $data['payment_no'])));

        hatdogWriteAuditTrail([
            'module' => 'payments',
            'action' => 'Updated',
            'source_connection' => 'accounting',
            'source_table' => 'process_payments',
            'source_id' => $paymentId,
            'display_id' => (string) $data['payment_no'],
            'record_name' => $recordName,
            'user_name' => $actor['name'],
            'user_identifier' => $actor['identifier'],
            'audit_data' => [
                'before' => $before,
                'after' => $after,
                'customer' => $customer?->toArray(),
            ],
        ]);

        DB::connection('accounting')->commit();
        return response()->json(['success' => true, 'payment_id' => $paymentId]);
    } catch (\Throwable $e) {
        DB::connection('accounting')->rollBack();
        Log::error('Payments update error: ' . $e->getMessage());
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.payments.history.update');

Route::delete('/admin/payments/history/{paymentId}', function (int $paymentId) use ($hatdogBuildProcessPaymentDetail) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

    try {
        DB::connection('accounting')->beginTransaction();

        $detail = $hatdogBuildProcessPaymentDetail($paymentId);
        $payment = $detail['payment'];
        $actor = hatdogAuditActor($user);

        $paymentInvoiceIds = DB::connection('accounting')->table('process_payment_invoices')
            ->where('process_payment_id', $paymentId)
            ->pluck('id')
            ->map(fn ($id) => (int) $id)
            ->values()
            ->all();

        // Deleting a Payment No. makes every invoice unpaid again. Group rows are
        // preserved but unlinked so they never point at removed PPI records.
        if (!empty($paymentInvoiceIds)) {
            DB::connection('accounting')->table('payment_invoice_group_items')
                ->whereIn('process_payment_invoice_id', $paymentInvoiceIds)
                ->update(['process_payment_invoice_id' => null, 'updated_at' => now()]);
        }

        DB::connection('accounting')->table('process_payment_returns')->where('process_payment_id', $paymentId)->delete();
        DB::connection('accounting')->table('process_payment_checks')->where('process_payment_id', $paymentId)->delete();
        DB::connection('accounting')->table('process_payment_invoices')->where('process_payment_id', $paymentId)->delete();
        DB::connection('accounting')->table('process_payments')->where('id', $paymentId)->delete();

        hatdogWriteAuditTrail([
            'module' => 'payments',
            'action' => 'Deleted',
            'source_connection' => 'accounting',
            'source_table' => 'process_payments',
            'source_id' => $paymentId,
            'display_id' => (string) ($payment['payment_no'] ?? $paymentId),
            'record_name' => (string) ($payment['customer_name'] ?? ('Payment ' . $paymentId)),
            'user_name' => $actor['name'],
            'user_identifier' => $actor['identifier'],
            'audit_data' => [
                'archived_data' => $detail,
            ],
        ]);

        DB::connection('accounting')->commit();
        return response()->json(['success' => true]);
    } catch (\Throwable $e) {
        DB::connection('accounting')->rollBack();
        Log::error('Payments delete error: ' . $e->getMessage());
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.payments.history.delete');

