Route::get('/admin/sales/sales-return/history', function (Request $request) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);
    try {
        $searchInv = $request->query('invoice');
        $searchCust = $request->query('customer');
        $page = (int)$request->query('page', 1);
        $perPage = 50;

        $query = DB::connection('sales')->table('sales_returns');

        if ($searchInv) {
            $query->where('invoice_no', 'LIKE', "%{$searchInv}%");
        }
        if ($searchCust) {
            $query->where('customer_name', 'LIKE', "%{$searchCust}%");
        }

        $totalCount = $query->count();
        $returns = $query->orderBy('created_at', 'desc')
            ->offset(($page - 1) * $perPage)
            ->limit($perPage)
            ->get();

        return response()->json([
            'success' => true, 
            'returns' => $returns,
            'total' => $totalCount,
            'page' => $page,
            'last_page' => ceil($totalCount / $perPage)
        ]);
    } catch (\Exception $e) {
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.sales-return.history');

// Sales Return - History Detail (Modal)
Route::get('/admin/sales/sales-return/history-detail/{id}', function ($id) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);
    try {
        $header = DB::connection('sales')->table('sales_returns')->where('id', $id)->first();
        if (!$header) throw new \Exception('Return not found');

        // Try to get address from masterlist.customers
        $address = '---';
        if ($header->customer_id) {
            $customer = DB::connection('masterlist')->table('customers')->where('id', $header->customer_id)->first();
            if ($customer) {
                $address = $customer->address ?? '---';
            }
        }
        $header->address = $address;

        $items = DB::connection('sales')->table('sales_return_items')->where('sales_return_id', $id)->get();

        // Fetch additional product details (application, position) from masterlist
        $productIds = $items->pluck('product_id')->unique();
        $products = DB::connection('masterlist')->table('products')
            ->whereIn('id', $productIds)
            ->select('id', 'application', 'position', 'unit')
            ->get()
            ->keyBy('id');

        foreach ($items as $item) {
            $prod = $products->get($item->product_id);
            $item->application = $prod->application ?? '---';
            $item->position = $prod->position ?? '---';
            $item->oum = $prod->unit ?? '';
        }

        return response()->json([
            'success' => true,
            'header' => $header,
            'items' => $items
        ]);
    } catch (\Exception $e) {
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.sales-return.history-detail');

// Sales Return - Dashboard Stats
Route::get('/admin/sales/sales-return/dashboard', function () {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);
    try {
        $nowManila = \Carbon\Carbon::now('Asia/Manila');
        $currentYear = (int) $nowManila->year;
        $currentMonth = (int) $nowManila->month;

        // Cache the Online invoice lookup because online_reports can contain a large migrated history.
        // This keeps the dashboard lightweight while still classifying both generated and migrated Online invoices.
        $onlineInvoiceKeys = Cache::remember('sales_return:dashboard_online_invoice_keys:v2', now()->addMinutes(10), function () {
            $keys = [];
            $normalize = static fn ($value) => mb_strtoupper(preg_replace('/\s+/', '', trim((string) $value)));

            DB::connection('sales')->table('sales_orders')
                ->where('order_number', 'LIKE', 'ONL-%')
                ->whereNotNull('invoice_numbers')
                ->where('invoice_numbers', '<>', '')
                ->pluck('invoice_numbers')
                ->each(function ($invoiceNo) use (&$keys, $normalize) {
                    $key = $normalize($invoiceNo);
                    if ($key !== '') $keys[$key] = true;
                });

            DB::connection('sales')->table('online_reports')
                ->whereNotNull('invoice_numbers')
                ->pluck('invoice_numbers')
                ->each(function ($raw) use (&$keys, $normalize) {
                    $invoiceNumbers = json_decode((string) $raw, true);
                    if (!is_array($invoiceNumbers)) return;
                    foreach ($invoiceNumbers as $invoiceNo) {
                        $key = $normalize($invoiceNo);
                        if ($key !== '') $keys[$key] = true;
                    }
                });

            return $keys;
        });

        $returnRows = Cache::remember('sales_return:dashboard_return_rows:v2', now()->addSeconds(20), function () {
            return DB::connection('sales')->table('sales_returns')
                ->select('invoice_no', 'created_at')
                ->get()
                ->map(fn ($row) => [
                    'invoice_no' => (string) ($row->invoice_no ?? ''),
                    'created_at' => $row->created_at,
                ])
                ->all();
        });

        $stats = [
            'total' => 0, 'total_year' => 0, 'total_month' => 0,
            'online' => 0, 'online_year' => 0, 'online_month' => 0,
            'local' => 0, 'local_year' => 0, 'local_month' => 0,
        ];
        $normalize = static fn ($value) => mb_strtoupper(preg_replace('/\s+/', '', trim((string) $value)));

        foreach ($returnRows as $row) {
            $stats['total']++;
            $key = $normalize($row['invoice_no'] ?? '');
            $isOnline = $key !== '' && isset($onlineInvoiceKeys[$key]);
            $type = $isOnline ? 'online' : 'local';
            $stats[$type]++;

            if (!empty($row['created_at'])) {
                try {
                    $created = \Carbon\Carbon::parse($row['created_at'], 'UTC')->timezone('Asia/Manila');
                    if ((int) $created->year === $currentYear) {
                        $stats['total_year']++;
                        $stats[$type . '_year']++;
                        if ((int) $created->month === $currentMonth) {
                            $stats['total_month']++;
                            $stats[$type . '_month']++;
                        }
                    }
                } catch (\Throwable $e) {
                    // Ignore malformed legacy timestamps in dashboard grouping only.
                }
            }
        }

        $totalSalesOrders = Cache::remember(
            'sales_return:dashboard_sales_order_count:v2',
            now()->addMinutes(2),
            fn () => DB::connection('sales')->table('sales_orders')->count()
        );
        $returnAverage = $totalSalesOrders > 0 ? ($stats['total'] / $totalSalesOrders) * 100 : 0;

        return response()->json([
            'success' => true,
            'total_returns' => number_format($stats['total']),
            'total_year' => number_format($stats['total_year']),
            'total_month' => number_format($stats['total_month']),
            'online_returns' => number_format($stats['online']),
            'online_year' => number_format($stats['online_year']),
            'online_month' => number_format($stats['online_month']),
            'local_returns' => number_format($stats['local']),
            'local_year' => number_format($stats['local_year']),
            'local_month' => number_format($stats['local_month']),
            'return_average' => number_format($returnAverage, 1) . '%',
        ]);
    } catch (\Exception $e) {
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.sales-return.dashboard');

// Sales Return - Finalize
Route::post('/admin/sales/sales-return/finalize', function (Request $request) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

    try {
        $returns = $request->input('returns', []);
        if (empty($returns)) {
            return response()->json(['success' => false, 'message' => 'No items to return.'], 422);
        }

        $actor = hatdogAuditActor($user);
        $affectedProductIds = [];

        \Illuminate\Support\Facades\Log::info('Sales Return Finalizing Processing:', ['count' => count($returns)]);

        DB::connection('sales')->beginTransaction();
        DB::connection('ledger')->beginTransaction();

        // Generate the next return number once, then increment in memory for batch finalization.
        $maxNum = DB::connection('sales')->table('sales_returns')->max(DB::raw("CAST(SUBSTRING(return_number, 4) AS UNSIGNED)"));
        $nextNum = ($maxNum ?: 0) + 1;

        foreach ($returns as $ret) {
            $returnNo = 'SR-' . str_pad($nextNum, 7, '0', STR_PAD_LEFT);
            $nextNum++;

            $generalRemarks = isset($ret['remarks']) ? (string) $ret['remarks'] : '';
            $addlDiscPercent = (float) ($ret['additional_discount'] ?? 0);
            $subtotalValue = (float) ($ret['subtotal'] ?? 0);
            $totalAmountValue = (float) ($ret['total_amount'] ?? 0);
            $addlDiscAmount = $subtotalValue - $totalAmountValue;

            $returnId = DB::connection('sales')->table('sales_returns')->insertGetId([
                'return_number' => $returnNo,
                'invoice_no' => $ret['invoice_no'],
                'customer_id' => $ret['customer_id'],
                'customer_name' => $ret['customer_name'],
                'total_items' => $ret['total_items'],
                'total_amount' => $totalAmountValue,
                'subtotal' => $subtotalValue,
                'additional_discount_percent' => $addlDiscPercent,
                'additional_discount_amount' => max(0, $addlDiscAmount),
                'status' => 'Completed',
                'remarks' => $generalRemarks,
                'created_at' => now(),
                'updated_at' => now(),
            ]);

            foreach (($ret['items'] ?? []) as $item) {
                $itemRemarks = isset($item['remarks']) ? (string) $item['remarks'] : '';
                $returnQty = max(0, (int) ($item['qty'] ?? 0));
                $goodItemsQty = max(0, (int) ($item['good_items'] ?? 0));
                $goodItemsQty = min($goodItemsQty, $returnQty);
                $itemDisc = (float) ($item['discount'] ?? 0);
                $itemGrossSubtotal = (float) ($item['gross_subtotal'] ?? 0);

                DB::connection('sales')->table('sales_return_items')->insert([
                    'sales_return_id' => $returnId,
                    'product_id' => $item['product_id'],
                    'product_code' => $item['product_code'],
                    'part_number' => $item['part_number'] ?? '',
                    'description' => $item['description'],
                    'application' => $item['application'] ?? '',
                    'quantity' => $returnQty,
                    'good_qty' => $goodItemsQty,
                    'discount' => $itemDisc,
                    'unit_price' => $item['unit_price'],
                    'subtotal' => $itemGrossSubtotal,
                    'return_amount' => $item['amount'],
                    'remarks' => $itemRemarks,
                    'created_at' => now(),
                    'updated_at' => now(),
                ]);
            }

            // GOOD items are written as IN. The remaining Return QTY is written
            // as a separate JUNK row that never changes balance_stock.
            $returnAffectedProductIds = app(\App\Services\SalesReturnProductLedgerService::class)
                ->replaceForReturn((int) $returnId);

            foreach ($returnAffectedProductIds as $productId) {
                $affectedProductIds[(int) $productId] = true;
            }

            $salesReturn = DB::connection('sales')->table('sales_returns')->where('id', $returnId)->first();
            $salesReturnItems = DB::connection('sales')->table('sales_return_items')
                ->where('sales_return_id', $returnId)
                ->get()
                ->map(fn ($item) => (array) $item)
                ->values()
                ->all();

            $customer = null;
            if (!empty($ret['customer_id'])) {
                $customer = \App\Models\Customer::on('masterlist')->find($ret['customer_id']);
            }

            $recordName = trim((string) (($ret['customer_name'] ?? '') !== '' ? $ret['customer_name'] : ('Sales Return ' . $returnNo)));

            hatdogWriteAuditTrail([
                'module' => 'sales_return',
                'action' => 'Processed',
                'source_connection' => 'sales',
                'source_table' => 'sales_returns',
                'source_id' => $returnId,
                'display_id' => $returnNo,
                'record_name' => $recordName,
                'user_name' => $actor['name'],
                'user_identifier' => $actor['identifier'],
                'audit_data' => [
                    'sales_return' => $salesReturn ? (array) $salesReturn : null,
                    'customer' => $customer?->toArray(),
                    'items' => $salesReturnItems,
                    'request_payload' => $ret,
                ],
            ]);
        }

        DB::connection('ledger')->commit();
        DB::connection('sales')->commit();

        // Sync products.on_hand only after the ledger transaction is committed.
        $finalizedProductIds = array_values(array_map('intval', array_keys($affectedProductIds)));
        if (!empty($finalizedProductIds)) {
            try {
                \App\Services\ProductStockSyncService::syncProducts($finalizedProductIds);
            } catch (\Throwable $syncError) {
                Log::error('Sales Return post-commit stock sync failed.', [
                    'product_ids' => $finalizedProductIds,
                    'error' => $syncError->getMessage(),
                ]);
            }

            if (config('services.shopee.auto_stock_sync', false)) {
                foreach ($finalizedProductIds as $productId) {
                    try {
                        \App\Jobs\SyncShopeeProductInventory::dispatch($productId)
                            ->onQueue('shopee-stock');
                    } catch (\Throwable $queueError) {
                        Log::error('Sales Return Shopee stock queue failed.', [
                            'product_id' => $productId,
                            'error' => $queueError->getMessage(),
                        ]);
                    }
                }
            }
        }

        Cache::forget('sales_return:dashboard_return_rows:v2');

        return response()->json(['success' => true]);
    } catch (\Exception $e) {
        if (DB::connection('ledger')->transactionLevel() > 0) DB::connection('ledger')->rollBack();
        if (DB::connection('sales')->transactionLevel() > 0) DB::connection('sales')->rollBack();

        \Illuminate\Support\Facades\Log::error('Sales Return Finalize Error: ' . $e->getMessage());

        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.sales-return.finalize');

// Sales Return - Edit Data (fetch existing return + original invoice items)
Route::get('/admin/sales/sales-return/edit-data/{id}', function ($id) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);
    try {
        $header = DB::connection('sales')->table('sales_returns')->where('id', $id)->first();
        if (!$header) throw new \Exception('Return not found');

        $existingItems = DB::connection('sales')->table('sales_return_items')
            ->where('sales_return_id', $id)
            ->get();

        $invoiceItems = collect();
        if ($header->invoice_no) {
            $salesOrder = DB::connection('sales')->table('sales_orders')
                ->where('invoice_numbers', $header->invoice_no)
                ->first();

            if ($salesOrder) {
                $rawItems = DB::connection('sales')->table('sales_order_items')
                    ->where('sales_order_id', $salesOrder->id)
                    ->get();

                $productIds = $rawItems->pluck('product_id')
                    ->map(fn ($value) => (int) $value)
                    ->filter(fn ($value) => $value > 0)
                    ->unique()
                    ->values();

                $products = $productIds->isEmpty()
                    ? collect()
                    : DB::connection('masterlist')->table('products')
                        ->whereIn('id', $productIds->all())
                        ->select('id', 'product_code', 'part_number', 'application')
                        ->get()
                        ->keyBy('id');

                $invoiceItems = $rawItems->map(function ($item) use ($products) {
                    $product = $products->get((int) $item->product_id);
                    return [
                        'product_id' => $item->product_id,
                        'product_code' => $item->product_code ?: ($product->product_code ?? ''),
                        'part_number' => $product->part_number ?? '',
                        'description' => $item->description,
                        'application' => $product->application ?? '',
                        'oum' => $item->oum ?? '',
                        'unit_price' => $item->unit_price ?? 0,
                        'quantity' => $item->quantity ?? 0,
                        'subtotal' => $item->subtotal ?? 0,
                        'discount' => $item->discount ?? 0,
                        'additional_discount' => $item->additional_discount ?? 0,
                    ];
                })->values();
            }
        }

        return response()->json([
            'success' => true,
            'header' => $header,
            'invoice_items' => $invoiceItems,
            'existing_items' => $existingItems
        ]);
    } catch (\Exception $e) {
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.sales-return.edit-data');

// Sales Return - Update
Route::post('/admin/sales/sales-return/update/{id}', function (Request $request, $id) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

    try {
        $header = DB::connection('sales')->table('sales_returns')->where('id', $id)->first();
        if (!$header) throw new \Exception('Return not found');

        $items = $request->input('items', []);
        $generalRemarks = $request->input('remarks', '');
        $returnNo = $header->return_number;
        $actor = hatdogAuditActor($user);

        DB::connection('sales')->beginTransaction();
        DB::connection('ledger')->beginTransaction();

        $newTotalItems = 0;
        $newSubtotal = 0;

        $productIds = collect($items)
            ->pluck('product_id')
            ->map(fn ($value) => (int) $value)
            ->filter(fn ($value) => $value > 0)
            ->unique()
            ->values();

        $existingItemsByProduct = DB::connection('sales')->table('sales_return_items')
            ->where('sales_return_id', $id)
            ->get()
            ->keyBy(fn ($item) => (int) $item->product_id);

        $productsById = $productIds->isEmpty()
            ? collect()
            : \App\Models\Product::on('masterlist')
                ->whereIn('id', $productIds->all())
                ->get()
                ->keyBy('id');

        foreach ($items as $item) {
            $productId = (int) ($item['product_id'] ?? 0);
            if ($productId <= 0) continue;

            $qty = max(0, (int) ($item['qty'] ?? 0));
            $goodItems = max(0, (int) ($item['good_items'] ?? 0));
            $goodItems = min($goodItems, $qty);
            $unitPrice = (float) ($item['unit_price'] ?? 0);
            $itemDisc = (float) ($item['discount'] ?? 0);
            $itemRemarks = (string) ($item['remarks'] ?? '');
            $product = $productsById->get($productId);
            $existingItem = $existingItemsByProduct->get($productId);

            $grossSubtotal = $qty * $unitPrice;
            $afterItemDisc = $grossSubtotal * (1 - $itemDisc / 100);
            $amount = $afterItemDisc;

            if ($existingItem) {
                DB::connection('sales')->table('sales_return_items')
                    ->where('id', $existingItem->id)
                    ->update([
                        'quantity' => $qty,
                        'good_qty' => $goodItems,
                        'discount' => $itemDisc,
                        'subtotal' => $grossSubtotal,
                        'return_amount' => $amount,
                        'remarks' => $itemRemarks,
                        'updated_at' => now(),
                    ]);
            } else {
                if ($qty <= 0 && $goodItems <= 0) {
                    continue;
                }

                DB::connection('sales')->table('sales_return_items')->insert([
                    'sales_return_id' => $id,
                    'product_id' => $productId,
                    'product_code' => $item['product_code'] ?? ($product->product_code ?? ''),
                    'part_number' => $item['part_number'] ?? '',
                    'description' => $item['description'] ?? '',
                    'application' => $item['application'] ?? '',
                    'quantity' => $qty,
                    'good_qty' => $goodItems,
                    'discount' => $itemDisc,
                    'unit_price' => $unitPrice,
                    'subtotal' => $grossSubtotal,
                    'return_amount' => $amount,
                    'remarks' => $itemRemarks,
                    'created_at' => now(),
                    'updated_at' => now(),
                ]);
            }

            $newTotalItems += $qty;
            $newSubtotal += $afterItemDisc;
        }

        $headerAddlDiscPct = (float) ($header->additional_discount_percent ?? 0);
        $addlDiscAmt = $newSubtotal * $headerAddlDiscPct / 100;
        $newTotalAfterAddlDisc = $newSubtotal - $addlDiscAmt;

        DB::connection('sales')->table('sales_returns')
            ->where('id', $id)
            ->update([
                'total_items' => $newTotalItems,
                'total_amount' => $newTotalAfterAddlDisc,
                'subtotal' => $newSubtotal,
                'additional_discount_amount' => $addlDiscAmt,
                'remarks' => $generalRemarks,
                'updated_at' => now(),
            ]);

        // Rebuild both Sales Return ledger rows:
        // GOOD -> IN and the remainder -> JUNK with zero stock effect.
        // The service reverses the old IN effect first, then propagates only
        // the new IN difference through every later balance_stock.
        $affectedProductIds = app(\App\Services\SalesReturnProductLedgerService::class)
            ->replaceForReturn((int) $id);

        DB::connection('ledger')->commit();
        DB::connection('sales')->commit();

        if (!empty($affectedProductIds)) {
            try {
                \App\Services\ProductStockSyncService::syncProducts($affectedProductIds);
            } catch (\Throwable $syncError) {
                Log::error('Sales Return update post-commit stock sync failed.', [
                    'product_ids' => $affectedProductIds,
                    'error' => $syncError->getMessage(),
                ]);
            }
        }

        Cache::forget('sales_return:dashboard_return_rows:v2');

        $updatedReturn = DB::connection('sales')->table('sales_returns')->where('id', $id)->first();
        $updatedItems = DB::connection('sales')->table('sales_return_items')
            ->where('sales_return_id', $id)
            ->get()
            ->map(fn ($i) => (array) $i)
            ->values()
            ->all();

        $customer = $header->customer_id
            ? \App\Models\Customer::on('masterlist')->find($header->customer_id)
            : null;

        hatdogWriteAuditTrail([
            'module' => 'sales_return',
            'action' => 'Edited',
            'source_connection' => 'sales',
            'source_table' => 'sales_returns',
            'source_id' => $id,
            'display_id' => $returnNo,
            'record_name' => $header->customer_name ?: 'Sales Return ' . $returnNo,
            'user_name' => $actor['name'],
            'user_identifier' => $actor['identifier'],
            'audit_data' => [
                'sales_return' => $updatedReturn ? (array) $updatedReturn : null,
                'customer' => $customer?->toArray(),
                'items' => $updatedItems,
            ],
        ]);

        return response()->json(['success' => true]);
    } catch (\Exception $e) {
        if (DB::connection('ledger')->transactionLevel() > 0) DB::connection('ledger')->rollBack();
        if (DB::connection('sales')->transactionLevel() > 0) DB::connection('sales')->rollBack();

        \Illuminate\Support\Facades\Log::error('Sales Return Update Error: ' . $e->getMessage());

        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.sales-return.update');// Sales Return - Delete
Route::post('/admin/sales/sales-return/delete/{id}', function (Request $request, $id) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

    try {
        $header = DB::connection('sales')->table('sales_returns')->where('id', $id)->first();
        if (!$header) throw new \Exception('Return not found');

        $returnNo = $header->return_number;
        $actor = hatdogAuditActor($user);

        DB::connection('sales')->beginTransaction();
        DB::connection('ledger')->beginTransaction();

        $items = DB::connection('sales')->table('sales_return_items')
            ->where('sales_return_id', $id)
            ->get();

        // Remove both GOOD/IN and JUNK rows. Only the old IN quantity is
        // reversed through later balance_stock values; JUNK has zero effect.
        $affectedProductIds = app(\App\Services\SalesReturnProductLedgerService::class)
            ->deleteForReturn((int) $id);

        DB::connection('sales')->table('sales_return_items')
            ->where('sales_return_id', $id)
            ->delete();

        DB::connection('sales')->table('sales_returns')
            ->where('id', $id)
            ->delete();

        DB::connection('ledger')->commit();
        DB::connection('sales')->commit();

        if (!empty($affectedProductIds)) {
            try {
                \App\Services\ProductStockSyncService::syncProducts($affectedProductIds);
            } catch (\Throwable $syncError) {
                Log::error('Sales Return delete post-commit stock sync failed.', [
                    'product_ids' => $affectedProductIds,
                    'error' => $syncError->getMessage(),
                ]);
            }
        }

        Cache::forget('sales_return:dashboard_return_rows:v2');

        hatdogWriteAuditTrail([
            'module' => 'sales_return',
            'action' => 'Deleted',
            'source_connection' => 'sales',
            'source_table' => 'sales_returns',
            'source_id' => $id,
            'display_id' => $returnNo,
            'record_name' => trim((string) ($header->customer_name ?? ('Sales Return ' . $returnNo))),
            'user_name' => $actor['name'],
            'user_identifier' => $actor['identifier'],
            'audit_data' => [
                'sales_return' => (array) $header,
                'items' => $items->map(fn ($i) => (array) $i)->values()->all(),
            ],
        ]);

        return response()->json(['success' => true, 'message' => 'Sales return deleted successfully']);
    } catch (\Exception $e) {
        if (DB::connection('ledger')->transactionLevel() > 0) DB::connection('ledger')->rollBack();
        if (DB::connection('sales')->transactionLevel() > 0) DB::connection('sales')->rollBack();

        \Illuminate\Support\Facades\Log::error('Sales Return Delete Error: ' . $e->getMessage());

        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.sales-return.delete');

