// Consignment Invoice - Proceed
Route::post('/admin/sales/consignment-invoice/proceed', function (Request $request) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);
    try {
        $noteId = $request->input('sales_note_id');
        $note = \App\Models\SalesNote::on('sales')->find($noteId);
        if (!$note) return response()->json(['success' => false, 'message' => 'Sales note not found.'], 404);
        $noteBefore = $note->toArray();
        $actor = hatdogAuditActor($user);
        $customer = null;
        if (!empty($note->customer_id)) {
            $customer = \App\Models\Customer::on('masterlist')->find($note->customer_id);
        }

        $invoices = $request->input('invoices', []);
        $items = $request->input('items', []);

        try {
            DB::connection('sales')->beginTransaction();
            DB::connection('ledger')->beginTransaction();

            $maxNum = \App\Models\ConsignmentInvoice::on('sales')->max(\DB::raw("CAST(SUBSTRING(invoice_number, 4) AS UNSIGNED)"));
            $nextNum = ($maxNum ?: 0) + 1;
            $invoiceNumber = 'CI-' . str_pad($nextNum, 7, '0', STR_PAD_LEFT);

            $totalAmount = 0;
            $processedItems = [];
            $productsToSync = [];
            foreach ($items as $itemData) {
                if (!($itemData['actual_qty'] ?? 0)) continue;
                $product = \App\Models\Product::on('masterlist')->find($itemData['product_id'] ?? 0);
                $itemSubtotal = ($itemData['actual_qty'] ?? 0) * ($itemData['unit_price'] ?? 0) * (1 - ($itemData['discount'] ?? 0) / 100);
                $totalAmount += $itemSubtotal;
                $processedItems[] = [
                    'product_id' => $product ? $product->id : null,
                    'product_code' => $itemData['product_code'] ?? '',
                    'description' => $itemData['description'] ?? '',
                    'quantity' => $itemData['quantity'] ?? 0,
                    'additional_qty' => $itemData['additional_qty'] ?? 0,
                    'oum' => $itemData['oum'] ?? 'PCS',
                    'unit_price' => $itemData['unit_price'] ?? 0,
                    'discount' => $itemData['discount'] ?? 0,
                    'additional_discount' => $itemData['additional_discount'] ?? 0,
                    'subtotal' => $itemSubtotal,
                    'particulars' => $itemData['particulars'] ?? '',
                ];

                if ($product) {
                    $result = SalesOrderLedgerService::recordOutMovement([
                        'product_id' => $product->id,
                        'customer_id' => $note->customer_id,
                        'customer_name' => $note->customer_name,
                        'transaction_number' => $note->sales_number,
                        'reference_number' => $invoiceNumber,
                        'source_type' => 'consignment_invoice',
                        'source_id' => 0,
                        'source_item_id' => 0,
                        'previous_actual_qty' => 0,
                        'new_actual_qty' => (float) ($itemData['actual_qty'] ?? 0),
                        'oum' => $itemData['oum'] ?? 'PCS',
                        'unit_price' => $itemData['unit_price'] ?? 0,
                        'cost' => $product->cost ?? 0,
                        'remarks_prefix' => 'Consignment Invoice Processing',
                    ]);
                    if ($result['created']) {
                        $productsToSync[] = $product->id;
                    }
                }
            }

            $consignmentInvoice = \App\Models\ConsignmentInvoice::create([
                'sales_note_id' => $note->id,
                'invoice_number' => $invoiceNumber,
                'customer_id' => $note->customer_id,
                'customer_name' => $note->customer_name,
                'total_amount' => $totalAmount,
                'status' => 'Active',
                'remarks' => implode(', ', $invoices),
            ]);

            foreach ($processedItems as $itemData) {
                $itemData['consignment_invoice_id'] = $consignmentInvoice->id;
                \App\Models\ConsignmentInvoiceItem::create($itemData);
            }

            $note->status = 'Partial';
            $note->save();

            DB::connection('sales')->commit();
            DB::connection('ledger')->commit();

            // Sync products.on_hand after ledger commit
            foreach (array_unique($productsToSync) as $syncPid) {
                try {
                    ProductStockSyncService::syncProduct($syncPid);
                } catch (\Exception $syncEx) {
                    \Illuminate\Support\Facades\Log::warning(
                        '[CONSIGNMENT LEDGER] ProductStockSync failed for product ' . $syncPid . ': ' . $syncEx->getMessage()
                    );
                }
            }

            $consignmentInvoice->load('items');
            $recordName = trim((string) (($note->customer_name ?? '') !== '' ? $note->customer_name : ('Consignment Invoice ' . $invoiceNumber)));

            hatdogWriteAuditTrail([
                'module' => 'consignment_invoice',
                'action' => 'Processed',
                'source_connection' => 'sales',
                'source_table' => 'consignment_invoices',
                'source_id' => $consignmentInvoice->id,
                'display_id' => $invoiceNumber,
                'record_name' => $recordName,
                'user_name' => $actor['name'],
                'user_identifier' => $actor['identifier'],
                'audit_data' => [
                    'consignment_invoice' => $consignmentInvoice->toArray(),
                    'items' => $consignmentInvoice->items->map(fn ($item) => $item->toArray())->values()->all(),
                    'sales_note_before' => $noteBefore,
                    'sales_note_after' => $note->fresh()->toArray(),
                    'customer' => $customer?->toArray(),
                    'invoice_remarks' => $invoices,
                    'request_items' => collect($items)->values()->all(),
                ],
            ]);

            return response()->json(['success' => true, 'invoice_number' => $invoiceNumber]);
        } catch (\Exception $dbEx) {
            DB::connection('sales')->rollBack();
            DB::connection('ledger')->rollBack();
            throw $dbEx;
        }
    } catch (\Exception $e) {
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.consignment-invoice.proceed');

