// Create new product
Route::post('/admin/masterlist/product/create', function (Request $request) {
    $user = session('user');
    if (!$user) {
        return response()->json(['error' => 'Unauthorized'], 403);
    }

    if (is_array($user)) {
        $user = (object) $user;
    }

    try {
        $validated = $request->validate([
            'product_code' => 'required|unique:masterlist.products,product_code',
            'pricelist_code' => 'nullable|string|max:255',
            'part_number' => 'required|string',
            'category' => 'required|string',
            'specification' => 'nullable|string',
            'description' => 'nullable|string',
            'unit' => 'nullable|string|max:50',
            'application' => 'nullable|string',
            'position' => 'nullable|string',
            'on_hand' => 'required|integer|min:0',
            'Re_order_level' => 'nullable|integer|min:0',
            'status' => 'required|string',
            'selling_price' => 'required|numeric|min:0',
            'price_online' => 'nullable|numeric|min:0',
            'cost' => 'nullable|numeric|min:0',
            'date_added' => 'required|date',
            'Product_Picture' => 'nullable|string',
            'price_codes' => 'nullable|string',
        ]);

        $validated['pricelist_code'] = isset($validated['pricelist_code']) && trim((string) $validated['pricelist_code']) !== ''
            ? trim((string) $validated['pricelist_code'])
            : null;


        // Ensure nullable fields are not actual null if DB column is NOT NULL
        $validated['description'] = $validated['description'] ?? '';
        $validated['application'] = $validated['application'] ?? '';
        $validated['position'] = $validated['position'] ?? '';
        $validated['specification'] = isset($validated['specification']) && trim((string) $validated['specification']) !== ''
            ? trim((string) $validated['specification'])
            : null;
        $validated['cost'] = $validated['cost'] ?? 0;
        $validated['price_online'] = $validated['price_online'] ?? 0;

        // Handle price codes
        $rawPriceCodes = $request->input('price_codes');
        $priceCodesData = [];
        if ($rawPriceCodes && is_string($rawPriceCodes)) {
            $decoded = json_decode($rawPriceCodes, true);
            if (is_array($decoded)) {
                $seen = [];
                foreach ($decoded as $i => $entry) {
                    // Backward-compatible: handle both string (old) and {price_code, selling_price} (new)
                    if (is_string($entry)) {
                        $code = trim($entry);
                        $sellingPrice = 0.00;
                    } elseif (is_array($entry)) {
                        $code = trim((string) ($entry['price_code'] ?? ''));
                        $sellingPrice = (float) ($entry['selling_price'] ?? 0);
                    } else {
                        continue;
                    }
                    if ($code === '') continue;
                    $upper = strtoupper($code);
                    if (isset($seen[$upper])) continue;
                    $seen[$upper] = true;
                    $priceCodesData[] = ['price_code' => $code, 'selling_price' => $sellingPrice, 'sort_order' => $i];
                }
            }
        }

        $product = \App\Models\Product::create($validated);

        // Save price codes
        if (!empty($priceCodesData)) {
            $product->priceCodes()->createMany($priceCodesData);
        }
        $product->load('priceCodes');

        $actor = hatdogAuditActor($user);
        $recordName = trim((string) ($product->description ?: ($product->part_number ?: $product->product_code)));

        hatdogWriteAuditTrail([
            'module' => 'product',
            'action' => 'Created',
            'source_connection' => 'masterlist',
            'source_table' => 'products',
            'source_id' => $product->id,
            'display_id' => (string) ($product->product_code ?? $product->id),
            'record_name' => $recordName,
            'user_name' => $actor['name'],
            'user_identifier' => $actor['identifier'],
            'audit_data' => [
                'after' => $product->toArray(),
            ],
        ]);

        return response()->json([
            'success' => true,
            'message' => 'Product added successfully',
            'product' => $product
        ]);
    } catch (\Exception $e) {
        return response()->json([
            'success' => false,
            'message' => $e->getMessage()
        ], 422);
    }
})->name('admin.prod-master.create');

// Update existing product
Route::post('/admin/masterlist/product/update/{id}', function (Request $request, $id) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

    try {
        $product = \App\Models\Product::findOrFail($id);
        $before = $product->toArray();

        $validated = $request->validate([
            'product_code' => 'required|unique:masterlist.products,product_code,' . $id,
            'pricelist_code' => 'nullable|string|max:255',
            'part_number' => 'required|string',
            'category' => 'required|string',
            'specification' => 'nullable|string',
            'description' => 'nullable|string',
            'unit' => 'nullable|string|max:50',
            'application' => 'nullable|string',
            'position' => 'nullable|string',
            'on_hand' => 'required|integer|min:0',
            'Re_order_level' => 'nullable|integer|min:0',
            'status' => 'required|string',
            'selling_price' => 'required|numeric|min:0',
            'price_online' => 'nullable|numeric|min:0',
            'cost' => 'nullable|numeric|min:0',
            'date_added' => 'required|date',
            'Product_Picture' => 'nullable|string', // JSON string of images
            'price_codes' => 'nullable|string',
        ]);

        $validated['pricelist_code'] = isset($validated['pricelist_code']) && trim((string) $validated['pricelist_code']) !== ''
            ? trim((string) $validated['pricelist_code'])
            : null;


        // Ensure nullable fields are not actual null if DB column is NOT NULL
        $validated['description'] = $validated['description'] ?? '';
        $validated['application'] = $validated['application'] ?? '';
        $validated['position'] = $validated['position'] ?? '';
        $validated['specification'] = isset($validated['specification']) && trim((string) $validated['specification']) !== ''
            ? trim((string) $validated['specification'])
            : null;
        // Product Master inline editor must never directly alter inventory or cost.
        $validated['on_hand'] = (int) ($product->on_hand ?? 0);
        $validated['cost'] = (float) ($product->cost ?? 0);
        $validated['price_online'] = $validated['price_online'] ?? 0;

        // Sync price codes (guarded: only if submitted)
        if ($request->has('price_codes')) {
            $rawPriceCodes = $request->input('price_codes');
            $priceCodesData = [];
            if ($rawPriceCodes && is_string($rawPriceCodes)) {
                $decoded = json_decode($rawPriceCodes, true);
                if (is_array($decoded)) {
                    $seen = [];
                    foreach ($decoded as $i => $entry) {
                        // Backward-compatible: handle both string (old) and {price_code, selling_price} (new)
                        if (is_string($entry)) {
                            $code = trim($entry);
                            $sellingPrice = 0.00;
                        } elseif (is_array($entry)) {
                            $code = trim((string) ($entry['price_code'] ?? ''));
                            $sellingPrice = (float) ($entry['selling_price'] ?? 0);
                        } else {
                            continue;
                        }
                        if ($code === '') continue;
                        $upper = strtoupper($code);
                        if (isset($seen[$upper])) continue;
                        $seen[$upper] = true;
                        $priceCodesData[] = ['price_code' => $code, 'selling_price' => $sellingPrice, 'sort_order' => $i];
                    }
                }
            }
            $product->priceCodes()->delete();
            if (!empty($priceCodesData)) {
                $product->priceCodes()->createMany($priceCodesData);
            }
            $product->load('priceCodes');
        }

        $product->update($validated);
        $product->refresh();
        $oldOnlinePrice = round((float) ($before['price_online'] ?? 0), 2);
        $newOnlinePrice = round((float) ($product->price_online ?? 0), 2);
        $priceSyncResult = null;
        if ($oldOnlinePrice !== $newOnlinePrice) {
            try {
                $priceSyncResult = app(\App\Services\ShopeePriceSyncService::class)
                    ->pushSystemPriceToShopee($product, 'product_master_user_update');
            } catch (\Throwable $syncError) {
                Log::error('Product Master SYSTEM -> SHOPEE price sync failed unexpectedly', [
                    'product_id' => $product->id,
                    'old_price_online' => $oldOnlinePrice,
                    'new_price_online' => $newOnlinePrice,
                    'error' => $syncError->getMessage(),
                ]);
                $priceSyncResult = [
                    'success' => false,
                    'sync_status' => 'failed',
                    'message' => 'Product saved, but Shopee price sync failed unexpectedly.',
                    'error' => $syncError->getMessage(),
                ];
            }
        }
        $actor = hatdogAuditActor($user);
        $recordName = trim((string) ($product->description ?: ($product->part_number ?: $product->product_code)));

        hatdogWriteAuditTrail([
            'module' => 'product',
            'action' => 'Updated',
            'source_connection' => 'masterlist',
            'source_table' => 'products',
            'source_id' => $product->id,
            'display_id' => (string) ($product->product_code ?? $product->id),
            'record_name' => $recordName,
            'user_name' => $actor['name'],
            'user_identifier' => $actor['identifier'],
            'audit_data' => [
                'before' => $before,
                'after' => $product->toArray(),
            ],
        ]);

        return response()->json([
            'success' => true,
            'message' => 'Product updated successfully',
            'product' => $product,
            'sync_status' => $priceSyncResult['sync_status'] ?? ($oldOnlinePrice === $newOnlinePrice ? 'not_changed' : null),
            'sync_message' => $priceSyncResult['message'] ?? ($oldOnlinePrice === $newOnlinePrice ? 'Online price was not changed; Shopee sync was not needed.' : null),
            'sync_error' => $priceSyncResult['error'] ?? (($priceSyncResult['summary']['errors'][0] ?? null) ?: null),
            'sync_result' => $priceSyncResult,
        ]);
    } catch (\Exception $e) {
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.prod-master.update');

// Product Master - save pricing-code setup from the inline View editor (Admin + proxied Regular/Special).
Route::post('/admin/masterlist/product/price-codes/{id}', function (Request $request, $id) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);
    if (is_array($user)) $user = (object) $user;
    if (!in_array((int) ($user->account_type ?? 0), [1, 2, 3], true)) {
        return response()->json(['error' => 'Forbidden'], 403);
    }

    try {
        $data = $request->validate([
            'price_codes' => 'present|array|max:100',
            'price_codes.*.price_code' => 'required|string|max:100',
            'price_codes.*.selling_price' => 'required|numeric|min:0',
        ]);

        DB::connection('masterlist')->beginTransaction();
        $product = \App\Models\Product::query()->lockForUpdate()->findOrFail($id);
        $before = $product->priceCodes()->get(['price_code', 'selling_price', 'sort_order'])->toArray();

        $seen = [];
        $rows = [];
        foreach (($data['price_codes'] ?? []) as $index => $entry) {
            $code = trim((string) ($entry['price_code'] ?? ''));
            if ($code === '') continue;
            $key = mb_strtoupper($code);
            if (isset($seen[$key])) continue;
            $seen[$key] = true;
            $rows[] = [
                'price_code' => $code,
                'selling_price' => round((float) ($entry['selling_price'] ?? 0), 2),
                'sort_order' => $index,
            ];
        }

        $product->priceCodes()->delete();
        if ($rows) $product->priceCodes()->createMany($rows);
        $product->load('priceCodes');
        DB::connection('masterlist')->commit();

        $priceCodes = $product->priceCodes->map(fn ($row) => [
            'price_code' => (string) $row->price_code,
            'selling_price' => (float) $row->selling_price,
        ])->values()->all();

        try {
            $actor = hatdogAuditActor($user);
            hatdogWriteAuditTrail([
                'module' => 'product',
                'action' => 'Updated Pricing Codes',
                'source_connection' => 'masterlist',
                'source_table' => 'product_price_codes',
                'source_id' => $product->id,
                'display_id' => (string) ($product->product_code ?? $product->id),
                'record_name' => trim((string) ($product->description ?: ($product->part_number ?: $product->product_code))),
                'user_name' => $actor['name'],
                'user_identifier' => $actor['identifier'],
                'audit_data' => ['before' => $before, 'after' => $priceCodes],
            ]);
        } catch (\Throwable $auditError) {
            Log::warning('Product pricing-code audit failed', ['product_id' => $product->id, 'error' => $auditError->getMessage()]);
        }

        return response()->json([
            'success' => true,
            'message' => 'Pricing codes updated successfully.',
            'price_codes' => $priceCodes,
        ]);
    } catch (\Throwable $e) {
        if (DB::connection('masterlist')->transactionLevel() > 0) DB::connection('masterlist')->rollBack();
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.prod-master.price-codes.update');

// Product Master - active Sales Notes / Purchase Notes for one product.
Route::get('/admin/masterlist/product/active-notes/{id}', function ($id) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);
    if (is_array($user)) $user = (object) $user;
    if (!in_array((int) ($user->account_type ?? 0), [1, 2, 3], true)) {
        return response()->json(['error' => 'Forbidden'], 403);
    }

    try {
        \App\Models\Product::findOrFail($id);

        $purchaseRows = DB::connection('purchase')
            ->table('purchase_note_items as pni')
            ->join('purchase_notes as pn', 'pn.id', '=', 'pni.purchase_note_id')
            ->where('pni.product_id', $id)
            ->whereIn('pn.status', ['Open', 'Partial', 'Surplus'])
            ->select([
                'pn.purchase_note_number as number',
                'pn.supplier_id',
                'pn.date as note_date',
                'pn.created_at',
                'pn.status',
                'pni.quantity',
                'pni.unit_price',
            ])
            ->get();

        $supplierIds = $purchaseRows->pluck('supplier_id')->map(fn ($value) => (int) $value)->filter()->unique()->values();
        $supplierNames = $supplierIds->isEmpty()
            ? collect()
            : DB::connection('masterlist')->table('suppliers')->whereIn('id', $supplierIds->all())->pluck('name', 'id');

        $salesRows = DB::connection('sales')
            ->table('sales_note_items as sni')
            ->join('sales_notes as sn', 'sn.id', '=', 'sni.sales_note_id')
            ->where('sni.product_id', $id)
            ->whereNull('sni.deleted_at')
            ->whereIn('sn.status', ['Open', 'Partial'])
            ->select([
                'sn.sales_number as number',
                'sn.customer_name',
                'sn.order_date as note_date',
                'sn.created_at',
                'sn.status',
                'sni.quantity',
                'sni.additional_qty',
                'sni.unit_price',
            ])
            ->get();

        $rows = collect();
        foreach ($purchaseRows as $row) {
            $dateSource = $row->created_at ?: $row->note_date;
            $rows->push([
                'type' => 'PN',
                'number' => (string) ($row->number ?? ''),
                'date' => $dateSource ? \Carbon\Carbon::parse($dateSource)->format('Y-m-d') : null,
                'quantity_in' => (int) ($row->quantity ?? 0),
                'quantity_out' => 0,
                'name' => (string) ($supplierNames[(int) ($row->supplier_id ?? 0)] ?? 'N/A'),
                'price' => null,
                'cost' => (float) ($row->unit_price ?? 0),
                'status' => (string) ($row->status ?? ''),
            ]);
        }
        foreach ($salesRows as $row) {
            $dateSource = $row->created_at ?: $row->note_date;
            $rows->push([
                'type' => 'SN',
                'number' => (string) ($row->number ?? ''),
                'date' => $dateSource ? \Carbon\Carbon::parse($dateSource)->format('Y-m-d') : null,
                'quantity_in' => 0,
                'quantity_out' => (int) ($row->quantity ?? 0) + (int) ($row->additional_qty ?? 0),
                'name' => (string) ($row->customer_name ?? 'N/A'),
                'price' => (float) ($row->unit_price ?? 0),
                'cost' => null,
                'status' => (string) ($row->status ?? ''),
            ]);
        }

        $rows = $rows->sortByDesc(fn ($row) => (($row['date'] ?? '') . '|' . ($row['number'] ?? '')))->values();
        return response()->json(['success' => true, 'rows' => $rows]);
    } catch (\Throwable $e) {
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.prod-master.active-notes');


// Delete product
Route::post('/admin/masterlist/product/delete/{id}', function ($id) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

    try {
        if (is_array($user)) {
            $user = (object) $user;
        }

        if (!Schema::connection('ledger')->hasTable('archived_records')) {
            throw new \Exception('Archive table is missing. Please run the archive migration first.');
        }

        DB::connection('masterlist')->beginTransaction();
        DB::connection('ledger')->beginTransaction();

        $product = \App\Models\Product::query()->lockForUpdate()->findOrFail($id);
        $productData = $product->toArray();
        $deletedBy = $user->name ?? $user->username ?? $user->User_ID ?? 'Admin';
        $displayId = (string) ($product->product_code ?? $product->id);
        $dataName = trim((string) (($product->description ?? '') !== '' ? $product->description : ($product->part_number ?? $product->product_code ?? 'Product')));
        $actor = hatdogAuditActor($user);

        $existingArchive = DB::connection('ledger')
            ->table('archived_records')
            ->where('module', 'product')
            ->whereNull('restored_at')
            ->where('source_connection', 'masterlist')
            ->where('source_table', 'products')
            ->where('source_id', $product->id)
            ->first();

        if ($existingArchive) {
            throw new \Exception('This product is already archived.');
        }

        DB::connection('ledger')->table('archived_records')->insert([
            'module' => 'product',
            'source_connection' => 'masterlist',
            'source_table' => 'products',
            'source_id' => $product->id,
            'display_id' => $displayId,
            'data_name' => $dataName,
            'archived_data' => json_encode($productData, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE),
            'deleted_by' => (string) $deletedBy,
            'deleted_at' => now(),
            'expires_at' => now()->addDays(30),
            'created_at' => now(),
            'updated_at' => now(),
        ]);

        hatdogWriteAuditTrail([
            'module' => 'product',
            'action' => 'Deleted',
            'source_connection' => 'masterlist',
            'source_table' => 'products',
            'source_id' => $product->id,
            'display_id' => $displayId,
            'record_name' => $dataName,
            'user_name' => $actor['name'],
            'user_identifier' => $actor['identifier'],
            'audit_data' => [
                'before' => $productData,
            ],
        ]);

        $product->delete();

        DB::connection('ledger')->commit();
        DB::connection('masterlist')->commit();

        return response()->json(['success' => true, 'message' => 'Product archived successfully']);
    } catch (\Exception $e) {
        if (DB::connection('ledger')->transactionLevel() > 0) DB::connection('ledger')->rollBack();
        if (DB::connection('masterlist')->transactionLevel() > 0) DB::connection('masterlist')->rollBack();
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.prod-master.delete');

// Logout Route
Route::post('/logout', function (Request $request) {
    $user = session('user');
    if ($user) {
        $userId = is_array($user) ? ($user['login_ID'] ?? null) : ($user->login_ID ?? null);
        if ($userId && Schema::hasTable('login_activity_logs')) {
            if (!Schema::hasColumn('login_activity_logs', 'logged_out_at')) {
                Schema::table('login_activity_logs', function ($table) {
                    $table->timestamp('logged_out_at')->nullable()->after('logged_in_at');
                });
            }
            DB::table('login_activity_logs')
                ->where('login_id', $userId)
                ->where('account_type', is_array($user) ? ($user['account_type'] ?? null) : ($user->account_type ?? null))
                ->whereNull('logged_out_at')
                ->orderBy('logged_in_at', 'desc')
                ->limit(1)
                ->update(['logged_out_at' => now()]);
        }
    }
    session()->forget('user');
    return response()->json(['success' => true]);
})->name('logout');

// AJAX User Creation Endpoint
Route::post('/admin/usm/create', function (Request $request) {
    $user = session('user');
    $authAccountType = is_array($user) ? $user['account_type'] : ($user ? $user->account_type : null);
    if (!$user || $authAccountType != 1) {
        return response()->json(['error' => 'Unauthorized Access'], 403);
    }

    try {
        $validated = $request->validate([
            'User_ID' => 'required|unique:logins,User_ID',
            'User_First_Name' => 'required|string|max:100',
            'User_Middle_Name' => 'nullable|string|max:100',
            'User_Last_Name' => 'required|string|max:100',
            'Password' => 'required|string|min:4',
            'account_type' => 'required|in:admin,employee,employee_with_pricelist,worker',
            'Gender' => 'required|string|in:Male,Female,Other',
        ]);
        
        $acctTypeMap = [
            'admin' => 1,
            'employee_with_pricelist' => 2,
            'employee' => 2,
            'worker' => 3,
            'customer' => 3
        ];

        $newUser = Login::create([
            'User_ID' => $validated['User_ID'],
            'User_First_Name' => $validated['User_First_Name'],
            'User_Middle_Name' => $validated['User_Middle_Name'] ?? '',
            'User_Last_Name' => $validated['User_Last_Name'],
            'Password' => $validated['Password'], // Stored plain text matching standard seed logins for reveals
            'account_type' => $acctTypeMap[$validated['account_type']],
            'Gender' => $validated['Gender'],
        ]);

        return response()->json(['success' => true, 'user' => $newUser]);
    } catch (\Illuminate\Validation\ValidationException $e) {
        return response()->json(['error' => $e->validator->errors()->first()], 422);
    } catch (\Throwable $e) {
        return response()->json(['error' => 'Database error: ' . $e->getMessage()], 500);
    }
})->name('admin.usm.create');

// AJAX Password Reset Endpoint
Route::post('/admin/usm/reset-password', function (Request $request) {
    $user = session('user');
    $authAccountType = is_array($user) ? $user['account_type'] : ($user ? $user->account_type : null);
    if (!$user || $authAccountType != 1) {
        return response()->json(['error' => 'Unauthorized Access'], 403);
    }

    try {
        $validated = $request->validate([
            'User_ID' => 'required|exists:logins,User_ID',
            'Password' => 'required|string|min:4',
        ]);

        $dbUser = Login::where('User_ID', $validated['User_ID'])->first();
        if ($dbUser) {
            $dbUser->Password = $validated['Password'];
            $dbUser->save();
            return response()->json([
                'success' => true, 
                'updated_at' => $dbUser->updated_at ? $dbUser->updated_at->format('Y-m-d H:i') : now()->format('Y-m-d H:i')
            ]);
        }
        return response()->json(['error' => 'User not found'], 404);
    } catch (\Illuminate\Validation\ValidationException $e) {
        return response()->json(['error' => $e->validator->errors()->first()], 422);
    } catch (\Throwable $e) {
        return response()->json(['error' => 'Database error: ' . $e->getMessage()], 500);
    }
})->name('admin.usm.reset-password');

// AJAX User Deletion Endpoint
Route::delete('/admin/usm/delete', function (Request $request) {
    $user = session('user');
    $authAccountType = is_array($user) ? $user['account_type'] : ($user ? $user->account_type : null);
    if (!$user || $authAccountType != 1) {
        return response()->json(['error' => 'Unauthorized Access'], 403);
    }

    try {
        $validated = $request->validate([
            'User_ID' => 'required|exists:logins,User_ID',
        ]);

        // Prevent self-deletion
        $loggedInUserId = is_array($user) ? $user['User_ID'] : $user->User_ID;
        if ($validated['User_ID'] === $loggedInUserId) {
            return response()->json(['error' => 'You cannot delete your own administrative account.'], 400);
        }

        $dbUser = Login::where('User_ID', $validated['User_ID'])->first();
        if ($dbUser) {
            $dbUser->delete();
            return response()->json(['success' => true]);
        }
        return response()->json(['error' => 'User not found'], 404);
    } catch (\Illuminate\Validation\ValidationException $e) {
        return response()->json(['error' => $e->validator->errors()->first()], 422);
    } catch (\Throwable $e) {
        return response()->json(['error' => 'Database error: ' . $e->getMessage()], 500);
    }
})->name('admin.usm.delete');

