Route::get('/admin/reports/cost-report/product-codes', function (\Illuminate\Http\Request $request) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

    $query = trim((string) $request->query('query', ''));
    $productCodes = DB::connection('masterlist')
        ->table('products')
        ->whereNotNull('product_code')
        ->where('product_code', '!=', '')
        ->when($query !== '', function ($q) use ($query) {
            $q->where('product_code', 'like', '%' . $query . '%');
        })
        ->distinct()
        ->orderBy('product_code')
        ->limit(25)
        ->pluck('product_code')
        ->values();

    return response()->json($productCodes);
})->name('admin.cost-report.product-codes');

