Route::get('/admin/reports/cost-report/pricelist-codes', function (\Illuminate\Http\Request $request) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

    try {
        if (
            !Schema::connection('masterlist')->hasTable('products')
            || !Schema::connection('masterlist')->hasColumn('products', 'pricelist_code')
        ) {
            return response()->json([]);
        }

        $query = trim((string) $request->query('query', ''));
        $pricelistCodes = DB::connection('masterlist')
            ->table('products')
            ->whereNotNull('pricelist_code')
            ->where('pricelist_code', '!=', '')
            ->when($query !== '', function ($q) use ($query) {
                $q->where('pricelist_code', 'like', '%' . $query . '%');
            })
            ->distinct()
            ->orderBy('pricelist_code')
            ->limit(25)
            ->pluck('pricelist_code')
            ->values();

        return response()->json($pricelistCodes);
    } catch (\Throwable $e) {
        Log::error('Cost Report pricelist-code lookup failed.', [
            'message' => $e->getMessage(),
            'exception' => $e::class,
        ]);

        // Keep Cost Report usable even if the optional Pricelist Code lookup fails.
        return response()->json([]);
    }
})->name('admin.cost-report.pricelist-codes');

Route::get('/admin/reports/cost-report/data', function (\Illuminate\Http\Request $request) {
    $user = session('user');
    if (!$user) return response()->json(['success' => false, 'error' => 'Unauthorized'], 403);

    $page = (int) $request->query('page', 1);
    $perPage = (int) $request->query('per_page', 50);

    $normalizeMultiFilter = static function ($value) {
        return collect(is_array($value) ? $value : [$value])
            ->map(fn ($item) => trim((string) $item))
            ->filter(fn ($item) => $item !== '')
            ->unique()
            ->values();
    };

    // Product Code and Part Number accept one legacy value or multiple
    // checkbox selections (product_code[] / part_number[]).
    $productCodes = $normalizeMultiFilter($request->query('product_code', []));
    $partNumbers = $normalizeMultiFilter($request->query('part_number', []));
    $description = $request->query('description', '');
    $application = $request->query('application', '');
    $category = $request->query('category', '');
    $pricelistCode = trim((string) $request->query('pricelist_code', ''));
    $supplier = $request->query('supplier', '');
    $year1 = (int) $request->query('year1', date('Y'));
    $year2 = (int) $request->query('year2', date('Y') - 1);
    $year3 = (int) $request->query('year3', date('Y') - 2);
    $all = $request->query('all', '0');

    $query = \App\Models\Product::on('masterlist');

    // Product Code / Part Number are searchable multi-select dropdowns. Apply
    // them before any ledger or Sales History work so only selected products
    // are calculated and printed.
    if ($productCodes->isNotEmpty()) $query->whereIn('product_code', $productCodes->all());
    if ($partNumbers->isNotEmpty()) $query->whereIn('part_number', $partNumbers->all());
    if (!empty($description)) $query->where('description', 'LIKE', '%' . $description . '%');
    if (!empty($application)) $query->where('application', 'LIKE', '%' . $application . '%');
    if (!empty($category)) $query->where('category', $category);
    if (
        $pricelistCode !== ''
        && Schema::connection('masterlist')->hasColumn('products', 'pricelist_code')
    ) {
        $query->where('pricelist_code', 'LIKE', '%' . $pricelistCode . '%');
    }
    if (!empty($supplier)) $query->where('supplier', 'LIKE', '%' . $supplier . '%');

    $allProductIds = (clone $query)->pluck('id');

    // Batch-fetch latest ledger entry per product
    $latestLedger = DB::connection('ledger')->table('product_ledgers')
        ->whereIn('product_id', $allProductIds)
        ->selectRaw('product_id, MAX(date) as max_date')
        ->groupBy('product_id')
        ->pluck('max_date', 'product_id');

    $latestPrices = [];
    $latestBalances = [];
    $latestSuppliers = [];
    $supplierDateByProduct = [];
    $purchaseTransByProduct = [];
    if ($latestLedger->isNotEmpty()) {
        $ledgerRows = DB::connection('ledger')->table('product_ledgers')
            ->whereIn('product_id', $latestLedger->keys())
            ->whereIn('id', function ($q) use ($latestLedger) {
                $q->selectRaw('MAX(l2.id)')
                    ->from('product_ledgers as l2')
                    ->whereIn('l2.product_id', $latestLedger->keys())
                    ->groupBy('l2.product_id');
            })
            ->get();
        foreach ($ledgerRows as $row) {
            $latestBalances[$row->product_id] = (int) ($row->balance_stock ?? 0);
            $latestPrices[$row->product_id] = (float) ($row->price ?? 0);
            $latestSuppliers[$row->product_id] = $row->entity_name ?? '';
        }

        // Get latest purchase (IN) per product for supplier_ledgers lookup (date & supplier)
        $latestPurchaseIds = DB::connection('ledger')->table('product_ledgers')
            ->whereIn('product_id', $allProductIds)
            ->where('transaction_type', 'IN')
            ->selectRaw('product_id, MAX(id) as max_id')
            ->groupBy('product_id')
            ->pluck('max_id', 'product_id');

        if ($latestPurchaseIds->isNotEmpty()) {
            $purchaseRows = DB::connection('ledger')->table('product_ledgers')
                ->whereIn('id', $latestPurchaseIds->values())
                ->get(['id', 'product_id', 'transaction_number', 'supplier_id']);

            $transNumbers = [];
            foreach ($purchaseRows as $pr) {
                $tn = trim((string) ($pr->transaction_number ?? ''));
                if ($tn !== '') {
                    $purchaseTransByProduct[$pr->product_id] = $tn;
                    $transNumbers[] = $tn;
                }
            }

            if (!empty($transNumbers)) {
                $transNumbers = array_unique($transNumbers);
                $supplierLedgers = DB::connection('ledger')->table('supplier_ledgers')
                    ->whereIn('transaction_code', $transNumbers)
                    ->where('module_type', 'Purchase Order')
                    ->get(['transaction_code', 'date', 'supplier_id']);

                $supplierLedgerMap = [];
                foreach ($supplierLedgers as $sl) {
                    $tc = trim((string) ($sl->transaction_code ?? ''));
                    if ($tc !== '') {
                        $supplierLedgerMap[$tc] = $sl;
                        $supplierDateByProduct[$tc] = $sl->date;
                    }
                }

                $supplierIds = collect($supplierLedgers)->pluck('supplier_id')->unique()->filter()->values();
                $supplierNames = [];
                if ($supplierIds->isNotEmpty()) {
                    $supplierNames = DB::connection('masterlist')->table('suppliers')
                        ->whereIn('id', $supplierIds)
                        ->pluck('name', 'id');
                }

                foreach ($purchaseTransByProduct as $pid => $tn) {
                    if (isset($supplierLedgerMap[$tn])) {
                        $slEntry = $supplierLedgerMap[$tn];
                        $latestSuppliers[$pid] = $supplierNames[$slEntry->supplier_id] ?? ($latestSuppliers[$pid] ?? '');
                    }
                }
            }
        }
    }

    // Batch-fetch GROSS sales per product per year from Product Ledger.
    // Sales Returns are deducted below from sales_return_items.quantity so both
    // legacy SALRTN imports and the current Sales Return module use the FULL
    // returned quantity (not only the good quantity restored to inventory).
    $outColumn = hatdogSchemaHasColumnCached('ledger', 'product_ledgers', 'out') ? 'out' : 'quantity_out';
    $salesByYear = [];
    $years = array_values(array_unique([$year1, $year2, $year3]));
    foreach ($years as $year) {
        $yearSales = DB::connection('ledger')->table('product_ledgers')
            ->whereIn('product_id', $allProductIds)
            ->whereYear('date', $year)
            ->selectRaw('product_id, SUM(' . $outColumn . ') as total_out')
            ->groupBy('product_id')
            ->pluck('total_out', 'product_id');
        foreach ($yearSales as $pid => $total) {
            $salesByYear[(int) $pid][(int) $year] = (float) $total;
        }
    }

    // Authoritative Sales Return quantities. sales_return_items contains both
    // imported legacy SALRTN returns and returns created by the current screen.
    $returnQtyByYear = [];
    $coveredReturnNumbers = [];

    if ($allProductIds->isNotEmpty() && !empty($years)) {
        $yearPlaceholders = implode(',', array_fill(0, count($years), '?'));

        $returnRows = DB::connection('sales')->table('sales_returns as sr')
            ->join('sales_return_items as sri', 'sri.sales_return_id', '=', 'sr.id')
            ->whereIn('sri.product_id', $allProductIds)
            ->whereRaw("UPPER(TRIM(COALESCE(sr.status, 'COMPLETED'))) NOT IN ('CANCELLED', 'VOID')")
            ->whereRaw(
                "YEAR(COALESCE(sr.created_at, sri.created_at)) IN ($yearPlaceholders)",
                $years
            )
            ->selectRaw(
                'sri.product_id, sri.quantity, sr.return_number, ' .
                'YEAR(COALESCE(sr.created_at, sri.created_at)) as return_year'
            )
            ->get();

        foreach ($returnRows as $returnRow) {
            $pid = (int) ($returnRow->product_id ?? 0);
            $year = (int) ($returnRow->return_year ?? 0);
            $qty = (float) ($returnRow->quantity ?? 0);

            if ($pid <= 0 || $year <= 0 || $qty <= 0) {
                continue;
            }

            $returnQtyByYear[$pid][$year] = ($returnQtyByYear[$pid][$year] ?? 0) + $qty;

            $returnNumber = strtolower(trim((string) ($returnRow->return_number ?? '')));
            if ($returnNumber !== '') {
                $coveredReturnNumbers[$pid . '|' . $year . '|' . $returnNumber] = true;
            }
        }

        // Fallback for historical ledger return rows that are not represented
        // in sales_return_items. Matching return numbers are skipped to prevent
        // the same legacy/current return from being deducted twice.
        $ledgerReturnRows = DB::connection('ledger')->table('product_ledgers')
            ->whereIn('product_id', $allProductIds)
            ->where('transaction_type', 'IN')
            ->whereRaw('YEAR(date) IN (' . $yearPlaceholders . ')', $years)
            ->where(function ($returnQuery) {
                $returnQuery
                    ->whereRaw("LOWER(COALESCE(remarks,'')) LIKE '%salrtn%'")
                    ->orWhereRaw("LOWER(COALESCE(remarks,'')) LIKE '%sales return%'")
                    ->orWhereRaw("LOWER(COALESCE(remarks,'')) LIKE '%sales order edit - item removed%'")
                    ->orWhereRaw("LOWER(COALESCE(transaction_number,'')) LIKE 'ret%'")
                    ->orWhereRaw("LOWER(COALESCE(transaction_number,'')) LIKE 'saltrn%'");
            })
            ->selectRaw(
                'product_id, quantity_in, transaction_number, reference_number, YEAR(date) as return_year'
            )
            ->get();

        foreach ($ledgerReturnRows as $returnRow) {
            $pid = (int) ($returnRow->product_id ?? 0);
            $year = (int) ($returnRow->return_year ?? 0);
            $qty = (float) ($returnRow->quantity_in ?? 0);

            if ($pid <= 0 || $year <= 0 || $qty <= 0) {
                continue;
            }

            $transactionNumber = strtolower(trim((string) ($returnRow->transaction_number ?? '')));
            $referenceNumber = strtolower(trim((string) ($returnRow->reference_number ?? '')));

            $alreadyCovered = ($transactionNumber !== ''
                    && isset($coveredReturnNumbers[$pid . '|' . $year . '|' . $transactionNumber]))
                || ($referenceNumber !== ''
                    && isset($coveredReturnNumbers[$pid . '|' . $year . '|' . $referenceNumber]));

            if ($alreadyCovered) {
                continue;
            }

            $returnQtyByYear[$pid][$year] = ($returnQtyByYear[$pid][$year] ?? 0) + $qty;
        }
    }

    // NET SALES = gross Product Ledger OUT - all valid Sales Return quantities.
    foreach ($returnQtyByYear as $pid => $yearReturns) {
        foreach ($yearReturns as $year => $returnQty) {
            $salesByYear[$pid][$year] = ($salesByYear[$pid][$year] ?? 0) - $returnQty;
        }
    }

    // Fetch total counts for stats (unpaginated)
    $allItemsForStats = $query->get();
    $totalItems = $allItemsForStats->count();
    $totalCost = 0;
    $highestCost = 0;
    foreach ($allItemsForStats as $p) {
        $cost = (float) ($p->cost ?? 0);
        $totalCost += $cost;
        if ($cost > $highestCost) $highestCost = $cost;
    }
    $avgCost = $totalItems > 0 ? $totalCost / $totalItems : 0;

    // All items (for print export) or paginated
    $allProducts = $all === '1' ? $query->get() : null;
    $paginated = $all === '1' ? null : $query->paginate($perPage, ['*'], 'page', $page);

    $productCollection = $all === '1' ? $allProducts : collect($paginated->items());

    // Cost Report pricing comes directly from core4_masterlist.products, while
    // Cost / Supplier / Cost Date come from supplier_ledger_items + supplier_ledgers.
    // Resolve only the products on this response so a filtered/single-product report
    // does not do unnecessary supplier-ledger work.
    $purchaseCostService = app(\App\Services\ProductPurchaseCostService::class);
    $purchaseCostLookup = $purchaseCostService->getLatestPurchaseCosts(
        $productCollection->pluck('id')->map(fn ($id) => (int) $id)->filter()->values()->all(),
        $productCollection->pluck('product_code')->map(fn ($code) => trim((string) $code))->filter()->values()->all(),
        true // Cost Report: supplier/cost/date must match this exact product identity.
    );

    $items = $productCollection->map(function ($p) use ($latestBalances, $latestPrices, $latestSuppliers, $salesByYear, $year1, $year2, $year3, $purchaseTransByProduct, $supplierDateByProduct, $purchaseCostService, $purchaseCostLookup) {
        $pid = $p->id;
        $slTransNo = $purchaseTransByProduct[$pid] ?? null;
        $amountDate = '';
        if ($slTransNo && isset($supplierDateByProduct[$slTransNo])) {
            $amountDate = \Carbon\Carbon::parse($supplierDateByProduct[$slTransNo])->format('Y-m-d');
        }

        $costInfo = $purchaseCostLookup['by_product_id'][(int) $pid] ?? null;
        if (!$costInfo) {
            $costInfo = $purchaseCostLookup['by_product_code'][
                $purchaseCostService->normalizeProductCode($p->product_code ?? '')
            ] ?? null;
        }

        $costDate = '';
        if (!empty($costInfo['purchase_date'])) {
            try {
                // The supplier-ledger parent date is the authoritative purchase date.
                $costDate = \Carbon\Carbon::parse($costInfo['purchase_date'])->format('Y-m-d');
            } catch (\Throwable $e) {
                $costDate = (string) $costInfo['purchase_date'];
            }
        }

        return [
            'product_code' => $p->product_code ?? '',
            'part_number' => $p->part_number ?? '',
            'description' => $p->description ?? '',
            'application' => $p->application ?? '',
            'category' => $p->category ?? '',
            // Preserve the legacy fields used by Admin/Regular Cost Report.
            'supplier' => $costInfo['supplier_name'] ?? '',
            'last_cost' => (float) ($p->cost ?? 0),
            // Special Cost Report uses these supplier-ledger and Product Master fields.
            'cost_supplier' => $costInfo['supplier_name'] ?? '',
            'supplier_cost' => (float) ($costInfo['unit_price'] ?? 0),
            'cost_date' => $costDate,
            'local_price' => (float) ($p->selling_price ?? 0),
            'online_price' => (float) ($p->price_online ?? 0),
            // Keep legacy response fields for the Admin/Regular templates that may
            // still reference them. Special Cost Report uses the fields above.
            'amount' => (float) ($latestPrices[$pid] ?? 0),
            'amount_date' => $amountDate,
            'on_hand' => (int) ($latestBalances[$pid] ?? 0),
            'sales_1' => (int) ($salesByYear[$pid][$year1] ?? 0),
            'sales_2' => (int) ($salesByYear[$pid][$year2] ?? 0),
            'sales_3' => (int) ($salesByYear[$pid][$year3] ?? 0),
        ];
    })->values();

    return response()->json([
        'success' => true,
        'items' => $items,
        'pagination' => $paginated ? [
            'current_page' => $paginated->currentPage(),
            'last_page' => $paginated->lastPage(),
            'per_page' => $paginated->perPage(),
            'total' => $paginated->total(),
        ] : null,
        'stats' => [
            'total_items' => $totalItems,
            'total_cost' => $totalCost,
            'avg_cost' => $avgCost,
            'highest_cost' => $highestCost,
        ],
    ]);
})->name('admin.cost-report.data');

Route::post('/admin/reports/accounts-receivable/print-data', function (\Illuminate\Http\Request $request) {
    $user = session('user');
    if (!$user) return response()->json(['success' => false, 'message' => 'Unauthorized'], 403);

    try {
        $dateType = (string) $request->input('date_type', 'monthly');
        $date = trim((string) $request->input('date', ''));
        $dateFrom = trim((string) $request->input('date_from', ''));
        $dateTo = trim((string) $request->input('date_to', ''));
        $customerId = (int) $request->input('customer_id', 0);
        $customer = trim((string) $request->input('customer', 'Select All'));
        $agent = trim((string) $request->input('agent', 'Select All'));

        $paidRows = DB::connection('accounting')->table('process_payment_invoices')
            ->select(
                'source_type',
                'source_id',
                DB::raw('SUM(paid_amount) as paid_total')
            )
            ->groupBy('source_type', 'source_id')
            ->get()
            ->keyBy(fn ($row) => $row->source_type . ':' . $row->source_id);

        $normalizeInvKey = static fn ($v) => strtoupper(preg_replace('/\s+/', '', trim((string) $v)));

        $rawReturnRows = DB::connection('sales')->table('sales_returns as sr')
            ->join('sales_return_items as sri', 'sri.sales_return_id', '=', 'sr.id')
            ->whereNotNull('sr.invoice_no')
            ->whereRaw("UPPER(TRIM(COALESCE(sr.status, ''))) NOT IN ('CANCELLED', 'VOID')")
            ->select(
                'sr.invoice_no',
                DB::raw("SUM(COALESCE(sri.return_amount, sri.subtotal, 0)) as return_total")
            )
            ->groupBy('sr.invoice_no')
            ->get();

        $returnMap = [];
        foreach ($rawReturnRows as $row) {
            $rawInvoice = (string) ($row->invoice_no ?? '');
            $total = (float) ($row->return_total ?? 0);
            if ($rawInvoice === '' || $total <= 0) {
                continue;
            }

            $keys = [$normalizeInvKey($rawInvoice)];

            foreach (preg_split('/[,\s\/]+/', $rawInvoice) as $token) {
                $token = trim((string) $token);
                if ($token === '') {
                    continue;
                }
                $keys[] = $normalizeInvKey($token);
            }

            if (preg_match_all('/SN-\d+/i', $rawInvoice, $matches) && !empty($matches[0])) {
                foreach ($matches[0] as $sn) {
                    $sn = trim((string) $sn);
                    if ($sn === '') {
                        continue;
                    }
                    $keys[] = $normalizeInvKey($sn);
                }
            }

            $keys = array_values(array_unique(array_filter($keys, fn ($key) => $key !== '')));
            foreach ($keys as $key) {
                $returnMap[$key] = (float) ($returnMap[$key] ?? 0) + $total;
            }
        }

        $salesOrders = DB::connection('sales')->table('sales_orders as so')
            ->leftJoin('sales_notes as sn', 'sn.id', '=', 'so.sales_note_id')
            ->where(function ($query) {
                $query->whereIn('so.status', ['Closed', 'Confirmed'])
                    ->orWhere('sn.status', 'Closed');
            })
            ->select(
                DB::raw("'sales_order' as source_type"),
                'so.id as source_id',
                'so.customer_id',
                'so.customer_name',
                'so.total_amount as amount',
                'so.order_number as po_no',
                'sn.sales_number as sales_note_no',
                'sn.net_total as sales_note_amount',
                DB::raw("COALESCE(NULLIF(so.invoice_numbers, ''), so.order_number) as invoice_no"),
                DB::raw("COALESCE(NULLIF(sn.salesman, ''), 'Unassigned') as salesman"),
                DB::raw('COALESCE(so.created_at, sn.order_date) as document_date')
            )
            ->get();

        $consignmentInvoices = DB::connection('sales')->table('consignment_invoices as ci')
            ->leftJoin('sales_notes as sn', 'sn.id', '=', 'ci.sales_note_id')
            ->whereNotIn('ci.status', ['Cancelled', 'Void'])
            ->select(
                DB::raw("'consignment_invoice' as source_type"),
                'ci.id as source_id',
                'ci.customer_id',
                'ci.customer_name',
                'ci.total_amount as amount',
                'ci.invoice_number as po_no',
                'sn.sales_number as sales_note_no',
                'sn.net_total as sales_note_amount',
                'ci.invoice_number as invoice_no',
                DB::raw("COALESCE(NULLIF(sn.salesman, ''), 'Unassigned') as salesman"),
                DB::raw('COALESCE(ci.created_at, sn.order_date) as document_date')
            )
            ->get();

        $documents = $salesOrders
            ->concat($consignmentInvoices)
            ->filter(fn ($doc) => !empty($doc->customer_id) && (float) $doc->amount > 0)
            ->map(function ($doc) use ($paidRows, $returnMap, $normalizeInvKey) {
                $paid = (float) ($paidRows->get($doc->source_type . ':' . $doc->source_id)->paid_total ?? 0);
                $amount = (float) ($doc->amount ?? 0);

                $invoiceList = collect(explode(',', (string) ($doc->invoice_no ?? '')))
                    ->map(fn ($value) => $normalizeInvKey($value))
                    ->filter(fn ($value) => $value !== '')
                    ->merge([$normalizeInvKey($doc->po_no ?? '')])
                    ->merge([$normalizeInvKey($doc->sales_note_no ?? '')])
                    ->unique()
                    ->values();

                $returned = (float) $invoiceList->sum(function ($invoice) use ($returnMap) {
                    return (float) ($returnMap[$invoice] ?? 0);
                });

                $salesNoteAmount = (float) ($doc->sales_note_amount ?? 0);
                $autoSettledByReturn = $returned > 0 && (
                    $returned >= $amount
                    || ($salesNoteAmount > 0 && $returned >= $salesNoteAmount)
                    || $paid >= ($amount / 2)
                );

                return (object) [
                    'source_type' => $doc->source_type,
                    'source_id' => (int) $doc->source_id,
                    'customer_id' => (int) $doc->customer_id,
                    'customer_name' => (string) ($doc->customer_name ?? ''),
                    'salesman' => trim((string) ($doc->salesman ?? '')) !== '' ? trim((string) $doc->salesman) : 'Unassigned',
                    'document_date' => $doc->document_date,
                    'due_amount' => $autoSettledByReturn ? 0 : max($amount - $paid - $returned, 0),
                ];
            })
            ->filter(fn ($doc) => $doc->due_amount > 0);

        $matchesDate = function ($value) use ($dateType, $date, $dateFrom, $dateTo) {
            if (empty($value)) {
                return $dateType === '' || ($date === '' && $dateFrom === '' && $dateTo === '');
            }

            try {
                $docDate = \Carbon\Carbon::parse($value);
            } catch (\Throwable $e) {
                return false;
            }

            if ($dateType === 'annual' && preg_match('/^\d{4}$/', $date)) {
                return (int) $docDate->format('Y') === (int) $date;
            }

            if ($dateType === 'monthly' && preg_match('/^\d{4}-\d{2}$/', $date)) {
                return $docDate->format('Y-m') === $date;
            }

            if ($dateType === 'as-of' && preg_match('/^\d{4}-\d{2}-\d{2}$/', $date)) {
                return $docDate->toDateString() <= $date;
            }

            if ($dateType === 'from-to' && preg_match('/^\d{4}-\d{2}-\d{2}$/', $dateFrom) && preg_match('/^\d{4}-\d{2}-\d{2}$/', $dateTo)) {
                $from = \Carbon\Carbon::parse($dateFrom)->startOfDay();
                $to = \Carbon\Carbon::parse($dateTo)->endOfDay();
                return $docDate->between($from, $to, true);
            }

            return true;
        };

        $documents = $documents
            ->filter(function ($doc) use ($customerId, $customer, $agent, $matchesDate) {
                if ($customerId > 0 && (int) $doc->customer_id !== $customerId) {
                    return false;
                }

                if ($customerId <= 0 && $customer !== '' && strtoupper($customer) !== 'SELECT ALL') {
                    if (!str_contains(strtolower((string) $doc->customer_name), strtolower($customer))) {
                        return false;
                    }
                }

                if ($agent !== '' && strtoupper($agent) !== 'SELECT ALL') {
                    if (!str_contains(strtolower((string) $doc->salesman), strtolower($agent))) {
                        return false;
                    }
                }

                return $matchesDate($doc->document_date);
            })
            ->values();

        $groups = $documents
            ->groupBy(fn ($doc) => trim((string) $doc->salesman) !== '' ? trim((string) $doc->salesman) : 'Unassigned')
            ->map(function ($agentDocs, $salesman) {
                $customers = $agentDocs
                    ->groupBy(fn ($doc) => ((int) $doc->customer_id) . '|' . trim((string) $doc->customer_name))
                    ->map(function ($customerDocs) {
                        $first = $customerDocs->first();
                        return [
                            'customer_name' => (string) ($first->customer_name ?? ''),
                            'total_credit' => round((float) $customerDocs->sum('due_amount'), 2),
                        ];
                    })
                    ->sortBy('customer_name', SORT_NATURAL | SORT_FLAG_CASE)
                    ->values();

                return [
                    'salesman' => (string) $salesman,
                    'customers' => $customers,
                    'agent_total' => round((float) $customers->sum('total_credit'), 2),
                ];
            })
            ->sortBy('salesman', SORT_NATURAL | SORT_FLAG_CASE)
            ->values();

        $dateTypeLabel = match ($dateType) {
            'annual' => 'Annual',
            'monthly' => 'Monthly',
            'as-of' => 'As of',
            'from-to' => 'From TO',
            default => 'Date Type',
        };

        $dateValueLabel = match ($dateType) {
            'annual', 'monthly', 'as-of' => $date !== '' ? $date : '—',
            'from-to' => trim(($dateFrom !== '' ? $dateFrom : '—') . ' to ' . ($dateTo !== '' ? $dateTo : '—')),
            default => '—',
        };

        return response()->json([
            'success' => true,
            'date_type_label' => $dateTypeLabel,
            'date_value_label' => $dateValueLabel,
            'groups' => $groups->values(),
        ]);
    } catch (\Throwable $e) {
        Log::error('Accounts receivable print data error: ' . $e->getMessage());
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.accounts-receivable.print-data');

