Route::post('/admin/reports/top-products/data', function (\Illuminate\Http\Request $request) {
    if (!session('user')) return response()->json(['error' => 'Unauthorized'], 403);

    try {
        $dateType = strtolower(trim((string) $request->input('date_type', 'monthly')));
        $channel = strtolower(trim((string) $request->input('channel', 'both')));
        if (!in_array($channel, ['both', 'local', 'online'], true)) $channel = 'both';

        $month = trim((string) $request->input('month', ''));
        $asOf = trim((string) $request->input('as_of', ''));
        $dateFrom = trim((string) $request->input('date_from', ''));
        $dateTo = trim((string) $request->input('date_to', ''));
        $years = collect((array) $request->input('years', []))
            ->map(fn ($value) => (int) $value)
            ->filter(fn ($year) => $year >= 2000 && $year <= 2100)
            ->unique()->sortDesc()->values()->all();

        $customerId = (int) $request->input('customer_id', 0);
        $customer = trim((string) $request->input('customer', ''));
        $brand = trim((string) $request->input('brand', ''));
        $description = trim((string) $request->input('description', ''));
        $agent = trim((string) $request->input('agent', ''));

        $isAll = static fn (string $value): bool => $value === '' || in_array(strtolower($value), ['all', 'select all'], true);

        if ($dateType === 'annual' && empty($years)) {
            $years = [(int) date('Y')];
        }

        $periods = [];
        if ($dateType === 'annual') {
            foreach ($years as $year) {
                $periods[] = ['key' => (string) $year, 'label' => (string) $year, 'from' => "$year-01-01", 'to' => "$year-12-31"];
            }
        } elseif ($dateType === 'monthly' && preg_match('/^\d{4}-\d{2}$/', $month)) {
            $from = \Carbon\Carbon::createFromFormat('Y-m', $month)->startOfMonth();
            $to = (clone $from)->endOfMonth();
            $periods[] = ['key' => $month, 'label' => $from->format('F Y'), 'from' => $from->toDateString(), 'to' => $to->toDateString()];
        } elseif ($dateType === 'as-of' && preg_match('/^\d{4}-\d{2}-\d{2}$/', $asOf)) {
            $periods[] = ['key' => 'as-of', 'label' => 'AS OF ' . \Carbon\Carbon::parse($asOf)->format('F d, Y'), 'from' => '2000-01-01', 'to' => $asOf];
        } elseif ($dateType === 'from-to' && preg_match('/^\d{4}-\d{2}-\d{2}$/', $dateFrom) && preg_match('/^\d{4}-\d{2}-\d{2}$/', $dateTo)) {
            if ($dateFrom > $dateTo) [$dateFrom, $dateTo] = [$dateTo, $dateFrom];
            $periods[] = ['key' => 'from-to', 'label' => \Carbon\Carbon::parse($dateFrom)->format('M d, Y') . ' - ' . \Carbon\Carbon::parse($dateTo)->format('M d, Y'), 'from' => $dateFrom, 'to' => $dateTo];
        } else {
            return response()->json(['success' => false, 'message' => 'Please choose a valid report date.'], 422);
        }

        $rangeFrom = collect($periods)->min('from');
        $rangeTo = collect($periods)->max('to');

        $productQuery = DB::connection('masterlist')->table('products')
            ->select(['id', 'product_code', 'part_number', 'description', 'category', 'unit', 'on_hand', 'selling_price', 'price_online']);
        if (!$isAll($brand)) $productQuery->where('category', 'like', '%' . $brand . '%');
        if (!$isAll($description)) $productQuery->where('description', 'like', '%' . $description . '%');
        $products = $productQuery->get()->keyBy('id');
        if ($products->isEmpty()) return response()->json(['success' => true, 'periods' => $periods, 'products' => []]);

        $productIds = $products->keys()->map(fn ($id) => (int) $id)->values()->all();

        // Historical Online Reports identify old Online Sales Notes; modern generated
        // Online orders are also detected by the ONL-* order number.
        $onlineNoteIds = [];
        DB::connection('sales')->table('online_reports')->select('sales_note_ids')->orderBy('id')->chunk(1000, function ($rows) use (&$onlineNoteIds) {
            foreach ($rows as $row) {
                foreach (explode(',', (string) ($row->sales_note_ids ?? '')) as $id) {
                    $id = (int) trim($id);
                    if ($id > 0) $onlineNoteIds[$id] = true;
                }
            }
        });

        $ordersQuery = DB::connection('sales')->table('sales_orders as so')
            ->join('sales_order_items as soi', 'soi.sales_order_id', '=', 'so.id')
            ->leftJoin('sales_notes as sn', 'sn.id', '=', 'so.sales_note_id')
            ->whereIn('soi.product_id', $productIds)
            ->whereBetween(DB::raw('COALESCE(sn.order_date, DATE(so.created_at))'), [$rangeFrom, $rangeTo])
            ->whereRaw("LOWER(COALESCE(so.order_number,'')) NOT LIKE '%return%'")
            ->whereRaw("LOWER(COALESCE(so.order_number,'')) NOT LIKE 'ret-%'")
            ->whereRaw("LOWER(COALESCE(so.order_number,'')) NOT LIKE 'salrtn%'");

        if ($customerId > 0) {
            $ordersQuery->where('so.customer_id', $customerId);
        } elseif (!$isAll($customer)) {
            $ordersQuery->where('so.customer_name', 'like', '%' . $customer . '%');
        }
        if (!$isAll($agent)) $ordersQuery->where('sn.salesman', 'like', '%' . $agent . '%');

        $orderRows = $ordersQuery->get([
            'so.id as sales_order_id', 'so.sales_note_id', 'so.order_number', 'so.customer_id', 'so.customer_name',
            'so.invoice_numbers', 'soi.product_id', 'soi.quantity', 'soi.actual_qty', 'soi.additional_qty',
            'soi.subtotal', 'sn.order_date', 'sn.salesman', DB::raw('DATE(so.created_at) as sales_order_date'),
        ]);

        $stats = [];
        $invoiceMeta = [];
        $normalizeInvoices = static function ($value): array {
            if (is_array($value)) return $value;
            $raw = trim((string) $value);
            if ($raw === '') return [];
            $decoded = json_decode($raw, true);
            if (is_array($decoded)) return $decoded;
            return preg_split('/\s*,\s*/', $raw, -1, PREG_SPLIT_NO_EMPTY) ?: [];
        };
        $periodForDate = static function (string $date) use ($periods): ?string {
            foreach ($periods as $period) {
                if ($date >= $period['from'] && $date <= $period['to']) return (string) $period['key'];
            }
            return null;
        };

        foreach ($orderRows as $row) {
            $pid = (int) $row->product_id;
            if (!$products->has($pid)) continue;
            $date = (string) (($row->order_date ?? '') ?: ($row->sales_order_date ?? ''));
            $periodKey = $periodForDate($date);
            if ($periodKey === null) continue;

            $isOnline = str_starts_with(strtoupper(trim((string) $row->order_number)), 'ONL-')
                || isset($onlineNoteIds[(int) ($row->sales_note_id ?? 0)]);
            $type = $isOnline ? 'online' : 'local';
            if ($channel !== 'both' && $channel !== $type) continue;

            $qty = (float) ($row->actual_qty ?? 0) + (float) ($row->additional_qty ?? 0);
            if ($qty <= 0) $qty = (float) ($row->quantity ?? 0);
            $amount = (float) ($row->subtotal ?? 0);

            $stats[$pid][$periodKey][$type]['qty'] = ($stats[$pid][$periodKey][$type]['qty'] ?? 0) + $qty;
            $stats[$pid][$periodKey][$type]['amount'] = ($stats[$pid][$periodKey][$type]['amount'] ?? 0) + $amount;

            foreach ($normalizeInvoices($row->invoice_numbers ?? null) as $invoice) {
                $invoiceKey = mb_strtolower(trim((string) $invoice));
                if ($invoiceKey === '') continue;
                $invoiceMeta[$invoiceKey] = [
                    'type' => $type,
                    'customer_id' => (int) ($row->customer_id ?? 0),
                    'customer_name' => (string) ($row->customer_name ?? ''),
                    'agent' => (string) ($row->salesman ?? ''),
                ];
            }
        }

        // Deduct valid completed Sales Returns by the return date, matching the
        // same net-sales behavior used by the Sales History/Online Print logic.
        $returns = DB::connection('sales')->table('sales_returns as sr')
            ->join('sales_return_items as sri', 'sri.sales_return_id', '=', 'sr.id')
            ->whereIn('sri.product_id', $productIds)
            ->whereBetween(DB::raw('DATE(COALESCE(sr.created_at, sri.created_at))'), [$rangeFrom, $rangeTo])
            ->whereRaw("UPPER(TRIM(COALESCE(sr.status, 'COMPLETED'))) NOT IN ('CANCELLED', 'VOID')")
            ->get(['sr.invoice_no', 'sr.customer_id', 'sr.customer_name', 'sri.product_id', 'sri.quantity', 'sri.return_amount', 'sri.subtotal', DB::raw('DATE(COALESCE(sr.created_at, sri.created_at)) as return_date')]);

        $onlineCustomerNames = ['LAZADA ONLINE BUYERS', 'SHOPEE ONLINE BUYERS', 'SHOPPE ONLINE', 'SHOPPEE ONLINE', 'TIKTOK SHOP', 'TIKTOK ONLINE BUYERS'];
        foreach ($returns as $row) {
            $pid = (int) $row->product_id;
            $periodKey = $periodForDate((string) $row->return_date);
            if ($periodKey === null) continue;
            $invoiceKey = mb_strtolower(trim((string) ($row->invoice_no ?? '')));
            $meta = $invoiceKey !== '' ? ($invoiceMeta[$invoiceKey] ?? null) : null;

            if ($customerId > 0) {
                $returnCustomerId = (int) ($row->customer_id ?? 0);
                if (($meta['customer_id'] ?? $returnCustomerId) !== $customerId) continue;
            } elseif (!$isAll($customer)) {
                $returnCustomerName = (string) ($meta['customer_name'] ?? $row->customer_name ?? '');
                if (stripos($returnCustomerName, $customer) === false) continue;
            }
            if (!$isAll($agent)) {
                if (!$meta || stripos((string) ($meta['agent'] ?? ''), $agent) === false) continue;
            }

            $type = $meta['type'] ?? (in_array(strtoupper(trim((string) ($row->customer_name ?? ''))), $onlineCustomerNames, true) ? 'online' : 'local');
            if ($channel !== 'both' && $channel !== $type) continue;

            $qty = (float) ($row->quantity ?? 0);
            $amount = (float) (($row->return_amount ?? 0) ?: ($row->subtotal ?? 0));
            $stats[$pid][$periodKey][$type]['qty'] = ($stats[$pid][$periodKey][$type]['qty'] ?? 0) - $qty;
            $stats[$pid][$periodKey][$type]['amount'] = ($stats[$pid][$periodKey][$type]['amount'] ?? 0) - $amount;
        }

        // For an unfiltered Annual report, use the exact read-only Sales History
        // classifier already used by Sales Order Online Print. This preserves its
        // validated Product Ledger rules (LOCAL/ONLINE classification, ignored
        // inventory movements, temporary-online de-duplication, and return handling).
        // Customer/Agent-specific reports stay on the filtered Sales Order path above
        // because the shared history service intentionally aggregates all customers.
        if ($dateType === 'annual' && $customerId <= 0 && $isAll($customer) && $isAll($agent)) {
            $onlinePrintRanges = collect($periods)
                ->map(fn ($period) => ['type' => 'annual', 'value' => (string) $period['key']])
                ->values()->all();
            $history = app(\App\Services\ProductLedgerSalesHistoryService::class)
                ->forOnlinePrint($productIds, $onlinePrintRanges);

            foreach ($productIds as $pid) {
                foreach ($periods as $period) {
                    $key = (string) $period['key'];
                    $year = (int) $key;
                    if ($channel !== 'online') {
                        $stats[$pid][$key]['local']['qty'] = (float) ($history[$pid . '-' . $year . '-local'] ?? 0);
                    }
                    if ($channel !== 'local') {
                        $stats[$pid][$key]['online']['qty'] = (float) ($history[$pid . '-' . $year . '-online'] ?? 0);
                    }
                }
            }
        }

        // Latest Purchase Order cost comes from ledger. Supplier names and PO
        // currency/date are resolved on their own MariaDB connections.
        $costRows = DB::connection('ledger')->table('supplier_ledger_items as sli')
            ->join('supplier_ledgers as sl', 'sl.id', '=', 'sli.supplier_ledger_id')
            ->whereIn('sli.product_id', $productIds)
            ->where('sl.module_type', 'Purchase Order')
            ->whereNotNull('sli.unit_price')
            ->orderByDesc('sl.date')->orderByDesc('sl.created_at')->orderByDesc('sl.id')->orderByDesc('sli.id')
            ->get([
                'sli.product_id', 'sli.unit_price', 'sl.supplier_id',
                'sl.date as ledger_date', 'sl.source_purchase_order_id',
            ])
            ->unique('product_id')
            ->keyBy('product_id');

        $costSupplierNames = DB::connection('masterlist')->table('suppliers')
            ->whereIn('id', $costRows->pluck('supplier_id')->map(fn ($id) => (int) $id)->filter()->unique()->values()->all())
            ->pluck('name', 'id');
        $costPurchaseOrders = DB::connection('purchase')->table('purchase_orders')
            ->whereIn('id', $costRows->pluck('source_purchase_order_id')->map(fn ($id) => (int) $id)->filter()->unique()->values()->all())
            ->get(['id', 'date', 'currency'])
            ->keyBy('id');

        $costRows = $costRows->map(function ($row) use ($costSupplierNames, $costPurchaseOrders) {
            $po = $costPurchaseOrders->get((int) ($row->source_purchase_order_id ?? 0));
            $row->supplier_name = (string) ($costSupplierNames->get((int) ($row->supplier_id ?? 0)) ?? '');
            $row->purchase_order_date = $po->date ?? null;
            $row->purchase_currency = $po->currency ?? null;
            return $row;
        });

        $shortSupplier = static function ($name): string {
            $name = trim(preg_replace('/\s+/', ' ', (string) $name));
            if ($name === '') return '--';
            if (mb_strlen($name) <= 18) return $name;
            $first = preg_split('/[\s,\(\/]+/', $name, 2)[0] ?? $name;
            return rtrim($first, '.,-') ?: mb_substr($name, 0, 18);
        };

        $result = [];
        foreach ($products as $pid => $product) {
            $pid = (int) $pid;
            $periodRows = [];
            $grandQty = 0.0;
            $grandAmount = 0.0;
            foreach ($periods as $period) {
                $key = (string) $period['key'];
                $localQty = max(0, (float) ($stats[$pid][$key]['local']['qty'] ?? 0));
                $onlineQty = max(0, (float) ($stats[$pid][$key]['online']['qty'] ?? 0));
                $localAmount = max(0, (float) ($stats[$pid][$key]['local']['amount'] ?? 0));
                $onlineAmount = max(0, (float) ($stats[$pid][$key]['online']['amount'] ?? 0));
                $totalQty = $localQty + $onlineQty;
                $amount = $localAmount + $onlineAmount;
                $grandQty += $totalQty;
                $grandAmount += $amount;
                $periodRows[] = [
                    'key' => $key, 'label' => (string) $period['label'],
                    'total' => round($totalQty, 4), 'local' => round($localQty, 4), 'online' => round($onlineQty, 4),
                    'amount' => round($amount, 2),
                ];
            }
            if ($grandQty <= 0 && $grandAmount <= 0) continue;
            $cost = $costRows->get($pid);
            $result[] = [
                'product_id' => $pid,
                'item_code' => (string) ($product->product_code ?? ''),
                'part_no' => (string) ($product->part_number ?? ''),
                'description' => (string) ($product->description ?? ''),
                'brand' => (string) ($product->category ?? ''),
                'unit' => trim((string) ($product->unit ?? '')),
                'on_hand' => (int) ($product->on_hand ?? 0),
                'cost' => round((float) ($cost->unit_price ?? 0), 2),
                'cost_date' => (string) (($cost->purchase_order_date ?? null) ?: ($cost->ledger_date ?? '')),
                'currency' => strtoupper(trim((string) ($cost->purchase_currency ?? ''))) ?: '--',
                'supplier' => $shortSupplier($cost->supplier_name ?? ''),
                'supplier_full' => trim((string) ($cost->supplier_name ?? '')),
                'local_price' => round((float) ($product->selling_price ?? 0), 2),
                'online_price' => round((float) ($product->price_online ?? 0), 2),
                'sales_amount' => round($grandAmount, 2),
                'total_sales' => round($grandQty, 4),
                'periods' => $periodRows,
            ];
        }

        usort($result, function ($a, $b) {
            $cmp = ($b['sales_amount'] <=> $a['sales_amount']);
            return $cmp !== 0 ? $cmp : strcmp($a['item_code'], $b['item_code']);
        });

        return response()->json([
            'success' => true,
            'date_type' => $dateType,
            'channel' => $channel,
            'periods' => $periods,
            'products' => array_values($result),
        ]);
    } catch (\Throwable $e) {
        Log::error('Top Products report error: ' . $e->getMessage(), ['trace' => $e->getTraceAsString()]);
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.top-products.data');

