Route::post('/admin/reports/sales-report/print-data', function (\Illuminate\Http\Request $request) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

    try {
        $dateType = (string) $request->input('date_type', 'monthly');
        $date = (string) $request->input('date', '');
        $dateFrom = (string) $request->input('date_from', '');
        $dateTo = (string) $request->input('date_to', '');

        $customer = trim((string) $request->input('customer', 'Select All'));
        $description = trim((string) $request->input('description', ''));
        $category = trim((string) $request->input('category', ''));
        $agent = trim((string) $request->input('agent', ''));

        $notesQuery = DB::connection('sales')
            ->table('sales_notes')
            ->where(function ($q) {
                $q->where('status', 'Partial')->orWhere('status', 'Open');
            });

        if ($agent !== '') {
            $notesQuery->where('salesman', 'like', '%' . $agent . '%');
        }

        if ($customer !== '' && strtoupper($customer) !== 'SELECT ALL') {
            $notesQuery->where('customer_name', 'like', '%' . $customer . '%');
        }

        $applyDate = function ($q) use ($dateType, $date, $dateFrom, $dateTo) {
            if ($dateType === 'monthly' && preg_match('/^\d{4}-\d{2}$/', $date)) {
                [$y, $m] = explode('-', $date);
                $q->whereYear('order_date', (int) $y)->whereMonth('order_date', (int) $m);
                return;
            }
            if ($dateType === 'annual' && preg_match('/^\d{4}$/', $date)) {
                $q->whereYear('order_date', (int) $date);
                return;
            }
            if ($dateType === 'as-of' && preg_match('/^\d{4}-\d{2}-\d{2}$/', $date)) {
                $q->whereDate('order_date', '<=', $date);
                return;
            }
            if ($dateType === 'from-to' && preg_match('/^\d{4}-\d{2}-\d{2}$/', $dateFrom) && preg_match('/^\d{4}-\d{2}-\d{2}$/', $dateTo)) {
                $q->whereDate('order_date', '>=', $dateFrom)->whereDate('order_date', '<=', $dateTo);
                return;
            }
        };

        $applyDate($notesQuery);

        $notes = $notesQuery
            ->orderBy('order_date', 'asc')
            ->orderBy('sales_number', 'asc')
            ->get(['id', 'sales_number', 'customer_id', 'customer_name', 'order_date']);

        $noteIds = $notes->pluck('id')->values()->all();
        if (empty($noteIds)) {
            return response()->json(['success' => true, 'notes' => []]);
        }

        $productIds = [];
        $useTextDescriptionMatch = false;
        if ($description !== '' || $category !== '') {
            $productQuery = DB::connection('masterlist')->table('products')->select('id');
            if ($description !== '') {
                $productQuery->where('description', 'like', '%' . $description . '%');
            }
            if ($category !== '') {
                $productQuery->where('category', 'like', '%' . $category . '%');
            }
            $productIds = $productQuery->limit(5000)->pluck('id')->values()->all();

            if ($category !== '' && empty($productIds)) {
                return response()->json(['success' => true, 'notes' => []]);
            }
            if ($description !== '' && empty($productIds)) {
                $useTextDescriptionMatch = true;
            }
        }

        $itemsQuery = DB::connection('sales')
            ->table('sales_note_items')
            ->whereIn('sales_note_id', $noteIds);

        if (!empty($productIds)) {
            $itemsQuery->whereIn('product_id', $productIds);
        } elseif ($useTextDescriptionMatch && $description !== '') {
            $itemsQuery->where('description', 'like', '%' . $description . '%');
        }

        $noteItems = $itemsQuery->get([
            'sales_note_id',
            'product_id',
            'product_code',
            'description',
            'quantity',
            'oum',
            'unit_price',
            'discount',
        ]);

        if ($noteItems->isEmpty()) {
            return response()->json(['success' => true, 'notes' => []]);
        }

        $servedRows = DB::connection('sales')
            ->table('sales_orders as so')
            ->join('sales_order_items as soi', 'soi.sales_order_id', '=', 'so.id')
            ->whereIn('so.sales_note_id', $noteIds)
            ->select([
                'so.sales_note_id as sales_note_id',
                'soi.product_id as product_id',
                DB::raw('SUM(COALESCE(soi.actual_qty, 0)) as served_qty'),
            ])
            ->groupBy('so.sales_note_id', 'soi.product_id')
            ->get();

        $servedMap = [];
        foreach ($servedRows as $row) {
            $snId = (int) $row->sales_note_id;
            $pId = (int) $row->product_id;
            if (!isset($servedMap[$snId])) $servedMap[$snId] = [];
            $servedMap[$snId][$pId] = (float) ($row->served_qty ?? 0);
        }

        $productIdList = $noteItems->pluck('product_id')->filter()->unique()->values()->all();
        $products = DB::connection('masterlist')
            ->table('products')
            ->whereIn('id', $productIdList)
            ->get(['id', 'application', 'Position'])
            ->keyBy('id');

        $onHandMap = [];
        if (!empty($productIdList)) {
            $latestCreatedAtQuery = DB::connection('ledger')
                ->table('product_ledgers as pl')
                ->selectRaw('pl.product_id, MAX(pl.created_at) as max_created_at')
                ->whereIn('pl.product_id', $productIdList)
                ->groupBy('pl.product_id');

            $latestIdsQuery = DB::connection('ledger')
                ->table('product_ledgers as pl')
                ->joinSub($latestCreatedAtQuery, 'lc', function ($join) {
                    $join->on('pl.product_id', '=', 'lc.product_id')
                        ->on('pl.created_at', '=', 'lc.max_created_at');
                })
                ->selectRaw('MAX(pl.id) as id')
                ->groupBy('pl.product_id');

            $latestRows = DB::connection('ledger')
                ->table('product_ledgers')
                ->whereIn('id', $latestIdsQuery)
                ->get(['product_id', 'balance_stock']);

            foreach ($latestRows as $r) {
                $onHandMap[(int) $r->product_id] = (float) ($r->balance_stock ?? 0);
            }
        }

        $customerIds = $notes->pluck('customer_id')->filter()->unique()->values()->all();
        $customerMap = DB::connection('masterlist')->table('customers')->whereIn('id', $customerIds)->get(['id', 'address'])->keyBy('id');
        $supplierMap = DB::connection('masterlist')->table('suppliers')->whereIn('id', $customerIds)->get(['id', 'address'])->keyBy('id');

        $itemsByNote = [];
        foreach ($noteItems as $item) {
            $snId = (int) $item->sales_note_id;
            $pId = (int) $item->product_id;
            $qty = (float) ($item->quantity ?? 0);
            $served = (float) ($servedMap[$snId][$pId] ?? 0);
            $remaining = $qty - $served;
            if ($remaining <= 0) continue;

            $discount = (float) ($item->discount ?? 0);
            $unitPrice = (float) ($item->unit_price ?? 0);
            $subtotal = $remaining * $unitPrice * (1 - ($discount / 100));

            $prod = $products->get($pId);
            $descParts = array_filter([(string) ($item->description ?? ''), $prod->application ?? '', $prod->Position ?? '']);

            if (!isset($itemsByNote[$snId])) $itemsByNote[$snId] = [];
            $itemsByNote[$snId][] = [
                'product_id' => $pId,
                'unserved_qty' => $remaining,
                'on_hand' => (float) ($onHandMap[$pId] ?? 0),
                'unit' => (string) ($item->oum ?? ''),
                'item_code' => (string) ($item->product_code ?? ''),
                'description' => implode(' | ', $descParts),
                'unit_price' => $unitPrice,
                'subtotal' => round($subtotal, 2),
            ];
        }

        $result = [];
        foreach ($notes as $note) {
            $snId = (int) $note->id;
            $items = $itemsByNote[$snId] ?? [];
            if (empty($items)) continue;

            usort($items, fn ($a, $b) => strcmp($a['item_code'], $b['item_code']));

            $cid = (int) ($note->customer_id ?? 0);
            $address = '';
            if ($cid) {
                $address = (string) (($customerMap->get($cid)->address ?? '') ?: ($supplierMap->get($cid)->address ?? ''));
            }

            $result[] = [
                'sales_number' => (string) ($note->sales_number ?? ''),
                'customer_name' => (string) ($note->customer_name ?? ''),
                'address' => $address !== '' ? $address : '--',
                'date' => (string) ($note->order_date ?? ''),
                'items' => $items,
            ];
        }

        return response()->json(['success' => true, 'notes' => $result]);
    } catch (\Exception $e) {
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.sales-report.print-data');

Route::post('/admin/reports/sales-report/print-soa', function (\Illuminate\Http\Request $request) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

    try {
        $dateType = (string) $request->input('date_type', 'monthly');
        $date = (string) $request->input('date', '');
        $dateFrom = (string) $request->input('date_from', '');
        $dateTo = (string) $request->input('date_to', '');
        $customer = trim((string) $request->input('customer', ''));
        if ($customer === '' || strtolower($customer) === 'all' || strtolower($customer) === 'select all') {
            $customer = null;
        }
        $agent = trim((string) $request->input('agent', ''));

        // ---- Date filter helper ----
        $applyDateFilter = function ($q, $col = 'order_date') use ($dateType, $date, $dateFrom, $dateTo) {
            if ($dateType === 'monthly' && preg_match('/^\d{4}-\d{2}$/', $date)) {
                [$y, $m] = explode('-', $date);
                $q->whereYear($col, (int) $y)->whereMonth($col, (int) $m);
            } elseif ($dateType === 'annual' && preg_match('/^\d{4}$/', $date)) {
                $q->whereYear($col, (int) $date);
            } elseif ($dateType === 'as-of' && preg_match('/^\d{4}-\d{2}-\d{2}$/', $date)) {
                $q->whereDate($col, '<=', $date);
            } elseif ($dateType === 'from-to' && preg_match('/^\d{4}-\d{2}-\d{2}$/', $dateFrom) && preg_match('/^\d{4}-\d{2}-\d{2}$/', $dateTo)) {
                $q->whereDate($col, '>=', $dateFrom)->whereDate($col, '<=', $dateTo);
            }
        };

        // ---- Date range label ----
        $dateRangeLabel = '';
        if ($dateType === 'monthly' && $date) {
            $d = \Carbon\Carbon::parse($date . '-01');
            $dateRangeLabel = $d->format('d-M-y') . ' To ' . $d->copy()->endOfMonth()->format('d-M-y');
        } elseif ($dateType === 'annual' && $date) {
            $y2 = substr($date, -2);
            $dateRangeLabel = '01-Jan-' . $y2 . ' To 31-Dec-' . $y2;
        } elseif ($dateType === 'as-of' && $date) {
            $dateRangeLabel = 'Up To ' . \Carbon\Carbon::parse($date)->format('d-M-y');
        } elseif ($dateType === 'from-to' && $dateFrom && $dateTo) {
            $dateRangeLabel = \Carbon\Carbon::parse($dateFrom)->format('d-M-y') . ' To ' . \Carbon\Carbon::parse($dateTo)->format('d-M-y');
        }

        // ---- Fetch customers ----
        $customerQuery = DB::connection('masterlist')->table('customers');
        if ($customer !== null) {
            $customerQuery->where('name', 'like', '%' . $customer . '%');
        }
        $customers = $customerQuery->orderBy('name')->get(['id', 'name', 'address', 'terms']);
        if ($customers->isEmpty()) {
            return response()->json(['success' => false, 'message' => 'No customers found.'], 422);
        }
        $customerIds = $customers->pluck('id')->toArray();

        // ---- Invoice-level date matcher for rows that are assembled in PHP (online invoices) ----
        $matchesDateFilter = function ($value) use ($dateType, $date, $dateFrom, $dateTo) {
            if (empty($value)) return false;

            try {
                $invoiceDate = \Carbon\Carbon::parse($value);
            } catch (\Throwable $e) {
                return false;
            }

            if ($dateType === 'monthly' && preg_match('/^\d{4}-\d{2}$/', $date)) {
                [$year, $month] = explode('-', $date);
                return $invoiceDate->year === (int) $year && $invoiceDate->month === (int) $month;
            }

            if ($dateType === 'annual' && preg_match('/^\d{4}$/', $date)) {
                return $invoiceDate->year === (int) $date;
            }

            if ($dateType === 'as-of' && preg_match('/^\d{4}-\d{2}-\d{2}$/', $date)) {
                return $invoiceDate->copy()->startOfDay()->lte(\Carbon\Carbon::parse($date)->endOfDay());
            }

            if ($dateType === 'from-to'
                && preg_match('/^\d{4}-\d{2}-\d{2}$/', $dateFrom)
                && preg_match('/^\d{4}-\d{2}-\d{2}$/', $dateTo)) {
                return $invoiceDate->copy()->startOfDay()->betweenIncluded(
                    \Carbon\Carbon::parse($dateFrom)->startOfDay(),
                    \Carbon\Carbon::parse($dateTo)->endOfDay()
                );
            }

            return true;
        };

        $normalizeInvKey = static fn ($value) => strtoupper(preg_replace('/\s+/', '', trim((string) $value)));

        // ---- Fetch LOCAL invoices one sales_orders row at a time ----
        // sales_orders.created_at is the invoice-generation date. Do not filter by the parent Sales Note date.
        $invoiceDateSql = 'COALESCE(so.created_at, sn.order_date)';
        $soQuery = DB::connection('sales')->table('sales_orders as so')
            ->leftJoin('sales_notes as sn', 'sn.id', '=', 'so.sales_note_id')
            ->whereIn('so.customer_id', $customerIds)
            ->where('so.order_number', 'NOT LIKE', 'ONL-%')
            ->where(function ($q) {
                $q->whereIn('so.status', ['Closed', 'Confirmed'])
                    ->orWhere('sn.status', 'Closed');
            })
            ->whereNotNull('so.total_amount')
            ->where('so.total_amount', '>', 0);

        if ($agent !== '' && strtoupper($agent) !== 'SELECT ALL') {
            $soQuery->where('sn.salesman', 'like', '%' . $agent . '%');
        }

        if ($dateType === 'monthly' && preg_match('/^\d{4}-\d{2}$/', $date)) {
            [$y, $m] = explode('-', $date);
            $soQuery->whereRaw("YEAR({$invoiceDateSql}) = ? AND MONTH({$invoiceDateSql}) = ?", [(int) $y, (int) $m]);
        } elseif ($dateType === 'annual' && preg_match('/^\d{4}$/', $date)) {
            $soQuery->whereRaw("YEAR({$invoiceDateSql}) = ?", [(int) $date]);
        } elseif ($dateType === 'as-of' && preg_match('/^\d{4}-\d{2}-\d{2}$/', $date)) {
            $soQuery->whereRaw("DATE({$invoiceDateSql}) <= ?", [$date]);
        } elseif ($dateType === 'from-to'
            && preg_match('/^\d{4}-\d{2}-\d{2}$/', $dateFrom)
            && preg_match('/^\d{4}-\d{2}-\d{2}$/', $dateTo)) {
            $soQuery->whereRaw("DATE({$invoiceDateSql}) BETWEEN ? AND ?", [$dateFrom, $dateTo]);
        }

        $localInvoices = $soQuery->select(
                DB::raw("'sales_order' as source_type"),
                'so.id as source_id',
                'so.customer_id',
                'so.customer_name',
                'so.order_number as po_no',
                DB::raw("COALESCE(NULLIF(so.invoice_numbers, ''), so.order_number) as invoice_no"),
                'so.total_amount as amount',
                'sn.sales_number as sales_note_no',
                'sn.net_total as sales_note_amount',
                DB::raw("{$invoiceDateSql} as invoice_date"),
                DB::raw("'' as row_remarks")
            )
            ->orderBy('so.customer_id')
            ->orderByRaw($invoiceDateSql)
            ->orderBy('so.id')
            ->get();

        $customerIdsLookup = array_fill_keys(array_map('intval', $customerIds), true);
        $customerIdByName = [];
        foreach ($customers as $cust) {
            $nameKey = mb_strtoupper(trim((string) $cust->name));
            if ($nameKey !== '') $customerIdByName[$nameKey] = (int) $cust->id;
        }

        // ---- Fetch ONLINE invoices individually ----
        // One Online Report can hold multiple exact invoice numbers, so use the same
        // source_type + report_id + invoice_no identity used by Accounting > Payments.
       $rawOnlineInvoices = collect(hatdogBuildOnlineInvoices())
    ->filter(function ($doc) use ($customerIdsLookup, $customerIdByName) {


        $customerId = (int) ($doc->customer_id ?? 0);

        if ($customerId <= 0) {
            $nameKey = mb_strtoupper(
                trim((string) ($doc->customer_name ?? ''))
            );

            $customerId = (int) (
                $customerIdByName[$nameKey] ?? 0
            );
        }

        return $customerId > 0
            && isset($customerIdsLookup[$customerId]);
    })
    ->values();

$onlineReportIds = $rawOnlineInvoices
    ->pluck('source_id')
    ->map(fn ($id) => (int) $id)
    ->filter()
    ->unique()
    ->values()
    ->all();

$onlineReportMap = collect();

foreach (array_chunk($onlineReportIds, 1000) as $reportIdChunk) {

    $chunkRows = DB::connection('sales')
        ->table('online_reports')
        ->whereIn('id', $reportIdChunk)
        ->get([
            'id',
            'addresses',
            'notes_data',
            'created_at',
            'updated_at'
        ]);

    // Keep the REAL online_reports.id as the collection key.
    // Collection::merge() re-indexes numeric keys and can attach
    // the wrong Online Report / Address to an invoice.
    foreach ($chunkRows as $row) {
        $onlineReportMap->put(
            (int) $row->id,
            $row
        );
    }
}
        $onlineReportIdLookup = array_fill_keys($onlineReportIds, true);

        // Match each generated online invoice back to its exact ONL sales_order so
        // the report date is the date that particular invoice was generated.
        $onlineOrderMap = [];
        if (!empty($onlineReportIds)) {
            $onlineOrders = DB::connection('sales')->table('sales_orders as so')
                ->leftJoin('sales_notes as sn', 'sn.id', '=', 'so.sales_note_id')
                ->where('so.order_number', 'LIKE', 'ONL-%')
                ->whereIn('so.status', ['Confirmed', 'Closed'])
                ->get([
                    'so.id',
                    'so.order_number',
                    'so.invoice_numbers',
                    'so.created_at',
                    'so.customer_id',
                    'so.customer_name',
                    'sn.salesman',
                ]);

            foreach ($onlineOrders as $order) {
                if (!preg_match('/^ONL-(\d+)-/', (string) $order->order_number, $matches)) continue;
                $reportId = (int) $matches[1];
                if (!isset($onlineReportIdLookup[$reportId])) continue;

                $invoiceValues = json_decode((string) ($order->invoice_numbers ?? ''), true);
                if (!is_array($invoiceValues)) {
                    $invoiceValues = array_map('trim', explode(',', (string) ($order->invoice_numbers ?? '')));
                }

                foreach ($invoiceValues as $invoiceValue) {
                    $invoiceKey = $normalizeInvKey($invoiceValue);
                    if ($invoiceKey !== '') {
                        $onlineOrderMap[$reportId . ':' . $invoiceKey] = $order;
                    }
                }
            }
        }

        $onlineInvoices = collect();
        foreach ($rawOnlineInvoices as $doc) {
            $reportId = (int) ($doc->source_id ?? 0);
            $invoiceNo = trim((string) ($doc->invoice_no ?? ''));
            if ($reportId <= 0 || $invoiceNo === '') continue;

            $invoiceKey = $normalizeInvKey($invoiceNo);
            $order = $onlineOrderMap[$reportId . ':' . $invoiceKey] ?? null;

            $customerId = (int) ($doc->customer_id ?? 0);
            if ($customerId <= 0) {
                $nameKey = mb_strtoupper(trim((string) ($doc->customer_name ?? '')));
                $customerId = (int) ($customerIdByName[$nameKey] ?? 0);
            }
            if ($customerId <= 0 || !isset($customerIdsLookup[$customerId])) continue;

            // Preserve the Salesman filter for generated online invoices.
            if ($agent !== '' && strtoupper($agent) !== 'SELECT ALL') {
                $salesman = trim((string) ($order->salesman ?? ''));
                if ($salesman === '' || stripos($salesman, $agent) === false) continue;
            }

            $report = $onlineReportMap->get($reportId);
            $invoiceIndex = (int) ($doc->invoice_index ?? 0);

            // Generated online invoices use their exact ONL sales_order creation date.
            // Migrated reports fall back to the original note order_date stored in notes_data,
            // not the migration timestamp of online_reports.created_at.
            $notesData = $report ? json_decode((string) ($report->notes_data ?? '[]'), true) : [];
            if (!is_array($notesData)) $notesData = [];
            $noteData = $notesData[(string) $invoiceIndex] ?? $notesData[$invoiceIndex] ?? null;
            $historicalInvoiceDate = is_array($noteData) ? ($noteData['order_date'] ?? null) : null;
            $invoiceDate = $order->created_at ?? ($historicalInvoiceDate ?: ($doc->created_at ?? ($report->created_at ?? null)));
            if (!$matchesDateFilter($invoiceDate)) continue;

            $addresses = $report ? json_decode((string) ($report->addresses ?? '[]'), true) : [];
            if (!is_array($addresses)) $addresses = [];
            $address = trim((string) ($addresses[(string) $invoiceIndex] ?? $addresses[$invoiceIndex] ?? ''));

            $onlineInvoices->push((object) [
                'source_type' => 'online_report',
                'source_id' => $reportId,
                'customer_id' => $customerId,
                'customer_name' => (string) ($doc->customer_name ?? ($order->customer_name ?? '')),
                'po_no' => $invoiceNo,
                'invoice_no' => $invoiceNo,
                'amount' => (float) ($doc->amount ?? 0),
                'sales_note_no' => null,
                'sales_note_amount' => null,
                'invoice_date' => $invoiceDate,
                'row_remarks' => $address,
            ]);
        }

        $invoiceDocuments = $localInvoices->concat($onlineInvoices)->values();
        if ($invoiceDocuments->isEmpty()) {
            return response()->json(['success' => false, 'message' => 'No invoices found for the selected criteria.'], 422);
        }

        // ---- Payments / adjustments: use the same invoice identity as Accounting > Payments ----
        $localSourceIds = $invoiceDocuments
            ->where('source_type', 'sales_order')
            ->pluck('source_id')
            ->map(fn ($id) => (int) $id)
            ->filter()
            ->unique()
            ->values()
            ->all();
        $onlineSourceIds = $invoiceDocuments
            ->where('source_type', 'online_report')
            ->pluck('source_id')
            ->map(fn ($id) => (int) $id)
            ->filter()
            ->unique()
            ->values()
            ->all();

        $settlementRows = collect();
        foreach (array_chunk($localSourceIds, 1000) as $sourceIdChunk) {
            $settlementRows = $settlementRows->concat(
                DB::connection('accounting')->table('process_payment_invoices')
                    ->where('source_type', 'sales_order')
                    ->whereIn('source_id', $sourceIdChunk)
                    ->get(['source_type', 'source_id', 'invoice_no', 'paid_amount', 'adjustment'])
            );
        }
        foreach (array_chunk($onlineSourceIds, 1000) as $sourceIdChunk) {
            $settlementRows = $settlementRows->concat(
                DB::connection('accounting')->table('process_payment_invoices')
                    ->where('source_type', 'online_report')
                    ->whereIn('source_id', $sourceIdChunk)
                    ->get(['source_type', 'source_id', 'invoice_no', 'paid_amount', 'adjustment'])
            );
        }
        $settlementMap = [];
        foreach ($settlementRows as $row) {
            $sourceType = (string) ($row->source_type ?? '');
            $sourceId = (int) ($row->source_id ?? 0);
            if ($sourceType === '' || $sourceId <= 0) continue;

            $key = $sourceType === 'online_report'
                ? $sourceType . ':' . $sourceId . ':' . $normalizeInvKey($row->invoice_no ?? '')
                : $sourceType . ':' . $sourceId;

            if (!isset($settlementMap[$key])) {
                $settlementMap[$key] = ['paid' => 0.0, 'adjustment' => 0.0];
            }
            $settlementMap[$key]['paid'] += (float) ($row->paid_amount ?? 0);
            $settlementMap[$key]['adjustment'] += (float) ($row->adjustment ?? 0);
        }

        // ---- Sales returns: same invoice-normalization and item-return amount used by Payments ----
        $rawReturnRows = DB::connection('sales')->table('sales_returns as sr')
            ->join('sales_return_items as sri', 'sri.sales_return_id', '=', 'sr.id')
            ->whereIn('sr.customer_id', $customerIds)
            ->whereNotNull('sr.invoice_no')
            ->whereRaw("UPPER(TRIM(COALESCE(sr.status, ''))) NOT IN ('CANCELLED', 'VOID')")
            ->select(
                'sr.invoice_no',
                DB::raw('SUM(COALESCE(sri.return_amount, sri.subtotal, 0)) as return_total')
            )
            ->groupBy('sr.invoice_no')
            ->get();

        $returnMap = [];
        foreach ($rawReturnRows as $row) {
            $rawInvoice = trim((string) ($row->invoice_no ?? ''));
            $returnTotal = (float) ($row->return_total ?? 0);
            if ($rawInvoice === '' || $returnTotal <= 0) continue;

            $keys = [$normalizeInvKey($rawInvoice)];
            foreach (preg_split('/[,\s\/]+/', $rawInvoice) as $token) {
                $token = trim((string) $token);
                if ($token !== '') $keys[] = $normalizeInvKey($token);
            }
            if (preg_match_all('/SN-\d+/i', $rawInvoice, $matches) && !empty($matches[0])) {
                foreach ($matches[0] as $salesNoteNo) {
                    $keys[] = $normalizeInvKey($salesNoteNo);
                }
            }

            foreach (array_values(array_unique(array_filter($keys))) as $key) {
                $returnMap[$key] = (float) ($returnMap[$key] ?? 0) + $returnTotal;
            }
        }

        // ---- Build one SOA row per exact invoice ----
        $customerSections = [];
        foreach ($customers as $cust) {
            $customerId = (int) $cust->id;
            $customerInvoices = $invoiceDocuments
                ->filter(fn ($doc) => (int) ($doc->customer_id ?? 0) === $customerId)
                ->values();
            if ($customerInvoices->isEmpty()) continue;

            $transactions = [];
            $customerTotalBalance = 0.0;

            foreach ($customerInvoices as $doc) {
                $sourceType = (string) ($doc->source_type ?? 'sales_order');
                $sourceId = (int) ($doc->source_id ?? 0);
                $invoiceNo = trim((string) ($doc->invoice_no ?? ''));
                $amount = round((float) ($doc->amount ?? 0), 2);
                if ($sourceId <= 0 || $invoiceNo === '' || $amount < 0) continue;

                $settlementKey = $sourceType === 'online_report'
                    ? $sourceType . ':' . $sourceId . ':' . $normalizeInvKey($invoiceNo)
                    : $sourceType . ':' . $sourceId;
                $settlement = $settlementMap[$settlementKey] ?? ['paid' => 0.0, 'adjustment' => 0.0];
                $paid = (float) ($settlement['paid'] ?? 0);
                $recordedAdjustment = (float) ($settlement['adjustment'] ?? 0);

                $invoiceKeys = collect(explode(',', $invoiceNo))
                    ->map(fn ($value) => $normalizeInvKey($value))
                    ->filter(fn ($value) => $value !== '')
                    ->merge([$normalizeInvKey($doc->po_no ?? '')])
                    ->merge([$normalizeInvKey($doc->sales_note_no ?? '')])
                    ->filter(fn ($value) => $value !== '')
                    ->unique()
                    ->values();

                $returned = (float) $invoiceKeys->sum(fn ($key) => (float) ($returnMap[$key] ?? 0));
                $salesNoteAmount = (float) ($doc->sales_note_amount ?? 0);

                // Keep the exact settlement principle used by Accounting > Payments.
                $effectiveAdjustment = max($returned, $recordedAdjustment);
                $autoSettledByReturn = $returned > 0 && (
                    $returned >= $amount
                    || ($salesNoteAmount > 0 && $returned >= $salesNoteAmount)
                    || $paid >= ($amount / 2)
                );
                $balance = $autoSettledByReturn
    ? 0.0
    : max($amount - $paid - $effectiveAdjustment, 0.0);

$balance = round($balance, 2);

// Hide fully paid positive-value invoices,
// but keep real finalized zero-value invoices visible.
if ($amount > 0 && $balance <= 0.005) {
    continue;
}

// Credit is whatever has already settled this exact invoice.
$credit = round(max($amount - $balance, 0.0), 2);
$customerTotalBalance += $balance;
                $invoiceDate = $doc->invoice_date ?? null;
                $dateStr = $invoiceDate ? \Carbon\Carbon::parse($invoiceDate)->format('Y-m-d') : '';

                $transactions[] = [
                    'date' => $dateStr,
                    'invoice_no' => $invoiceNo,
                    'debits' => $amount,
                    'credits' => $credit,
                    'balance' => $balance,
                    // Remarks are the Online Report Address only. Do not print Sales Note,
                    // Product Ledger, Payment, Return, or "Invoice: ..." remarks here.
                    'remarks' => trim((string) ($doc->row_remarks ?? '')),
                    'sort_key' => $dateStr . '|' . $invoiceNo . '|' . $sourceType . '|' . $sourceId,
                ];
            }

            if (empty($transactions)) continue;

            usort($transactions, fn ($a, $b) => strcmp($a['sort_key'], $b['sort_key']));
            foreach ($transactions as &$transaction) {
                unset($transaction['sort_key']);
            }
            unset($transaction);

            $customerSections[] = [
                'customer' => $cust,
                'transactions' => $transactions,
                'total_balance' => round($customerTotalBalance, 2),
            ];
        }

        if (empty($customerSections)) {
            return response()->json(['success' => false, 'message' => 'No data to display.'], 422);
        }

        // ---- Build paginated pages (max ~35 rows per A4 page) ----
        $ROWS_PER_PAGE = 35;
        $pages = [];

        foreach ($customerSections as $section) {
            $cust = $section['customer'];
            $txns = $section['transactions'];
            $totalBalance = $section['total_balance'];

            $chunks = array_chunk($txns, $ROWS_PER_PAGE);
            $chunkCount = count($chunks);

            foreach ($chunks as $chunkIndex => $chunk) {
                $pages[] = [
                    'customer' => [
                        'id' => $cust->id,
                        'name' => $cust->name,
                        'address' => $cust->address ?? '',
                        'terms' => $cust->terms ?? '',
                    ],
                    'rows' => $chunk,
                    'show_customer_box' => ($chunkIndex === 0),
                    'show_payment_summary' => ($chunkIndex === $chunkCount - 1),
                    'total_balance' => ($chunkIndex === $chunkCount - 1) ? $totalBalance : 0,
                ];
            }
        }

        // Assign page numbers
        $totalPageCount = count($pages);
        foreach ($pages as $idx => &$page) {
            $page['page_number'] = $idx + 1;
            $page['total_pages'] = $totalPageCount;
        }
        unset($page);

        // ---- User info for footer ----
        $userId = '';
        $userLoginId = '';
        if (is_array($user)) {
            $userId = $user['User_ID'] ?? '';
            $userLoginId = $user['login_ID'] ?? '';
        } else {
            $userId = $user->User_ID ?? '';
            $userLoginId = $user->login_ID ?? '';
        }

        return view('Admin.Reports.prints.sales-report-print', [
            'pages' => $pages,
            'dateRangeLabel' => $dateRangeLabel,
            'timestamp' => \Carbon\Carbon::now()->format('m-d-Y h:i A'),
            'printedBy' => $userId ?: $userLoginId,
            'securityId' => \Illuminate\Support\Str::uuid()->toString(),
        ]);
    } catch (\Throwable $e) {
        Log::error('SOA print error: ' . $e->getMessage() . "\n" . $e->getTraceAsString());
        return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
    }
})->name('admin.sales-report.print-soa');

// Autocomplete and data retrieval endpoints for reports
Route::get('/api/products/search-descriptions', function (\Illuminate\Http\Request $request) {
    $query = $request->query('query', '');
    $browse = $request->query('browse', 0);
    // In browse mode allow empty query (show first 50 unique descriptions)
    // In search mode require at least 1 character
    if (!$browse && strlen($query) < 1) {
        return response()->json([]);
    }
    $dbQuery = \App\Models\Product::whereNotNull('description')->where('description', '!=', '');
    if (strlen($query) >= 1) {
        $dbQuery->where('description', 'like', '%' . $query . '%');
    }
    $descriptions = $dbQuery->distinct()->orderBy('description')->take(50)->pluck('description');
    return response()->json($descriptions);
})->name('api.products.search-descriptions');

Route::get('/api/products/search-categories', function (\Illuminate\Http\Request $request) {
    $query  = $request->query('query', '');
    $browse = $request->query('browse', 0);
    if (!$browse && strlen($query) < 1) {
        return response()->json([]);
    }
    $dbQuery = \App\Models\Product::whereNotNull('category')->where('category', '!=', '');
    if (strlen($query) >= 1) {
        $dbQuery->where('category', 'like', '%' . $query . '%');
    }
    $categories = $dbQuery->distinct()->orderBy('category')->take(50)->pluck('category');
    return response()->json($categories);
})->name('api.products.search-categories');

Route::get('/api/reports/inventory-data', function (\Illuminate\Http\Request $request) {
    $reportType  = $request->query('report_type', 'product_on_hand');
    $description = $request->query('description', '');
    $category    = $request->query('category', '');
    $yearFrom    = $request->query('year_from', '');   // e.g. "2024"
    $yearTo      = $request->query('year_to',   '');   // e.g. "2026"

    // ── Products ────────────────────────────────────────────────────────────
    $select = ['id','product_code','description','application','cost','selling_price','price_online','on_hand','actual_qty','category'];
    if (Schema::connection('masterlist')->hasColumn('products', 'Re_order_level')) {
        $select[] = 'Re_order_level';
    }

    $query = \App\Models\Product::query()->select($select);

    if ($description !== '') {
        $query->where('description', 'like', '%' . $description . '%');
    }
    if ($category !== '') {
        $query->where('category', 'like', '%' . $category . '%');
    }

    $products = $query->orderBy('description')->get();

    // Fetch latest balance_stock for each product from product_ledgers table in ledger database
    try {
        $latestLedgerMap = DB::connection('ledger')
            ->table('product_ledgers')
            ->whereIn('product_id', $products->pluck('id'))
            ->orderBy('date', 'desc')
            ->orderBy('id', 'desc')
            ->get()
            ->groupBy('product_id')
            ->map(function ($group) {
                return $group->first()->balance_stock;
            });
    } catch (\Throwable $e) {
        $latestLedgerMap = collect();
    }

    // Override on_hand with latest ledger balance_stock
    $products = $products->map(function ($p) use ($latestLedgerMap) {
        $p->on_hand = $latestLedgerMap->get($p->id) ?? ($p->on_hand ?? 0);
        return $p;
    });

    if ($reportType === 'reorder_report') {
        $products = $products->filter(function ($p) {
            $reorderLevel = (int) ($p->Re_order_level ?? 0);
            $onHand = (int) ($p->on_hand ?? 0);

            if ($reorderLevel <= 0) return false;
            return $onHand <= $reorderLevel;
        })->values();
    }

    // ── Yearly Sales from Ledger (OUT transactions) ─────────────────────────
    // Determine which years to show: default 2024-2026, expand based on user input
    $salesYears = [2024, 2025, 2026];
    if ($yearFrom !== '' || $yearTo !== '') {
        $fromYear = $yearFrom !== '' ? (int) $yearFrom : 2024;
        $toYear   = $yearTo   !== '' ? (int) $yearTo   : (int) date('Y');
        for ($y = $fromYear; $y <= $toYear; $y++) {
            if (!in_array($y, $salesYears)) $salesYears[] = $y;
        }
        sort($salesYears);
    }

    // Build ledger query — group by product_id and year
    try {
        $ledgerQuery = DB::connection('ledger')
            ->table('product_ledgers')
            ->where('transaction_type', 'OUT')
            ->whereIn('product_id', $products->pluck('id'));

        if ($yearFrom !== '') $ledgerQuery->whereRaw('YEAR(created_at) >= ?', [(int) $yearFrom]);
        if ($yearTo   !== '') $ledgerQuery->whereRaw('YEAR(created_at) <= ?', [(int) $yearTo]);

        $ledgerRows = $ledgerQuery
            ->selectRaw('product_id, YEAR(created_at) as yr, SUM(quantity_out) as total_out')
            ->groupBy('product_id', DB::raw('YEAR(created_at)'))
            ->get();

        // Index: [product_id][year] => qty
        $salesMap = [];
        foreach ($ledgerRows as $row) {
            $salesMap[$row->product_id][$row->yr] = (int) $row->total_out;
        }
    } catch (\Throwable $e) {
        $salesMap = [];
    }

    // Attach sales_by_year to each product
    $productsOut = $products->map(function ($p) use ($salesMap, $salesYears) {
        $byYear = [];
        foreach ($salesYears as $y) {
            $byYear[$y] = $salesMap[$p->id][$y] ?? 0;
        }
        return array_merge($p->toArray(), ['sales_by_year' => $byYear]);
    });

    return response()->json([
        'products'    => $productsOut,
        'sales_years' => $salesYears,
    ]);
})->name('api.reports.inventory-data');

// ─── Warehouse Profile ───────────────────────────────────────────────────────
Route::get('/warehouse/profile', function () {
    $user = session('user');
    if (!$user) return redirect('/login');
    if (is_array($user)) $user = (object) $user;
    if ((int) ($user->account_type ?? 0) !== 5) return redirect()->route('login');

    $profileUser = Login::where('login_ID', $user->login_ID ?? 0)
        ->orWhere('User_ID', $user->User_ID)
        ->first();

    if (!$profileUser) return redirect()->route('warehouse.dashboard');

    $accountTypeLabel = 'Warehouse User';
    $profilePictureUrl = null;
    $hasPp = Schema::hasColumn('logins', 'profile_picture');
    $hasPpMime = Schema::hasColumn('logins', 'profile_picture_mime');
    if ($hasPp && !empty($profileUser->profile_picture)) {
        $mime = $hasPpMime && !empty($profileUser->profile_picture_mime) ? $profileUser->profile_picture_mime : 'image/png';
        $profilePictureUrl = 'data:' . $mime . ';base64,' . base64_encode($profileUser->profile_picture);
    }

    $welcomeFullName = trim(collect([trim((string) ($profileUser->User_First_Name ?? '')), trim((string) ($profileUser->User_Middle_Name ?? '')), trim((string) ($profileUser->User_Last_Name ?? ''))])->filter()->implode(' '));
    if (empty($welcomeFullName)) $welcomeFullName = $profileUser->User_ID ?? 'Warehouse User';

    $sidebarAvatarUrl = $profilePictureUrl ?? '';
    $sidebarFullName = $welcomeFullName;
    $sidebarRoleLabel = $accountTypeLabel;

    $graphDays = collect(range(6, 0))
        ->map(fn ($daysAgo) => \Carbon\Carbon::today()->subDays($daysAgo))
        ->values();
    $dailyLoginMap = $graphDays->mapWithKeys(fn ($date) => [$date->toDateString() => 0]);
    $totalLoginCount = 0;
    $weeklyLoginCount = 0;
    $latestLoginAt = null;

    if (Schema::hasTable('login_activity_logs')) {
        $base = DB::table('login_activity_logs')->where('user_id', $profileUser->User_ID);
        $totalLoginCount = (clone $base)->count();
        $weeklyLoginCount = (clone $base)->where('logged_in_at', '>=', now()->startOfWeek())->count();
        $latestLoginAt = (clone $base)->max('logged_in_at');
        $dailyCounts = (clone $base)
            ->whereBetween('logged_in_at', [$graphDays->first()->copy()->startOfDay(), $graphDays->last()->copy()->endOfDay()])
            ->selectRaw('DATE(logged_in_at) as login_date, COUNT(*) as total')
            ->groupBy('login_date')
            ->pluck('total', 'login_date');
        foreach ($dailyCounts as $loginDate => $total) {
            if ($dailyLoginMap->has($loginDate)) $dailyLoginMap->put($loginDate, (int) $total);
        }
    }

    return view('partials.Warehouse_User.warehouse-profile', [
        'user' => $user,
        'account_type' => 5,
        'profileUser' => $profileUser,
        'accountTypeLabel' => $accountTypeLabel,
        'profilePictureUrl' => $profilePictureUrl,
        'loginGraphLabels' => $graphDays->map(fn ($d) => $d->format('M d'))->values(),
        'loginGraphData' => $dailyLoginMap->values(),
        'totalLoginCount' => $totalLoginCount,
        'weeklyLoginCount' => $weeklyLoginCount,
        'latestLoginAt' => $latestLoginAt ? \Carbon\Carbon::parse($latestLoginAt)->format('M d, Y h:i A') : 'No login activity yet',
        'sidebarAvatarUrl' => $sidebarAvatarUrl,
        'sidebarFullName' => $sidebarFullName,
        'sidebarRoleLabel' => $sidebarRoleLabel,
    ]);
})->name('warehouse.profile');

Route::post('/warehouse/profile/update', function (Request $request) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);
    if (is_array($user)) $user = (object) $user;
    if ((int) ($user->account_type ?? 0) !== 5) return response()->json(['error' => 'Unauthorized'], 403);

    $validated = $request->validate([
        'User_First_Name' => 'required|string|max:255',
        'User_Middle_Name' => 'nullable|string|max:255',
        'User_Last_Name' => 'required|string|max:255',
    ]);

    $profileUser = Login::where('login_ID', $user->login_ID ?? 0)
        ->orWhere('User_ID', $user->User_ID)
        ->first();
    if (!$profileUser) return response()->json(['error' => 'Profile not found.'], 404);

    $profileUser->User_First_Name = trim($validated['User_First_Name']);
    $profileUser->User_Middle_Name = trim((string) ($validated['User_Middle_Name'] ?? '')) ?: null;
    $profileUser->User_Last_Name = trim($validated['User_Last_Name']);
    $profileUser->save();

    $freshSessionUser = Login::select(hatdogLoginSessionColumns())
        ->where('login_ID', $profileUser->login_ID)->first();
