Route::post('/warehouse/profile/picture/update', function (Request $request) {
    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);
    if (is_array($user)) $user = (object) $user;
    if ((int) ($user->account_type ?? 0) !== 5) return response()->json(['error' => 'Unauthorized'], 403);

    $request->validate(['profile_picture' => 'required|image|mimes:jpeg,png,jpg,gif|max:2048']);
    $profileUser = Login::where('login_ID', $user->login_ID ?? 0)
        ->orWhere('User_ID', $user->User_ID)
        ->first();
    if (!$profileUser) return response()->json(['error' => 'Profile not found.'], 404);

    $file = $request->file('profile_picture');
    $profileUser->profile_picture = file_get_contents($file->getRealPath());
    if (Schema::hasColumn('logins', 'profile_picture_mime')) {
        $profileUser->profile_picture_mime = $file->getMimeType();
    }
    $profileUser->save();

    $freshSessionUser = Login::select(hatdogLoginSessionColumns())
        ->where('login_ID', $profileUser->login_ID)->first();
    if ($freshSessionUser) session(['user' => $freshSessionUser]);

    return response()->json(['success' => true, 'message' => 'Profile picture updated successfully.']);
})->name('warehouse.profile.picture.update');

