Route::get('/warehouse/inventory/item-convert/data', function (\Illuminate\Http\Request $request) {
    $user = session('user');
    if (!$user) return response()->json(['success' => false, 'error' => 'Unauthorized'], 403);
    if (is_array($user)) $user = (object) $user;
    if ((int) ($user->account_type ?? 0) !== 5) return response()->json(['success' => false, 'error' => 'Forbidden'], 403);

    $perPage = 50;
    $page = (int) $request->query('page', 1);
    $search = $request->query('search', []);

    $query = \App\Models\Product::select(['id', 'product_code', 'part_number', 'description', 'application', 'category']);

    if (!empty($search['code'])) {
        $query->where('product_code', 'LIKE', '%' . $search['code'] . '%');
    }
    if (!empty($search['part'])) {
        $query->where('part_number', 'LIKE', '%' . $search['part'] . '%');
    }
    if (!empty($search['app'])) {
        $query->where('application', 'LIKE', '%' . $search['app'] . '%');
    }
    if (!empty($search['desc'])) {
        $query->where('description', 'LIKE', '%' . $search['desc'] . '%');
    }
    if (!empty($search['pos'])) {
        $query->where('category', 'LIKE', '%' . $search['pos'] . '%');
    }

    $products = $query->orderBy('description')->paginate($perPage, ['*'], 'page', $page);

    try {
        $productIds = collect($products->items())->pluck('id');
        $latestLedgerMap = DB::connection('ledger')
            ->table('product_ledgers')
            ->whereIn('product_id', $productIds)
            ->orderBy('date', 'desc')
            ->orderBy('id', 'desc')
            ->get()
            ->groupBy('product_id')
            ->map(function ($group) {
                return (int) $group->first()->balance_stock;
            });
    } catch (\Throwable $e) {
        $latestLedgerMap = collect();
    }

    $items = collect($products->items())->map(function ($p) use ($latestLedgerMap) {
        $availableQty = $latestLedgerMap->get($p->id) ?? 0;
        return [
            'id' => $p->id,
            'product_code' => $p->product_code,
            'part_number' => $p->part_number,
            'description' => $p->description,
            'application' => $p->application,
            'position' => $p->category,
            'available_qty' => $availableQty,
            'target_code' => $p->product_code,
            'target_part' => $p->part_number,
            'target_app' => $p->application,
            'target_desc' => $p->description,
            'target_pos' => $p->category,
            'target_avail' => $availableQty,
        ];
    })->values();

    return response()->json([
        'success' => true,
        'items' => $items,
        'converted' => DB::connection('masterlist')->table('product_conversion_requests')
            ->where('requestor_id', $user->login_ID ?? 0)
            ->where('status', 'confirmed')
            ->orderBy('created_at', 'desc')
            ->get()
            ->map(function ($r) {
                return [
                    'product_code' => $r->source_product_code,
                    'part_number' => $r->source_part_number,
                    'description' => $r->source_description,
                    'application' => $r->source_application,
                    'position' => $r->source_position,
                    'converted_qty' => (int) $r->converted_qty,
                    'converted_at' => $r->created_at,
                ];
            })->values(),
        'rejected' => DB::connection('masterlist')->table('product_conversion_requests')
            ->where('requestor_id', $user->login_ID ?? 0)
            ->where('status', 'rejected')
            ->orderBy('created_at', 'desc')
            ->get()
            ->map(function ($r) {
                return [
                    'product_code' => $r->source_product_code,
                    'part_number' => $r->source_part_number,
                    'description' => $r->source_description,
                    'application' => $r->source_application,
                    'position' => $r->source_position,
                    'qty' => (int) $r->converted_qty,
                    'reason' => 'N/A',
                ];
            })->values(),
        'pagination' => [
            'current_page' => $products->currentPage(),
            'last_page' => $products->lastPage(),
            'per_page' => $products->perPage(),
            'total' => $products->total(),
        ],
        'stats' => [
            'converted' => DB::connection('masterlist')->table('product_conversion_requests')->where('requestor_id', $user->login_ID ?? 0)->where('status', 'confirmed')->count(),
            'rejected' => DB::connection('masterlist')->table('product_conversion_requests')->where('requestor_id', $user->login_ID ?? 0)->where('status', 'rejected')->count(),
            'total' => $products->total(),
        ],
    ]);
})->name('warehouse.item-convert.data');

Route::post('/warehouse/inventory/item-convert/save', function (\Illuminate\Http\Request $request) {
    $user = session('user');
    if (!$user) return response()->json(['success' => false, 'error' => 'Unauthorized'], 403);
    if (is_array($user)) $user = (object) $user;
    if ((int) ($user->account_type ?? 0) !== 5) return response()->json(['success' => false, 'error' => 'Forbidden'], 403);

    $data = $request->json()->all();
    $sourceProductId = $data['product_id'] ?? null;
    $targetProductId = $data['target_product_id'] ?? null;
    $quantity = (int) ($data['quantity'] ?? 0);

    if (!$sourceProductId || !$targetProductId || $quantity < 1) {
        return response()->json(['success' => false, 'error' => 'Invalid parameters.']);
    }

    $sourceProduct = \App\Models\Product::on('masterlist')->find($sourceProductId);
    $targetProduct = \App\Models\Product::on('masterlist')->find($targetProductId);

    if (!$sourceProduct || !$targetProduct) {
        return response()->json(['success' => false, 'error' => 'Product not found.']);
    }

    $profileUser = \App\Models\Login::where('login_ID', $user->login_ID ?? 0)->first();
    $requestorName = $profileUser ? trim(collect([$profileUser->User_First_Name ?? '', $profileUser->User_Middle_Name ?? '', $profileUser->User_Last_Name ?? ''])->filter()->implode(' ')) : ($user->User_ID ?? 'Warehouse User');
    if (empty($requestorName)) $requestorName = $user->User_ID ?? 'Warehouse User';

    try {
        DB::connection('ledger')->beginTransaction();
        DB::connection('masterlist')->beginTransaction();

        $sourcePrevBalance = (int) DB::connection('ledger')
            ->table('product_ledgers')
            ->where('product_id', $sourceProductId)
            ->orderBy('date', 'desc')
            ->orderBy('id', 'desc')
            ->value('balance_stock') ?? 0;

            $sourceNewBalance = max(0, $sourcePrevBalance - $quantity);

            \App\Models\ProductLedger::create([
                'product_id' => $sourceProductId,
                'transaction_type' => 'CONVERSION_DEDUCT',
                'transaction_number' => 'CNV-' . now()->format('YmdHis'),
                'quantity_out' => $quantity,
                'balance_stock' => $sourceNewBalance,
                'date' => now()->format('Y-m-d'),
            ]);

            $targetPrevBalance = (int) DB::connection('ledger')
                ->table('product_ledgers')
                ->where('product_id', $targetProductId)
                ->orderBy('date', 'desc')
                ->orderBy('id', 'desc')
                ->value('balance_stock') ?? 0;

            $targetNewBalance = $targetPrevBalance + $quantity;

            \App\Models\ProductLedger::create([
                'product_id' => $targetProductId,
                'transaction_type' => 'CONVERSION_ADD',
                'transaction_number' => 'CNV-' . now()->format('YmdHis'),
                'quantity_in' => $quantity,
                'balance_stock' => $targetNewBalance,
                'date' => now()->format('Y-m-d'),
            ]);

        $requestId = DB::connection('masterlist')->table('product_conversion_requests')->insertGetId([
            'requestor_id' => $user->login_ID ?? 0,
            'requestor_name' => $requestorName,
            'source_product_id' => $sourceProduct->id,
            'source_product_code' => $sourceProduct->product_code,
            'source_part_number' => $sourceProduct->part_number,
            'source_description' => $sourceProduct->description,
            'source_application' => $sourceProduct->application,
            'source_position' => $sourceProduct->category,
            'source_available_qty' => (int) $sourceProduct->on_hand,
            'target_product_id' => $targetProduct->id,
            'target_product_code' => $targetProduct->product_code,
            'target_part_number' => $targetProduct->part_number,
            'target_description' => $targetProduct->description,
            'target_application' => $targetProduct->application,
            'target_position' => $targetProduct->category,
            'target_available_qty' => (int) $targetProduct->on_hand,
            'converted_qty' => $quantity,
            'status' => 'pending',
            'created_at' => now(),
            'updated_at' => now(),
        ]);

        // Auto-accept if enabled
        $autoAccepted = false;
        if (Schema::connection('masterlist')->hasTable('auto_accept_config')) {
            $autoConfig = DB::connection('masterlist')->table('auto_accept_config')
                ->where('key', 'conversion_auto_accept')
                ->first();
            if ($autoConfig && $autoConfig->value) {
                $autoSettings = json_decode($autoConfig->value, true);
                if ($autoSettings && !empty($autoSettings['enabled']) && $autoSettings['enabled'] !== '0') {
                    DB::connection('masterlist')
                        ->table('product_conversion_requests')
                        ->where('id', $requestId)
                        ->update([
                            'status' => 'confirmed',
                            'reviewed_by' => 0,
                            'reviewed_at' => now(),
                            'updated_at' => now(),
                        ]);
                    $autoAccepted = true;
                }
            }
        }

        DB::connection('ledger')->commit();
        DB::connection('masterlist')->commit();

        $message = $autoAccepted ? 'Conversion request auto-approved.' : 'Conversion request submitted for review.';
        return response()->json(['success' => true, 'message' => $message, 'auto_accepted' => $autoAccepted]);
    } catch (\Throwable $e) {
        DB::connection('ledger')->rollBack();
        DB::connection('masterlist')->rollBack();
        return response()->json(['success' => false, 'error' => 'Conversion failed: ' . $e->getMessage()]);
    }
})->name('warehouse.item-convert.save');

