    $user = session('user');
    if (!$user) return response()->json(['error' => 'Unauthorized'], 403);

    $startDate = $request->input('start_date');
    $endDate = $request->input('end_date');
    $dateRangeLabel = $request->input('date_range_label', '');

    return hatdogGenerateSlowMovingExportResponse('/admin', $user, $startDate, $endDate, $dateRangeLabel);
})->name('admin.ai.slow-moving-products.generate');

